def solution(text, comment_markers):
    # Split text into individual lines
    lines = text.split('\n')

    processed_lines = []

    for line in lines:
        # Find all positions where comment markers appear in the line
        marker_positions = []
        for marker in comment_markers:
            pos = line.find(marker)
            if pos != -1:
                marker_positions.append(pos)

        # If any comment marker is found, truncate line at earliest marker position
        if marker_positions:
            earliest_marker_pos = min(marker_positions)
            line = line[:earliest_marker_pos]

