def is_balanced(s, pairs):
    # Create a mapping from opening to closing characters
    pair_map = {}
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        pair_map[opening] = closing

    # Stack to keep track of opening characters
    stack = []

    for char in s:
        # If character is an opening character
        if char in pair_map:
            stack.append(char)
        # If character is a closing character
        elif char in pair_map.values():
            # If stack is empty, we have a closing character without opening
            if not stack:
                return False

            # Pop the last opening character
            last_opening = stack.pop()

            # Check if the closing character matches the last opening character
            if pair_map[last_opening] != char:
                return False

    # String is balanced if stack is empty
    return len(stack) == 0

def greatest_common_divisor(a: int, b: int) -> int:
    # Handle edge cases
    if a == 0:
        return abs(b)
    if b == 0:
        return abs(a)

    # Use Euclidean algorithm
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

def cycpattern_check(a, b):
    if not b:
        return True
    if not a:
        return False

    # Create a string that contains all rotations of b
    # If b is a rotation of a substring of a, then b will appear in a+a
    doubled_b = b + b

    # Check if b is a substring of a
    if b in a:
        return True

    # Check all possible rotations of b
    for i in range(len(b)):
        rotation = doubled_b[i:i+len(b)]
        if rotation in a:
            return True

    return False

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, number) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract just the numbers from the sorted pairs
    return [num for _, _, num in indexed_nums]

def correct_bracketing(brackets: str):
    count = 0
    for char in brackets:
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
            if count < 0:
                return False
    return count == 0

