                    break  # Blocked by white king
                if nr == br and nc == bc:
                    return True  # Under threat
                if nr == wr and nc == wc:
                    break  # Blocked by white king
                nr += dr
                nc += dc

        # Knight moves
        knight_moves = [(-2,-1), (-2,1), (-1,-2), (-1,2), (1,-2), (1,2), (2,-1), (2,1)]
        for dr, dc in knight_moves:
            nr, nc = ar + dr, ac + dc
            if is_valid(nr, nc) and nr == br and nc == bc:
                return True

        return False

    def is_near_white_king(br, bc, wr, wc):
        return is_adjacent(br, bc, wr, wc)

    def is_legal_occupancy(br, bc, wr, wc, ar, ac):
        return is_valid(br, bc) and not (br == wr and bc == wc) and not (br == ar and bc == ac)

    def is_safe_square(br, bc, wr, wc, ar, ac):
        return not is_under_threat(br, bc, wr, wc, ar, ac)

    def count_valid_moves(br, bc, wr, wc, ar, ac):
        count = 0
        moves = get_king_moves(br, bc)
        for nr, nc in moves:
            if (is_legal_occupancy(nr, nc, wr, wc, ar, ac) and 
                not is_under_threat(nr, nc, wr, wc, ar, ac) and 
                not is_near_white_king(nr, nc, wr, wc)):
                count += 1
        return count

    wr, wc = chess_to_coords(king)
    ar, ac = chess_to_coords(amazon)

    result = [0, 0, 0, 0]

    for br in range(8):
        for bc in range(8):
            # Skip if square is occupied by white king or amazon
            if (br == wr and bc == wc) or (br == ar and bc == ac):
                continue

            # Skip if square is adjacent to white king
            if is_adjacent(br, bc, wr, wc):
                continue

            # Check if square is under threat
            under_threat = is_under_threat(br, bc, wr, wc, ar, ac)

            # Count valid moves
            valid_moves = count_valid_moves(br, bc, wr, wc, ar, ac)

            # Determine state
            if under_threat:
                if valid_moves == 0:
                    result[0] += 1  # Checkmate
                else:
                    result[1] += 1   # Check
            else:
                if valid_moves == 0:
                    result[2] += 1   # Stalemate
                else:
                    result[3] += 1   # Safe

    return result

