def amazon_check_mate(king, amazon):
    # Convert chess notation to (row, col) where row is 0-7 and col is 0-7
    def parse_position(pos):
        col = ord(pos[0]) - ord('a')  # 'a' -> 0, 'b' -> 1, ..., 'h' -> 7
        row = int(pos[1]) - 1  # '1' -> 0, '2' -> 1, ..., '8' -> 7
        return row, col

    white_king = parse_position(king)
    white_amazon = parse_position(amazon)

    # Function to check if position is on board
    def is_valid(r, c):
        return 0 <= r < 8 and 0 <= c < 8

    # Function to check if two positions are adjacent (kings cannot be adjacent)
    def are_adjacent(pos1, pos2):
        return abs(pos1[0] - pos2[0]) <= 1 and abs(pos1[1] - pos2[1]) <= 1

    # Function to check if a square is under attack by the amazon
    def is_under_attack(pos, amazon_pos):
        r, c = pos
        ar, ac = amazon_pos

        # Queen-like moves (same row, column, or diagonal)
        if r == ar or c == ac:
            return True
        if abs(r - ar) == abs(c - ac):
            return True

        # Knight-like moves (L-shape)
        dr = abs(r - ar)
        dc = abs(c - ac)
        if (dr == 2 and dc == 1) or (dr == 1 and dc == 2):
            return True

        return False

    # Check all possible positions for black king
    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    for r in range(8):
        for c in range(8):
            black_pos = (r, c)

            # Cannot be on white pieces
            if black_pos == white_king or black_pos == white_amazon:
                continue

            # Cannot be adjacent to white king
            if are_adjacent(black_pos, white_king):
                continue

            # Check if under attack
            under_attack = is_under_attack(black_pos, white_amazon)

            # Check if any valid moves exist
            has_valid_move = False
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    new_pos = (r + dr, c + dc)
                    if not is_valid(new_pos[0], new_pos[1]):
                        continue
                    if new_pos == white_king or new_pos == white_amazon:
                        continue
                    if are_adjacent(new_pos, white_king):
                        continue
                    if is_under_attack(new_pos, white_amazon):
                        continue
                    has_valid_move = True
                    break
                if has_valid_move:
                    break

            # Categorize
            if under_attack:
                if has_valid_move:
                    check += 1
                else:
                    checkmate += 1
            else:
                if has_valid_move:
                    safe += 1
                else:
                    stalemate += 1

    return [checkmate, check, stalemate, safe]

def greatest_common_divisor(a, b):
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    even_count = 0
    odd_count = 0

    for num in range(1, n + 1):
        num_str = str(num)
        if num_str == num_str[::-1]:
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    colors = list(map(int, lines[1].split()))

    # Precompute palindromes
    is_palindrome = [[False] * n for _ in range(n)]

    # Every single gemstone is a palindrome
    for i in range(n):
        is_palindrome[i][i] = True

    # Check for palindromes of length 2
    for i in range(n - 1):
        if colors[i] == colors[i + 1]:
            is_palindrome[i][i + 1] = True

    # Check for palindromes of length 3 and more
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if colors[i] == colors[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP solution
    # dp[i][j] represents minimum seconds to destroy substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Fill DP table
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if i == j:
                # Single gemstone
                dp[i][j] = 1
            elif is_palindrome[i][j]:
                # Substring is palindrome
                dp[i][j] = 1
            else:
                # Need to split
                dp[i][j] = float('inf')
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

