def format_duration(seconds):
    if seconds == 0:
        return "now"

    units = [
        (31536000, "year", "years"),
        (86400, "day", "days"),
        (3600, "hour", "hours"),
        (60, "minute", "minutes"),
        (1, "second", "seconds")
    ]

    components = []

    for value, singular, plural in units:
        count = seconds // value
        if count > 0:
            if count == 1:
                components.append(f"{count} {singular}")
            else:
                components.append(f"{count} {plural}")
            seconds %= value

    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + " and " + components[-1]

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 365 * 24 * 60 * 60),
        ('day', 24 * 60 * 60),
        ('hour', 60 * 60),
        ('minute', 60),
        ('second', 1)
    ]

    # Calculate each time unit
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            if count > 1:
                components.append(f"{count} {unit_name}s")
            else:
                components.append(f"{count} {unit_name}")

    # Format the result
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

import hashlib

def string_to_md5(text):
    if text == "":
        return None

    # Encode the string to bytes and compute MD5 hash
    md5_hash = hashlib.md5(text.encode('utf-8'))

    # Return the hexadecimal representation
    return md5_hash.hexdigest()

def differentiate(polynomial, x):
    # Parse the polynomial into terms
    # Handle the case where the polynomial starts with a minus sign
    if polynomial[0] == '-':
        terms = ['-']
        polynomial = polynomial[1:]
    else:
        terms = []

    # Split by '+' and handle '-' signs properly
    current_term = ""
    for i, char in enumerate(polynomial):
        if char == '+' or char == '-':
            if current_term:
                terms.append(current_term)
            current_term = char
        else:
            current_term += char

    if current_term:
        terms.append(current_term)

    # Process each term
    derivative_sum = 0

    for term in terms:
        if term == '+' or term == '-':
            continue

        # Determine the sign
        sign = 1
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            term = term[1:]

        # Extract coefficient and exponent
        if 'x^' in term:
            # Format: coefficient x^exponent
            parts = term.split('x^')
            coeff_str = parts[0]
            exp_str = parts[1]

            if coeff_str == '':
                coeff = sign * 1
            else:
                coeff = sign * int(coeff_str)

            exp = int(exp_str)

        elif 'x' in term:
            # Format: coefficient x or x
            if term == 'x':
                coeff = sign * 1
                exp = 1
            else:
                # term is like "2x" or "-2x"
                coeff_str = term[:-1]  # Remove the 'x'
                if coeff_str == '+':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = sign * int(coeff_str)
                exp = 1

        else:
            # Constant term
            coeff = sign * int(term)
            exp = 0

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exp == 0:
            # Constant term differentiates to 0
            derivative_term = 0
        else:
            derivative_term = exp * coeff * (x ** (exp - 1))

        derivative_sum += derivative_term

    return derivative_sum

