                elif new_coeff == -1:
                    derivative_terms.append(f'-x^{new_exp}')
                else:
                    derivative_terms.append(f'{new_coeff}x^{new_exp}')
        else:
            # Constant term
            # Derivative of a constant is 0
            continue

    # If no terms, return 0
    if not derivative_terms:
        return 0

    # Evaluate the derivative at x
    result = 0
    for term in derivative_terms:
        if term == 'x':
            result += x
        elif term == '-x':
            result -= x
        elif 'x^' in term:
            # Extract coefficient and exponent
            parts = term.split('x^')
            coeff_str = parts[0]
            exp_str = parts[1]

            if coeff_str == '':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)

            exp = int(exp_str)
            result += coeff * (x ** exp)
        elif term.startswith('-'):
            # Negative coefficient
            coeff = int(term)
            result += coeff
        else:
            # Positive coefficient
            coeff = int(term)
            result += coeff

    return result

