def poohbear(code):
    # Initialize memory and pointer
    memory = {}
    pointer = 0
    copied = 0
    ip = 0
    loop_stack = []
    loop_map = {}

    # Preprocess code to build loop mapping
    for i, char in enumerate(code):
        if char == 'W':
            loop_stack.append(i)
        elif char == 'E':
            if loop_stack:
                start = loop_stack.pop()
                loop_map[start] = i
                loop_map[i] = start

    # Process code
    while ip < len(code):
        char = code[ip]

        if char == '+':
            memory[pointer] = memory.get(pointer, 0) + 1
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == '-':
            memory[pointer] = memory.get(pointer, 0) - 1
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copied = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copied
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                ip = loop_map[ip]
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                ip = loop_map[ip]
        elif char == 'P':
            print(chr(memory.get(pointer, 0)), end='')
        elif char == 'N':
            print(memory.get(pointer, 0))
        elif char == 'T':
            memory[pointer] = memory.get(pointer, 0) * 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'Q':
            memory[pointer] = memory.get(pointer, 0) ** 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'U':
            import math
            memory[pointer] = int(math.sqrt(memory.get(pointer, 0)))
        elif char == 'L':
            memory[pointer] = memory.get(pointer, 0) + 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'V':
            memory[pointer] = memory.get(pointer, 0) // 2
        elif char == 'A':
            memory[pointer] = memory.get(pointer, 0) + copied
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'B':
            memory[pointer] = memory.get(pointer, 0) - copied
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'Y':
            memory[pointer] = memory.get(pointer, 0) * copied
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'D':
            if copied != 0:
                memory[pointer] = memory.get(pointer, 0) // copied
            else:
                memory[pointer] = 0

        ip += 1

    return ''.join(chr(memory.get(i, 0)) for i in sorted(memory.keys()) if memory.get(i, 0) != 0)

import sys
from collections import defaultdict

def parse_url(url):
    # Remove "http://"
    url = url[7:]

    # Split by first slash to get hostname and path
    if '/' in url:
        hostname, path = url.split('/', 1)
    else:
        hostname = url
        path = ""

    return hostname, path

def normalize_path(path):
    # Handle empty path
    if not path:
        return ""

    # Split path into components
    components = path.split('/')

    # Filter out empty components (from leading/trailing slashes)
    components = [c for c in components if c]

    # Build normalized path
    if not components:
        return "/"

    return "/" + "/".join(components)

def get_paths_for_hostname(hostname, urls):
    paths = set()
    for url in urls:
        parsed_hostname, parsed_path = parse_url(url)
        if parsed_hostname == hostname:
            normalized_path = normalize_path(parsed_path)
            paths.add(normalized_path)
    return paths

def hash_paths(paths):
    # Create a sorted tuple of paths for consistent hashing
    sorted_paths = sorted(paths)
    # Join with a delimiter that won't appear in paths
    path_string = "|".join(sorted_paths)
    # Use Python's built-in hash function (should be sufficient for this problem)
    return hash(path_string)

def main():
    data = sys.stdin.read()
    lines = data.strip().split('\n')

    n = int(lines[0])
    urls = lines[1:n+1]

    # Group URLs by hostname
    hostname_to_urls = defaultdict(list)
    for url in urls:
        hostname, _ = parse_url(url)
        hostname_to_urls[hostname].append(url)

    # For each hostname, get its set of paths
    hostname_to_paths = {}
    for hostname in hostname_to_urls:
        paths = get_paths_for_hostname(hostname, urls)
        hostname_to_paths[hostname] = paths

    # Group hostnames by their path sets using hashing
    path_set_to_hostnames = defaultdict(list)

    for hostname, paths in hostname_to_paths.items():
        hash_val = hash_paths(paths)
        path_set_to_hostnames[hash_val].append(hostname)

    # Filter out clusters with only one hostname
    clusters = []
    for hostnames in path_set_to_hostnames.values():
        if len(hostnames) > 1:
            # Verify that the hash actually corresponds to identical path sets
            # (to avoid hash collisions)
            first_paths = hostname_to_paths[hostnames[0]]
            all_same = True
            for hostname in hostnames[1:]:
                if hostname_to_paths[hostname] != first_paths:
                    all_same = False
                    break

            if all_same:
                clusters.append(hostnames)

    # Output results
    print(len(clusters))
    for cluster in clusters:
        print(" ".join(sorted(cluster)))

if __name__ == "__main__":
    main()

import hashlib

def string_to_md5(text):
    if not text:
        return None

    # Encode the string to bytes and compute MD5 hash
    md5_hash = hashlib.md5(text.encode('utf-8'))

    # Return the hexadecimal representation
    return md5_hash.hexdigest()

def get_closest_vowel(word):
    if len(word) < 3:
        return ""

    vowels = set('aeiouAEIOU')

    # Scan from right to left, excluding first and last characters
    for i in range(len(word) - 2, 0, -1):
        # Check if current character is a vowel
        if word[i] in vowels:
            # Check if it's between two consonants
            if word[i-1] not in vowels and word[i+1] not in vowels:
                return word[i]

    return ""

