def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    even_count = 0
    odd_count = 0

    for num in range(1, n + 1):
        # Check if num is a palindrome by comparing string with its reverse
        s = str(num)
        if s == s[::-1]:
            # It's a palindrome, check if even or odd
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    if n < 2:
        return []

    # Use Sieve of Eratosthenes to find all primes less than n
    sieve = [True] * n
    sieve[0] = sieve[1] = False

    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n, i):
                sieve[j] = False

    # Collect primes in ascending order
    primes = []
    for i in range(2, n):
        if sieve[i]:
            primes.append(i)

    return primes

def parse_int(text):
    if text == "zero":
        return 0

    # Mapping of number words to their values
    units = {
        "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
        "six": 6, "seven": 7, "eight": 8, "nine": 9,
        "ten": 10, "eleven": 11, "twelve": 12, "thirteen": 13,
        "fourteen": 14, "fifteen": 15, "sixteen": 16, "seventeen": 17,
        "eighteen": 18, "nineteen": 19
    }

    tens = {
        "twenty": 20, "thirty": 30, "forty": 40, "fifty": 50,
        "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90
    }

    scales = {
        "hundred": 100, "thousand": 1000, "million": 1000000
    }

    # Combine all word mappings
    word_values = {}
    for w, v in units.items():
        word_values[w] = v
    for w, v in tens.items():
        word_values[w] = v
    for w, v in scales.items():
        word_values[w] = v

    # Preprocess: remove "and" and hyphens, split into tokens
    text = text.replace("and", "").replace("-", "")
    tokens = text.split()

    total = 0
    current = 0

    for token in tokens:
        if token in scales:
            scale_value = word_values[token]

            if scale_value == 100:
                current *= 100
            else:
                # For thousand/million, add current to total (multiplied if needed)
                if current > 0:
                    total += current * scale_value
                else:
                    total += scale_value
                current = 0
        else:
            # Regular number word
            current += word_values[token]

    total += current
    return total

def format_duration(seconds):
    if seconds == 0:
        return "now"

    units = [
        ("year", 365 * 24 * 60 * 60),
        ("day", 24 * 60 * 60),
        ("hour", 60 * 60),
        ("minute", 60),
        ("second", 1)
    ]

    parts = []

    for name, value in units:
        count = seconds // value
        if count > 0:
            if count == 1:
                parts.append(f"{count} {name}")
            else:
                parts.append(f"{count} {name}s")
            seconds %= value

    if len(parts) == 1:
        return parts[0]
    else:
        return ", ".join(parts[:-1]) + " and " + parts[-1]

import math

def converter(value, decimals=0, base=math.pi):
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36")

    if value == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Determine if base is integer
    is_integer_base = base == int(base)
    base = int(base)

    # Handle negative numbers
    negative = value < 0
    value = abs(value)

    # Convert integer part
    if is_integer_base:
        # Integer base conversion
        integer_part = int(value)
        result = ""
        if integer_part == 0:
            result = "0"
        else:
            while integer_part > 0:
                digit = integer_part % base
                if digit < 10:
                    result = str(digit) + result
                else:
                    result = chr(ord('A') + digit - 10) + result
                integer_part //= base

        # Handle fractional part for integer bases
        fractional_part = ""
        if decimals > 0:
            remainder = value - int(value)
            fractional_part = "."
            for _ in range(decimals):
                remainder *= base
                digit = int(remainder)
                if digit < 10:
                    fractional_part += str(digit)
                else:
                    fractional_part += chr(ord('A') + digit - 10)
                remainder -= digit
                if remainder < 1e-15:  # Prevent infinite loop
                    break
            # Pad with zeros if needed
            fractional_part = fractional_part.ljust(decimals + 1, '0')
    else:
        # Non-integer base conversion
        integer_part = int(value)
        result = ""

        # Convert integer part using greedy algorithm
        temp_value = integer_part
        powers = []
        power = 1

        # Find the maximum power needed
        while power <= temp_value:
            powers.append(power)
            power *= base

        # Process from highest to lowest power
        remaining = temp_value
        power_index = len(powers) - 1

        while power_index >= 0:
            current_power = powers[power_index]
            if current_power <= remaining:
                digit = int(remaining / current_power)
                # Clamp digit to valid range
                if digit >= base:
                    digit = base - 1
                if digit < 0:
                    digit = 0
                if digit < 10:
                    result += str(digit)
                else:
                    result += chr(ord('A') + digit - 10)
                remaining -= digit * current_power
            else:
                if len(result) > 0:  # Only add zero if we have already added a digit
                    result += "0"
            power_index -= 1

        # Handle fractional part for non-integer bases
        fractional_part = ""
        if decimals > 0:
            fractional_part = "."
            residual = value - integer_part
            for _ in range(decimals):
                if residual < 1e-15:
                    fractional_part += "0"
                else:
                    digit = int(residual * base)
                    # Clamp digit to valid range
                    if digit >= base:
                        digit = base - 1
                    if digit < 0:
                        digit = 0
                    if digit < 10:
                        fractional_part += str(digit)
                    else:
                        fractional_part += chr(ord('A') + digit - 10)
                    residual = residual * base - digit
            # Pad with zeros if needed
            fractional_part = fractional_part.ljust(decimals + 1, '0')

    # Combine result
    final_result = result + fractional_part

    # Handle leading zero for values less than 1
    if float(value) < 1 and decimals > 0:
        if not final_result.startswith("0."):
            final_result = "0" + final_result

    # Handle negative sign
    if negative and final_result != "0":
        final_result = "-" + final_result

    return final_result

def get_closest_vowel(word):
    vowels = "aeiouAEIOU"

    # Need at least 3 characters to have a vowel between two consonants
    if len(word) < 3:
        return ""

    # Iterate from right to left, from len(word)-2 down to 1
    # (excludes beginning at index 0 and ending at index len(word)-1)
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            # Check if it's between two consonants
            if word[i-1] not in vowels and word[i+1] not in vowels:
                return word[i]

    return ""

def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    result = []
    for char_a, char_b in zip(a, b):
        if char_a == char_b:
            result.append('0')
        else:
            result.append('1')
    return ''.join(result)

def solution(text, markers):
    lines = text.split('\n')
    result_lines = []

    for line in lines:
        # Find the earliest position of any comment marker
        min_pos = len(line)
        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < min_pos:
                min_pos = pos

        # Truncate at the marker position
        if min_pos < len(line):
            line = line[:min_pos]

        # Strip trailing whitespace
        line = line.rstrip()
        result_lines.append(line)

    return '\n'.join(result_lines)

