def is_balanced(s):
    """
    Check if parentheses and brackets in a string are properly balanced.

    Args:
        s (str): Input string to check

    Returns:
        bool: True if balanced, False otherwise
    """
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack.pop() != pairs[char]:
                return False

    return len(stack) == 0

