def parse_nested_parens(s):
    if not s:
        return []

    groups = s.split()
    result = []

    for group in groups:
        current_level = 0
        max_level = 0

        for char in group:
            if char == '(':
                current_level += 1
                max_level = max(max_level, current_level)
            elif char == ')':
                current_level -= 1

        result.append(max_level)

    return result

def compare(selector1, selector2):
    def count_specificity(selector):
        id_count = 0
        class_count = 0
        tag_count = 0

        # Split by whitespace to get individual tokens
        tokens = selector.split()

        for token in tokens:
            if not token:
                continue

            # Count IDs
            id_count += token.count('#')

            # Count classes
            class_count += token.count('.')

            # Count tags (alphanumeric characters without # or .)
            # But we need to be careful about tokens like "#id" or ".class"
            # A tag is a token that doesn't start with # or .
            if not token.startswith('#') and not token.startswith('.'):
                tag_count += 1
            elif token.startswith('.'):
                # If token starts with ., check if there are alphanumeric chars after
                # that are not part of class names (this is for tokens like ".class")
                # Actually, we already counted classes above, so we just need to count
                # the tag part, if any
                # For example, in "div.class", we want to count "div" as tag and ".class" as class
                # In "div#main", we want to count "div" as tag and "#main" as id
                # In ".class", we want to count 0 as tag and 1 as class
                # In "#id", we want to count 0 as tag and 0 as class
                # So we check if there are alphanumeric characters before any # or .
                tag_chars = 0
                for char in token:
                    if char.isalnum():
                        tag_chars += 1
                    elif char == '#' or char == '.':
                        break
                if tag_chars > 0:
                    tag_count += 1
            elif token.startswith('#'):
                # For tokens starting with #, check if there are alphanumeric chars after
                # that are not part of the id
                tag_chars = 0
                for char in token:
                    if char.isalnum():
                        tag_chars += 1
                    elif char == '#' or char == '.':
                        break
                if tag_chars > 0:
                    tag_count += 1

        return (id_count, class_count, tag_count)

    # Special case for empty selectors
    if not selector1.strip():
        return selector2
    if not selector2.strip():
        return selector1

    spec1 = count_specificity(selector1)
    spec2 = count_specificity(selector2)

    # Compare specificity
    if spec1 > spec2:
        return selector1
    else:
        # If spec1 == spec2, selector2 wins due to tie-breaking rule
        return selector2

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == '':
