import math

def converter(number, decimals=0, base=math.pi):
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36")

    if decimals < 0:
        raise ValueError("Decimals must be non-negative")

    # Handle zero case
    if number == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Handle sign
    sign = ""
    if number < 0:
        sign = "-"
        number = -number

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Build integer part
    if integer_part == 0:
        integer_digits = []
    else:
        # Find maximum power
        max_power = int(math.log(integer_part) / math.log(base)) if base > 1 else 0
        if base <= 1:
            max_power = 0

        integer_digits = []
        remaining = integer_part

        # Handle case where base is less than 1
        if base < 1:
            # For bases < 1, we need to be more careful
            temp = remaining
            power = 0
            while temp >= 1 and power < 100:  # Prevent infinite loop
                temp /= base
                power += 1
            max_power = power
            remaining = integer_part

        # Greedily build digits from highest power down
        for power in range(max_power, -1, -1):
            if remaining == 0:
                integer_digits.append('0')
            else:
                digit_value = int(remaining // (base ** power))
                if digit_value >= base:
                    digit_value = int(base - 1)  # Cap at base-1
                integer_digits.append(str(digit_value))
                remaining -= digit_value * (base ** power)

    # Handle case where all digits are zero
    if not integer_digits or all(d == '0' for d in integer_digits):
        integer_str = "0"
    else:
        # Remove leading zeros
        while len(integer_digits) > 1 and integer_digits[0] == '0':
            integer_digits.pop(0)
        integer_str = ''.join(integer_digits)

    # Convert fractional part
    fractional_digits = []
    if decimals > 0:
        remainder = fractional_part
        for _ in range(decimals):
            if remainder == 0:
                fractional_digits.append('0')
            else:
                product = remainder * base
                digit_value = int(product)
                if digit_value >= base:
                    digit_value = int(base - 1)  # Cap at base-1
                fractional_digits.append(str(digit_value))
                remainder = product - digit_value

    # Build result
    result = integer_str
    if fractional_digits:
        result += "." + "".join(fractional_digits)

    return sign + result

