def is_balanced(s, pairs):
    # Build mapping from closing to opening character
    closing_to_opening = {}
    opening_chars = set()

    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        closing_to_opening[closing] = opening
        opening_chars.add(opening)

    stack = []

    for char in s:
        if char in opening_chars:
            # For characters that are both opening and closing (like ''),
            # check if this should be a closing operation first
            if char in closing_to_opening and stack and stack[-1] == closing_to_opening[char]:
                stack.pop()
            else:
                stack.append(char)
        elif char in closing_to_opening:
            # Must have something to close and must match
            if not stack or stack[-1] != closing_to_opening[char]:
                return False
            stack.pop()
        # Characters not in pairs are ignored

    return len(stack) == 0

def cycpattern_check(a, b):
    # Handle edge cases
    if not b:
        return True
    if not a:
        return False

    # If length of b is greater than a, no rotation of b can be in a
    if len(b) > len(a):
        return False

    # Create doubled string b to contain all rotations
    doubled_b = b + b

    # Check if any rotation of b is a substring of a
    for i in range(len(b)):
        rotation = doubled_b[i:i+len(b)]
        if rotation in a:
            return True

    return False

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == "":
        return None

    return hashlib.md5(text.encode('utf-8')).hexdigest()

