    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """

    def to_numeric(value):
        if isinstance(value, str):
            return float(value.replace(',', '.'))
        else:
            return float(value)

    num_a = to_numeric(a)
    num_b = to_numeric(b)

    if num_a == num_b:
        return None
    elif num_a > num_b:
        return a
    else:
        return b

def histogram(s):
    if not s:
        return {}

    # Split the string and count frequencies
    letters = s.split()
    freq = {}
    for letter in letters:
        freq[letter] = freq.get(letter, 0) + 1

    # Find the maximum frequency
    max_freq = max(freq.values())

    # Return dictionary with only the letters having maximum frequency
    return {letter: count for letter, count in freq.items() if count == max_freq}

def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    result = ""
    for i in range(len(a)):
        if a[i] == b[i]:
            result += "0"
        else:
            result += "1"
    return result

def get_closest_vowel(word):
    vowels = set('aeiouAEIOU')

    # Need at least 3 characters to have a vowel between two consonants
    if len(word) < 3:
        return ""

    # Search from right to left, excluding first and last characters
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            # Check if both neighbors are consonants (not vowels and are letters)
            left_is_consonant = word[i-1].isalpha() and word[i-1] not in vowels
            right_is_consonant = word[i+1].isalpha() and word[i+1] not in vowels

            if left_is_consonant and right_is_consonant:
                return word[i]

    return ""

