def simplify(expression):
    if not expression:
        return ""

    # Tokenize expression into terms
    terms = []
    i = 0
    while i < len(expression):
        start = i
        while i < len(expression) and expression[i] not in '+-':
            i += 1
        if i > start:
            terms.append(expression[start:i])

    # Process each term to extract coefficient and variable part
    from collections import defaultdict
    term_dict = defaultdict(int)

    for term in terms:
        # Handle sign
        sign = 1
        if term[0] == '+':
            term = term[1:]
        elif term[0] == '-':
            sign = -1
            term = term[1:]

        # Handle empty term after sign removal (shouldn't happen but safety check)
        if not term:
            continue

        # Parse coefficient and variable part
        coeff = 1
        var_start = 0
        if term[0].isdigit():
            # Find end of coefficient
            var_start = 0
            while var_start < len(term) and term[var_start].isdigit():
                var_start += 1
            coeff = int(term[:var_start])
            var_part = term[var_start:]
        else:
            var_part = term

        # Apply sign
        coeff *= sign

        if not var_part:
            # This shouldn't happen based on problem statement (no constants)
            continue

        # Normalize variable part (sort letters for canonical form)
        var_part = ''.join(sorted(var_part))

        # Add to dictionary
        term_dict[var_part] += coeff

    # Filter out zero coefficients
    term_dict = {k: v for k, v in term_dict.items() if v != 0}

    # Sort terms: by length of variable part, then lexicographically
    sorted_terms = sorted(term_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Format output
    result = []
    for i, (var, coeff) in enumerate(sorted_terms):
        if coeff == 1:
            if i == 0:
                result.append(var)
            else:
                result.append('+' + var)
        elif coeff == -1:
            if i == 0:
                result.append('-' + var)
            else:
                result.append('-' + var)
        elif coeff > 0:
            if i == 0:
                result.append(str(coeff) + var)
            else:
                result.append('+' + str(coeff) + var)
        else:  # coeff < 0 and not -1
            if i == 0:
                result.append(str(coeff) + var)
            else:
                result.append(str(coeff) + var)

    return ''.join(result)

