def parse_int(s):
    if not s:
        return 0

    # Define word mappings
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14, 'fifteen': 15,
        'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19, 'twenty': 20,
        'thirty': 30, 'forty': 40, 'fifty': 50, 'sixty': 60, 'seventy': 70,
        'eighty': 80, 'ninety': 90
    }

    # Normalize input: remove 'and', split by spaces and hyphens
    s = s.replace(' and ', ' ')
    tokens = []
    for token in s.split():
        tokens.extend(token.split('-'))

    result = 0
    current = 0

    for token in tokens:
        if token in word_to_num:
            current += word_to_num[token]
        elif token == 'hundred':
            current *= 100
        elif token == 'thousand':
            result += current * 1000
            current = 0
        elif token == 'million':
            result += current * 1000000
            current = 0

    return result + current

def histogram(s):
    if not s:
        return {}

    # Count frequency of each letter
    freq = {}
    for letter in s.split():
        freq[letter] = freq.get(letter, 0) + 1

    # Find maximum frequency
    max_freq = max(freq.values())

    # Return all letters with maximum frequency
    return {letter: count for letter, count in freq.items() if count == max_freq}

def is_balanced(s, pairs):
    open_chars = set()
    close_to_open = {}

    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        open_chars.add(open_char)
        close_to_open[close_char] = open_char

    stack = []

    for char in s:
        if char in open_chars:
            if char in close_to_open and stack and stack[-1] == char:
                stack.pop()
            else:
                stack.append(char)
        elif char in close_to_open:
            if not stack or stack[-1] != close_to_open[char]:
                return False
            stack.pop()

    return len(stack) == 0

