    if not (s[0].isalpha() or s[0] == '_' or s[0] == '$'):
        return False

    # Check if all remaining characters are valid
    for i in range(1, len(s)):
        if not (s[i].isalpha() or s[i].isdigit() or s[i] == '_' or s[i] == '$'):
            return False

    return True

def almost_everywhere_zero(n, k):
    n_str = str(n)
    length = len(n_str)

    memo = {}

    def dp(pos, cnt, tight, leading_zero):
        state = (pos, cnt, tight, leading_zero)
        if state in memo:
            return memo[state]

        if pos == length:
            return 1 if cnt == k and not leading_zero else 0

        limit = int(n_str[pos]) if tight else 9
        result = 0

        for digit in range(0, limit + 1):
            new_tight = tight and (digit == limit)
            new_leading_zero = leading_zero and (digit == 0)
            new_cnt = cnt + (1 if digit != 0 else 0)

            if new_cnt <= k:
                result += dp(pos + 1, new_cnt, new_tight, new_leading_zero)

        memo[state] = result
        return result

    return dp(0, 0, True, True)

def getAllPrimeFactors(n):
    # Input validation
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []
    if isinstance(n, float) and not n.is_integer():
        return []
    if n <= 0:
        return []

    n = int(n)

    # Special case for n=1
    if n == 1:
        return [1]

    factors = []
    divisor = 2

    # Trial division up to sqrt(n)
    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n = n // divisor
        divisor += 1

    # If n is still greater than 1, it's a prime factor
    if n > 1:
        factors.append(n)

    return factors


