    return sorted(nums, key=digit_sum)

def simplify(expression):
    from collections import defaultdict

    if not expression or not expression.strip():
        return ""

    expression = expression.strip()

    # Parse terms - split by + and - while preserving the sign of each term
    terms = []
    i = 0
    while i < len(expression):
        start = i
        if expression[i] == '+' or expression[i] == '-':
            i += 1
        j = i
        while j < len(expression) and expression[j] not in ['+', '-']:
            j += 1
        if j > start:
            terms.append(expression[start:j])
        i = j

    # Dictionary to store coefficient for each variable combination
    coeff_dict = defaultdict(int)

    for term in terms:
        if not term:
            continue

        # Determine sign
        sign = 1
        var_part = term
        if term[0] == '+':
            var_part = term[1:]
        elif term[0] == '-':
            sign = -1
            var_part = term[1:]

        if not var_part:
            continue

        # Parse coefficient
        coeff_idx = 0
        while coeff_idx < len(var_part) and var_part[coeff_idx].isdigit():
            coeff_idx += 1

        if coeff_idx == 0:
            # No explicit coefficient, it's 1
            coefficient = sign
            variables = var_part
        elif coeff_idx == len(var_part):
            # Only coefficient, no variables (should not happen per problem)
            continue
        else:
            coefficient = int(var_part[:coeff_idx]) * sign
            variables = var_part[coeff_idx:]

        # Sort variables lexicographically (xy == yx)
        sorted_vars = ''.join(sorted(variables))

        coeff_dict[sorted_vars] += coefficient

    # Build list of non-zero terms
    result = []
    for vars, coeff in coeff_dict.items():
        if coeff != 0:
            result.append((vars, coeff))

    if not result:
        return ""

    # Sort by number of variables, then lexicographically
    result.sort(key=lambda x: (len(x[0]), x[0]))

    # Format output
    parts = []
    for i, (vars, coeff) in enumerate(result):
        if coeff == 1 and len(vars) > 0:
            coeff_str = ""
        elif coeff == -1 and len(vars) > 0:
            coeff_str = "-"
        else:
            coeff_str = str(coeff)

        if i == 0 and coeff > 0:
            parts.append(coeff_str + vars)
        else:
            parts.append(coeff_str + vars)

    return ''.join(parts)

