def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px, py = find(parent, x), find(parent, y)
    if px != py:
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1

def solve():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])

    edges = []
    for i in range(1, n):
        a, b, c = map(int, lines[i].split())
        edges.append((c, a, b))

    x = []
    for i in range(n):
        x.append(int(lines[n + i]))

    # Sort edges by weight
    edges.sort()

    # Get unique weights
    weights = []
    for c, a, b in edges:
        if not weights or weights[-1] != c:
            weights.append(c)

    # Binary search on answer
    def can_achieve_threshold(threshold):
        # Create union-find structure
        parent = list(range(n + 1))
        rank = [0] * (n + 1)

        # Union nodes connected by edges with weight < threshold
        for c, a, b in edges:
            if c < threshold:
                union(parent, rank, a, b)

        # Group nodes by their root
        components = defaultdict(list)
        for i in range(1, n + 1):
            root = find(parent, i)
            components[root].append(i)

        # Calculate demand for each component
        total_demand = 0
        for root, nodes in components.items():
            demand = 0
            for node in nodes:
                demand += x[node - 1] + 1  # +1 because each node in component needs to be matched to some node outside
            total_demand += demand

        # Check if total demand is <= total capacity
        total_capacity = sum(x)
        return total_demand <= total_capacity

    # Binary search
    left, right = 0, len(weights)
    result = 0

    while left < right:
        mid = (left + right + 1) // 2
        if mid < len(weights):
            threshold = weights[mid]
        else:
            threshold = float('inf')

        if can_achieve_threshold(threshold):
            result = threshold
            left = mid
        else:
            right = mid - 1

    print(result)

