def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    i = 2

    while i * i <= d:
        if d % i == 0:
            result -= result // i
            while d % i == 0:
                d //= i
        i += 1

    if d > 1:
        result -= result // d

    return result

