def choose(n, k):
    # Handle edge cases
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry property to minimize iterations
    if k > n // 2:
        k = n - k

    # Compute C(n, k) iteratively using multiplicative formula
    # C(n, k) = product from i=1 to k of (n - i + 1) / i
    result = 1
    for i in range(1, k + 1):
        result = result * (n - i + 1) // i

    return result

def is_balanced(s):
    stack = []
    pairs = {'(': ')', '{': '}', '[': ']'}

    for char in s:
        if char in pairs:
            stack.append(char)
        elif char in pairs.values():
            if not stack:
                return False
            top = stack.pop()
            if pairs[top] != char:
                return False

    return len(stack) == 0

