import sys

def solve():
    data = sys.stdin.read()
    lines = data.splitlines()

    # Parse first line
    n, l, r, Ql, Qr = map(int, lines[0].split())

    # Parse second line
    weights = list(map(int, lines[1].split()))

    # dp[i][j][0] = minimum energy to take i items from left, j items from right, last action was from left
    # dp[i][j][1] = minimum energy to take i items from left, j items from right, last action was from right

    # Initialize DP array
    INF = float('inf')
    dp = [[[-1, -1] for _ in range(n + 1)] for _ in range(n + 1)]

    # Base case: no items taken
    dp[0][0][0] = 0
    dp[0][0][1] = 0

    # Fill DP table
    for i in range(n + 1):
        for j in range(n + 1):
            if i + j > n:
                continue

            # If we can take from left
            if i < n and i + j < n:
                # Take from left
                cost = weights[i] * l
                if i > 0:  # Previous action was from left
                    cost += Ql

                if dp[i][j][0] != -1:
                    if dp[i + 1][j][0] == -1:
                        dp[i + 1][j][0] = dp[i][j][0] + cost
                    else:
                        dp[i + 1][j][0] = min(dp[i + 1][j][0], dp[i][j][0] + cost)

                # Take from right (if previous action was from left)
                if dp[i][j][0] != -1:
                    if dp[i][j + 1][1] == -1:
                        dp[i][j + 1][1] = dp[i][j][0] + weights[n - 1 - j] * r
                    else:
                        dp[i][j + 1][1] = min(dp[i][j + 1][1], dp[i][j][0] + weights[n - 1 - j] * r)

            # If we can take from right
            if j < n and i + j < n:
                # Take from right
                cost = weights[n - 1 - j] * r
                if j > 0:  # Previous action was from right
                    cost += Qr

                if dp[i][j][1] != -1:
                    if dp[i][j + 1][1] == -1:
                        dp[i][j + 1][1] = dp[i][j][1] + cost
                    else:
                        dp[i][j + 1][1] = min(dp[i][j + 1][1], dp[i][j][1] + cost)

                # Take from left (if previous action was from right)
                if dp[i][j][1] != -1:
                    if dp[i + 1][j][0] == -1:
                        dp[i + 1][j][0] = dp[i][j][1] + weights[i] * l
                    else:
                        dp[i + 1][j][0] = min(dp[i + 1][j][0], dp[i][j][1] + weights[i] * l)

    # Find minimum energy to collect all items
    result = INF
    for i in range(n + 1):
        for j in range(n + 1):
            if i + j == n:
                if dp[i][j][0] != -1:
                    result = min(result, dp[i][j][0])
                if dp[i][j][1] != -1:
                    result = min(result, dp[i][j][1])

    print(result)

