def converter(number, decimals=0, base=3.141592653589793):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Split into integer and fractional parts
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_result = ''
    else:
        digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        integer_result = ''
        while integer_part > 0:
            remainder = integer_part % base
            # Handle floating point precision issues
            if remainder >= base:
                remainder = base - 1e-10
            elif remainder < 0:
                remainder = 0
            integer_result = digits[int(round(remainder))] + integer_result
            integer_part = int((integer_part - remainder) / base)

    # Convert fractional part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            # Handle floating point precision issues
            if digit >= base:
                digit = int(base - 1e-10)
            elif digit < 0:
                digit = 0
            fractional_result += str(digit)
            fractional_part -= digit

    # Combine results
    result = integer_result + fractional_result

    # Handle negative sign
    if negative:
        result = '-' + result

    # Ensure leading zero for numbers less than 1
    if result.startswith('.'):
        result = '0' + result

    return result

def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) <= 1:
        return True

    is_increasing = None

    for i in range(1, len(l)):
        if l[i] > l[i-1]:
            if is_increasing is False:
                return False
            is_increasing = True
        elif l[i] < l[i-1]:
            if is_increasing is True:
                return False
            is_increasing = False
        # If l[i] == l[i-1], we continue without changing the trend

    return True

def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def coords_to_chess(x, y):
        return chr(x + ord('a')) + str(y + 1)

    def is_valid(x, y):
        return 0 <= x < 8 and 0 <= y < 8

    def get_amazon_attacks(amazon_x, amazon_y):
        attacks = set()

        # Queen moves (rook + bishop)
        # Horizontal and vertical
        for i in range(8):
            if i != amazon_x:
                attacks.add((i, amazon_y))
            if i != amazon_y:
                attacks.add((amazon_x, i))

        # Diagonal moves
        for i in range(1, 8):
            if is_valid(amazon_x + i, amazon_y + i):
                attacks.add((amazon_x + i, amazon_y + i))
            if is_valid(amazon_x + i, amazon_y - i):
                attacks.add((amazon_x + i, amazon_y - i))
            if is_valid(amazon_x - i, amazon_y + i):
                attacks.add((amazon_x - i, amazon_y + i))
            if is_valid(amazon_x - i, amazon_y - i):
                attacks.add((amazon_x - i, amazon_y - i))

        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            new_x, new_y = amazon_x + dx, amazon_y + dy
            if is_valid(new_x, new_y):
                attacks.add((new_x, new_y))

        return attacks

    def get_king_moves(x, y):
        moves = []
        for i in range(-1, 2):
            for j in range(-1, 2):
                if i == 0 and j == 0:
                    continue
                new_x, new_y = x + i, y + j
                if is_valid(new_x, new_y):
                    moves.append((new_x, new_y))
        return moves

    def is_adjacent(x1, y1, x2, y2):
        return abs(x1 - x2) <= 1 and abs(y1 - y2) <= 1

    king_x, king_y = chess_to_coords(king)
    amazon_x, amazon_y = chess_to_coords(amazon)

    attacks = get_amazon_attacks(amazon_x, amazon_y)

    result = [0, 0, 0, 0]  # checkmate, check, stalemate, safe

    for x in range(8):
        for y in range(8):
            # Skip if king is adjacent to white king
            if is_adjacent(king_x, king_y, x, y):
                continue

            # Check if black king is under attack
            is_under_attack = (x, y) in attacks

            # Get all possible moves for black king
            king_moves = get_king_moves(x, y)

            # Check if any move leads to a safe square
            can_move_to_safe = False
            for move_x, move_y in king_moves:
                if not is_adjacent(king_x, king_y, move_x, move_y) and (move_x, move_y) not in attacks:
                    can_move_to_safe = True
                    break

            if is_under_attack:
                if not can_move_to_safe:
                    # Checkmate
                    result[0] += 1
                else:
                    # Check
                    result[1] += 1
            else:
                if not can_move_to_safe:
                    # Stalemate
                    result[2] += 1
                else:
                    # Safe
                    result[3] += 1

    return result

def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    i = 2

    while i * i <= d:
        if d % i == 0:
            result = result // i * (i - 1)
            while d % i == 0:
                d //= i
        i += 1

    if d > 1:
        result = result // d * (d - 1)

    return result

def poohbear(code):
    memory = {}  # Sparse memory dictionary, key is position, value is byte
    pointer = 0  # Current cell pointer
    copy_reg = 0  # Copied value register

    def wrap(val):
        return val % 256

    def get_cell():
        return memory.get(pointer, 0)

    def set_cell(val):
        memory[pointer] = wrap(val)

    # Preprocess code to find matching W/E pairs
    def find_matching(code, start_pos, direction):
        depth = 0
        pos = start_pos
        while pos < len(code):
            if code[pos] == 'W':
                if direction == 1:
                    depth += 1
                else:
                    if depth == 0:
                        return pos
                    depth -= 1
            elif code[pos] == 'E':
                if direction == -1:
                    depth += 1
                else:
                    if depth == 0:
                        return pos
                    depth -= 1
            pos += direction
        return None

    output = []
    ip = 0  # Instruction pointer

    while ip < len(code):
        cmd = code[ip]

        if cmd == '+':
            set_cell(get_cell() + 1)
        elif cmd == '-':
            set_cell(get_cell() - 1)
        elif cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == 'c':
            copy_reg = get_cell()
        elif cmd == 'p':
            set_cell(copy_reg)
        elif cmd == 'W':
            if get_cell() == 0:
                # Jump to matching E
                match = find_matching(code, ip + 1, 1)
                if match is not None:
                    ip = match
                else:
                    ip += 1
            else:
                ip += 1
        elif cmd == 'E':
            if get_cell() != 0:
                # Jump back to matching W
                match = find_matching(code, ip - 1, -1)
                if match is not None:
                    ip = match
                else:
                    ip += 1
            else:
                ip += 1
        elif cmd == 'P':
            output.append(chr(get_cell()))
        elif cmd == 'N':
            output.append(str(get_cell()))
        elif cmd == 'T':
            set_cell(get_cell() * 2)
        elif cmd == 'Q':
            set_cell(get_cell() ** 2)
        elif cmd == 'U':
            set_cell(int(get_cell() ** 0.5))
        elif cmd == 'L':
            set_cell(get_cell() + 2)
        elif cmd == 'I':
            set_cell(get_cell() - 2)
        elif cmd == 'V':
            set_cell(int(get_cell() / 2))
        elif cmd == 'A':
            set_cell(get_cell() + copy_reg)
        elif cmd == 'B':
            set_cell(get_cell() - copy_reg)
        elif cmd == 'Y':
            set_cell(get_cell() * copy_reg)
        elif cmd == 'D':
            if copy_reg != 0:
                set_cell(int(get_cell() / copy_reg))
            # If copy_reg is 0, no change (division by zero undefined)

        ip += 1

    return ''.join(output)

def poohbear(code):
    # Filter valid commands only
    valid_commands = '+-><cWEPNTQULIVABYD'
    filtered_code = [c for c in code if c in valid_commands]

    # Build jump map for W/E loop pairing
    jump_map = {}
    stack = []
    for i, char in enumerate(filtered_code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                w_idx = stack.pop()
                jump_map[w_idx] = i
                jump_map[i] = w_idx

    # Initialize state
    memory = {}  # Infinite cells, default 0 for any index
    pointer = 0  # Data pointer (can be negative)
    copy_register = 0  # Copy register
    pc = 0  # Program counter
    output = []  # Output accumulator

    def get_cell(addr):
        return memory.get(addr, 0)

    def set_cell(addr, val):
        # Wrap value to 0-255 range
        memory[addr] = val % 256

    # Execute commands
    while pc < len(filtered_code):
        cmd = filtered_code[pc]
        current_val = get_cell(pointer)

        if cmd == '+':
            set_cell(pointer, current_val + 1)
            pc += 1
        elif cmd == '-':
            set_cell(pointer, current_val - 1)
            pc += 1
        elif cmd == '>':
            pointer += 1
            pc += 1
        elif cmd == '<':
            pointer -= 1
            pc += 1
        elif cmd == 'c':
            copy_register = current_val
            pc += 1
        elif cmd == 'p':
            set_cell(pointer, copy_register)
            pc += 1
        elif cmd == 'W':
            if current_val == 0:
                pc = jump_map.get(pc, pc + 1)
            else:
                pc += 1
        elif cmd == 'E':
            if current_val != 0:
                pc = jump_map.get(pc, pc)
            else:
                pc += 1
        elif cmd == 'P':
            output.append(chr(current_val))
            pc += 1
        elif cmd == 'N':
            output.append(str(current_val))
            pc += 1
        elif cmd == 'T':
            set_cell(pointer, current_val * 2)
            pc += 1
        elif cmd == 'Q':
            set_cell(pointer, current_val * current_val)
            pc += 1
        elif cmd == 'U':
            set_cell(pointer, int(current_val ** 0.5))
            pc += 1
        elif cmd == 'L':
            set_cell(pointer, current_val + 2)
            pc += 1
        elif cmd == 'I':
            set_cell(pointer, current_val - 2)
            pc += 1
        elif cmd == 'V':
            set_cell(pointer, current_val // 2)
            pc += 1
        elif cmd == 'A':
            set_cell(pointer, current_val + copy_register)
            pc += 1
        elif cmd == 'B':
            set_cell(pointer, current_val - copy_register)
            pc += 1
        elif cmd == 'Y':
            set_cell(pointer, current_val * copy_register)
            pc += 1
        elif cmd == 'D':
            if copy_register != 0:
                set_cell(pointer, current_val // copy_register)
            pc += 1
        else:
            pc += 1

    return ''.join(output)

def proper_fractions(d):
    if d == 1:
        return 0

    result = d

    # Check for factor 2
    if d % 2 == 0:
        result -= result // 2
        while d % 2 == 0:
            d //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= d:
        if d % i == 0:
            result -= result // i
            while d % i == 0:
                d //= i
        i += 2

    # If d is still greater than 1, then it's a prime factor
    if d > 1:
        result -= result // d

    return result

def reverse_delete(s, c):
