    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            integer_digits.append(temp % base)
            temp //= base
        integer_digits.reverse()

    # Convert fractional part
    fractional_part = number - integer_part
    fractional_digits = []

    if fractional_part > 0:
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            fractional_digits.append(digit)
            fractional_part -= digit
            if fractional_part == 0:
                break

    # Format digits
    digits = []

    # Handle integer part
    if integer_digits:
        digits.extend(integer_digits)
    else:
        digits.append(0)

    # Handle fractional part
    if decimals > 0:
        digits.append('.')
        digits.extend(fractional_digits)

        # Pad with zeros if needed
        while len(digits) - digits.index('.') - 1 < decimals:
            digits.append(0)

    # Convert digits to characters
    digit_chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    result = ''.join(digit_chars[d] for d in digits if d != '.')

    # Add decimal point back in if needed
    if decimals > 0:
        # Find where to place decimal point
        integer_part_len = len(integer_digits) if integer_digits else 1
        if integer_part_len == 0:
            result = '0.' + result[1:]
        else:
            result = result[:integer_part_len] + '.' + result[integer_part_len:]

    # Special case for numbers less than 1 (exactly one leading zero)
    if integer_part == 0 and decimals > 0:
        if not result.startswith('0.'):
            result = '0.' + result[1:]

    # Handle case where we have integer part but no fractional part
    if decimals == 0 and integer_part > 0:
        result = ''.join(digit_chars[d] for d in integer_digits)

    # Special case for zero
    if number == 0:
        return '0'

    # Handle negative sign
    if negative:
        result = '-' + result

    # Special handling for base π conversion cases
    if base == 3.141592653589793 and decimals == 0:
        # This is a special case for π base
        pass

    # Rebuild result properly
    if decimals == 0:
        if integer_part == 0:
