def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, value) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract the sorted values
    return [num for _, _, num in indexed_nums]

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    # Split the string and count frequencies
    letters = test.split()
    freq_count = {}

    for letter in letters:
        freq_count[letter] = freq_count.get(letter, 0) + 1

    # Find the maximum frequency
    max_freq = max(freq_count.values())

    # Return dictionary with all letters that have maximum frequency
    return {letter: count for letter, count in freq_count.items() if count == max_freq}

def sum_array(arr):
    # Handle edge cases: None, empty, or single element arrays
    if arr is None or len(arr) < 2:
        return 0

    # Calculate the sum of all elements, then subtract one min and one max
    return sum(arr) - min(arr) - max(arr)

def getAllPrimeFactors(n):
    # Error handling for non-numbers
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []
    # Error handling for non-integers
    if isinstance(n, float):
        return []
    # Error handling for negative or zero
    if n <= 0:
        return []
    # Special case for n=1
    if n == 1:
        return [1]

    factors = []
    # Handle factor 2
    while n % 2 == 0:
        factors.append(2)
        n //= 2

    # Handle odd factors from 3 onwards
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 2

    # If n is still greater than 1, it's a prime factor
    if n > 1:
        factors.append(n)

    return factors


def getUniquePrimeFactorsWithCount(n):
    # Error handling for non-numbers
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return [[], []]
    # Error handling for non-integers
    if isinstance(n, float):
        return [[], []]
    # Error handling for negative or zero
    if n <= 0:
        return [[], []]
    # Special case for n=1
    if n == 1:
        return [[1], [1]]

    unique_factors = []
    counts = []

    # Handle factor 2
    if n % 2 == 0:
        count = 0
        while n % 2 == 0:
            count += 1
            n //= 2
        unique_factors.append(2)
        counts.append(count)

    # Handle odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            count = 0
            while n % i == 0:
                count += 1
                n //= i
            unique_factors.append(i)
            counts.append(count)
        i += 2

    # If n is still greater than 1, it's a prime factor
    if n > 1:
        unique_factors.append(n)
        counts.append(1)

    return [unique_factors, counts]


def getUniquePrimeFactorsWithProducts(n):
    # Error handling for non-numbers
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []
    # Error handling for non-integers
    if isinstance(n, float):
        return []
    # Error handling for negative or zero
    if n <= 0:
        return []
    # Special case for n=1
    if n == 1:
        return [1]

    products = []

    # Handle factor 2
    if n % 2 == 0:
        count = 0
        while n % 2 == 0:
            count += 1
            n //= 2
        products.append(2 ** count)

    # Handle odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            count = 0
            while n % i == 0:
                count += 1
                n //= i
            products.append(i ** count)
        i += 2

    # If n is still greater than 1, it's a prime factor
    if n > 1:
        products.append(n)

    return products

