    return [checkmate, check, stalemate, safe_with_move]

def solution(input_str, markers):
    lines = input_str.split('\n')
    result_lines = []

    for line in lines:
        min_index = len(line)

        for marker in markers:
            index = line.find(marker)
            if index != -1 and index < min_index:
                min_index = index

        processed_line = line[:min_index].rstrip()
        result_lines.append(processed_line)

    return '\n'.join(result_lines)

def get_closest_vowel(word):
    vowels = set('aeiouAEIOU')

    # Iterate from right to left, checking positions between first and last character
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            # Check if both neighbors are consonants (not vowels)
            if word[i-1] not in vowels and word[i+1] not in vowels:
                return word[i]

    return ""

