        # Horizontal (left and right)
        for dc in range(-8, 9):
            if dc == 0:
                continue
            nc = c + dc
            if 0 <= nc <= 7:
                attacks.add((r, nc))

        # Vertical (up and down)
        for dr in range(-8, 9):
            if dr == 0:
                continue
            nr = r + dr
            if 0 <= nr <= 7:
                attacks.add((nr, c))

        # Diagonal (4 directions)
        for dr in range(-8, 9):
            if dr == 0:
                continue
            # Down-right
            nr = r + dr
            nc = c + dr
            if 0 <= nr <= 7 and 0 <= nc <= 7:
                attacks.add((nr, nc))
            # Down-left
            nr = r + dr
            nc = c - dr
            if 0 <= nr <= 7 and 0 <= nc <= 7:
                attacks.add((nr, nc))

        # Knight moves (8 possible L-shaped jumps)
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
                        (1, -2), (1, 2), (2, -1), (2, 1)]
        for dr, dc in knight_moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr <= 7 and 0 <= nc <= 7:
                attacks.add((nr, nc))

        return attacks

