    def get_king_adjacent(pos):
        adjacent = set()
        r, c = pos
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr <= 7 and 0 <= nc <= 7:
                    adjacent.add((nr, nc))
        return adjacent

    king_adjacent = get_king_adjacent(king_pos)

    # Count positions for each category
    checkmate_count = 0
    check_count = 0
    stalemate_count = 0
    safe_count = 0

    # Iterate through all 64 squares
    for row in range(8):
        for col in range(8):
            black_pos = (row, col)

            # Skip invalid positions
            if black_pos == king_pos or black_pos == amazon_pos:
                continue
            if black_pos in king_adjacent:
                continue

            # Check if under amazon attack
            under_attack = black_pos in amazon_attacks

            # Get all adjacent squares for black king (potential moves)
            black_adjacent = get_king_adjacent(black_pos)

            # Filter to only valid moves (within board, not on white pieces, not adjacent to white king)
            valid_moves = []
            for move in black_adjacent:
                if move != king_pos and move != amazon_pos and move not in king_adjacent:
                    valid_moves.append(move)

            if under_attack:
                # Under attack - check if any valid move leads to safety
                can_escape = False
                for move in valid_moves:
                    if move not in amazon_attacks:
                        can_escape = True
                        break

                if can_escape:
                    check_count += 1
                else:
                    checkmate_count += 1
            else:
                # Not under attack - check if any valid moves exist
                if len(valid_moves) > 0:
                    safe_count += 1
                else:
                    stalemate_count += 1

    return [checkmate_count, check_count, stalemate_count, safe_count]

def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        # Check if the number is a palindrome
        if str(i) == str(i)[::-1]:
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def cycpattern_check(a, b):
    # Check if b is longer than a
    if len(b) > len(a):
        return False

    # If b is empty, it should be considered as a substring
    if len(b) == 0:
        return True

    # Create doubled string to contain all rotations
    doubled_b = b + b

    # Check if any rotation of b exists in a
    for i in range(len(b)):
        rotation = doubled_b[i:i+len(b)]
        if rotation in a:
            return True

    return False

