def valid_mersenne(n):
    if n < 2:
        return False

    # Calculate 2^n - 1
    mersenne_number = (2 ** n) - 1

    # Check if the number is prime
    if mersenne_number < 2:
        return False

    # Simple prime checking
    for i in range(2, int(mersenne_number ** 0.5) + 1):
        if mersenne_number % i == 0:
            return False

    return True

def decimal_to_binary(decimal):
    if decimal == 0:
        return "db0db"

    binary_digits = []
    while decimal > 0:
        binary_digits.append(str(decimal % 2))
        decimal = decimal // 2

    # Reverse the digits to get the correct binary representation
    binary_string = ''.join(reversed(binary_digits))
    return f"db{binary_string}db"

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    result = []

    if integer_part == 0:
        result = ['0']
    else:
        while integer_part > 0:
            remainder = integer_part % base
            integer_part = integer_part // base

            # Handle negative remainders
            if remainder < 0:
                remainder += base
                integer_part += 1

            # Convert remainder to digit
            if remainder >= 10:
                digit = chr(ord('A') + int(remainder) - 10)
            else:
                digit = str(int(remainder))
            result.append(digit)

    # Reverse to get correct order
    result.reverse()

    # Handle fractional part
    fractional_part = number - int(number)
    if decimals > 0:
        decimal_result = []
        for _ in range(decimals):
            fractional_part *= base
            digit_value = int(fractional_part)

            # Handle negative digits
            if digit_value < 0:
                digit_value += base
                fractional_part += base

            if digit_value >= 10:
                digit = chr(ord('A') + digit_value - 10)
            else:
                digit = str(digit_value)
            decimal_result.append(digit)
            fractional_part -= digit_value

        if decimal_result:
            result.append('.')
            result.extend(decimal_result)

    # Join the result
    final_result = ''.join(result)

    # Add negative sign if needed
    if negative and final_result != '0':
        final_result = '-' + final_result

    # Ensure leading zero for numbers < 1
    if '.' in final_result and final_result.startswith('0.'):
        pass  # Already correct
    elif '.' in final_result and not final_result.startswith('0.'):
        # Check if we need to add leading zero
        integer_part_str = final_result.split('.')[0]
        if integer_part_str == '':
            final_result = '0' + final_result

    return final_result

