def is_balanced(s, pairs):
    if not s or not pairs:
        return True

    # Parse pairs into openers and closers
    openers = pairs[::2]
    closers = pairs[1::2]

    # Create mapping for distinct pairs
    pair_map = {}
    # Set for characters that are both openers and closers
    self_balancing = set()

    for i, (opener, closer) in enumerate(zip(openers, closers)):
        if opener == closer:
            self_balancing.add(opener)
        else:
            pair_map[opener] = closer

    # Initialize tracking structures
    stack = []
    counters = {char: 0 for char in self_balancing}

    for char in s:
        if char in pair_map:
            # Distinct pair: opener
            if char in pair_map:
                stack.append(char)
        elif char in self_balancing:
            # Self-balancing pair
            counters[char] += 1
        elif char in closers:
            # Closing character
            if char in pair_map.values():
                # It's a closer from distinct pair
                if not stack:
                    return False
                opener = stack.pop()
                if pair_map[opener] != char:
                    return False
            elif char in self_balancing:
                # It's a closer from self-balancing pair
                counters[char] -= 1
                if counters[char] < 0:
                    return False

    # Check if all counters are zero for self-balancing pairs
    for count in counters.values():
        if count != 0:
            return False

    # Check if stack is empty for distinct pairs
    return len(stack) == 0

