def proper_fractions(d):
    if d == 1:
        return 0

    result = d

    # Handle factor of 2
    if d % 2 == 0:
        result = result - result // 2
        while d % 2 == 0:
            d //= 2

    # Handle odd factors from 3 to sqrt(d)
    i = 3
    while i * i <= d:
        if d % i == 0:
            result = result - result // i
            while d % i == 0:
                d //= i
        i += 2

    # If d is still greater than 1, it's a prime factor
    if d > 1:
        result = result - result // d

    return result

