    fractional_str = []

    if decimals > 0:
        fractional_str.append('.')
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            if digit < 10:
                fractional_str.append(str(digit))
            else:
                fractional_str.append(chr(ord('A') + digit - 10))
            fractional_part -= digit

    # Combine parts
    if decimals == 0:
        final_result = integer_str
    else:
        final_result = integer_str + ''.join(fractional_str)

    # Handle negative numbers
    if negative:
        final_result = '-' + final_result

    return final_result

def order_by_points(nums):
