    # Create list of (digit_sum, original_index, value) tuples
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Return just the values
    return [num for digit_sum_val, index, num in indexed_nums]

def amazon_check_mate(king, amazon):
    def parse_pos(pos):
        col = ord(pos[0]) - ord('a')
        row = int(pos[1]) - 1
        return (col, row)

    wk = parse_pos(king)  # white king
    wa = parse_pos(amazon)  # white amazon

    def attacked_by_amazon(sq, amazon_pos):
        ac, ar = amazon_pos
        bc, br = sq

        # Queen moves (rook + bishop)
        if ac == bc or ar == br:
            return True
        if abs(ac - bc) == abs(ar - br):
            return True

        # Knight moves (L-shaped)
        knight_deltas = [(1, 2), (2, 1), (2, -1), (1, -2), 
                        (-1, -2), (-2, -1), (-2, 1), (-1, 2)]
        for dc, dr in knight_deltas:
            if (ac + dc, ar + dr) == sq:
                return True

        return False

    def kings_adjacent(k1, k2):
        return max(abs(k1[0] - k2[0]), abs(k1[1] - k2[1])) == 1

    def get_valid_moves(square, wk_pos, wa_pos):
        moves = []
        for dc in [-1, 0, 1]:
            for dr in [-1, 0, 1]:
                if dc == 0 and dr == 0:
                    continue
                new_sq = (square[0] + dc, square[1] + dr)
                if 0 <= new_sq[0] <= 7 and 0 <= new_sq[1] <= 7:
                    if not kings_adjacent(new_sq, wk_pos):
                        if not attacked_by_amazon(new_sq, wa_pos):
                            moves.append(new_sq)
        return moves

    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    for c in range(8):
        for r in range(8):
            sq = (c, r)

            # Skip occupied squares
            if sq == wk or sq == wa:
                continue

            # Skip if adjacent to white king (kings can't be adjacent)
            if kings_adjacent(sq, wk):
                continue

            in_check = attacked_by_amazon(sq, wa)
            valid_moves = get_valid_moves(sq, wk, wa)

            if in_check:
                if len(valid_moves) == 0:
                    checkmate += 1
                else:
                    check += 1
            else:
                if len(valid_moves) == 0:
                    stalemate += 1
                else:
                    safe += 1

    return [checkmate, check, stalemate, safe]

def string_xor(s: str, t: str) -> str:
    """
    Returns the bitwise XOR of two binary strings of equal length.

    Args:
        s (str): First binary string.
        t (str): Second binary string.

    Returns:
        str: Binary string resulting from XOR operation.
    """
    if len(s) != len(t):
        raise ValueError("Input strings must be of equal length.")

    result = []
    for char_s, char_t in zip(s, t):
        if char_s == char_t:
            result.append('0')
        else:
            result.append('1')

    return ''.join(result)

def valid_mersenne(n):
    if n <= 1:
        return False

    if n == 2:
        return True

    # n must be prime for 2^n - 1 to potentially be a Mersenne prime
    if n % 2 == 0:
        return False

    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2

    # Lucas-Lehmer primality test for Mersenne numbers M_n = 2^n - 1
    mersenne = pow(2, n) - 1
    s = 4
    for _ in range(n - 2):
        s = (s * s - 2) % mersenne

    return s == 0

