def even_odd_palindrome(k: int) -> list:
    def is_palindrome(n: int) -> bool:
        s = str(n)
        return s == s[::-1]

    even_count = 0
    odd_count = 0
    num = 0

    while even_count < k or odd_count < k:
        num += 1
        if is_palindrome(num):
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return [num, num]  # [max_even_palindrome, max_odd_palindrome] both are num

