def amazon_check_mate(board):
    # Find the white king position
    white_king = None
    for r in range(8):
        for c in range(8):
            if board[r][c] == 'K':
                white_king = (r, c)
                break
        if white_king:
            break

    if not white_king:
        return False  # No white king, not a checkmate

    # Directions for all pieces
    knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
    rook_moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    bishop_moves = [(1, 1), (1, -1), (-1, 1), (-1, -1)]

    # Check if the white king is under attack
    def is_under_attack(kr, kc):
        # Check all enemy pieces
        for r in range(8):
            for c in range(8):
                piece = board[r][c]
                if piece not in 'nbrq':  # Only black pieces
                    continue

                dr, dc = kr - r, kc - c

                # Knight
                if piece == 'n' and (dr, dc) in knight_moves:
                    return True

                # Rook
                if piece == 'r':
                    if dr == 0 and abs(dc) <= 7:
                        # Horizontal
                        if check_path_clear(r, c, kr, kc):
                            return True
                    elif dc == 0 and abs(dr) <= 7:
                        # Vertical
                        if check_path_clear(r, c, kr, kc):
                            return True

                # Bishop
                if piece == 'b':
                    if abs(dr) == abs(dc) and abs(dr) <= 7:
                        if check_path_clear(r, c, kr, kc):
                            return True

                # Queen
                if piece == 'q':
                    if dr == 0 or dc == 0:
                        if check_path_clear(r, c, kr, kc):
                            return True
                    if abs(dr) == abs(dc):
                        if check_path_clear(r, c, kr, kc):
                            return True

                # King
                if piece == 'k':
                    if abs(dr) <= 1 and abs(dc) <= 1 and (dr != 0 or dc != 0):
                        return True

        return False

    def check_path_clear(r1, c1, r2, c2):
        dr = 0 if r2 == r1 else (1 if r2 > r1 else -1)
        dc = 0 if c2 == c1 else (1 if c2 > c1 else -1)
        r, c = r1 + dr, c1 + dc
        while (r, c) != (r2, c2):
            if board[r][c] != '.':
                return False
            r += dr
            c += dc
        return True

    # If king is not under attack, it's not checkmate
    if not is_under_attack(white_king[0], white_king[1]):
        return False

    # Get all possible moves for the white king
    king_moves = []
    kr, kc = white_king
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = kr + dr, kc + dc
            if 0 <= nr < 8 and 0 <= nc < 8:
                king_moves.append((nr, nc))

    # Check if any move escapes the check
    for nr, nc in king_moves:
        # Check if the square is occupied by white piece
        if board[nr][nc] in 'KQRNBP':
            continue
        # Check if moving there would still be under attack
        if not is_under_attack_after_move(kr, kc, nr, nc):
            return False

    return True

def is_under_attack_after_move(old_r, old_c, new_r, new_c):
    # Temporarily move the king
    original_board = board
    board_temp = [row[:] for row in board]  # Create a copy
    board_temp[old_r][old_c] = '.'
    board_temp[new_r][new_c] = 'K'

    # Use the global board replacement
    global board
    old_board = board
    board = board_temp

    result = is_under_attack(new_r, new_c)

    board = old_board  # Restore original board
    return result

