def greatest_common_divisor(a: int, b: int) -> int:
    # Handle edge cases
    if a == 0:
        return abs(b)
    if b == 0:
        return abs(a)

    # Use Euclidean algorithm
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

