def is_balanced(s, pairs):
    # Create a mapping from closing characters to opening characters
    closing_to_opening = {}
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        closing_to_opening[closing] = opening

    # Stack to keep track of opening characters
    stack = []

    for char in s:
        # If character is an opening character
        if char in pairs[::2]:  # Check if it's in the opening characters (even indices)
            stack.append(char)
        # If character is a closing character
        elif char in closing_to_opening:
            # If stack is empty or the top element doesn't match, it's unbalanced
            if not stack or stack[-1] != closing_to_opening[char]:
                return False
            stack.pop()

    # If stack is empty, all characters were properly matched
    return len(stack) == 0

def amazon_check_mate(king, amazon):
    # Parse chess notation to (row, col)
    def parse_pos(pos):
        col = ord(pos[0]) - ord('a')
        row = int(pos[1]) - 1
        return (row, col)

    # White pieces positions
    wk = parse_pos(king)
    wz = parse_pos(amazon)

    # Generate all squares threatened by amazon (queen + knight moves)
    def get_amazon_threats(pos):
        threats = set()
        r, c = pos

        # Queen moves (horizontal, vertical, diagonal)
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r, c
                while True:
                    nr += dr
                    nc += dc
                    if 0 <= nr < 8 and 0 <= nc < 8:
                        threats.add((nr, nc))
                    else:
                        break

        # Knight moves (L-shaped)
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
                       (1, -2), (1, 2), (2, -1), (2, 1)]
        for dr, dc in knight_moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 8 and 0 <= nc < 8:
                threats.add((nr, nc))

        return threats

    amazon_threats = get_amazon_threats(wz)

    # Check if a square is adjacent to white king (kings cannot be adjacent)
    def is_adjacent_to_wk(pos):
        r, c = pos
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if (nr, nc) == wk:
                    return True
        return False

    # Check if black king at pos has at least one legal move to a safe square
    def has_legal_move(pos):
        r, c = pos
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < 8 and 0 <= nc < 8:
                    target = (nr, nc)
                    # Cannot move to occupied squares
                    if target == wk or target == wz:
                        continue
                    # Cannot move adjacent to white king
                    if is_adjacent_to_wk(target):
                        continue
                    # Cannot move to amazon-threatened squares
                    if target in amazon_threats:
                        continue
                    # This is a valid legal move
                    return True
        return False

    # Count scenarios for each possible black king position
    checkmate = 0
    check = 0
    stalemate = 0
    normal = 0

    for r in range(8):
        for c in range(8):
            pos = (r, c)

            # Skip squares occupied by white pieces
            if pos == wk or pos == wz:
                continue

            # Skip squares adjacent to white king
            if is_adjacent_to_wk(pos):
                continue

            # Determine if under attack by amazon
            under_attack = pos in amazon_threats

            # Determine if black king has at least one legal move
            can_move = has_legal_move(pos)

            if under_attack and not can_move:
                checkmate += 1
            elif under_attack and can_move:
                check += 1
            elif not under_attack and not can_move:
                stalemate += 1
            else:
                normal += 1

    return [checkmate, check, stalemate, normal]

def parse_int(s):
    # Define word to number mappings
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14, 'fifteen': 15,
        'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19,
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50, 'sixty': 60,
        'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    # Split the string into words and remove 'and'
    words = s.replace(' and ', ' ').split()

    # Handle special case of zero
    if len(words) == 1 and words[0] == 'zero':
        return 0

    total = 0
    current = 0

    for word in words:
        if word in word_to_num:
            current += word_to_num[word]
        elif word == 'hundred':
            current *= 100
        elif word == 'thousand':
            total += current * 1000
            current = 0
        elif word == 'million':
            total += current * 1000000
            current = 0

    return total + current

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part to the given base
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            # Handle floating point precision issues
            if remainder >= base - 1e-10:
                remainder = 0
                temp = temp // base - 1
            else:
                temp = temp // base
            integer_digits.append(remainder)

    # Reverse to get the correct order
    integer_digits.reverse()

    # Convert fractional part to the given base
    fractional_digits = []
    if decimals > 0:
        temp_fractional = fractional_part
        for _ in range(decimals):
            temp_fractional *= base
            digit = int(temp_fractional)
            fractional_digits.append(digit)
            temp_fractional -= digit

    # Convert digits to characters
    def digit_to_char(digit):
        if digit < 10:
            return str(digit)
        else:
            return chr(ord('A') + digit - 10)

    # Build integer part string
    if not integer_digits:
        integer_str = '0'
    else:
        integer_str = ''.join(digit_to_char(d) for d in integer_digits)

    # Build fractional part string
    if decimals == 0:
        fractional_str = ''
    else:
        fractional_str = ''.join(digit_to_char(d) for d in fractional_digits)

    # Combine parts
    if fractional_str:
        result = integer_str + '.' + fractional_str
    else:
        result = integer_str

    # Handle negative sign
    if negative:
        result = '-' + result

    # Handle leading zero for numbers less than 1
    if number < 1 and not negative:
        if '.' in result:
            result = '0' + result
        else:
            result = '0' + result

    return result

def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2
    n = d

    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1

    if n > 1:
        result -= result // n

    return result

def sum_of_squares(n):
    # Check if n is a perfect square (answer = 1)
    sqrt_n = int(n**0.5)
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n is sum of two squares (answer = 2)
    # Try all squares s where s < n, check if n - s is also a perfect square
    for i in range(1, sqrt_n + 1):
        j = n - i*i
        if j <= 0:
            break
        sqrt_j = int(j**0.5)
        if sqrt_j * sqrt_j == j:
            return 2

    # Check Legendre's three-square theorem condition
    # If n = 4^k * (8m + 7) for integers k, m >= 0, then answer = 4, else answer = 3
    temp = n
    while temp % 4 == 0:
        temp //= 4

    if temp % 8 == 7:
        return 4

    return 3

