        for term in terms:
            if term == '0':
                continue
            elif term == '1':
                total += 1
            elif term == '-1':
                total -= 1
            elif 'x^' in term:
                # Handle terms like "3*x^2"
                parts = term.split('*x^')
                coeff = int(parts[0])
                power = int(parts[1])
                total += coeff * (x_val ** power)
            elif 'x' in term:
                # Handle terms like "3*x" or "-2*x"
                parts = term.split('*x')
                if len(parts) == 2:
                    coeff = int(parts[0])
                    total += coeff * x_val
                else:
                    # It's just "x" or "-x"
                    if term == 'x':
                        total += 1
                    elif term == '-x':
                        total -= 1
            else:
                # Simple number
                total += int(term)
        return total

    # Let's do a cleaner implementation
    # Parse and differentiate properly
    def parse_and_differentiate(poly_str, x_val):
        # Remove spaces
