                current_term = poly_str[i]
            else:
                current_term += poly_str[i]
            i += 1

        if current_term:
            terms.append(current_term)

        # Differentiate each term
        derivative_terms = []

        for term in terms:
            if term == 'x':
                # x^1 -> 1*x^0 = 1
