            elif term == '-x^0':
                # -x^0 -> 0*x^-1 = 0
                derivative_terms.append('0')
            elif term.startswith('x^'):
                # x^n -> n*x^(n-1)
                n = int(term[2:])
                if n == 1:
                    derivative_terms.append('1')
                else:
                    derivative_terms.append(str(n) + '*x^' + str(n-1))
            elif term.startswith('-x^'):
                # -x^n -> -n*x^(n-1)
                n = int(term[4:])
                if n == 1:
                    derivative_terms.append('-1')
                else:
                    derivative_terms.append('-' + str(n) + '*x^' + str(n-1))
            elif 'x^' in term:
                # ax^n -> a*n*x^(n-1)
                parts = term.split('x^')
                a = parts[0]
                if a == '':
                    a = '1'
                elif a == '-':
                    a = '-1'
                else:
