            elif term == 'x':
                # x^1 -> 1*x^0 = 1
                derivative_terms.append('1')
            elif term == '-x':
                # -x^1 -> -1*x^0 = -1
                derivative_terms.append('-1')
            elif 'x' in term:
                # ax -> a (constant)
                a = term[:-1]
                if a == '':
                    a = '1'
                elif a == '-':
                    a = '-1'
                derivative_terms.append(a)
            else:
                # Constant term -> 0
                derivative_terms.append('0')

        # Evaluate the derivative at x_val
        result = 0
        for term in derivative_terms:
            if term == '0':
                continue
            elif term == '1':
                result += 1
            elif term == '-1':
                result -= 1
            elif '*' in term and 'x^' in term:
                # Handle terms like "3*x^2"
