import math

def sum_of_squares(n):
    # Check if n is a perfect square
    sqrt_n = int(math.sqrt(n))
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n can be represented as sum of two squares
    # Using the fact that a number is sum of two squares if and only if
    # in its prime factorization, every prime of the form 4k+3 appears an even number of times
    def is_sum_of_two_squares(num):
        # Factor out powers of 4
        while num % 4 == 0:
            num //= 4
        # Check if all prime factors of the form 4k+3 appear an even number of times
        i = 3
        while i * i <= num:
            count = 0
            while num % i == 0:
                num //= i
                count += 1
            if i % 4 == 3 and count % 2 == 1:
                return False
            i += 2
        if num % 4 == 3:
            return False
        return True

    if is_sum_of_two_squares(n):
        return 2

    # Check if n can be represented as sum of three squares
    # Legendre's three-square theorem: a natural number n can be represented as the sum of three squares
    # if and only if n is not of the form 4^a(8b+7) for integers a and b
    def is_sum_of_three_squares(num):
        # Remove factors of 4
        while num % 4 == 0:
            num //= 4
        # If num is of the form 8b+7, then it cannot be sum of three squares
        if num % 8 == 7:
            return False
        return True

    if is_sum_of_three_squares(n):
        return 3

    # If none of the above, it must be sum of four squares (Lagrange's theorem)
    return 4

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False

        # Check odd divisors up to sqrt(num)
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    if is_prime(n):
        return x
    else:
        return y

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    if is_prime(n):
        return x
    else:
        return y

def sum_of_a_beach(s):
    words = ["sand", "water", "fish", "sun"]
    s_lower = s.lower()
    count = 0

    for word in words:
        start = 0
        while True:
            pos = s_lower.find(word, start)
            if pos == -1:
