def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def is_valid(pos):
        return 0 <= pos[0] < 8 and 0 <= pos[1] < 8

    def is_adjacent(pos1, pos2):
        return abs(pos1[0] - pos2[0]) <= 1 and abs(pos1[1] - pos2[1]) <= 1

    def get_amazon_attacks(amazon_pos):
        attacks = set()
        # Queen moves (rook + bishop)
        # Horizontal and vertical
        for i in range(8):
            if i != amazon_pos[0]:
                attacks.add((i, amazon_pos[1]))
            if i != amazon_pos[1]:
                attacks.add((amazon_pos[0], i))

        # Diagonals
        for i in range(1, 8):
            if is_valid((amazon_pos[0] + i, amazon_pos[1] + i)):
                attacks.add((amazon_pos[0] + i, amazon_pos[1] + i))
            if is_valid((amazon_pos[0] + i, amazon_pos[1] - i)):
                attacks.add((amazon_pos[0] + i, amazon_pos[1] - i))
            if is_valid((amazon_pos[0] - i, amazon_pos[1] + i)):
                attacks.add((amazon_pos[0] - i, amazon_pos[1] + i))
            if is_valid((amazon_pos[0] - i, amazon_pos[1] - i)):
                attacks.add((amazon_pos[0] - i, amazon_pos[1] - i))

        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            new_pos = (amazon_pos[0] + dx, amazon_pos[1] + dy)
            if is_valid(new_pos):
                attacks.add(new_pos)

        return attacks

    def get_king_attacks(king_pos):
        attacks = set()
        for i in range(-1, 2):
            for j in range(-1, 2):
                if i == 0 and j == 0:
                    continue
                new_pos = (king_pos[0] + i, king_pos[1] + j)
                if is_valid(new_pos):
                    attacks.add(new_pos)
        return attacks

    king_pos = chess_to_coords(king)
    amazon_pos = chess_to_coords(amazon)

    # Get all squares attacked by the amazon
    amazon_attacks = get_amazon_attacks(amazon_pos)

    # Get all squares attacked by the white king
    king_attacks = get_king_attacks(king_pos)

    # Counters for the four situations
    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    # Check all possible black king positions
    for i in range(8):
        for j in range(8):
            black_king_pos = (i, j)

            # Skip if position is occupied by white king or amazon
            if black_king_pos == king_pos or black_king_pos == amazon_pos:
                continue

            # Skip if position is adjacent to white king
            if is_adjacent(black_king_pos, king_pos):
                continue

            # Check if black king is under attack by amazon
            is_under_attack = black_king_pos in amazon_attacks

            # Check if black king can make a valid move
            can_move = False
            for di in range(-1, 2):
                for dj in range(-1, 2):
                    if di == 0 and dj == 0:
                        continue
                    new_pos = (black_king_pos[0] + di, black_king_pos[1] + dj)

                    # Check if new position is valid
                    if not is_valid(new_pos):
                        continue

                    # Check if new position is occupied by white pieces
                    if new_pos == king_pos or new_pos == amazon_pos:
                        continue

                    # Check if new position is adjacent to white king
                    if is_adjacent(new_pos, king_pos):
                        continue

                    # Check if new position is under attack by amazon
                    if new_pos in amazon_attacks:
                        continue

                    # If we reach here, the move is valid
                    can_move = True
                    break
                if can_move:
                    break

            # Classify the position
            if is_under_attack:
                if not can_move:
                    checkmate += 1
                else:
                    check += 1
            else:
                if not can_move:
                    stalemate += 1
                else:
                    safe += 1

    return [checkmate, check, stalemate, safe]

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % int(base)
            integer_digits.append(remainder)
            temp = (temp - remainder) // int(base)
        integer_digits.reverse()

    # Convert fractional part
    fractional_digits = []
    if decimals > 0:
        temp_fractional = fractional_part
        for _ in range(decimals):
            temp_fractional *= base
            digit = int(temp_fractional)
            fractional_digits.append(digit)
            temp_fractional -= digit

    # Format result
    if not integer_digits:
        result = '0'
    else:
        result = ''.join(str(digit) for digit in integer_digits)

    if decimals > 0:
        result += '.'
        result += ''.join(str(digit) for digit in fractional_digits)

    # Handle negative sign
    if negative:
        result = '-' + result

    # Handle leading zero for numbers less than 1
    if number < 1 and not negative:
        if '.' not in result:
            result = '0.' + result
        else:
            # Find the position of decimal point
            dot_pos = result.index('.')
            if dot_pos == 0:
                result = '0' + result

    return result

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()
    n = int(lines[0])
    c = list(map(int, lines[1].split()))

    # dp[i][j] represents the minimum seconds to destroy substring from i to j (inclusive)
    dp = [[float('inf')] * n for _ in range(n)]

    # Base case: single gemstone requires 1 second
    for i in range(n):
        dp[i][i] = 1

    # Fill DP table for substrings of length 2
    for i in range(n - 1):
        if c[i] == c[i + 1]:
            dp[i][i + 1] = 1
        else:
            dp[i][i + 1] = 2

    # Fill DP table for substrings of length 3 to n
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            # Try all possible splits
            for k in range(i, j):
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

            # If the first and last gemstones have the same color,
            # we can remove them together with the inner substring
            if c[i] == c[j]:
                if i + 1 <= j - 1:
                    dp[i][j] = min(dp[i][j], dp[i + 1][j - 1])
                else:
                    dp[i][j] = min(dp[i][j], 1)

    print(dp[0][n - 1])

