def reverse_delete(s, c):
    # Remove all characters from s that appear in c
    result = ''.join(char for char in s if char not in c)

    # Check if the result is a palindrome (case-sensitive)
    is_palindrome = result == result[::-1]

    return (result, is_palindrome)

def string_xor(a, b):
    # Pad the shorter string with leading zeros to match lengths
    max_len = max(len(a), len(b))
    a = a.zfill(max_len)
    b = b.zfill(max_len)

    # Perform XOR operation bit by bit
    result = []
    for i in range(max_len):
        # XOR: same bits give '0', different bits give '1'
        if a[i] == b[i]:
            result.append('0')
        else:
            result.append('1')

    return ''.join(result)

def converter(number, decimals, base):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    result = []

    if integer_part == 0:
        result = ['0']
    else:
        while integer_part > 0:
            remainder = integer_part % base
            if remainder >= 10:
                result.append(chr(ord('A') + remainder - 10))
            else:
                result.append(str(remainder))
            integer_part //= base
        result.reverse()

    # Handle fractional part
    fractional_part = number - int(number)
    if decimals > 0:
        result.append('.')
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            if digit >= 10:
                result.append(chr(ord('A') + digit - 10))
            else:
                result.append(str(digit))
            fractional_part -= digit

    # Format the result
    final_result = ''.join(result)

    # Handle negative sign
    if negative:
        final_result = '-' + final_result

    # Ensure exactly one leading zero for fractional numbers < 1
    if '.' in final_result:
        integer_part_end = final_result.index('.')
        if integer_part_end == 1 and final_result[0] == '0':
            # Already correctly formatted
            pass
        elif integer_part_end == 0:
            # Need to add leading zero
            final_result = '0' + final_result

    return final_result

