def almost_everywhere_zero(n, k):
    s = str(n)
    n_len = len(s)

    # DP memoization: (pos, count, tight, started) -> result
    memo = {}

    def dp(pos, count, tight, started):
        # Base case: processed all digits
        if pos == n_len:
            # Valid number if we've started and have exactly k non-zero digits
            return 1 if started and count == k else 0

        state = (pos, count, tight, started)
        if state in memo:
            return memo[state]

        result = 0
        limit = int(s[pos]) if tight else 9

        for digit in range(limit + 1):
            new_tight = tight and (digit == limit)
            new_started = started or (digit > 0)

            # Count non-zero digit only if it's a non-zero digit AND we've started
            new_count = count + (1 if digit > 0 else 0)

            # Prune if count exceeds k
            if new_count <= k:
                result += dp(pos + 1, new_count, new_tight, new_started)

        memo[state] = result
        return result

    return dp(0, 0, True, False)

