            (1, 1), (1, -1), (-1, 1), (-1, -1)
        ]

        for dr, dc in directions:
            nr, nc = am_row + dr, am_col + dc
            while 0 <= nr < 8 and 0 <= nc < 8:
                if nr == r and nc == c:
                    return True
                if nr == wk_row and nc == wk_col:
                    break
                nr += dr
                nc += dc

        return False

    def count_valid_moves(r, c):
        count = 0
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < 8 and 0 <= nc < 8:
                    # Cannot be on white pieces
                    if (nr, nc) == (wk_row, wk_col) or (nr, nc) == (am_row, am_col):
                        continue
                    # Cannot be adjacent to white king
                    if is_adjacent_to_white_king(nr, nc):
                        continue
                    # Must not be threatened by amazon
                    if is_threatened_by_amazon(nr, nc):
                        continue
                    count += 1
        return count

    checkmate = 0
    check = 0
    stalemate = 0
    safe_with_moves = 0

    for r in range(8):
        for c in range(8):
            # Cannot be on white pieces
            if (r, c) == (wk_row, wk_col) or (r, c) == (am_row, am_col):
                continue
            # Cannot be adjacent to white king
            if is_adjacent_to_white_king(r, c):
                continue

            threatened = is_threatened_by_amazon(r, c)
            valid_moves = count_valid_moves(r, c)

            if threatened:
                if valid_moves == 0:
                    checkmate += 1
                else:
                    check += 1
            else:
                if valid_moves == 0:
                    stalemate += 1
                else:
                    safe_with_moves += 1

    return [checkmate, check, stalemate, safe_with_moves]

import sys
from math import factorial

def combination(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1
    return factorial(n) // (factorial(k) * factorial(n - k))

def probability_at_least_k_types(n, k):
    # Using inclusion-exclusion principle
    # P(at least k types) = 1 - P(less than k types)
    # P(less than k types) = sum_{i=0}^{k-1} (-1)^i * C(k, i) * ((k-i)/k)^n
    if n == 0:
        return 0.0

    prob = 0.0
    for i in range(k):
        sign = (-1) ** i
        comb = combination(k, i)
        prob += sign * comb * ((k - i) / k) ** n

    return 1.0 - prob

def solve(k, target_prob):
    # Binary search for minimum n
    left, right = 1, k * 10000  # Upper bound estimation

    while left < right:
        mid = (left + right) // 2
        prob = probability_at_least_k_types(mid, k)

        if prob >= target_prob:
            right = mid
        else:
            left = mid + 1

    return left

