def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    if not numbers:
        return (0, 1)

    total_sum = sum(numbers)

    product = 1
    for num in numbers:
        product *= num

    return (total_sum, product)

def valid_mersenne(n):
    if n <= 0:
        return False

    # Check if n is a power of 2 minus 1 (i.e., n = 2^k - 1)
    # This means n+1 must be a power of 2
    m = n + 1

    # Check if m is a power of 2
    # A number is a power of 2 if it has exactly one bit set
    if m <= 0:
        return False

    # Bitwise check: m & (m-1) should be 0 for power of 2
    if m & (m - 1) != 0:
        return False

    # Now check if the exponent (k) is prime
    # m = 2^k, so k = log2(m)
    k = 0
    temp = m
    while temp > 1:
        temp >>= 1
        k += 1

    # Check if k is prime
    if k <= 1:
        return False
    if k == 2:
        return True
    if k % 2 == 0:
        return False

    i = 3
    while i * i <= k:
        if k % i == 0:
            return False
        i += 2

    return True

