from functools import lru_cache

def almost_everywhere_zero(n, k):
    s = str(n)
    digits = [int(d) for d in s]
    n_len = len(digits)

    @lru_cache(maxsize=None)
    def dp(pos, count, tight, started):
        if pos == n_len:
            return 1 if (started and count == k) else 0

        limit = digits[pos] if tight else 9
        result = 0

        for d in range(limit + 1):
            new_tight = tight and (d == limit)
            new_started = started or (d > 0)
            new_count = count + (1 if d > 0 else 0)

            if new_count <= k:
                result += dp(pos + 1, new_count, new_tight, new_started)

        return result

    return dp(0, 0, True, False)

def poohbear(code):
    memory = {}
    pointer = 0
    copy_register = 0
    program_counter = 0

    w_map = {}
    e_map = {}

    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                w_index = stack.pop()
                w_map[w_index] = i + 1
                e_map[i] = w_index

    output = []

    while program_counter < len(code):
        cmd = code[program_counter]
        jumped = False

        if cmd == 'N':
            pointer += 1
        elif cmd == 'B':
            pointer -= 1
        elif cmd == 'I':
            memory[pointer] = (memory.get(pointer, 0) + 1) % 256
        elif cmd == 'Y':
            memory[pointer] = (memory.get(pointer, 0) - 1) % 256
        elif cmd == 'W':
            if memory.get(pointer, 0) == 0:
                if program_counter in w_map:
                    program_counter = w_map[program_counter]
                    jumped = True
        elif cmd == 'E':
            if program_counter in e_map:
                program_counter = e_map[program_counter]
                jumped = True
        elif cmd == 'Q':
            output.append(chr(memory.get(pointer, 0)))
        elif cmd == 'P':
            current = memory.get(pointer, 0)
            next_cell = memory.get(pointer + 1, 0)
            memory[pointer] = (current + next_cell) % 256
        elif cmd == 'A':
            current = memory.get(pointer, 0)
            next_cell = memory.get(pointer + 1, 0)
            memory[pointer] = (current - next_cell) % 256
        elif cmd == 'T':
            copy_register = memory.get(pointer, 0)
        elif cmd == 'C':
            memory[pointer] = copy_register % 256
        elif cmd == 'M':
            current = memory.get(pointer, 0)
            memory[pointer] = (current * copy_register) % 256
        elif cmd == 'D':
            current = memory.get(pointer, 0)
            if copy_register != 0:
                memory[pointer] = int(current / copy_register) % 256
        elif cmd == 'R':
            current = memory.get(pointer, 0)
            memory[pointer] = int(current ** 0.5) % 256
        elif cmd == 'S':
            current = memory.get(pointer, 0)
            memory[pointer] = copy_register
            copy_register = current
        elif cmd == 'X':
            break
        else:
            pass

        if not jumped:
            program_counter += 1

    return ''.join(output)

