def getAllPrimeFactors(n):
    # Error handling
    if not isinstance(n, int) or not isinstance(n, (int, float)) or n <= 0:
        return []

    if n == 1:
        return [1]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Error handling
    if not isinstance(n, int) or not isinstance(n, (int, float)) or n <= 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)
    unique_factors = []
    counts = []

    if not factors:
        return [[], []]

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Error handling
    if not isinstance(n, int) or not isinstance(n, (int, float)) or n <= 0:
        return []

    if n == 1:
        return [1]

    factor_counts = getUniquePrimeFactorsWithCount(n)
    unique_factors = factor_counts[0]
    counts = factor_counts[1]

    products = []
    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

def encrypt(s):
    """Create a function encrypt that takes a string as an argument and
    returns a string encrypted with the alphabet being rotated. 
    The alphabet should be rotated in a manner such that the letters 
    shift down by two multiplied to two places.
    For example:
    encrypt('hi') returns 'lm'
    encrypt('asdfghjkl') returns 'ewhjklnop'
    encrypt('gf') returns 'kj'
    encrypt('et') returns 'ix'
    """
    result = []
    for char in s:
        if char.isalpha():
            if char.islower():
                base = ord('a')
            else:
                base = ord('A')
            shifted = chr((ord(char) - base + 4) % 26 + base)
            result.append(shifted)
        else:
            result.append(char)
    return ''.join(result)

