def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2
    temp = d

    # Find all unique prime factors and apply Euler's totient formula
    while p * p <= temp:
        if temp % p == 0:
            result = result - result // p
            while temp % p == 0:
                temp //= p
        p += 1

    # If temp > 1, it's a prime factor
    if temp > 1:
        result = result - result // temp

    return result

def exchange_sort(lst):
    """
    Sorts a list in ascending order using the Exchange Sort algorithm (similar to Bubble Sort).
    This function modifies the list in-place and returns it.
    """
    n = len(lst)
    for i in range(n):
        for j in range(0, n - i - 1):
            if lst[j] > lst[j + 1]:
                # Swap elements
                lst[j], lst[j + 1] = lst[j + 1], lst[j]
    return lst

def poohbear(code):
    # Preprocess to find matching W and E
    loop_map = {}
    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                start = stack.pop()
                loop_map[start] = i
                loop_map[i] = start

    # Initialize memory, pointer, clipboard, and output
    memory = {}
    pointer = 0
    clipboard = 0
    output = []
    ip = 0

    # Wrapping function
    def wrap(x):
        return (x % 256 + 256) % 256

    # Main execution loop
    while ip < len(code):
        char = code[ip]

        if char == '+':
            memory[pointer] = wrap(memory.get(pointer, 0) + 1)
        elif char == '-':
            memory[pointer] = wrap(memory.get(pointer, 0) - 1)
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            clipboard = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = clipboard
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                ip = loop_map[ip]
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                ip = loop_map[ip]
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif char == 'T':
            memory[pointer] = wrap(memory.get(pointer, 0) * 2)
        elif char == 'Q':
            memory[pointer] = wrap(memory.get(pointer, 0) ** 2)
        elif char == 'U':
            val = memory.get(pointer, 0)
            # Floor of square root
            if val >= 0:
                memory[pointer] = int(val ** 0.5)
            else:
                memory[pointer] = 0
        elif char == 'L':
            memory[pointer] = wrap(memory.get(pointer, 0) + 2)
        elif char == 'I':
            memory[pointer] = wrap(memory.get(pointer, 0) - 2)
        elif char == 'V':
            val = memory.get(pointer, 0)
            memory[pointer] = wrap(val // 2)
        elif char == 'A':
            val = memory.get(pointer, 0)
            memory[pointer] = wrap(val + clipboard)
        elif char == 'B':
            val = memory.get(pointer, 0)
            memory[pointer] = wrap(val - clipboard)
        elif char == 'Y':
            val = memory.get(pointer, 0)
            memory[pointer] = wrap(val * clipboard)
        elif char == 'D':
            val = memory.get(pointer, 0)
            if clipboard != 0:
                memory[pointer] = wrap(val // clipboard)
            else:
                memory[pointer] = 0

        ip += 1

    return ''.join(output)

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    return sorted(nums, key=digit_sum)

def count_up_to(n):
    if n <= 2:
        return []

    # Sieve of Eratosthenes
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n, i):
                is_prime[j] = False

    return [i for i in range(2, n) if is_prime[i]]

