def solution(text, comment_markers):
    if not text:
        return ""

    lines = text.split('\n')
    result_lines = []

    for line in lines:
        # Initialize min_index to the end of the line (no comment found)
        min_index = len(line)

        # Find the first occurrence of any comment marker
        for marker in comment_markers:
            index = line.find(marker)
            if index != -1 and index < min_index:
                min_index = index

        # Extract the line up to (but not including) the first comment marker
        processed_line = line[:min_index]

        # Strip trailing whitespace
        processed_line = processed_line.rstrip()

        result_lines.append(processed_line)

    return '\n'.join(result_lines)

def count_divisors(n):
    if n == 0:
        return 0

    sqrt_n = int(n ** 0.5)

    # Calculate sum of floor(n/i) for i from 1 to sqrt_n
    total = 0
    for i in range(1, sqrt_n + 1):
        total += n // i

    # Apply the formula: 2 * sum - sqrt_n^2
    return 2 * total - sqrt_n * sqrt_n

def differentiate(poly, x_val):
    # Insert spaces around + and - (except at start) to separate terms
    processed = poly
    for i in range(1, len(poly)):
        if poly[i] in '+-':
            processed = processed[:i] + ' ' + poly[i] + processed[i+1:]

    # Split into terms
    terms = processed.split()

    result = 0

    for term in terms:
        # Check if term has x
        has_x = 'x' in term

        if has_x:
            # Split at x to get coefficient and potential exponent
            x_pos = term.index('x')
            coeff_str = term[:x_pos]
            rest = term[x_pos+1:]

            # Parse coefficient
            if coeff_str == '' or coeff_str == '+':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)

            # Parse exponent
            if '^' in rest:
                exp_str = rest.split('^')[1]
                exponent = int(exp_str)
            else:
                exponent = 1
        else:
            # Constant term (exponent 0, derivative is 0)
            coeff = int(term)
            exponent = 0

        # Power rule: d/dx(coeff * x^exponent) = coeff * exponent * x^(exponent-1)
        if exponent == 0:
            continue  # derivative of constant is 0
        elif exponent == 1:
            result += coeff
        else:
            result += coeff * exponent * (x_val ** (exponent - 1))

    return result

