def exchange_sort(sequence):
    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for val in sequence:
        count[val] += 1

    # Create target sorted sequence
    target = []
    for val in [7, 8, 9]:
        target.extend([val] * count[val])

    # Create position mapping for target
    target_positions = {7: [], 8: [], 9: []}
    for i, val in enumerate(target):
        target_positions[val].append(i)

    # Create current positions mapping
    current_positions = {7: [], 8: [], 9: []}
    for i, val in enumerate(sequence):
        current_positions[val].append(i)

    # Create permutation mapping: where each element should go
    perm = [0] * len(sequence)
    for val in [7, 8, 9]:
        target_idx = 0
        for current_idx in current_positions[val]:
            perm[current_idx] = target_positions[val][target_idx]
            target_idx += 1

    # Find cycles in permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i] and perm[i] != i:
            # Start a new cycle
            cycles += 1
            current = i
            while not visited[current]:
                visited[current] = True
                current = perm[current]

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

