def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # For 2^n - 1 to be a Mersenne prime, n must be prime
    if not is_prime(n):
        return False

    # Check if 2^n - 1 is prime
    mersenne = (1 << n) - 1  # This is 2^n - 1

    # For large numbers, we use a more efficient primality test
    # Simple trial division for smaller numbers
    if mersenne < 1000000:
        # For numbers up to about 1 million, simple trial division is fine
        if mersenne < 2:
            return False
        if mersenne == 2:
            return True
        if mersenne % 2 == 0:
            return False
        for i in range(3, int(mersenne**0.5) + 1, 2):
            if mersenne % i == 0:
                return False
        return True

    # For larger numbers, we use a more sophisticated approach
    # But given the constraint (n up to 2000), 2^n - 1 can be very large
    # Let's use a known list of Mersenne primes for efficiency
    # Mersenne primes are 2^p - 1 where p is prime and 2^p - 1 is prime
    # Known Mersenne primes for small exponents
    known_mersenne_primes = {
        2, 3, 5, 7, 13, 17, 19, 31, 61, 89, 107, 127, 521, 607, 1279, 2203, 2281, 3217, 4253, 4423, 9689, 9941, 11213, 19937, 21701, 23209, 44497, 86243, 110503, 132049, 216091, 756839, 859433, 1257787, 1398269, 2976221, 3021377, 6972593, 13466917, 20996011, 24036583, 25964951, 30402457, 32582657, 37156667, 42643801, 43112609, 57885161, 74207281, 77232917, 82589933
    }

    return n in known_mersenne_primes

