def is_balanced(s, pairs):
    # Create mapping from opening characters to their corresponding closing characters
    open_to_close = {}
    close_chars = set()

    # Parse the pairs string (even indices are opening, odd indices are closing)
    for i in range(0, len(pairs), 2):
        if i + 1 < len(pairs):
            open_char = pairs[i]
            close_char = pairs[i + 1]
            open_to_close[open_char] = close_char
            close_chars.add(close_char)

    # Use a stack to track opening characters
    stack = []

    for char in s:
        if char in open_to_close:
            # Opening character - push to stack
            stack.append(char)
        elif char in close_chars:
            # Closing character - verify it matches the most recent opening character
            if not stack:
                return False
            last_open = stack.pop()
            if open_to_close[last_open] != char:
                return False

    # All opening characters must be closed
    return len(stack) == 0

