    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14, 'fifteen': 15,
        'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19, 'twenty': 20,
        'thirty': 30, 'forty': 40, 'fifty': 50, 'sixty': 60, 'seventy': 70,
        'eighty': 80, 'ninety': 90
    }

    # Split the string into words and remove 'and'
    words = s.replace(' and ', ' ').split()

    # Handle special case of zero
    if len(words) == 1 and words[0] == 'zero':
        return 0

    # Process the words
    result = 0
    current = 0

    for word in words:
        if word in word_to_num:
            current += word_to_num[word]
        elif word == 'hundred':
            current *= 100
        elif word == 'thousand':
            result += current * 1000
            current = 0
        elif word == 'million':
            result += current * 1000000
            current = 0

    result += current
    return result

