def exchange_sort(sequence):
    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for val in sequence:
        count[val] += 1

    # Determine the correct positions for each group
    # 7s should be in positions [0, count[7])
    # 8s should be in positions [count[7], count[7] + count[8])
    # 9s should be in positions [count[7] + count[8], len(sequence))

    # Create the target sequence
    target = []
    target.extend([7] * count[7])
    target.extend([8] * count[8])
    target.extend([9] * count[9])

    # Find mismatches
    mismatches = []
    for i in range(len(sequence)):
        if sequence[i] != target[i]:
            mismatches.append(i)

    # Count how many elements from each group are misplaced
    misplaced_7 = 0
    misplaced_8 = 0
    misplaced_9 = 0

    for i in mismatches:
        if sequence[i] == 7:
            misplaced_7 += 1
        elif sequence[i] == 8:
            misplaced_8 += 1
        elif sequence[i] == 9:
            misplaced_9 += 1

    # The minimum number of swaps is the maximum of misplaced counts
    # because each swap can fix two mismatches (one from each group)
    return max(misplaced_7, misplaced_8, misplaced_9)

def almost_everywhere_zero(n, k):
    s = str(n)
    n_digits = len(s)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, cnt, tight, started):
        if cnt > k:
            return 0
        if pos == n_digits:
            return 1 if cnt == k and started else 0

        limit = int(s[pos]) if tight else 9
        result = 0

        for digit in range(limit + 1):
            new_tight = tight and (digit == limit)
            new_started = started or (digit > 0)
            new_cnt = cnt + (1 if new_started and digit > 0 else 0)

            result += dp(pos + 1, new_cnt, new_tight, new_started)

        return result

    return dp(0, 0, True, False)

