    integer palindromes that fall within the range(1, n), inclusive.
    """
    even_count = 0
    odd_count = 0

    for num in range(1, n + 1):
        # Check if num is palindrome using mathematical reversal (no string conversion)
        original = num
        reversed_num = 0
        temp = num
        while temp > 0:
            digit = temp % 10
            reversed_num = reversed_num * 10 + digit
            temp //= 10

        # If palindrome, count as even or odd
        if original == reversed_num:
            if num % 2 == 0:
