            else:
                odd_count += 1

    return (even_count, odd_count)

def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2

    # Find all distinct prime factors and apply Euler's totient formula
    while p * p <= d:
        if d % p == 0:
            # p is a prime factor
            while d % p == 0:
                d //= p
            # Apply φ(d) = d × (p-1)/p for each prime factor p
            result -= result // p
        p += 1

    # If d > 1, then d itself is a prime factor
    if d > 1:
        result -= result // d

    return result

def getAllPrimeFactors(n):
    # Error handling
    if not isinstance(n, int) or not isinstance(n, (int, float)) or n <= 0:
        return []

    if n == 1:
        return [1]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Error handling
    if not isinstance(n, int) or not isinstance(n, (int, float)) or n <= 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)

    if not factors:
        return [[], []]

    unique_factors = []
    counts = []

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Error handling
    if not isinstance(n, int) or not isinstance(n, (int, float)) or n <= 0:
        return []

