def get_closest_vowel(word):
    if len(word) < 3:
        return ""

    vowels = set('aeiouAEIOU')

    # Search from right to left, excluding first and last characters
    for i in range(len(word) - 2, 0, -1):
        # Check if current character is a vowel
        if word[i] in vowels:
            # Check if both neighbors are consonants
            if word[i-1] not in vowels and word[i+1] not in vowels:
                return word[i]

    return ""

def check_if_last_char_is_a_letter(txt):
    # Handle empty string
    if not txt:
        return False

    # Check if last character is alphabetical
    if not txt[-1].isalpha():
        return False

    # If string has only one character and it's alphabetical, return True
    if len(txt) == 1:
        return True

    # Check if the character before the last one is a space
    # This would mean the last character is not part of a word
    return txt[-2] == ' '

def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    result = []
    for char_a, char_b in zip(a, b):
        if char_a == char_b:
            result.append('0')
        else:
            result.append('1')
    return ''.join(result)

def converter(number, decimals=0, base=3.141592653589793):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    is_negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    result = []

    if integer_part == 0:
        result = ['0']
    else:
        while integer_part > 0:
            remainder = integer_part % int(base)
            result.append(get_digit(remainder))
            integer_part = integer_part // int(base)
        result.reverse()

    # Handle fractional part
    fractional_part = number - int(number)
    if decimals > 0:
        result.append('.')
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            result.append(get_digit(digit))
            fractional_part -= digit

    # Join the result
    final_result = ''.join(result)

    # Add negative sign if needed
    if is_negative:
        final_result = '-' + final_result

    return final_result

def get_digit(value):
    if value < 10:
        return str(value)
    else:
        return chr(ord('A') + value - 10)

def automorphic(n):
    square = n * n
    n_str = str(n)
    square_str = str(square)

    # Check if the square ends with the same digits as n
    if square_str.endswith(n_str):
        return "Automorphic"
    else:
        return "Not!!"

def reverse_delete(s, c):
    # Remove all characters from s that appear in c
    result = ''.join(char for char in s if char not in c)

    # Check if result is palindrome
    is_palindrome = result == result[::-1]

    return (result, is_palindrome)

import sys
from math import factorial, log, exp

def combination(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1
    return factorial(n) // (factorial(k) * factorial(n - k))

def calculate_probability(k, n):
    # Using inclusion-exclusion principle
    # P(all k types collected in n days) = sum_{i=0}^k (-1)^i * C(k,i) * ((k-i)/k)^n
    prob = 0.0
    for i in range(k + 1):
        sign = (-1) ** i
        comb = combination(k, i)
        prob += sign * comb * ((k - i) / k) ** n
    return prob

def find_min_days(k, p):
    # Binary search for minimum days
    left = k
    right = k * 1000000  # Upper bound estimate

    target = (p - 1e-10) / 2000.0

    while left < right:
        mid = (left + right) // 2
        prob = calculate_probability(k, mid)

        if prob >= target:
            right = mid
        else:
            left = mid + 1

    return left

