def converter(value, from_unit, to_unit):
    """
    Convert a value from one unit to another.
    Currently supports temperature conversions: C (Celsius), F (Fahrenheit), K (Kelvin).

    Args:
        value: Numeric value to convert
        from_unit: Source unit ('C', 'F', or 'K')
        to_unit: Target unit ('C', 'F', or 'K')

    Returns:
        Converted numeric value

    Raises:
        ValueError: If units are not supported
    """
    if from_unit == to_unit:
        return value

    if from_unit == 'C' and to_unit == 'F':
        return value * 9/5 + 32
    elif from_unit == 'F' and to_unit == 'C':
        return (value - 32) * 5/9
    elif from_unit == 'C' and to_unit == 'K':
        return value + 273.15
    elif from_unit == 'K' and to_unit == 'C':
        return value - 273.15
    elif from_unit == 'F' and to_unit == 'K':
        return (value - 32) * 5/9 + 273.15
    elif from_unit == 'K' and to_unit == 'F':
        return (value - 273.15) * 9/5 + 32
    else:
        raise ValueError("Unsupported unit conversion")

def poohbear(code):
    # Preprocess code to remove non-command characters
    commands = [c for c in code if c in "+-><cpWEPN-TQULIVABYD"]

    # Build jump map for W/E pairs
    jump_map = {}
    stack = []
    for i, cmd in enumerate(commands):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                start = stack.pop()
                jump_map[start] = i
                jump_map[i] = start

    # Initialize state
    cells = {}
    pointer = 0
    copied = 0
    ip = 0
    output = []

    while ip < len(commands):
        cmd = commands[ip]

        if cmd == '+':
            cells[pointer] = (cells.get(pointer, 0) + 1) % 256
        elif cmd == '-':
            cells[pointer] = (cells.get(pointer, 0) - 1) % 256
        elif cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == 'c':
            copied = cells.get(pointer, 0)
        elif cmd == 'p':
            cells[pointer] = copied
        elif cmd == 'W':
            if cells.get(pointer, 0) == 0:
                ip = jump_map[ip]
        elif cmd == 'E':
            if cells.get(pointer, 0) != 0:
                ip = jump_map[ip]
        elif cmd == 'P':
            output.append(chr(cells.get(pointer, 0)))
        elif cmd == 'N':
            output.append(str(cells.get(pointer, 0)))
        elif cmd == 'T':
            cells[pointer] = (cells.get(pointer, 0) * 2) % 256
        elif cmd == 'Q':
            cells[pointer] = (cells.get(pointer, 0) ** 2) % 256
        elif cmd == 'U':
            import math
            cells[pointer] = int(math.sqrt(cells.get(pointer, 0)))
        elif cmd == 'L':
            cells[pointer] = (cells.get(pointer, 0) + 2) % 256
        elif cmd == 'I':
            cells[pointer] = (cells.get(pointer, 0) - 2) % 256
        elif cmd == 'V':
            if copied != 0:
                cells[pointer] = (cells.get(pointer, 0) // copied) % 256
            else:
                cells[pointer] = 0
        elif cmd == 'A':
            cells[pointer] = (cells.get(pointer, 0) + copied) % 256
        elif cmd == 'B':
            cells[pointer] = (cells.get(pointer, 0) - copied) % 256
        elif cmd == 'Y':
            cells[pointer] = (cells.get(pointer, 0) * copied) % 256
        elif cmd == 'D':
            if copied != 0:
                cells[pointer] = (cells.get(pointer, 0) // copied) % 256
            else:
                cells[pointer] = 0

        ip += 1

    return ''.join(output)

def amazon_check_mate(king, amazon):
    def to_coords(pos):
        col = ord(pos[0]) - ord('a')
        row = int(pos[1]) - 1
        return (row, col)

    king_pos = to_coords(king)
    amazon_pos = to_coords(amazon)

    def amazon_attacks(pos):
        row, col = pos
        attacks = set()

        # Queen-like moves (horizontal, vertical, diagonal)
        for c in range(8):
            if c != col:
                attacks.add((row, c))
        for r in range(8):
            if r != row:
                attacks.add((r, col))

        # Diagonals in all four directions
        for dr, dc in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
            r, c = row + dr, col + dc
            while 0 <= r < 8 and 0 <= c < 8:
                attacks.add((r, c))
                r += dr
                c += dc

        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
                       (1, -2), (1, 2), (2, -1), (2, 1)]
        for dr, dc in knight_moves:
            r, c = row + dr, col + dc
            if 0 <= r < 8 and 0 <= c < 8:
                attacks.add((r, c))

        return attacks

    def adjacent_squares(pos):
        row, col = pos
        adj = set()
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                r, c = row + dr, col + dc
                if 0 <= r < 8 and 0 <= c < 8:
                    adj.add((r, c))
        return adj

    amazon_attacked = amazon_attacks(amazon_pos)
    king_forbidden = adjacent_squares(king_pos)
    king_forbidden.add(king_pos)

    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    for row in range(8):
        for col in range(8):
            pos = (row, col)

            # Skip if black king would be on same square as white king
            if pos == king_pos:
                continue

            # Skip if black king would be adjacent to white king
            if pos in king_forbidden:
                continue

            # Check if under amazon attack
            under_attack = pos in amazon_attacked

            # Check if black king can make a valid move (escape to safe square)
            can_escape = False
            for adj_pos in adjacent_squares(pos):
                # Escape square must be:
                # - On the board (already guaranteed by adjacent_squares)
                # - Not under amazon attack
                # - Not on white king's square
                # - Not adjacent to white king
                if adj_pos not in amazon_attacked and adj_pos not in king_forbidden:
                    can_escape = True
                    break

            if under_attack:
                if can_escape:
                    check += 1
                else:
                    checkmate += 1
            else:
                if can_escape:
                    safe += 1
                else:
                    stalemate += 1

    return [checkmate, check, stalemate, safe]

def sum_of_squares(n):
    def is_perfect_square(x):
        if x < 0:
            return False
        sqrt_x = int(x ** 0.5)
        return sqrt_x * sqrt_x == x

    # Step 1: Check if n is a perfect square (answer = 1)
    if is_perfect_square(n):
        return 1

    # Step 2: Check if n can be written as sum of 2 squares (answer = 2)
    for i in range(1, int(n ** 0.5) + 1):
        if is_perfect_square(n - i * i):
            return 2

    # Step 3: Apply Legendre's Three-Square Theorem
    # n can be written as sum of 3 squares iff n is NOT of form 4^a(8b + 7)
    temp = n
    while temp % 4 == 0:
        temp //= 4
    if temp % 8 == 7:
        return 4
    else:
        return 3

