    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result -= result // i
            while n % i == 0:
                n //= i
        i += 2

    # If n is a prime factor greater than 2
    if n > 1:
        result -= result // n

    return result

def decode_shift(s: str):
