import re
from collections import defaultdict

def simplify(expression: str) -> str:
    # Parse the expression into terms with their signs
    # Each term is represented as (sign, coefficient, variables)
    terms = re.findall(r'([+-]?)(\d*)([a-z]+)', expression)

    # Dictionary to store combined coefficients for each sorted variable string
    term_dict = defaultdict(int)

    for sign, coeff, vars in terms:
        # Determine the sign
        if sign == '-':
            sign_val = -1
        elif sign == '+':
            sign_val = 1
        else:
            sign_val = 1  # No sign means positive

        # Determine the coefficient
        if coeff == '':
            coef = 1
        else:
            coef = int(coeff)

        # Apply the sign to the coefficient
        coef = sign_val * coef

        # Sort the variables alphabetically (xy == yx)
        sorted_vars = ''.join(sorted(vars))

        # Add to the dictionary
        term_dict[sorted_vars] += coef

    # Filter out terms with zero coefficient
    term_dict = {k: v for k, v in term_dict.items() if v != 0}

    # Sort terms by number of variables, then lexicographically
    sorted_terms = sorted(term_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Format the output string
    result = []
    for vars, coef in sorted_terms:
        if coef == 1:
            term_str = vars
        elif coef == -1:
            term_str = '-' + vars
        else:
            term_str = str(coef) + vars

        if len(result) == 0:
            # First term: don't add + for positive
            result.append(term_str)
        else:
            # Subsequent terms: add + for positive, - is already included for negative
            if coef > 0 and not term_str.startswith('-'):
                result.append('+' + term_str)
            else:
                result.append(term_str)

    return ''.join(result)

def valid_mersenne(n):
    # Check if n is prime
    if n <= 1:
        return False

    # Simple primality check for n
    if n == 2:
        is_n_prime = True
    elif n % 2 == 0:
        is_n_prime = False
    else:
        is_n_prime = True
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                is_n_prime = False
                break

    if not is_n_prime:
        return False

    # If n is prime, check if 2^n - 1 is prime
    mersenne_number = (1 << n) - 1  # This is 2^n - 1

    # Miller-Rabin primality test
    def miller_rabin(n, k=5):
        if n < 2:
            return False
        if n == 2 or n == 3:
            return True
        if n % 2 == 0:
            return False

        # Write n-1 as d * 2^r
        r = 0
        d = n - 1
        while d % 2 == 0:
            d //= 2
            r += 1

        # Witness loop
        import random
        for _ in range(k):
            a = random.randrange(2, n - 1)
            x = pow(a, d, n)
            if x == 1 or x == n - 1:
                continue
            for _ in range(r - 1):
                x = pow(x, 2, n)
                if x == n - 1:
                    break
            else:
                return False
        return True

    return miller_rabin(mersenne_number)

def next_bigger(n):
    digits = [int(d) for d in str(n)]
    length = len(digits)

    if length <= 1:
        return -1

    pivot_idx = -1
    for i in range(length - 2, -1, -1):
        if digits[i] < digits[i + 1]:
            pivot_idx = i
            break

    if pivot_idx == -1:
        return -1

    swap_idx = -1
    for i in range(length - 1, pivot_idx, -1):
        if digits[i] > digits[pivot_idx]:
            swap_idx = i
            break

    digits[pivot_idx], digits[swap_idx] = digits[swap_idx], digits[pivot_idx]

    left, right = pivot_idx + 1, length - 1
    while left < right:
        digits[left], digits[right] = digits[right], digits[left]
        left += 1
        right -= 1

    return int(''.join(str(d) for d in digits))

