    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                arr[i], arr[j] = arr[j], arr[i]
    return arr

def solution(text, markers):
    lines = text.split('\n')
    result_lines = []

    for line in lines:
        marker_pos = len(line)  # Default: no marker found

        # Find the first occurrence of any marker
        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < marker_pos:
                marker_pos = pos

        # Truncate at the first marker position (if found)
        if marker_pos < len(line):
            line = line[:marker_pos]

        # Strip trailing whitespace
        line = line.rstrip()

        result_lines.append(line)

    return '\n'.join(result_lines)

def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2

    # Find all distinct prime factors and apply Euler's totient formula
    while p * p <= d:
        if d % p == 0:
            # p is a prime factor
            while d % p == 0:
                d //= p
            # Apply φ(d) = d × (p-1)/p for each prime factor p
            result -= result // p
        p += 1

    # If d > 1, then d itself is a prime factor
    if d > 1:
        result -= result // d

    return result

