    return sum(arr) - min(arr) - max(arr)

def compare(selector1, selector2):
    def get_specificity(selector):
        id_count = 0
        class_count = 0
        tag_count = 0

        # Split by whitespace to get individual tokens
        tokens = selector.split()

        for token in tokens:
            # Count IDs
            id_count += token.count('#')

            # Count classes (handle multiple classes in one token like ".a.b")
            class_count += token.count('.')

            # Count tags (elements that are not IDs or classes)
            if not token.startswith('#') and not token.startswith('.'):
                tag_count += 1
            else:
                # If token starts with # or ., we need to count the actual tag part
                # Find where the tag part starts (after # or .)
                if '#' in token:
                    # Extract tag part before first #
                    tag_part = token.split('#')[0]
                    if tag_part and tag_part.isalnum():
                        tag_count += 1
                elif '.' in token:
                    # Extract tag part before first .
                    tag_part = token.split('.')[0]
                    if tag_part and tag_part.isalnum():
                        tag_count += 1
                else:
                    # This shouldn't happen for valid CSS, but just in case
                    if token.isalnum():
                        tag_count += 1

        # Handle the case where we have tokens like "div#id.class" - we want to count the tag "div"
        # We need to reprocess tokens to properly count tags
        tag_count = 0
        for token in tokens:
            # Remove all # and . from the token to get the tag
            clean_token = ''.join(c for c in token if c not in '#.')
            # If there's something left and it's alphanumeric, it's a tag
            if clean_token and clean_token.isalnum():
                tag_count += 1

        return (id_count, class_count, tag_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    # Compare specificity
    if spec1 > spec2:
        return selector1
    else:
        return selector2

def cycpattern_check(a, b):
    # Handle edge cases
    if not b or not a:
        return False
    if len(b) > len(a):
        return False

    # Generate all unique rotations of b
    rotations = set()
    for i in range(len(b)):
        rotation = b[i:] + b[:i]
        rotations.add(rotation)

    # Check if any rotation is a substring of a
    for rotation in rotations:
        if rotation in a:
            return True

    return False

def cycpattern_check(a, b):
    # Handle edge cases
    if not b:
        return True
    if not a:
        return False
    if len(b) > len(a):
        return False
    if b == a:
        return True

    # Concatenate b with itself
    # All rotations of b will be substrings of b+b
    b_double = b + b

    # Check if any substring of length len(b) in b_double exists in a
    for i in range(len(b)):
        rotation = b_double[i:i+len(b)]
        if rotation in a:
            return True

    return False

def cycpattern_check(a, b):
    # Handle edge cases
    if not b:
        return True
    if not a:
        return False

    # If length of b is greater than a, b or its rotations cannot be substring of a
    if len(b) > len(a):
        return False

    # Create doubled string of b
    # All rotations of b will be substrings of b+b
    doubled_b = b + b

    # Check if any rotation of b (which are substrings of doubled_b) 
    # is present in a
    for i in range(len(b)):
        rotation = doubled_b[i:i+len(b)]
        if rotation in a:
            return True

    return False

def parse_selector(selector):
    """Parse a CSS selector and return specificity tuple (id_count, class_count, tag_count)"""
    id_count = 0
    class_count = 0
    tag_count = 0

    # Split by spaces to handle chain of selectors
    parts = selector.split()

    for part in parts:
        if part == '*':
            continue

        # Parse the part which may have combined selectors like div#id.class
        idx = 0
        while idx < len(part):
            char = part[idx]
            if char == '#':
                id_count += 1
                idx += 1
                # Skip the id name
                while idx < len(part) and part[idx] not in ['#', '.', ' ', '\t', '\n', '*']:
                    idx += 1
            elif char == '.':
                class_count += 1
                idx += 1
                # Skip the class name
                while idx < len(part) and part[idx] not in ['#', '.', ' ', '\t', '\n', '*']:
                    idx += 1
            elif char.isalpha() or char == '_' or char == '-':
                tag_count += 1
                # Skip the tag name
                while idx < len(part) and (part[idx].isalnum() or part[idx] == '_'):
                    idx += 1
            else:
                idx += 1

    return (id_count, class_count, tag_count)


def compare(selector1, selector2):
    """Compare two CSS selectors and return the one with higher specificity"""
    specificity1 = parse_selector(selector1)
    specificity2 = parse_selector(selector2)

    # Compare specificities: (id_count, class_count, tag_count)
    # More #id wins, then more .class, then more tagname
    if specificity1 > specificity2:
        return selector1
    elif specificity2 > specificity1:
        return selector2
    else:
        # If all values are same, the one that appears later wins
        return selector2

