def is_balanced(s, config):
    # Build opener to closer mapping from the configuration string
    # Each pair (index i, i+1) defines an opener and its corresponding closer
    opener_to_closer = {}
    for i in range(0, len(config), 2):
        opener_to_closer[config[i]] = config[i + 1]

    # Build closer to opener mapping for quick lookup
    closer_to_opener = {}
    for opener, closer in opener_to_closer.items():
        closer_to_opener[closer] = opener

    stack = []

    for char in s:
        if char in opener_to_closer:
            # This character can be an opener
            # Check if it could also be a closer for the top of stack (identical opener/closer case)
            if stack and opener_to_closer.get(stack[-1]) == char:
                # It's a closer for the top opener - pop it
                stack.pop()
            else:
                # It's an opener - push it
                stack.append(char)
        elif char in closer_to_opener:
            # This character is only a closer (not an opener)
            if not stack or opener_to_closer.get(stack[-1]) != char:
                return False
            stack.pop()
        # Characters not in config are ignored

    # Stack must be empty for balanced string
    return len(stack) == 0

import math

def sum_of_squares(n):
    # Check if n is a perfect square
    sqrt_n = int(math.sqrt(n))
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n can be represented as sum of two squares
    # Using the fact that a number is sum of two squares if and only if
    # in its prime factorization, every prime of the form 4k+3 appears an even number of times
    def is_sum_of_two_squares(num):
        # Factor out powers of 4
        while num % 4 == 0:
            num //= 4
        # Check if all prime factors of the form 4k+3 appear an even number of times
        i = 3
        while i * i <= num:
            count = 0
            while num % i == 0:
                num //= i
                count += 1
            if i % 4 == 3 and count % 2 == 1:
                return False
            i += 2
        if num % 4 == 3:
            return False
        return True

    if is_sum_of_two_squares(n):
        return 2

    # Check if n can be represented as sum of three squares
    # Legendre's three-square theorem: a natural number n can be represented as the sum of three squares
    # if and only if n is not of the form 4^a(8b+7) for integers a and b
    def is_sum_of_three_squares(num):
        # Remove factors of 4
        while num % 4 == 0:
            num //= 4
        # If num is of the form 8b+7, then it cannot be sum of three squares
        if num % 8 == 7:
            return False
        return True

    if is_sum_of_three_squares(n):
        return 3

    # If none of the above, it must be sum of four squares (Lagrange's theorem)
    return 4

