def choose(n, k):
    # Handle edge cases
    if k < 0 or k > n:
        return 0

    # Use symmetry property: C(n, k) = C(n, n-k)
    if k > n // 2:
        k = n - k

    # Base cases
    if k == 0 or k == n:
        return 1

    # Compute using multiplicative formula
    # C(n, k) = n * (n-1) * ... * (n-k+1) / (1 * 2 * ... * k)
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

