def sum_of_a_beach(s):
    s_lower = s.lower()
    words = ["sand", "water", "fish", "sun"]
    return sum(s_lower.count(word) for word in words)

def exchange_sort(lst):
    """
    Sorts a list in ascending order using the Exchange Sort algorithm (similar to Bubble Sort).
    This function modifies the list in-place and returns it.
    """
    n = len(lst)
    for i in range(n):
        for j in range(0, n - i - 1):
            if lst[j] > lst[j + 1]:
                # Swap elements
                lst[j], lst[j + 1] = lst[j + 1], lst[j]
    return lst

def next_smallest(nums):
    if not nums or len(nums) < 2:
        return None
    unique_nums = sorted(set(nums))
    if len(unique_nums) < 2:
        return None
    return unique_nums[1]

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 365 * 24 * 60 * 60),
        ('day', 24 * 60 * 60),
        ('hour', 60 * 60),
        ('minute', 60),
        ('second', 1)
    ]

    # Calculate each unit
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            if count > 1:
                components.append(f"{count} {unit_name}s")
            else:
                components.append(f"{count} {unit_name}")

    # Format the output
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

