def is_balanced(s, pairs):
    # Build opening set and closing map
    openers = set()
    closers = {}

    for i in range(0, len(pairs), 2):
        opener = pairs[i]
        closer = pairs[i + 1]
        openers.add(opener)
        closers[closer] = opener

    stack = []

    for char in s:
        if char in closers:
            # Character is in closing map (potential closer)
            if char in openers:
                # Character is both opener and closer (identical pair like "'" or "-")
                if stack and stack[-1] == char:
                    # Stack not empty and top matches - treat as closer
                    stack.pop()
                else:
                    # Stack empty or top doesn't match - treat as opener
                    stack.append(char)
            else:
                # Character is only a closer (distinct from opener)
                if not stack or stack[-1] != closers[char]:
                    return False
                stack.pop()
        elif char in openers:
            # Character is only an opener (not in closing map)
            stack.append(char)
        # Ignore characters not in pairs

    return len(stack) == 0

def getAllPrimeFactors(n):
