    tokens = s.split()

    # If the list of tokens is empty (empty string or whitespace only), return empty dictionary
    if not tokens:
        return {}

    # Count frequency of each letter
    counts = {}
    for token in tokens:
        counts[token] = counts.get(token, 0) + 1

    # Determine the maximum frequency
    max_count = max(counts.values())

    # Return a dictionary containing all letters with the maximum frequency
    return {letter: count for letter, count in counts.items() if count == max_count}

