def compare(selector1, selector2):
    def calculate_specificity(selector):
        ids = 0
        classes = 0
        tags = 0

        # Split by spaces to get each part (descendant combinators)
        parts = selector.split()

        for part in parts:
            part = part.strip()
            if not part:
                continue

            # Count ID selectors (#)
            ids += part.count('#')

            # Count class selectors (.)
            classes += part.count('.')

            # Check if there's a tag name
            # A tag name is an alphanumeric identifier at the start
            # (before any # or .)
            i = 0
            if i < len(part) and part[i].isalpha():
                tags += 1

        return (ids, classes, tags)

    spec1 = calculate_specificity(selector1)
    spec2 = calculate_specificity(selector2)

    # Compare: IDs first, then classes, then tags
    if spec1[0] > spec2[0]:
        return selector1
    elif spec1[0] < spec2[0]:
        return selector2
    elif spec1[1] > spec2[1]:
        return selector1
    elif spec1[1] < spec2[1]:
        return selector2
    elif spec1[2] > spec2[2]:
        return selector1
    elif spec1[2] < spec2[2]:
        return selector2
    else:
        # All equal, the later one wins (selector2)
        return selector2

def parse_int(s):
    s = s.lower()
    s = s.replace('-', ' ')
    words = [w for w in s.split() if w and w != 'and']

    ones = {"zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, 
            "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9}
    teens = {"ten": 10, "eleven": 11, "twelve": 12, "thirteen": 13, "fourteen": 14,
             "fifteen": 15, "sixteen": 16, "seventeen": 17, "eighteen": 18, "nineteen": 19}
    tens = {"twenty": 20, "thirty": 30, "forty": 40, "fifty": 50, 
            "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90}

    num_map = {**ones, **teens, **tens}

    total = 0
    current = 0

    for word in words:
        if word in num_map:
            current += num_map[word]
        elif word == "hundred":
            current *= 100
        elif word == "thousand":
            total += current * 1000
            current = 0
        elif word == "million":
            total += current * 1000000
            current = 0

    total += current
    return total

def almost_everywhere_zero(n, k):
    s = str(n)
    length = len(s)

    memo = {}

    def dp(pos, count, tight, leading_zeros):
        if pos == length:
            # Valid only if we have exactly k non-zero digits
            # and we're not still in leading zeros state (which would mean number 0)
            return 1 if count == k and not leading_zeros else 0

        state = (pos, count, tight, leading_zeros)
        if state in memo:
            return memo[state]

        result = 0
        limit = int(s[pos]) if tight else 9

        for digit in range(limit + 1):
            new_tight = tight and (digit == limit)

            if leading_zeros and digit == 0:
                # Still placing leading zeros, don't count this digit
                new_leading_zeros = True
                new_count = count
            else:
                # Either transitioning out of leading zeros or placing actual digit
                new_leading_zeros = False
                new_count = count + (1 if digit != 0 else 0)

            # Prune if we already exceeded k non-zero digits
            if new_count <= k:
                result += dp(pos + 1, new_count, new_tight, new_leading_zeros)

        memo[state] = result
        return result

    return dp(0, 0, True, True)

