def differentiate(polynomial, x):
    # Parse the polynomial into terms
    # Handle the case where the polynomial starts with a negative term
    if polynomial[0] == '-':
        terms = ['-']
        polynomial = polynomial[1:]
    else:
        terms = []

    # Split by '+' and '-' to get individual terms
    current_term = ""
    for i, char in enumerate(polynomial):
        if char in ['+', '-'] and i > 0:
            terms.append(current_term)
            current_term = char
        else:
            current_term += char
    terms.append(current_term)

    # Process each term to get coefficient and exponent
    derived_terms = []

    for term in terms:
        if not term:
            continue

        # Handle the case where term is just a constant (no x)
        if 'x' not in term:
            # This is a constant term, its derivative is 0
            continue

        # Extract coefficient and exponent
        if term == 'x':
            coeff = 1
            exp = 1
        elif term == '-x':
            coeff = -1
            exp = 1
        else:
            # Find where x is
            x_pos = term.find('x')
            if x_pos == 0:
                coeff = 1
            elif x_pos == 1 and term[0] == '-':
                coeff = -1
            else:
                coeff_str = term[:x_pos]
                if coeff_str == '+':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str)

            # Find exponent
            if '^' in term:
                exp = int(term[term.find('^') + 1:])
            elif x_pos == len(term) - 1:
                exp = 1
            else:
                exp = 1

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exp > 0:
            new_coeff = coeff * exp
            new_exp = exp - 1
            derived_terms.append((new_coeff, new_exp))

    # Evaluate the derived polynomial at x
    result = 0
    for coeff, exp in derived_terms:
        if exp == 0:
            result += coeff
        else:
            result += coeff * (x ** exp)

    return result

def solution(input_string, markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the position of the first comment marker
        first_comment_pos = len(line)
        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < first_comment_pos:
                first_comment_pos = pos

        # If we found a comment marker, truncate the line
        if first_comment_pos < len(line):
            line = line[:first_comment_pos]

        # Strip trailing whitespace
        line = line.rstrip()

        result_lines.append(line)

    return '\n'.join(result_lines)

