def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2

    # Check for factor 2
    if d % p == 0:
        while d % p == 0:
            d //= p
        result -= result // p

    # Check for odd factors from 3 onwards
    p = 3
    while p * p <= d:
        if d % p == 0:
            while d % p == 0:
                d //= p
            result -= result // p
        p += 2

    # If d is a prime number greater than 2
    if d > 1:
        result -= result // d

    return result

