        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # Check if n is prime
    if not is_prime(n):
        return False

    # Check if 2^n - 1 is prime
    mersenne_number = (1 << n) - 1  # This is 2^n - 1

    return is_prime(mersenne_number)

def exchange_sort(sequence):
    # Create the target sorted sequence
    target = sorted(sequence)

    # Create a mapping from value to its target positions
    from collections import defaultdict
    target_positions = defaultdict(list)
    for i, val in enumerate(target):
        target_positions[val].append(i)

    # Create a mapping from current position to target position
    pos_map = {}
    for i, val in enumerate(sequence):
        if target_positions[val]:
            pos_map[i] = target_positions[val].pop(0)

    # Count cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i] and i != pos_map.get(i, i):
            # Start a new cycle
            cycles += 1
            current = i
            while not visited[current]:
                visited[current] = True
                current = pos_map.get(current, current)

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

