    def parse_term(term):
        """Parse a term to extract coefficient and exponent."""
        if 'x' not in term:
            # Constant term
            try:
                return int(term), 0
            except ValueError:
                return 0, 0

        # Split around 'x'
        x_pos = term.find('x')
        coeff_str = term[:x_pos]
        exp_str = term[x_pos + 1:]

        # Parse coefficient
        if coeff_str == '' or coeff_str == '+':
            coefficient = 1
        elif coeff_str == '-':
            coefficient = -1
        else:
            try:
                coefficient = int(coeff_str)
            except ValueError:
                coefficient = 0

        # Parse exponent
        if exp_str == '':
            exponent = 1
        elif exp_str.startswith('^'):
            exponent = int(exp_str[1:])
        else:
            exponent = 1

        return coefficient, exponent

    # Split polynomial into terms
    # We need to split by + or - but keep the sign with each term
    import re

    # Use regex to find all terms including their signs
    terms = re.findall(r'[+-]?[^+-]+', polynomial)

    # Remove empty strings if any
    terms = [t for t in terms if t.strip()]

    # Calculate derivative value
    derivative_value = 0

    for term in terms:
        coefficient, exponent = parse_term(term)

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent == 0:
            # Derivative of constant is 0
            continue
        else:
            new_coefficient = exponent * coefficient
            new_exponent = exponent - 1

            if new_exponent == 0:
                derivative_value += new_coefficient
            else:
                derivative_value += new_coefficient * (x_value ** new_exponent)

    return derivative_value

import math

def converter(number, decimals=0, base=math.pi):
    EPSILON = 1e-12
    SYMBOLS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle sign
    sign = ''
    if number < 0:
        sign = '-'
        number = -number

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Handle integer part
    if integer_part == 0:
        integer_result = ''
    else:
        integer_result = ''
        temp = integer_part
        power = 0

        # Find the highest power
        while base ** (power + 1) <= temp:
            power += 1

        # Convert to base
        while temp > EPSILON:
            if power < 0:
                break
            digit_value = int(temp // (base ** power))
            if digit_value >= base:
                digit_value = int(base - 1)
            if digit_value < 0:
                digit_value = 0
            integer_result += SYMBOLS[digit_value]
            temp -= digit_value * (base ** power)
            power -= 1

    # Handle fractional part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        remainder = fractional_part

        # Calculate required digits
        for i in range(decimals + 1):  # One extra for rounding
            product = remainder * base
            digit = int(round(product))  # Round to nearest integer
            if digit >= base:
                digit = int(base - 1)
            if digit < 0:
                digit = 0
            fractional_result += SYMBOLS[digit]
            remainder = product - digit

            # If we've calculated all required digits, check for rounding
            if i == decimals - 1:
                # Check if the extra digit is >= 5
                if remainder * base >= 0.5:
                    # Need to round up the last digit
                    # This is a simplified approach - in practice, we'd need to handle carry propagation
                    pass

        # Remove the extra digit we calculated for rounding
        fractional_result = fractional_result[:-1]

        # Handle rounding properly
        if decimals > 0:
            # Recalculate with proper rounding
            fractional_result = ''
            remainder = fractional_part
            for i in range(decimals):
                product = remainder * base
                digit = int(round(product))
                if digit >= base:
                    digit = int(base - 1)
                if digit < 0:
                    digit = 0
                fractional_result += SYMBOLS[digit]
                remainder = product - digit

            # Handle final rounding
            if decimals > 0:
                product = remainder * base
                extra_digit = int(round(product))
                if extra_digit >= base:
                    extra_digit = int(base - 1)
                if extra_digit >= 5:
                    # Propagate carry
                    fractional_result = list(fractional_result)
                    for j in range(len(fractional_result) - 1, -1, -1):
                        if fractional_result[j] != '0':
                            digit_val = SYMBOLS.index(fractional_result[j])
                            fractional_result[j] = SYMBOLS[(digit_val + 1) % len(SYMBOLS)]
                            if digit_val + 1 < len(SYMBOLS):
                                break
                            else:
                                fractional_result[j] = '0'
                                if j == 0:
                                    # Need to add carry to integer part
                                    integer_result = integer_result[:-1] + SYMBOLS[SYMBOLS.index(integer_result[-1]) + 1] if integer_result else '1'
                                    break
                        else:
                            fractional_result[j] = '0'
                            if j == 0:
                                integer_result = integer_result[:-1] + SYMBOLS[SYMBOLS.index(integer_result[-1]) + 1] if integer_result else '1'
                    fractional_result = ''.join(fractional_result)

    # Combine results
    if fractional_result == '.':
        fractional_result = ''
    elif fractional_result == '.0' and decimals == 0:
        fractional_result = ''

    result = sign + integer_result + fractional_result

    # Handle special case where we have a leading zero in fractional part
    if result.startswith('.'):
        result = '0' + result

    # Remove trailing zeros in fractional part
    if '.' in result:
        result = result.rstrip('0').rstrip('.')

    return result

def encrypt(s):
    result = ""
    shift = 2 * 2  # shift down by two multiplied by two places (4 places)

    for char in s:
        if char.isalpha():
            # Determine if the character is uppercase or lowercase
            if char.isupper():
                # For uppercase letters
                result += chr((ord(char) - ord('A') + shift) % 26 + ord('A'))
            else:
                # For lowercase letters
                result += chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
        else:
            # Non-alphabetic characters remain unchanged
            result += char

    return result

def check_if_last_char_is_a_letter(txt):
    # Check if string is empty
    if not txt:
        return False

    # Check if last character is alphabetical
    if not txt[-1].isalpha():
        return False

    # If string has only one character and it's a letter, it's isolated
    if len(txt) == 1:
        return True

    # Check if the character before the last one is a space
    # This would mean the last letter is isolated
    return txt[-2] == ' '

def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    even_count = 0
    odd_count = 0

    for num in range(1, n + 1):
        # Convert number to string and check if it equals its reverse
        s = str(num)
        if s == s[::-1]:
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def is_palindrome(num: int) -> bool:
    s = str(num)
    return s == s[::-1]

def count_even_odd_palindromes(limit: int) -> tuple[int, int]:
    even_count = 0
    odd_count = 0
    for i in range(1, limit + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
    return (even_count, odd_count)

def even_odd_palindrome(n: int) -> tuple[int, int]:
    return count_even_odd_palindromes(n)

import re

def differentiate(poly, x):
    if not poly or poly.strip() == '':
        return 0

    poly = poly.strip()
    terms = re.findall(r'[+-]?\d*x?(\^\d+)?', poly)

    result = 0

    for term, exponent_part in terms:
        if 'x' not in term:
            continue

        if exponent_part:
            exponent = int(exponent_part[1:])
        else:
            exponent = 1

        if not term or term == 'x' or term == '+x':
            coefficient = 1
        elif term == '-x' or term == '-':
            coefficient = -1
        else:
            coefficient = int(term)

        if exponent == 0:
            continue

        derivative_value = coefficient * exponent * (x ** (exponent - 1))
        result += derivative_value

    return result

