            j = i + length - 1

            if i == j:
                # Single element is palindrome, takes 1 second
                dp[i][j] = 1
            elif is_palindrome[i][j]:
                # If the substring is palindrome, takes 1 second
                dp[i][j] = 1
            else:
                # Need to split into two parts
                dp[i][j] = length  # Worst case: remove each element separately
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

