def is_balanced(s, pairs):
    # Create a mapping from opener to closer
    pair_map = {}
    for i in range(0, len(pairs), 2):
        opener = pairs[i]
        closer = pairs[i + 1]
        pair_map[opener] = closer

    # Stack to keep track of openers
    stack = []

    for char in s:
        # If character is not part of any pair, skip it
        if char not in pairs:
            continue

        # Check if it's an opener (either from pair map or if it's a self-closing pair)
        if char in pair_map:
            # Check if it's a self-closing pair (same character for opener and closer)
            if pair_map[char] == char:
                # For self-closing pairs, if stack is empty or top doesn't match, push
                if not stack or stack[-1] != char:
                    stack.append(char)
                else:
                    # Pop if matches the top of stack
                    stack.pop()
            else:
                # Regular pair - always push opener
                stack.append(char)
        else:
            # It's a closer
            # If stack is empty, it's unbalanced
            if not stack:
                return False

            # Get the last opener
            last_opener = stack[-1]

            # Check if this closer matches the last opener
            if pair_map[last_opener] == char:
                stack.pop()
            else:
                return False

    # If stack is empty, all brackets were properly closed
    return len(stack) == 0

def solution(input_string, markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the position of the first comment marker
        first_marker_pos = len(line)  # Initialize to end of line
        found_marker = False

        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < first_marker_pos:
                first_marker_pos = pos
                found_marker = True

        # If we found a marker, truncate the line at that position
        if found_marker:
            processed_line = line[:first_marker_pos]
        else:
            processed_line = line

        # Strip trailing whitespace
        processed_line = processed_line.rstrip()
        result_lines.append(processed_line)

    return '\n'.join(result_lines)

import re
from collections import defaultdict

def simplify(expression):
    if not expression:
        return ""

    # Extract terms with their signs, coefficients, and variables
    terms = re.findall(r'([+-]?)(\d*)([a-z]+)', expression)

    monomials = defaultdict(int)

    for sign, coeff_str, var_part in terms:
        # Determine sign value
        if sign == '-':
            sign_val = -1
        else:
            sign_val = 1

        # Determine coefficient
        if coeff_str == '':
            coeff = 1
        else:
            coeff = int(coeff_str)

        coeff *= sign_val

        # Normalize variable order (sort alphabetically)
        var_part = ''.join(sorted(var_part))

        monomials[var_part] += coeff

    # Filter out zero coefficients
    monomials = {k: v for k, v in monomials.items() if v != 0}

    # Sort: by number of variables (ascending), then lexicographically
    sorted_vars = sorted(monomials.keys(), key=lambda x: (len(x), x))

    # Build output
    result_parts = []
    for i, var in enumerate(sorted_vars):
        coeff = monomials[var]
        if i == 0:
            # First term: no leading +
            if coeff == 1:
                result_parts.append(var)
            elif coeff == -1:
                result_parts.append('-' + var)
            elif coeff > 0:
                result_parts.append(str(coeff) + var)
            else:
                result_parts.append(str(coeff) + var)
        else:
            # Subsequent terms: + for positive coefficients
            if coeff == 1:
                result_parts.append('+' + var)
            elif coeff == -1:
                result_parts.append('-' + var)
            elif coeff > 0:
                result_parts.append('+' + str(coeff) + var)
            else:
                result_parts.append(str(coeff) + var)

    return ''.join(result_parts)

