from collections import defaultdict

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    n = int(data[0].strip())

    hostname_paths = defaultdict(set)

    for i in range(1, n + 1):
        if i >= len(data):
            break
        url = data[i].strip()

        # Remove http:// prefix
        if url.startswith('http://'):
            url_after_protocol = url[7:]
        else:
            url_after_protocol = url

        # Find the first slash after hostname
        slash_pos = url_after_protocol.find('/')

        if slash_pos == -1:
            # No path at all (http://hostname)
            hostname = url_after_protocol
            path = None
        else:
            hostname = url_after_protocol[:slash_pos]
            # If slash_pos+1 is beyond the string, path is empty (http://hostname/)
            # Otherwise, path is everything after the slash
            if slash_pos + 1 < len(url_after_protocol):
                path = url_after_protocol[slash_pos + 1:]
            else:
                path = ""

        hostname_paths[hostname].add(path)

    # Create a mapping from path set to hostnames
    path_set_to_hostnames = defaultdict(list)

    for hostname, paths in hostname_paths.items():
        # Convert set to sorted tuple for hashability
        path_tuple = tuple(sorted(paths, key=lambda x: (x is None, str(x) if x is not None else "")))
        path_set_to_hostnames[path_tuple].append(hostname)

    # Filter groups with more than one hostname
    result = []
    for paths, hostnames in path_set_to_hostnames.items():
        if len(hostnames) > 1:
            result.append(hostnames)

    # Output
    print(len(result))
    for group in result:
        sorted_hosts = sorted(group)
        print(" ".join(f"http://{h}" for h in sorted_hosts))

