def smallest_change(arr):
    n = len(arr)
    changes = 0
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1
    return changes

def valid_mersenne(n):
    if n < 2:
        return False

    # Check if n is prime
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False

    # Check if 2^n - 1 is prime
    mersenne_number = (2 ** n) - 1

    # Handle special case for 2^2 - 1 = 3
    if mersenne_number == 3:
        return True

    # Check if mersenne_number is prime
    if mersenne_number < 2:
        return False
    for i in range(2, int(mersenne_number**0.5) + 1):
        if mersenne_number % i == 0:
            return False

    return True

def fib4(n):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize the first four values
    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute fib4(n)
    for i in range(4, n + 1):
        next_val = a + b + c + d
        a, b, c, d = b, c, d, next_val

    return d

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """

    def to_float(value):
        """Convert a value to float, handling string representations with comma decimal separator"""
        if isinstance(value, (int, float)):
            return float(value)
        elif isinstance(value, str):
            # Replace comma with dot for decimal separator
            normalized_str = value.replace(',', '.')
            return float(normalized_str)
        else:
            raise TypeError(f"Unsupported type: {type(value)}")

    # Convert both values to float for comparison
    float_a = to_float(a)
    float_b = to_float(b)

    # Compare the float values
    if float_a > float_b:
        return a
    elif float_b > float_a:
        return b
    else:
        return None

def pig_latin(word):
    if not word or not word.isalpha():
        return None

    word = word.lower()
    vowels = "aeiou"

    if word[0] in vowels:
        return word + "way"

    # Find the index where the first vowel occurs
    first_vowel_index = 0
    for i, char in enumerate(word):
        if char in vowels:
            first_vowel_index = i
            break
    else:
        # No vowels found
        return word + "ay"

    # Move consonants from the beginning to the end
    return word[first_vowel_index:] + word[:first_vowel_index] + "ay"

def exchange_sort(sequence):
    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for val in sequence:
        count[val] += 1

    # Determine the target positions
    # 7s should be in positions [0, count[7])
    # 8s should be in positions [count[7], count[7] + count[8])
    # 9s should be in positions [count[7] + count[8], len(sequence))

    # Find misplaced elements
    misplaced = []

    # Check 7s in wrong positions
    for i in range(count[7]):
        if sequence[i] != 7:
            misplaced.append((i, sequence[i]))

    # Check 8s in wrong positions
    for i in range(count[7], count[7] + count[8]):
        if sequence[i] != 8:
            misplaced.append((i, sequence[i]))

    # Check 9s in wrong positions
    for i in range(count[7] + count[8], len(sequence)):
        if sequence[i] != 9:
            misplaced.append((i, sequence[i]))

    # Count how many 7s and 9s are misplaced (8s are already handled)
    misplaced_7s = sum(1 for pos, val in misplaced if val == 7)
    misplaced_9s = sum(1 for pos, val in misplaced if val == 9)

    # The minimum number of swaps is the maximum of misplaced 7s and 9s
    # because each swap can fix two misplaced elements
    return max(misplaced_7s, misplaced_9s)

def simplify(expression):
    if not expression:
        return ""

    # Parse the expression into terms
    terms = []
    i = 0
    while i < len(expression):
        # Determine the sign
        if expression[i] == '+':
            sign = 1
            i += 1
        elif expression[i] == '-':
            sign = -1
            i += 1
        else:
            sign = 1

        # Parse the coefficient
        coeff_str = ""
        while i < len(expression) and expression[i].isdigit():
            coeff_str += expression[i]
            i += 1

        if coeff_str == "":
            coeff = sign * 1
        else:
            coeff = sign * int(coeff_str)

        # Parse the variables
        vars_str = ""
        while i < len(expression) and expression[i].islower():
            vars_str += expression[i]
            i += 1

        # If no variables, it's just a constant term
        if vars_str == "":
            terms.append((coeff, ""))
        else:
            # Sort variables alphabetically
            sorted_vars = ''.join(sorted(vars_str))
            terms.append((coeff, sorted_vars))

    # Combine like terms
    term_dict = {}
    for coeff, vars_str in terms:
        if vars_str in term_dict:
            term_dict[vars_str] += coeff
        else:
            term_dict[vars_str] = coeff

    # Remove terms with zero coefficient
    term_dict = {vars_str: coeff for vars_str, coeff in term_dict.items() if coeff != 0}

    # Sort terms
    sorted_terms = sorted(term_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Format output
    result = []
    first = True
    for vars_str, coeff in sorted_terms:
        if coeff == 0:
            continue

        if first:
            if coeff > 0:
                result.append(f"{coeff}{vars_str}" if coeff != 1 or vars_str == "" else vars_str)
            else:
                result.append(f"-{abs(coeff)}{vars_str}" if abs(coeff) != 1 or vars_str == "" else "-" + vars_str)
            first = False
        else:
            if coeff > 0:
                result.append(f"+{coeff}{vars_str}" if coeff != 1 or vars_str == "" else "+" + vars_str)
            else:
                result.append(f"-{abs(coeff)}{vars_str}" if abs(coeff) != 1 or vars_str == "" else "-" + vars_str)

    # Handle case where all terms cancelled out
    if not result:
        return "0"

    return "".join(result)

def proper_fractions(n):
    if n == 1:
        return 0

    result = n

    # Check for factor 2
    if n % 2 == 0:
        result -= result // 2
        while n % 2 == 0:
            n //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result -= result // i
            while n % i == 0:
                n //= i
        i += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        result -= result // n

    return result

