import sys

def parse_url(url):
    # Remove http:// prefix
    if url.startswith("http://"):
        url = url[7:]

    # Find the first slash
    slash_index = url.find('/')

    if slash_index == -1:
        # No slash, so the whole string is the hostname
        hostname = url
        path = ""
    else:
        # Split hostname and path
        hostname = url[:slash_index]
        path = url[slash_index:]

    return hostname, path

