def proper_fractions(n):
    if n == 1:
        return 0

    result = n

    # Check for factor 2
    if n % 2 == 0:
        result //= 2
        while n % 2 == 0:
            n //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result = result - result // i
            while n % i == 0:
                n //= i
        i += 2

    # If n is a prime factor greater than 2
    if n > 1:
        result = result - result // n

    return result

