def valid_mersenne(n):
    """
    Check if 2^n - 1 is a Mersenne prime.
    """
    # n must be at least 2
    if n < 2:
        return False

    # n must be prime for 2^n - 1 to be prime (necessary condition)
    if not is_prime(n):
