    return lucas_lehmer(n)


def is_prime(num):
    """
    Check if a number is prime using trial division.
    """
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False

    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True


def lucas_lehmer(n):
    """
    Lucas-Lehmer test for Mersenne primes.

    For M_p = 2^p - 1 where p is prime, M_p is prime if and only if
    S_{p-2} ≡ 0 (mod M_p), where S_0 = 4 and S_{i+1} = S_i^2 - 2 (mod M_p).
    """
    m = pow(2, n) - 1

    # Lucas-Lehmer sequence
    s = 4

    # Perform n-2 iterations
    for _ in range(n - 2):
        s = (s * s - 2) % m

    return s == 0

def poohbear(code):
    # Filter out non-command characters
    valid_commands = "+-><cWEPNTQU LIVABYD"
    cmd_chars = [char for char in code if char in valid_commands]

    # Pre-process W-E loops
    w_to_e = {}  # maps W index in cmd_chars to matching E index
    e_to_w = {}  # maps E index in cmd_chars to matching W index
    stack = []

    for i, cmd in enumerate(cmd_chars):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                w_idx = stack.pop()
                w_to_e[w_idx] = i
                e_to_w[i] = w_idx

    # Initialize memory and pointer
    memory = {}  # Dictionary for infinite cells, default value 0
    pointer = 0
    copied = 0  # "copied" value from c command
    output = []

    # Execute commands
    cmd_idx = 0

    while cmd_idx < len(cmd_chars):
        cmd = cmd_chars[cmd_idx]
        cell = memory.get(pointer, 0)

        if cmd == '+':
            memory[pointer] = (cell + 1) % 256
        elif cmd == '-':
            memory[pointer] = (cell - 1) % 256
        elif cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == 'c':
            copied = cell
        elif cmd == 'p':
            memory[pointer] = copied
        elif cmd == 'W':
            if cell == 0:
                cmd_idx = w_to_e[cmd_idx] + 1
            else:
                cmd_idx += 1
        elif cmd == 'E':
            if cell != 0:
                cmd_idx = e_to_w[cmd_idx]
            else:
                cmd_idx += 1
        elif cmd == 'P':
            output.append(chr(cell))
        elif cmd == 'N':
            output.append(str(cell))
        elif cmd == 'T':
            memory[pointer] = (cell * 2) % 256
        elif cmd == 'Q':
            memory[pointer] = (cell * cell) % 256
        elif cmd == 'U':
            memory[pointer] = int(cell ** 0.5) % 256
        elif cmd == 'L':
            memory[pointer] = (cell + 2) % 256
        elif cmd == 'I':
            memory[pointer] = (cell - 2) % 256
        elif cmd == 'V':
            memory[pointer] = (cell // 2) % 256
        elif cmd == 'A':
            memory[pointer] = (cell + copied) % 256
        elif cmd == 'B':
            memory[pointer] = (cell - copied) % 256
        elif cmd == 'Y':
            memory[pointer] = (cell * copied) % 256
        elif cmd == 'D':
            if copied != 0:
                memory[pointer] = (cell // copied) % 256

        cmd_idx += 1

    return ''.join(output)

