    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    # Handle string representation of lists by safely parsing them
    if isinstance(numbers, str):
        try:
            numbers = ast.literal_eval(numbers)
        except (ValueError, SyntaxError):
            raise TypeError("Input must be a list of integers")

    # Validate that input is a list
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list of integers")

    # Validate all elements are integers (excluding booleans)
    for num in numbers:
        if not isinstance(num, int) or isinstance(num, bool):
            raise TypeError("All elements must be integers")

    # Handle empty list case
    if len(numbers) == 0:
        return (0, 1)

    # Calculate sum
    total_sum = sum(numbers)

    # Calculate product
    product = 1
    for num in numbers:
        product *= num

    return (total_sum, product)

def is_balanced(s, brackets):
    # Create a mapping of opening to closing brackets
    bracket_map = {}
    for i in range(0, len(brackets), 2):
        opening = brackets[i]
        closing = brackets[i + 1]
        bracket_map[opening] = closing

    # Stack to keep track of opening brackets
    stack = []

    for char in s:
        # If it's an opening bracket, push it onto the stack
        if char in bracket_map:
            stack.append(char)
        # If it's a closing bracket
        elif char in bracket_map.values():
            # If stack is empty or the closing bracket doesn't match the most recent opening bracket
            if not stack or bracket_map[stack.pop()] != char:
                return False

    # If stack is empty, all brackets were properly closed
    return len(stack) == 0

def is_balanced(string, pairs):
    # Create a mapping of opening to closing characters
    opening_to_closing = {}
    closing_to_opening = {}

    # Populate the mappings from the pairs string
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        opening_to_closing[opening] = closing
        closing_to_opening[closing] = opening

    # Use a stack to track opening characters
    stack = []

    for char in string:
        # If character is an opening character
        if char in opening_to_closing:
            stack.append(char)
        # If character is a closing character
        elif char in closing_to_opening:
            # If stack is empty, no matching opening character
            if not stack:
                return False
            # Pop the last opening character
            last_opening = stack.pop()
            # Check if it matches the current closing character
            if opening_to_closing[last_opening] != char:
                return False

    # String is balanced if stack is empty
    return len(stack) == 0

def solution(input_str, markers):
    # Handle empty input
    if not input_str:
        return ""

    # Split input into lines
    lines = input_str.split('\n')
    result_lines = []

    for line in lines:
        # Find the first occurrence of any marker in this line
        first_marker_idx = len(line)  # Default to end of line (no marker found)

        for marker in markers:
            idx = line.find(marker)
            if idx != -1 and idx < first_marker_idx:
                first_marker_idx = idx

        # Keep only text before the first marker
        if first_marker_idx < len(line):
            line = line[:first_marker_idx]

        # Strip trailing whitespace
        line = line.rstrip()

        result_lines.append(line)

    return '\n'.join(result_lines)

def smallest_change(arr):
    if not arr or len(arr) <= 1:
        return 0

    changes = 0
    left = 0
    right = len(arr) - 1

    while left < right:
        if arr[left] != arr[right]:
            changes += 1
        left += 1
        right -= 1

    return changes

import math

def converter(number, precision=0, base=math.pi):
    if number == 0:
        if precision == 0:
            return '0'
        else:
            return '0.' + '0' * precision

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Separate integer and fractional parts
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            # Handle the case where remainder is very close to base
            if abs(remainder - base) < 1e-10:
                remainder = 0
                temp = temp // base - 1
            else:
                temp = temp // base
            integer_digits.append(remainder)

        # Convert remainders to digits
        result_digits = []
        for remainder in reversed(integer_digits):
            digit_value = int(remainder)
            if digit_value < 10:
                result_digits.append(str(digit_value))
            else:
                result_digits.append(chr(ord('A') + digit_value - 10))

        integer_result = ''.join(result_digits)

    # Convert fractional part
    fractional_digits = []
    if precision > 0:
        temp_fractional = fractional_part
        for _ in range(precision):
            temp_fractional *= base
            digit = int(temp_fractional)
            fractional_digits.append(digit)
            temp_fractional -= digit

            # Handle case where we get a digit that's equal to base
            if digit >= base:
                digit = int(base) - 1
                fractional_digits[-1] = digit
                # Adjust the fractional part
                temp_fractional = temp_fractional + 1

    # Format the result
    if not fractional_digits:
        if negative:
            return '-' + integer_result
        else:
            return integer_result
    else:
        # Build fractional part
        fractional_str = ''
        for digit in fractional_digits:
            if digit < 10:
                fractional_str += str(digit)
            else:
                fractional_str += chr(ord('A') + digit - 10)

        # Combine integer and fractional parts
        if integer_result:
            result = integer_result + '.' + fractional_str
        else:
            result = '0.' + fractional_str

        if negative:
            result = '-' + result

        return result

def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        # Check if the number is a palindrome
        if str(i) == str(i)[::-1]:
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

