    king_x, king_y = pos_to_coords(king)
    amazon_x, amazon_y = pos_to_coords(amazon)

    # Get all squares that amazon can attack
    attacked_squares = get_attacked_squares(amazon_x, amazon_y)

    # Get all squares that white king can move to
    white_king_safe = get_safe_squares(king_x, king_y)

    # Get all squares that black king can be placed on
    result = [0, 0, 0, 0]  # [checkmate, check, stalemate, safe]

    for x in range(8):
        for y in range(8):
            # Skip if this square is occupied by white king or amazon
            if (x == king_x and y == king_y) or (x == amazon_x and y == amazon_y):
                continue

            # Skip if this square is adjacent to white king
            if is_adjacent(x, y, king_x, king_y):
                continue

            # Check if black king is under attack by amazon
            if can_attack(amazon_x, amazon_y, x, y):
                # Check if black king can move to any safe square
                safe_moves = 0
                for dx in [-1, 0, 1]:
                    for dy in [-1, 0, 1]:
                        if dx == 0 and dy == 0:
                            continue
                        nx, ny = x + dx, y + dy
                        if is_valid(nx, ny):
                            # Check if this square is safe
                            if not can_attack(amazon_x, amazon_y, nx, ny) and \
                               not (nx == king_x and ny == king_y) and \
                               not (is_adjacent(nx, ny, king_x, king_y)):
                                safe_moves += 1

                # If black king has no safe moves, it's checkmate
                if safe_moves == 0:
                    result[0] += 1  # checkmate
                else:
                    result[1] += 1  # check
            else:
                # Black king is not under attack
                # Check if black king can move to any safe square
                safe_moves = 0
                for dx in [-1, 0, 1]:
                    for dy in [-1, 0, 1]:
                        if dx == 0 and dy == 0:
                            continue
                        nx, ny = x + dx, y + dy
                        if is_valid(nx, ny):
                            # Check if this square is safe
                            if not can_attack(amazon_x, amazon_y, nx, ny) and \
                               not (nx == king_x and ny == king_y) and \
                               not (is_adjacent(nx, ny, king_x, king_y)):
                                safe_moves += 1

                # If black king has no safe moves, it's stalemate
                if safe_moves == 0:
                    result[2] += 1  # stalemate
                else:
                    result[3] += 1  # safe

    return result

from typing import List, Tuple


def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    if not numbers:
        return (0, 1)

    total_sum = sum(numbers)

    product = 1
    for num in numbers:
        product *= num

    return (total_sum, product)

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)

