def decimal_to_binary(decimal):
    if decimal == 0:
        return "db0db"

    binary_digits = []
    while decimal > 0:
        binary_digits.append(str(decimal % 2))
        decimal //= 2

    # Reverse the digits to get the correct binary representation
    binary_string = ''.join(reversed(binary_digits))
    return f"db{binary_string}db"

def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        col = ord(pos[0]) - ord('a')
        row = int(pos[1]) - 1
        return (row, col)

    def is_valid_bk_pos(bk_pos, king_pos, amazon_pos):
        if bk_pos == king_pos or bk_pos == amazon_pos:
            return False
        if abs(bk_pos[0] - king_pos[0]) <= 1 and abs(bk_pos[1] - king_pos[1]) <= 1:
