        row_diff = abs(pos[0] - amazon_pos[0])
        col_diff = abs(pos[1] - amazon_pos[1])

        if row_diff == 0 or col_diff == 0 or row_diff == col_diff:
            return True

        if (row_diff == 1 and col_diff == 2) or (row_diff == 2 and col_diff == 1):
            return True

        return False

    def get_valid_king_moves(bk_pos, king_pos, amazon_pos):
        moves = 0
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                new_pos = (bk_pos[0] + dr, bk_pos[1] + dc)
                if not (0 <= new_pos[0] <= 7 and 0 <= new_pos[1] <= 7):
                    continue
                if not is_valid_bk_pos(new_pos, king_pos, amazon_pos):
                    continue
                if not is_attacked_by_amazon(new_pos, amazon_pos):
                    moves += 1
        return moves

    king_pos = chess_to_coords(king)
    amazon_pos = chess_to_coords(amazon)

    checkmate = 0
    check = 0
    stalemate = 0
    safe_moves = 0

    for row in range(8):
        for col in range(8):
            bk_pos = (row, col)

            if not is_valid_bk_pos(bk_pos, king_pos, amazon_pos):
                continue

