def histogram(s):
    if not s:
        return {}

    # Count frequency of each letter
    counts = {}
    for letter in s.split():
        counts[letter] = counts.get(letter, 0) + 1

    # Find maximum frequency
    max_count = max(counts.values())

    # Return dictionary with only letters having maximum frequency
    return {letter: count for letter, count in counts.items() if count == max_count}

def compare_one(a, b):
    def to_numeric(val):
        if isinstance(val, (int, float)):
            return float(val)
        elif isinstance(val, str):
            # Replace comma with dot for decimal separator
            normalized = val.replace(',', '.')
            return float(normalized)
        else:
            raise TypeError("Unsupported type")

    def is_equal(val1, val2):
        return abs(val1 - val2) < 1e-10

    num_a = to_numeric(a)
    num_b = to_numeric(b)

    if is_equal(num_a, num_b):
        return None

    if num_a > num_b:
        return a
    else:
        return b

def getAllPrimeFactors(n):
    # Input validation
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Handle edge cases
    if n == 1:
        return [1]
    if n == 2:
        return [2]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Input validation
    if not isinstance(n, int):
        return [[], []]
    if n <= 0:
        return [[], []]

    # Handle edge cases
    if n == 1:
        return [[1], [1]]
    if n == 2:
        return [[2], [1]]

    factors = getAllPrimeFactors(n)

    if not factors:
        return [[], []]

    unique_factors = []
    counts = []

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Input validation
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Handle edge cases
    if n == 1:
        return [1]
    if n == 2:
        return [2]

    factor_counts = getUniquePrimeFactorsWithCount(n)
    unique_factors = factor_counts[0]
    counts = factor_counts[1]

    products = []

    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

def sum_array(arr):
