def poohbear(code):
    import math

    memory = {}
    cell_ptr = 0
    copy_register = 0
    output = []

    def get_cell():
        return memory.get(cell_ptr, 0)

    def set_cell(value):
        memory[cell_ptr] = ((value % 256) + 256) % 256

    # Preprocess W/E pairs for loops
    w_to_e = {}
    e_to_w = {}
    stack = []

    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                w_pos = stack.pop()
                w_to_e[w_pos] = i
                e_to_w[i] = w_pos

    pc = 0
    while pc < len(code):
        cmd = code[pc]

        if cmd not in '+-><cpWEPNTQUILYDAB':
            pc += 1
            continue

        current = get_cell()

        if cmd == '+':
            set_cell(current + 1)
        elif cmd == '-':
            set_cell(current - 1)
        elif cmd == '>':
            cell_ptr += 1
        elif cmd == '<':
            cell_ptr -= 1
        elif cmd == 'c':
            copy_register = current
        elif cmd == 'p':
            set_cell(copy_register)
        elif cmd == 'W':
            if current == 0:
                pc = w_to_e[pc] + 1
                continue
            pc += 1
        elif cmd == 'E':
            if current != 0:
                pc = e_to_w[pc]
                continue
            pc += 1
        elif cmd == 'P':
            output.append(chr(current))
        elif cmd == 'N':
            output.append(str(current))
        elif cmd == 'T':
            set_cell(current * 2)
        elif cmd == 'Q':
            set_cell(current * current)
        elif cmd == 'U':
            set_cell(int(math.floor(current ** 0.5)))
        elif cmd == 'L':
            set_cell(current + 2)
        elif cmd == 'I':
            set_cell(current - 2)
        elif cmd == 'V':
            set_cell(current // 2)
        elif cmd == 'A':
            set_cell(current + copy_register)
        elif cmd == 'B':
            set_cell(current - copy_register)
        elif cmd == 'Y':
            set_cell(current * copy_register)
        elif cmd == 'D':
            if copy_register != 0:
                set_cell(current // copy_register)

        pc += 1

    return ''.join(output)

def fib4(n):
    # Base cases
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Initialize the last 4 values: fib4(0), fib4(1), fib4(2), fib4(3)
    f0, f1, f2, f3 = 0, 0, 2, 0

    # Iteratively compute fib4(n) using the recurrence relation
    for _ in range(4, n + 1):
        fn = f0 + f1 + f2 + f3
        # Shift values: drop the oldest, add the newest
        f0, f1, f2, f3 = f1, f2, f3, fn

    return f3

def correct_bracketing(brackets: str):
    balance = 0
    for char in brackets:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1

        if balance < 0:
            return False

    return balance == 0

from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    result = []

    if not paren_string:
        return result

    groups = paren_string.split()

    for group in groups:
        current_depth = 0
        max_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

def simplify(expression):
    from collections import defaultdict

    terms_dict = defaultdict(int)

    i = 0
    n = len(expression)

    while i < n:
        # Handle sign at the start of a term
        sign = 1
        if i < n and expression[i] == '+':
            sign = 1
            i += 1
        elif i < n and expression[i] == '-':
            sign = -1
            i += 1

        # Parse coefficient
        coeff = 1
        if i < n and expression[i].isdigit():
            start = i
            while i < n and expression[i].isdigit():
                i += 1
            coeff = int(expression[start:i])

        # Parse variables
        vars_str = ''
        while i < n and expression[i].isalpha():
            vars_str += expression[i]
            i += 1

        if vars_str:  # Only process if we found variables
            vars_tuple = tuple(sorted(vars_str))
            terms_dict[vars_tuple] += sign * coeff

    # Build result - sort by number of variables, then lexicographically
    sorted_terms = sorted(terms_dict.items(), key=lambda x: (len(x[0]), x[0]))

    result_parts = []
    first = True
    for vars_tuple, coeff in sorted_terms:
        if coeff == 0:
            continue

        vars_str = ''.join(vars_tuple)

        if first:
            # First term: no leading +
            if coeff > 0:
                result_parts.append(f'{coeff if coeff != 1 else ""}{vars_str}')
            else:
                result_parts.append(f'{coeff if coeff != -1 else "-"}{vars_str}')
            first = False
        else:
            # Subsequent terms: include + sign for positive
