def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """

    def is_prime(num):
        """Helper function to check if a number is prime"""
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        # Check odd divisors up to sqrt(num)
        for i in range(3, int(num ** 0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    return x if is_prime(n) else y

def poohbear(code):
    cells = {}
    pointer = 0
    copied = 0
    ip = 0
    output = []

    # Preprocess to find matching W/E pairs
    loop_map = {}
    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                start = stack.pop()
                loop_map[start] = i
                loop_map[i] = start

    while ip < len(code):
        char = code[ip]

        if char == '+':
            cells[pointer] = cells.get(pointer, 0) + 1
            if cells[pointer] > 255:
                cells[pointer] = 0
        elif char == '-':
            cells[pointer] = cells.get(pointer, 0) - 1
            if cells[pointer] < 0:
                cells[pointer] = 255
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copied = cells.get(pointer, 0)
        elif char == 'p':
            cells[pointer] = copied
        elif char == 'W':
            if cells.get(pointer, 0) == 0:
                ip = loop_map[ip]
        elif char == 'E':
            if cells.get(pointer, 0) != 0:
                ip = loop_map[ip]
        elif char == 'P':
            output.append(chr(cells.get(pointer, 0)))
        elif char == 'N':
            output.append(str(cells.get(pointer, 0)))
        elif char == 'T':
            cells[pointer] = cells.get(pointer, 0) * 2
            if cells[pointer] > 255:
                cells[pointer] = 0
        elif char == 'Q':
            cells[pointer] = cells.get(pointer, 0) ** 2
            if cells[pointer] > 255:
                cells[pointer] = 0
        elif char == 'U':
            import math
            cells[pointer] = int(math.sqrt(cells.get(pointer, 0)))
        elif char == 'L':
            cells[pointer] = cells.get(pointer, 0) + 2
            if cells[pointer] > 255:
                cells[pointer] = 0
        elif char == 'I':
            cells[pointer] = cells.get(pointer, 0) - 2
            if cells[pointer] < 0:
                cells[pointer] = 255
        elif char == 'V':
            cells[pointer] = cells.get(pointer, 0) // 2
        elif char == 'A':
            cells[pointer] = cells.get(pointer, 0) + copied
            if cells[pointer] > 255:
                cells[pointer] = 0
            elif cells[pointer] < 0:
                cells[pointer] = 255
        elif char == 'B':
            cells[pointer] = cells.get(pointer, 0) - copied
            if cells[pointer] > 255:
                cells[pointer] = 0
            elif cells[pointer] < 0:
                cells[pointer] = 255
        elif char == 'Y':
            cells[pointer] = cells.get(pointer, 0) * copied
            if cells[pointer] > 255:
                cells[pointer] = 0
        elif char == 'D':
            if copied != 0:
                cells[pointer] = cells.get(pointer, 0) // copied
            else:
                cells[pointer] = 0

        ip += 1

    return ''.join(output)

def is_balanced(s, pairs):
    # Create a mapping of opening to closing characters and vice versa
    pair_map = {}
    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        pair_map[open_char] = close_char
        # If opening and closing are the same character, it's both
        if open_char == close_char:
            pair_map[close_char] = open_char

    # Stack to keep track of opening characters
    stack = []

    for char in s:
        # If character is an opening character
        if char in pair_map and (pair_map[char] != char or (char in pair_map and pair_map[char] == char)):
            # Check if it's a valid opening character (either it's not the same as closing, or it's a self-pair)
            if char in pair_map and pair_map[char] != char:
                # Regular pair
                stack.append(char)
            elif char in pair_map and pair_map[char] == char:
                # Self-pairing character
                stack.append(char)
        # If character is a closing character
        elif char in pair_map.values():
            # If stack is empty or the character doesn't match the last opening character
            if not stack or pair_map.get(stack[-1], '') != char:
                return False
            stack.pop()

    # If stack is empty, all characters were matched
    return len(stack) == 0

def order_by_points(nums):
    def digit_sum(n):
        # Calculate sum of digits, treating negative numbers as positive
        return sum(int(digit) for digit in str(abs(n)))

    # Create list of tuples (digit_sum, original_index, number)
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract the numbers in the new order
    return [num for _, _, num in indexed_nums]

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle sign
    sign = ''
    if number < 0:
        sign = '-'
        number = -number

    # Convert integer part
    integer_part = int(number)
    digits = []

    # Special case for base 2
    if base == 2:
        temp = integer_part
        while temp > 0:
            digits.append(str(temp % 2))
            temp //= 2
        digits.reverse()
        integer_result = ''.join(digits) if digits else '0'
    else:
        # General case for any base
        temp = integer_part
        while temp > 0:
            remainder = temp % int(base)
            digits.append(str(remainder))
            temp = temp // int(base)
        digits.reverse()
        integer_result = ''.join(digits) if digits else '0'

    # Convert fractional part
    fractional_part = number - integer_part
    fractional_digits = []

    if decimals > 0:
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            fractional_digits.append(str(digit))
            fractional_part -= digit

    # Build result
    if decimals == 0:
        result = integer_result
    else:
        fractional_str = ''.join(fractional_digits)
        # Handle the case where we have trailing zeros
        if fractional_str.rstrip('0'):
            result = integer_result + '.' + fractional_str.rstrip('0')
        else:
            result = integer_result + '.' + fractional_str

    # Handle leading zero for numbers less than 1
    if number < 1 and decimals > 0:
        if not result.startswith('0.'):
            result = '0' + result

    return sign + result

