def simplify(expression):
    if not expression:
        return ""

    # Parse the expression into terms
    terms = []
    i = 0
    while i < len(expression):
        # Skip spaces
        if expression[i] == ' ':
            i += 1
            continue

        # Determine the sign
        sign = 1
        if expression[i] == '-':
            sign = -1
            i += 1
        elif expression[i] == '+':
            sign = 1
            i += 1

        # Extract the coefficient and variables
        coeff_str = ""
        var_str = ""
        start = i

        # Find where the term ends (next + or - or end of string)
        while i < len(expression) and expression[i] not in "+-":
            if expression[i].isalpha():
                var_str += expression[i]
            else:
                coeff_str += expression[i]
            i += 1

        # Parse coefficient
        if coeff_str == "" or coeff_str == "+":
            coeff = sign * 1
        elif coeff_str == "-":
            coeff = sign * -1
        else:
            coeff = sign * int(coeff_str)

        # Sort variables alphabetically
        var_str = ''.join(sorted(var_str))

        terms.append((coeff, var_str))

    # Combine like terms
    term_dict = {}
    for coeff, var in terms:
        if var in term_dict:
            term_dict[var] += coeff
        else:
            term_dict[var] = coeff

    # Filter out zero coefficients
    result_terms = [(coeff, var) for var, coeff in term_dict.items() if coeff != 0]

    # Sort by number of variables, then lexicographically
    result_terms.sort(key=lambda x: (len(x[1]), x[1]))

    # Format output
    if not result_terms:
        return ""

    result = []
    for i, (coeff, var) in enumerate(result_terms):
        if i == 0:
            # First term: no leading +
            if coeff == 1 and var:
                result.append(var)
            elif coeff == -1 and var:
                result.append("-" + var)
            else:
                result.append(str(coeff) + var if var else str(coeff))
        else:
            # Subsequent terms: handle signs properly
            if coeff == 1 and var:
                result.append("+" + var)
            elif coeff == -1 and var:
                result.append("-" + var)
            elif coeff > 0:
                result.append("+" + str(coeff) + var if var else "+" + str(coeff))
            else:
                result.append(str(coeff) + var if var else str(coeff))

    return "".join(result)

