            # Handle edge cases
            if n == 0:
                results.append("0")
                continue

            if k <= 0:
                results.append("-1")
                continue

            # Sort and find K-th smallest element
            arr.sort()

            if k > n:
                results.append("-1")
            else:
                # K-th smallest (1-indexed)
                results.append(str(arr[k - 1]))

    except StopIteration:
        pass

