def exchange_sort(sequence):
    # Create target sorted sequence
    target = sorted(sequence)

    # Create a mapping from value to its correct positions
    from collections import defaultdict
    correct_positions = defaultdict(list)
    for i, val in enumerate(target):
        correct_positions[val].append(i)

    # Create a mapping from each position to what value should be there
    position_to_correct_value = {}
    for val, positions in correct_positions.items():
        for pos in positions:
            position_to_correct_value[pos] = val

    # Find all positions where the current value doesn't match the target
    mismatches = []
    for i, val in enumerate(sequence):
        if val != position_to_correct_value[i]:
            mismatches.append(i)

    # If no mismatches, return 0
    if not mismatches:
        return 0

    # Create a mapping from current position to target position
    # for all mismatched elements
    position_mapping = {}
    for i in range(len(sequence)):
        if sequence[i] != position_to_correct_value[i]:
            position_mapping[i] = position_to_correct_value[i]

    # Count cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i] and i in position_mapping:
            # Start a new cycle
            cycle_length = 0
            current = i
            while not visited[current]:
                visited[current] = True
                if current in position_mapping:
                    current = position_mapping[current]
                else:
                    break
                cycle_length += 1
            if cycle_length > 0:
                cycles += 1

    # Minimum swaps = (number of mismatches - number of cycles) / 2
    # But we need to be more careful - let's count properly
    # Actually, let's use a simpler approach:
    # Each cycle of length k requires (k-1) swaps
    # So total swaps = total_positions - number_of_cycles

    visited = [False] * len(sequence)
    swaps = 0

    for i in range(len(sequence)):
        if not visited[i] and i in position_mapping:
            # Find the cycle
            cycle_length = 0
            current = i
            while not visited[current]:
                visited[current] = True
                if current in position_mapping:
                    current = position_mapping[current]
                else:
                    break
                cycle_length += 1
            if cycle_length > 0:
                swaps += cycle_length - 1

    return swaps

