def normalize_path(path):
    # Handle empty path
    if not path:
        return ""

    # Split path into components
    components = path.split('/')

    # Process components to handle . and ..
    stack = []
    for component in components:
        if component == '.' or component == '':
            continue
        elif component == '..':
            if stack:
                stack.pop()
        else:
            stack.append(component)

    # Join components back
    if not stack:
        return ""

    return '/'.join(stack)

def get_path_set(paths):
    # Get unique normalized paths
    normalized_paths = set()
    for path in paths:
        normalized_paths.add(normalize_path(path))

    # Convert to sorted tuple for hashing
    return tuple(sorted(normalized_paths))

def hash_path_set(path_set):
    # Create a robust hash for the path set
    # We'll use a combination of string concatenation and hashing
    if not path_set:
        return hash("")

    # Sort the path set for consistent hashing
    sorted_paths = sorted(path_set)

    # Create a string representation
    path_str = '|'.join(sorted_paths)

    # Return hash of the string
    return hash(path_str)

