def histogram(s):
    if not s:
        return {}

    # Split the string into letters
    letters = s.split()

    # Count frequency of each letter
    count_dict = {}
    for letter in letters:
        count_dict[letter] = count_dict.get(letter, 0) + 1

    # Find maximum frequency
    max_count = max(count_dict.values())

    # Return all letters with maximum frequency
    return {letter: count for letter, count in count_dict.items() if count == max_count}

def choose(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n - k:
        k = n - k

    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

def check_if_last_char_is_a_letter(txt):
    # Handle empty string
    if not txt:
        return False

    # Check if last character is alphabetical
    if not txt[-1].isalpha():
        return False

    # If string has only one character and it's alphabetical, it's not part of a word
    if len(txt) == 1:
        return True

    # Check if the character before the last one is a space
    # If so, the last character is not part of a word
    return txt[-2] == ' '

