def is_valid(s):
    # Check if string is empty
    if len(s) == 0:
        return False

    # Check first character (must be alpha, underscore, or dollar sign)
    first_char = s[0]
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Check remaining characters (can be alpha, digit, underscore, or dollar sign)
    for char in s[1:]:
