def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def is_valid(r, c):
        return 0 <= r < 8 and 0 <= c < 8

    def is_adjacent(r1, c1, r2, c2):
        return abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1

    def is_attacked_by_amazon(br, bc, kr, kc, ar, ac):
        # Check if the square (br, bc) is attacked by the amazon at (ar, ac)
        # considering the white king at (kr, kc) blocks the attack

        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dr, dc in knight_moves:
            if br == ar + dr and bc == ac + dc:
                return True

        # Queen moves (rook + bishop)
        # Check if (br, bc) is on the same row, column or diagonal as (ar, ac)
        if br == ar or bc == ac or abs(br - ar) == abs(bc - ac):
            # Check if the path is blocked by the white king
            # For queen moves, we need to check if the white king is on the path
            if br == ar:  # Same row
                step_c = 1 if bc > ac else -1
                for c in range(ac + step_c, bc, step_c):
                    if kr == ar and kc == c:
                        return False
            elif bc == ac:  # Same column
                step_r = 1 if br > ar else -1
                for r in range(ar + step_r, br, step_r):
                    if kr == r and kc == ac:
                        return False
            else:  # Same diagonal
                step_r = 1 if br > ar else -1
                step_c = 1 if bc > ac else -1
                r, c = ar + step_r, ac + step_c
                while r != br and c != bc:
                    if kr == r and kc == c:
                        return False
                    r += step_r
                    c += step_c
            return True

        return False

    kr, kc = chess_to_coords(king)
    ar, ac = chess_to_coords(amazon)

    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    # Iterate through all possible black king positions
    for br in range(8):
        for bc in range(8):
            # Skip if the square is occupied by white king or amazon
            if (br == kr and bc == kc) or (br == ar and bc == ac):
                continue

            # Skip if the square is adjacent to white king
            if is_adjacent(br, bc, kr, kc):
                continue

            # Check if black king is attacked by amazon
            is_attacked = is_attacked_by_amazon(br, bc, kr, kc, ar, ac)

            # Count valid moves
            valid_moves = 0
            # Check all 8 adjacent squares
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = br + dr, bc + dc
                    # Check if neighbor is valid
                    if not is_valid(nr, nc):
                        continue
                    # Check if neighbor is occupied by white king or amazon
                    if (nr == kr and nc == kc) or (nr == ar and nc == ac):
                        continue
                    # Check if neighbor is adjacent to white king
                    if is_adjacent(nr, nc, kr, kc):
                        continue
                    # Check if neighbor is attacked by amazon
                    if is_attacked_by_amazon(nr, nc, kr, kc, ar, ac):
                        continue
                    valid_moves += 1

            # Classify the position
            if is_attacked:
                if valid_moves == 0:
                    checkmate += 1
                else:
                    check += 1
            else:
                if valid_moves == 0:
                    stalemate += 1
                else:
                    safe += 1

    return [checkmate, check, stalemate, safe]

