            if gems[i] == gems[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP: dp[i][j] represents minimum seconds to destroy substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Fill DP table
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if length == 1:
                dp[i][j] = 1
            elif is_palindrome[i][j]:
                dp[i][j] = 1
            else:
                # Try all possible splits
                dp[i][j] = length  # Worst case: each gem destroyed individually
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

