        # Extract coefficient and exponent
        term_part = term[term_start:]

        # Handle constant term (no x)
        if 'x' not in term_part:
            # This is a constant term, its derivative is 0
            continue

        # Find where x is
        x_pos = term_part.find('x')
        if x_pos == -1:
