        # Extract exponent
        exp = 1
        if '^' in term_part:
            exp_pos = term_part.find('^')
            exp = int(term_part[exp_pos+1:])
        else:
            exp = 1

        # Apply power rule: d/dx(ax^n) = a*n*x^(n-1)
        new_coeff = coeff * exp
        new_exp = exp - 1

        # Special case: if new_exp is 0, the term is just a constant
        if new_exp == 0:
            derivative_terms.append(str(new_coeff))
        elif new_exp == 1:
            if new_coeff == 1:
                derivative_terms.append('x')
            elif new_coeff == -1:
                derivative_terms.append('-x')
            else:
                derivative_terms.append(str(new_coeff) + 'x')
        else:
            if new_coeff == 1:
                derivative_terms.append('x^' + str(new_exp))
            elif new_coeff == -1:
                derivative_terms.append('-x^' + str(new_exp))
            else:
                derivative_terms.append(str(new_coeff) + 'x^' + str(new_exp))

    # Evaluate the derivative at x
    result = 0
    for term in derivative_terms:
        if 'x' in term:
            # Handle terms with x
            if term == 'x':
                result += x
            elif term == '-x':
                result -= x
            else:
