def exchange_sort(sequence):
    # Create target sorted sequence
    target = []
    count = [0, 0, 0]  # count[0] for 7s, count[1] for 8s, count[2] for 9s

    for num in sequence:
        if num == 7:
            count[0] += 1
        elif num == 8:
            count[1] += 1
        else:  # num == 9
            count[2] += 1

    # Build target sequence
    target = [7] * count[0] + [8] * count[1] + [9] * count[2]

    # Create position mapping for target
    pos = {}
    for i, num in enumerate(target):
        if num not in pos:
            pos[num] = []
        pos[num].append(i)

    # Create a copy of the original sequence to track positions
    original_positions = []
    for i, num in enumerate(sequence):
        original_positions.append((num, i))

    # Create mapping from current positions to target positions
    # For each element, we need to know where it should go
    element_to_target_pos = {}
    for i, num in enumerate(sequence):
        if num in pos and pos[num]:
            element_to_target_pos[i] = pos[num].pop(0)

    # Find cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i]:
            # Start a new cycle
            cycle_length = 0
            current = i

            while not visited[current]:
                visited[current] = True
                # Move to where current element should go
                if current in element_to_target_pos:
                    current = element_to_target_pos[current]
                else:
                    break
                cycle_length += 1

            if cycle_length > 0:
                cycles += 1

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

