def combination(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1
    return factorial(n) // (factorial(k) * factorial(n - k))

def probability_all_collected(k, n):
    # Using inclusion-exclusion principle
    # P(all k types collected in n trials) = sum_{i=0}^{k} (-1)^i * C(k,i) * ((k-i)/k)^n
    if n < k:
        return 0.0

    prob = 0.0
    for i in range(k + 1):
        sign = (-1) ** i
        comb = combination(k, i)
        prob += sign * comb * ((k - i) / k) ** n

    return prob

def solve(k, target_prob):
    if k == 1:
        return 1

    # Binary search for the minimum n
    left, right = k, k * 1000000  # Upper bound estimation

    while left < right:
        mid = (left + right) // 2
        prob = probability_all_collected(k, mid)

        if prob >= target_prob:
            right = mid
        else:
            left = mid + 1

    return left

