def is_balanced(string, pairs):
    # Create a mapping from opener to closer
    pair_map = {}
    for i in range(0, len(pairs), 2):
        opener = pairs[i]
        closer = pairs[i + 1]
        pair_map[opener] = closer

    # Stack to keep track of openers
    stack = []

    for char in string:
        # Skip characters not in pairs
        if char not in pairs:
            continue

        # Check if character is an opener
        if char in pair_map:
            # If it's an opener, push it onto the stack
            stack.append(char)
        else:
            # It's a closer
            # If stack is empty, no opener to match
            if not stack:
                return False

            # Pop the last opener
            last_opener = stack.pop()

            # Check if the closer matches the opener
            if pair_map[last_opener] != char:
                return False

    # String is balanced if stack is empty
    return len(stack) == 0

