            term = term[1:]
        else:
            sign = 1

        # Parse coefficient and exponent
        if 'x' not in term:
            # Constant term
            continue
        elif '^' not in term:
            # x or -x or 5x etc.
            if term == 'x':
                coefficient = 1
                exponent = 1
            elif term == '-x':
                coefficient = 1
                exponent = 1
            else:
                # Extract coefficient (everything before x)
                coeff_part = term[:-1]
                if coeff_part == '':
                    coefficient = 1
                elif coeff_part == '-':
                    coefficient = 1
                else:
                    coefficient = int(coeff_part)
                exponent = 1
        else:
            # Contains ^ (e.g., 3x^2 or -5x^3)
            parts = term.split('x^')
            if len(parts) == 2:
                coeff_part = parts[0]
                exponent = int(parts[1])
                if coeff_part == '' or coeff_part == '+':
                    coefficient = 1
                elif coeff_part == '-':
                    coefficient = 1
                else:
                    coefficient = int(coeff_part)

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if 'x' in term and '^' in term:
            # Term is ax^n where n > 0
            parts = term.split('x^')
            coeff_part = parts[0]
            exponent = int(parts[1])
            if coeff_part == '' or coeff_part == '+':
                coefficient = 1
            elif coeff_part == '-':
                coefficient = -1
            else:
                coefficient = int(coeff_part)

            if exponent > 0:
                new_coefficient = exponent * coefficient * sign
                new_exponent = exponent - 1
                derivative_terms.append((new_coefficient, new_exponent))
        elif 'x' in term and '^' not in term:
            # Term is ax where a is coefficient and exponent is 1
            if term == 'x':
                coefficient = 1
                exponent = 1
            elif term == '-x':
                coefficient = -1
                exponent = 1
            else:
                # Extract coefficient
                coeff_part = term[:-1]
                if coeff_part == '':
                    coefficient = 1
                elif coeff_part == '-':
                    coefficient = -1
                else:
                    coefficient = int(coeff_part)
                exponent = 1

            if exponent > 0:
                new_coefficient = exponent * coefficient * sign
                new_exponent = exponent - 1
                derivative_terms.append((new_coefficient, new_exponent))

    # Evaluate the derivative at x
    result = 0
    for coeff, exp in derivative_terms:
        if exp == 0:
            result += coeff
        else:
            result += coeff * (x ** exp)

    return result

