def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            if char.islower():
                base = ord('a')
            else:
                base = ord('A')
            # Shift by 4 positions with circular wrapping
            shifted = (ord(char) - base + 4) % 26 + base
            result.append(chr(shifted))
        else:
            result.append(char)
    return ''.join(result)

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == "":
        return None

    return hashlib.md5(text.encode('utf-8')).hexdigest()

def exchange_sort(arr):
    n = len(arr)
    for i in range(n - 1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                arr[i], arr[j] = arr[j], arr[i]
    return arr

import re

def simplify(expression):
    # Extract all terms using regex
    # Pattern: optional sign, optional number, one or more lowercase letters
    terms = re.findall(r'[+-]?\d*[a-z]+', expression)

    if not terms:
        return "0"

    # Dictionary to store monomials: key = sorted variable string, value = coefficient
    monomials = {}

    for term in terms:
        # Find where variables start (after coefficient)
        var_start = 0
        for i, c in enumerate(term):
            if c.isalpha():
                var_start = i
                break

        # Extract coefficient
        coef_str = term[:var_start]
        if not coef_str or coef_str == '+':
            coef = 1
        elif coef_str == '-':
            coef = -1
        else:
            coef = int(coef_str)

        # Extract and sort variables
        variables = sorted(term[var_start:])
        var_key = ''.join(variables)

        # Combine like terms
        if var_key in monomials:
            monomials[var_key] += coef
        else:
            monomials[var_key] = coef

    # Remove zero coefficient monomials
    monomials = {k: v for k, v in monomials.items() if v != 0}

    if not monomials:
        return "0"

    # Sort monomials: first by number of variables, then lexicographically
    sorted_monomials = sorted(monomials.items(), key=lambda x: (len(x[0]), x[0]))

    # Format output
    result = []
    for i, (variables, coef) in enumerate(sorted_monomials):
        if i == 0:
            # First term
            if coef == 1 and variables:
                result.append(variables)
            elif coef == -1 and variables:
                result.append('-' + variables)
            elif coef == 1 and not variables:
                result.append('1')
            elif coef == -1 and not variables:
                result.append('-1')
            elif coef != 0:
                if coef > 0:
                    result.append(f'{coef}{variables}')
                else:
                    result.append(f'{coef}{variables}')
        else:
            # Subsequent terms
            if coef == 1 and variables:
                result.append('+' + variables)
            elif coef == -1 and variables:
                result.append('-' + variables)
            elif coef == 1 and not variables:
                result.append('+1')
            elif coef == -1 and not variables:
                result.append('-1')
            elif coef > 0:
                result.append(f'+{coef}{variables}')
            else:
                result.append(f'{coef}{variables}')

    return ''.join(result)

