def count_up_to(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    result = []
    for i in range(2, n):
        if is_prime(i):
            result.append(i)
    return result

def is_balanced(s, pairs):
    if not s:
        return True

    # Create mapping of opening to closing characters
    open_to_close = {}
    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        open_to_close[open_char] = close_char

    # Stack to track opening characters
    stack = []

    for char in s:
        # If character is an opening character
        if char in open_to_close:
            stack.append(char)
        # If character is a closing character
        elif char in open_to_close.values():
            # Stack is empty or closing character doesn't match last opening character
            if not stack or open_to_close[stack.pop()] != char:
                return False

    # All characters should be matched (stack should be empty)
    return len(stack) == 0

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    if not nums:
        return []

    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)

def is_valid(identifier):
    # Check if identifier is empty
    if not identifier:
        return False

    # Check first character - must be alpha, underscore, or dollar sign
    first_char = identifier[0]
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Check remaining characters - must be alpha, digit, underscore, or dollar sign
    for i in range(1, len(identifier)):
        char = identifier[i]
        if not (char.isalnum() or char == '_' or char == '$'):
            return False

    return True

def amazon_check_mate(amazon_pos, white_king_pos):
    # Convert chess notation to 0-indexed coordinates
    def chess_to_coord(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    # Get all attack positions for amazon
    def get_amazon_attacks(amazon_coord):
        row, col = amazon_coord
        attacks = set()

        # Queen moves (row, column, diagonals)
        # Horizontal and vertical
        for i in range(8):
            attacks.add((row, i))
            attacks.add((i, col))

        # Diagonals
        for i in range(8):
            if 0 <= row + i < 8 and 0 <= col + i < 8:
                attacks.add((row + i, col + i))
            if 0 <= row + i < 8 and 0 <= col - i < 8:
                attacks.add((row + i, col - i))
            if 0 <= row - i < 8 and 0 <= col + i < 8:
                attacks.add((row - i, col + i))
            if 0 <= row - i < 8 and 0 <= col - i < 8:
                attacks.add((row - i, col - i))

        # Knight moves (L-shaped)
        knight_moves = [
            (-2, -1), (-2, 1), (-1, -2), (-1, 2),
            (1, -2), (1, 2), (2, -1), (2, 1)
        ]
        for dr, dc in knight_moves:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < 8 and 0 <= new_col < 8:
                attacks.add((new_row, new_col))

        return attacks

    # Get all adjacent squares to a king
    def get_king_adjacent(king_coord):
        row, col = king_coord
        adjacent = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < 8 and 0 <= new_col < 8:
                    adjacent.append((new_row, new_col))
        return adjacent

    # Parse input
    amazon_coord = chess_to_coord(amazon_pos)
    white_king_coord = chess_to_coord(white_king_pos)

    # Get amazon attack set
    amazon_attacks = get_amazon_attacks(amazon_coord)

    # Get adjacent squares to white king
    white_king_adjacent = set(get_king_adjacent(white_king_coord))

    # Initialize result counts
    counts = [0, 0, 0, 0]

    # Check all possible black king positions
    for row in range(8):
        for col in range(8):
            # Skip if position is occupied by white king or amazon
            if (row, col) == white_king_coord or (row, col) == amazon_coord:
                continue

            # Skip if position is adjacent to white king
            if (row, col) in white_king_adjacent:
                continue

            # Check if black king is attacked by amazon
            is_attacked = (row, col) in amazon_attacks

            # Check if black king has valid move
            has_valid_move = False
            black_king_coord = (row, col)
            king_adjacent = get_king_adjacent(black_king_coord)

            for adj_row, adj_col in king_adjacent:
                # Check if adjacent square is valid
                if (adj_row, adj_col) == white_king_coord or (adj_row, adj_col) == amazon_coord:
                    continue
                if (adj_row, adj_col) in white_king_adjacent:
                    continue
                if (adj_row, adj_col) in amazon_attacks:
                    continue

                # If we reach here, the move is valid
                has_valid_move = True
                break

            # Classify state
            if is_attacked:
                if has_valid_move:
                    counts[1] += 1  # Check
                else:
                    counts[0] += 1  # Checkmate
            else:
                if has_valid_move:
                    counts[3] += 1  # Safe
                else:
                    counts[2] += 1  # Stalemate

    return counts

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            integer_digits.append(temp % base)
            temp //= base
        integer_digits.reverse()

    # Convert fractional part
    fractional_part = number - integer_part
    fractional_digits = []

    if fractional_part > 0 and decimals > 0:
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            fractional_digits.append(digit)
            fractional_part -= digit

    # Convert digits to characters
    def digit_to_char(digit):
        if digit < 10:
            return str(digit)
        else:
            return chr(ord('A') + digit - 10)

    # Build integer part string
    if integer_digits:
        integer_str = ''.join(digit_to_char(d) for d in integer_digits)
    else:
        integer_str = '0'

    # Build fractional part string
    if fractional_digits:
        fractional_str = ''.join(digit_to_char(d) for d in fractional_digits)
        result = integer_str + '.' + fractional_str
    else:
        result = integer_str

    # Handle negative sign
    if negative:
        result = '-' + result

    return result

def vowel_indices(word):
    vowels = 'aeiouyAEIOUY'
