def calculate_specificity(selector):
    id_count = 0
    class_count = 0
    tagname_count = 0

    parts = selector.split()

    for part in parts:
        if '#' in part:
            id_count += 1
            part = part.split('#')[0]

        class_count += part.count('.')

        if part.count('.') > 0:
            parts_after_dot = part.split('.')
            tagname_candidate = parts_after_dot[0]
        else:
            tagname_candidate = part

        if tagname_candidate:
            tagname_count += 1

    return (id_count, class_count, tagname_count)


def compare(selector1, selector2):
    spec1 = calculate_specificity(selector1)
    spec2 = calculate_specificity(selector2)

    if spec1 > spec2:
        return selector1
    else:
        return selector2

def is_balanced(s, pairs):
    if not pairs:
        return True

    bracket_map = {}
    opening_brackets = set()

    for i in range(0, len(pairs), 2):
        if i + 1 < len(pairs):
            opening = pairs[i]
            closing = pairs[i + 1]
            bracket_map[closing] = opening
            opening_brackets.add(opening)

    stack = []

    for char in s:
        if char in opening_brackets:
            stack.append(char)
        elif char in bracket_map:
            if not stack:
                return False
            last_open = stack.pop()
            if last_open != bracket_map[char]:
                return False

    return len(stack) == 0

def amazon_check_mate(king, amazon):
    # Convert chess notation to coordinates (0-7, 0-7)
    def parse_pos(pos):
        col = ord(pos[0]) - ord('a')
