    # Check if a position is on the board
    def is_valid(col, row):
        return 0 <= col < 8 and 0 <= row < 8

    # Get all squares attacked by amazon (ignoring blocking)
    def get_amazon_attacks(amazon_col, amazon_row):
        attacks = set()

        # Queen-like moves (horizontal, vertical, diagonal)
        for dc in [-1, 0, 1]:
            for dr in [-1, 0, 1]:
                if dc == 0 and dr == 0:
                    continue
                c, r = amazon_col, amazon_row
                while True:
                    c += dc
                    r += dr
                    if not is_valid(c, r):
                        break
                    attacks.add((c, r))

        # Knight-like moves (L-shaped)
        knight_moves = [
            (2, 1), (2, -1), (-2, 1), (-2, -1),
            (1, 2), (1, -2), (-1, 2), (-1, -2)
        ]
        for dc, dr in knight_moves:
            c = amazon_col + dc
            r = amazon_row + dr
            if is_valid(c, r):
                attacks.add((c, r))

        return attacks

    # Get all squares adjacent to a position (including diagonals)
    def get_adjacent(col, row):
        adjacent = set()
        for dc in [-1, 0, 1]:
            for dr in [-1, 0, 1]:
                if dc == 0 and dr == 0:
                    continue
                c = col + dc
                r = row + dr
                if is_valid(c, r):
                    adjacent.add((c, r))
        return adjacent

    # Check if square is attacked by amazon (considering white king blocks)
    def is_attacked(black_col, black_row):
        # Amazon attacks
        attacked = False

        # Check queen-like attacks (with blocking by white king)
        for dc in [-1, 0, 1]:
            for dr in [-1, 0, 1]:
                if dc == 0 and dr == 0:
                    continue
                c, r = amazon_col, amazon_row
                while True:
                    c += dc
                    r += dr
                    if not is_valid(c, r):
                        break
                    if (c, r) == (black_col, black_row):
                        attacked = True
                        break
                    if (c, r) == (king_col, king_row):
                        break  # White king blocks

        # Check knight attacks (not blocked)
        if not attacked:
            knight_moves = [
                (2, 1), (2, -1), (-2, 1), (-2, -1),
                (1, 2), (1, -2), (-1, 2), (-1, -2)
            ]
            for dc, dr in knight_moves:
                c = amazon_col + dc
                r = amazon_row + dr
                if (c, r) == (black_col, black_row):
                    attacked = True
                    break

        return attacked

    # Parse positions
    king_col, king_row = parse_pos(king)
    amazon_col, amazon_row = parse_pos(amazon)

    # Get squares adjacent to white king (black king cannot be here)
    king_adjacent = get_adjacent(king_col, king_row)

    # Results for each scenario
    checkmate_count = 0
    check_count = 0
    stalemate_count = 0
    safe_count = 0

    # Check all possible black king positions
    for col in range(8):
        for row in range(8):
            # Black king cannot be on white king or amazon square
            if (col, row) == (king_col, king_row):
                continue
            if (col, row) == (amazon_col, amazon_row):
                continue

            # Black king cannot be adjacent to white king
            if (col, row) in king_adjacent:
                continue

            # Check if black king is under amazon's attack
            in_check = is_attacked(col, row)

            # Find all valid moves for black king
            valid_moves = 0
            for dc in [-1, 0, 1]:
                for dr in [-1, 0, 1]:
                    if dc == 0 and dr == 0:
                        continue
                    new_col = col + dc
                    new_row = row + dr
                    if not is_valid(new_col, new_row):
                        continue
                    # Cannot move to white king or amazon
                    if (new_col, new_row) == (king_col, king_row):
                        continue
                    if (new_col, new_row) == (amazon_col, amazon_row):
                        continue
                    # Cannot move adjacent to white king
                    if (new_col, new_row) in king_adjacent:
                        continue
                    # Cannot move to amazon's attacked square
                    if is_attacked(new_col, new_row):
                        continue
                    valid_moves += 1

            # Classify the position
            if in_check:
                if valid_moves == 0:
                    checkmate_count += 1
                else:
                    check_count += 1
            else:
                if valid_moves == 0:
                    stalemate_count += 1
                else:
                    safe_count += 1

    return [checkmate_count, check_count, stalemate_count, safe_count]

