def compare(selector1, selector2):
    def calculate_specificity(selector):
        ids = 0
        classes = 0
        tags = 0

        # Split by spaces to get individual components
        parts = selector.split()

        for part in parts:
            if not part or part == '*':
                continue

            # Count IDs (#)
            ids += part.count('#')

            # Count classes (.)
            classes += part.count('.')

            # Check if there's a tag name
            # A tag name is the first part before any # or .
            tag_part = part
            for char in ['#', '.']:
                idx = tag_part.find(char)
                if idx != -1:
                    tag_part = tag_part[:idx]

            # If tag_part is not empty, it's a tag
            if tag_part:
                tags += 1

        return (ids, classes, tags)

    spec1 = calculate_specificity(selector1)
    spec2 = calculate_specificity(selector2)

    # Compare: (ids, classes, tags) - tuples compare lexicographically
    if spec1 > spec2:
        return selector1
    elif spec2 > spec1:
        return selector2
    else:
        # If equal, return the later selector (selector2)
        return selector2

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    return sorted(nums, key=digit_sum)

from functools import lru_cache

def almost_everywhere_zero(n, k):
    s = str(n)
    n_digits = len(s)

    @lru_cache(None)
    def dp(pos, cnt, tight, started):
        if pos == n_digits:
            return 1 if cnt == k and started else 0

        limit = int(s[pos]) if tight else 9
        total = 0

        for d in range(0, limit + 1):
            new_tight = tight and (d == limit)
            new_started = started or (d > 0)

            if d == 0:
                # Zero digit doesn't increase non-zero count
                new_cnt = cnt
            else:
                # Non-zero digit increases the count
                new_cnt = cnt + 1

            if new_cnt <= k:
                total += dp(pos + 1, new_cnt, new_tight, new_started)

        return total

    return dp(0, 0, True, False)

