from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    # Validate input is a list
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list")

    # Validate all elements are integers (excluding booleans, since bool is subclass of int)
    for num in numbers:
        if not isinstance(num, int) or isinstance(num, bool):
            raise TypeError("All elements must be integers")

    # Handle empty list
    if not numbers:
        return (0, 1)

    # Calculate sum
    total_sum = sum(numbers)

    # Calculate product
    product = 1
    for num in numbers:
        product *= num

    # Return as tuple - explicitly ensure tuple type
    return tuple([total_sum, product])

def is_balanced(string, pairs):
    if not string or not pairs:
        return True

    # Create mapping of opening to closing characters
    pair_map = {}
    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        pair_map[open_char] = close_char

    # Stack to track opening characters
    stack = []

    for char in string:
        # If character is an opening character
        if char in pair_map:
            # If it's also a closing character (same char for open and close)
            if char in pair_map and pair_map[char] == char:
                # For identical pairs, we need to check if we can close it
                if stack and stack[-1] == char:
                    stack.pop()
                else:
                    stack.append(char)
            else:
                # Regular opening character
                stack.append(char)
        # If character is a closing character
        elif char in pair_map.values():
            # Find which opening character this closing character matches
            matching_open = None
            for open_char, close_char in pair_map.items():
                if close_char == char:
                    matching_open = open_char
                    break

            # If no matching opening character or doesn't match the last one
            if not stack or stack[-1] != matching_open:
                return False
            stack.pop()

    # String is balanced if stack is empty
    return len(stack) == 0

def reverse_delete(s, c):
    # Remove all characters in s that are equal to any character in c
    result = ''.join(char for char in s if char not in c)

    # Check if the result string is palindrome
    is_palindrome = result == result[::-1]

    return (result, is_palindrome)

