def count_divisors(n: int) -> int:
    if n <= 0:
        raise ValueError("Input must be a positive integer.")

    count = 0
    sqrt_n = int(math.isqrt(n))

    for i in range(1, sqrt_n + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2

    return count

