def choose(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry property: C(n,k) = C(n,n-k)
    k = min(k, n - k)

    # Calculate C(n,k) = n! / (k! * (n-k)!)
    # Using the iterative approach to avoid large factorials
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

import ast

def poohbear(code):
    # Input sanitization - handle list-string format if needed
    if isinstance(code, str):
        try:
            parsed = ast.literal_eval(code)
            if isinstance(parsed, list) and len(parsed) > 0:
                code = parsed[0]
        except:
            pass
    elif isinstance(code, list) and len(code) > 0:
        code = code[0]

    code = str(code)

    # Filter to only valid commands
    valid_commands = set(['+', '-', '>', '<', 'c', 'p', 'W', 'E', 'P', 'N', 
                          'T', 'Q', 'U', 'L', 'I', 'V', 'A', 'B', 'Y', 'D'])
    filtered_code = ''.join(c for c in code if c in valid_commands)

    # Pre-process loops to map W-E pairs
    loop_map = {}
    stack = []

    for i, cmd in enumerate(filtered_code):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                w_idx = stack.pop()
                loop_map[w_idx] = i
                loop_map[i] = w_idx

    # Initialize VM state
    tape = {}  # Infinite tape using dict for sparse storage
    ptr = 0  # Cell pointer
    copy_buffer = 0  # Copy buffer
    pc = 0  # Program counter
    output = []  # Output buffer

    def wrap(value):
        return value % 256

    while pc < len(filtered_code):
        cmd = filtered_code[pc]
        current_val = tape.get(ptr, 0)

        if cmd == '+':
            tape[ptr] = wrap(current_val + 1)
            pc += 1
        elif cmd == '-':
            tape[ptr] = wrap(current_val - 1)
            pc += 1
        elif cmd == '>':
            ptr += 1
            pc += 1
        elif cmd == '<':
            ptr -= 1
            pc += 1
        elif cmd == 'c':
            copy_buffer = current_val
            pc += 1
        elif cmd == 'p':
            tape[ptr] = copy_buffer
            pc += 1
        elif cmd == 'W':
            if current_val == 0:
                pc = loop_map[pc] + 1
            else:
                pc += 1
        elif cmd == 'E':
            if current_val != 0:
                pc = loop_map[pc]
            else:
                pc += 1
        elif cmd == 'P':
            output.append(chr(current_val))
            pc += 1
        elif cmd == 'N':
            output.append(str(current_val))
            pc += 1
        elif cmd == 'T':
            tape[ptr] = wrap(current_val * 2)
            pc += 1
        elif cmd == 'Q':
            tape[ptr] = wrap(current_val * current_val)
            pc += 1
        elif cmd == 'U':
            tape[ptr] = wrap(int(current_val ** 0.5))
            pc += 1
        elif cmd == 'L':
            tape[ptr] = wrap(current_val + 2)
            pc += 1
        elif cmd == 'I':
            tape[ptr] = wrap(current_val - 2)
            pc += 1
        elif cmd == 'V':
            tape[ptr] = wrap(current_val // 2)
            pc += 1
        elif cmd == 'A':
            tape[ptr] = wrap(current_val + copy_buffer)
            pc += 1
        elif cmd == 'B':
            tape[ptr] = wrap(current_val - copy_buffer)
            pc += 1
        elif cmd == 'Y':
            tape[ptr] = wrap(current_val * copy_buffer)
            pc += 1
        elif cmd == 'D':
            if copy_buffer != 0:
                tape[ptr] = wrap(current_val // copy_buffer)
            pc += 1
        else:
            pc += 1

    return ''.join(output)

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
