def poohbear(code):
    MAX_ITERATIONS = 1000000

    # Pre-process to build W-E maps
    w_to_e = {}
    e_to_w = {}
    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                w_pos = stack.pop()
                w_to_e[w_pos] = i
                e_to_w[i] = w_pos

    # Initialize state
    memory = {}
    pointer = 0
    copied_value = 0
    ip = 0
    output = []

    def wrap(val):
        return val % 256

    def floor_div(a, b):
        if b == 0:
            return 0
        return a // b

    iterations = 0
    while ip < len(code) and iterations < MAX_ITERATIONS:
        iterations += 1
        cmd = code[ip]

        if cmd == '+':
            memory[pointer] = wrap(memory.get(pointer, 0) + 1)
            ip += 1
        elif cmd == '-':
            memory[pointer] = wrap(memory.get(pointer, 0) - 1)
            ip += 1
        elif cmd == '>':
            pointer += 1
            ip += 1
        elif cmd == '<':
            pointer -= 1
            ip += 1
        elif cmd == 'c':
            copied_value = memory.get(pointer, 0)
            ip += 1
        elif cmd == 'p':
            memory[pointer] = copied_value
            ip += 1
        elif cmd == 'W':
            if ip in w_to_e:
                if memory.get(pointer, 0) == 0:
                    ip = w_to_e[ip] + 1
                else:
                    ip += 1
            else:
                ip += 1
        elif cmd == 'E':
            if ip in e_to_w:
                if memory.get(pointer, 0) != 0:
                    ip = e_to_w[ip]
                else:
                    ip += 1
            else:
                ip += 1
        elif cmd == 'P':
            output.append(chr(memory.get(pointer, 0)))
            ip += 1
        elif cmd == 'N':
            output.append(str(memory.get(pointer, 0)))
            ip += 1
        elif cmd == 'T':
            memory[pointer] = wrap(memory.get(pointer, 0) * 2)
            ip += 1
        elif cmd == 'Q':
            memory[pointer] = wrap(memory.get(pointer, 0) ** 2)
            ip += 1
        elif cmd == 'U':
            memory[pointer] = wrap(int(memory.get(pointer, 0) ** 0.5))
            ip += 1
        elif cmd == 'L':
            memory[pointer] = wrap(memory.get(pointer, 0) + 2)
            ip += 1
        elif cmd == 'I':
            memory[pointer] = wrap(memory.get(pointer, 0) - 2)
            ip += 1
        elif cmd == 'V':
            memory[pointer] = floor_div(memory.get(pointer, 0), 2)
            ip += 1
        elif cmd == 'A':
            memory[pointer] = wrap(memory.get(pointer, 0) + copied_value)
            ip += 1
        elif cmd == 'B':
            memory[pointer] = wrap(memory.get(pointer, 0) - copied_value)
            ip += 1
        elif cmd == 'Y':
            memory[pointer] = wrap(memory.get(pointer, 0) * copied_value)
            ip += 1
        elif cmd == 'D':
            memory[pointer] = floor_div(memory.get(pointer, 0), copied_value)
            ip += 1
        else:
            ip += 1

    return ''.join(output)

def fib4(n: int):
    if n == 0 or n == 1 or n == 3:
        return 0
    if n == 2:
        return 2

    # Initialize the first four values
    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute fib4(n)
    for i in range(4, n + 1):
        next_val = a + b + c + d
        a, b, c, d = b, c, d, next_val

    return d

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
integers that are prime numbers and less than n.
for example:
count_up_to(5) => [2,3]
count_up_to(11) => [2,3,5,7]
count_up_to(0) => []
