def valid_mersenne(n):
    if n <= 0:
        return False

    # Check if n is a prime number
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    if not is_prime(n):
        return False

    # Calculate Mersenne number 2^n - 1
    mersenne = (1 << n) - 1  # Equivalent to 2**n - 1

    # Check if the Mersenne number is prime
    def is_mersenne_prime(m):
        if m < 2:
            return False
        if m == 2:
            return True
        if m % 2 == 0:
            return False

        # For Mersenne numbers, we can use Miller-Rabin or trial division up to sqrt(m)
        # Given that n is prime, we only need to check divisibility
        i = 3
        while i * i <= m:
            if m % i == 0:
                return False
            i += 2
        return True

    return is_mersenne_prime(mersenne)

