    # Check if n is a perfect square
    if is_perfect_square(n):
        return 1

    # Check if n can be written as sum of 2 perfect squares
    if is_sum_of_two_squares(n):
        return 2

    # Apply Legendre's three square theorem
    # If n = 4^k * (8m + 7), then it requires 4 squares
    temp = n
