def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    root = int(n ** 0.5)
    return root * root == n

def is_sum_of_two_squares(n):
    # Check if n = a^2 + b^2 for some integers a, b >= 0
    max_a = int(n ** 0.5)
    for a in range(1, max_a + 1):
        b_squared = n - a * a
        if is_perfect_square(b_squared):
            return True
    return False

