    dp[0] = 0

    for i in range(1, n + 1):
        # For each possible ending position j (0-indexed)
        for j in range(i):
            # If substring from j to i-1 is palindrome
            if is_palindrome[j][i - 1]:
                dp[i] = min(dp[i], dp[j] + 1)

    print(dp[n])

