import re
from collections import defaultdict

def simplify(expression):
    if not expression:
        return ""

    # Split by + and - signs, keeping the signs
    # We need to be careful about the first term which might not have a leading +
    terms = re.findall(r'[+-]?[^+-]+', expression)

    # Dictionary to store normalized monomials and their coefficients
    monomials = defaultdict(int)

    for term in terms:
        # Determine the sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Parse coefficient and variable part
        # Find where the coefficient ends (before the first letter)
        coeff_str = ""
        var_part = term

        for i, char in enumerate(term):
            if char.isalpha():
                coeff_str = term[:i]
                var_part = term[i:]
                break
        else:
            # No letters found, whole term is coefficient
            coeff_str = term
            var_part = ""

        # If coefficient is empty, it's 1 or -1
        if not coeff_str:
            coefficient = sign * 1
        else:
            coefficient = sign * int(coeff_str)

        # Normalize variable part by sorting letters
        if var_part:
            normalized_var = ''.join(sorted(var_part))
            monomials[normalized_var] += coefficient
        else:
            # Constant term (no variables)
            monomials[''] += coefficient

    # Remove terms with zero coefficient
    monomials = {k: v for k, v in monomials.items() if v != 0}

    # Sort terms
    # Primary key: number of variables
    # Secondary key: lexicographic order of variable string
    sorted_terms = sorted(monomials.items(), key=lambda x: (len(x[0]), x[0]))

    # Format result
    result = []
    first = True

    for var, coeff in sorted_terms:
        if coeff == 0:
            continue

        # Handle the coefficient
        if coeff == 1:
            coeff_str = ""
        elif coeff == -1:
            coeff_str = "-"
        else:
            coeff_str = str(coeff)

        # Handle variable part
        if var == "":
            var_str = ""
        else:
            var_str = var

        term_str = coeff_str + var_str

        # First term: no leading +
        if first:
            result.append(term_str)
            first = False
        else:
            # Positive coefficient: prefix with +
            if coeff > 0:
                result.append("+" + term_str)
            else:
                result.append(term_str)

    # Join the terms
    if not result:
        return "0"

    return "".join(result)

def valid_mersenne(n):
    # First check if n is prime
    if n < 2:
        return False

    # Check if n is prime
    if n == 2:
        is_prime_n = True
    elif n % 2 == 0:
        is_prime_n = False
    else:
        is_prime_n = True
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                is_prime_n = False
                break

    if not is_prime_n:
        return False

    # If n is prime, check if 2^n - 1 is prime
    # For small values, we can use deterministic Miller-Rabin
    # For larger values, we'll use probabilistic Miller-Rabin
    mersenne = (1 << n) - 1  # This is 2^n - 1

    # For numbers up to 2000, we can use a simple primality check
    # But since 2^n - 1 can be very large, we use Miller-Rabin
    return miller_rabin(mersenne, 5)

def miller_rabin(n, k):
    # Miller-Rabin primality test
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    # Write n-1 as d * 2^r
    r = 0
    d = n - 1
    while d % 2 == 0:
        d //= 2
        r += 1

    # Witness loop
    import random
    for _ in range(k):
        a = random.randrange(2, n - 1)
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into terms
    terms = re.findall(r'[+-]?\w+', expression)

    # Dictionary to store monomials and their coefficients
    monomial_dict = defaultdict(int)

    for term in terms:
        # Separate coefficient from variables
        if term[0] == '-':
            if len(term) > 1 and term[1].isalpha():
                coeff = -1
                variables = term[1:]
            else:
                # This is a coefficient like "-3"
                coeff_str = re.match(r'-\d+', term).group()
                coeff = int(coeff_str)
                variables = term[len(coeff_str):]
        elif term[0] == '+':
            if len(term) > 1 and term[1].isalpha():
                coeff = 1
                variables = term[1:]
            else:
                # This is a coefficient like "+3"
                coeff_str = re.match(r'\+\d+', term).group()
                coeff = int(coeff_str)
                variables = term[len(coeff_str):]
        else:
            # Positive coefficient or just variables
            if term.isalpha():
                coeff = 1
                variables = term
            else:
                # Find where coefficient ends
                i = 0
                while i < len(term) and (term[i].isdigit() or term[i] == '-'):
                    i += 1
                if i == 0:
                    coeff = 1
                    variables = term
                else:
                    coeff = int(term[:i])
                    variables = term[i:]

        # Normalize the variables (sort them)
        sorted_variables = ''.join(sorted(variables))

        # Add to dictionary
        monomial_dict[sorted_variables] += coeff

    # Remove zero coefficients
    monomial_dict = {k: v for k, v in monomial_dict.items() if v != 0}

    # Sort monomials
    sorted_monomials = sorted(monomial_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Format the result
    result_parts = []
    for monomial, coeff in sorted_monomials:
        if coeff == 1 and monomial != '':
            result_parts.append('+' + monomial)
        elif coeff == -1 and monomial != '':
            result_parts.append('-' + monomial)
        elif coeff > 0:
            result_parts.append('+' + str(coeff) + monomial)
        else:
            result_parts.append(str(coeff) + monomial)

    # Join and clean up
    result = ''.join(result_parts)

    # Remove leading '+' if present
    if result.startswith('+'):
        result = result[1:]

    return result

