def choose(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry property: C(n,k) = C(n,n-k)
    k = min(k, n - k)

    # Calculate C(n,k) = n! / (k! * (n-k)!)
    # Using the iterative approach to avoid large factorials
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

