def parse_int(text):
    # Mapping of number words to values
    ones = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9,
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16,
        'seventeen': 17, 'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    multipliers = {
        'hundred': 100,
        'thousand': 1000,
        'million': 1000000
    }

    # Special case for zero
    if text.lower() == 'zero':
        return 0

    # Normalize text: lowercase, replace hyphens with spaces
    text = text.lower().replace('-', ' ')
    words = text.split()

    # Remove 'and' words (they don't contribute to value)
    words = [w for w in words if w != 'and']

    total = 0
    current = 0

    for word in words:
        if word in ones:
            current += ones[word]
        elif word in tens:
            current += tens[word]
        elif word == 'hundred':
            current *= 100
        elif word == 'thousand':
            total += current * 1000
            current = 0
        elif word == 'million':
            total += current * 1000000
            current = 0

    total += current
    return total

