def solution(text, markers):
    lines = text.split('\n')
    result_lines = []

    for line in lines:
        marker_pos = len(line)  # Default: no marker found

        # Find the first occurrence of any marker
        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < marker_pos:
                marker_pos = pos

        # Truncate at the first marker position (if found)
        if marker_pos < len(line):
            line = line[:marker_pos]

        # Strip trailing whitespace
        line = line.rstrip()

        result_lines.append(line)

    return '\n'.join(result_lines)

