import sys
from collections import defaultdict

def parse_url(url):
    # Remove "http://"
    url = url[7:]

    # Split by first slash to get hostname and path
    if '/' in url:
        hostname, path = url.split('/', 1)
        # Normalize path: ensure it starts with / if it's not empty
        if path:
            path = '/' + path
        else:
            path = ''
    else:
        hostname = url
        path = ''

    return hostname, path

def normalize_path(path):
    # Remove trailing slash for comparison purposes, but keep track of whether it was there
    if path == '':
        return ''
    elif path == '/':
        return '/'
    else:
        # Remove trailing slash if present
        if path.endswith('/'):
            return path[:-1]
        else:
            return path

def hash_path_set(paths):
    # Create a sorted tuple of normalized paths for hashing
    normalized = [normalize_path(p) for p in paths]
    normalized.sort()
    return tuple(normalized)

def main():
    data = sys.stdin.read()
    lines = data.strip().split('\n')

    n = int(lines[0])
    urls = lines[1:n+1]

    # Group URLs by hostname
    hostname_to_paths = defaultdict(set)

    for url in urls:
        hostname, path = parse_url(url)
        hostname_to_paths[hostname].add(path)

    # Create mapping from hash to list of hostnames
    hash_to_hostnames = defaultdict(list)

    for hostname, paths in hostname_to_paths.items():
        path_hash = hash_path_set(paths)
        hash_to_hostnames[path_hash].append(hostname)

    # Find groups with more than one hostname
    groups = []
    for hostnames in hash_to_hostnames.values():
        if len(hostnames) > 1:
            groups.append(sorted(hostnames))

    # Sort groups lexicographically
    groups.sort()

    # Output
    print(len(groups))
    for group in groups:
        # Convert hostnames to full URLs
        full_urls = ['http://' + hostname for hostname in group]
        print(' '.join(full_urls))

