def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    n = d

    # Check for factor of 2 separately for efficiency
    if n % 2 == 0:
        while n % 2 == 0:
            n //= 2
        result -= result // 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            while n % i == 0:
                n //= i
            result -= result // i
        i += 2

    # If remaining n is a prime greater than 2
    if n > 1:
        result -= result // n

    return result

def sum_of_squares(n):
    def is_perfect_square(x):
        if x < 0:
            return False
        if x == 0:
            return True
        root = int(x**0.5)
        return root * root == x

    # Check if n is a perfect square (answer = 1)
    if is_perfect_square(n):
        return 1

    # Check if n can be written as sum of 2 squares (answer = 2)
    # Iterate through all possible values of a from 0 to sqrt(n)
    root = int(n**0.5)
    for a in range(root + 1):
        remainder = n - a * a
        if is_perfect_square(remainder):
            return 2

    # Check Legendre's Three-Square Theorem
    # n = 4^a(8k+7) means answer is 4, otherwise answer is 3
    temp = n
    while temp % 4 == 0:
        temp //= 4
    if temp % 8 == 7:
        return 4

    return 3

def order_by_points(nums):
    """
    Create a function that arranges the provided list of integers
    in ascending order based on their digit sums.
    Note: when multiple elements share the same digit sum,
    arrange them according to their original positions in the list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)

