import heapq

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])

    edges = []
    for i in range(1, n):
        a, b, c = map(int, lines[i].split())
        edges.append((a, b, c))

    x = []
    for i in range(n):
        x.append(int(lines[n + i]))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for a, b, c in edges:
        adj[a].append((b, c))
        adj[b].append((a, c))

    # Compute all-pairs maximum edge weight on shortest paths
    g = [[0] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        # Modified Dijkstra to find shortest paths with maximum edge weight
        dist = [float('inf')] * (n + 1)
        max_edge = [0] * (n + 1)
        dist[start] = 0
        max_edge[start] = 0

        # Priority queue: (max_edge_weight, node)
        pq = [(0, start)]

        while pq:
            max_w, u = heapq.heappop(pq)

            if max_w > max_edge[u]:
                continue

            for v, w in adj[u]:
                new_max = max(max_edge[u], w)
                if new_max < max_edge[v]:
                    max_edge[v] = new_max
                    dist[v] = dist[u] + 1
                    heapq.heappush(pq, (new_max, v))

        # For each node, we store the maximum edge weight on the shortest path
        for i in range(1, n + 1):
            if dist[i] < float('inf'):
                g[start][i] = max_edge[i]

    # Binary search on the answer
    def can_achieve(min_val):
        # Create a bipartite graph for matching
        # Left side: nodes 1 to n
        # Right side: elements 1 to n
        # Edge exists if g[i][j] >= min_val

        # Build adjacency list for the bipartite graph
        adj_match = [[] for _ in range(n * 2 + 2)]
        source = n * 2 + 1
        sink = n * 2 + 2

        # Connect source to left nodes (1 to n)
        for i in range(1, n + 1):
            adj_match[source].append((i, 1))
            adj_match[i].append((source, 0))

        # Connect right nodes (n+1 to 2*n) to sink
        for i in range(1, n + 1):
            adj_match[n + i].append((sink, x[i-1]))
            adj_match[sink].append((n + i, 0))

        # Connect left to right if g[i][j] >= min_val
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if g[i][j] >= min_val:
                    adj_match[i].append((n + j, 1))
                    adj_match[n + j].append((i, 0))

        # Find maximum flow using Ford-Fulkerson with BFS
        def bfs():
            parent = [-1] * (n * 2 + 3)
            visited = [False] * (n * 2 + 3)
            queue = deque([source])
            visited[source] = True

            while queue:
                u = queue.popleft()
                for v, capacity in adj_match[u]:
                    if not visited[v] and capacity > 0:
                        visited[v] = True
                        parent[v] = u
                        queue.append(v)
                        if v == sink:
                            return True
            return False

        def dfs(u, flow):
            if u == sink:
                return flow

            for i in range(len(adj_match[u])):
                v, capacity = adj_match[u][i]
                if capacity > 0 and not visited[v]:
                    visited[v] = True
                    result = dfs(v, min(flow, capacity))
                    if result > 0:
                        adj_match[u][i] = (v, capacity - result)
                        for j in range(len(adj_match[v])):
                            if adj_match[v][j][0] == u:
                                adj_match[v][j] = (u, adj_match[v][j][1] + result)
                                break
                        return result
            return 0

        # Ford-Fulkerson algorithm
        max_flow = 0
        while True:
            visited = [False] * (n * 2 + 3)
            visited[source] = True
            if not bfs():
                break

            flow = float('inf')
            current = sink
            while current != source:
                prev_node = parent[current]
                for i, (v, c) in enumerate(adj_match[prev_node]):
                    if v == current:
                        flow = min(flow, c)
                        break
                current = prev_node

            if flow > 0:
                max_flow += flow
                current = sink
                while current != source:
                    prev_node = parent[current]
                    for i, (v, c) in enumerate(adj_match[prev_node]):
                        if v == current:
                            adj_match[prev_node][i] = (v, c - flow)
                            break
                    current = prev_node

        return max_flow == n

    # Binary search
    left, right = 0, 10000
    result = 0

    while left <= right:
        mid = (left + right) // 2
        if can_achieve(mid):
            result = mid
            left = mid + 1
        else:
            right = mid - 1

    print(result)

