def exchange_sort(arr):
    n = len(arr)
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """

    def to_float(value):
        """Convert any input to float, handling comma as decimal separator"""
        if isinstance(value, (int, float)):
            return float(value)
        elif isinstance(value, str):
            # Replace comma with period for decimal separator
            normalized_str = value.replace(',', '.')
            return float(normalized_str)
        else:
            raise TypeError("Unsupported type")

    # Convert both values to float for comparison
    a_float = to_float(a)
    b_float = to_float(b)

    # Compare with tolerance for floating point equality
    epsilon = 1e-9
    if abs(a_float - b_float) < epsilon:
        return None

    # Return the original value that is larger
    if a_float > b_float:
        return a
    else:
        return b

def choose(n, k):
    if k > n or k < 0:
        return 0

    if k == 0 or k == n:
        return 1

    # Use symmetry property to minimize calculations
    k = min(k, n - k)

    # Calculate using multiplicative formula
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

