def valid_mersenne(n):
    """Check if 2^n - 1 is a Mersenne prime"""
    # Handle edge cases
    if n < 2:
        return False

    # Necessary condition: n must be prime
    # For small n (up to 2000), trial division is efficient
    if n == 2:
        return True  # M_2 = 3 is prime
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False

    # Compute M_n = 2^n - 1
    m = (1 << n) - 1

    # Lucas-Lehmer test for Mersenne primes (works for n >= 3)
    s = 4
    for _ in range(n - 2):
        s = (s * s - 2) % m

    return s == 0

