def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    if n <= 1:
        return y
    if n == 2:
        return x
    if n % 2 == 0:
        return y

    limit = int(n**0.5) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return y

    return x

def differentiate(polynomial, x):
    # Normalize the polynomial string by replacing - with +-
    polynomial = polynomial.replace('-', '+-')
    if polynomial.startswith('+'):
        polynomial = polynomial[1:]

    terms = polynomial.split('+')

    # Parse each term and calculate its derivative
    total_derivative = 0

    for term in terms:
        if not term:
            continue

        # Handle the case where term is just a constant
        if 'x' not in term:
            # This is a constant term, its derivative is 0
            continue

        # Split the term to get coefficient and exponent
        if 'x^' in term:
            # Term is like "3x^2" or "-3x^2"
            parts = term.split('x^')
            coeff_str = parts[0]
            if coeff_str == '' or coeff_str == '+':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)
            exponent = int(parts[1])
        elif 'x' in term:
            # Term is like "3x" or "-3x" or "x" or "-x"
            if term == 'x':
                coeff = 1
                exponent = 1
            elif term == '-x':
                coeff = -1
                exponent = 1
            else:
                # Remove the 'x' to get coefficient
                coeff_str = term[:-1]
                if coeff_str == '' or coeff_str == '+':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str)
                exponent = 1
        else:
            # This shouldn't happen, but just in case
            continue

        # Apply power rule: d/dx(cx^n) = c*n*x^(n-1)
        if exponent == 0:
            # Constant term, derivative is 0
            continue
        else:
            new_coeff = coeff * exponent
            new_exponent = exponent - 1

            # Evaluate the derivative at x
            if new_exponent == 0:
                total_derivative += new_coeff
            else:
                total_derivative += new_coeff * (x ** new_exponent)

    return total_derivative

