def differentiate(polynomial, x):
    # Parse the polynomial into terms
    # Split by + and - signs, but keep the signs
    terms = re.findall(r'[+-]?[^+-]+', polynomial)

    total_derivative = 0

    for term in terms:
        term = term.strip()
        if not term:
            continue

        # Handle the sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Parse the term
        if 'x^' in term:
            # Format: [coefficient]x^[exponent]
            parts = term.split('x^')
            if parts[0] == '':
                coefficient = sign * 1
            else:
                coefficient = sign * int(parts[0])
            exponent = int(parts[1])
        elif 'x' in term:
            # Format: [coefficient]x or x
            if term == 'x':
                coefficient = sign * 1
                exponent = 1
            else:
                # Remove 'x' from the end
                coefficient_str = term[:-1]
                if coefficient_str == '':
                    coefficient = sign * 1
                elif coefficient_str == '-':
                    coefficient = sign * -1
                else:
                    coefficient = sign * int(coefficient_str)
                exponent = 1
        else:
            # Constant term
            coefficient = sign * int(term)
            exponent = 0

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent == 0:
            # Derivative of constant is 0
            derivative = 0
        else:
            derivative = exponent * coefficient * (x ** (exponent - 1))

        total_derivative += derivative

    return total_derivative

def is_balanced(s, pairs):
    # Create a mapping from closing characters to opening characters
    closing_to_opening = {}
    opening_to_closing = {}

    # Build the mapping from pairs
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        closing_to_opening[closing] = opening
        opening_to_closing[opening] = closing

    # Stack to keep track of opening characters
    stack = []

    for char in s:
        # If character is an opening character
        if char in opening_to_closing:
            stack.append(char)
        # If character is a closing character
        elif char in closing_to_opening:
            # If stack is empty or the top element doesn't match, it's unbalanced
            if not stack or stack[-1] != closing_to_opening[char]:
                return False
            # Pop the matching opening character
            stack.pop()

    # If stack is empty, all characters were properly matched
    return len(stack) == 0

