def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    n = d

    # Handle factor 2
    if n % 2 == 0:
        result = result // 2 * 1
        while n % 2 == 0:
            n //= 2

    # Handle odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result = result // i * (i - 1)
            while n % i == 0:
                n //= i
        i += 2

    # If n > 1 after all divisions, it's a prime factor
    if n > 1:
        result = result // n * (n - 1)

    return result

