import math

def converter(number, decimals=0, base=math.pi):
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36")

    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    if integer_part == 0:
        integer_result = '0'
    else:
        digits = []
        temp = integer_part
        while temp > 0:
            digits.append(temp % int(base))
            temp //= int(base)
        integer_result = ''.join(str(d) if d < 10 else chr(ord('A') + d - 10) for d in reversed(digits))

    # Convert fractional part
    fractional_part = number - integer_part
    if decimals == 0:
        fractional_result = ''
    else:
        digits = []
        temp = fractional_part
        for _ in range(decimals):
            temp *= base
            digit = int(temp)
            digits.append(digit)
            temp -= digit
        fractional_result = ''.join(str(d) if d < 10 else chr(ord('A') + d - 10) for d in digits)
        fractional_result = fractional_result.rstrip('0')  # Remove trailing zeros
        if not fractional_result:
            fractional_result = ''
        else:
            fractional_result = '.' + fractional_result

    # Combine results
    result = integer_result + fractional_result

    # Handle negative sign
    if negative:
        result = '-' + result

    # Handle case where result is just a decimal point (e.g., 0.5 in base 3)
    if result.startswith('.'):
        result = '0' + result

    return result

