    if not s:
        return False

    # Check the first character
    # Must be alpha, underscore, or dollar sign (cannot be digit)
    first_char = s[0]
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Check the remaining characters
    # Can be alpha, digit, underscore, or dollar sign
    for char in s[1:]:
        if not (char.isalnum() or char == '_' or char == '$'):
            return False

    return True

def getAllPrimeFactors(n):
    # Input validation
    if not isinstance(n, int) or n < 0:
        return []

    # Handle special cases
    if n == 0:
        return []
    elif n == 1:
        return [1]
    elif n == 2:
        return [2]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Input validation
    if not isinstance(n, int) or n < 0:
        return [[], []]

    # Handle special cases
    if n == 0:
        return [[], []]
    elif n == 1:
        return [[1], [1]]
    elif n == 2:
        return [[2], [1]]

    factors = getAllPrimeFactors(n)

    if not factors:
        return [[], []]

    unique_factors = []
    counts = []

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Input validation
    if not isinstance(n, int) or n < 0:
        return []

    # Handle special cases
    if n == 0:
        return []
    elif n == 1:
        return [1]
    elif n == 2:
        return [2]

    factor_count_pairs = getUniquePrimeFactorsWithCount(n)
    unique_factors = factor_count_pairs[0]
    counts = factor_count_pairs[1]

    products = []

    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False

        # Check odd divisors up to sqrt(num)
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    if is_prime(n):
        return x
    else:
        return y

def monotonic(l: list):
    # Handle edge cases
    if len(l) <= 1:
        return True

    # Determine the initial trend
    is_increasing = None

    # Check the first pair of elements that are not equal
    for i in range(len(l) - 1):
        if l[i] < l[i + 1]:
            is_increasing = True
            break
        elif l[i] > l[i + 1]:
            is_increasing = False
            break

    # If all elements are equal, it's monotonic
    if is_increasing is None:
        return True

    # Validate the entire sequence maintains the determined trend
    for i in range(len(l) - 1):
        if is_increasing:
            if l[i] > l[i + 1]:
                return False
        else:
            if l[i] < l[i + 1]:
                return False

    return True

