def differentiate(polynomial, point):
    # Parse the polynomial into terms
    # Handle the case where there's no + or - in the string
    if '+' in polynomial:
        terms = polynomial.split('+')
    else:
        terms = [polynomial]

    # Split terms by - (but keep the minus sign with negative terms)
    expanded_terms = []
    for term in terms:
        if '-' in term and term != '-':
            # Split by - but keep the minus sign
            parts = term.split('-')
            expanded_terms.append(parts[0])
            for part in parts[1:]:
                expanded_terms.append('-' + part)
        else:
            expanded_terms.append(term)

    # Remove empty strings
    expanded_terms = [term for term in expanded_terms if term]

    # Parse each term
    parsed_terms = []
    for term in expanded_terms:
        # Handle negative terms
        is_negative = False
        if term.startswith('-'):
            is_negative = True
            term = term[1:]

        # Parse coefficient and exponent
        if 'x^' in term:
            # Format: ax^n
            parts = term.split('x^')
            coeff_str = parts[0]
            if coeff_str == '':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)
            if is_negative:
                coeff = -coeff
            exponent = int(parts[1])
            parsed_terms.append((coeff, exponent))
        elif 'x' in term:
            # Format: ax or ax^1
            if term == 'x':
                coeff = 1
                exponent = 1
            elif term == '-x':
                coeff = -1
                exponent = 1
            else:
                coeff_str = term.replace('x', '')
                if coeff_str == '':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str)
                exponent = 1
            if is_negative:
                coeff = -coeff
            parsed_terms.append((coeff, exponent))
        else:
            # Format: constant term
            coeff = int(term)
            exponent = 0
            parsed_terms.append((coeff, exponent))

    # Differentiate each term
    derivative_terms = []
    for coeff, exponent in parsed_terms:
        if exponent == 0:
            # Derivative of constant is 0
            derivative_terms.append((0, 0))
        else:
            # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
            new_coeff = coeff * exponent
            new_exponent = exponent - 1
            derivative_terms.append((new_coeff, new_exponent))

    # Evaluate the derivative at the given point
    result = 0
    for coeff, exponent in derivative_terms:
        if exponent == 0:
            result += coeff
        else:
            result += coeff * (point ** exponent)

    return result

