def valid_mersenne(n):
    """
    Determines if a given number n is a Mersenne prime.
    A Mersenne prime is a prime number that can be written in the form 2^p - 1, where p is also a prime number.
    """
    if n < 3:  # Smallest Mersenne prime is 3 (2^2 - 1)
        return False

    # Check if n+1 is a power of 2
    m = n + 1
    if m <= 0 or (m & (m - 1)) != 0:
        return False

    # Find p such that 2^p = m
    p = 0
    temp = m
    while temp > 1:
        temp >>= 1
        p += 1

    # Check if p is prime
    if p < 2:
        return False
    if p == 2:
        return True
    if p % 2 == 0:
        return False

    i = 3
    while i * i <= p:
        if p % i == 0:
            return False
        i += 2

    return True

def format_duration(seconds):
    if seconds == 0:
        return "now"

    years = seconds // 31536000
    seconds %= 31536000

    days = seconds // 86400
    seconds %= 86400

    hours = seconds // 3600
    seconds %= 3600

    minutes = seconds // 60
    seconds %= 60

    parts = []

    if years:
        parts.append(f"{years} year{'s' if years > 1 else ''}")
    if days:
        parts.append(f"{days} day{'s' if days > 1 else ''}")
    if hours:
        parts.append(f"{hours} hour{'s' if hours > 1 else ''}")
    if minutes:
        parts.append(f"{minutes} minute{'s' if minutes > 1 else ''}")
    if seconds:
        parts.append(f"{seconds} second{'s' if seconds > 1 else ''}")

    if len(parts) == 1:
        return parts[0]

    return ", ".join(parts[:-1]) + " and " + parts[-1]

