def poohbear(code):
    # Preprocess code to find matching W/E pairs
    we_pairs = {}
    stack = []

    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                start = stack.pop()
                we_pairs[start] = i
                we_pairs[i] = start

    # Initialize memory and state
    memory = {}
    pointer = 0
    copied = 0
    ip = 0
    output = []

    while ip < len(code):
        char = code[ip]

        if char == '+':
            memory[pointer] = memory.get(pointer, 0) + 1
            memory[pointer] = memory[pointer] % 256

        elif char == '-':
            memory[pointer] = memory.get(pointer, 0) - 1
            memory[pointer] = memory[pointer] % 256

        elif char == '>':
            pointer += 1

        elif char == '<':
            pointer -= 1

        elif char == 'c':
            copied = memory.get(pointer, 0)

        elif char == 'p':
            memory[pointer] = copied

        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                ip = we_pairs[ip]

        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                ip = we_pairs[ip]

        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))

        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))

        elif char == 'T':
            memory[pointer] = memory.get(pointer, 0) * 2
            memory[pointer] = memory[pointer] % 256

        elif char == 'Q':
            memory[pointer] = memory.get(pointer, 0) ** 2
            memory[pointer] = memory[pointer] % 256

        elif char == 'U':
            import math
            memory[pointer] = int(math.sqrt(memory.get(pointer, 0)))

        elif char == 'L':
            memory[pointer] = memory.get(pointer, 0) + 2
            memory[pointer] = memory[pointer] % 256

        elif char == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            memory[pointer] = memory[pointer] % 256

        elif char == 'V':
            memory[pointer] = memory.get(pointer, 0) // 2

        elif char == 'A':
            memory[pointer] = memory.get(pointer, 0) + copied
            memory[pointer] = memory[pointer] % 256

        elif char == 'B':
            memory[pointer] = memory.get(pointer, 0) - copied
            memory[pointer] = memory[pointer] % 256

        elif char == 'Y':
            memory[pointer] = memory.get(pointer, 0) * copied
            memory[pointer] = memory[pointer] % 256

        elif char == 'D':
            if copied != 0:
                memory[pointer] = memory.get(pointer, 0) // copied
            # If copied is 0, do nothing (division by zero)

        # Skip non-command characters
        ip += 1

    return ''.join(output)

