def differentiate(polynomial, point):
    # Parse the polynomial into terms
    terms = []
    i = 0
    n = len(polynomial)

    while i < n:
        term_start = i

        # Find the end of this term (next + or - that's not at the start)
        while i < n and polynomial[i] not in '+-' and term_start > 0:
            i += 1
        while i < n and term_start == 0 and polynomial[i] != '+':
            # Skip leading +
            if polynomial[i] == '+':
                i += 1
            else:
                break

        term = polynomial[term_start:i]
        terms.append(term)

        # Skip past the operator if present
        if i < n and polynomial[i] == '+':
            i += 1

    if not terms:
        terms = [polynomial]

    def parse_term(term):
        """Parse a term into (coefficient, exponent)"""
        # Remove leading '+'
        term = term.lstrip('+')

        if term == '':
            return 0, 0

        # Check if term contains x
        if 'x' in term:
            x_index = term.index('x')

            # Extract coefficient part (before x)
            coeff_str = term[:x_index]

            # Extract exponent part (after x, if any)
            exp_str = term[x_index + 1:]

            # Parse coefficient
            if coeff_str == '' or coeff_str == '-':
                coefficient = -1 if coeff_str == '-' else 1
            else:
                coefficient = int(coeff_str)

            # Parse exponent
            if exp_str == '':
                exponent = 1
            elif exp_str.startswith('^'):
                exponent = int(exp_str[1:])
            else:
                exponent = 1
        else:
            # Constant term
            coefficient = int(term)
            exponent = 0

        return coefficient, exponent

    # Differentiate and evaluate
    result = 0
    for term in terms:
        coefficient, exponent = parse_term(term)

        # Apply power rule: d/dx (ax^n) = n*ax^(n-1)
        if exponent == 0:
            # Constant term, derivative is 0
            continue
        elif exponent == 1:
            # Linear term, derivative is coefficient
            result += coefficient
        else:
            # Higher order term: n * a * x^(n-1)
            result += coefficient * exponent * (point ** (exponent - 1))

    return result

def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    even_count = 0
    odd_count = 0

    # Iterate through numbers from 1 to n inclusive
    for num in range(1, n + 1):
        # Convert number to string to check if it is a palindrome
        s_num = str(num)

        # Check if the string reads the same forwards and backwards
        if s_num == s_num[::-1]:
            # Determine if the palindrome is even or odd
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

