def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 365 * 24 * 60 * 60),
        ('day', 24 * 60 * 60),
        ('hour', 60 * 60),
        ('minute', 60),
        ('second', 1)
    ]

    # Calculate each unit
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            if count > 1:
                components.append(f"{count} {unit_name}s")
            else:
                components.append(f"{count} {unit_name}")

    # Format the output
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

def is_balanced(string, pairs):
    # Create a mapping from opener to closer
    pair_map = {}
    for i in range(0, len(pairs), 2):
        opener = pairs[i]
        closer = pairs[i + 1]
        pair_map[opener] = closer

    # Stack to keep track of openers
    stack = []

    for char in string:
        # Skip characters not in pairs
        if char not in pairs:
            continue

        # Check if character is an opener
        if char in pair_map:
            # If it's an opener, push it onto the stack
            stack.append(char)
        else:
            # It's a closer
            # If stack is empty, no opener to match
            if not stack:
                return False

            # Pop the last opener
            last_opener = stack.pop()

            # Check if the closer matches the opener
            if pair_map[last_opener] != char:
                return False

    # String is balanced if stack is empty
    return len(stack) == 0

def compare(selector1, selector2):
    def get_specificity(selector):
        # Initialize counts
        id_count = 0
        class_count = 0
        tag_count = 0

        # Remove spaces for easier parsing
        selector = selector.replace(' ', '')

        # Parse the selector
        i = 0
        while i < len(selector):
            if selector[i] == '#':
                id_count += 1
                # Skip to the next non-alphanumeric character
                i += 1
                while i < len(selector) and (selector[i].isalnum() or selector[i] == '-'):
                    i += 1
            elif selector[i] == '.':
                class_count += 1
                # Skip to the next non-alphanumeric character
                i += 1
                while i < len(selector) and (selector[i].isalnum() or selector[i] == '-'):
                    i += 1
            elif selector[i] == '*':
                # Wildcard - no increment
                i += 1
            else:
                # It's a tag name
                tag_count += 1
                # Skip to the next non-alphanumeric character
                while i < len(selector) and (selector[i].isalnum() or selector[i] == '-'):
                    i += 1

        return (id_count, class_count, tag_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    if spec1 > spec2:
        return selector1
    else:
        return selector2

def count_divisors(n):
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n <= 0:
        raise ValueError("Input must be a positive integer")
    if n == 1:
        return 1
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # For 2^n - 1 to be a Mersenne prime, n must be prime
    if not is_prime(n):
        return False

    # Calculate 2^n - 1
    mersenne_number = (1 << n) - 1

    # Check if the Mersenne number is prime
    return is_prime(mersenne_number)

