def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []

    for group in groups:
        max_depth = 0
        current_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

def get_closest_vowel(word):
    vowels = set('aeiouAEIOU')

    # If word length is less than 3, no vowel can be between two consonants
    if len(word) < 3:
        return ""

    # Iterate from right to left (closest from the right side)
    # Check indices from len(word)-2 down to 1
    for i in range(len(word) - 2, 0, -1):
        # Check if current character is a vowel
        if word[i] in vowels:
            # Check if both neighbors are consonants (not vowels)
            if word[i-1] not in vowels and word[i+1] not in vowels:
                return word[i]

    return ""

