def encrypt(s):
    result = ""
    for char in s:
        if 'a' <= char <= 'z':
            # Calculate the shifted position with wrapping
            shifted = (ord(char) - ord('a') + 4) % 26
            # Convert back to character
            encrypted_char = chr(shifted + ord('a'))
            result += encrypted_char
        else:
            # Keep uppercase letters and non-alphabetic characters unchanged
            result += char
    return result

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part to the given base
    if integer_part == 0:
        integer_result = ""
    else:
        digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        integer_result = ""
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            # Handle negative remainders
            if remainder < 0:
                remainder += base
                temp = (temp - remainder) // base - 1
            else:
                temp = (temp - remainder) // base
            integer_result = digits[int(remainder)] + integer_result

    # Convert fractional part to the given base
    fractional_result = ""
    if decimals > 0:
        temp_fractional = fractional_part
        for _ in range(decimals):
            temp_fractional *= base
            digit = int(temp_fractional)
            fractional_result += str(digit)
            temp_fractional -= digit

    # Combine results
    if integer_result == "":
        result = "0"
    else:
        result = integer_result

    if decimals > 0:
        result += "." + fractional_result

    # Handle negative sign
    if negative:
        result = "-" + result

    return result

