def proper_fractions(d):
    if d == 1:
        return 0

    result = d

    # Check factor 2
    if d % 2 == 0:
        while d % 2 == 0:
            d //= 2
        result -= result // 2

    # Check odd factors from 3 onwards
    p = 3
    while p * p <= d:
        if d % p == 0:
            while d % p == 0:
                d //= p
            result -= result // p
        p += 2

    # If d > 1, then the remaining d is a prime
    if d > 1:
        result -= result // d

    return result

