            while True:
                x += dx
                y += dy
                if not is_valid((x, y)):
                    break
                attacks.add((x, y))
                # Stop after one step for knight moves
                if (dx, dy) in [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]:
                    break

        # Knight moves (8 possible L-shapes)
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            x, y = amazon_pos[0] + dx, amazon_pos[1] + dy
            if is_valid((x, y)):
                attacks.add((x, y))

        return attacks

