        moves = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                new_pos = (pos[0] + dx, pos[1] + dy)
                if is_valid(new_pos):
                    moves.append(new_pos)
