    amazon_attacks = get_amazon_attacks(amazon_pos)

    # Initialize counters
    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    # Check all possible black king positions
    for i in range(8):
        for j in range(8):
            black_pos = (i, j)

            # Skip if position is adjacent to white king
            if is_adjacent(black_pos, king_pos):
                continue

            # Skip if position is occupied by white pieces
            if black_pos == king_pos or black_pos == amazon_pos:
                continue

            # Check if black king is under attack by amazon
            is_under_attack = black_pos in amazon_attacks

            # Get all possible moves for black king
            king_moves = get_king_moves(black_pos)

            # Check if black king can move to any safe square
            can_move = False
            safe_moves = 0

            for move in king_moves:
                # Check if move is valid (not adjacent to white king and not occupied)
                if not is_adjacent(move, king_pos) and move != amazon_pos and move != king_pos:
                    # Check if move is safe (not under attack by amazon)
                    if move not in amazon_attacks:
