def exchange_sort(sequence):
    # Create a sorted version to know where each element should go
    sorted_seq = sorted(sequence)

    # Create a mapping from value to its correct positions
    value_positions = {}
    for i, val in enumerate(sorted_seq):
        if val not in value_positions:
            value_positions[val] = []
        value_positions[val].append(i)

    # Create a permutation mapping: where does each element in original sequence
    # need to go in the sorted sequence?
    perm = []
    position_tracker = {}
    for val in value_positions:
        position_tracker[val] = 0

    for i, val in enumerate(sequence):
        correct_pos = value_positions[val][position_tracker[val]]
        perm.append(correct_pos)
        position_tracker[val] += 1

    # Count cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i]:
            # Start a new cycle
            cycles += 1
            current = i
            while not visited[current]:
                visited[current] = True
                current = perm[current]

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

def compare(selector1, selector2):
