        # Count element selectors (any word that's not # or .)
        # Split by spaces and remove # and . to count elements
        elements = []
        for part in selector.split():
            # Remove any # or . from the part to count elements
            clean_part = ''.join(char for char in part if char not in '#.')
            if clean_part and not clean_part.isdigit():
                elements.append(clean_part)

        # Count elements (this counts each unique element name)
        element_count = len(elements)

        return (id_count, class_count, element_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    if spec1 > spec2:
        return selector1
    else:
        return selector2

