    vowels = "aeiouAEIOU"

    # Need at least 3 characters to have a vowel between two consonants
    if len(word) < 3:
        return ""

    # Iterate from right to left, from len(word)-2 down to 1
    # (excludes beginning at index 0 and ending at index len(word)-1)
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            # Check if it's between two consonants
            if word[i-1] not in vowels and word[i+1] not in vowels:
                return word[i]

    return ""

import sys
from math import comb

def compute_probability(k, n):
    """Compute probability of collecting all k types in at most n trials"""
    if n < k:
        return 0.0

    prob = 0.0
    for i in range(k + 1):
        sign = (-1) ** i
        binom = comb(k, i)
        prob_term = (k - i) ** n
        prob += sign * binom * prob_term

    return prob / (k ** n)

def find_min_days(k, target_prob):
    """Find minimum number of days such that probability >= target_prob"""
    if k == 1:
        return 1

    # Binary search for the minimum n
    left, right = k, k * k * 10  # Upper bound estimation

    while left < right:
        mid = (left + right) // 2
        prob = compute_probability(k, mid)
        if prob >= target_prob:
            right = mid
        else:
            left = mid + 1

    return left

