def differentiate(polynomial, x):
    # Remove all spaces
    polynomial = polynomial.replace(" ", "")

    # Split by + and - operators, keeping the operators
    terms = []
    current_term = ""

    for i, char in enumerate(polynomial):
        if char in ['+', '-'] and i > 0:
            terms.append(current_term)
            current_term = char
        else:
            current_term += char

    terms.append(current_term)

    # Process each term
    derivative_terms = []

    for term in terms:
        if not term:
            continue

        # Handle the case where term starts with a minus sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        else:
            sign = 1

        # Parse the term
        if 'x^' in term:
            # Term is like "3x^2" or "-3x^2"
            parts = term.split('x^')
            coeff_str = parts[0]
            if coeff_str == '' or coeff_str == '+':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)
            coeff *= sign
            exponent = int(parts[1])

            # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
            if exponent > 0:
                new_coeff = coeff * exponent
                new_exponent = exponent - 1
                if new_exponent == 0:
                    derivative_terms.append(str(new_coeff))
                elif new_exponent == 1:
                    derivative_terms.append(f"{new_coeff}x")
                else:
                    derivative_terms.append(f"{new_coeff}x^{new_exponent}")

        elif 'x' in term:
            # Term is like "3x" or "-3x"
            coeff_str = term.replace('x', '')
            if coeff_str == '' or coeff_str == '+':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)
            coeff *= sign

            # Apply power rule: d/dx(ax^1) = 1*ax^0 = a
            derivative_terms.append(str(coeff))

        else:
            # Term is a constant
            # Derivative of a constant is 0
            continue

    # If no terms, derivative is 0
    if not derivative_terms:
        return 0

    # Create the derivative polynomial string
    derivative_poly = derivative_terms[0]
    for i in range(1, len(derivative_terms)):
        if derivative_terms[i].startswith('-'):
            derivative_poly += f" - {derivative_terms[i][1:]}"
        else:
            derivative_poly += f" + {derivative_terms[i]}"

    # Evaluate the derivative at x
    # Replace x with the value and evaluate
    result = 0
    for term in derivative_terms:
        if 'x' in term:
            if term == 'x':
                result += x
            elif term == '-x':
                result -= x
            else:
                # Extract coefficient and exponent
                if term.startswith('-'):
                    coeff_str = term[1:]
                    if 'x^' in coeff_str:
                        coeff_str = coeff_str.split('x^')[0]
                        coeff = int(coeff_str) * -1
                    else:
                        coeff = int(coeff_str[:-1]) * -1
                else:
                    if 'x^' in term:
                        coeff_str = term.split('x^')[0]
                        coeff = int(coeff_str)
                    else:
                        coeff = int(term[:-1])

                # Calculate coeff * x^exponent
                if 'x^' in term:
                    exponent = int(term.split('x^')[1])
                    result += coeff * (x ** exponent)
                else:
                    result += coeff * x
        else:
            # Constant term
            result += int(term)

    return result

def differentiate(polynomial, x):
    # Split the polynomial into terms
    # Handle the case where the first term might be negative
    if polynomial[0] == '-':
        terms = ['-']
        i = 1
    else:
        terms = []
        i = 0

    current_term = ""
    while i < len(polynomial):
        if polynomial[i] in '+-' and current_term:
            terms.append(current_term)
            current_term = polynomial[i]
        else:
            current_term += polynomial[i]
        i += 1

    if current_term:
        terms.append(current_term)

    # Process each term
    derivative_terms = []

    for term in terms:
        if not term or term == '+':
            continue
        if term == '-':
            continue

        # Handle negative terms
        if term.startswith('-') and len(term) > 1:
            sign = -1
            term = term[1:]
        else:
            sign = 1

        # Parse the term
        if 'x' not in term:
            # Constant term
            continue
        elif term == 'x':
            # x term
            coefficient = sign * 1
            exponent = 1
        elif term == '-x':
            # -x term
            coefficient = sign * -1
            exponent = 1
        elif term.endswith('x'):
            # ax term
            coefficient = sign * int(term[:-1])
            exponent = 1
        elif term.endswith('x^0'):
            # ax^0 term
            coefficient = sign * int(term[:-2])
            exponent = 0
        elif 'x^' in term:
            # ax^n term
            parts = term.split('x^')
            if parts[0] == '':
                coefficient = sign * 1
            elif parts[0] == '-':
                coefficient = sign * -1
            else:
                coefficient = sign * int(parts[0])
            exponent = int(parts[1])
        else:
            # ax term
            coefficient = sign * int(term[:-1])
            exponent = 1

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent == 0:
            # Derivative of a constant is 0
            continue
        else:
            new_coefficient = coefficient * exponent
            new_exponent = exponent - 1

            if new_exponent == 0:
                # Just a constant
                derivative_terms.append(new_coefficient)
            elif new_exponent == 1:
                # ax term
                if new_coefficient == 1:
                    derivative_terms.append('x')
                elif new_coefficient == -1:
                    derivative_terms.append('-x')
                else:
                    derivative_terms.append(f"{new_coefficient}x")
            else:
                # ax^n term
                if new_coefficient == 1:
                    derivative_terms.append(f"x^{new_exponent}")
                elif new_coefficient == -1:
                    derivative_terms.append(f"-x^{new_exponent}")
                else:
                    derivative_terms.append(f"{new_coefficient}x^{new_exponent}")

    # Evaluate the derivative at x
    result = 0

    # If there are no derivative terms, the result is 0
    if not derivative_terms:
        return 0

    # Process each term in the derivative
    for term in derivative_terms:
        if term == 'x':
            result += x
        elif term == '-x':
            result -= x
        elif term.endswith('x'):
            # ax term
            coefficient = int(term[:-1])
            result += coefficient * x
        elif 'x^' in term:
            # ax^n term
            parts = term.split('x^')
            coefficient = int(parts[0])
            exponent = int(parts[1])
            result += coefficient * (x ** exponent)
        else:
            # Constant term
            result += int(term)

    return result

