def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []

    for group in groups:
        max_depth = 0
        current_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

def parse_int(s):
    # Mapping of words to their numeric values
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14, 'fifteen': 15,
        'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19, 'twenty': 20,
        'thirty': 30, 'forty': 40, 'fifty': 50, 'sixty': 60, 'seventy': 70,
        'eighty': 80, 'ninety': 90
    }

    # Scale words
    scales = {
        'hundred': 100,
        'thousand': 1000,
        'million': 1000000
    }

    # Split the string into words, handling hyphens
    words = []
    for word in s.split():
        if '-' in word:
            # Split hyphenated words and add each part
            parts = word.split('-')
            words.extend(parts)
        else:
            words.append(word)

    total = 0
    current = 0

    for word in words:
        if word == 'and':
            continue  # Skip 'and' words

        if word in word_to_num:
            current += word_to_num[word]
        elif word in scales:
            if word == 'hundred':
                current *= scales[word]
            else:  # thousand or million
                total += current * scales[word]
                current = 0

    # Add the final current value to the total
    total += current

    return total

def sum_of_squares(n):
    # Check if n is a perfect square
    sqrt_n = int(n**0.5)
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n can be expressed as sum of 2 squares
    # We'll use a more efficient approach: check if n = a^2 + b^2
    for i in range(1, int(n**0.5) + 1):
        remainder = n - i * i
        sqrt_remainder = int(remainder**0.5)
        if sqrt_remainder * sqrt_remainder == remainder:
            return 2

    # Check if n is of the form 4^a(8b+7)
    # This would require 4 squares
    while n % 4 == 0:
        n //= 4

    if n % 8 == 7:
        return 4

    # If none of the above, it requires 3 squares
    return 3

