def amazonCheckmate(king, amazon):
    def pos_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def coords_to_pos(x, y):
        return chr(ord('a') + x) + str(y + 1)

    def is_valid(x, y):
        return 0 <= x < 8 and 0 <= y < 8

    def is_adjacent(x1, y1, x2, y2):
        return abs(x1 - x2) <= 1 and abs(y1 - y2) <= 1

    def get_amazon_attacks(x, y):
        attacks = set()

        # Queen moves (rook + bishop)
        # Horizontal and vertical
        for i in range(8):
            if i != x:
                attacks.add((i, y))
        for j in range(8):
            if j != y:
                attacks.add((x, j))

        # Diagonals
        for i in range(1, 8):
            if is_valid(x + i, y + i):
                attacks.add((x + i, y + i))
            if is_valid(x - i, y + i):
                attacks.add((x - i, y + i))
            if is_valid(x + i, y - i):
                attacks.add((x + i, y - i))
            if is_valid(x - i, y - i):
                attacks.add((x - i, y - i))

        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            new_x, new_y = x + dx, y + dy
            if is_valid(new_x, new_y):
                attacks.add((new_x, new_y))

        return attacks

    def get_king_moves(x, y):
        moves = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                new_x, new_y = x + dx, y + dy
                if is_valid(new_x, new_y):
                    moves.append((new_x, new_y))
        return moves

    king_x, king_y = pos_to_coords(king)
    amazon_x, amazon_y = pos_to_coords(amazon)

    # Get all squares amazon attacks
    amazon_attacks = get_amazon_attacks(amazon_x, amazon_y)

    # Get all valid black king positions
    result = [0, 0, 0, 0]  # [checkmate, check, stalemate, safe]

    for x in range(8):
        for y in range(8):
            # Skip if adjacent to white king
            if is_adjacent(x, y, king_x, king_y):
                continue

            # Skip if this position is occupied by white king or amazon
            if (x, y) == (king_x, king_y) or (x, y) == (amazon_x, amazon_y):
                continue

            # Check if black king is under attack
            is_under_attack = (x, y) in amazon_attacks

            # Get all possible moves for black king
            king_moves = get_king_moves(x, y)

            # Check if any move is safe
            safe_moves = []
            for move_x, move_y in king_moves:
                # Check if move is not adjacent to white king
                if not is_adjacent(move_x, move_y, king_x, king_y):
                    safe_moves.append((move_x, move_y))

            # If no safe moves, king is either checkmate or stalemate
            if not safe_moves:
                if is_under_attack:
                    # Checkmate
                    result[0] += 1
                else:
                    # Stalemate
                    result[2] += 1
            else:
                # King can move
                if is_under_attack:
                    # Check
                    result[1] += 1
                else:
                    # Safe
                    result[3] += 1

    return result

def count_up_to(n):
    if n < 2:
        return []

    # Sieve of Eratosthenes
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n, i):
                is_prime[j] = False

    # Collect primes
    primes = []
    for i in range(2, n):
        if is_prime[i]:
            primes.append(i)

    return primes

def choose(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result

