def pig_latin(word):
    # Check if the word contains only alphabetic characters
    if not word.isalpha():
        return None

    # Convert to lowercase
    word = word.lower()

    # Check if the word starts with a vowel
    if word[0] in 'aeiou':
        return word + 'way'

    # Find the index of the first vowel
    first_vowel_index = -1
    for i, char in enumerate(word):
        if char in 'aeiou':
