def count_up_to(n):
    if n <= 2:
        return []

    # Use Sieve of Eratosthenes for efficiency
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n, i):
                is_prime[j] = False

    # Collect primes less than n
    primes = []
    for i in range(2, n):
        if is_prime[i]:
            primes.append(i)

    return primes

def simplify(expression):
    # Handle empty or whitespace-only expression
    expression = expression.strip()
    if not expression:
        return ""

    # Parse expression into terms
    terms = parse_expression(expression)

    # Combine like terms
    combined = {}
    for coeff, vars in terms:
        key = vars
        if key not in combined:
            combined[key] = 0
        combined[key] += coeff

    # Remove terms with coefficient 0
    result = [(coeff, vars) for vars, coeff in combined.items() if coeff != 0]

    # Sort terms: by number of variables (ascending), then lexicographically
    result.sort(key=lambda x: (len(x[1]), x[1]))

    # Format output
    if not result:
        return ""

    parts = []
    for i, (coeff, vars) in enumerate(result):
        # Determine sign and magnitude
        if coeff == 0:
            continue
        sign = ""
        mag = abs(coeff)
        if i == 0 and coeff >= 0:
            # No leading + for first positive term
            if mag == 1 and vars:
                parts.append(vars)
            elif mag != 1 or not vars:
                parts.append(str(mag))
        else:
            # Include sign for subsequent terms or first negative term
            if coeff < 0:
                sign = "-"
            else:
                sign = "+"
            if mag == 1 and vars:
                parts.append(sign + vars)
            elif mag != 1 or not vars:
                parts.append(sign + str(mag))

    return "".join(parts)


def parse_expression(expression):
    """Parse the expression into list of (coefficient, sorted_variable_string) tuples."""
    terms = []
    i = 0
    n = len(expression)

    while i < n:
        # Determine sign
        sign = 1
        if expression[i] == '+':
            sign = 1
            i += 1
        elif expression[i] == '-':
            sign = -1
            i += 1

        # Determine coefficient
        j = i
        while j < n and expression[j].isdigit():
            j += 1

        if j > i:
            coeff = int(expression[i:j])
            i = j
        else:
            coeff = 1  # implicit coefficient of 1

        # Extract variables
        j = i
        while j < n and expression[j].isalpha():
            j += 1

        vars = expression[i:j]
        i = j

        # Normalize: sort variables alphabetically and apply sign
        sorted_vars = ''.join(sorted(vars))
        coeff *= sign

        terms.append((coeff, sorted_vars))

    return terms

