def is_balanced(s, pairs):
    stack = []
    # Create mapping of opening to closing brackets
    pair_map = {}
    for i in range(0, len(pairs), 2):
        pair_map[pairs[i]] = pairs[i+1]

    for char in s:
        # If it's an opening bracket
        if char in pair_map:
            stack.append(char)
        # If it's a closing bracket
        elif char in pair_map.values():
            # Stack is empty or doesn't match
            if not stack or pair_map[stack.pop()] != char:
                return False

    # All brackets should be closed
    return len(stack) == 0

