def proper_fractions(n):
    if n == 1:
        return 0

    result = n

    # Check for factor 2
    if n % 2 == 0:
        result -= result // 2
        while n % 2 == 0:
            n //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result -= result // i
            while n % i == 0:
                n //= i
        i += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        result -= result // n

    return result

import re

def differentiate(polynomial, x):
    # Split by + and - operators, keeping the operators
    terms = re.split(r'(?=[+-])', polynomial)
    # Remove empty strings
    terms = [term for term in terms if term]

    derivative_terms = []

    for term in terms:
        # Handle the sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Parse the term
        if 'x^' in term:
            # Format: coefficient x^exponent
            coeff_str, exp_str = term.split('x^')
            coefficient = int(coeff_str) if coeff_str else 1
            exponent = int(exp_str)
        elif 'x' in term:
            # Format: coefficient x or x
            if term == 'x':
                coefficient = 1
                exponent = 1
            else:
                coeff_str = term[:-1]  # Remove 'x'
                coefficient = int(coeff_str) if coeff_str != '-' else -1
                exponent = 1
        else:
            # Constant term
            coefficient = int(term)
            exponent = 0

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent == 0:
            # Derivative of constant is 0
            continue
        else:
            new_coefficient = coefficient * exponent
            new_exponent = exponent - 1

            # Build the derivative term
            if new_exponent == 0:
                derivative_terms.append(str(new_coefficient))
            elif new_exponent == 1:
                if new_coefficient == 1:
                    derivative_terms.append('x')
                elif new_coefficient == -1:
                    derivative_terms.append('-x')
                else:
                    derivative_terms.append(f"{new_coefficient}x")
            else:
                if new_coefficient == 1:
                    derivative_terms.append(f"x^{new_exponent}")
                elif new_coefficient == -1:
                    derivative_terms.append(f"-x^{new_exponent}")
                else:
                    derivative_terms.append(f"{new_coefficient}x^{new_exponent}")

    # If no derivative terms, return 0
    if not derivative_terms:
        return 0

    # Reconstruct the derivative polynomial
    derivative_poly = derivative_terms[0]
    for i in range(1, len(derivative_terms)):
        if derivative_terms[i].startswith('-'):
            derivative_poly += f" - {derivative_terms[i][1:]}"
        else:
            derivative_poly += f" + {derivative_terms[i]}"

    # Evaluate the derivative at x
    # We'll use substitution
    result = 0
    for term in derivative_terms:
        if 'x' in term:
            if term == 'x':
                result += x
            elif term == '-x':
                result -= x
            elif term.startswith('-'):
                coeff = int(term[1:-1]) if term[1:-1] else -1
                result += coeff * (x ** (int(term.split('x')[1]) if 'x^' in term else 1))
            else:
                coeff = int(term[:-1]) if term[:-1] else 1
                result += coeff * (x ** (int(term.split('x')[1]) if 'x^' in term else 1))
        else:
            result += int(term)

    return result

def cycpattern_check(a, b):
    # If b is empty, it's considered a substring of any string
    if not b:
        return True
    # If b is longer than a, no rotation of b can be a substring of a
    if len(b) > len(a):
        return False
    # Check all rotations of b
    for i in range(len(b)):
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True
    return False

def sum_of_a_beach(text):
    text_lower = text.lower()
    targets = ["sand", "water", "fish", "sun"]
    count = 0
