    return count

import re
from collections import defaultdict

def simplify(expression):
    if not expression:
        return ""

    # Split by + and - signs, keeping the signs
    # We need to be careful about the first term which might not have a leading +
    terms = re.findall(r'[+-]?[^+-]+', expression)

    # Dictionary to store normalized monomials and their coefficients
    monomials = defaultdict(int)

    for term in terms:
        # Determine the sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Parse coefficient and variable part
        # Find where the coefficient ends (before the first letter)
        coeff_str = ""
        var_part = term

        for i, char in enumerate(term):
            if char.isalpha():
                coeff_str = term[:i]
                var_part = term[i:]
                break
        else:
            # No letters found, whole term is coefficient
            coeff_str = term
            var_part = ""

        # If coefficient is empty, it's 1 or -1
        if not coeff_str:
            coefficient = sign * 1
        else:
            coefficient = sign * int(coeff_str)

        # Normalize variable part by sorting letters
        if var_part:
            normalized_var = ''.join(sorted(var_part))
            monomials[normalized_var] += coefficient
        else:
            # Constant term (no variables)
            monomials[''] += coefficient

    # Remove terms with zero coefficient
    monomials = {k: v for k, v in monomials.items() if v != 0}

    # Sort terms
    # Primary key: number of variables
    # Secondary key: lexicographic order of variable string
    sorted_terms = sorted(monomials.items(), key=lambda x: (len(x[0]), x[0]))

    # Format result
    result = []
    first = True

    for var, coeff in sorted_terms:
        if coeff == 0:
            continue

        # Handle the coefficient
        if coeff == 1:
            coeff_str = ""
        elif coeff == -1:
            coeff_str = "-"
        else:
            coeff_str = str(coeff)

        # Handle variable part
        if var == "":
            var_str = ""
        else:
            var_str = var

        term_str = coeff_str + var_str

        # First term: no leading +
        if first:
            result.append(term_str)
            first = False
        else:
            # Positive coefficient: prefix with +
            if coeff > 0:
                result.append("+" + term_str)
            else:
                result.append(term_str)

    # Join the terms
    if not result:
        return "0"

    return "".join(result)

