def median(l: list):
    if not l:
        return None

    sorted_list = sorted(l)
    n = len(sorted_list)

    if n % 2 == 1:
        # Odd length: return the middle element
        return sorted_list[n // 2]
    else:
        # Even length: return the average of the two middle elements
        mid1 = sorted_list[n // 2 - 1]
        mid2 = sorted_list[n // 2]
        return (mid1 + mid2) / 2.0

def compare(selector1, selector2):
    def calculate_specificity(selector):
        ids = 0
        classes = 0
        tags = 0

        parts = selector.split()

        for part in parts:
            if not part or part == '*':
                continue

            ids += part.count('#')
            classes += part.count('.')

            # Find the tag name (everything before the first # or .)
            min_pos = len(part)
            if '#' in part:
                min_pos = min(min_pos, part.find('#'))
            if '.' in part:
                min_pos = min(min_pos, part.find('.'))

            tag_part = part[:min_pos]

            if tag_part and tag_part != '*':
                tags += 1

        return (ids, classes, tags)

    spec1 = calculate_specificity(selector1)
    spec2 = calculate_specificity(selector2)

    if spec1 > spec2:
        return selector1
    elif spec2 > spec1:
        return selector2
    else:
        return selector2  # Later selector wins on tie

