def differentiate(polynomial, x):
    # Parse the polynomial into terms
    # Handle the case where the polynomial starts with a negative term
    if polynomial[0] == '-':
        terms = ['-']
        polynomial = polynomial[1:]
    else:
        terms = []

    # Split by '+' and '-' to get individual terms
    current_term = ""
    for i, char in enumerate(polynomial):
        if char in ['+', '-'] and i > 0:
            terms.append(current_term)
            current_term = char
        else:
            current_term += char
    terms.append(current_term)

    # Process each term to get coefficient and exponent
    derived_terms = []

    for term in terms:
        if not term:
            continue

        # Handle the case where term is just a constant (no x)
        if 'x' not in term:
            # This is a constant term, its derivative is 0
            continue

        # Extract coefficient and exponent
        if term == 'x':
            coeff = 1
            exp = 1
        elif term == '-x':
            coeff = -1
            exp = 1
        else:
            # Find where x is
            x_pos = term.find('x')
            if x_pos == 0:
                coeff = 1
            elif x_pos == 1 and term[0] == '-':
                coeff = -1
            else:
                coeff_str = term[:x_pos]
                if coeff_str == '+':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str)

            # Find exponent
            if '^' in term:
                exp = int(term[term.find('^') + 1:])
            elif x_pos == len(term) - 1:
                exp = 1
            else:
                exp = 1

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exp > 0:
            new_coeff = coeff * exp
            new_exp = exp - 1
            derived_terms.append((new_coeff, new_exp))

    # Evaluate the derived polynomial at x
    result = 0
    for coeff, exp in derived_terms:
        if exp == 0:
            result += coeff
        else:
            result += coeff * (x ** exp)

    return result

def proper_fractions(d):
    if d <= 1:
        return 0

    result = d
    p = 2

    # Check for factor 2
    if d % p == 0:
        while d % p == 0:
            d //= p
        result -= result // p

    # Check for odd factors from 3 onwards
    p = 3
    while p * p <= d:
        if d % p == 0:
            while d % p == 0:
                d //= p
            result -= result // p
        p += 2

    # If d > 1, then d is a prime factor
    if d > 1:
        result -= result // d

    return result

def getAllPrimeFactors(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    if not isinstance(n, int) or n <= 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)
    unique_factors = []
    counts = []

    if not factors:
        return [[], []]

    current_factor = factors[0]
    count = 0

    for factor in factors:
        if factor == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factor
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
