def count_up_to(n):
    if n <= 2:
        return []

    # Create a boolean array and initialize all entries as True
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not prime numbers

    # Sieve of Eratosthenes
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            # Mark all multiples of i as not prime
            for j in range(i * i, n, i):
                is_prime[j] = False

    # Collect all prime numbers
    primes = []
    for i in range(2, n):
        if is_prime[i]:
            primes.append(i)

    return primes

def exchange_sort(sequence):
    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for val in sequence:
        count[val] += 1

    # Create the target sorted sequence
    target = []
    target.extend([7] * count[7])
    target.extend([8] * count[8])
    target.extend([9] * count[9])

    # Create a mapping from value to its correct positions
    correct_positions = {7: [], 8: [], 9: []}
    for i, val in enumerate(target):
        correct_positions[val].append(i)

    # Create a mapping from current position to correct position
    pos_to_correct = {}
    for i, val in enumerate(sequence):
        if correct_positions[val]:
            pos_to_correct[i] = correct_positions[val].pop(0)

    # Find cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i] and i in pos_to_correct:
            # Start a new cycle
            current = i
            cycle_length = 0
            while not visited[current]:
                visited[current] = True
                if current in pos_to_correct:
                    current = pos_to_correct[current]
                else:
                    break
                cycle_length += 1
            if cycle_length > 0:
                cycles += 1

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

