        epsilon = 1e-9
        return abs(val1 - val2) < epsilon

    num_a = to_numeric(a)
    num_b = to_numeric(b)

    if is_equal(num_a, num_b):
        return None

    if num_a > num_b:
        return a
    else:
        return b

def is_balanced(s, pairs):
    if not s:
        return True

    # Create mapping from closing to opening characters
    closing_to_opening = {}
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        closing_to_opening[closing] = opening

    # Stack to track opening characters
    stack = []

    for char in s:
        # If character is an opening character
        if char in pairs[::2]:  # Check if it's in even positions (opening chars)
            stack.append(char)
        # If character is a closing character
        elif char in closing_to_opening:
            # If stack is empty or doesn't match, it's unbalanced
            if not stack or stack.pop() != closing_to_opening[char]:
                return False

    # All characters should be matched (stack should be empty)
    return len(stack) == 0

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """

    def to_float(value):
        """Convert any input to float, handling comma as decimal separator"""
        if isinstance(value, (int, float)):
            return float(value)
        elif isinstance(value, str):
            # Replace comma with period for decimal separator
            normalized_str = value.replace(',', '.')
            return float(normalized_str)
        else:
            raise TypeError("Unsupported type")

    # Convert both values to float for comparison
    a_float = to_float(a)
    b_float = to_float(b)

    # Compare with tolerance for floating point equality
    epsilon = 1e-9
    if abs(a_float - b_float) < epsilon:
        return None

    # Return the original value that is larger
    if a_float > b_float:
        return a
    else:
        return b

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 365 * 24 * 60 * 60),
        ('day', 24 * 60 * 60),
        ('hour', 60 * 60),
        ('minute', 60),
        ('second', 1)
    ]

    # Calculate each unit
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            if count > 1:
                components.append(f"{count} {unit_name}s")
            else:
                components.append(f"{count} {unit_name}")

    # Format the output
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None

    return hashlib.md5(text.encode('utf-8')).hexdigest()

