    return len(stack) == 0

def amazon_check_mate(king, amazon):
    # Convert chess notation to coordinates
    def to_coords(pos):
        col = ord(pos[0]) - ord('a')  # a=0, b=1, ..., h=7
        row = int(pos[1]) - 1  # 1=0, 2=1, ..., 8=7
        return (row, col)

    # Parse input positions
    wk_row, wk_col = to_coords(king)
    am_row, am_col = to_coords(amazon)

