                        # Not attacked by amazon
                        if (new_row, new_col) in amazon_attacks:
                            continue
                        safe_moves += 1

            # Categorize position
            if under_attack:
                if safe_moves == 0:
                    checkmate += 1
                else:
                    check += 1
            else:
                if safe_moves == 0:
                    stalemate += 1
                else:
                    safe += 1

    return [checkmate, check, stalemate, safe]

def almost_everywhere_zero(n, k):
    MOD = 10**9 + 7

    s = str(n)
    n_len = len(s)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, count, tight, leading_zeros):
        # Base case: all digits placed
        if pos == n_len:
            return 1 if count == k else 0

        # Determine upper bound for current digit
        upper = int(s[pos]) if tight else 9

        result = 0

        for digit in range(upper + 1):
            new_tight = tight and (digit == upper)

            if leading_zeros and digit == 0:
                # Still in leading zeros, count doesn't change
                result = (result + dp(pos + 1, count, new_tight, True)) % MOD
            else:
                # Not in leading zeros or placing non-zero digit
                new_count = count + (1 if digit != 0 else 0)
                if new_count <= k:
                    result = (result + dp(pos + 1, new_count, new_tight, False)) % MOD

        return result

    return dp(0, 0, True, True)

def simplify(expression):
    if not expression:
        return ""

    # Parse terms from the expression
    terms = {}  # maps sorted variables tuple to coefficient

    i = 0
    n = len(expression)

    while i < n:
        # Determine the sign of the term
        if expression[i] == '+':
            sign = 1
            i += 1
        elif expression[i] == '-':
            sign = -1
            i += 1
        else:
            sign = 1

        # Parse coefficient
        if i < n and expression[i].isdigit():
            j = i
            while j < n and expression[j].isdigit():
                j += 1
            coeff = int(expression[i:j])
            i = j
        else:
            coeff = 1

        coeff *= sign

        # Parse variables
        variables = []
        while i < n and expression[i].islower():
            variables.append(expression[i])
            i += 1

        # Only process if there are variables (non-constant terms)
        if variables:
            # Sort variables to handle commutativity (xy == yx)
            variables.sort()
            var_tuple = tuple(variables)

            if var_tuple in terms:
                terms[var_tuple] += coeff
            else:
                terms[var_tuple] = coeff

    # Filter out zero coefficients
    terms = {k: v for k, v in terms.items() if v != 0}

    if not terms:
        return ""

    # Sort terms by: (1) number of variables, (2) lexicographic order
    sorted_terms = sorted(terms.items(), key=lambda x: (len(x[0]), x[0]))

    # Build the output string
    result = []
    for var_tuple, coeff in sorted_terms:
        variables_str = ''.join(var_tuple)

        if coeff == 1 and len(result) > 0:
            term = "+" + variables_str
        elif coeff == 1:
            term = variables_str
        elif coeff == -1 and len(result) > 0:
            term = "-" + variables_str
        elif coeff == -1:
            term = "-" + variables_str
        elif coeff > 0 and len(result) > 0:
            term = "+" + str(coeff) + variables_str
        elif coeff > 0:
            term = str(coeff) + variables_str
        elif coeff < 0 and len(result) > 0:
            term = str(coeff) + variables_str
        else:
            term = str(coeff) + variables_str

        result.append(term)

    return ''.join(result)

def pig_latin(word):
    if not word:
        return None

    # Check if all characters are alphabetic
    if not word.isalpha():
        return None

    # Convert to lowercase
    word = word.lower()

    # Check if word starts with a vowel
    if word[0] in 'aeiou':
        return word + 'way'

    # Find the index where the first vowel occurs
    vowel_index = 0
    for i, char in enumerate(word):
        if char in 'aeiou':
            vowel_index = i
            break
    else:
        # No vowels found, return original word plus "ay"
        return word + 'ay'

    # Move consonants from the beginning to the end until the first vowel
    return word[vowel_index:] + word[:vowel_index] + 'ay'

def fib4(n):
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    a, b, c, d = 0, 0, 2, 0

    for _ in range(4, n + 1):
        next_val = a + b + c + d
        a, b, c, d = b, c, d, next_val

    return d

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units: (seconds_in_unit, singular_name, plural_name)
    units = [
        (31536000, "year", "years"),   # 365 * 24 * 60 * 60
        (86400, "day", "days"),         # 24 * 60 * 60
        (3600, "hour", "hours"),        # 60 * 60
        (60, "minute", "minutes"),
        (1, "second", "seconds")
    ]

    parts = []

    for val, singular, plural in units:
        count = seconds // val
        seconds %= val

        if count > 0:
            if count == 1:
                parts.append(f"{count} {singular}")
            else:
                parts.append(f"{count} {plural}")

    if len(parts) == 1:
        return parts[0]
    else:
        return ", ".join(parts[:-1]) + " and " + parts[-1]

from typing import List, Tuple


def sum_product(numbers: List[int]) -> Tuple[int, int]:
    current_sum = 0
    current_product = 1

    for num in numbers:
        current_sum += num
        current_product *= num

    return (current_sum, current_product)

def valid_mersenne(n):
    if n <= 1:
        return False

    # Check if n is a Mersenne number (form 2^k - 1)
    # A number n is a Mersenne number if n + 1 is a power of 2
    n_plus_1 = n + 1

    # Check if n_plus_1 is a power of 2
    if n_plus_1 & (n_plus_1 - 1) != 0:
        return False

    # Now check if n is prime
    # Since n = 2^k - 1, for n to be a Mersenne prime, k must be prime
    # But we'll check primality of n directly

    # Special case for small n
    if n < 2:
        return False
    if n == 2:
        return False  # 2 is not a Mersenne number (2 = 2^1 - 0, not 2^k - 1)
    if n % 2 == 0:
        return False

    # Check for primality
    import math
    sqrt_n = int(math.sqrt(n)) + 1
    for i in range(3, sqrt_n, 2):
        if n % i == 0:
            return False

    return True

def get_closest_vowel(word):
    if len(word) < 3:
        return ""

    vowels = "aeiouAEIOU"

    # Iterate from right to left, excluding first and last positions
    for i in range(len(word) - 2, 0, -1):
        # Check if current character is a vowel
        if word[i] in vowels:
            # Check if it's surrounded by consonants
            if word[i-1] not in vowels and word[i+1] not in vowels:
