    for x_or_y(15, 8, 5) == 5

    """

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False

        # Check odd divisors up to sqrt(num)
        i = 3
        while i * i <= num:
