import math

def converter(number, base, decimals=0):
    """
    Converts a base 10 number to a given base.

    Args:
        number (int|float|str): The number to convert
        base (int|float|str): The base to convert to (must be >= 2)
        decimals (int): Number of decimal places in the result

    Returns:
        str: String representation of the converted number
    """
    # Parse inputs
    try:
        num = float(number)
        base_val = float(base)
    except (ValueError, TypeError):
        raise ValueError("Invalid number or base")

    if base_val < 2:
        raise ValueError("Base must be >= 2")

    # Handle sign
    sign = ''
    if num < 0:
        sign = '-'
        num = abs(num)

    # Handle zero
    if num == 0:
        if decimals > 0:
            return '0.' + '0' * decimals
        return '0'

    # Separate integer and fractional parts
    integer_part = int(num)
    fractional_part = num - integer_part

    # Convert integer part
    int_str = _integer_to_base(integer_part, base_val)

    # Convert fractional part if needed
    frac_str = ''
    if decimals > 0:
        frac_str = _fractional_to_base(fractional_part, base_val, decimals)

    # Assemble result
    if decimals > 0:
        return sign + int_str + '.' + frac_str
    else:
        return sign + int_str


def _integer_to_base(n, base):
    """Convert integer part to given base."""
    if n == 0:
        return '0'

    digits = []
    while n > 0:
        # Use integer division for standard base conversion
        n, remainder = divmod(n, int(base))
        digits.append(_digit_to_char(remainder))

    return ''.join(reversed(digits))


def _fractional_to_base(frac, base, count):
    """Convert fractional part to given base."""
    digits = []
    for _ in range(count):
        frac *= base
        digit = int(frac)
        frac -= digit
        digits.append(_digit_to_char(digit))

    return ''.join(digits)


def _digit_to_char(d):
    """Convert digit value to character."""
    if 0 <= d < 10:
        return str(d)
    elif 10 <= d < 36:
        return chr(ord('A') + d - 10)
    else:
        return '?'  # For digits beyond base 36

def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into terms
    # Find all terms (including signs)
    terms = re.findall(r'[+-]?[^+-]+', expression)

    # Dictionary to store monomial -> coefficient
    monomial_coeffs = defaultdict(int)

    for term in terms:
        # Separate sign from the rest
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Handle coefficient
        coeff_str = ''
        i = 0
        while i < len(term) and term[i].isdigit():
            coeff_str += term[i]
            i += 1

        if coeff_str:
            coeff = int(coeff_str) * sign
        else:
            coeff = sign

        # Extract variables (everything after the coefficient)
        variables = term[i:]

        # Sort variables to normalize the monomial
        sorted_vars = ''.join(sorted(variables))

        # Add to our dictionary
        monomial_coeffs[sorted_vars] += coeff

    # Remove zero coefficients
    monomial_coeffs = {m: c for m, c in monomial_coeffs.items() if c != 0}

    if not monomial_coeffs:
        return "0"

    # Sort monomials by degree and then lexicographically
    def sort_key(monomial):
        return (len(monomial), monomial)

    sorted_monomials = sorted(monomial_coeffs.keys(), key=sort_key)

    # Build result string
    result_parts = []

    for i, monomial in enumerate(sorted_monomials):
        coeff = monomial_coeffs[monomial]

        # Handle the coefficient
        if coeff == 1 and i > 0:
            coeff_str = ""
        elif coeff == -1 and i > 0:
            coeff_str = "-"
        else:
            coeff_str = str(coeff)

        # Handle first term (no leading +)
        if i == 0:
            if coeff == 1 and monomial:
                result_parts.append(monomial)
            elif coeff == -1 and monomial:
                result_parts.append("-" + monomial)
            else:
                result_parts.append(coeff_str + monomial if monomial else coeff_str)
        else:
            if coeff == 1:
                result_parts.append("+" + monomial)
            elif coeff == -1:
                result_parts.append("-" + monomial)
            else:
                if coeff > 0:
                    result_parts.append("+" + coeff_str + monomial)
                else:
                    result_parts.append(coeff_str + monomial)

    return "".join(result_parts)

def decode_shift(s: str) -> str:
    result = ""
    for char in s:
        if 'a' <= char <= 'z':
            # Shift backward by 5 positions with wrapping
            shifted = (ord(char) - ord('a') - 5) % 26
            result += chr(shifted + ord('a'))
        else:
            result += char
    return result

def getAllPrimeFactors(n):
    # Error handling - check if n is a number (int or float, but not bool)
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []

    # Check if n is actually an integer (not a float like 2.0)
    if isinstance(n, float):
        return []

    if n < 0:
        return []

    # Edge case n=0
    if n == 0:
        return []

    # Edge case n=1
    if n == 1:
        return [1]

    factors = []
    # Check for 2
    while n % 2 == 0:
        factors.append(2)
        n //= 2

    # Check odd numbers from 3
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 2

    # If n > 2, then n is prime
    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Error handling
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return [[], []]

    if isinstance(n, float):
        return [[], []]

    if n < 0:
        return [[], []]

    if n == 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)

    # Count occurrences
    primes = []
    counts = []
    if factors:
        current_prime = factors[0]
        count = 1
        for i in range(1, len(factors)):
            if factors[i] == current_prime:
                count += 1
            else:
                primes.append(current_prime)
                counts.append(count)
                current_prime = factors[i]
                count = 1
        primes.append(current_prime)
        counts.append(count)

    return [primes, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Error handling
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []

    if isinstance(n, float):
        return []

    if n < 0:
        return []

    if n == 0:
        return []

    if n == 1:
        return [1]

    primes, counts = getUniquePrimeFactorsWithCount(n)

    # Calculate prime^count for each
    products = []
    for p, c in zip(primes, counts):
        products.append(p ** c)

    return products

