def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    total_sum = 0
    total_product = 1
    has_elements = False

    def flatten_and_process(items):
        nonlocal total_sum, total_product, has_elements
        for item in items:
            if isinstance(item, list):
                flatten_and_process(item)
            else:
                total_sum += item
                total_product *= item
                has_elements = True

    flatten_and_process(numbers)

    # If no elements were processed, return (0, 1) as specified
    if not has_elements:
        return (0, 1)

    return (total_sum, total_product)

