        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    # Check if n is prime first (a necessary condition for 2^n - 1 to be a Mersenne prime)
    if not is_prime(n):
