def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, value) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract the sorted values
    return [num for _, _, num in indexed_nums]

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    result = []
    for i in range(2, n):
        if is_prime(i):
            result.append(i)

    return result

def is_balanced(text, pairs):
    open_chars = set()
    close_to_open = {}

    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        open_chars.add(open_char)
        close_to_open[close_char] = open_char

    stack = []

    for char in text:
        if char in open_chars:
            stack.append(char)
        elif char in close_to_open:
            if not stack or stack[-1] != close_to_open[char]:
                return False
            stack.pop()

    return len(stack) == 0

from typing import List, Tuple


def sum_product(numbers: List[int]) -> Tuple[int, int]:
    sum_val = 0
    product_val = 1

    for num in numbers:
        sum_val += num
        product_val *= num

    return (sum_val, product_val)

