def get_closest_vowel(word):
    vowels = set('aeiouAEIOU')

    # Iterate from right to left to find the closest vowel from the right
    for i in range(len(word) - 1, 0, -1):
        if word[i] in vowels:
            # Check if there are characters on both sides
            if i > 0 and i < len(word) - 1:
                left_char = word[i - 1]
                right_char = word[i + 1]
                # Check if both neighbors are consonants (not vowels)
                if left_char not in vowels and right_char not in vowels:
                    return word[i]

    return ""

