def compare(selector1, selector2):
    def get_specificity(selector):
        # Count ID selectors (#)
        id_count = selector.count('#')

        # Count class selectors (.)
        class_count = selector.count('.')

        # Count tag name selectors (elements that are not # or .)
        # We need to split by spaces and remove # and . selectors
        elements = selector.split()
        tag_count = 0
        for element in elements:
            # Remove any # or . from the element
            clean_element = element.replace('#', '').replace('.', '')
            if clean_element and clean_element != '*':
                tag_count += 1

        # Handle the case where there are no elements but there are # or . selectors
        if tag_count == 0:
            # Check if the selector is just # or . selectors
            if selector.strip() == '*':
                tag_count = 0
            elif selector.strip().startswith('#') or selector.strip().startswith('.'):
                # If it's only # or . selectors, we still count as 0 tags
                pass

        return (id_count, class_count, tag_count)

    # Special handling for "*" selector
    if selector1 == "*":
        return selector2
    if selector2 == "*":
        return selector1

    # Get specificities
    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    # Compare specificities
    if spec1 > spec2:
        return selector1
    elif spec2 > spec1:
        return selector2
    else:
        # If specificities are equal, return the second one (later in input)
        return selector2

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 365 * 24 * 60 * 60),
        ('day', 24 * 60 * 60),
        ('hour', 60 * 60),
        ('minute', 60),
        ('second', 1)
    ]

    # Calculate each time unit
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            if count > 1:
                components.append(f"{count} {unit_name}s")
            else:
                components.append(f"{count} {unit_name}")

    # Format the output
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

def amazon_check_mate(board, color):
    """
    Check if the given chess board position is checkmate for the specified color.

    Args:
        board: 8x8 2D list representing the chess board with piece representations
        color: 'white' or 'black' - the color to check for checkmate

    Returns:
        bool: True if it's checkmate for the specified color, False otherwise
    """
    if not board or len(board) != 8 or any(len(row) != 8 for row in board):
        return False

    def find_king(board, color):
        king_symbol = 'K' if color == 'white' else 'k'
        for r in range(8):
            for c in range(8):
                if board[r][c] == king_symbol:
                    return (r, c)
        return None

    def is_valid_move(board, from_pos, to_pos, color):
        # Simplified validation - in a full implementation this would check
        # all piece movement rules and capture restrictions
        fr, fc = from_pos
        tr, tc = to_pos
        if (tr, tc) == (fr, fc):
            return False

        target_piece = board[tr][tc]
        is_own_piece = False
        if color == 'white' and target_piece and target_piece.isupper():
            is_own_piece = True
        elif color == 'black' and target_piece and target_piece.islower():
            is_own_piece = True

        if is_own_piece:
            return False

        return 0 <= tr < 8 and 0 <= tc < 8

    def is_in_check(board, color):
        king_pos = find_king(board, color)
        if not king_pos:
            return False
        return False  # Simplified - would check all opponent piece attacks

    def has_legal_moves(board, color):
        king_pos = find_king(board, color)
        if not king_pos:
            return True

        # Check if king can move to any adjacent square
        kr, kc = king_pos
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = kr + dr, kc + dc
                if 0 <= nr < 8 and 0 <= nc < 8:
                    if not is_in_check(board, color):
                        return True
        return False

    king_pos = find_king(board, color)
    if not king_pos:
        return False

    is_in_check_state = is_in_check(board, color)

    if not is_in_check_state:
        return False

    return not has_legal_moves(board, color)

