def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False

        # Check odd divisors up to sqrt(num)
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    if is_prime(n):
        return x
    else:
        return y

def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2

    # Iterate through all potential prime factors up to sqrt(d)
    while p * p <= d:
        if d % p == 0:
            # p is a prime factor
            # Divide d by p until it's no longer divisible (remove all occurrences)
            while d % p == 0:
                d //= p
            # Apply Euler's totient formula: result = result * (1 - 1/p)
            # which is equivalent to: result = result - result // p
            result -= result // p
        p += 1

    # If d > 1 after the loop, the remaining d is a prime factor
    if d > 1:
        result -= result // d

    return result

