def largest_divisor(n: int) -> int:
    if n <= 1:
        return 1

    largest = 1

    # Check divisors up to sqrt(n)
    i = 2
    while i * i <= n:
        if n % i == 0:
            # i is a divisor
            largest = max(largest, i)
            # n/i is also a divisor (if it's different from i)
            if n // i != i:
                largest = max(largest, n // i)
        i += 1

    return largest

