def parse_int(text):
    if text == "zero":
        return 0

    # Mapping of number words to their values
    units = {
        "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
        "six": 6, "seven": 7, "eight": 8, "nine": 9,
        "ten": 10, "eleven": 11, "twelve": 12, "thirteen": 13,
        "fourteen": 14, "fifteen": 15, "sixteen": 16, "seventeen": 17,
        "eighteen": 18, "nineteen": 19
    }

    tens = {
        "twenty": 20, "thirty": 30, "forty": 40, "fifty": 50,
        "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90
    }

    scales = {
        "hundred": 100, "thousand": 1000, "million": 1000000
    }

    # Combine all word mappings
    word_values = {}
    for w, v in units.items():
        word_values[w] = v
    for w, v in tens.items():
        word_values[w] = v
    for w, v in scales.items():
        word_values[w] = v

    # Preprocess: remove "and" and hyphens, split into tokens
    text = text.replace("and", "").replace("-", "")
    tokens = text.split()

    total = 0
    current = 0

    for token in tokens:
        if token in scales:
            scale_value = word_values[token]

            if scale_value == 100:
                current *= 100
            else:
                # For thousand/million, add current to total (multiplied if needed)
                if current > 0:
                    total += current * scale_value
                else:
                    total += scale_value
                current = 0
        else:
            # Regular number word
            current += word_values[token]

    total += current
    return total

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds (from most to least significant)
    units = [
        ('year', 31536000),   # 365 * 24 * 60 * 60
        ('day', 86400),       # 24 * 60 * 60
        ('hour', 3600),       # 60 * 60
        ('minute', 60),       # 60
        ('second', 1)         # 1
    ]

    result = []

    for unit_name, unit_value in units:
        if seconds >= unit_value:
            count = seconds // unit_value
            seconds %= unit_value
            # Add plural 's' if count > 1
            unit_name_with_plural = unit_name + 's' if count > 1 else unit_name
            result.append(f"{count} {unit_name_with_plural}")

    # Format the result with proper separators
    if len(result) == 1:
        return result[0]
    elif len(result) == 2:
        return f"{result[0]} and {result[1]}"
    else:
        return ", ".join(result[:-1]) + " and " + result[-1]

def greatest_common_divisor(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> greatest_common_divisor(3, 5)
    1
    >>> greatest_common_divisor(25, 15)
    5
    """
    # Handle edge cases
    if a == 0:
        return abs(b)
    if b == 0:
        return abs(a)

    # Use Euclidean algorithm
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b

    return a

def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2
    temp = d

    # Find all unique prime factors and apply Euler's totient formula
    while p * p <= temp:
        if temp % p == 0:
            result = result - result // p
            while temp % p == 0:
                temp //= p
        p += 1

    # If temp > 1, it's a prime factor
    if temp > 1:
        result = result - result // temp

    return result

