def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # For 2^n - 1 to be a Mersenne prime, n must be prime
    if not is_prime(n):
        return False

    # Calculate 2^n - 1
    mersenne_number = (1 << n) - 1  # This is 2^n - 1

    # Check if the Mersenne number is prime
    return is_prime(mersenne_number)

