import sys
from math import factorial

def comb(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1
    return factorial(n) // (factorial(k) * factorial(n - k))

def probability_all_collected(k, n):
    # Using inclusion-exclusion principle
    # P(all k types collected in n days) = sum_{i=0}^{k} (-1)^i * C(k,i) * ((k-i)/k)^n
    prob = 0.0
    for i in range(k + 1):
        sign = (-1) ** i
        choose = comb(k, i)
        prob += sign * choose * ((k - i) / k) ** n
    return prob

def binary_search(k, target_prob):
    left, right = 1, k * k  # Upper bound estimation

    while left < right:
        mid = (left + right) // 2
        prob = probability_all_collected(k, mid)

        if prob >= target_prob:
            right = mid
        else:
            left = mid + 1

    return left

