def is_valid(s):
    # Check if string is empty (must have at least one character)
    if len(s) == 0:
        return False

    # First character must be alpha, underscore, or dollar sign
    first_char = s[0]
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Remaining characters can be alpha, digit, underscore, or dollar sign
    for char in s[1:]:
