def simplify(expression):
    if not expression:
        return ""

    # Parse the expression into terms
    terms = []
    i = 0
    while i < len(expression):
        # Determine the sign
        if expression[i] == '+':
            sign = 1
            i += 1
        elif expression[i] == '-':
            sign = -1
            i += 1
        else:
            sign = 1

        # Parse the coefficient
        coeff_str = ""
        while i < len(expression) and expression[i].isdigit():
            coeff_str += expression[i]
            i += 1

        if coeff_str == "":
            coeff = sign * 1
        else:
            coeff = sign * int(coeff_str)

        # Parse the variables
        vars_str = ""
        while i < len(expression) and expression[i].islower():
            vars_str += expression[i]
            i += 1

        # If no variables, it's just a constant term
        if vars_str == "":
            terms.append((coeff, ""))
        else:
            # Sort variables alphabetically
            sorted_vars = ''.join(sorted(vars_str))
            terms.append((coeff, sorted_vars))

    # Combine like terms
    term_dict = {}
    for coeff, vars_str in terms:
        if vars_str in term_dict:
            term_dict[vars_str] += coeff
        else:
            term_dict[vars_str] = coeff

    # Remove terms with zero coefficient
    term_dict = {vars_str: coeff for vars_str, coeff in term_dict.items() if coeff != 0}

    # Sort terms
    sorted_terms = sorted(term_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Format output
    result = []
    first = True
    for vars_str, coeff in sorted_terms:
        if coeff == 0:
            continue

        if first:
            if coeff > 0:
                result.append(f"{coeff}{vars_str}" if coeff != 1 or vars_str == "" else vars_str)
            else:
                result.append(f"-{abs(coeff)}{vars_str}" if abs(coeff) != 1 or vars_str == "" else "-" + vars_str)
            first = False
        else:
            if coeff > 0:
                result.append(f"+{coeff}{vars_str}" if coeff != 1 or vars_str == "" else "+" + vars_str)
            else:
                result.append(f"-{abs(coeff)}{vars_str}" if abs(coeff) != 1 or vars_str == "" else "-" + vars_str)

    # Handle case where all terms cancelled out
    if not result:
        return "0"

    return "".join(result)

def order_by_points(nums):
    def digit_sum(n):
