    # Create pairs of (digit_sum, original_index, number) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract just the numbers from the sorted pairs
    return [num for _, _, num in indexed_nums]

def correct_bracketing(brackets: str):
    balance = 0

    for bracket in brackets:
        if bracket == "(":
            balance += 1
        elif bracket == ")":
            balance -= 1
            # If we have more closing brackets than opening brackets at any point,
            # the string is invalid
            if balance < 0:
                return False

    # All brackets are matched if balance is exactly 0
    return balance == 0

def cycpattern_check(a, b):
    if len(b) == 0:
        return True
    if len(b) > len(a):
        return False

    doubled_b = b + b
    for i in range(len(b)):
        rotation = doubled_b[i:i+len(b)]
        if rotation in a:
            return True

    return False

def parse_int(s):
    ones = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9,
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17,
        'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    multipliers = {
        'hundred': 100, 'thousand': 1000, 'million': 1000000
    }

    # Replace hyphens with spaces and convert to lowercase
    s = s.replace('-', ' ').lower()
    words = s.split()

    total = 0
    current = 0

    for word in words:
        if word == 'and':
            continue

        if word in ones:
            current += ones[word]
        elif word in tens:
            current += tens[word]
        elif word in multipliers:
            if word == 'hundred':
                current *= 100
            else:
                current *= multipliers[word]
                total += current
                current = 0

    total += current
    return total

def poohbear(code):
    # Initialize memory (dictionary for infinite cells, default 0)
    cells = {}
    ptr = 0  # cell pointer position
    copy_buffer = 0  # buffer for copy/paste commands

    # Filter only valid command characters
    valid_commands = set('+-><cpWEPNTQLIVABYD')
    commands = [ch for ch in code if ch in valid_commands]

    # Pre-process to find W-E loop pairs
    w_e_pairs = {}
    w_stack = []

    for i, cmd in enumerate(commands):
        if cmd == 'W':
            w_stack.append(i)
        elif cmd == 'E':
            if w_stack:
                start = w_stack.pop()
                w_e_pairs[start] = i
                w_e_pairs[i] = start

    # Execute commands
    pc = 0  # program counter
    output = []

    while pc < len(commands):
        cmd = commands[pc]
        current = cells.get(ptr, 0)

        if cmd == '+':
            cells[ptr] = (current + 1) % 256
            pc += 1
        elif cmd == '-':
            cells[ptr] = (current - 1) % 256
            pc += 1
        elif cmd == '>':
            ptr += 1
            pc += 1
        elif cmd == '<':
            ptr -= 1
            pc += 1
        elif cmd == 'c':
            copy_buffer = current
            pc += 1
        elif cmd == 'p':
            cells[ptr] = copy_buffer % 256
            pc += 1
        elif cmd == 'W':
            if current != 0:
                pc += 1
            else:
                pc = w_e_pairs[pc] + 1 if pc in w_e_pairs else pc + 1
        elif cmd == 'E':
            if current == 0:
                pc += 1
            else:
                pc = w_e_pairs[pc] + 1 if pc in w_e_pairs else pc + 1
        elif cmd == 'P':
            output.append(chr(current))
            pc += 1
        elif cmd == 'N':
            output.append(str(current))
            pc += 1
        elif cmd == 'T':
            cells[ptr] = (current * 2) % 256
            pc += 1
        elif cmd == 'Q':
            cells[ptr] = (current * current) % 256
            pc += 1
        elif cmd == 'U':
            cells[ptr] = int(current ** 0.5) % 256
            pc += 1
        elif cmd == 'L':
            cells[ptr] = (current + 2) % 256
            pc += 1
        elif cmd == 'I':
            cells[ptr] = (current - 2) % 256
            pc += 1
        elif cmd == 'V':
            cells[ptr] = (current // 2) % 256
            pc += 1
        elif cmd == 'A':
            cells[ptr] = (current + copy_buffer) % 256
            pc += 1
        elif cmd == 'B':
            cells[ptr] = (current - copy_buffer) % 256
            pc += 1
        elif cmd == 'Y':
            cells[ptr] = (current * copy_buffer) % 256
            pc += 1
        elif cmd == 'D':
            if copy_buffer != 0:
                cells[ptr] = (current // copy_buffer) % 256
            pc += 1

    return ''.join(output)

def count_divisors(n):
    if n <= 0:
        return 0

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

def histogram(s):
    # Split the string by spaces to get individual letters
    letters = s.split()

    # If no letters (empty string or only spaces)
    if not letters:
        return {}

    # Count frequency of each letter
    frequency = {}
    for letter in letters:
        frequency[letter] = frequency.get(letter, 0) + 1

    # Find the maximum frequency
    max_freq = max(frequency.values())

    # Return all letters with maximum frequency
    return {letter: count for letter, count in frequency.items() if count == max_freq}

