        elif cmd == 'Y':
            set_cell(pointer, get_cell(pointer) * copy_value)
        elif cmd == 'D':
            if copy_value != 0:
                set_cell(pointer, int(get_cell(pointer) / copy_value))

        ip += 1

    return ''.join(output)

import math

def sum_of_squares(n):
    # Check if n is a perfect square
    sqrt_n = int(math.sqrt(n))
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n can be represented as sum of two squares
    for i in range(1, int(math.sqrt(n)) + 1):
        remainder = n - i * i
        sqrt_remainder = int(math.sqrt(remainder))
        if sqrt_remainder * sqrt_remainder == remainder:
            return 2

    # Check Legendre's three-square theorem
    # n = 4^a * (8b + 7) for some integers a, b >= 0
    while n % 4 == 0:
        n //= 4

    if n % 8 == 7:
        return 4

    # If none of the above, return 3
    return 3

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []

    for group in groups:
        max_depth = 0
        current_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

