def poohbear(code):
    # Preprocess code to remove non-command characters
    commands = [c for c in code if c in "+-><cpWEPN-TQULIVABYD"]

    # Build jump map for W/E pairs
    jump_map = {}
    stack = []
    for i, cmd in enumerate(commands):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                start = stack.pop()
                jump_map[start] = i
                jump_map[i] = start

    # Initialize state
    cells = {}
    pointer = 0
    copied = 0
    ip = 0
    output = []

    while ip < len(commands):
        cmd = commands[ip]

        if cmd == '+':
            cells[pointer] = (cells.get(pointer, 0) + 1) % 256
        elif cmd == '-':
            cells[pointer] = (cells.get(pointer, 0) - 1) % 256
        elif cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == 'c':
            copied = cells.get(pointer, 0)
        elif cmd == 'p':
            cells[pointer] = copied
        elif cmd == 'W':
            if cells.get(pointer, 0) == 0:
                ip = jump_map[ip]
        elif cmd == 'E':
            if cells.get(pointer, 0) != 0:
                ip = jump_map[ip]
        elif cmd == 'P':
            output.append(chr(cells.get(pointer, 0)))
        elif cmd == 'N':
            output.append(str(cells.get(pointer, 0)))
        elif cmd == 'T':
            cells[pointer] = (cells.get(pointer, 0) * 2) % 256
        elif cmd == 'Q':
            cells[pointer] = (cells.get(pointer, 0) ** 2) % 256
        elif cmd == 'U':
            import math
            cells[pointer] = int(math.sqrt(cells.get(pointer, 0)))
        elif cmd == 'L':
            cells[pointer] = (cells.get(pointer, 0) + 2) % 256
        elif cmd == 'I':
            cells[pointer] = (cells.get(pointer, 0) - 2) % 256
        elif cmd == 'V':
            if copied != 0:
                cells[pointer] = (cells.get(pointer, 0) // copied) % 256
            else:
                cells[pointer] = 0
        elif cmd == 'A':
            cells[pointer] = (cells.get(pointer, 0) + copied) % 256
        elif cmd == 'B':
            cells[pointer] = (cells.get(pointer, 0) - copied) % 256
        elif cmd == 'Y':
            cells[pointer] = (cells.get(pointer, 0) * copied) % 256
        elif cmd == 'D':
            if copied != 0:
                cells[pointer] = (cells.get(pointer, 0) // copied) % 256
            else:
                cells[pointer] = 0

        ip += 1

    return ''.join(output)

def parse_int(s):
    # Define word to number mappings
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14,
        'fifteen': 15, 'sixteen': 16, 'seventeen': 17, 'eighteen': 18,
        'nineteen': 19, 'twenty': 20, 'thirty': 30, 'forty': 40,
        'fifty': 50, 'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    # Split the string into words and remove 'and' words
    words = s.replace(' and ', ' ').split()

    result = 0
    current = 0

    for word in words:
        if word in word_to_num:
            current += word_to_num[word]
        elif word == 'hundred':
            current *= 100
        elif word == 'thousand':
            result += current * 1000
            current = 0
        elif word == 'million':
            result += current * 1000000
            current = 0

    return result + current

def largest_divisor(n: int) -> int:
    if n <= 1:
        return 1

    # Find the smallest prime factor
    smallest_factor = n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            smallest_factor = i
            break

    # If no factor found, n is prime, so largest proper divisor is 1
    if smallest_factor == n:
        return 1

    # Return n divided by its smallest prime factor
    return n // smallest_factor

