    hostname_to_paths = defaultdict(set)

    for url in urls:
        hostname, path = parse_url(url)
        hostname_to_paths[hostname].add(path)

    # Create mapping from hash to list of hostnames
    hash_to_hostnames = defaultdict(list)

    for hostname, paths in hostname_to_paths.items():
        path_hash = hash_path_set(paths)
        hash_to_hostnames[path_hash].append(hostname)

    # Find groups with more than one hostname
    groups = []
    for hostnames in hash_to_hostnames.values():
        if len(hostnames) > 1:
