        elif char == 'p':
            tape[pointer] = clipboard
        elif char == 'W':
            if tape.get(pointer, 0) == 0:
                ip = jump_map[ip]
        elif char == 'E':
            if tape.get(pointer, 0) != 0:
                ip = jump_map[ip]
        elif char == 'P':
            output.append(chr(tape.get(pointer, 0)))
        elif char == 'N':
            output.append(str(tape.get(pointer, 0)))
        elif char == 'T':
            tape[pointer] = (tape.get(pointer, 0) * 2) % 256
        elif char == 'Q':
            tape[pointer] = (tape.get(pointer, 0) ** 2) % 256
        elif char == 'U':
            import math
            tape[pointer] = int(math.sqrt(tape.get(pointer, 0)))
        elif char == 'L':
            tape[pointer] = (tape.get(pointer, 0) + 2) % 256
        elif char == 'I':
            tape[pointer] = (tape.get(pointer, 0) - 2) % 256
        elif char == 'V':
            tape[pointer] = (tape.get(pointer, 0) // 2) % 256
        elif char == 'A':
            tape[pointer] = (tape.get(pointer, 0) + clipboard) % 256
        elif char == 'B':
            tape[pointer] = (tape.get(pointer, 0) - clipboard) % 256
        elif char == 'Y':
            tape[pointer] = (tape.get(pointer, 0) * clipboard) % 256
        elif char == 'D':
            if clipboard != 0:
                tape[pointer] = (tape.get(pointer, 0) // clipboard) % 256
            else:
                tape[pointer] = 0

        ip += 1

    return ''.join(output)

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(enumerate(nums), key=lambda x: (digit_sum(x[1]), x[0]))

def count_up_to(n):
    if n <= 2:
        return []

    # Create a boolean array and initialize all entries as True
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not prime numbers

    # Sieve of Eratosthenes
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            # Mark all multiples of i as not prime
            for j in range(i * i, n, i):
                is_prime[j] = False

    # Collect all prime numbers
    primes = []
    for i in range(2, n):
        if is_prime[i]:
            primes.append(i)

    return primes

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    is_negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % int(base)
            integer_digits.append(remainder)
            temp = temp // int(base)
        integer_digits.reverse()

    # Convert fractional part
    fractional_part = number - integer_part
    fractional_digits = []

    if fractional_part > 0 and decimals > 0:
        temp_fraction = fractional_part
        for _ in range(decimals):
            temp_fraction *= base
            digit = int(temp_fraction)
            fractional_digits.append(digit)
            temp_fraction -= digit

    # Format the result
    if not integer_digits:
        result = '0'
    else:
        result = ''.join(str(digit) for digit in integer_digits)

    if decimals > 0 and fractional_digits:
        result += '.'
        result += ''.join(str(digit) for digit in fractional_digits)

    # Handle negative sign
    if is_negative:
        result = '-' + result

    # Ensure proper formatting for numbers < 1
    if not is_negative and number < 1 and '.' in result:
        # If the result starts with a decimal point, we need a leading zero
        if result.startswith('.'):
            result = '0' + result

    # Convert digits to base-36 representation
    digit_map = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    final_result = ''
    for char in result:
        if char == '.':
            final_result += '.'
        elif char == '-':
            final_result += '-'
        else:
            digit_value = int(char)
            final_result += digit_map[digit_value]

    return final_result

def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    result = ""
    for i in range(len(a)):
        if a[i] == b[i]:
            result += "0"
        else:
            result += "1"
    return result

