def converter(number, decimals=0, base=3.141592653589793):
    if number == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Handle sign
    negative = number < 0
    number = abs(number)

    # Split into integer and fractional parts
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_result = ""
    else:
        digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        integer_result = ""
        while integer_part > 0:
            remainder = integer_part % base
            # Handle floating point precision issues
            if remainder >= base:
                remainder = base - 1e-10
            elif remainder < 0:
                remainder = 0
            integer_result = digits[int(remainder)] + integer_result
            integer_part = int((integer_part - remainder) / base)

    # Convert fractional part
    fractional_result = ""
    if decimals > 0:
        fractional_result = "."
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            # Handle floating point precision issues
            if digit >= base:
                digit = int(base - 1e-10)
            fractional_result += "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"[digit]
            fractional_part -= digit

    # Combine results
    if integer_result == "":
        result = "0" + fractional_result
    else:
        result = integer_result + fractional_result

    # Add negative sign if needed
    if negative:
        result = "-" + result

    return result

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    if n <= 1:
        return y
    if n == 2:
        return x
    if n % 2 == 0:
        return y
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return y
    return x

