def poohbear(code):
    # Initialize memory and pointer
    memory = {}
    pointer = 0
    copied = 0
    code_ptr = 0
    loop_stack = []
    output = []

    # Parse code to find loop pairs
    loop_pairs = {}
    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                start = stack.pop()
                loop_pairs[start] = i
                loop_pairs[i] = start

    while code_ptr < len(code):
        char = code[code_ptr]

        if char == '+':
            memory[pointer] = memory.get(pointer, 0) + 1
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == '-':
            memory[pointer] = memory.get(pointer, 0) - 1
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copied = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copied
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                code_ptr = loop_pairs[code_ptr]
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                code_ptr = loop_pairs[code_ptr]
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif char == 'T':
            memory[pointer] = memory.get(pointer, 0) * 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'Q':
            memory[pointer] = memory.get(pointer, 0) ** 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'U':
            import math
            memory[pointer] = int(math.sqrt(memory.get(pointer, 0)))
        elif char == 'L':
            memory[pointer] = memory.get(pointer, 0) + 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'V':
            memory[pointer] = memory.get(pointer, 0) // 2
        elif char == 'A':
            memory[pointer] = memory.get(pointer, 0) + copied
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'B':
            memory[pointer] = memory.get(pointer, 0) - copied
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'Y':
            memory[pointer] = memory.get(pointer, 0) * copied
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'D':
            if copied != 0:
                memory[pointer] = memory.get(pointer, 0) // copied
            else:
                memory[pointer] = 0

        code_ptr += 1

    return ''.join(output)

def amazon_check_mate(white_king_pos, white_amazon_pos):
    # Convert chess notation to coordinates (0-indexed)
    def parse_pos(pos):
        file = ord(pos[0]) - ord('a')  # a=0, b=1, ..., h=7
        rank = int(pos[1]) - 1  # 1=0, 2=1, ..., 8=7
        return (file, rank)

    white_king = parse_pos(white_king_pos)
    white_amazon = parse_pos(white_amazon_pos)

    # Check if a position is on the board
    def is_valid_pos(pos):
        return 0 <= pos[0] < 8 and 0 <= pos[1] < 8

    # Check if amazon attacks a position (queen-like + knight-like)
    def amazon_attacks(pos):
        ax, ay = white_amazon
        bx, by = pos

        # Same square - not an attack
        if (ax, ay) == (bx, by):
            return False

        # Queen-like moves: horizontal, vertical, diagonal
        if ax == bx:  # Same file (vertical)
            return True
        if ay == by:  # Same rank (horizontal)
            return True
        if abs(ax - bx) == abs(ay - by):  # Same diagonal
            return True

        # Knight-like moves: L-shaped (2 in one direction, 1 in perpendicular)
        dx = abs(ax - bx)
        dy = abs(ay - by)
        if (dx == 2 and dy == 1) or (dx == 1 and dy == 2):
            return True

        return False

    # Check if black king can make a valid move from a position
    def has_valid_move(black_king_pos):
        bx, by = black_king_pos
        # All 8 possible king moves plus staying put
        moves = [
            (bx + dx, by + dy)
            for dx in [-1, 0, 1]
            for dy in [-1, 0, 1]
            if not (dx == 0 and dy == 0)  # Can't stay on same square
        ]

        for next_pos in moves:
            # Must be on board
            if not is_valid_pos(next_pos):
                continue
            # Cannot move to white king's position
            if next_pos == white_king:
                continue
            # Cannot move to amazon's position
            if next_pos == white_amazon:
                continue
            # Cannot be adjacent to white king
            if abs(next_pos[0] - white_king[0]) <= 1 and abs(next_pos[1] - white_king[1]) <= 1:
                continue
            # This is a valid move
            return True

        return False

    # Check if black king on a position is in check (under attack by amazon)
    def is_in_check(black_king_pos):
        return amazon_attacks(black_king_pos)

    # Count the four scenarios
    checkmate = 0
    check = 0
    stalemate = 0
    safe_with_moves = 0

    # Iterate through all 64 squares
    for x in range(8):
        for y in range(8):
            black_king_pos = (x, y)

            # Invalid: occupied by white king or amazon
            if black_king_pos == white_king or black_king_pos == white_amazon:
                continue

            # Invalid: adjacent to white king (kings cannot be adjacent)
            if abs(x - white_king[0]) <= 1 and abs(y - white_king[1]) <= 1:
                continue

            # Now it's a valid position for black king
            in_check = is_in_check(black_king_pos)
            can_move = has_valid_move(black_king_pos)

            if in_check:
                if can_move:
                    check += 1  # Check: under attack but can escape
                else:
                    checkmate += 1  # Checkmate: under attack and cannot escape
            else:
                if can_move:
                    safe_with_moves += 1  # Safe with valid moves
                else:
                    stalemate += 1  # Stalemate: safe but no moves

    return [checkmate, check, stalemate, safe_with_moves]

