            return False

    return True

def fib4(n):
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Initialize the base cases for iteration
    a, b, c, d = 0, 0, 2, 0  # fib4(0), fib4(1), fib4(2), fib4(3)

    for i in range(4, n + 1):
        # Calculate fib4(i) as the sum of the previous 4 values
        next_val = a + b + c + d

        # Shift values forward: discard oldest, add new value
        a, b, c, d = b, c, d, next_val

    return d

