def simplify(expr):
    import re

    # Handle empty expression
    if not expr or not expr.strip():
        return ""

    # Find all terms with their signs
    # Pattern matches: optional sign, optional number, variables
    term_pattern = re.compile(r'([+-]?)(\d*)([a-z]+)')
    matches = term_pattern.findall(expr)

    if not matches:
        return ""

    # Dictionary to combine like terms: key = sorted variables, value = coefficient
    terms_dict = {}

    for sign, num, vars in matches:
        # Parse coefficient
        if num == '':
            coef = 1
        else:
            coef = int(num)

        if sign == '-':
            coef = -coef

        # Normalize variables by sorting them alphabetically
        sorted_vars = ''.join(sorted(vars))

        # Combine like terms
        if sorted_vars in terms_dict:
            terms_dict[sorted_vars] += coef
        else:
            terms_dict[sorted_vars] = coef

    # Remove terms with zero coefficient
    terms_dict = {k: v for k, v in terms_dict.items() if v != 0}

    if not terms_dict:
        return ""

    # Sort terms: first by number of variables (length), then lexicographically
    sorted_terms = sorted(terms_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Format output string
    result_parts = []
    for i, (vars, coef) in enumerate(sorted_terms):
        if coef == 1:
            term_str = vars
        elif coef == -1:
            term_str = '-' + vars
        elif coef > 0:
            term_str = str(coef) + vars
        else:
            term_str = str(coef) + vars

        if i == 0:
            # First term: no leading +
            result_parts.append(term_str)
        else:
            # Subsequent terms
            if coef > 0:
                result_parts.append('+' + term_str)
            else:
                result_parts.append(term_str)

    return ''.join(result_parts)

def is_balanced(input_string, pairs):
    # Create a mapping of closing characters to opening characters
    # and a set of opening characters
    opening_chars = set()
    closing_to_opening = {}

    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        opening_chars.add(opening)
        # If opening and closing are the same character, it's both
        if opening == closing:
            closing_to_opening[opening] = opening
        else:
            closing_to_opening[closing] = opening

    # Stack to keep track of opening characters
    stack = []

    for char in input_string:
        # If character is an opening character
        if char in opening_chars:
            # If it's also a closing character (self-matching)
            if char in closing_to_opening and closing_to_opening[char] == char:
                # For self-matching, we push and pop immediately
                # But we need to track the count, so we'll push it
                stack.append(char)
            else:
                # Regular opening character
                stack.append(char)
        # If character is a closing character
        elif char in closing_to_opening:
            # If stack is empty or the top doesn't match, it's unbalanced
            if not stack or stack[-1] != closing_to_opening[char]:
                return False
            stack.pop()

    # If stack is empty, all brackets were matched
    return len(stack) == 0

def next_smallest(lst):
    if len(lst) < 2:
        return None

    # Use a set to remove duplicates
    unique_elements = set(lst)

    # If we don't have at least 2 distinct elements, return None
    if len(unique_elements) < 2:
        return None

    # Find the smallest element
    smallest = min(unique_elements)

    # Remove the smallest element and find the new minimum
    unique_elements.remove(smallest)
    return min(unique_elements)

