def solution(input_string, comment_markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the position of the first comment marker
        first_comment_pos = len(line)
        for marker in comment_markers:
            pos = line.find(marker)
            if pos != -1 and pos < first_comment_pos:
                first_comment_pos = pos

        # Remove everything from the first comment marker onwards
        processed_line = line[:first_comment_pos]

        # Strip trailing whitespace
        processed_line = processed_line.rstrip()

        result_lines.append(processed_line)

    return '\n'.join(result_lines)

def smallest_change(arr):
    if not arr:
        return 0

    changes = 0
    left = 0
    right = len(arr) - 1

    while left < right:
        if arr[left] != arr[right]:
            changes += 1
        left += 1
        right -= 1

    return changes

