def getAllPrimeFactors(n):
    # Input validation
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Special case for 1
    if n == 1:
        return [1]

    factors = []
    # Handle factor 2
    while n % 2 == 0:
        factors.append(2)
        n = n // 2

    # Handle odd factors
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n = n // i
        i += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Input validation
    if not isinstance(n, int):
        return [[], []]
    if n <= 0:
        return [[], []]

    # Special case for 1
    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)

    if not factors:
        return [[], []]

    unique_factors = []
    counts = []

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    # Add the last group
    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Input validation
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Special case for 1
    if n == 1:
        return [1]

    unique_factors_counts = getUniquePrimeFactorsWithCount(n)
    unique_factors = unique_factors_counts[0]
    counts = unique_factors_counts[1]

    if not unique_factors:
        return []

    products = []
    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

def amazon_check_mate(white_king, amazon):
    def to_coords(pos):
        return ord(pos[0]) - ord('a'), int(pos[1]) - 1

    def from_coords(r, c):
        return chr(ord('a') + c), str(r + 1)

    def get_amazon_attacks(amz_r, amz_c):
        attacked = set()

        # Queen moves (horizontal, vertical, diagonal)
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                r, c = amz_r, amz_c
                while True:
                    r += dr
                    c += dc
                    if 0 <= r < 8 and 0 <= c < 8:
                        attacked.add((r, c))
                    else:
                        break

        # Knight moves (L-shaped)
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
                        (1, -2), (1, 2), (2, -1), (2, 1)]
        for dr, dc in knight_moves:
            r, c = amz_r + dr, amz_c + dc
            if 0 <= r < 8 and 0 <= c < 8:
                attacked.add((r, c))

        return attacked

    def is_king_adjacent(r1, c1, r2, c2):
        return abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1

    def get_adjacent_squares(r, c):
        adjacent = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < 8 and 0 <= nc < 8:
                    adjacent.append((nr, nc))
        return adjacent

    def classify_square(blk_r, blk_c, wk_r, wk_c, amz_r, amz_c, amazon_attacks):
        # Check if black king is adjacent to white king (invalid position)
        if is_king_adjacent(blk_r, blk_c, wk_r, wk_c):
            return None

        # Check if black king is under amazon's attack
        under_attack = (blk_r, blk_c) in amazon_attacks

        # Check all adjacent squares for escape options
        escape_available = False
        for ar, ac in get_adjacent_squares(blk_r, blk_c):
            # Skip if adjacent to white king
            if is_king_adjacent(ar, ac, wk_r, wk_c):
                continue
            # Skip if under amazon's attack
            if (ar, ac) in amazon_attacks:
                continue
            # This is a valid escape square
            escape_available = True
            break

        # Classify based on attack status and escape availability
        if under_attack and not escape_available:
            return "checkmate"
        elif under_attack and escape_available:
            return "check"
        elif not under_attack and not escape_available:
            return "stalemate"
        else:  # not under_attack and escape_available
            return "safe"

    # Convert positions to coordinates
    wk_r, wk_c = to_coords(white_king)
    amz_r, amz_c = to_coords(amazon)

    # Get all squares under amazon's attack
    amazon_attacks = get_amazon_attacks(amz_r, amz_c)

    # Analyze all possible black king positions
    result = {
        "checkmate": [],
        "check": [],
        "stalemate": [],
        "safe": []
    }

    for r in range(8):
        for c in range(8):
            classification = classify_square(r, c, wk_r, wk_c, amz_r, amz_c, amazon_attacks)
            if classification:
                square = from_coords(r, c)
                result[classification].append(square)

    return result

def compare(sel1, sel2):
    def parse_selector(sel):
        components = sel.split()
        id_count = 0
        class_count = 0
        tag_count = 0

        for component in components:
            if component == '*':
                continue

            id_count += component.count('#')
            class_count += component.count('.')

            if component and (component[0].isalnum() or component[0] == '_'):
                tag_count += 1

        return (id_count, class_count, tag_count)

    spec1 = parse_selector(sel1)
    spec2 = parse_selector(sel2)

    if spec1 > spec2:
        return sel1
    else:
        return sel2

def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0

    # Generate all palindromes up to n
    # Single digit palindromes (1-9)
    for i in range(1, min(10, n + 1)):
        if i % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    # Two digit palindromes (11, 22, 33, ...)
    for i in range(1, 10):
        palindrome = i * 11  # 11, 22, 33, ..., 99
        if palindrome > n:
            break
        if palindrome % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    # Three digit palindromes (101, 111, 121, ...)
    for i in range(1, 10):  # first digit
        for j in range(0, 10):  # middle digit
            palindrome = i * 100 + j * 10 + i  # e.g., 101, 111, 121, ...
            if palindrome > n:
                break
            if palindrome % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def parse_int(s):
    if not s:
        return 0

    # Define mappings
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14,
        'fifteen': 15, 'sixteen': 16, 'seventeen': 17, 'eighteen': 18,
        'nineteen': 19, 'twenty': 20, 'thirty': 30, 'forty': 40,
        'fifty': 50, 'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    scale_words = {
        'hundred': 100,
        'thousand': 1000,
        'million': 1000000
    }

    # Split the string into words, handling hyphens
    words = s.replace('-', ' ').split()

    # Remove 'and' words
    words = [word for word in words if word != 'and']

    # Process words
    total = 0
    current = 0

    for word in words:
        if word in word_to_num:
            current += word_to_num[word]
        elif word in scale_words:
            if word == 'hundred':
                current *= scale_words[word]
            else:
                total += current * scale_words[word]
                current = 0

    total += current
    return total

def exchange_sort(arr):
    n = len(arr)
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

def is_balanced(sequence):
    stack = []
    pairs = {')': '(', '}': '{', ']': '['}

    for char in sequence:
        if char in pairs.values():
            stack.append(char)
        elif char in pairs:
            if not stack or stack.pop() != pairs[char]:
                return False
        else:
            return False

    return len(stack) == 0

