import math

def poohbear(code):
    tape = {}  # Position -> value (default 0 for uninitialized positions)
    pos = 0    # Current cell pointer position
    clipboard = 0  # Stores copied cell value
    output = []    # Collect output

    def wrap(value):
        """Wrap value to 0-255 range, handling negatives"""
        value = int(value)
        return ((value % 256) + 256) % 256

    # Pre-compute W/E loop pairs
    w_pairs = {}  # W index -> corresponding E index
    stack = []

    for i, cmd in enumerate(code):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                w_idx = stack.pop()
                w_pairs[w_idx] = i

    ip = 0  # Instruction pointer
    while ip < len(code):
        cmd = code[ip]

        if cmd == 'W':
            cell_val = tape.get(pos, 0)
            if cell_val == 0:
                ip = w_pairs.get(ip, ip) + 1
            else:
                ip += 1
        elif cmd == 'E':
            cell_val = tape.get(pos, 0)
            if cell_val != 0:
                ip = w_pairs.get(ip, ip)
                continue
            ip += 1
        elif cmd == '+':
            tape[pos] = wrap(tape.get(pos, 0) + 1)
            ip += 1
        elif cmd == '-':
            tape[pos] = wrap(tape.get(pos, 0) - 1)
            ip += 1
        elif cmd == '>':
            pos += 1
            ip += 1
        elif cmd == '<':
            pos -= 1
            ip += 1
        elif cmd == 'c':
            clipboard = tape.get(pos, 0)
            ip += 1
        elif cmd == 'p':
            tape[pos] = wrap(clipboard)
            ip += 1
        elif cmd == 'P':
            cell_val = tape.get(pos, 0)
            if cell_val > 0:
                output.append(chr(cell_val))
            ip += 1
        elif cmd == 'N':
            output.append(str(tape.get(pos, 0)))
            ip += 1
        elif cmd == 'T':
            cell_val = tape.get(pos, 0)
            tape[pos] = wrap(cell_val * 2)
            ip += 1
        elif cmd == 'Q':
            cell_val = tape.get(pos, 0)
            tape[pos] = wrap(cell_val * cell_val)
            ip += 1
        elif cmd == 'U':
            cell_val = tape.get(pos, 0)
            tape[pos] = wrap(int(math.sqrt(cell_val)))
            ip += 1
        elif cmd == 'L':
            tape[pos] = wrap(tape.get(pos, 0) + 2)
            ip += 1
        elif cmd == 'I':
            tape[pos] = wrap(tape.get(pos, 0) - 2)
            ip += 1
        elif cmd == 'V':
            cell_val = tape.get(pos, 0)
            tape[pos] = wrap(cell_val // 2)
            ip += 1
        elif cmd == 'A':
            cell_val = tape.get(pos, 0)
            tape[pos] = wrap(cell_val + clipboard)
            ip += 1
        elif cmd == 'B':
            cell_val = tape.get(pos, 0)
            tape[pos] = wrap(cell_val - clipboard)
            ip += 1
        elif cmd == 'Y':
            cell_val = tape.get(pos, 0)
            tape[pos] = wrap(cell_val * clipboard)
            ip += 1
        elif cmd == 'D':
            cell_val = tape.get(pos, 0)
            if clipboard != 0:
                tape[pos] = wrap(cell_val // clipboard)
            ip += 1
        else:
            ip += 1

    return ''.join(output)

def choose(n, k):
    if k < 0 or n < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry property to reduce computation
    k = min(k, n - k)

    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

