def longest(strings: List[str]) -> Optional[str]:
    if not strings:
        return None

    longest_str = strings[0]
    max_len = len(longest_str)

    for s in strings:
        current_len = len(s)
        if current_len > max_len:
            max_len = current_len
            longest_str = s

    return longest_str

def is_balanced(s, pairs):
    # Create a mapping of opening to closing characters and vice versa
    open_to_close = {}
    close_to_open = {}

    # Process pairs to build mappings
    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        open_to_close[open_char] = close_char
        close_to_open[close_char] = open_char

    # Stack to keep track of opening characters
    stack = []

    for char in s:
        # If character is an opening character
        if char in open_to_close:
            stack.append(char)
        # If character is a closing character
        elif char in close_to_open:
            # If stack is empty or the top element doesn't match, it's unbalanced
            if not stack or stack[-1] != close_to_open[char]:
                return False
            # Pop the matching opening character
            stack.pop()

    # If stack is empty, all characters were matched
    return len(stack) == 0

