def monotonic(l: list):
    """Return True if list elements are monotonically increasing or decreasing."""
    # Edge cases: empty or single element lists are monotonic
    if len(l) <= 1:
        return True

    is_increasing = True
    is_decreasing = True

    for i in range(1, len(l)):
        if l[i] < l[i-1]:
            is_increasing = False
        if l[i] > l[i-1]:
            is_decreasing = False

        # Early exit if neither trend is valid
        if not is_increasing and not is_decreasing:
            break

    return is_increasing or is_decreasing

