def pig_latin(word):
    # Check for empty string
    if not word:
        return None

    # Check if all characters are alphabetic
    if not word.isalpha():
        return None

    # Convert to lowercase
    word = word.lower()

    vowels = 'aeiou'

    # Check if the word starts with a vowel
    if word[0] in vowels:
        return word + 'way'

    # Find the first vowel
    for i, char in enumerate(word):
        if char in vowels:
            # Move consonants before this vowel to the end
            return word[i:] + word[:i] + 'ay'

    # No vowels found
    return word + 'ay'

