def amazon_check_mate(king, amazon):
    def pos_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def coords_to_pos(x, y):
        return chr(x + ord('a')) + str(y + 1)

    def is_valid(x, y):
        return 0 <= x < 8 and 0 <= y < 8

    def is_attacked(x, y, king_pos, amazon_pos):
        # Check if square (x,y) is attacked by amazon
        ax, ay = amazon_pos
        kx, ky = king_pos

        # Check queen moves (rook + bishop)
        if ax == x or ay == y or abs(ax - x) == abs(ay - y):
            # Check if king is blocking the attack
            if ax == x:
                # Vertical attack
                if (kx == x and (ky < max(ay, y) and ky > min(ay, y))):
                    return False
            elif ay == y:
                # Horizontal attack
                if (ky == y and (kx < max(ax, x) and kx > min(ax, x))):
                    return False
            else:
                # Diagonal attack
                if (abs(kx - x) == abs(ky - y) and 
                    kx < max(ax, x) and kx > min(ax, x) and 
                    ky < max(ay, y) and ky > min(ay, y)):
                    return False
            return True

        # Check knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            if x == ax + dx and y == ay + dy:
                return True

        return False

    def is_safe(x, y, king_pos, amazon_pos):
        # Check if square (x,y) is safe for black king
        # Not attacked by amazon
        if is_attacked(x, y, king_pos, amazon_pos):
            return False

        # Not adjacent to white king
        kx, ky = king_pos
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                if x + dx == kx and y + dy == ky:
                    return False

        return True

    def can_escape(x, y, king_pos, amazon_pos):
        # Check if black king at (x,y) can escape to a safe square
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and is_safe(nx, ny, king_pos, amazon_pos):
                    return True
        return False

    def get_all_positions():
        positions = []
        for x in range(8):
            for y in range(8):
                positions.append((x, y))
        return positions

    king_pos = pos_to_coords(king)
    amazon_pos = pos_to_coords(amazon)

    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    all_positions = get_all_positions()

    for x, y in all_positions:
        # Skip positions where white king and black king would be adjacent
        kx, ky = king_pos
        if abs(x - kx) <= 1 and abs(y - ky) <= 1:
            continue

        # Skip positions where amazon and black king are on the same square
        ax, ay = amazon_pos
        if x == ax and y == ay:
            continue

        # Check if black king is under attack
        if is_attacked(x, y, king_pos, amazon_pos):
            # Check if black king can escape
            if can_escape(x, y, king_pos, amazon_pos):
                check += 1
            else:
                # Checkmate
                checkmate += 1
        else:
            # Black king is safe
            if can_escape(x, y, king_pos, amazon_pos):
                safe += 1
            else:
                # Stalemate
                stalemate += 1

    return [checkmate, check, stalemate, safe]

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        return 1

    # Find the smallest prime factor
    if n % 2 == 0:
        smallest_prime = 2
    else:
        smallest_prime = n  # Assume prime initially
        i = 3
        while i * i <= n:
            if n % i == 0:
                smallest_prime = i
                break
            i += 2

    return n // smallest_prime

