import re

def simplify(expr):
    # Split the expression into monomials, keeping track of signs
    monomials_str = re.split(r'(?=[+-])', expr)
    monomials_str = [m.strip() for m in monomials_str if m.strip()]

    if not monomials_str:
        return "0"

    # Parse each monomial into coefficient and variables
    parsed = []
    for mon in monomials_str:
        # Determine sign
        if mon[0] == '-':
            sign = -1
            mon = mon[1:]
        elif mon[0] == '+':
            sign = 1
            mon = mon[1:]
        else:
            sign = 1

        # Parse coefficient (digits at the start)
        i = 0
        while i < len(mon) and mon[i].isdigit():
            i += 1

        if i > 0:
            coeff = int(mon[:i]) * sign
            variables = ''.join(sorted(mon[i:]))
        else:
            coeff = sign
            variables = ''.join(sorted(mon))

        parsed.append((coeff, variables))

    # Combine like terms (same variables)
    terms = {}
    for coeff, variables in parsed:
        key = frozenset(variables)
        terms[key] = terms.get(key, 0) + coeff

    # Filter out zero coefficients and convert to list
    result = []
    for key in terms:
        coeff = terms[key]
        if coeff != 0:
            result.append((coeff, ''.join(sorted(key))))

    if not result:
        return "0"

    # Sort: first by number of variables, then lexicographically
    result.sort(key=lambda x: (len(x[1]), x[1]))

    # Format output
    output_parts = []
    for i, (coeff, variables) in enumerate(result):
        if coeff == 1:
            part = variables
        elif coeff == -1:
            part = '-' + variables
        elif coeff > 0:
            part = str(coeff) + variables
        else:
            part = str(coeff) + variables

        # No leading + for first term
        if i == 0 and part.startswith('+'):
            part = part[1:]
        elif i > 0 and part.startswith('-'):
            pass  # Keep the minus
        elif i > 0:
            part = '+' + part

        output_parts.append(part)

    return ''.join(output_parts)

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    if n <= 2:
        return []

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
