def parse_nested_parens(paren_string: str) -> List[int]:
    if not paren_string.strip():
        return []

    groups = paren_string.split()
    result = []

    for group in groups:
        level = 0
        max_level = 0
        for char in group:
            if char == '(':
                level += 1
                max_level = max(max_level, level)
            elif char == ')':
                level -= 1
        result.append(max_level)

    return result

