import re

def differentiate(poly_string, x_value):
    # Normalize consecutive signs
    poly_string = poly_string.replace('+-', '-').replace('--', '+')

    # Split by + and - but keep signs with terms
    terms = re.split(r'(?=[+-])', poly_string)
    terms = [t for t in terms if t]  # Remove empty strings

    total = 0

    for term in terms:
        # Parse coefficient and exponent
        if 'x' in term:
            # Find position of x
            x_pos = term.index('x')
            coeff_part = term[:x_pos]
            exp_part = term[x_pos+1:]

            # Parse exponent
            if '^' in exp_part:
                exp = int(exp_part.split('^')[1])
            else:
                exp = 1

            # Parse coefficient
            if coeff_part == '' or coeff_part == '+':
                coeff = 1
            elif coeff_part == '-':
                coeff = -1
            else:
                coeff = int(coeff_part)
        else:
            # Constant term - derivative is 0
            continue

        # Apply power rule: derivative of cx^n is cnx^(n-1)
        if exp == 0:
            term_result = 0
        elif exp == 1:
            term_result = coeff
        else:
            term_result = coeff * exp * (x_value ** (exp - 1))

        total += term_result

    return total

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    gems = list(map(int, lines[1].split()))

    # Precompute palindromes
    is_palindrome = [[False] * n for _ in range(n)]

    # Every single gemstone is a palindrome
    for i in range(n):
        is_palindrome[i][i] = True

    # Check for palindromes of length 2
    for i in range(n - 1):
        if gems[i] == gems[i + 1]:
            is_palindrome[i][i + 1] = True

    # Check for palindromes of length 3 and more
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if gems[i] == gems[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP solution
    # dp[i][j] represents minimum seconds to destroy substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Fill DP table
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if i == j:
                # Single gemstone
                dp[i][j] = 1
            elif is_palindrome[i][j]:
                # If the substring is palindrome, destroy it in 1 second
                dp[i][j] = 1
            else:
                # Split into two parts and take minimum
                dp[i][j] = float('inf')
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

