    # Collect all prime numbers less than n
    return [i for i in range(2, n) if is_prime[i]]

def longest_palindrome(s: str) -> str:
    if not s:
        return ""

    start, end = 0, 0

    def expand_around_center(left: int, right: int) -> tuple[int, int]:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        l1, r1 = expand_around_center(i, i)
        l2, r2 = expand_around_center(i, i + 1)

        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]

def valid_mersenne(n):
    # Handle edge cases
    if n <= 1:
        return False

    # Check if n is prime (necessary condition for Mersenne prime)
    if not is_prime(n):
        return False

    # For Mersenne primes, we need to check if 2^n - 1 is prime
    # Using Lucas-Lehmer test for Mersenne numbers
    # This is the most efficient way to test Mersenne primality
    if n == 2:
        return True

    # Lucas-Lehmer test
    # For Mersenne numbers 2^p - 1 where p is prime
    m = (1 << n) - 1  # This is 2^n - 1

    # Special case for n = 2
    if n == 2:
        return True

    # Lucas-Lehmer test
    s = 4
    for i in range(n - 2):
        s = (s * s - 2) % m

    return s == 0

def is_prime(n):
    """Check if a number is prime using trial division up to sqrt(n)"""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

import math

def is_perfect_square(n):
    if n < 0:
        return False
    root = int(math.sqrt(n))
    return root * root == n

def sum_of_squares(n):
    # Check if n is a perfect square
    if is_perfect_square(n):
        return 1

    # Check if n is a sum of two squares
    sqrt_n = int(math.sqrt(n))
    for i in range(1, sqrt_n + 1):
        remainder = n - i * i
        if is_perfect_square(remainder):
            return 2

    # Check Legendre's three-square theorem
    # Remove all factors of 4
    while n % 4 == 0:
        n //= 4

    # If n ≡ 7 (mod 8), then it requires 4 squares
    if n % 8 == 7:
        return 4

    # Otherwise, it can be represented as sum of 3 squares
    return 3

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)

