def sum_of_squares(n):
    import math

    # Step 1: Check if n is a perfect square (answer = 1)
    root = math.isqrt(n)
    if root * root == n:
        return 1

    # Step 2: Check if n can be written as sum of 2 perfect squares (answer = 2)
    for i in range(root + 1):
        remainder = n - i * i
        if remainder < 0:
            break
        j = math.isqrt(remainder)
        if j * j == remainder:
            return 2

    # Step 3: Check Legendre's three-square theorem
    # A number can be written as sum of 3 squares iff it's NOT of the form 4^a(8b + 7)
    temp = n
    while temp % 4 == 0:
        temp //= 4
    if temp % 8 == 7:
        return 4

    # Step 4: Otherwise, answer = 3
    return 3

