            if 0 <= r <= 7 and 0 <= c <= 7:
                attacks.add((r, c))

        return attacks

    # Get all adjacent squares to a king position
    def get_king_adjacent(pos):
        row, col = chess_to_coord(pos)
        adjacent = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                r, c = row + dr, col + dc
                if 0 <= r <= 7 and 0 <= c <= 7:
                    adjacent.append((r, c))
        return adjacent

    # Pre-compute all attack squares
    amazon_attacks = get_amazon_attacks(amazon)

    # Get positions of white king and amazon
    white_king_row, white_king_col = chess_to_coord(king)
    amazon_row, amazon_col = chess_to_coord(amazon)

    # Get all squares adjacent to white king (invalid for black king)
    white_king_adjacent = set(get_king_adjacent(king))

    # Initialize result counts
    result = [0, 0, 0, 0]  # [checkmate, check, stalemate, safe_with_move]

    # Check all possible black king positions
    for row in range(8):
        for col in range(8):
            # Skip if square is occupied by white king or amazon
            if (row, col) == (white_king_row, white_king_col) or (row, col) == (amazon_row, amazon_col):
                continue

            # Skip if square is adjacent to white king
            if (row, col) in white_king_adjacent:
                continue

            # This is a valid black king position
            is_attacked = (row, col) in amazon_attacks

            # Check if there's a valid move from this position
            has_valid_move = False
            # Check all 8 adjacent squares
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    new_row, new_col = row + dr, col + dc

                    # Check if new position is on board
                    if 0 <= new_row <= 7 and 0 <= new_col <= 7:
                        # Check if new position is occupied by white king or amazon
                        if (new_row, new_col) == (white_king_row, white_king_col) or (new_row, new_col) == (amazon_row, amazon_col):
                            continue

                        # Check if new position is adjacent to white king
                        if (new_row, new_col) in white_king_adjacent:
                            continue

                        # Check if new position is attacked by amazon
                        if (new_row, new_col) in amazon_attacks:
                            continue

                        # If we reach here, this is a valid move
                        has_valid_move = True
                        break
                if has_valid_move:
                    break

            # Classify position
            if is_attacked:
                if has_valid_move:
                    result[1] += 1  # Check
                else:
                    result[0] += 1  # Checkmate
            else:
                if has_valid_move:
                    result[3] += 1  # Safe with move
                else:
                    result[2] += 1  # Stalemate

    return result

