def factorize(n):
    if n <= 1:
        return []

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getAllPrimeFactors(n):
    # Input validation
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Special case for n = 1
    if n == 1:
        return [1]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Input validation
    if not isinstance(n, int):
        return [[], []]
    if n <= 0:
        return [[], []]

    # Special case for n = 1
    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)

    if not factors:
        return [[], []]

    unique_factors = []
    counts = []

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Input validation
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Special case for n = 1
    if n == 1:
        return [1]

    # Get unique prime factors with their counts
    unique_factors, counts = getUniquePrimeFactorsWithCount(n)

    if not unique_factors:
        return []

    products = []
    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

