import ast

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """

    # Handle string representation of list by parsing it
    if isinstance(numbers, str):
        try:
            numbers = ast.literal_eval(numbers)
        except (ValueError, SyntaxError):
            raise TypeError("Input must be a list of integers or a string representation of a list")

    # Validate that input is a list
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list of integers")

    # Validate all elements are integers (excluding booleans)
    for i, num in enumerate(numbers):
        if isinstance(num, bool) or not isinstance(num, int):
            raise TypeError(f"All elements must be integers, got {type(num)} at index {i}")

    # Handle empty list case
    if len(numbers) == 0:
        return (0, 1)

    # Compute sum and product
    total_sum = sum(numbers)
    total_product = 1
    for num in numbers:
        total_product *= num

    return (total_sum, total_product)

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            # Handle floating point precision issues
            if remainder >= base:
                remainder = base - 1e-10
            elif remainder < 0:
                remainder = 0
            integer_digits.append(int(remainder))
            temp = (temp - remainder) / base

    # Reverse to get correct order
    integer_digits.reverse()

    # Convert fractional part
    fractional_part = number - integer_part
    fractional_digits = []

    if fractional_part > 0 and decimals > 0:
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            fractional_digits.append(digit)
            fractional_part -= digit

    # Format the result
    if not integer_digits:
        result = '0'
    else:
        result = ''.join(str(digit) for digit in integer_digits)

    if decimals > 0 and fractional_digits:
        result += '.'
        result += ''.join(str(digit) for digit in fractional_digits)

    # Handle negative sign
    if negative:
        result = '-' + result

    # Handle leading zero for numbers < 1
    if number < 1 and not negative:
        if '.' in result:
            result = '0' + result
        else:
            result = '0.' + result

    return result

def almost_everywhere_zero(n, k):
    MOD = 10**9 + 7

    s = str(n)
    n_len = len(s)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, count, tight, leading_zeros):
        # Base case: all digits placed
        if pos == n_len:
            return 1 if count == k else 0

        # Determine upper bound for current digit
        upper = int(s[pos]) if tight else 9

        result = 0

        for digit in range(upper + 1):
            new_tight = tight and (digit == upper)

            if leading_zeros and digit == 0:
                # Still in leading zeros, count doesn't change
                result = (result + dp(pos + 1, count, new_tight, True)) % MOD
            else:
                # Not in leading zeros or placing non-zero digit
                new_count = count + (1 if digit != 0 else 0)
                if new_count <= k:
                    result = (result + dp(pos + 1, new_count, new_tight, False)) % MOD

        return result

    return dp(0, 0, True, True)

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False

        # Check odd divisors up to sqrt(num)
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    if is_prime(n):
        return x
    else:
        return y

