    integer_part = int(number)
    result = []

    if integer_part == 0:
        result = ['0']
    else:
        while integer_part > 0:
            remainder = integer_part % base
            if remainder < 10:
                result.append(str(remainder))
            else:
                result.append(chr(ord('A') + remainder - 10))
            integer_part //= base

    # Reverse to get correct order
    result.reverse()

    # Handle fractional part
    fractional_part = number - int(number)
    if decimals > 0 and fractional_part != 0:
        result.append('.')
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            if digit < 10:
                result.append(str(digit))
            else:
                result.append(chr(ord('A') + digit - 10))
            fractional_part -= digit
    elif decimals == 0 and fractional_part != 0:
        # If we have a fractional part but no decimals requested,
        # we still need to check if there's a fractional part to represent
        # But since we're not adding decimals, we don't add anything
        pass

    # Join result
    final_result = ''.join(result)

    # Add negative sign if needed
    if is_negative:
        final_result = '-' + final_result

    # Handle case where absolute value < 1
    if number < 1 and '.' in final_result:
        # Check if we need to add leading zero
        parts = final_result.split('.')
        if len(parts) > 1 and parts[0] == '0':
            # Already has leading zero
            pass
        elif len(parts) > 1 and parts[0] == '-0':
            # Already has leading zero for negative
            pass
        elif len(parts) > 1 and parts[0] == '':
            # This case shouldn't happen but just in case
            pass
        else:
            # Check if we need to add leading zero
            if not is_negative and parts[0] == '0':
                pass  # Already has leading zero
            elif is_negative and parts[0] == '-0':
                pass  # Already has leading zero
            elif not is_negative and parts[0] != '0':
                # Need to add leading zero for numbers less than 1
                pass  # Actually, we should not be adding leading zeros for numbers less than 1
                # Let's recheck the logic
                pass

    # Special case for numbers less than 1
    if number < 1 and '.' in final_result:
        # Check if we have a leading zero already
        if final_result.startswith('0.'):
            pass  # Already correct
        elif final_result.startswith('-0.'):
            pass  # Already correct
        elif final_result.startswith('.'):
            # Need to add leading zero
            if is_negative:
                final_result = '-0' + final_result[1:]
            else:
                final_result = '0' + final_result

    return final_result

import random

def valid_mersenne(n):
    if n <= 1:
        return False

    # n must be prime for 2^n - 1 to be a Mersenne prime
    if not is_prime(n):
        return False

    # Compute 2^n - 1
    m = pow(2, n) - 1

    # Check if m is prime
    return is_prime(m)

def is_prime(num):
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False

    # For smaller numbers, trial division is efficient
    if num < 1000000:
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    # For larger numbers, use Miller-Rabin
    return miller_rabin(num)

def miller_rabin(n, k=10):
    """Miller-Rabin primality test for large numbers"""
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    # Write n-1 as 2^r * d where d is odd
    r = 0
    d = n - 1
    while d % 2 == 0:
        r += 1
        d //= 2

    # Test with k random witnesses
    for _ in range(k):
        a = random.randrange(2, n - 1)
        x = pow(a, d, n)

        if x == 1 or x == n - 1:
            continue

        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False

    return True

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, value) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract the sorted values
    return [num for _, _, num in indexed_nums]

import sys

def solve():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    gems = list(map(int, lines[1].split()))

    # Precompute palindromes
    is_palindrome = [[False] * n for _ in range(n)]

    # Every single gem is a palindrome
    for i in range(n):
        is_palindrome[i][i] = True

    # Check for palindromes of length 2
    for i in range(n - 1):
        if gems[i] == gems[i + 1]:
            is_palindrome[i][i + 1] = True

    # Check for palindromes of length 3 and more
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if gems[i] == gems[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP approach: dp[i][j] represents minimum seconds to destroy substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Fill DP table
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if i == j:
                # Single gemstone - takes 1 second
                dp[i][j] = 1
            elif is_palindrome[i][j]:
                # If the whole substring is palindrome, remove it in 1 second
                dp[i][j] = 1
            else:
                # Find minimum by trying all possible splits
                dp[i][j] = float('inf')
                for k in range(i, j):
                    if dp[i][j] > dp[i][k] + dp[k + 1][j]:
                        dp[i][j] = dp[i][k] + dp[k + 1][j]

    print(dp[0][n - 1])

