import re
from collections import defaultdict

def simplify(expression: str) -> str:
    # Parse the expression into terms with their signs
    # Each term is represented as (sign, coefficient, variables)
    terms = re.findall(r'([+-]?)(\d*)([a-z]+)', expression)

    # Dictionary to store combined coefficients for each sorted variable string
    term_dict = defaultdict(int)

    for sign, coeff, vars in terms:
        # Determine the sign
        if sign == '-':
            sign_val = -1
        elif sign == '+':
            sign_val = 1
        else:
            sign_val = 1  # No sign means positive

        # Determine the coefficient
        if coeff == '':
            coef = 1
        else:
            coef = int(coeff)

        # Apply the sign to the coefficient
        coef = sign_val * coef

        # Sort the variables alphabetically (xy == yx)
        sorted_vars = ''.join(sorted(vars))

        # Add to the dictionary
        term_dict[sorted_vars] += coef

    # Filter out terms with zero coefficient
    term_dict = {k: v for k, v in term_dict.items() if v != 0}

    # Sort terms by number of variables, then lexicographically
    sorted_terms = sorted(term_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Format the output string
    result = []
    for vars, coef in sorted_terms:
        if coef == 1:
            term_str = vars
        elif coef == -1:
            term_str = '-' + vars
        else:
            term_str = str(coef) + vars

        if len(result) == 0:
            # First term: don't add + for positive
            result.append(term_str)
        else:
            # Subsequent terms: add + for positive, - is already included for negative
            if coef > 0 and not term_str.startswith('-'):
                result.append('+' + term_str)
            else:
                result.append(term_str)

    return ''.join(result)

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    if n < 2:
        return y

    if n == 2:
        return x

    if n % 2 == 0:
        return y

    limit = int(n**0.5) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return y

    return x

def poohbear(code):
    memory = {}
    pointer = 0
    copied_value = 0
    output = []

    valid_commands = set('+-><cpWEPNTQULIYABD')
    commands = [c for c in code if c in valid_commands]

    w_to_e = {}
    e_to_w = {}
    stack = []

    for i, cmd in enumerate(commands):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                w_pos = stack.pop()
                w_to_e[w_pos] = i
                e_to_w[i] = w_pos

    pc = 0

    while pc < len(commands):
        cmd = commands[pc]
        val = memory.get(pointer, 0)

        if cmd == 'W':
            if val == 0:
                pc = w_to_e.get(pc, pc + 1)
                continue
            pc += 1
        elif cmd == 'E':
            if val != 0:
                pc = e_to_w.get(pc, pc + 1)
                continue
            pc += 1
        elif cmd == '+':
            memory[pointer] = (val + 1) % 256
        elif cmd == '-':
            memory[pointer] = (val - 1) % 256
        elif cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == 'c':
            copied_value = val
        elif cmd == 'p':
            memory[pointer] = copied_value % 256
        elif cmd == 'P':
            output.append(chr(val))
        elif cmd == 'N':
            output.append(str(val))
        elif cmd == 'T':
            memory[pointer] = (val * 2) % 256
        elif cmd == 'Q':
            memory[pointer] = (val * val) % 256
        elif cmd == 'U':
            memory[pointer] = int(val ** 0.5) % 256
        elif cmd == 'L':
            memory[pointer] = (val + 2) % 256
        elif cmd == 'I':
            memory[pointer] = (val - 2) % 256
        elif cmd == 'V':
            memory[pointer] = (val // 2) % 256
        elif cmd == 'A':
            memory[pointer] = (val + copied_value) % 256
        elif cmd == 'B':
            memory[pointer] = (val - copied_value) % 256
        elif cmd == 'Y':
            memory[pointer] = (val * copied_value) % 256
        elif cmd == 'D':
            if copied_value != 0:
                memory[pointer] = (val // copied_value) % 256

        pc += 1

    return ''.join(output)

def greatest_common_divisor(a: int, b: int) -> int:
    # Handle edge cases
    if a == 0:
        return abs(b)
    if b == 0:
        return abs(a)

    # Use Euclidean algorithm
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

