    terms = []
    current_term = ""

    # Handle the first character specially to manage leading minus signs
    i = 0
    if polynomial[0] == '-':
        current_term = "-"
        i = 1
    else:
        current_term = ""
        i = 0

    # Parse terms, being careful with signs
    while i < len(polynomial):
        if polynomial[i] in ['+', '-'] and i > 0:
            terms.append(current_term)
            current_term = polynomial[i]
        else:
            current_term += polynomial[i]
        i += 1

    # Add the last term
    if current_term:
        terms.append(current_term)

    # Process each term
    derivative_terms = []

    for term in terms:
        # Skip empty terms
        if not term or term == '+' or term == '-':
            continue

        # Determine sign
        sign = 1
        term_start = 0
        if term[0] == '-':
            sign = -1
            term_start = 1
        elif term[0] == '+':
            term_start = 1

        # Extract coefficient and exponent
        term_part = term[term_start:]

        # Handle constant term (no x)
        if 'x' not in term_part:
            # This is a constant term, its derivative is 0
            continue

        # Find where x is
        x_pos = term_part.find('x')
        if x_pos == -1:
            continue

        # Extract coefficient
        if x_pos == 0:
            # x or -x
            coeff = sign * 1
        else:
            # There's a coefficient before x
            coeff_str = term_part[:x_pos]
            if coeff_str == '-':
                coeff = sign * -1
            elif coeff_str == '+':
                coeff = sign * 1
            else:
                coeff = sign * int(coeff_str)

        # Extract exponent
        exp = 1
        if '^' in term_part:
            exp_pos = term_part.find('^')
            exp = int(term_part[exp_pos+1:])
        else:
            exp = 1

        # Apply power rule: d/dx(ax^n) = a*n*x^(n-1)
        new_coeff = coeff * exp
        new_exp = exp - 1

        # Special case: if new_exp is 0, the term is just a constant
        if new_exp == 0:
            derivative_terms.append(str(new_coeff))
        elif new_exp == 1:
            if new_coeff == 1:
                derivative_terms.append('x')
            elif new_coeff == -1:
                derivative_terms.append('-x')
            else:
                derivative_terms.append(str(new_coeff) + 'x')
        else:
            if new_coeff == 1:
                derivative_terms.append('x^' + str(new_exp))
            elif new_coeff == -1:
                derivative_terms.append('-x^' + str(new_exp))
            else:
                derivative_terms.append(str(new_coeff) + 'x^' + str(new_exp))

    # Evaluate the derivative at x
    result = 0
    for term in derivative_terms:
        if 'x' in term:
            # Handle terms with x
            if term == 'x':
                result += x
            elif term == '-x':
                result -= x
            else:
                # Extract coefficient
                coeff_str = ""
                i = 0
                if term[0] == '-':
                    coeff_str = "-"
                    i = 1
                while i < len(term) and term[i] != 'x':
                    coeff_str += term[i]
                    i += 1
                coeff = int(coeff_str)
                # Extract exponent
                exp = 1
                if '^' in term:
                    exp_pos = term.find('^')
                    exp = int(term[exp_pos+1:])
                result += coeff * (x ** exp)
        else:
            # Constant term
            result += int(term)

    return result

