def sum_of_squares(n):
    # Check if n is a perfect square
    sqrt_n = int(n**0.5)
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n can be expressed as sum of two squares
    for i in range(1, int(n**0.5) + 1):
        remainder = n - i * i
        sqrt_remainder = int(remainder**0.5)
        if sqrt_remainder * sqrt_remainder == remainder:
            return 2

    # Check if n can be expressed as sum of three squares
    # Using Legendre's three-square theorem: n = 4^a(8b + 7)
    # If n is of this form, it cannot be expressed as sum of three squares
    while n % 4 == 0:
        n //= 4

    if n % 8 == 7:
        return 4

    # If none of the above, it can be expressed as sum of three squares
    return 3

def vowels_count(s):
