def converter(number, decimals=0, base=None):
    import math

    # Set default base to π if not provided
    if base is None:
        base = math.pi

    # Character set for digits
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

    # Handle sign
    negative = False
    if isinstance(number, (int, float)) and number < 0:
        negative = True
        number = abs(number)

    # Handle zero case
    if number == 0:
        if decimals > 0:
            return '-0.' + '0' * decimals if negative else '0.' + '0' * decimals
        else:
            return '-0' if negative else '0'

    # Split into integer and fractional parts
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_result = '0'
    else:
        result = []
        temp = integer_part

        # For integer base, use standard algorithm
        if base == int(base):
            while temp > 0:
                temp, remainder = divmod(temp, int(base))
                result.append(digits[remainder])
            integer_result = ''.join(reversed(result))
        else:
            # For non-integer base (like π)
            while temp > 0:
                quotient = temp / base
                remainder = temp - quotient
                result.append(digits[int(round(remainder))])
                temp = int(quotient)
            integer_result = ''.join(reversed(result))

    # Convert fractional part
    fractional_result = ''
    if decimals > 0 and fractional_part > 0:
        frac_digits = []
        temp = fractional_part
        for _ in range(decimals):
            temp = temp * base
            digit = int(temp)
            frac_digits.append(digits[digit])
            temp = temp - digit
        fractional_result = ''.join(frac_digits)

    # Ensure we have the right number of decimals
    while len(fractional_result) < decimals:
        fractional_result += '0'

    # Combine results with proper formatting
    if negative:
        if fractional_result:
            return f'-{integer_result}.{fractional_result}'
        else:
            return f'-{integer_result}'
    else:
        if fractional_result:
            return f'{integer_result}.{fractional_result}'
        else:
            return integer_result

def fib4(n: int):
    # Handle negative input
    if n < 0:
        return 0

    # Base cases
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # For n >= 4, use iteration
    # Initialize the last 4 values: fib4(0), fib4(1), fib4(2), fib4(3)
    a, b, c, d = 0, 0, 2, 0

    for i in range(4, n + 1):
        # Calculate fib4(i) = fib4(i-1) + fib4(i-2) + fib4(i-3) + fib4(i-4)
        new_val = a + b + c + d
        # Shift values for next iteration
        a, b, c, d = b, c, d, new_val

    return d

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        return 1

    # Find the smallest divisor starting from 2 up to sqrt(n)
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i

    # If no divisor found, n is prime, so the largest proper divisor is 1
    return 1

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    if n <= 1:
        return y
    if n == 2:
        return x
    if n % 2 == 0:
        return y

    i = 3
    while i * i <= n:
        if n % i == 0:
            return y
        i += 2

    return x

def poohbear(code):
    # Initialize memory (dictionary for infinite cells, default 0)
    cells = {}
    ptr = 0  # cell pointer position
    copy_buffer = 0  # buffer for copy/paste commands

    # Filter only valid command characters
    valid_commands = set('+-><cpWEPNTQLIVABYD')
    commands = [ch for ch in code if ch in valid_commands]

    # Pre-process to find W-E loop pairs
    w_e_pairs = {}
    w_stack = []

    for i, cmd in enumerate(commands):
        if cmd == 'W':
            w_stack.append(i)
        elif cmd == 'E':
            if w_stack:
                start = w_stack.pop()
                w_e_pairs[start] = i
                w_e_pairs[i] = start

    # Execute commands
    pc = 0  # program counter
    output = []

    while pc < len(commands):
        cmd = commands[pc]
        current = cells.get(ptr, 0)

        if cmd == '+':
            cells[ptr] = (current + 1) % 256
            pc += 1
        elif cmd == '-':
            cells[ptr] = (current - 1) % 256
            pc += 1
        elif cmd == '>':
            ptr += 1
            pc += 1
        elif cmd == '<':
            ptr -= 1
            pc += 1
        elif cmd == 'c':
            copy_buffer = current
            pc += 1
        elif cmd == 'p':
            cells[ptr] = copy_buffer % 256
            pc += 1
        elif cmd == 'W':
            if current != 0:
                pc += 1
            else:
                pc = w_e_pairs[pc] + 1 if pc in w_e_pairs else pc + 1
        elif cmd == 'E':
            if current == 0:
                pc += 1
            else:
                pc = w_e_pairs[pc] + 1 if pc in w_e_pairs else pc + 1
        elif cmd == 'P':
            output.append(chr(current))
            pc += 1
        elif cmd == 'N':
            output.append(str(current))
            pc += 1
        elif cmd == 'T':
            cells[ptr] = (current * 2) % 256
            pc += 1
        elif cmd == 'Q':
            cells[ptr] = (current * current) % 256
            pc += 1
        elif cmd == 'U':
            cells[ptr] = int(current ** 0.5) % 256
            pc += 1
        elif cmd == 'L':
            cells[ptr] = (current + 2) % 256
            pc += 1
        elif cmd == 'I':
            cells[ptr] = (current - 2) % 256
            pc += 1
        elif cmd == 'V':
            cells[ptr] = (current // 2) % 256
            pc += 1
        elif cmd == 'A':
            cells[ptr] = (current + copy_buffer) % 256
            pc += 1
        elif cmd == 'B':
            cells[ptr] = (current - copy_buffer) % 256
            pc += 1
        elif cmd == 'Y':
            cells[ptr] = (current * copy_buffer) % 256
            pc += 1
        elif cmd == 'D':
            if copy_buffer != 0:
                cells[ptr] = (current // copy_buffer) % 256
            pc += 1

    return ''.join(output)

def parse_int(s):
    s = s.lower()

    units = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9,
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17,
        'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    # Replace hyphens and extra spaces, then split into words
    s = s.replace('-', ' ')
    words = s.split()
    words = [w for w in words if w != 'and']

    result = 0
    current = 0

    for word in words:
        if word == 'hundred':
            current *= 100
        elif word == 'thousand':
            result += current * 1000
            current = 0
        elif word == 'million':
            result += current * 1000000
            current = 0
        elif word in units:
            current += units[word]
        elif word in tens:
            current += tens[word]

    return result + current

