def getAllPrimeFactors(n):
    # Input validation: check if n is a number
    if not isinstance(n, (int, float)):
        return []

    # Input validation: check if n is an integer (not a float)
    if isinstance(n, float):
        if n != int(n):
            return []

    # Convert to int if it's a valid whole number
    n = int(n)

    # Input validation: n must be positive (greater than 0)
    if n <= 0:
        return []

    # Edge case: n = 1
    if n == 1:
        return [1]

    # Find all prime factors
    factors = []
    divisor = 2

    while n > 1:
        while n % divisor == 0:
            factors.append(divisor)
            n = n // divisor
        divisor += 1

    return factors

def median(l: list):
    """Return median of elements in the list l.
    >>> median([3, 1, 2, 4, 5])
    3
    >>> median([-10, 4, 6, 1000, 10, 20])
    8.0
    """
    if not l:
        raise ValueError("Cannot calculate median of empty list")

    sorted_list = sorted(l)
    n = len(sorted_list)
    mid = n // 2

    if n % 2 == 1:
        return float(sorted_list[mid])
    else:
        return (sorted_list[mid - 1] + sorted_list[mid]) / 2.0

