def amazon_check_mate(king, amazon):
    # Parse algebraic notation to coordinates (row, col) 0-7
    def parse_position(pos):
        col = ord(pos[0]) - ord('a')
        row = int(pos[1]) - 1
        return (row, col)

    white_king = parse_position(king)
    white_amazon = parse_position(amazon)

    # Check if position is on board
    def is_valid(pos):
        return 0 <= pos[0] <= 7 and 0 <= pos[1] <= 7

    # Check if two positions are adjacent (including diagonal)
    def is_adjacent(pos1, pos2):
        if pos1 == pos2:
            return False
        return abs(pos1[0] - pos2[0]) <= 1 and abs(pos1[1] - pos2[1]) <= 1

    # Check if amazon attacks a position
    def amazon_attacks(amazon_pos, target):
        if amazon_pos == target:
            return False

        dr = target[0] - amazon_pos[0]
        dc = target[1] - amazon_pos[1]

        # Queen-like move: same row (rook movement)
        if dr == 0:
            min_c = min(amazon_pos[1], target[1])
            max_c = max(amazon_pos[1], target[1])
            for c in range(min_c + 1, max_c):
                if (amazon_pos[0], c) == white_king:
                    return False
            return True

        # Queen-like move: same column (rook movement)
        if dc == 0:
            min_r = min(amazon_pos[0], target[0])
            max_r = max(amazon_pos[0], target[0])
            for r in range(min_r + 1, max_r):
                if (r, amazon_pos[1]) == white_king:
                    return False
            return True

        # Queen-like move: diagonal (bishop movement)
        if abs(dr) == abs(dc):
            r_step = 1 if dr > 0 else -1
            c_step = 1 if dc > 0 else -1
            r, c = amazon_pos[0] + r_step, amazon_pos[1] + c_step
            while (r, c) != (target[0], target[1]):
                if (r, c) == white_king:
                    return False
                r += r_step
                c += c_step
            return True

        # Knight-like moves (can jump over pieces)
        if abs(dr) == 2 and abs(dc) == 1:
            return True
        if abs(dr) == 1 and abs(dc) == 2:
            return True

        return False

    # Count valid escape squares from a position
    def count_escapes(king_pos):
        escapes = 0
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue

                escape_pos = (king_pos[0] + dr, king_pos[1] + dc)

                if not is_valid(escape_pos):
                    continue

                # Cannot be on white pieces
                if escape_pos == white_king or escape_pos == white_amazon:
                    continue

                # Cannot be adjacent to white king
                if is_adjacent(escape_pos, white_king):
                    continue

                # Cannot be under amazon attack
                if amazon_attacks(white_amazon, escape_pos):
                    continue

                escapes += 1

        return escapes

    # Initialize counters
    checkmate = 0
    check = 0
    stalemate = 0
    safe_with_moves = 0

    # Iterate through all 64 squares
    for row in range(8):
        for col in range(8):
            pos = (row, col)

            # Black king cannot be on white pieces
            if pos == white_king or pos == white_amazon:
                continue

            # Black king cannot be adjacent to white king
            if is_adjacent(pos, white_king):
                continue

            # Check if under amazon attack
            under_attack = amazon_attacks(white_amazon, pos)

            # Count valid escapes
            escapes = count_escapes(pos)

            # Categorize
            if under_attack:
                if escapes == 0:
                    checkmate += 1
                else:
                    check += 1
            else:
                if escapes == 0:
                    stalemate += 1
                else:
                    safe_with_moves += 1

    return [checkmate, check, stalemate, safe_with_moves]

def largest_divisor(n: int) -> int:
    if n <= 1:
        return 1

    # Find the smallest prime factor
    smallest_factor = n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            smallest_factor = i
            break

    # If no factor found, n is prime, so largest divisor smaller than n is 1
    if smallest_factor == n:
        return 1

    # Otherwise, largest divisor smaller than n is n/smallest_factor
    return n // smallest_factor

