def parse_nested_parens(paren_string):
    if not paren_string:
        return []

    structures = paren_string.split()
    result = []

    for structure in structures:
        max_depth = 0
        current_depth = 0

        for char in structure:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

def valid_mersenne(n):
    if n < 2:
        return False

    # Check if n is prime
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False

    # Check if 2^n - 1 is prime
    mersenne_number = (2 ** n) - 1

    # Check if mersenne_number is prime
    if mersenne_number < 2:
        return False
    for i in range(2, int(mersenne_number**0.5) + 1):
        if mersenne_number % i == 0:
            return False

    return True

