def getAllPrimeFactors(n):
    if not isinstance(n, int) or isinstance(n, bool) or n <= 0:
        return []

    if n == 1:
        return [1]

    factors = []
    temp = n
    factor = 2

    while factor * factor <= temp:
        while temp % factor == 0:
            factors.append(factor)
            temp = temp // factor
        factor += 1

    if temp > 1:
        factors.append(temp)

    return factors


def getUniquePrimeFactorsWithCount(n):
    if not isinstance(n, int) or isinstance(n, bool) or n <= 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = []
    counts = []
    temp = n
    factor = 2

    while factor * factor <= temp:
        if temp % factor == 0:
            count = 0
            while temp % factor == 0:
                count += 1
                temp = temp // factor
            factors.append(factor)
            counts.append(count)
        factor += 1

    if temp > 1:
        factors.append(temp)
        counts.append(1)

    return [factors, counts]


def getUniquePrimeFactorsWithProducts(n):
    if not isinstance(n, int) or isinstance(n, bool) or n <= 0:
        return []

    if n == 1:
        return [1]

    result = []
    temp = n
    factor = 2

    while factor * factor <= temp:
        if temp % factor == 0:
            count = 0
            while temp % factor == 0:
                count += 1
                temp = temp // factor
            result.append(factor ** count)
        factor += 1

    if temp > 1:
        result.append(temp)

    return result

