    opening_to_closing = {}
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        opening_to_closing[opening] = closing

    # Stack to keep track of expected closing characters
    stack = []

    for char in s:
        # If character is an opening character
        if char in opening_to_closing:
            # Push the corresponding closing character onto the stack
            stack.append(opening_to_closing[char])
        # If character is a closing character
        elif char in opening_to_closing.values():
            # If stack is empty or the top doesn't match, it's unbalanced
            if not stack or stack.pop() != char:
