import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_digits = []
    else:
        digits = []
        temp = integer_part
        power = 0
        # Find the highest power needed
        while base ** power <= temp:
            power += 1
        power -= 1

        # Extract digits from highest power down
        while power >= 0:
            if base ** power <= temp:
                digit = int(temp // (base ** power))
                digits.append(digit)
                temp -= digit * (base ** power)
            else:
                digits.append(0)
            power -= 1

        integer_digits = digits

    # Convert fractional part
    fractional_digits = []
    if decimals > 0:
        temp_fraction = fractional_part
        for _ in range(decimals):
            temp_fraction *= base
            digit = int(temp_fraction)
            fractional_digits.append(digit)
            temp_fraction -= digit

    # Convert digits to characters
    def digit_to_char(digit):
        if digit < 10:
            return str(digit)
        else:
            return chr(ord('A') + digit - 10)

    integer_str = ''.join(digit_to_char(d) for d in integer_digits)

    if decimals == 0:
        result = integer_str
    else:
        fractional_str = ''.join(digit_to_char(d) for d in fractional_digits)
        result = integer_str + '.' + fractional_str

    if negative:
        result = '-' + result

    # Handle special case where result is less than 1
    if not negative and number < 1 and decimals == 0:
        # This case shouldn't happen with our algorithm, but just in case
        pass

    return result

