        tagname_count = 0

        # Split by spaces to handle compound selectors
        parts = selector.split()

        for part in parts:
            # Count ID selectors (#id)
            if part.startswith('#'):
                id_count += 1
            # Count class selectors (.class)
            elif part.startswith('.'):
                class_count += 1
            # Count tag names (everything else)
            else:
                tagname_count += 1

        return (id_count, class_count, tagname_count)

    specificity1 = get_specificity(selector1)
    specificity2 = get_specificity(selector2)

    if specificity1 > specificity2:
        return selector1
    else:
        return selector2

def cycpattern_check(a, b):
    if not b:
        return True
    if not a:
        return False

    # Create a string that contains all rotations of b
    # If b is a rotation of a substring of a, then b will appear in a+a
    doubled_b = b + b

    # Check if b is a substring of a
    if b in a:
        return True

    # Check all possible rotations of b
    for i in range(len(b)):
        rotation = doubled_b[i:i+len(b)]
        if rotation in a:
            return True

    return False

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """

    def parse_value(val):
        """Convert a value to float for comparison, handling comma decimal separators"""
        if isinstance(val, (int, float)):
            return float(val)
        elif isinstance(val, str):
            # Replace comma with dot for decimal separator
            normalized_str = val.replace(',', '.')
            return float(normalized_str)
        else:
            raise TypeError("Unsupported type")

    # Parse both values for comparison
    parsed_a = parse_value(a)
    parsed_b = parse_value(b)

    # Compare the parsed values
    if parsed_a > parsed_b:
        return a
    elif parsed_b > parsed_a:
        return b
    else:
        return None

