def is_balanced(s, pairs):
    # Create a mapping from opener to closer
    pair_map = {}
    for i in range(0, len(pairs), 2):
        opener = pairs[i]
        closer = pairs[i + 1]
        pair_map[opener] = closer

    # Stack to keep track of openers
    stack = []

    for char in s:
        # If character is not part of any pair, skip it
        if char not in pairs:
            continue

        # Check if it's an opener (either from pair map or if it's a self-closing pair)
        if char in pair_map:
            # Check if it's a self-closing pair (same character for opener and closer)
            if pair_map[char] == char:
                # For self-closing pairs, if stack is empty or top doesn't match, push
                if not stack or stack[-1] != char:
                    stack.append(char)
                else:
                    # Pop if matches the top of stack
                    stack.pop()
            else:
                # Regular pair - always push opener
                stack.append(char)
        else:
            # It's a closer
            # If stack is empty, it's unbalanced
            if not stack:
                return False

            # Get the last opener
            last_opener = stack[-1]

            # Check if this closer matches the last opener
            if pair_map[last_opener] == char:
                stack.pop()
            else:
                return False

    # If stack is empty, all brackets were properly closed
    return len(stack) == 0

import sys
from collections import defaultdict

def normalize_path(path):
    """Normalize path by resolving . and .. references"""
    if not path:
        return ""

    # Split path by slashes
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            # Empty part or current directory reference - skip
            continue
        elif part == '..':
            # Parent directory reference - go back if possible
            if stack:
                stack.pop()
        else:
            # Regular directory/file name
            stack.append(part)

    # Join parts back with slashes
    if not stack:
        return ""

    return '/' + '/'.join(stack)

def parse_url(url):
    """Parse URL and return (hostname, normalized_path)"""
    # Remove http:// prefix
    if url.startswith('http://'):
        url = url[7:]

    # Split by first slash to separate hostname and path
    if '/' in url:
        hostname, path = url.split('/', 1)
        # Normalize the path
        normalized_path = normalize_path(path)
    else:
        hostname = url
        normalized_path = ""

    return hostname, normalized_path

