        if k == 1:
            return 1.0 if n >= 1 else 0.0

        prob = 0.0
        sign = 1
        for i in range(k + 1):
            if i > n:
                break
            # Compute C(k,i)
            if i == 0:
                comb = 1
            else:
                comb = 1
                for j in range(i):
                    if (k - j) > 0:
                        comb = comb * (k - j) // (j + 1)

            # Compute ((k-i)/k)^n
            if k == i:
                power = 0.0
            else:
                power = ((k - i) / k) ** n

            prob += sign * comb * power
            sign = -sign

        return prob

    results = []
    for i in range(1, q + 1):
        p = int(lines[i])
        target_prob = (p - 1e-10) / 2000

        # Binary search for minimum n
        left, right = k, k * k + 1000  # Reasonable upper bound

        while left < right:
            mid = (left + right) // 2
            prob = inclusion_exclusion_prob(mid, k)
            if prob >= target_prob:
                right = mid
            else:
                left = mid + 1

        results.append(str(left))

    print('\n'.join(results))

