def getAllPrimeFactors(n):
    # Input validation
    if not isinstance(n, int) or n <= 0:
        return []

    # Edge cases
    if n == 0:
        return []
    elif n == 1:
        return [1]
    elif n == 2:
        return [2]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

