def simplify(expression):
    if not expression:
        return ""

    # Parse terms
    terms = []
    i = 0
    while i < len(expression):
        # Skip spaces
        if expression[i] == ' ':
            i += 1
            continue

        # Determine sign
        sign = 1
        if expression[i] == '+':
            i += 1
        elif expression[i] == '-':
            sign = -1
            i += 1

        # Parse coefficient
        coeff = 0
        while i < len(expression) and expression[i].isdigit():
            coeff = coeff * 10 + int(expression[i])
            i += 1

        # If no digits were found, coefficient is 1 or -1
        if coeff == 0:
            coeff = 1

        # Apply sign to coefficient
        coeff *= sign

        # Parse variables
        variables = []
        while i < len(expression) and expression[i].islower():
            variables.append(expression[i])
            i += 1

        # Sort variables to normalize
        variables.sort()
        var_str = ''.join(variables)

        # Add to terms
        if var_str:  # Only add if there are variables
            terms.append((coeff, var_str))
        else:  # Handle constant terms (no variables)
            terms.append((coeff, ""))

    # Combine like terms
    monomial_dict = {}
    for coeff, var_str in terms:
        if var_str in monomial_dict:
            monomial_dict[var_str] += coeff
        else:
            monomial_dict[var_str] = coeff

    # Remove terms with zero coefficient
    monomial_dict = {var_str: coeff for var_str, coeff in monomial_dict.items() if coeff != 0}

    # Sort terms
    sorted_terms = sorted(monomial_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Format result
    result = []
    for i, (var_str, coeff) in enumerate(sorted_terms):
        if coeff == 1 and var_str:  # Coefficient is 1 and there are variables
            term = var_str
        elif coeff == -1 and var_str:  # Coefficient is -1 and there are variables
            term = '-' + var_str
        else:  # Other coefficients
            term = str(coeff) + var_str if var_str else str(coeff)

        if i == 0:
            result.append(term)
        else:
            if term.startswith('-'):
                result.append('-' + term[1:])
            else:
                result.append('+' + term)

    # Handle empty result
    if not result:
        return ""

    # Join the terms
    final_result = result[0]
    for term in result[1:]:
        if term.startswith('-'):
            final_result += term
        else:
            final_result += '+' + term

    return final_result

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part to given base
    if integer_part == 0:
        integer_result = ''
    else:
        digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
        integer_result = ''
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            # Handle negative remainders
            if remainder < 0:
                remainder += base
                temp = (temp - remainder) // base - 1
            else:
                temp = (temp - remainder) // base
            integer_result = digits[int(remainder)] + integer_result

    # Convert fractional part
    if decimals == 0:
        fractional_result = ''
    else:
        digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
        fractional_result = '.'
        temp_fraction = fractional_part
        for _ in range(decimals):
            temp_fraction *= base
            digit = int(temp_fraction)
            # Handle negative digits
            if digit < 0:
                digit += base
                temp_fraction = temp_fraction - digit + 1
            else:
                temp_fraction = temp_fraction - digit
            fractional_result += digits[digit]

    # Combine results
    if integer_result == '':
        result = '0' + fractional_result
    else:
        result = integer_result + fractional_result

    # Handle negative sign
    if negative:
        result = '-' + result

    return result

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    # Split the string by spaces to get individual letters
    letters = test.split()

    # Count occurrences of each letter
    count_dict = {}
    for letter in letters:
        count_dict[letter] = count_dict.get(letter, 0) + 1

    # Find the maximum count
    max_count = max(count_dict.values())

    # Create result dictionary with letters that have maximum count
    result = {letter: count for letter, count in count_dict.items() if count == max_count}

    return result

import re

def differentiate(poly, x):
    if not poly or poly.strip() == '':
        return 0

    poly = poly.strip()
    terms = re.findall(r'[+-]?\d*x?(\^\d+)?', poly)

    result = 0

    for term, exponent_part in terms:
        if 'x' not in term:
            continue

        if exponent_part:
            exponent = int(exponent_part[1:])
        else:
            exponent = 1

        if not term or term == 'x' or term == '+x':
            coefficient = 1
        elif term == '-x' or term == '-':
            coefficient = -1
        else:
            coefficient = int(term)

        if exponent == 0:
            continue

        derivative_value = coefficient * exponent * (x ** (exponent - 1))
        result += derivative_value

    return result

def count_up_to(n):
    if n <= 2:
        return []

    # Use Sieve of Eratosthenes to find all primes less than n
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n, i):
                is_prime[j] = False

    # Collect primes in ascending order
    primes = []
    for i in range(2, n):
        if is_prime[i]:
            primes.append(i)

    return primes

