def parse_nested_parens(groups):
    def max_depth(s):
        max_depth = 0
        current_depth = 0
        for char in s:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1
        return max_depth

    # Split the input string into groups
    input_string = groups[0]
    group_list = input_string.split()

    # Calculate max depth for each group
    result = []
    for group in group_list:
        result.append(max_depth(group))

    return result

