def smallest_change(arr):
    if not arr or len(arr) <= 1:
        return 0

    changes = 0
    left = 0
    right = len(arr) - 1

    while left < right:
        if arr[left] != arr[right]:
            changes += 1
        left += 1
        right -= 1

    return changes

def compare(selector1, selector2):
    def calculate_specificity(selector):
        ids = 0
        classes = 0
        tags = 0

        # Split by spaces to get individual components
        parts = selector.split()

        for part in parts:
            if not part or part == '*':
                continue

            # Count IDs (#)
            ids += part.count('#')

            # Count classes (.)
            classes += part.count('.')

            # Check if there's a tag name
            # A tag name is the first part before any # or .
            tag_part = part
            for char in ['#', '.']:
                idx = tag_part.find(char)
                if idx != -1:
                    tag_part = tag_part[:idx]

            # If tag_part is not empty, it's a tag
            if tag_part:
                tags += 1

        return (ids, classes, tags)

    spec1 = calculate_specificity(selector1)
    spec2 = calculate_specificity(selector2)

    # Compare: (ids, classes, tags) - tuples compare lexicographically
    if spec1 > spec2:
        return selector1
    elif spec2 > spec1:
        return selector2
    else:
        # If equal, return the later selector (selector2)
        return selector2

def proper_fractions(d):
    """
    Counts the number of proper fractions with denominator d.
    This is equivalent to computing Euler's totient function φ(d).
    """
    if d == 1:
        return 0

    result = d
    n = d

    # Check for factor 2
    if n % 2 == 0:
        result = result // 2 * 1  # result = result * (1 - 1/2)
        while n % 2 == 0:
            n //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result = result // i * (i - 1)  # result = result * (1 - 1/i)
            while n % i == 0:
                n //= i
        i += 2

    # If n > 1, then it's a prime factor
    if n > 1:
        result = result // n * (n - 1)

    return result

