def histogram(s):
    # Handle empty string or string with only whitespace
    if not s or not s.strip():
        return {}

    # Split the string by spaces to get individual letters
    letters = s.split()

    # Count frequency of each letter
    counts = {}
    for letter in letters:
        counts[letter] = counts.get(letter, 0) + 1

    # If no letters found, return empty dictionary
    if not counts:
        return {}

    # Find maximum frequency
    max_freq = max(counts.values())

    # Build result dictionary with all letters that have maximum frequency
    result = {}
    for letter, freq in counts.items():
        if freq == max_freq:
            result[letter] = freq

    return result

