import math

def converter(number, decimals=0, base=math.pi):
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36")

    if decimals < 0:
        raise ValueError("Decimals must be non-negative")

    # Handle zero case
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    result = []

    if integer_part == 0:
        result.append('0')
    else:
        while integer_part > 0:
            remainder = integer_part % int(base)
            if remainder < 10:
                result.append(str(remainder))
            else:
                result.append(chr(ord('A') + remainder - 10))
            integer_part //= int(base)

    # Reverse the integer part digits
    result.reverse()

    # Add decimal point if needed
    if decimals > 0:
        result.append('.')

        # Convert fractional part
        fractional_part = number - int(number)
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            if digit < 10:
                result.append(str(digit))
            else:
                result.append(chr(ord('A') + digit - 10))
            fractional_part -= digit

    # Join the result
    final_result = ''.join(result)

    # Add negative sign if needed
    if negative:
        final_result = '-' + final_result

    # Handle special case where we need to add leading zero
    if not negative and number < 1 and decimals == 0:
        final_result = '0' + final_result

    return final_result

