import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])

    if n == 1:
        print(0)
        return

    edges = []
    max_weight = 0

    # Parse edges
    for i in range(n - 1):
        u = int(data[1 + 3 * i])
        v = int(data[2 + 3 * i])
        w = int(data[3 + 3 * i])
        edges.append((u, v, w))
        max_weight = max(max_weight, w)

    # DSU class for union-find
    class DSU:
        def __init__(self, n):
            self.parent = list(range(n))
            self.rank = [0] * n
            self.size = [1] * n

        def find(self, x):
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])  # Path compression
            return self.parent[x]

        def union(self, x, y):
            px, py = self.find(x), self.find(y)
            if px != py:
                # Union by rank
                if self.rank[px] < self.rank[py]:
                    px, py = py, px
                self.parent[py] = px
                self.size[px] += self.size[py]
                if self.rank[px] == self.rank[py]:
                    self.rank[px] += 1
                return True
            return False

    # Check if a minimum weight W is feasible
    def check(W):
        dsu = DSU(n + 1)  # 1-indexed

        # Add edges with weight strictly less than W
        for u, v, w in edges:
            if w < W:
                dsu.union(u, v)

        # Check if any component has more than n/2 nodes
        # We need to count component sizes for root nodes
        component_sizes = {}
        for i in range(1, n + 1):
            root = dsu.find(i)
            if root not in component_sizes:
                component_sizes[root] = 0
            component_sizes[root] += 1

        # If any component has more than n//2 nodes, it's not feasible
        for size in component_sizes.values():
            if size > n // 2:
                return False

        return True

    # Binary search on the answer
    low, high = 0, max_weight
    ans = 0

    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            low = mid + 1  # Try for a larger value
        else:
            high = mid - 1  # Try for a smaller value

    print(ans)

if __name__ == "__main__":
    main()

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, number) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract the numbers in the new order
    return [num for _, _, num in indexed_nums]

def decimal_to_binary(decimal):
    if decimal == 0:
        return "db0db"

    binary_digits = []
    while decimal > 0:
        binary_digits.append(str(decimal % 2))
        decimal //= 2

    # Reverse the digits to get the correct binary representation
    binary_string = ''.join(reversed(binary_digits))
    return f"db{binary_string}db"

def sort_even(l: list):
    even_values = sorted([l[i] for i in range(0, len(l), 2)])
    result = list(l)
    for i in range(0, len(l), 2):
        result[i] = even_values[i // 2]
    return result

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    gems = list(map(int, lines[1].split()))

    # Precompute palindromes
    is_palindrome = [[False] * n for _ in range(n)]

    # Every single gemstone is a palindrome
    for i in range(n):
        is_palindrome[i][i] = True

    # Check for palindromes of length 2
    for i in range(n - 1):
        if gems[i] == gems[i + 1]:
            is_palindrome[i][i + 1] = True

    # Check for palindromes of length 3 and more
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if gems[i] == gems[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP: dp[i][j] represents minimum seconds to destroy substring from i to j
    dp = [[float('inf')] * n for _ in range(n)]

    # Base case: single gemstone
    for i in range(n):
        dp[i][i] = 1

    # Fill DP table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            # If the entire substring is palindrome, we can destroy it in 1 second
            if is_palindrome[i][j]:
                dp[i][j] = 1
            else:
                # Try all possible splits
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

