def encrypt(s):
    result = ""
    for char in s:
        if char.isalpha():
            if char.islower():
                # For lowercase letters, shift by 4 positions with wraparound
                shifted = (ord(char) - ord('a') + 4) % 26
                result += chr(shifted + ord('a'))
            else:
                # For uppercase letters, shift by 4 positions with wraparound
                shifted = (ord(char) - ord('A') + 4) % 26
                result += chr(shifted + ord('A'))
        else:
            # Non-alphabetic characters remain unchanged
            result += char
    return result

from typing import List, Tuple
import ast

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    # Handle string representation of lists by safely parsing them
    if isinstance(numbers, str):
        try:
            numbers = ast.literal_eval(numbers)
        except (ValueError, SyntaxError):
            raise TypeError("Input must be a list of integers")

    # Validate that input is a list
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list of integers")

    # Validate all elements are integers (excluding booleans)
    for num in numbers:
        if not isinstance(num, int) or isinstance(num, bool):
            raise TypeError("All elements must be integers")

    # Handle empty list case
    if len(numbers) == 0:
        return (0, 1)

