def calculate_specificity(selector):
    if not selector:
        return (0, 0, 0)

    id_count = 0
    class_count = 0
    tag_count = 0

    elements = selector.split()

    for element in elements:
        if not element:
            continue

        temp = element

        # Extract all #id components
        while '#' in temp:
            idx = temp.find('#')
            end_idx = idx + 1
            while end_idx < len(temp) and (temp[end_idx].isalnum() or temp[end_idx] in '-_'):
                end_idx += 1
            temp = temp[:idx] + temp[end_idx:]
            id_count += 1

        # Extract all .class components
        while '.' in temp:
            idx = temp.find('.')
            end_idx = idx + 1
            while end_idx < len(temp) and (temp[end_idx].isalnum() or temp[end_idx] in '-_'):
                end_idx += 1
            temp = temp[:idx] + temp[end_idx:]
            class_count += 1

        # If anything remains and it's not *, it's a tag
        if temp and temp != '*':
            tag_count += 1

    return (id_count, class_count, tag_count)


def compare(selector1, selector2):
