    lines = data.splitlines()
    n = int(lines[0])
    c = list(map(int, lines[1].split()))

    # dp[i][j] represents the minimum seconds to destroy substring from i to j (inclusive)
    dp = [[float('inf')] * n for _ in range(n)]

    # Base case: single gemstone requires 1 second
    for i in range(n):
        dp[i][i] = 1

    # Fill DP table for substrings of length 2
    for i in range(n - 1):
        if c[i] == c[i + 1]:
            dp[i][i + 1] = 1
        else:
            dp[i][i + 1] = 2

    # Fill DP table for substrings of length 3 to n
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            # Try all possible splits
            for k in range(i, j):
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

            # If the first and last gemstones have the same color,
            # we can remove them together with the inner substring
            if c[i] == c[j]:
                if i + 1 <= j - 1:
                    dp[i][j] = min(dp[i][j], dp[i + 1][j - 1])
                else:
                    dp[i][j] = min(dp[i][j], 1)

    print(dp[0][n - 1])

