    current_term = ""
    for i, char in enumerate(polynomial):
        if char == '+' or char == '-':
            if current_term:
                terms.append(current_term)
            current_term = char
        else:
            current_term += char

    if current_term:
        terms.append(current_term)

    # Process each term
    derivative_terms = []

    for term in terms:
        if term == '+':
            continue
        elif term == '-':
            term = '-1'
        elif term.startswith('+'):
            term = term[1:]

        # Extract coefficient and exponent
        if 'x^' in term:
            # Format: ax^n
            parts = term.split('x^')
            coeff_str = parts[0]
            exp_str = parts[1]

            if coeff_str == '':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)

            exp = int(exp_str)

            # Apply power rule: d/dx[ax^n] = n*ax^(n-1)
            if exp > 0:
                new_coeff = coeff * exp
                new_exp = exp - 1
                if new_exp == 0:
                    derivative_terms.append(str(new_coeff))
                elif new_exp == 1:
                    if new_coeff == 1:
                        derivative_terms.append('x')
                    elif new_coeff == -1:
                        derivative_terms.append('-x')
                    else:
                        derivative_terms.append(f'{new_coeff}x')
                else:
                    if new_coeff == 1:
                        derivative_terms.append(f'x^{new_exp}')
                    elif new_coeff == -1:
                        derivative_terms.append(f'-x^{new_exp}')
                    else:
                        derivative_terms.append(f'{new_coeff}x^{new_exp}')

        elif 'x' in term:
            # Format: ax or -ax
            if term == 'x':
                coeff = 1
                exp = 1
            elif term == '-x':
                coeff = -1
                exp = 1
            else:
                # Remove the 'x' and get coefficient
                coeff_str = term[:-1]
                if coeff_str == '':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str)
                exp = 1

            # Apply power rule
            new_coeff = coeff * exp
            new_exp = exp - 1
            if new_exp == 0:
