                    derivative_terms.append(f'-x^{new_exp}')
                else:
                    derivative_terms.append(f'{new_coeff}x^{new_exp}')
        else:
            # Constant term
            # Derivative of a constant is 0
            continue

    # If no terms, return 0
    if not derivative_terms:
        return 0

    # Evaluate the derivative at x
    result = 0
    for term in derivative_terms:
        if term == 'x':
            result += x
