            result += coeff

    return result

def is_balanced(s, pairs):
    opening_set = set()
    closing_to_opening = {}

    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        opening_set.add(opening)
        closing_to_opening[closing] = opening

    stack = []

    for char in s:
        if char in opening_set:
            stack.append(char)
        elif char in closing_to_opening:
            if not stack:
                return False
            top = stack.pop()
            if top != closing_to_opening[char]:
                return False

    return len(stack) == 0

