def median(l: list):
    """Return median of elements in the list l.
    >>> median([3, 1, 2, 4, 5])
    3
    >>> median([-10, 4, 6, 1000, 10, 20])
    8.0
    """
    if not l:
        raise ValueError("Cannot calculate median of empty list")

    sorted_list = sorted(l)
    n = len(sorted_list)
    mid = n // 2

    if n % 2 == 1:
        return float(sorted_list[mid])
    else:
        return (sorted_list[mid - 1] + sorted_list[mid]) / 2.0

def valid_mersenne(n):
    # Edge cases
    if n <= 1:
        return False

    # Check if n is prime (necessary condition for Mersenne prime)
    if n == 2:
        return True  # M_2 = 3 is prime

    if n % 2 == 0:
        return False

    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2

    # n is prime, now check if 2^n - 1 is prime using Lucas-Lehmer test
    m = 2 ** n - 1

    s = 4
    for _ in range(n - 2):
        s = (s * s - 2) % m

    return s == 0

def differentiate(polynomial, point):
    # Parse the polynomial into terms
    terms = []
    i = 0
    n = len(polynomial)

    while i < n:
        term_start = i

        # Find the end of this term (next + or - that's not at the start)
        while i < n and polynomial[i] not in '+-' and term_start > 0:
            i += 1
        while i < n and term_start == 0 and polynomial[i] != '+':
            # Skip leading +
            if polynomial[i] == '+':
                i += 1
            else:
                break

        term = polynomial[term_start:i]
        terms.append(term)

        # Skip past the operator if present
        if i < n and polynomial[i] == '+':
            i += 1

    if not terms:
        terms = [polynomial]

    def parse_term(term):
        """Parse a term into (coefficient, exponent)"""
        # Remove leading '+'
        term = term.lstrip('+')

        if term == '':
            return 0, 0

        # Check if term contains x
        if 'x' in term:
            x_index = term.index('x')

            # Extract coefficient part (before x)
            coeff_str = term[:x_index]

            # Extract exponent part (after x, if any)
            exp_str = term[x_index + 1:]

            # Parse coefficient
            if coeff_str == '' or coeff_str == '-':
                coefficient = -1 if coeff_str == '-' else 1
            else:
                coefficient = int(coeff_str)

            # Parse exponent
            if exp_str == '':
                exponent = 1
            elif exp_str.startswith('^'):
                exponent = int(exp_str[1:])
            else:
                exponent = 1
        else:
            # Constant term
            coefficient = int(term)
            exponent = 0

        return coefficient, exponent

    # Differentiate and evaluate
    result = 0
    for term in terms:
        coefficient, exponent = parse_term(term)

        # Apply power rule: d/dx (ax^n) = n*ax^(n-1)
        if exponent == 0:
            # Constant term, derivative is 0
            continue
        elif exponent == 1:
            # Linear term, derivative is coefficient
            result += coefficient
        else:
            # Higher order term: n * a * x^(n-1)
            result += coefficient * exponent * (point ** (exponent - 1))

    return result

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % int(base)
            integer_digits.append(remainder)
            temp = (temp - remainder) // int(base)
        integer_digits.reverse()

    # Convert fractional part
    fractional_digits = []
    if decimals > 0:
        temp_fractional = fractional_part
        for _ in range(decimals):
            temp_fractional *= base
            digit = int(temp_fractional)
            fractional_digits.append(digit)
            temp_fractional -= digit

    # Format result
    if not integer_digits:
        result = '0'
    else:
        result = ''.join(str(digit) for digit in integer_digits)

    if decimals > 0:
        result += '.'
        result += ''.join(str(digit) for digit in fractional_digits)

    # Handle negative sign
    if negative:
        result = '-' + result

    # Handle leading zero for numbers less than 1
    if number < 1 and not negative:
        if '.' not in result:
            result = '0.' + result
        else:
            # Find the position of decimal point
            dot_pos = result.index('.')
            if dot_pos == 0:
                result = '0' + result

    return result

