def valid_mersenne(n):
    def is_prime(x):
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True

    if not is_prime(n):
        return False
    return (1 << n) - 1 == int(''.join(['1' if (int((1 << n) - 1) >> i) & 1 else '0' for i in range(n-1, -1, -1)]), 2)

def get_closest_vowel(word):
    vowels = set('aeiouAEIOU')

    # Need at least 3 characters to have a vowel between two consonants
    if len(word) < 3:
        return ""

    # Scan from right to left (excluding first and last positions)
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            # Check if both neighbors are consonants (not vowels)
            if word[i-1] not in vowels and word[i+1] not in vowels:
                return word[i]

    return ""

