import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            integer_digits.append(temp % base)
            temp //= base
        integer_digits.reverse()

    # Convert fractional part
    fractional_part = number - integer_part
    fractional_digits = []

    if decimals > 0 and fractional_part > 0:
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            fractional_digits.append(digit)
            fractional_part -= digit
            if fractional_part < 1e-15:  # Stop if very small
                break

    # Format digits according to base (0-9, A-Z)
    def format_digit(digit):
        if digit < 10:
            return str(digit)
        else:
            return chr(ord('A') + digit - 10)

    # Build integer part string
    if integer_digits:
        integer_str = ''.join(format_digit(d) for d in integer_digits)
    else:
        integer_str = '0'

    # Build fractional part string
    if fractional_digits:
        fractional_str = ''.join(format_digit(d) for d in fractional_digits)
        result = integer_str + '.' + fractional_str
    else:
        result = integer_str

    # Add negative sign if needed
    if negative:
        result = '-' + result

    return result

def separate_paren_groups(s):
    result = []
    current_group = []
    counter = 0

    for char in s:
        if char == ' ':
            continue
        elif char == '(':
            current_group.append(char)
            counter += 1
        elif char == ')':
            current_group.append(char)
            counter -= 1
            if counter == 0:
                result.append(''.join(current_group))
                current_group = []

    return result

def is_valid(s):
    # Rule: Each identifier must have at least one character
    if not s:
        return False

    # Helper function to check if a character is a valid first character
    # (alpha, underscore, or dollar sign)
    def is_valid_first_char(c):
        return c.isalpha() or c == '_' or c == '$'

    # Helper function to check if a character is a valid identifier character
    # (alpha, digit, underscore, or dollar sign)
    def is_valid_char(c):
        return c.isalpha() or c.isdigit() or c == '_' or c == '$'

    # Check first character (must be alpha, underscore, or dollar sign, not digit)
    if not is_valid_first_char(s[0]):
        return False

    # Check remaining characters (can be alpha, digit, underscore, or dollar sign)
    for c in s[1:]:
        if not is_valid_char(c):
            return False

    return True

def vowels_count(s):
