    # Find the index where the first vowel occurs
    first_vowel_index = 0
    for i, char in enumerate(word):
        if char in vowels:
            first_vowel_index = i
            break
    else:
        # No vowels found
        return word + "ay"

    # Move consonants from the beginning to the end
    return word[first_vowel_index:] + word[:first_vowel_index] + "ay"

