def fib4(n):
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Maintain the last 4 values: fib4(i-4), fib4(i-3), fib4(i-2), fib4(i-1)
    fib0, fib1, fib2, fib3 = 0, 0, 2, 0

    for i in range(4, n + 1):
        fibn = fib0 + fib1 + fib2 + fib3
        fib0, fib1, fib2, fib3 = fib1, fib2, fib3, fibn

    return fib3

