                if is_palindrome[i][j]:
                    dp[i][j] = 1
                else:
                    # Try all possible splits
                    dp[i][j] = float('inf')
                    for k in range(i, j):
                        dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

