from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = ""
    depth = 0

    for char in paren_string:
        if char == ' ':
            continue
        elif char == '(':
            current_group += char
            depth += 1
        elif char == ')':
            current_group += char
            depth -= 1
            if depth == 0:
                result.append(current_group)
                current_group = ""

    return result

def poohbear(code):
    # Pre-scan for W-E loop pairs
    jump_table = {}
    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                w_index = stack.pop()
                jump_table[w_index] = i
                jump_table[i] = w_index

    # Initialize memory (infinite tape using sparse dict)
    memory = {}
    pointer = 0
    copy_value = 0

    # Output collection
    output = []

    # Execute code
    pc = 0
    code_len = len(code)
    valid_commands = set('+-><cWEPNTQULIVABYD')

    while pc < code_len:
        cmd = code[pc]

        # Skip non-command characters
        if cmd not in valid_commands:
            pc += 1
            continue

        # Get current cell value (default 0 if not set)
        cell = memory.get(pointer, 0)

        if cmd == '+':
            memory[pointer] = (cell + 1) % 256
            pc += 1
        elif cmd == '-':
            memory[pointer] = (cell - 1) % 256
            pc += 1
        elif cmd == '>':
            pointer += 1
            pc += 1
        elif cmd == '<':
            pointer -= 1
            pc += 1
        elif cmd == 'c':
            copy_value = cell
            pc += 1
        elif cmd == 'p':
            memory[pointer] = copy_value % 256
            pc += 1
        elif cmd == 'W':
            if cell == 0:
                # Jump to matching E
                pc = jump_table.get(pc, pc + 1)
            else:
                pc += 1
        elif cmd == 'E':
            if cell != 0:
                # Jump back to matching W
                pc = jump_table.get(pc, pc - 1)
            else:
                pc += 1
        elif cmd == 'P':
            output.append(chr(cell))
            pc += 1
        elif cmd == 'N':
            output.append(str(cell))
            pc += 1
        elif cmd == 'T':
            memory[pointer] = (cell * 2) % 256
            pc += 1
        elif cmd == 'Q':
            memory[pointer] = (cell * cell) % 256
            pc += 1
        elif cmd == 'U':
            memory[pointer] = int(cell ** 0.5)
            pc += 1
        elif cmd == 'L':
            memory[pointer] = (cell + 2) % 256
            pc += 1
        elif cmd == 'I':
            memory[pointer] = (cell - 2) % 256
            pc += 1
        elif cmd == 'V':
            memory[pointer] = int(cell / 2)
            pc += 1
        elif cmd == 'A':
            memory[pointer] = (cell + copy_value) % 256
            pc += 1
        elif cmd == 'B':
            memory[pointer] = (cell - copy_value) % 256
            pc += 1
        elif cmd == 'Y':
            memory[pointer] = (cell * copy_value) % 256
            pc += 1
        elif cmd == 'D':
            if copy_value != 0:
                memory[pointer] = int(cell / copy_value)
            pc += 1

    return ''.join(output)

def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        # Check if i is a palindrome by comparing string representation with its reverse
        if str(i) == str(i)[::-1]:
            if i % 2 == 0:
