        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx, ny = king_x + dx, king_y + dy
                if is_valid(nx, ny):
                    moves.append((nx, ny))
        return moves

    king_x, king_y = pos_to_coords(king)
    amazon_x, amazon_y = pos_to_coords(amazon)

