    amazon_controls = get_amazon_moves(amazon_x, amazon_y)

    # Get all valid black king positions (on board, not adjacent to white king)
    valid_positions = []
    for x in range(8):
        for y in range(8):
            if not is_adjacent(king_x, king_y, x, y):
                valid_positions.append((x, y))

    # Classify each position
    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    for bx, by in valid_positions:
        # Check if black king is under attack
        is_attacked = (bx, by) in amazon_controls

        if is_attacked:
            # Check if black king can escape
            king_moves = get_king_moves(bx, by)
            can_escape = False
            for nx, ny in king_moves:
                # Check if the new position is valid (not adjacent to white king)
                if not is_adjacent(king_x, king_y, nx, ny):
                    # Check if the new position is under attack by amazon
                    if (nx, ny) not in amazon_controls:
                        can_escape = True
                        break

            if can_escape:
                check += 1
            else:
                checkmate += 1
        else:
            # King is not under attack, check if it can move
            king_moves = get_king_moves(bx, by)
