        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    primes = []
    for i in range(2, n):
        if is_prime(i):
            primes.append(i)

    return primes

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, number) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract just the numbers from the sorted pairs
    return [num for _, _, num in indexed_nums]

def histogram(test):
    letters = test.split()

    if not letters:
        return {}

    from collections import Counter
    freq = Counter(letters)

    max_freq = max(freq.values())

    return {letter: count for letter, count in freq.items() if count == max_freq}

def solution(input_string, markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the position of the first comment marker
        first_marker_pos = len(line)  # Initialize to end of line
        found_marker = False

        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < first_marker_pos:
                first_marker_pos = pos
                found_marker = True

        # If we found a marker, truncate the line at that position
        if found_marker:
            processed_line = line[:first_marker_pos]
        else:
            processed_line = line

        # Strip trailing whitespace
        processed_line = processed_line.rstrip()
        result_lines.append(processed_line)

    return '\n'.join(result_lines)

def is_valid(identifier):
    # Check if identifier is empty
    if not identifier:
        return False

    # Define valid characters for first position: alpha, underscore, or dollar sign
    first_char_valid = identifier[0].isalpha() or identifier[0] == '_' or identifier[0] == '$'

    # Check if first character is valid
    if not first_char_valid:
        return False

    # Check rest of the characters: alpha, digit, underscore, or dollar sign
    for i in range(1, len(identifier)):
        if not (identifier[i].isalnum() or identifier[i] == '_' or identifier[i] == '$'):
            return False

    return True

def poohbear(code):
    memory = {}  # Sparse memory dictionary, key is position, value is byte
    pointer = 0  # Current cell pointer
    copy_reg = 0  # Copied value register

    def wrap(val):
        return val % 256

    def get_cell():
        return memory.get(pointer, 0)

    def set_cell(val):
        memory[pointer] = wrap(val)

    # Preprocess code to find matching W/E pairs
    def find_matching(code, start_pos, direction):
        depth = 0
        pos = start_pos
        while pos < len(code):
            if code[pos] == 'W':
                if direction == 1:
                    depth += 1
                else:
                    if depth == 0:
                        return pos
                    depth -= 1
            elif code[pos] == 'E':
                if direction == -1:
                    depth += 1
                else:
                    if depth == 0:
                        return pos
                    depth -= 1
            pos += direction
        return None

    output = []
    ip = 0  # Instruction pointer

    while ip < len(code):
        cmd = code[ip]

        if cmd == '+':
            set_cell(get_cell() + 1)
        elif cmd == '-':
            set_cell(get_cell() - 1)
        elif cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == 'c':
            copy_reg = get_cell()
        elif cmd == 'p':
            set_cell(copy_reg)
        elif cmd == 'W':
            if get_cell() == 0:
                # Jump to matching E
                match = find_matching(code, ip + 1, 1)
                if match is not None:
                    ip = match
                else:
                    ip += 1
            else:
                ip += 1
        elif cmd == 'E':
            if get_cell() != 0:
                # Jump back to matching W
                match = find_matching(code, ip - 1, -1)
                if match is not None:
                    ip = match
                else:
                    ip += 1
            else:
                ip += 1
        elif cmd == 'P':
            output.append(chr(get_cell()))
        elif cmd == 'N':
            output.append(str(get_cell()))
        elif cmd == 'T':
            set_cell(get_cell() * 2)
        elif cmd == 'Q':
            set_cell(get_cell() ** 2)
        elif cmd == 'U':
            set_cell(int(get_cell() ** 0.5))
        elif cmd == 'L':
            set_cell(get_cell() + 2)
        elif cmd == 'I':
            set_cell(get_cell() - 2)
        elif cmd == 'V':
            set_cell(int(get_cell() / 2))
        elif cmd == 'A':
            set_cell(get_cell() + copy_reg)
        elif cmd == 'B':
            set_cell(get_cell() - copy_reg)
        elif cmd == 'Y':
            set_cell(get_cell() * copy_reg)
        elif cmd == 'D':
            if copy_reg != 0:
                set_cell(int(get_cell() / copy_reg))
            # If copy_reg is 0, no change (division by zero undefined)

        ip += 1

    return ''.join(output)

def even_odd_palindrome(n):
