def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """

    def to_float(value):
        """Convert value to float for comparison"""
        if isinstance(value, (int, float)):
            return float(value)
        elif isinstance(value, str):
            # Replace comma with dot for decimal separator
            normalized = value.replace(',', '.')
            return float(normalized)
        else:
            return None

    # Convert both values to float for comparison
    num_a = to_float(a)
    num_b = to_float(b)

    # Compare numerically
    if num_a > num_b:
        return a
    elif num_b > num_a:
        return b
    else:
        return None

def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    even_count = 0
    odd_count = 0

    for num in range(1, n + 1):
        # Convert number to string to check for palindrome
        s = str(num)
        if s == s[::-1]:  # Check if palindrome by comparing with reverse
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def parse_int(s: str) -> int:
    # Handle empty string edge case
    if not s or not s.strip():
        return 0

    # Create mappings for number words
    units = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9,
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17,
        'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    scales = {
        'hundred': 100, 'thousand': 1000, 'million': 1000000
    }

    # Tokenize: split on spaces and hyphens, convert to lowercase
    import re
    tokens = re.split(r'[\s-]+', s.strip().lower())
    tokens = [t for t in tokens if t]  # Remove empty strings

    result = 0
    current = 0

    for token in tokens:
        if token == 'and':
            # Ignore 'and' as it's grammatical only
            continue

        if token in units:
            # Basic number word (zero through nineteen)
            if token == 'zero' and current == 0 and result == 0:
                # Special case for "zero" at the start
                result = 0
                current = 0
            else:
                current += units[token]

        elif token in tens:
            # Tens word (twenty through ninety)
            current += tens[token]

        elif token in scales:
            # Scale multiplier
            scale = scales[token]

            if token == 'hundred':
                # Hundred multiplies the current accumulated value
                current *= scale
            else:
                # Thousand or million: add current chunk to result, reset current
                current *= scale
                result += current
                current = 0

    # Add any remaining value to result
    result += current

    return result

def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

