                        # Check if move is valid (not adjacent to white king)
                        if not is_adjacent(king, coords_to_pos(k, l)):
                            king_moves.append(coords_to_pos(k, l))

            # Check if black king can move to any safe square
            can_move = False
            for move in king_moves:
                # Check if move is not adjacent to white king
                if not is_adjacent(king, move):
                    # Check if move is not attacked by amazon
                    move_x, move_y = pos_to_coords(move)
                    if (move_x, move_y) not in attacks:
                        can_move = True
                        break

            if is_attacked:
                # Check if black king can escape
                can_escape = False
                for move in king_moves:
                    if not is_adjacent(king, move):
                        move_x, move_y = pos_to_coords(move)
                        if (move_x, move_y) not in attacks:
                            can_escape = True
                            break

                if can_escape:
                    # It's a check
                    result[1] += 1
                else:
                    # It's a checkmate
                    result[0] += 1
            else:
                # It's safe
                if can_move:
                    # It's a safe square with valid moves
                    result[3] += 1
                else:
                    # It's a stalemate
                    result[2] += 1

    return result

def poohbear(code):
    memory = {}
    ptr = 0
    copied = 0

    commands = [c for c in code if c in '+-><cWpEPTQULIABDY']

    w_e_pairs = {}
    stack = []
    for i, cmd in enumerate(commands):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                w_idx = stack.pop()
                w_e_pairs[w_idx] = i
                w_e_pairs[i] = w_idx

    def wrap(val):
        return val % 256

    pc = 0
    output = []

    while pc < len(commands):
        cmd = commands[pc]
        val = memory.get(ptr, 0)

        if cmd == '+':
            memory[ptr] = wrap(val + 1)
        elif cmd == '-':
            memory[ptr] = wrap(val - 1)
        elif cmd == '>':
            ptr += 1
        elif cmd == '<':
            ptr -= 1
        elif cmd == 'c':
            copied = val
        elif cmd == 'p':
            memory[ptr] = wrap(copied)
        elif cmd == 'W':
            if val == 0:
                pc = w_e_pairs[pc] + 1
                continue
        elif cmd == 'E':
            if val != 0:
                pc = w_e_pairs[pc] - 1
                continue
        elif cmd == 'P':
            output.append(chr(val))
        elif cmd == 'N':
            output.append(str(val))
        elif cmd == 'T':
            memory[ptr] = wrap(val * 2)
        elif cmd == 'Q':
            memory[ptr] = wrap(val ** 2)
        elif cmd == 'U':
            memory[ptr] = wrap(int(val ** 0.5))
        elif cmd == 'L':
            memory[ptr] = wrap(val + 2)
        elif cmd == 'I':
            memory[ptr] = wrap(val - 2)
        elif cmd == 'V':
            memory[ptr] = wrap(int(val / 2))
        elif cmd == 'A':
            memory[ptr] = wrap(val + copied)
        elif cmd == 'B':
            memory[ptr] = wrap(val - copied)
        elif cmd == 'Y':
            memory[ptr] = wrap(val * copied)
        elif cmd == 'D':
            if copied != 0:
                memory[ptr] = wrap(int(val / copied))

        pc += 1

    return ''.join(output)

def is_valid(identifier):
    # Check if the identifier is empty
    if not identifier:
