def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2

    # Handle factor 2
    if d % p == 0:
        while d % p == 0:
            d //= p
        result -= result // p

    # Handle odd factors from 3 onwards
    p = 3
    while p * p <= d:
        if d % p == 0:
