def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, number) and sort by digit_sum and original_index
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]
    sorted_nums = sorted(indexed_nums, key=lambda x: (x[0], x[1]))

    # Extract just the numbers from the sorted result
    return [num for _, _, num in sorted_nums]

def is_balanced(s, pairs):
    if not s:
        return True

    open_to_close = {}
    close_to_open = {}

    for i in range(0, len(pairs), 2):
        if i + 1 < len(pairs):
            open_to_close[pairs[i]] = pairs[i + 1]
            close_to_open[pairs[i + 1]] = pairs[i]

    stack = []

    for char in s:
        if char in close_to_open and stack and stack[-1] == close_to_open[char]:
            stack.pop()
        elif char in open_to_close:
            stack.append(char)
        else:
            if char in close_to_open:
                return False

    return len(stack) == 0

