def amazon_check_mate(king, amazon):
    def parse_pos(pos):
        col = ord(pos[0]) - ord('a')
        row = int(pos[1]) - 1
        return (row, col)

    white_king = parse_pos(king)
    white_amazon = parse_pos(amazon)

    def get_amazon_attacks(pos):
        row, col = pos
        attacks = set()

        # Queen-like moves: all rows and columns
        for r in range(8):
            attacks.add((r, col))
        for c in range(8):
            attacks.add((row, c))

        # Queen-like moves: main diagonal (row - col is constant)
        d = row - col
        for r in range(8):
            c = r - d
            if 0 <= c < 8:
                attacks.add((r, c))

        # Queen-like moves: anti-diagonal (row + col is constant)
        s = row + col
        for r in range(8):
            c = s - r
            if 0 <= c < 8:
                attacks.add((r, c))

        # Knight-like moves: L-shaped (8 possible directions)
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
                        (1, -2), (1, 2), (2, -1), (2, 1)]
        for dr, dc in knight_moves:
            nr, nc = row + dr, col + dc
            if 0 <= nr < 8 and 0 <= nc < 8:
                attacks.add((nr, nc))

        return attacks

    amazon_attacks = get_amazon_attacks(white_amazon)

    def is_adjacent(p1, p2):
        return abs(p1[0] - p2[0]) <= 1 and abs(p1[1] - p2[1]) <= 1 and p1 != p2

    def is_valid_bk_pos(pos):
        return not is_adjacent(pos, white_king)

    # [checkmate, check, stalemate, safe with moves]
    result = [0, 0, 0, 0]

    for r in range(8):
        for c in range(8):
            pos = (r, c)

            # Skip squares occupied by white pieces
            if pos == white_king or pos == white_amazon:
                continue

            # Black king cannot be adjacent to white king
            if not is_valid_bk_pos(pos):
                continue

            # Check if black king is under amazon's attack
            under_attack = pos in amazon_attacks

            # Find all safe adjacent squares for black king
            safe_squares = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 8 and 0 <= nc < 8:
                        npos = (nr, nc)
                        if not is_adjacent(npos, white_king):
                            if npos not in amazon_attacks:
                                safe_squares.append(npos)

            if under_attack:
                if len(safe_squares) == 0:
                    result[0] += 1  # checkmate
                else:
                    result[1] += 1  # check
            else:
                if len(safe_squares) == 0:
                    result[2] += 1  # stalemate
                else:
                    result[3] += 1  # safe with moves

    return result

import math

def sum_of_squares(n):
    # Check if n is a perfect square
    sqrt_n = int(math.sqrt(n))
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n can be represented as sum of two squares
    for i in range(1, int(math.sqrt(n)) + 1):
        remainder = n - i * i
        sqrt_remainder = int(math.sqrt(remainder))
        if sqrt_remainder * sqrt_remainder == remainder:
            return 2

    # Check if n can be represented as sum of three squares
    # Using Legendre's three-square theorem: n = 4^a(8b + 7) cannot be represented as sum of 3 squares
    while n % 4 == 0:
        n //= 4

    if n % 8 == 7:
        return 4

    # If none of the above, it can be represented as sum of 3 squares
    return 3

