def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    def lucas_lehmer_test(p):
        if p == 2:
            return True
        s = 4
        m = (1 << p) - 1  # This is 2^p - 1
        for _ in range(p - 2):
            s = (s * s - 2) % m
        return s == 0

    # Check if n is prime
    if not is_prime(n):
        return False

    # If n is prime, check if 2^n - 1 is prime using Lucas-Lehmer test
    return lucas_lehmer_test(n)

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part to given base
    if integer_part == 0:
        integer_digits = ['0']
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            # Handle floating point precision issues
            if remainder >= base - 1e-10:
                remainder = 0
                temp = temp // base - 1
            else:
                temp = temp // base
            integer_digits.append(remainder)

        # Convert remainders to digits (handling the case where remainder is close to base)
        for i in range(len(integer_digits)):
            if integer_digits[i] >= base - 1e-10:
                integer_digits[i] = 0
                if i + 1 < len(integer_digits):
                    integer_digits[i + 1] += 1
                else:
                    integer_digits.append(1)

        # Convert to proper digit characters
        result_digits = []
        for digit in integer_digits:
            if digit < 10:
                result_digits.append(str(int(digit)))
            else:
                result_digits.append(chr(ord('A') + int(digit) - 10))

        # Reverse to get correct order
        result_digits.reverse()
        integer_result = ''.join(result_digits)

    # Handle fractional part
    if decimals == 0:
        fractional_result = ''
    else:
        fractional_digits = []
        temp_fraction = fractional_part
        for _ in range(decimals):
            temp_fraction *= base
            digit = int(temp_fraction)
            fractional_digits.append(digit)
            temp_fraction -= digit

            # Handle precision issues
            if abs(temp_fraction) < 1e-10:
                break

        # Convert fractional digits to proper characters
        fractional_chars = []
        for digit in fractional_digits:
            if digit < 10:
                fractional_chars.append(str(digit))
            else:
                fractional_chars.append(chr(ord('A') + digit - 10))

        fractional_result = '.' + ''.join(fractional_chars)

    # Combine results
    result = integer_result + fractional_result

    # Handle negative sign
    if negative:
        result = '-' + result

    # Handle leading zero for numbers less than 1
    if number < 1 and '.' in result:
        if result.startswith('0.'):
            pass
        elif result.startswith('-0.'):
            result = result[:2] + '0' + result[2:]

    return result

def differentiate(poly, x_point):
