def amazon_check_mate(king, amazon):
    def parse_pos(pos):
        file = ord(pos[0]) - ord('a')
        rank = int(pos[1]) - 1
        return (file, rank)

    def get_king_moves(file, rank):
        moves = []
        for df in [-1, 0, 1]:
            for dr in [-1, 0, 1]:
                if df == 0 and dr == 0:
                    continue
                new_file = file + df
                new_rank = rank + dr
                if 0 <= new_file <= 7 and 0 <= new_rank <= 7:
                    moves.append((new_file, new_rank))
        return moves

    def is_attacked_by_amazon(bk_file, bk_rank, am_file, am_rank):
        # Queen-like attacks (same file, rank, or diagonal)
        if bk_file == am_file or bk_rank == am_rank or abs(bk_file - am_file) == abs(bk_rank - am_rank):
            return True
        # Knight-like attacks (L-shape: 2+1)
        if abs(bk_file - am_file) * abs(bk_rank - am_rank) == 2:
            return True
        return False

    wk_file, wk_rank = parse_pos(king)
    am_file, am_rank = parse_pos(amazon)

    checkmate_count = 0
    check_count = 0
    stalemate_count = 0
    safe_count = 0

    for bk_file in range(8):
        for bk_rank in range(8):
            # Skip if occupied by white pieces
            if (bk_file == wk_file and bk_rank == wk_rank) or \
               (bk_file == am_file and bk_rank == am_rank):
                continue

            # Skip if adjacent to white king (kings cannot be adjacent)
            if abs(bk_file - wk_file) <= 1 and abs(bk_rank - wk_rank) <= 1:
                continue

            # Check if attacked by amazon
            attacked = is_attacked_by_amazon(bk_file, bk_rank, am_file, am_rank)

            # Check if there are valid escape moves
            has_escape = False
            for move_file, move_rank in get_king_moves(bk_file, bk_rank):
                # Skip if move lands on white pieces
                if (move_file == wk_file and move_rank == wk_rank) or \
                   (move_file == am_file and move_rank == am_rank):
                    continue

                # Skip if move is adjacent to white king
                if abs(move_file - wk_file) <= 1 and abs(move_rank - wk_rank) <= 1:
                    continue

                # Skip if move is attacked by amazon
                if is_attacked_by_amazon(move_file, move_rank, am_file, am_rank):
                    continue

                has_escape = True
                break

            # Classify the position
            if attacked:
                if has_escape:
                    check_count += 1
                else:
                    checkmate_count += 1
            else:
                if has_escape:
                    safe_count += 1
                else:
                    stalemate_count += 1

    return [checkmate_count, check_count, stalemate_count, safe_count]

