def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2

    while p * p <= d:
        if d % p == 0:
            while d % p == 0:
                d //= p
            result -= result // p
        p += 1

    if d > 1:
        result -= result // d

    return result

def string_xor(a, b):
    # Handle empty strings
    if not a and not b:
        return ""
    if not a:
        return b
    if not b:
        return a

    # Make both strings the same length by padding with leading zeros
    max_len = max(len(a), len(b))
    a = a.zfill(max_len)
    b = b.zfill(max_len)

    # Perform XOR operation bit by bit
    result = ""
    for i in range(max_len):
        # XOR: same bits = 0, different bits = 1
        if a[i] == b[i]:
            result += "0"
        else:
            result += "1"

    return result

