def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    is_negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % int(base)
            integer_digits.append(remainder)
            temp = temp // int(base)
        integer_digits.reverse()

    # Convert fractional part
    fractional_part = number - integer_part
    fractional_digits = []

    if fractional_part > 0 and decimals > 0:
        temp_fraction = fractional_part
        for _ in range(decimals):
            temp_fraction *= base
            digit = int(temp_fraction)
            fractional_digits.append(digit)
            temp_fraction -= digit

    # Format the result
    if not integer_digits:
        result = '0'
    else:
        result = ''.join(str(digit) for digit in integer_digits)

    if decimals > 0 and fractional_digits:
        result += '.'
        result += ''.join(str(digit) for digit in fractional_digits)

    # Handle negative sign
    if is_negative:
        result = '-' + result

    # Ensure proper formatting for numbers < 1
    if not is_negative and number < 1 and '.' in result:
        # If the result starts with a decimal point, we need a leading zero
        if result.startswith('.'):
            result = '0' + result

    # Convert digits to base-36 representation
    digit_map = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    final_result = ''
    for char in result:
        if char == '.':
            final_result += '.'
        elif char == '-':
            final_result += '-'
        else:
            digit_value = int(char)
            final_result += digit_map[digit_value]

    return final_result

