    import re
    from collections import defaultdict

    # Parse the expression into terms
    # Split by + and - signs, keeping the signs
    terms = re.findall(r'[+-]?[^+-]+', expression)

    # Dictionary to store monomial -> coefficient mapping
    monomial_coeffs = defaultdict(int)

    for term in terms:
        # Handle the sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Parse the coefficient and monomial
        if 'x' in term:
            # Find coefficient (everything before the first 'x')
            coeff_str = ''
            i = 0
            while i < len(term) and term[i] != 'x':
                coeff_str += term[i]
                i += 1

            if coeff_str == '' or coeff_str == '+':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)

            # Get the remaining part (the monomial without coefficient)
            monomial_part = term[i:]
        else:
            # No 'x' means it's a constant or just a variable
            if term == '':
                coeff = 0
            else:
                coeff = int(term) if term.lstrip('+-').isdigit() else 1
            monomial_part = ''

        # Apply sign to coefficient
        coeff *= sign

        # Normalize monomial (sort variables)
        if monomial_part:
            sorted_vars = ''.join(sorted(monomial_part))
        else:
            sorted_vars = ''

        # Add to dictionary
        monomial_coeffs[sorted_vars] += coeff

    # Remove zero coefficients
    monomial_coeffs = {m: c for m, c in monomial_coeffs.items() if c != 0}

    # Sort monomials by number of variables, then lexicographically
    sorted_monomials = sorted(monomial_coeffs.items(), 
                              key=lambda x: (len(x[0]), x[0]))

    # Format output
    result = []
    for i, (monomial, coeff) in enumerate(sorted_monomials):
        if coeff == 1 and monomial != '':
            term = monomial
        elif coeff == -1 and monomial != '':
            term = '-' + monomial
        else:
            term = str(coeff) + monomial

        # Add sign
        if i == 0:
            result.append(term)
        else:
            if term.startswith('-'):
                result.append('-' + term[1:])
            else:
                result.append('+' + term)

    # Join and remove leading +
    output = ''.join(result)
    if output.startswith('+'):
        output = output[1:]

    return output

def is_balanced(string_to_validate, pairs_string):
    # Parse the pairs string to create mapping
    opening_chars = set()
    closing_chars = set()
    pair_map = {}  # opening -> closing

    for i in range(0, len(pairs_string), 2):
        if i + 1 < len(pairs_string):
            opening = pairs_string[i]
            closing = pairs_string[i + 1]
            opening_chars.add(opening)
            closing_chars.add(closing)
            pair_map[opening] = closing

    # Handle empty string
    if not string_to_validate:
        return True

    # Stack to track opening characters
    stack = []

    # Process each character in the string
    for char in string_to_validate:
        if char in opening_chars:
            stack.append(char)
        elif char in closing_chars:
            if not stack:
                return False
            top = stack.pop()
            if pair_map[top] != char:
                return False
        # If character is neither opening nor closing, ignore it

    # Stack should be empty if balanced
    return len(stack) == 0

import math

def converter(number, decimals=0, base=math.pi):
    # Define the digit mapping
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

    # Handle zero case
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    is_negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Handle integer part
    if integer_part == 0:
        result_integer = ''
    else:
        result_integer = ''
        value = integer_part
        while value >= 1:
            remainder = value % base
            digit = int(remainder)
            # Validate digit
            if digit < 0 or digit >= int(base):
                raise ValueError("Digit out of range")
            result_integer = digits[digit] + result_integer
            value = (value - remainder) / base

    # Handle fractional part
    result_fractional = ''
    if decimals > 0:
        fraction = fractional_part
        for _ in range(decimals):
            fraction = fraction * base
            digit = int(fraction)
            # Validate digit
            if digit < 0 or digit >= int(base):
                raise ValueError("Digit out of range")
            result_fractional += digits[digit]
            fraction = fraction - digit

    # Combine parts
    if result_integer:
        if result_fractional:
            result = result_integer + '.' + result_fractional
        else:
            result = result_integer
    else:
        if result_fractional:
            result = '0.' + result_fractional
        else:
            result = '0'

    # Add negative sign if needed
    if is_negative:
        result = '-' + result

    return result

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False

        # Check odd divisors up to sqrt(num)
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    if is_prime(n):
        return x
    else:
        return y

