    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

def amazon_check_mate(king, amazon):
    def parse_position(pos):
        file_idx = ord(pos[0]) - ord('a')
        rank_idx = int(pos[1]) - 1
        return (file_idx, rank_idx)

    def is_adjacent(pos1, pos2):
        return 0 < abs(pos1[0] - pos2[0]) <= 1 and 0 < abs(pos1[1] - pos2[1]) <= 1

    def amazon_attacks(amazon_pos, target_pos):
        dx = target_pos[0] - amazon_pos[0]
        dy = target_pos[1] - amazon_pos[1]

        # Knight move
        if (abs(dx), abs(dy)) in [(1, 2), (2, 1)]:
            return True

        # Horizontal/Vertical move
        if dx == 0 or dy == 0:
            steps = max(abs(dx), abs(dy))
            step_x = 0 if dx == 0 else (1 if dx > 0 else -1)
            step_y = 0 if dy == 0 else (1 if dy > 0 else -1)
            for i in range(1, steps):
                if (amazon_pos[0] + step_x * i, amazon_pos[1] + step_y * i) == white_king_pos:
                    return False
            return True

        # Diagonal move
        if abs(dx) == abs(dy):
            steps = abs(dx)
            step_x = 1 if dx > 0 else -1
            step_y = 1 if dy > 0 else -1
            for i in range(1, steps):
                if (amazon_pos[0] + step_x * i, amazon_pos[1] + step_y * i) == white_king_pos:
                    return False
            return True

        return False

    white_king_pos = parse_position(king)
    amazon_pos = parse_position(amazon)

    checkmate_count = 0
    check_count = 0
    stalemate_count = 0
    safe_count = 0

    for file_idx in range(8):
        for rank_idx in range(8):
            black_pos = (file_idx, rank_idx)

            if black_pos == white_king_pos or black_pos == amazon_pos:
                continue
            if is_adjacent(black_pos, white_king_pos):
                continue

            under_attack = amazon_attacks(amazon_pos, black_pos)

            valid_moves = []
            for df in [-1, 0, 1]:
                for dr in [-1, 0, 1]:
                    if df == 0 and dr == 0:
                        continue
                    new_file = file_idx + df
                    new_rank = rank_idx + dr
                    if 0 <= new_file < 8 and 0 <= new_rank < 8:
                        new_pos = (new_file, new_rank)
                        if new_pos == white_king_pos or new_pos == amazon_pos:
                            continue
                        if is_adjacent(new_pos, white_king_pos):
                            continue
                        if amazon_attacks(amazon_pos, new_pos):
                            continue
                        valid_moves.append(new_pos)

            if under_attack and len(valid_moves) == 0:
                checkmate_count += 1
            elif under_attack and len(valid_moves) > 0:
                check_count += 1
            elif not under_attack and len(valid_moves) == 0:
                stalemate_count += 1
            else:
                safe_count += 1

    return [checkmate_count, check_count, stalemate_count, safe_count]

def compare(selector1, selector2):
    def parse_selector(selector):
        if not selector or selector == "*":
            return (0, 0, 0)

        components = selector.split()

        total_ids = 0
        total_classes = 0
        total_tagnames = 0

        for component in components:
            if component == "*":
                continue

            id_count = component.count('#')
            total_ids += id_count

            class_count = component.count('.')
            total_classes += class_count

            pos = len(component)
            for i, c in enumerate(component):
                if c in '#.':
                    pos = i
                    break

            tagname_part = component[:pos]
            if tagname_part:
                total_tagnames += 1

        return (total_ids, total_classes, total_tagnames)

    spec1 = parse_selector(selector1)
    spec2 = parse_selector(selector2)

    if spec1 > spec2:
        return selector1
    elif spec2 > spec1:
        return selector2
    else:
        return selector2

import math
from collections import defaultdict

def poohbear(code):
    # Extract actual code from input
    if isinstance(code, list):
        code_str = code[0] if code else ""
    elif isinstance(code, str):
        code_str = code
        # Strip outer brackets if present
        code_str = code_str.strip()
        if code_str.startswith("['") and code_str.endswith("']"):
            code_str = code_str[2:-2]
        elif code_str.startswith('["') and code_str.endswith('"]'):
            code_str = code_str[2:-2]
    else:
        code_str = str(code)

    # Filter to only valid commands
    valid_commands = set('+-<>cpWEPNTQULIVABYD')
    filtered_code = ''.join(c for c in code_str if c in valid_commands)

    # Build loop matching dictionary (W -> E and E -> W)
    loop_map = {}
    stack = []

    for i, cmd in enumerate(filtered_code):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                w_index = stack.pop()
                loop_map[w_index] = i
                loop_map[i] = w_index

    # Initialize state
    cells = defaultdict(int)  # Infinite memory, default 0
    ptr = 0  # Data pointer
    copy = 0  # Copy register
    pc = 0  # Program counter
    output = []

    # Execute commands
    while pc < len(filtered_code):
        cmd = filtered_code[pc]

        if cmd == '+':
            cells[ptr] = (cells[ptr] + 1) % 256
        elif cmd == '-':
            cells[ptr] = (cells[ptr] - 1) % 256
        elif cmd == '>':
            ptr += 1
        elif cmd == '<':
            ptr -= 1
        elif cmd == 'c':
            copy = cells[ptr]
        elif cmd == 'p':
            cells[ptr] = copy
        elif cmd == 'W':
            if cells[ptr] == 0:
                pc = loop_map[pc]
                pc += 1
                continue
        elif cmd == 'E':
            if cells[ptr] != 0:
                pc = loop_map[pc]
                continue
        elif cmd == 'P':
            output.append(chr(cells[ptr]))
        elif cmd == 'N':
            output.append(str(cells[ptr]))
        elif cmd == 'T':
            cells[ptr] = (cells[ptr] * 2) % 256
        elif cmd == 'Q':
            cells[ptr] = (cells[ptr] ** 2) % 256
        elif cmd == 'U':
            cells[ptr] = int(math.sqrt(cells[ptr]))
        elif cmd == 'L':
            cells[ptr] = (cells[ptr] + 2) % 256
        elif cmd == 'I':
            cells[ptr] = (cells[ptr] - 2) % 256
        elif cmd == 'V':
            cells[ptr] = (cells[ptr] // 2) % 256
        elif cmd == 'A':
            cells[ptr] = (cells[ptr] + copy) % 256
        elif cmd == 'B':
            cells[ptr] = (cells[ptr] - copy) % 256
        elif cmd == 'Y':
            cells[ptr] = (cells[ptr] * copy) % 256
        elif cmd == 'D':
            if copy != 0:
                cells[ptr] = (cells[ptr] // copy) % 256

        pc += 1

    return ''.join(output)

