def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    def is_palindrome(num):
        s = str(num)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

import re

def differentiate(poly, x):
    poly = poly.strip()
    if not poly:
        return 0

    total = 0
    i = 0
    n = len(poly)

    while i < n:
        # Skip whitespace
        while i < n and poly[i].isspace():
            i += 1
        if i >= n:
            break

        # Parse term sign
        sign = 1
        if i < n and poly[i] == '-':
            sign = -1
            i += 1
        elif i < n and poly[i] == '+':
            i += 1

        # Skip whitespace
        while i < n and poly[i].isspace():
            i += 1
        if i >= n:
            break

        # Parse coefficient
        term_start = i
        while i < n and poly[i].isdigit():
            i += 1

        coeff_str = poly[term_start:i]
        coeff = int(coeff_str) if coeff_str else 1

        # Check for 'x'
        if i < n and poly[i] == 'x':
            i += 1

            # Check for exponent
            if i < n and poly[i] == '^':
                i += 1
                exp_start = i
                while i < n and poly[i].isdigit():
                    i += 1
                exp_str = poly[exp_start:i]
                exponent = int(exp_str) if exp_str else 1
            else:
                exponent = 1

            final_coeff = sign * coeff

            # Differentiate: d/dx(ax^n) = n*a*x^(n-1)
            if exponent > 0:
                deriv_coeff = final_coeff * exponent
                deriv_exponent = exponent - 1
                if deriv_exponent == 0:
                    total += deriv_coeff
                elif deriv_exponent > 0:
                    total += deriv_coeff * (x ** deriv_exponent)
        else:
            # Constant term, derivative is 0
            pass

        # Skip whitespace
        while i < n and poly[i].isspace():
            i += 1

    return total

