                                if (color == 'white' and is_black(target)) or (color == 'black' and is_white(target)):
                                    if target != 'K' and target != 'k':
                                        moves.append(((r, c), (nr, nc)))
                                break
                            if target != 'K' and target != 'k':
                                moves.append(((r, c), (nr, nc)))
                            nr += dr
                            nc += dc
                elif piece_type == 'A':
                    # Amazon = Queen + Knight moves
                    # Knight part
                    for dr, dc in [(1, 2), (2, 1), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2)]:
                        nr, nc = r + dr, c + dc
