def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    result = []
    for char_a, char_b in zip(a, b):
        if char_a == char_b:
            result.append('0')
        else:
            result.append('1')
    return ''.join(result)

def largest_divisor(n: int) -> int:
    if n <= 1:
        return 1

    # Find the smallest prime factor
    smallest_factor = n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            smallest_factor = i
            break

    # If no factor found, n is prime, so largest proper divisor is 1
    if smallest_factor == n:
        return 1

    # Otherwise, largest proper divisor is n divided by smallest prime factor
    return n // smallest_factor

