def monotonic(l: list):
    # Handle edge cases
    if len(l) <= 1:
        return True

    # Determine the initial trend
    is_increasing = None

    # Check the first pair of elements that are not equal
    for i in range(len(l) - 1):
        if l[i] < l[i + 1]:
            is_increasing = True
            break
        elif l[i] > l[i + 1]:
            is_increasing = False
            break

    # If all elements are equal, it's monotonic
    if is_increasing is None:
        return True

    # Validate the entire sequence maintains the determined trend
    for i in range(len(l) - 1):
        if is_increasing:
            if l[i] > l[i + 1]:
                return False
        else:
            if l[i] < l[i + 1]:
                return False

    return True

