def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # For 2^n - 1 to be a Mersenne prime, n must be prime
    # Also, we need to check that 2^n - 1 is actually prime
    if not is_prime(n):
        return False

    # Special case: 2^1 - 1 = 1, which is not prime
    if n == 1:
        return False

    # Calculate 2^n - 1
    mersenne_number = (1 << n) - 1

    # Check if the Mersenne number is prime
    return is_prime(mersenne_number)

def differentiate(polynomial, x):
    # Split the polynomial into terms
    # Handle the case where the first term might be negative
    if polynomial[0] == '-':
        terms = ['-']
        i = 1
    else:
        terms = []
        i = 0

    current_term = ""
    while i < len(polynomial):
        if polynomial[i] in '+-' and current_term:
            terms.append(current_term)
            current_term = polynomial[i]
        else:
            current_term += polynomial[i]
        i += 1

    if current_term:
        terms.append(current_term)

    # Process each term
    derivative_terms = []

    for term in terms:
        if not term or term == '+':
            continue
        if term == '-':
            continue

        # Handle negative terms
        if term.startswith('-') and len(term) > 1:
            sign = -1
            term = term[1:]
        else:
            sign = 1

        # Parse the term
        if 'x' not in term:
            # Constant term
            continue
        elif term == 'x':
            # x term
            coefficient = sign * 1
            exponent = 1
        elif term == '-x':
            # -x term
            coefficient = sign * -1
            exponent = 1
        elif term.endswith('x'):
            # ax term
            coefficient = sign * int(term[:-1])
            exponent = 1
        elif term.endswith('x^0'):
            # ax^0 term
            coefficient = sign * int(term[:-2])
            exponent = 0
        elif 'x^' in term:
            # ax^n term
            parts = term.split('x^')
            if parts[0] == '':
                coefficient = sign * 1
            elif parts[0] == '-':
                coefficient = sign * -1
            else:
                coefficient = sign * int(parts[0])
            exponent = int(parts[1])
        else:
            # ax term
            coefficient = sign * int(term[:-1])
            exponent = 1

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent == 0:
            # Derivative of a constant is 0
            continue
        else:
            new_coefficient = coefficient * exponent
            new_exponent = exponent - 1

            if new_exponent == 0:
                # Just a constant
                derivative_terms.append(new_coefficient)
            elif new_exponent == 1:
                # ax term
                if new_coefficient == 1:
                    derivative_terms.append('x')
                elif new_coefficient == -1:
                    derivative_terms.append('-x')
                else:
                    derivative_terms.append(f"{new_coefficient}x")
            else:
                # ax^n term
                if new_coefficient == 1:
                    derivative_terms.append(f"x^{new_exponent}")
                elif new_coefficient == -1:
                    derivative_terms.append(f"-x^{new_exponent}")
                else:
                    derivative_terms.append(f"{new_coefficient}x^{new_exponent}")

    # Evaluate the derivative at x
    result = 0

    # If there are no derivative terms, the result is 0
    if not derivative_terms:
        return 0

    # Process each term in the derivative
    for term in derivative_terms:
        if term == 'x':
            result += x
        elif term == '-x':
            result -= x
        elif term.endswith('x'):
            # ax term
            coefficient = int(term[:-1])
            result += coefficient * x
        elif 'x^' in term:
            # ax^n term
            parts = term.split('x^')
            coefficient = int(parts[0])
            exponent = int(parts[1])
            result += coefficient * (x ** exponent)
        else:
            # Constant term
            result += int(term)

    return result

def factorize(n):
    if n <= 1:
        return []

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    # Split the string and count frequencies
    letters = test.split()
    freq_dict = {}

    for letter in letters:
        freq_dict[letter] = freq_dict.get(letter, 0) + 1

    # Find the maximum frequency
    max_freq = max(freq_dict.values())

    # Return all letters with maximum frequency
    return {letter: count for letter, count in freq_dict.items() if count == max_freq}

