    if len(txt) == 1:
        return True

    # Check if the character before the last one is a space
    # This would mean the last character is not part of a word
    return txt[-2] == ' '

import math

def sum_of_squares(n):
    # Step 1: Check if n is a perfect square (answer is 1)
    if math.isqrt(n) ** 2 == n:
        return 1

    # Step 2: Check if n is of the form 4^a * (8b + 7) using Legendre's three-square theorem
    # Such numbers require exactly 4 squares
    temp = n
    while temp % 4 == 0:
        temp //= 4
    if temp % 8 == 7:
        return 4

    # Step 3: Check if n can be written as sum of 2 squares
    sqrt_n = math.isqrt(n)
    for i in range(sqrt_n + 1):
        remainder = n - i * i
        if math.isqrt(remainder) ** 2 == remainder:
            return 2

    # Step 4: Otherwise, by Legendre's theorem, answer is 3
    return 3

def is_valid(s):
    # Check if string is empty
    if not s:
        return False

    # Check first character: must be alpha, underscore, or dollar sign
    first_char = s[0]
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Check remaining characters: can be alpha, digit, underscore, or dollar sign
    for char in s[1:]:
        if not (char.isalpha() or char.isdigit() or char == '_' or char == '$'):
            return False

    return True

def solution(input_string, markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the position of the first comment marker
        comment_pos = len(line)
        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < comment_pos:
                comment_pos = pos

        # If we found a comment marker, truncate the line
        if comment_pos < len(line):
            line = line[:comment_pos]

        # Strip trailing whitespace
        line = line.rstrip()
        result_lines.append(line)

    return '\n'.join(result_lines)

def valid_mersenne(n):
    if n <= 1:
        return False

    if n == 2:
        return True

    # n must be prime for 2^n - 1 to potentially be a Mersenne prime
    if n % 2 == 0:
        return False

    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2

    # Lucas-Lehmer primality test for Mersenne numbers M_n = 2^n - 1
    mersenne = pow(2, n) - 1
    s = 4
    for _ in range(n - 2):
        s = (s * s - 2) % mersenne

    return s == 0

def even_odd_palindrome(n):
