def parse_int(s):
    if not s:
        return 0

    # Define mappings
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14,
        'fifteen': 15, 'sixteen': 16, 'seventeen': 17, 'eighteen': 18,
        'nineteen': 19, 'twenty': 20, 'thirty': 30, 'forty': 40,
        'fifty': 50, 'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    # Split the string by spaces and hyphens
    words = []
    for part in s.split():
        words.extend(part.split('-'))

    # Remove empty strings
    words = [word for word in words if word]

    # Process the words
    result = 0
    current = 0

    for word in words:
        if word in word_to_num:
            current += word_to_num[word]
        elif word == 'hundred':
            current *= 100
        elif word == 'thousand':
            result += current * 1000
            current = 0
        elif word == 'million':
            result += current * 1000000
            current = 0

    return result + current

import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])

    if n == 1:
        print(0)
        return

    edges = []
    max_weight = 0

    for i in range(n - 1):
        u = int(data[1 + 3 * i])
        v = int(data[2 + 3 * i])
        w = int(data[3 + 3 * i])
        edges.append((u, v, w))
        max_weight = max(max_weight, w)

    # Binary search on the answer
    low = 0
    high = max_weight
    ans = 0

    def find(x, parent):
        if parent[x] != x:
            parent[x] = find(parent[x], parent)
        return parent[x]

    def union(x, y, parent, rank):
        px = find(x, parent)
        py = find(y, parent)
        if px != py:
            if rank[px] < rank[py]:
                px, py = py, px
            parent[py] = px
            if rank[px] == rank[py]:
                rank[px] += 1

    def check(w):
        # Create DSU for edges with weight < w
        parent = list(range(n + 1))
        rank = [0] * (n + 1)

        # Add edges with weight < w
        for u, v, weight in edges:
            if weight < w:
                union(u, v, parent, rank)

        # Count component sizes
        component_size = [0] * (n + 1)
        for i in range(1, n + 1):
            root = find(i, parent)
            component_size[root] += 1

        # Check if any component has more than n/2 nodes
        for i in range(1, n + 1):
            if component_size[i] > 0 and component_size[i] > n // 2:
                return False

        return True

    # Binary search
    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            low = mid + 1
        else:
            high = mid - 1

    print(ans)

if __name__ == "__main__":
    main()

