def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into monomials
    # Find all terms (including signs)
    terms = re.findall(r'[+-]?[^+-]+', expression)

    # Dictionary to store monomials and their coefficients
    monomial_dict = defaultdict(int)

    for term in terms:
        # Separate the coefficient from the variables
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Find coefficient
        coeff_str = ''
        i = 0
        while i < len(term) and term[i].isdigit():
            coeff_str += term[i]
            i += 1

        if coeff_str == '':
            coeff = sign * 1
        else:
            coeff = sign * int(coeff_str)

        # Remaining part is the variables
        variables = term[i:]

        # Sort variables to normalize the monomial
        sorted_vars = ''.join(sorted(variables))

        # Add to dictionary
        monomial_dict[sorted_vars] += coeff

    # Filter out zero coefficients
    monomial_dict = {k: v for k, v in monomial_dict.items() if v != 0}

    # Sort monomials by number of variables, then lexicographically
    sorted_monomials = sorted(monomial_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Build result string
    result = []
    first = True

    for monomial, coeff in sorted_monomials:
        if coeff > 0 and not first:
            result.append('+')
        elif coeff < 0:
            if first:
                result.append('-')
            else:
                result.append('-')
            coeff = abs(coeff)
        elif first and coeff == 0:
            continue

        if coeff == 1 and monomial != '':
            result.append(monomial)
        elif coeff == -1 and monomial != '':
            result.append('-' + monomial)
        elif monomial == '':
            result.append(str(coeff))
        else:
            result.append(str(coeff) + monomial)

        first = False

    if not result:
        return "0"

    return ''.join(result)

