def poohbear(code):
    # Initialize memory and pointer
    memory = {}
    pointer = 0
    copied = 0
    output = ""

    # Parse code to find loop pairs
    loops = []
    loop_stack = []
    for i, char in enumerate(code):
        if char == 'W':
            loop_stack.append(i)
        elif char == 'E':
            if loop_stack:
                start = loop_stack.pop()
                loops.append((start, i))

    # Create a mapping for loop pairs
    loop_map = {}
    for start, end in loops:
        loop_map[start] = end
        loop_map[end] = start

    # Execute code
    i = 0
    while i < len(code):
        char = code[i]

        # Ignore non-command characters
        if char not in "+-><cpWEPNTQLIVABYD":
            i += 1
            continue

        if char == '+':
            memory[pointer] = memory.get(pointer, 0) + 1
            if memory[pointer] > 255:
                memory[pointer] = 0

        elif char == '-':
            memory[pointer] = memory.get(pointer, 0) - 1
            if memory[pointer] < 0:
                memory[pointer] = 255

        elif char == '>':
            pointer += 1

        elif char == '<':
            pointer -= 1

        elif char == 'c':
            copied = memory.get(pointer, 0)

        elif char == 'p':
            memory[pointer] = copied

        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                # Jump to matching E
                if i in loop_map:
                    i = loop_map[i]
            # If not zero, continue normally

        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                # Jump back to matching W
                if i in loop_map:
                    i = loop_map[i]
            # If zero, continue normally

        elif char == 'P':
            output += chr(memory.get(pointer, 0))

        elif char == 'N':
            output += str(memory.get(pointer, 0))

        elif char == 'T':
            value = memory.get(pointer, 0)
            memory[pointer] = value * 2
            if memory[pointer] > 255:
                memory[pointer] = 0

        elif char == 'Q':
            value = memory.get(pointer, 0)
            memory[pointer] = value * value
            if memory[pointer] > 255:
                memory[pointer] = 0

        elif char == 'U':
            value = memory.get(pointer, 0)
            import math
            memory[pointer] = int(math.sqrt(value))

        elif char == 'L':
            memory[pointer] = memory.get(pointer, 0) + 2
            if memory[pointer] > 255:
                memory[pointer] = 0

        elif char == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            if memory[pointer] < 0:
                memory[pointer] = 255

        elif char == 'V':
            value = memory.get(pointer, 0)
            memory[pointer] = value // 2

        elif char == 'A':
            value = memory.get(pointer, 0)
            memory[pointer] = value + copied
            if memory[pointer] > 255:
                memory[pointer] = 0

        elif char == 'B':
            value = memory.get(pointer, 0)
            memory[pointer] = value - copied
            if memory[pointer] < 0:
                memory[pointer] = 255

        elif char == 'Y':
            value = memory.get(pointer, 0)
            memory[pointer] = value * copied
            if memory[pointer] > 255:
                memory[pointer] = 0

        elif char == 'D':
            value = memory.get(pointer, 0)
            if copied != 0:
                memory[pointer] = value // copied
            else:
                memory[pointer] = 0

        i += 1

    return output

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        return 1

    # Find the smallest prime factor
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i

    # If no factor found, n is prime, so largest proper divisor is 1
    return 1

def sum_of_squares(n):
    # Step 1: Check if n is a perfect square (answer = 1)
    sqrt_n = int(n ** 0.5)
    if sqrt_n * sqrt_n == n:
        return 1

    # Step 2: Check if n can be expressed as sum of two squares (answer = 2)
    for a in range(1, sqrt_n + 1):
        remainder = n - a * a
        if remainder <= 0:
            break
        sqrt_rem = int(remainder ** 0.5)
        if sqrt_rem * sqrt_rem == remainder:
            return 2

    # Step 3: Check Legendre's Three-Square Theorem
    # A number n can be written as sum of 3 squares iff n is NOT of form 4^a * (8b + 7)
    m = n
    while m % 4 == 0:
        m //= 4

    if m % 8 == 7:
        return 4

    # Step 4: Otherwise, answer is 3
    return 3

def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    n = d

    # Handle factor 2
    if n % 2 == 0:
        result = result // 2 * 1
        while n % 2 == 0:
            n //= 2

    # Handle odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result = result // i * (i - 1)
            while n % i == 0:
                n //= i
        i += 2

    # If n > 1 after all divisions, it's a prime factor
    if n > 1:
        result = result // n * (n - 1)

    return result

def compare_one(a, b):
    def to_numeric(value):
        if isinstance(value, (int, float)):
            return float(value)
        elif isinstance(value, str):
            # Replace comma with dot for decimal separator
            normalized = value.replace(',', '.')
            return float(normalized)
        else:
            raise TypeError("Unsupported type")

    def is_equal(val1, val2):
        return abs(val1 - val2) < 1e-10

    num_a = to_numeric(a)
    num_b = to_numeric(b)

    if is_equal(num_a, num_b):
        return None

    if num_a > num_b:
        return a
    else:
        return b

def histogram(s):
