    return {letter: count for letter, count in freq.items() if count == max_freq}

from typing import List, Tuple


def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    if not numbers:
        return (0, 1)

    total_sum = sum(numbers)

    product = 1
    for num in numbers:
        product *= num

    return (total_sum, product)

def max_element(l: list):
    """Return maximum element in the list.
    >>> max_element([1, 2, 3])
    3
    >>> max_element([5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10])
    123
    """
    if not l:
        raise ValueError("max_element() arg is an empty sequence")
    return max(l)

def simplify(expression):
    # Dictionary to store monomial -> coefficient mapping
    monomials = {}

    # Parse the expression
    # We'll split by '+' and '-' but handle the signs properly
    i = 0
    current_monomial = ""
    is_positive = True

    while i < len(expression):
        if expression[i] == '+':
            # Process the previous monomial
            if current_monomial:
                if is_positive:
                    add_monomial(current_monomial, 1, monomials)
                else:
                    add_monomial(current_monomial, -1, monomials)
            current_monomial = ""
            is_positive = True
        elif expression[i] == '-':
            # Process the previous monomial
            if current_monomial:
                if is_positive:
                    add_monomial(current_monomial, 1, monomials)
                else:
                    add_monomial(current_monomial, -1, monomials)
            current_monomial = ""
            is_positive = False
        else:
            current_monomial += expression[i]
        i += 1

    # Process the last monomial
    if current_monomial:
        if is_positive:
            add_monomial(current_monomial, 1, monomials)
        else:
            add_monomial(current_monomial, -1, monomials)

    # Process the monomials to combine like terms
    # This is already done in add_monomial function

    # Now sort and format the result
    # Create list of (normalized_monomial, coefficient) pairs
    result_items = []
    for monomial, coeff in monomials.items():
        if coeff != 0:
            result_items.append((monomial, coeff))

    # Sort by number of variables (degree), then lexicographically
    result_items.sort(key=lambda x: (len(x[0]), x[0]))

    # Format the result
    if not result_items:
        return ""

    result = []
    for i, (monomial, coeff) in enumerate(result_items):
        if coeff == 1 and i > 0:
            result.append("+" + monomial)
        elif coeff == -1 and i > 0:
            result.append("-" + monomial)
        elif coeff > 0 and i > 0:
            result.append("+" + str(coeff) + monomial)
        elif coeff < 0 and i > 0:
            result.append("-" + str(-coeff) + monomial)
        elif coeff > 0:
            result.append(str(coeff) + monomial)
        else:  # coeff < 0
            result.append("-" + str(-coeff) + monomial)

    return "".join(result)

def add_monomial(monomial_str, coefficient, monomials):
    # Extract coefficient and variables
    # If monomial_str starts with a number, that's the coefficient
    # Otherwise coefficient is 1 or -1 (depending on sign)

    # Find where the coefficient part ends
    i = 0
    while i < len(monomial_str) and (monomial_str[i].isdigit() or monomial_str[i] == '-'):
        i += 1

    if i == 0:
        # No coefficient specified, so it's 1 or -1
        coeff = coefficient
    else:
        # Extract coefficient
        coeff_str = monomial_str[:i]
        if coeff_str == "-":
            coeff = -1
        else:
            coeff = int(coeff_str)
        coefficient = coeff * coefficient

    # Get the variable part
    var_part = monomial_str[i:]

    # Normalize the variable part (sort letters)
    normalized_var = ''.join(sorted(var_part))

    # Add to dictionary
    if normalized_var in monomials:
        monomials[normalized_var] += coefficient
    else:
        monomials[normalized_var] = coefficient

