def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False

        # Check odd divisors up to sqrt(num)
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    if is_prime(n):
        return x
    else:
        return y

def sum_array(arr):
    # Check for None, empty, or single element array
    if arr is None or len(arr) <= 1:
        return 0

    # Calculate sum of all elements, then subtract min and max
    return sum(arr) - min(arr) - max(arr)

def poohbear(code):
    # Initialize memory as a dictionary for infinite cells in both directions
    memory = {}
    pointer = 0
    copy_register = 0
    output = []

    # Pre-process to find W-E pairs
    w_e_pairs = {}
    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                start = stack.pop()
                w_e_pairs[start] = i
                w_e_pairs[i] = start

    instruction_ptr = 0
    while instruction_ptr < len(code):
        cmd = code[instruction_ptr]

        # Ignore non-command characters
        if cmd not in '+-><cpWEPNTQU LIVABYD':
            instruction_ptr += 1
            continue

        # Get current cell value (default 0 if not exists)
        current_cell = memory.get(pointer, 0)

        # Execute command
        if cmd == '+':
            memory[pointer] = (current_cell + 1) % 256
        elif cmd == '-':
            memory[pointer] = (current_cell - 1) % 256
        elif cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == 'c':
            copy_register = current_cell
        elif cmd == 'p':
            memory[pointer] = copy_register
        elif cmd == 'W':
            if current_cell == 0:
                instruction_ptr = w_e_pairs.get(instruction_ptr)
                continue  # Jump to E, process it next iteration
            else:
                instruction_ptr += 1
        elif cmd == 'E':
            if current_cell != 0:
                instruction_ptr = w_e_pairs.get(instruction_ptr)
                continue  # Jump to W, process it next iteration
            else:
                instruction_ptr += 1
        elif cmd == 'P':
            output.append(chr(current_cell))
        elif cmd == 'N':
            output.append(str(current_cell))
        elif cmd == 'T':
            memory[pointer] = (current_cell * 2) % 256
        elif cmd == 'Q':
            memory[pointer] = (current_cell ** 2) % 256
        elif cmd == 'U':
            memory[pointer] = int(current_cell ** 0.5) % 256
        elif cmd == 'L':
            memory[pointer] = (current_cell + 2) % 256
        elif cmd == 'I':
            memory[pointer] = (current_cell - 2) % 256
        elif cmd == 'V':
            memory[pointer] = (current_cell // 2) % 256
        elif cmd == 'A':
            memory[pointer] = (current_cell + copy_register) % 256
        elif cmd == 'B':
            memory[pointer] = (current_cell - copy_register) % 256
        elif cmd == 'Y':
            memory[pointer] = (current_cell * copy_register) % 256
        elif cmd == 'D':
            if copy_register != 0:
                memory[pointer] = (current_cell // copy_register) % 256
            # Division by zero: do nothing

        instruction_ptr += 1

    return ''.join(output)

def proper_fractions(n):
    if n == 1:
        return 0

    result = n

    # Check for factor 2
    if n % 2 == 0:
        result -= result // 2
        while n % 2 == 0:
            n //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result -= result // i
            while n % i == 0:
                n //= i
        i += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        result -= result // n

    return result

def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # Check if n is prime
    if not is_prime(n):
        return False

    # Compute 2^n - 1
    mersenne_number = (1 << n) - 1  # This is 2^n - 1

    # Check if the Mersenne number is prime
    return is_prime(mersenne_number)

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None
    return hashlib.md5(text.encode('utf-8')).hexdigest()

def exchange_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                arr[i], arr[j] = arr[j], arr[i]
    return arr

def histogram(test):
    if not test:
        return {}

    # Split the string and count occurrences of each letter
    letters = test.split()
    count_dict = {}

    for letter in letters:
        count_dict[letter] = count_dict.get(letter, 0) + 1

    # Find the maximum frequency
    max_count = max(count_dict.values())

    # Return all letters with maximum frequency
    return {letter: count for letter, count in count_dict.items() if count == max_count}

def fib4(n: int):
    if n == 0 or n == 1 or n == 3:
        return 0
    elif n == 2:
        return 2

    # Initialize the first four values
    a, b, c, d = 0, 0, 2, 0  # fib4(0), fib4(1), fib4(2), fib4(3)

    # Iterate from fib4(4) to fib4(n)
    for i in range(4, n + 1):
        next_val = a + b + c + d
        # Shift the window: move each value one position left
        a, b, c, d = b, c, d, next_val

    return d

def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    even_count = 0
    odd_count = 0

    for num in range(1, n + 1):
        # Check if the number is a palindrome
        if str(num) == str(num)[::-1]:
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        return (int(pos[1]) - 1, ord(pos[0]) - ord('a'))

    def is_on_board(row, col):
        return 0 <= row < 8 and 0 <= col < 8

    def is_adjacent(row1, col1, row2, col2):
        return abs(row1 - row2) <= 1 and abs(col1 - col2) <= 1

    def is_attacked(row, col, wkr, wkc, ar, ac):
        # Check queen-like moves (rook + bishop)
        # Horizontal and vertical
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            r, c = row + dr, col + dc
            while is_on_board(r, c):
                if r == ar and c == ac:
                    break
                if r == wkr and c == wkc:
                    break
                if r == wkr and c == wkc:
                    break
                r += dr
                c += dc
            else:
                continue
            return True

        # Diagonal
        for dr, dc in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
            r, c = row + dr, col + dc
            while is_on_board(r, c):
                if r == ar and c == ac:
                    break
                if r == wkr and c == wkc:
                    break
                r += dr
                c += dc
            else:
                continue
            return True

        # Check knight-like moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dr, dc in knight_moves:
            r, c = row + dr, col + dc
            if is_on_board(r, c) and r == ar and c == ac:
                return True

        return False

    def count_valid_moves(br, bc, wkr, wkc, ar, ac):
        count = 0
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = br + dr, bc + dc
                if (is_on_board(nr, nc) and 
                    not (nr == wkr and nc == wkc) and 
                    not (nr == ar and nc == ac) and
                    not is_adjacent(nr, nc, wkr, wkc) and
                    not is_attacked(nr, nc, wkr, wkc, ar, ac)):
                    count += 1
        return count

    # Convert positions to coordinates
    wkr, wkc = chess_to_coords(king)
    ar, ac = chess_to_coords(amazon)

    # Initialize counters
    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    # Check all possible black king positions
    for br in range(8):
        for bc in range(8):
            # Skip if position is occupied by white king or amazon
            if (br == wkr and bc == wkc) or (br == ar and bc == ac):
                continue

            # Skip if adjacent to white king
            if is_adjacent(br, bc, wkr, wkc):
                continue

            # Check if black king is under attack
            under_attack = is_attacked(br, bc, wkr, wkc, ar, ac)

            # Count valid escape moves
            escape_moves = count_valid_moves(br, bc, wkr, wkc, ar, ac)

            # Classify position
            if under_attack and escape_moves == 0:
                checkmate += 1
            elif under_attack and escape_moves > 0:
                check += 1
            elif not under_attack and escape_moves == 0:
                stalemate += 1
            elif not under_attack and escape_moves > 0:
                safe += 1

    return [checkmate, check, stalemate, safe]

def count_divisors(n):
    if n <= 0:
        return 0

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1

    return count

def sum_of_a_beach(s):
    s_lower = s.lower()
    target_words = ["sand", "water", "fish", "sun"]
    count = 0
    i = 0

    while i < len(s_lower):
        for word in target_words:
            if s_lower[i:i+len(word)] == word:
                count += 1
                i += len(word)
                break
        else:
            i += 1

    return count

def greatest_common_divisor(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> greatest_common_divisor(3, 5)
    1
    >>> greatest_common_divisor(25, 15)
    5
    """
    # Handle edge cases
    if a == 0:
        return b
    if b == 0:
        return a

    # Use Euclidean algorithm
    while b != 0:
        a, b = b, a % b

    return abs(a)

from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    result = []

    if not paren_string:
        return result

    groups = paren_string.split()

    for group in groups:
        current_depth = 0
        max_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

def parse_int(s: str) -> int:
    units = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    teens = {
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17,
        'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    scales = {
        'hundred': 100,
        'thousand': 1000,
        'million': 1000000
    }

    # Split by whitespace, then by hyphens for compound numbers
    words = []
    for word in s.split():
        words.extend(word.split('-'))

    current_total = 0
    final_total = 0

    for word in words:
        word = word.lower()

        # Skip "and"
        if word == 'and':
            continue

        # Check for scale words
        if word in scales:
            if scales[word] == 100:  # hundred
                current_total *= 100
            else:  # thousand or million
                current_total *= scales[word]
                final_total += current_total
                current_total = 0
        elif word in units:
            current_total += units[word]
        elif word in teens:
            current_total += teens[word]
        elif word in tens:
            current_total += tens[word]

    final_total += current_total

    return final_total

def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) <= 1:
        return True

    is_increasing = None

    for i in range(1, len(l)):
        if l[i] > l[i-1]:
            if is_increasing is False:
                return False
            is_increasing = True
        elif l[i] < l[i-1]:
            if is_increasing is True:
                return False
            is_increasing = False
        # If l[i] == l[i-1], we continue without changing the trend

    return True

def amazon_check_mate(king: str, amazon: str):
    def parse_pos(pos):
        file = ord(pos[0]) - ord('a')
        rank = int(pos[1]) - 1
        return (file, rank)

    wk = parse_pos(king)
    am = parse_pos(amazon)

    def is_valid_bk_position(pos):
        """Check if a position is valid for black king (not same as wk/am, not adjacent to wk)"""
        if pos == wk or pos == am:
            return False
        if abs(pos[0] - wk[0]) <= 1 and abs(pos[1] - wk[1]) <= 1:
            return False
        return True

    def is_on_board(pos):
        return 0 <= pos[0] <= 7 and 0 <= pos[1] <= 7

    def is_attacked_by_amazon(pos):
        """Check if position is under amazon's attack (queen + knight moves)"""
        if pos == am:
            return False

        # Queen moves: same file, rank, or diagonal
        # Same file (column)
        if pos[0] == am[0] and pos[1] != am[1]:
            min_r = min(pos[1], am[1]) + 1
            max_r = max(pos[1], am[1])
            blocked = False
            for r in range(min_r, max_r):
                if (pos[0], r) == wk:
                    blocked = True
                    break
            if not blocked:
                return True

        # Same rank (row)
        if pos[1] == am[1] and pos[0] != am[0]:
            min_f = min(pos[0], am[0]) + 1
            max_f = max(pos[0], am[0])
            blocked = False
            for f in range(min_f, max_f):
                if (f, pos[1]) == wk:
                    blocked = True
                    break
            if not blocked:
                return True

        # Diagonal
        if abs(pos[0] - am[0]) == abs(pos[1] - am[1]) and pos != am:
            df = 1 if pos[0] > am[0] else -1
            dr = 1 if pos[1] > am[1] else -1
            f, r = am[0] + df, am[1] + dr
            blocked = False
            while (f, r) != (pos[0], pos[1]):
                if (f, r) == wk:
                    blocked = True
                    break
                f += df
                r += dr
            if not blocked:
                return True

        # Knight moves
        dx = abs(pos[0] - am[0])
        dy = abs(pos[1] - am[1])
        return (dx == 2 and dy == 1) or (dx == 1 and dy == 2)

    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    for f in range(8):
        for r in range(8):
            bk = (f, r)
            if not is_valid_bk_position(bk):
                continue

            under_attack = is_attacked_by_amazon(bk)

            if under_attack:
                can_escape = False
                for df in range(-1, 2):
                    for dr in range(-1, 2):
                        if df == 0 and dr == 0:
                            continue
                        escape = (bk[0] + df, bk[1] + dr)
                        if is_valid_bk_position(escape) and not is_attacked_by_amazon(escape):
                            can_escape = True
                            break
                    if can_escape:
                        break

                if not can_escape:
                    checkmate += 1
                else:
                    check += 1
            else:
                has_valid_move = False
                for df in range(-1, 2):
                    for dr in range(-1, 2):
                        if df == 0 and dr == 0:
                            continue
                        move = (bk[0] + df, bk[1] + dr)
                        if is_valid_bk_position(move):
                            has_valid_move = True
                            break
                    if has_valid_move:
                        break

                if not has_valid_move:
                    stalemate += 1
                else:
                    safe += 1

    return [checkmate, check, stalemate, safe]

def even_odd_palindrome(n):
    def is_palindrome(num):
        s = str(num)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def solution(s: str) -> bool:
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
        else:
            # If there are any other characters, the string is invalid per problem constraints
            return False

    return not stack

def get_closest_vowel(word):
    if len(word) < 3:
        return ""

    vowels = set('aeiouAEIOU')

    # Iterate from right to left, excluding the last character
    for i in range(len(word) - 2, 0, -1):
        # Check if current character is a vowel
        if word[i] in vowels:
            # Check if left neighbor is a consonant
            if word[i-1] not in vowels:
                # Check if right neighbor is a consonant
                if word[i+1] not in vowels:
                    return word[i]

    return ""

def is_balanced(input_string, pairs):
    stack = []
    # Create a mapping from closing characters to opening characters
    # and a set of opening characters
    opening_chars = set()
    closing_to_opening = {}

    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        opening_chars.add(open_char)
        closing_to_opening[close_char] = open_char

    for char in input_string:
        # If it's an opening character, push to stack
        if char in opening_chars:
            stack.append(char)
        # If it's a closing character
        elif char in closing_to_opening:
            # If stack is empty or the top doesn't match, it's unbalanced
            if not stack or stack[-1] != closing_to_opening[char]:
                return False
            stack.pop()

    # If stack is empty, all brackets were matched
    return len(stack) == 0

def choose(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry property to minimize computation
    k = min(k, n - k)

    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

def reverse_delete(s, c):
    chars_to_remove = set(c)
    result_string = "".join([char for char in s if char not in chars_to_remove])
    is_palindrome = result_string == result_string[::-1]
    return (result_string, is_palindrome)

def count_up_to(n, divisor=None):
    if divisor is None:
        return n if n >= 1 else 0
    return n // divisor if n >= 1 else 0

def palindrome(num):
    if not isinstance(num, int) or isinstance(num, bool) or num < 0:
        return "Not valid"

    num_str = str(num)
    return num_str == num_str[::-1]

def solution(input_string, comment_markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Initialize with the length of the line (no marker found means keep entire line)
        min_index = len(line)

        # Find the earliest occurrence of any comment marker
        for marker in comment_markers:
            index = line.find(marker)
            if index != -1 and index < min_index:
                min_index = index

        # Truncate at the first comment marker and strip trailing whitespace
        truncated_line = line[:min_index].rstrip()
        result_lines.append(truncated_line)

    return '\n'.join(result_lines)

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        (31536000, "year"),
        (86400, "day"),
        (3600, "hour"),
        (60, "minute"),
        (1, "second")
    ]

    # Calculate components
    components = []
    for unit_seconds, unit_name in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            if count > 1:
                components.append(f"{count} {unit_name}s")
            else:
                components.append(f"{count} {unit_name}")

    # Format the result
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

def max_element(seq):
        iterator = iter(seq)
        try:
            maximum = next(iterator)
        except StopIteration:
            raise ValueError("max_element() arg is an empty sequence")

        for item in iterator:
            if item > maximum:
                maximum = item
        return maximum

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
integers that are prime numbers and less than n.
for example:
count_up_to(5) => [2,3]
count_up_to(11) => [2,3,5,7]
count_up_to(0) => []
count_up_to(20) => [2,3,5,7,11,13,17,19]
count_up_to(1) => []
count_up_to(18) => [2,3,5,7,11,13,17]
"""
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    result = []
    for i in range(2, n):
        if is_prime(i):
            result.append(i)

    return result

def greatest_common_divisor(a, b):
    while b:
        a, b = b, a % b
    return abs(a)

def amazon_check_mate(king, amazon):
