            if is_adjacent(col, row, wk_col, wk_row):
                continue
            # Skip amazon's position
            if (col, row) == (am_col, am_row):
                continue

            # Check if threatened by amazon
            is_threatened = (col, row) in threatened

            # Check for any valid moves from this position
            has_valid_move = False
            for dc in range(-1, 2):
                for dr in range(-1, 2):
                    if dc == 0 and dr == 0:
                        continue
                    nc = col + dc
                    nr = row + dr
                    if is_valid(nc, nr):
                        if (nc, nr) == (wk_col, wk_row):
                            continue
                        if (nc, nr) == (am_col, am_row):
                            continue
                        if is_adjacent(nc, nr, wk_col, wk_row):
                            continue
                        if (nc, nr) in threatened:
                            continue
                        has_valid_move = True
                        break
                if has_valid_move:
                    break

            if is_threatened:
                if has_valid_move:
                    check += 1
                else:
                    checkmate += 1
            else:
                if has_valid_move:
                    safe_with_moves += 1
                else:
                    stalemate += 1

    return [checkmate, check, stalemate, safe_with_moves]

def decode_shift(s: str):
