        take_min = not take_min

    return result

def parse_int(s):
    # Define word values for numbers
    units = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    teens = {
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16,
        'seventeen': 17, 'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    # Combine all numeric word values
    num_words = {**units, **teens, **tens}

    # Tokenize the input string
    tokens = s.lower().split()

    total = 0
    current = 0

    for token in tokens:
        if token == 'and':
            # Skip the word "and" (optional in input)
            continue

        # Handle hyphenated words like "twenty-four"
        if '-' in token:
            parts = token.split('-')
            tens_val = num_words.get(parts[0], 0)
            units_val = num_words.get(parts[1], 0)
            current += tens_val + units_val
            continue

        if token in num_words:
            # Add the value of the word to current segment
            current += num_words[token]
        elif token == 'hundred':
            # Multiply current segment by 100
            current *= 100
        elif token == 'thousand':
            # Finalize the current segment (multiply by 1000) and add to total
            total += current * 1000
            current = 0

    # Add any remaining current value to total
    total += current

    return total

def median(l: list):
    """Return median of elements in the list l."""
    sorted_l = sorted(l)
    n = len(sorted_l)

    if n == 0:
        raise ValueError("Cannot calculate median of empty list")

    mid = n // 2
    if n % 2 == 1:
        return sorted_l[mid]
    else:
        return (sorted_l[mid - 1] + sorted_l[mid]) / 2

def automorphic(n):
