from typing import List, Tuple
import ast

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """

    # Handle string representation of list by parsing it
    if isinstance(numbers, str):
        try:
            numbers = ast.literal_eval(numbers)
        except (ValueError, SyntaxError):
            raise TypeError("Input must be a list of integers or a string representation of a list")

    # Validate that input is a list
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list of integers")

    # Validate all elements are integers (excluding booleans)
    for i, num in enumerate(numbers):
        if isinstance(num, bool) or not isinstance(num, int):
            raise TypeError(f"All elements must be integers, got {type(num)} at index {i}")

    # Handle empty list case
    if len(numbers) == 0:
        return (0, 1)

    # Compute sum and product
    total_sum = sum(numbers)
    total_product = 1
    for num in numbers:
        total_product *= num

    return (total_sum, total_product)

