def decimal_to_binary(decimal):
    if decimal == 0:
        return "db0db"

    binary_digits = []
    while decimal > 0:
        binary_digits.append(str(decimal % 2))
        decimal //= 2

    # Reverse the list to get the correct binary representation
    binary_string = ''.join(reversed(binary_digits))
    return f"db{binary_string}db"

def valid_mersenne(n):
    """
    Determines if a given number n is a Mersenne prime.
    A Mersenne prime is a prime number that can be written in the form 2^p - 1, where p is also a prime number.
    """
    if n < 3:  # Smallest Mersenne prime is 3 (2^2 - 1)
        return False

    # Check if n+1 is a power of 2
    m = n + 1
    if m <= 0 or (m & (m - 1)) != 0:
        return False

    # Find p such that 2^p = m
    p = 0
    temp = m
    while temp > 1:
        temp >>= 1
        p += 1

    # Check if p is prime
    if p < 2:
        return False
    if p == 2:
        return True
    if p % 2 == 0:
        return False

    i = 3
    while i * i <= p:
        if p % i == 0:
            return False
        i += 2

    return True

def choose(n, k):
    # Handle edge cases
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry property to minimize iterations
    if k > n // 2:
        k = n - k

    # Compute C(n, k) iteratively using multiplicative formula
    # C(n, k) = product from i=1 to k of (n - i + 1) / i
    result = 1
    for i in range(1, k + 1):
        result = result * (n - i + 1) // i

    return result

