def simplify(expression):
    from collections import defaultdict

    # Step 1: Split the expression into terms
    terms = []
    i = 0
    while i < len(expression):
        # Skip + or - at the start
        term_start = i
        while i < len(expression) and expression[i] not in '+-':
            i += 1
        if i > term_start:
            terms.append(expression[term_start:i])
        if i < len(expression) and expression[i] in '+-':
            i += 1

    # Step 2-3: Parse and normalize each term
    term_dict = defaultdict(int)

    for term in terms:
        # Handle sign
        start = 0
        if term[0] == '+':
            start = 1
        elif term[0] == '-':
            sign = -1
            start = 1
        else:
            sign = 1

        # Find where coefficient ends and variables begin
        coeff_start = start
        coeff_end = start
        while coeff_end < len(term) and term[coeff_end].isdigit():
            coeff_end += 1

        # Extract coefficient (default to 1 if not specified)
        if coeff_end == coeff_start:
            coeff = 1
        else:
            coeff = int(term[coeff_start:coeff_end])

        coeff *= sign

        # Extract and sort variables
        vars_str = term[coeff_end:]
        sorted_vars = ''.join(sorted(vars_str))

        # Aggregate
        term_dict[sorted_vars] += coeff

    # Remove zero coefficients
    term_dict = {k: v for k, v in term_dict.items() if v != 0}

    # Step 4: Sort terms by length, then lexicographically
    sorted_terms = sorted(term_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Step 5: Format output
    result = []
    for idx, (vars_str, coeff) in enumerate(sorted_terms):
        if idx == 0:
            # First term: no leading + for positive
            if coeff == 1:
                result.append(vars_str)
            elif coeff == -1:
                result.append('-' + vars_str)
            else:
                result.append(str(coeff) + vars_str)
        else:
            # Subsequent terms: add + or - as separator
            if coeff > 0:
                if coeff == 1:
                    result.append('+' + vars_str)
                else:
                    result.append('+' + str(coeff) + vars_str)
            else:
                # coeff < 0
                if coeff == -1:
                    result.append('-' + vars_str)
                else:
                    result.append(str(coeff) + vars_str)

    return ''.join(result)

