def solution(input_string, comment_markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the earliest comment marker position
        min_pos = len(line)
        for marker in comment_markers:
            pos = line.find(marker)
            if pos != -1 and pos < min_pos:
                min_pos = pos

        # If we found a comment marker, truncate the line
        if min_pos < len(line):
            line = line[:min_pos]

        # Strip trailing whitespace
        line = line.rstrip()
        result_lines.append(line)

    return '\n'.join(result_lines)

def proper_fractions(d):
    if d == 1:
        return 0

    result = d

    # Check for factor 2
    if d % 2 == 0:
        result -= result // 2
        while d % 2 == 0:
            d //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= d:
        if d % i == 0:
            result -= result // i
            while d % i == 0:
                d //= i
        i += 2

    # If d is still greater than 1, then it's a prime factor
    if d > 1:
        result -= result // d

    return result

