import re

def differentiate(polynomial, x):
    # Split polynomial into terms
    terms = re.split(r'(?=[+-])', polynomial)
    terms = [term for term in terms if term]  # Remove empty strings

    derivative_terms = []

    for term in terms:
        # Handle the sign
        if term.startswith('+'):
            term = term[1:]
        elif term.startswith('-'):
            term = term[1:]
            sign = -1
        else:
            sign = 1

        # Parse the term
        if 'x^' in term:
            # Format: coefficient*x^exponent
            parts = term.split('x^')
            coeff_str = parts[0]
            exp_str = parts[1]

            if coeff_str == '':
                coeff = 1 * sign
            else:
                coeff = int(coeff_str) * sign

            exp = int(exp_str)

            # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
            if exp == 0:
                continue  # Derivative of constant is 0
            else:
                new_coeff = coeff * exp
                new_exp = exp - 1
                if new_exp == 0:
                    derivative_terms.append(str(new_coeff))
                elif new_exp == 1:
                    derivative_terms.append(f"{new_coeff}x")
                else:
                    derivative_terms.append(f"{new_coeff}x^{new_exp}")

        elif 'x' in term:
            # Format: coefficient*x or x
            if term == 'x':
                coeff = 1 * sign
                exp = 1
            else:
                coeff_str = term.split('x')[0]
                if coeff_str == '+':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str) * sign
                exp = 1

            # Apply power rule
            if exp == 0:
                continue  # Derivative of constant is 0
            else:
                new_coeff = coeff * exp
                new_exp = exp - 1
                if new_exp == 0:
                    derivative_terms.append(str(new_coeff))
                elif new_exp == 1:
                    derivative_terms.append(f"{new_coeff}x")
                else:
                    derivative_terms.append(f"{new_coeff}x^{new_exp}")

        else:
            # Format: constant
            if term:
                coeff = int(term) * sign
                # Derivative of constant is 0, so we skip this term
                continue

    # Handle the case where all terms were constants
    if not derivative_terms:
        return 0

    # Build derivative expression string
    derivative_expr = derivative_terms[0]
    for i in range(1, len(derivative_terms)):
        if derivative_terms[i].startswith('-'):
            derivative_expr += f" - {derivative_terms[i][1:]}"
        else:
            derivative_expr += f" + {derivative_terms[i]}"

    # Evaluate the derivative at x
    # Replace x with the value and evaluate
    result = 0
    for term in derivative_terms:
        if 'x' in term:
            if term == 'x':
                result += x
            elif term == '-x':
                result -= x
            else:
                # Extract coefficient and power
                if term.startswith('-'):
                    coeff_str = term[1:].split('x')[0]
                    coeff = -int(coeff_str)
                else:
                    coeff_str = term.split('x')[0]
                    coeff = int(coeff_str)

                # Check if there's an exponent
                if '^' in term:
                    exp = int(term.split('^')[1])
                    result += coeff * (x ** exp)
                else:
                    result += coeff * x
        else:
            # Constant term
            result += int(term)

    return result

import re

def differentiate(poly, x):
    if not poly:
        return 0

    # Normalize: ensure polynomial starts with + or -
    if not poly.startswith('-') and not poly.startswith('+'):
        poly = '+' + poly

    # Extract all terms with their signs
    terms = re.findall(r'([+-])([^\+\-]+)', poly)

    result = 0

    for sign, term in terms:
        # Parse coefficient and exponent from the term
        if 'x^' in term:
            # Term has explicit exponent like "3x^2" or "x^2"
            x_index = term.index('x')
            exp_index = term.index('^', x_index)
            coeff_str = term[:x_index]
            exponent = int(term[exp_index + 1:])
            if coeff_str == '':
                coeff = 1
            else:
                coeff = int(coeff_str)
        elif 'x' in term:
            # Term has x but no exponent like "3x" or "x"
            x_index = term.index('x')
            coeff_str = term[:x_index]
            exponent = 1
            if coeff_str == '':
                coeff = 1
            else:
                coeff = int(coeff_str)
        else:
            # Constant term like "5" or "12"
            coeff = int(term)
            exponent = 0

        # Apply sign
        if sign == '-':
            coeff = -coeff

        # Differentiate: d/dx (coeff * x^exponent) = coeff * exponent * x^(exponent-1)
        if exponent > 0:
            result += coeff * exponent * (x ** (exponent - 1))

    return result

