def getAllPrimeFactors(n):
    # Error checking
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Special case for 1
    if n == 1:
        return [1]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Error checking
    if not isinstance(n, int):
        return [[], []]
    if n <= 0:
        return [[], []]

    # Special case for 1
    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)
    unique_factors = []
    counts = []

    if not factors:
        return [[], []]

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Error checking
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Special case for 1
    if n == 1:
        return [1]

    unique_factors, counts = getUniquePrimeFactorsWithCount(n)
    products = []

    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

def is_balanced(s, pairs):
    # Create a mapping from opening to closing characters and vice versa
    pair_map = {}
    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        pair_map[open_char] = close_char
        pair_map[close_char] = open_char

    # Stack to track open characters
    stack = []

    for char in s:
        # If it's an opening character, push it onto the stack
        if char in pair_map and char in pair_map and pair_map[char] != char:
            # This is an opening character
            stack.append(char)
        # If it's a closing character
        elif char in pair_map and char in pair_map and pair_map[char] == char:
            # This is a self-closing character (like ')
            if not stack or stack[-1] != char:
                return False
            stack.pop()
        elif char in pair_map:
            # This is a closing character
            if not stack or pair_map[char] != stack[-1]:
                return False
            stack.pop()

    # If stack is empty, all characters were properly closed
    return len(stack) == 0

def median(l: list):
    sorted_l = sorted(l)
    n = len(sorted_l)
    if n == 0:
        raise ValueError("Cannot compute median of empty list")
    if n % 2 == 1:
        return sorted_l[n // 2]
    else:
        return (sorted_l[n // 2 - 1] + sorted_l[n // 2]) / 2

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_digits = []
    else:
        digits = []
        temp = integer_part
        power = 0
        # Find the highest power needed
        while base ** power <= temp:
            power += 1
        power -= 1

        # Extract digits from highest power down
        while power >= 0:
            if base ** power <= temp:
                digit = int(temp // (base ** power))
                digits.append(digit)
                temp -= digit * (base ** power)
            else:
                digits.append(0)
            power -= 1

        integer_digits = digits

    # Convert fractional part
    fractional_digits = []
    if decimals > 0:
        temp_fraction = fractional_part
        for _ in range(decimals):
            temp_fraction *= base
            digit = int(temp_fraction)
            fractional_digits.append(digit)
            temp_fraction -= digit

    # Convert digits to characters
    def digit_to_char(digit):
        if digit < 10:
            return str(digit)
        else:
            return chr(ord('A') + digit - 10)

    integer_str = ''.join(digit_to_char(d) for d in integer_digits)

    if decimals == 0:
        result = integer_str
    else:
        fractional_str = ''.join(digit_to_char(d) for d in fractional_digits)
        result = integer_str + '.' + fractional_str

    if negative:
        result = '-' + result

    # Handle special case where result is less than 1
    if not negative and number < 1 and decimals == 0:
        # This case shouldn't happen with our algorithm, but just in case
        pass

    return result

