def exchange_sort(sequence):
    if len(sequence) <= 1:
        return 0

    # Create target sorted sequence
    target = sorted(sequence)

    # Create a mapping from value to its target positions
    value_positions = {7: [], 8: [], 9: []}
    for i, val in enumerate(target):
        value_positions[val].append(i)

    # Create position mapping: where each element should go
    position_map = {}
    for val in [7, 8, 9]:
        positions = value_positions[val]
        for i, pos in enumerate(positions):
            position_map[pos] = positions[i] if i < len(positions) else positions[0]

    # Find cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i]:
            # Start a new cycle
            cycle_length = 0
            current = i

            while not visited[current]:
                visited[current] = True
                current = position_map[current]
                cycle_length += 1

            # A cycle of length k requires (k-1) swaps
            if cycle_length > 1:
                cycles += cycle_length - 1

    return cycles

