def exchange_sort(sequence):
    n = len(sequence)
    if n <= 1:
        return 0

    # Create target sorted sequence
    target = []
    count = [0, 0, 0]  # count[0] for 7, count[1] for 8, count[2] for 9

    # Count occurrences
    for val in sequence:
        count[val - 7] += 1

    # Build target sequence
    for i in range(3):
        target.extend([i + 7] * count[i])

    # Create position mapping for target
    pos = {}
    for i, val in enumerate(target):
        if val not in pos:
            pos[val] = []
        pos[val].append(i)

    # Create a mapping from each element to its target position
    element_to_target = {}
    for i, val in enumerate(target):
        if val not in element_to_target:
            element_to_target[val] = []
        element_to_target[val].append(i)

    # Create a mapping from each position in original to target position
    pos_map = [0] * n
    for i in range(n):
        val = sequence[i]
        if element_to_target[val]:
            pos_map[i] = element_to_target[val].pop(0)

    # Count cycles using visited array
    visited = [False] * n
    cycles = 0

    for i in range(n):
        if not visited[i]:
            # Start a new cycle
            cycles += 1
            current = i
            while not visited[current]:
                visited[current] = True
                current = pos_map[current]

    # Minimum swaps = n - cycles
    return n - cycles

def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    n = d

    # Handle factor of 2 separately for efficiency
    if n % 2 == 0:
        result = result // 2 * 1
        while n % 2 == 0:
            n //= 2

    # Check odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result = result // i * (i - 1)
            while n % i == 0:
                n //= i
        i += 2

    # If n > 1, then n is a remaining prime factor
    if n > 1:
        result = result // n * (n - 1)

    return result

