        if pos_map[num]:  # If there are still positions available for this number
            target_pos = pos_map[num].pop(0)
            current_to_target[i] = target_pos

    # Find cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i] and i in current_to_target:
            # Start a new cycle
            cycle_length = 0
            current = i

            while not visited[current]:
                visited[current] = True
                current = current_to_target[current]
                cycle_length += 1

            if cycle_length > 1:
                cycles += cycle_length - 1

    return cycles

