def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into terms
    # Split by + and - signs, but keep the signs
    terms = re.findall(r'[+-]?[^+-]+', expression)

    # Dictionary to store normalized monomials and their coefficients
    monomial_dict = defaultdict(int)

    for term in terms:
        # Handle the sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Parse the coefficient and monomial part
        if term == '':
            continue

        # Check if there's a coefficient
        coeff_str = ''
        i = 0
        while i < len(term) and term[i].isdigit():
            coeff_str += term[i]
            i += 1

        if coeff_str == '':
            coeff = sign * 1
        else:
            coeff = sign * int(coeff_str)

        # Get the variable part
        var_part = term[i:]

        # Normalize the variable part by sorting characters
        normalized = ''.join(sorted(var_part))

        # Add to dictionary
        monomial_dict[normalized] += coeff

    # Remove zero coefficients
    monomial_dict = {k: v for k, v in monomial_dict.items() if v != 0}

    # Sort by number of variables and then lexicographically
    sorted_items = sorted(monomial_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Format the result
    result_parts = []
    first = True

    for monomial, coeff in sorted_items:
        if coeff == 0:
            continue

        # Handle the coefficient
        if coeff == 1 and not first:
            coeff_str = '+'
        elif coeff == -1 and not first:
            coeff_str = '-'
        elif coeff == 1 and first:
            coeff_str = ''
        elif coeff == -1 and first:
            coeff_str = '-'
        else:
            coeff_str = str(coeff)

        # Add the term
        if monomial == '':
            term_str = coeff_str
        else:
            term_str = coeff_str + monomial

        # Special case for first term when coefficient is 1 or -1
        if first and (coeff == 1 or coeff == -1):
            if coeff == 1:
                result_parts.append(monomial)
            else:
                result_parts.append('-' + monomial)
        else:
            result_parts.append(term_str)

        first = False

    # Join parts
    if not result_parts:
        return "0"

    result = result_parts[0]
    for part in result_parts[1:]:
        if part.startswith('-'):
            result += ' - ' + part[1:]
        else:
            result += ' + ' + part

    return result

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 365 * 24 * 60 * 60),
        ('day', 24 * 60 * 60),
        ('hour', 60 * 60),
        ('minute', 60),
        ('second', 1)
    ]

    # Calculate each unit
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            if count > 1:
                components.append(f"{count} {unit_name}s")
            else:
                components.append(f"{count} {unit_name}")

    # Format the output
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

