import math

def converter(number, decimals=0, base=math.pi):
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36")

    if decimals < 0:
        raise ValueError("Decimals must be non-negative")

    # Handle special case of zero
    if number == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Handle negative numbers
    is_negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    digits = []

    if integer_part == 0:
        digits = ['0']
    else:
        while integer_part > 0:
            remainder = integer_part % base
            # Handle floating point precision issues
            if remainder >= base:
                remainder = base - 1e-10
            elif remainder < 0:
                remainder = 0
            digits.append(remainder)
            integer_part = int((integer_part - remainder) / base)

    # Convert fractional part
    fractional_part = number - int(number)
    fractional_digits = []

    if fractional_part > 0 and decimals > 0:
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            # Handle floating point precision issues
            if digit >= base:
                digit = int(base - 1e-10)
            fractional_digits.append(digit)
            fractional_part -= digit

    # Build result string
    # Convert digits to proper character representation
    digit_chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

    # Process integer part digits (they're in reverse order)
    integer_result = ''
    for i in range(len(digits) - 1, -1, -1):
        integer_result += digit_chars[int(digits[i])]

    # Handle fractional part
    if decimals > 0 and fractional_digits:
        fractional_result = ''
        for digit in fractional_digits:
            fractional_result += digit_chars[digit]
        result = integer_result + '.' + fractional_result
    elif decimals == 0:
        result = integer_result
    else:
        result = integer_result

    # Handle leading zero for numbers < 1
    if number < 1 and decimals == 0:
        result = '0' + result
    elif number < 1 and decimals > 0:
        # If the integer part was 0 and we have fractional part, we still need leading 0
        if result[0] != '0':
            result = '0' + result

    # Handle negative numbers
    if is_negative:
        result = '-' + result

    return result

def differentiate(polynomial, x):
    # Split the polynomial into terms
    # Handle the case where the polynomial starts with a negative term
    if polynomial[0] == '-':
        terms = ['-']
        polynomial = polynomial[1:]
    else:
        terms = []

    # Split by '+' and handle '-' as a separator
    current_term = ""
    for i, char in enumerate(polynomial):
        if char == '+' or char == '-':
            if current_term:
                terms.append(current_term)
            if char == '-':
                current_term = '-'
            else:
                current_term = ''
        else:
            current_term += char
    if current_term:
        terms.append(current_term)

    # Process each term
    derivative_sum = 0

    for term in terms:
        if term == '':
            continue

        # Handle the sign
        if term[0] == '-':
            sign = -1
            term = term[1:]
        else:
            sign = 1

        # Parse the term
        if 'x^' in term:
            # Format: ax^n
            coeff_part, exp_part = term.split('x^')
            coefficient = int(coeff_part) if coeff_part else 1
            exponent = int(exp_part)
        elif 'x' in term:
            # Format: ax or a (where a is the coefficient)
            if term == 'x':
                coefficient = 1
                exponent = 1
            else:
                coeff_part = term[:-1]  # Remove 'x'
                coefficient = int(coeff_part) if coeff_part != '-' else -1
                exponent = 1
        else:
            # Format: constant
            coefficient = int(term)
            exponent = 0

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent == 0:
            # Derivative of a constant is 0
            derivative = 0
        else:
            derivative = coefficient * exponent * (x ** (exponent - 1))

        derivative_sum += sign * derivative

    return derivative_sum

def factorize(n):
    factors = {}
    if n < 2:
        return factors

    # Handle factor of 2
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n //= 2

    # Check odd factors from 3 onwards
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
        i += 2

    # If remaining n is a prime number
    if n > 1:
        factors[n] = factors.get(n, 0) + 1

    return factors

def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    result = []
    for i in range(len(a)):
        # XOR: same bits give 0, different bits give 1
        if a[i] == b[i]:
            result.append('0')
        else:
            result.append('1')
    return ''.join(result)

def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2

    # Handle factor 2
    if d % p == 0:
        while d % p == 0:
            d //= p
        result -= result // p

    # Handle odd factors from 3 onwards
    p = 3
    while p * p <= d:
        if d % p == 0:
            while d % p == 0:
                d //= p
            result -= result // p
        p += 2

    # If remaining d is a prime number greater than 1
    if d > 1:
        result -= result // d

    return result

