def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    if n <= 2:
        return []

    # Use Sieve of Eratosthenes for efficiency
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n, i):
                is_prime[j] = False

    # Collect primes less than n
    primes = []
    for i in range(2, n):
        if is_prime[i]:
            primes.append(i)

    return primes

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """

    def normalize(value):
        """Convert any input to a float for comparison"""
        if isinstance(value, (int, float)):
            return float(value)
        elif isinstance(value, str):
            # Replace comma with dot for decimal separator
            normalized_str = value.replace(',', '.')
            return float(normalized_str)
        else:
            raise TypeError("Unsupported type")

    # Normalize both values for comparison
    norm_a = normalize(a)
    norm_b = normalize(b)

    # Compare normalized values
    if norm_a > norm_b:
        return a
    elif norm_b > norm_a:
        return b
    else:
        return None

def fib4(n):
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Initialize the first four values: fib4(0), fib4(1), fib4(2), fib4(3)
    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute fib4(4) through fib4(n)
    for i in range(4, n + 1):
        next_val = a + b + c + d
        a, b, c, d = b, c, d, next_val

    return d

def sum_of_squares(n):
    # Step 1: Check if n is a perfect square (answer = 1)
    sqrt_n = int(n ** 0.5)
    if sqrt_n * sqrt_n == n:
        return 1

    # Step 2: Check if n can be expressed as sum of two squares (answer = 2)
    for a in range(1, sqrt_n + 1):
        remainder = n - a * a
        if remainder <= 0:
            break
        sqrt_rem = int(remainder ** 0.5)
        if sqrt_rem * sqrt_rem == remainder:
            return 2

    # Step 3: Check Legendre's Three-Square Theorem
    # A number n can be written as sum of 3 squares iff n is NOT of form 4^a * (8b + 7)
    m = n
    while m % 4 == 0:
        m //= 4

    if m % 8 == 7:
        return 4

    # Step 4: Otherwise, answer is 3
    return 3

