def is_balanced(s, pairs):
    # Create a mapping from opening to closing characters
    open_to_close = {}
    close_to_open = {}

    # Populate the mappings
    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        open_to_close[open_char] = close_char
        close_to_open[close_char] = open_char

    # Stack to keep track of opening characters
    stack = []

    # Process each character in the string
    for char in s:
        # If it's an opening character, push it onto the stack
        if char in open_to_close:
            stack.append(char)
        # If it's a closing character
        elif char in close_to_open:
            # If stack is empty, there's no matching opening character
            if not stack:
                return False

            # Pop the last opening character
            last_open = stack.pop()

            # Check if it matches the current closing character
            if open_to_close[last_open] != char:
                return False

    # If stack is empty, all characters were properly matched
    return len(stack) == 0

def pig_latin(word):
    if not word:
        return None

    if not word.isalpha():
        return None

    word = word.lower()

    vowels = "aeiou"

    if word[0] in vowels:
        return word + "way"

    # Find the index where the first vowel occurs
    first_vowel_index = -1
    for i, char in enumerate(word):
        if char in vowels:
            first_vowel_index = i
            break

    # If no vowel found, move all consonants to the end and add "ay"
    if first_vowel_index == -1:
        return word + "ay"

    # Move consonants from the beginning to the end until the first vowel
    consonant_cluster = word[:first_vowel_index]
    rest_of_word = word[first_vowel_index:]

    return rest_of_word + consonant_cluster + "ay"

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [1, -1, 11, -11, -12]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)

