            curr_x = amazon_pos[0] + step_x
            curr_y = amazon_pos[1] + step_y
            blocked = False
            while (curr_x, curr_y) != target_pos:
                if (curr_x, curr_y) == white_king_pos:
                    blocked = True
                    break
                curr_x += step_x
                curr_y += step_y

            if not blocked:
                return True

        # Check knight-like movement
        abs_dx = abs(dx)
        abs_dy = abs(dy)
        if (abs_dx == 1 and abs_dy == 2) or (abs_dx == 2 and abs_dy == 1):
            return True

        return False

    def is_valid_square(pos, white_king_pos, white_amazon_pos):
        # Black king cannot be on white pieces
        if pos == white_king_pos or pos == white_amazon_pos:
            return False
        # Black king cannot be adjacent to white king
        if is_adjacent(pos, white_king_pos):
            return False
        return True

    # Parse input positions
    wk_pos = parse_pos(king)   # white king
    wa_pos = parse_pos(amazon) # white amazon

    checkmate = 0
    check = 0
    stalemate = 0
    safe_with_moves = 0

    # Iterate over all possible black king positions
    for file in range(8):
        for rank in range(8):
            bk_pos = (file, rank)

            # Skip invalid positions for black king
            if not is_valid_square(bk_pos, wk_pos, wa_pos):
                continue

            # Check if black king is under attack
            under_attack = amazon_attacks_pos(wa_pos, bk_pos, wk_pos)

            # Count valid moves from current position
            valid_moves = 0
            for file2 in range(8):
                for rank2 in range(8):
                    move_pos = (file2, rank2)

                    # Must be a legal king move (adjacent)
                    if not is_adjacent(bk_pos, move_pos):
                        continue

                    # Must be a valid square for the king
                    if not is_valid_square(move_pos, wk_pos, wa_pos):
                        continue

                    # Must not be under amazon attack
                    if amazon_attacks_pos(wa_pos, move_pos, wk_pos):
                        continue

                    valid_moves += 1

            # Categorize the position
            if under_attack:
                if valid_moves == 0:
                    checkmate += 1
                else:
                    check += 1
            else:
                if valid_moves == 0:
                    stalemate += 1
                else:
                    safe_with_moves += 1

    return [checkmate, check, stalemate, safe_with_moves]

def candies(arr):
    if len(arr) <= 1:
        return -1

    max_candies = max(arr)
    total_given = 0

    for candy_count in arr:
        total_given += max_candies - candy_count

    return total_given

def order_by_points(nums):
    def get_digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    return sorted(nums, key=lambda x: (get_digit_sum(x), nums.index(x)))

def solution(text, markers):
    # Split the input into lines
    lines = text.split('\n')

    result_lines = []

    for line in lines:
        # Find the first occurrence of any marker
        first_marker_pos = len(line)  # Default: no marker found

        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < first_marker_pos:
                first_marker_pos = pos

        # Truncate line at first marker position (if found)
        if first_marker_pos < len(line):
            line = line[:first_marker_pos]

        # Strip trailing whitespace
        line = line.rstrip()

        result_lines.append(line)

    # Rejoin lines with newline
    return '\n'.join(result_lines)

def sum_of_squares(n):
    # Check if n is a perfect square
    sqrt_n = int(n ** 0.5)
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n can be represented as sum of two squares
    for i in range(1, int(n ** 0.5) + 1):
        remainder = n - i * i
        sqrt_remainder = int(remainder ** 0.5)
        if sqrt_remainder * sqrt_remainder == remainder:
            return 2

    # Check if n is of the form 4^a(8b+7)
    # This requires exactly 4 squares by Legendre's three-square theorem
    while n % 4 == 0:
        n //= 4

    if n % 8 == 7:
        return 4

    # Otherwise, it can be represented as sum of three squares
    return 3

def cycpattern_check(a, b):
    if not b:
        return True
    if not a:
        return False

    # Generate all rotations of b and check if any is a substring of a
    for i in range(len(b)):
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True
    return False

def count_divisors(n):
    if n == 1:
        return 1

    k = int(n**0.5)
    total = 0

    for i in range(1, k + 1):
        total += n // i

    return 2 * total - k * k

from typing import List


def intersperse(numbers: List[int], delimeter: int) -> List[int]:
    if not numbers:
        return []

    result = [numbers[0]]
    for num in numbers[1:]:
        result.append(delimeter)
        result.append(num)

    return result

def count_up_to(n):
    if n <= 2:
        return []

    # Use Sieve of Eratosthenes to find all primes less than n
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n, i):
                is_prime[j] = False

    # Collect the first n primes
    result = []
    for i in range(2, n):
        if is_prime[i]:
            result.append(i)
            if len(result) == n:
                break

    return result

def vowel_indices(word):
    vowels = set('aeiouyAEIOUY')
    result = []

    for i, char in enumerate(word, 1):
        if char in vowels:
            result.append(i)

    return result

def get_closest_vowel(word):
    vowels = set('aeiouAEIOU')

    # Need at least 3 characters to have a vowel between two consonants
    if len(word) < 3:
        return ""

    # Iterate from right to left, checking positions from len-2 down to 1
    # (positions 0 and len-1 are boundaries where vowels don't count)
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            # Check if both adjacent characters are consonants
            left_is_consonant = word[i-1] not in vowels
            right_is_consonant = word[i+1] not in vowels

            if left_is_consonant and right_is_consonant:
                return word[i]

    return ""

def is_balanced(s, pairs):
    if not s:
        return True

    # Build mapping from opening to closing characters
    # Track identical pairs (where opening == closing character)
    opening_to_closing = {}
    closing_chars = set()
    identical_pairs = set()

    for i in range(0, len(pairs), 2):
        if i + 1 >= len(pairs):
            continue  # Skip incomplete pair
        open_char = pairs[i]
        close_char = pairs[i + 1]
        opening_to_closing[open_char] = close_char
        closing_chars.add(close_char)
        if open_char == close_char:
            identical_pairs.add(open_char)

    stack = []

    for char in s:
        if char in identical_pairs:
            # For identical pairs: if char is on stack top, it's a closer; otherwise it's an opener
            if stack and stack[-1] == char:
                stack.pop()
            else:
                stack.append(char)
        elif char in opening_to_closing:
            # Opening character
            stack.append(char)
        elif char in closing_chars:
            # Closing character - must match the most recent opening
            if not stack:
                return False
            if opening_to_closing[stack[-1]] == char:
                stack.pop()
            else:
                return False
        # Other characters are ignored

    return len(stack) == 0

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    if not test:
        return {}

    letters = test.split()
    freq = {}

    for letter in letters:
        freq[letter] = freq.get(letter, 0) + 1

    max_freq = max(freq.values())

    result = {letter: count for letter, count in freq.items() if count == max_freq}

    return result

def is_balanced(content, bracket_pairs):
    # Create a mapping of opening to closing brackets and vice versa
    bracket_map = {}
    for i in range(0, len(bracket_pairs), 2):
        open_bracket = bracket_pairs[i]
        close_bracket = bracket_pairs[i + 1]
        bracket_map[open_bracket] = close_bracket
        # If opening and closing are the same character, it's a dual-role bracket
        if open_bracket == close_bracket:
            if open_bracket in bracket_map:
                # Already exists, which is fine for dual roles
                pass
            else:
                bracket_map[open_bracket] = close_bracket
        else:
            # For different brackets, we need to track both directions
            if close_bracket not in bracket_map:
                bracket_map[close_bracket] = None  # Mark as closing

    # Stack to keep track of opening brackets
    stack = []

    for char in content:
        # If it's an opening bracket
        if char in bracket_map and (bracket_map[char] is not None or char in bracket_map):
            # Check if it's a dual-role bracket (same char for open and close)
            if char in bracket_map and bracket_map[char] == char:
                stack.append(char)
            elif char in bracket_map and bracket_map[char] is not None:
                # Regular opening bracket
                stack.append(char)
        # If it's a closing bracket
        elif char in bracket_map and bracket_map[char] is None:
            # This is a closing bracket that's also an opening bracket (dual role)
            if not stack or stack[-1] != char:
                return False
            stack.pop()
        elif char in bracket_map:
            # Regular closing bracket
            if not stack or bracket_map[stack[-1]] != char:
                return False
            stack.pop()

    # If stack is empty, all brackets were matched
    return len(stack) == 0

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ("year", 365 * 24 * 60 * 60),
        ("day", 24 * 60 * 60),
        ("hour", 60 * 60),
        ("minute", 60),
        ("second", 1)
    ]

    # Calculate each unit
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            if count > 1:
                components.append(f"{count} {unit_name}s")
            else:
                components.append(f"{count} {unit_name}")

    # Format the result
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

def pig_latin(word):
    # Check if the word is empty
    if not word:
        return None

    # Check if all characters are alphabetic
    if not word.isalpha():
        return None

    # Convert to lowercase
    word = word.lower()

    # Check if the word starts with a vowel
    if word[0] in 'aeiou':
        return word + 'way'

    # Find the index where the first vowel occurs
    first_vowel_index = 0
    for i, char in enumerate(word):
        if char in 'aeiou':
            first_vowel_index = i
            break
    else:
        # No vowels found, return original word plus "ay"
        return word + 'ay'

    # Move consonants from the beginning to the end until the first vowel
    return word[first_vowel_index:] + word[:first_vowel_index] + 'ay'

def is_valid(identifier):
    # Check if identifier is empty
    if not identifier:
        return False

    # Check first character
    first_char = identifier[0]
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Check rest of characters
    for char in identifier[1:]:
        if not (char.isalnum() or char == '_' or char == '$'):
            return False

    return True

def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        return (ord(pos[1]) - ord('1'), ord(pos[0]) - ord('a'))

    def is_valid(r, c):
        return 0 <= r < 8 and 0 <= c < 8

    def is_adjacent(br, bc, wr, wc):
        return abs(br - wr) <= 1 and abs(bc - wc) <= 1

    def is_attacked(br, bc, wkr, wkc, ar, ac):
        # Check queen moves (rook + bishop)
        # Horizontal and vertical
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            r, c = br + dr, bc + dc
            while is_valid(r, c):
                if r == ar and c == ac:
                    return True
                if r == wkr and c == wkc:
                    break
                r += dr
                c += dc

        # Diagonal
        for dr, dc in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
            r, c = br + dr, bc + dc
            while is_valid(r, c):
                if r == ar and c == ac:
                    return True
                if r == wkr and c == wkc:
                    break
                r += dr
                c += dc

        # Knight moves
        knight_moves = [(2, 1), (2, -1), (-2, 1), (-2, -1), 
                       (1, 2), (1, -2), (-1, 2), (-1, -2)]
        for dr, dc in knight_moves:
            nr, nc = br + dr, bc + dc
            if is_valid(nr, nc) and nr == ar and nc == ac:
                return True

        return False

    def can_escape(br, bc, wkr, wkc, ar, ac):
        escape_count = 0
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = br + dr, bc + dc
                if (is_valid(nr, nc) and 
                    not (nr == wkr and nc == wkc) and 
                    not is_adjacent(nr, nc, wkr, wkc) and
                    not is_attacked(nr, nc, wkr, wkc, ar, ac)):
                    escape_count += 1
        return escape_count

    wkr, wkc = chess_to_coords(king)
    ar, ac = chess_to_coords(amazon)

    result = [0, 0, 0, 0]

    for br in range(8):
        for bc in range(8):
            # Check if this position is valid for black king
            if (br == wkr and bc == wkc) or (br == ar and bc == ac):
                continue
            if is_adjacent(br, bc, wkr, wkc):
                continue

            # Check if black king is under attack
            is_under_attack = is_attacked(br, bc, wkr, wkc, ar, ac)

            # Check escape count
            escape_count = can_escape(br, bc, wkr, wkc, ar, ac)

            # Classify position
            if is_under_attack and escape_count == 0:
                result[0] += 1  # Checkmate
            elif is_under_attack and escape_count > 0:
                result[1] += 1  # Check
            elif not is_under_attack and escape_count == 0:
                result[2] += 1  # Stalemate
            elif not is_under_attack and escape_count > 0:
                result[3] += 1  # Safe

    return result

def amazon_check_mate(board, color):
    """
    Check if the given chess board position is checkmate for the specified color.

    Args:
        board: 8x8 2D list representing the chess board with piece representations
        color: 'white' or 'black' - the color to check for checkmate

    Returns:
        bool: True if it's checkmate for the specified color, False otherwise
    """
    if not board or len(board) != 8 or any(len(row) != 8 for row in board):
        return False

    def find_king(board, color):
        king_symbol = 'K' if color == 'white' else 'k'
        for r in range(8):
            for c in range(8):
                if board[r][c] == king_symbol:
                    return (r, c)
        return None

    def is_valid_move(board, from_pos, to_pos, color):
        # Simplified validation - in a full implementation this would check
        # all piece movement rules and capture restrictions
        fr, fc = from_pos
        tr, tc = to_pos
        if (tr, tc) == (fr, fc):
            return False

        target_piece = board[tr][tc]
        is_own_piece = False
        if color == 'white' and target_piece and target_piece.isupper():
            is_own_piece = True
        elif color == 'black' and target_piece and target_piece.islower():
            is_own_piece = True

        if is_own_piece:
            return False

        return 0 <= tr < 8 and 0 <= tc < 8

    def is_in_check(board, color):
        king_pos = find_king(board, color)
        if not king_pos:
            return False
        return False  # Simplified - would check all opponent piece attacks

    def has_legal_moves(board, color):
        king_pos = find_king(board, color)
        if not king_pos:
            return True

        # Check if king can move to any adjacent square
        kr, kc = king_pos
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = kr + dr, kc + dc
                if 0 <= nr < 8 and 0 <= nc < 8:
                    if not is_in_check(board, color):
                        return True
        return False

    king_pos = find_king(board, color)
    if not king_pos:
        return False

    is_in_check_state = is_in_check(board, color)

    if not is_in_check_state:
        return False

    return not has_legal_moves(board, color)

def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0

    # For each number from 1 to n, check if it's a palindrome
    for i in range(1, n + 1):
        # Convert number to string to check if it's palindrome
        s = str(i)
        if s == s[::-1]:  # Check if string equals its reverse
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def histogram(test):
    # Split the string by spaces to get individual letters
    letters = test.split()

    # If no letters, return empty dict
    if not letters:
        return {}

    # Count frequencies using a dictionary
    counts = {}
    for letter in letters:
        counts[letter] = counts.get(letter, 0) + 1

    # Find maximum frequency
    max_count = max(counts.values())

    # Collect all letters with max frequency
    result = {letter: max_count for letter, count in counts.items() if count == max_count}

    return result

def poohbear(code):
    # Initialize memory as a dictionary for infinite cells in both directions
    memory = {}
    pointer = 0
    copy_register = 0
    output = []

    # Pre-process to find W-E pairs
    w_e_pairs = {}
    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                start = stack.pop()
                w_e_pairs[start] = i
                w_e_pairs[i] = start

    instruction_ptr = 0
    while instruction_ptr < len(code):
        cmd = code[instruction_ptr]

        # Ignore non-command characters
        if cmd not in '+-><cpWEPNTQU LIVABYD':
            instruction_ptr += 1
            continue

        # Get current cell value (default 0 if not exists)
        current_cell = memory.get(pointer, 0)

        # Execute command
        if cmd == '+':
            memory[pointer] = (current_cell + 1) % 256
        elif cmd == '-':
            memory[pointer] = (current_cell - 1) % 256
        elif cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == 'c':
            copy_register = current_cell
        elif cmd == 'p':
            memory[pointer] = copy_register
        elif cmd == 'W':
            if current_cell == 0:
                instruction_ptr = w_e_pairs.get(instruction_ptr)
                continue  # Jump to E, process it next iteration
            else:
                instruction_ptr += 1
        elif cmd == 'E':
            if current_cell != 0:
                instruction_ptr = w_e_pairs.get(instruction_ptr)
                continue  # Jump to W, process it next iteration
            else:
                instruction_ptr += 1
        elif cmd == 'P':
            output.append(chr(current_cell))
        elif cmd == 'N':
            output.append(str(current_cell))
        elif cmd == 'T':
            memory[pointer] = (current_cell * 2) % 256
        elif cmd == 'Q':
            memory[pointer] = (current_cell ** 2) % 256
        elif cmd == 'U':
            memory[pointer] = int(current_cell ** 0.5) % 256
        elif cmd == 'L':
            memory[pointer] = (current_cell + 2) % 256
        elif cmd == 'I':
            memory[pointer] = (current_cell - 2) % 256
        elif cmd == 'V':
            memory[pointer] = (current_cell // 2) % 256
        elif cmd == 'A':
            memory[pointer] = (current_cell + copy_register) % 256
        elif cmd == 'B':
            memory[pointer] = (current_cell - copy_register) % 256
        elif cmd == 'Y':
            memory[pointer] = (current_cell * copy_register) % 256
        elif cmd == 'D':
            if copy_register != 0:
                memory[pointer] = (current_cell // copy_register) % 256
            # Division by zero: do nothing

        instruction_ptr += 1

    return ''.join(output)

def converter(input_data, target_type, options=None):
    """
    High-reliability converter with comprehensive boundary validation.

    Args:
        input_data: The data to be converted
        target_type: String specifying target type ('int', 'float', 'str', 'list', 'dict')
        options: Optional dict with conversion parameters

    Returns:
        Converted data with validated structure

    Raises:
        TypeError: If input type is unsupported
        ValueError: If conversion fails or constraints violated
    """

    # Strategic Decomposition - Phase 1: Input Validation
    if options is None:
        options = {}

    # Critical Edge Case 1: None/null input handling
    if input_data is None:
        if options.get('null_as_empty', False):
            input_data = '' if target_type == 'str' else [] if target_type in ['list', 'dict'] else 0
        else:
            raise ValueError("Input data cannot be None without null_as_empty option")

    # Critical Edge Case 2: Type validation for target_type
    valid_types = ['int', 'float', 'str', 'list', 'dict']
    if target_type not in valid_types:
        raise ValueError(f"Unsupported target_type: {target_type}. Must be one of {valid_types}")

    # Critical Edge Case 3: Extreme value boundaries
    max_value = options.get('max_value', float('inf'))
    min_value = options.get('min_value', float('-inf'))

    # Strategic Decomposition - Phase 2: Core Computation
    converted_value = None

    if target_type == 'int':
        # Handle numeric conversion with overflow protection
        if isinstance(input_data, (int, float)):
            converted_value = int(input_data)
        elif isinstance(input_data, str) and input_data.strip():
            try:
                converted_value = int(float(input_data))
            except (ValueError, OverflowError):
                raise ValueError(f"Cannot convert '{input_data}' to int")
        else:
            raise TypeError(f"Cannot convert type {type(input_data).__name__} to int")

    elif target_type == 'float':
        # Handle numeric conversion with precision
        if isinstance(input_data, (int, float)):
            converted_value = float(input_data)
        elif isinstance(input_data, str) and input_data.strip():
            try:
                converted_value = float(input_data)
            except ValueError:
                raise ValueError(f"Cannot convert '{input_data}' to float")
        else:
            raise TypeError(f"Cannot convert type {type(input_data).__name__} to float")

    elif target_type == 'str':
        # Handle string conversion with encoding validation
        if isinstance(input_data, str):
            converted_value = input_data
        else:
            converted_value = str(input_data)

    elif target_type == 'list':
        # Handle list conversion with deduplication option
        if isinstance(input_data, list):
            converted_value = list(input_data)
        elif isinstance(input_data, str):
            converted_value = list(input_data) if options.get('char_by_char', False) else [input_data]
        elif isinstance(input_data, (int, float, dict)):
            converted_value = [input_data]
        else:
            try:
                converted_value = list(input_data)
            except TypeError:
                converted_value = [input_data]

    elif target_type == 'dict':
        # Handle dict conversion with validation
        if isinstance(input_data, dict):
            converted_value = dict(input_data)
        elif isinstance(input_data, (list, tuple)):
            try:
                converted_value = dict(input_data)
            except ValueError:
                raise ValueError("List/tuple cannot be converted to dict (invalid key-value pairs)")
        else:
            raise TypeError(f"Cannot convert type {type(input_data).__name__} to dict")

    # Strategic Decomposition - Phase 3: Boundary Validation
    if target_type in ['int', 'float']:
        if converted_value > max_value or converted_value < min_value:
            raise ValueError(f"Value {converted_value} outside bounds [{min_value}, {max_value}]")

    # Complexity Justification:
    # - Time: O(1) for primitive types, O(n) for list/dict conversions where n is input size
    # - Space: O(1) for primitives, O(n) for collection types
    # - Uses hash-based validation for O(1) type checking

    # Strategic Decomposition - Phase 4: Result Serialization
    return converted_value

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)

def almost_everywhere_zero(n, k):
    s = str(n)
    n_digits = len(s)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, cnt, tight, started):
        if cnt > k:
            return 0
        if pos == n_digits:
            return 1 if cnt == k and started else 0

        limit = int(s[pos]) if tight else 9
        result = 0

        for digit in range(limit + 1):
            new_tight = tight and (digit == limit)
            new_started = started or (digit > 0)
            new_cnt = cnt + (1 if new_started and digit > 0 else 0)

            result += dp(pos + 1, new_cnt, new_tight, new_started)

        return result

    return dp(0, 0, True, False)

import sys
from math import factorial

def combination(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1
    return factorial(n) // (factorial(k) * factorial(n - k))

def probability_at_least_k_types(n, k):
    # Using inclusion-exclusion principle
    # P(at least k types) = 1 - P(less than k types)
    # P(less than k types) = sum_{i=0}^{k-1} (-1)^i * C(k, i) * ((k-i)/k)^n
    if n == 0:
        return 0.0

    prob = 0.0
    for i in range(k):
        sign = (-1) ** i
        comb = combination(k, i)
        prob += sign * comb * ((k - i) / k) ** n

    return 1.0 - prob

def solve(k, target_prob):
    # Binary search for minimum n
    left, right = 1, k * 10000  # Upper bound estimation

    while left < right:
        mid = (left + right) // 2
        prob = probability_at_least_k_types(mid, k)

        if prob >= target_prob:
            right = mid
        else:
            left = mid + 1

    return left

