def exchange_sort(sequence):
    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for val in sequence:
        count[val] += 1

    # Create target sorted sequence
    target = []
    target.extend([7] * count[7])
    target.extend([8] * count[8])
    target.extend([9] * count[9])

    # Create a mapping from each position to its target position
    # We need to track where each element should go
    pos_map = {}
    for i, val in enumerate(sequence):
        if val not in pos_map:
            pos_map[val] = []
        pos_map[val].append(i)

    # Create a target position mapping
    target_pos = {}
    for i, val in enumerate(target):
        if val not in target_pos:
            target_pos[val] = []
        target_pos[val].append(i)

    # Create permutation mapping
    # perm[i] = j means element at position i should be at position j
    perm = [-1] * len(sequence)

    # For each value, map positions
    for val in [7, 8, 9]:
        if val in pos_map and val in target_pos:
            current_positions = pos_map[val]
            target_positions = target_pos[val]
            for i, pos in enumerate(current_positions):
                perm[pos] = target_positions[i]

    # Count cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i] and perm[i] != i:
            # Start a new cycle
            cycles += 1
            current = i
            while not visited[current]:
                visited[current] = True
                current = perm[current]

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

