def getAllPrimeFactors(n):
    # Input validation: check if n is a number
    if not isinstance(n, (int, float)):
        return []

    # Check if n is an integer (handle float that represents integer)
    if isinstance(n, float):
        if not n.is_integer():
            return []
        n = int(n)

    # Check if n is negative or 0
    if n <= 0:
        return []

    # Edge case: n = 1
    if n == 1:
        return [1]

    # Edge case: n = 2
    if n == 2:
        return [2]

    # Prime factorization
    factors = []

    # Handle factor 2
    while n % 2 == 0:
        factors.append(2)
        n = n // 2

    # Handle odd factors
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n = n // i
        i += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        factors.append(n)

    return factors

