def differentiate(polynomial, x):
    # Remove spaces
    polynomial = polynomial.replace(" ", "")

    # Split by + and - signs (keeping the signs with terms)
    terms = []
    current_term = ""
    i = 0

    while i < len(polynomial):
        if polynomial[i] in ['+', '-'] and i > 0:
            terms.append(current_term)
            current_term = polynomial[i]
        else:
            current_term += polynomial[i]
        i += 1
    terms.append(current_term)

    # Parse each term
    derivative_terms = []

    for term in terms:
        if not term:
            continue

        # Handle the sign
        sign = 1
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            term = term[1:]

        # Parse coefficient and exponent
        if 'x' not in term:
            # Constant term
            coeff = sign * int(term)
            derivative_terms.append(0)  # Derivative of constant is 0
        elif '^' in term:
            # Term with exponent: ax^n
            base, exp = term.split('x^')
            if base == '':
                coeff = sign * 1
            else:
                coeff = sign * int(base)
            exponent = int(exp)
            if exponent == 0:
                derivative_terms.append(0)
            else:
                derivative_terms.append(coeff * exponent * (x ** (exponent - 1)))
        elif term.endswith('x'):
            # Term with implicit exponent 1: ax
            base = term[:-1]
            if base == '':
                coeff = sign * 1
            elif base == '-':
                coeff = sign * -1
            else:
                coeff = sign * int(base)
            derivative_terms.append(coeff)
        else:
            # Term with implicit coefficient 1 and exponent 1: x
            derivative_terms.append(sign * 1)

    # Sum up all derivative terms
    result = sum(derivative_terms)
    return result

def parse_nested_parens(input_string):
    if not input_string:
        return []

    groups = input_string.split()
    result = []

    for group in groups:
        max_depth = 0
        current_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

