def almost_everywhere_zero(n, k):
    s = str(n)
    length = len(s)
    memo = {}

    def dp(pos, count, tight, leading_zeros):
        if count > k:
            return 0

        if pos == length:
            return 1 if count == k and not leading_zeros else 0

        state = (pos, count, tight, leading_zeros)
        if state in memo:
            return memo[state]

        result = 0
        limit = int(s[pos]) if tight else 9

        for digit in range(0, limit + 1):
            new_tight = tight and (digit == limit)
            new_leading_zeros = leading_zeros and (digit == 0)
            new_count = count + (1 if digit != 0 else 0)
            result += dp(pos + 1, new_count, new_tight, new_leading_zeros)

        memo[state] = result
        return result

    return dp(0, 0, True, True)

def choose(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry property to minimize computation
    k = min(k, n - k)

    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

def greatest_common_divisor(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> greatest_common_divisor(3, 5)
    1
    >>> greatest_common_divisor(25, 15)
    5
    """
    # Handle edge cases with zero values
    if a == 0:
        return abs(b)
    if b == 0:
        return abs(a)

    # Use Euclidean algorithm
    a, b = abs(a), abs(b)  # Work with absolute values
    while b:
        a, b = b, a % b

    return a

def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) <= 1:
        return True

    is_increasing = None

    for i in range(len(l) - 1):
        if l[i] < l[i + 1]:
            if is_increasing is False:
                return False
            is_increasing = True
        elif l[i] > l[i + 1]:
            if is_increasing is True:
                return False
            is_increasing = False
        # if l[i] == l[i + 1], we continue without changing is_increasing

    return True

def candies(arr):
    # Handle edge cases: empty array or single element
    if len(arr) <= 1:
        return -1

    # Find the maximum number of candies
    max_candies = max(arr)

    # Calculate total candies to be given out
    total_given = 0
    for candy_count in arr:
        # Only give candies to children who have fewer than the maximum
        if candy_count < max_candies:
            total_given += max_candies - candy_count

    return total_given

