def poohbear(code):
    # Preprocess: find matching W/E pairs
    w_to_e = {}
    e_to_w = {}
    stack = []

    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                w_pos = stack.pop()
                w_to_e[w_pos] = i
                e_to_w[i] = w_pos

    # Initialize state
    tape = {}  # dictionary for infinite tape
    pointer = 0
    copied = 0
    outputs = []

    def get_cell(pos):
        return tape.get(pos, 0)

    def set_cell(pos, value):
        tape[pos] = value

    def wrap(value):
        return value % 256

    # Execute commands
    i = 0
    while i < len(code):
        cmd = code[i]

        # Skip non-commands
        if cmd not in '+-><cWEPNTQLIVABYUD':
            i += 1
            continue

        cell = get_cell(pointer)

        if cmd == '+':
            set_cell(pointer, wrap(cell + 1))
            i += 1

        elif cmd == '-':
            set_cell(pointer, wrap(cell - 1))
            i += 1

        elif cmd == '>':
            pointer += 1
            i += 1

        elif cmd == '<':
            pointer -= 1
            i += 1

        elif cmd == 'c':
            copied = cell
            i += 1

        elif cmd == 'p':
            set_cell(pointer, copied)
            i += 1

        elif cmd == 'W':
            if cell == 0:
                # Jump to matching E
                i = w_to_e.get(i, i) + 1
            else:
                i += 1

        elif cmd == 'E':
            if cell != 0:
                # Jump back to matching W
                i = e_to_w.get(i, i)
            else:
                i += 1

        elif cmd == 'P':
            outputs.append(chr(cell))
            i += 1

        elif cmd == 'N':
            outputs.append(cell)
            i += 1

        elif cmd == 'T':
            set_cell(pointer, wrap(cell * 2))
            i += 1

        elif cmd == 'Q':
            set_cell(pointer, wrap(cell * cell))
            i += 1

        elif cmd == 'U':
            set_cell(pointer, wrap(int(cell ** 0.5)))
            i += 1

        elif cmd == 'L':
            set_cell(pointer, wrap(cell + 2))
            i += 1

        elif cmd == 'I':
            set_cell(pointer, wrap(cell - 2))
            i += 1

        elif cmd == 'V':
            set_cell(pointer, wrap(int(cell / 2)))
            i += 1

        elif cmd == 'A':
            set_cell(pointer, wrap(cell + copied))
            i += 1

        elif cmd == 'B':
            set_cell(pointer, wrap(cell - copied))
            i += 1

        elif cmd == 'Y':
            set_cell(pointer, wrap(cell * copied))
            i += 1

        elif cmd == 'D':
            if copied == 0:
                set_cell(pointer, 0)
            else:
                set_cell(pointer, wrap(int(cell / copied)))
            i += 1

    return outputs

def even_odd_palindrome(n):
