def _convert_integer_base(number, decimals, base):
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    sign = '-' if number < 0 else ''
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    if integer_part == 0:
        integer_result = '0'
    else:
        integer_result = ''
        while integer_part > 0:
            integer_result = digits[integer_part % base] + integer_result
            integer_part //= base

    # Convert fractional part
    fractional_part = number - int(number)
    if decimals == 0:
        fractional_result = ''
    else:
        fractional_result = '.'
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            fractional_result += digits[digit]
            fractional_part -= digit

    result = integer_result + fractional_result

    # Handle case where result is less than 1
    if result.startswith('.'):
        result = '0' + result

    return sign + result

def _convert_non_integer_base(number, decimals, base):
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    sign = '-' if number < 0 else ''
    number = abs(number)

    # Handle integer part using greedy algorithm
    if number == 0:
        integer_result = '0'
    else:
        # Find the highest power
        if number >= 1:
            power = int(math.log(number) / math.log(base))
        else:
            power = 0

        integer_result = ''
        remaining = number

        # Process from highest power down to 0
        for p in range(power, -1, -1):
            power_value = base ** p
            if power_value <= remaining:
                digit = int(remaining / power_value)
                integer_result += digits[digit]
                remaining -= digit * power_value
            else:
                integer_result += '0'

        # Handle case where we might have leading zeros
        integer_result = integer_result.lstrip('0') or '0'

    # Handle fractional part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        remaining = number - int(number)
        for _ in range(decimals):
            remaining *= base
            digit = int(remaining)
            fractional_result += digits[digit]
            remaining -= digit

    result = integer_result + fractional_result

    # Handle case where result is less than 1
    if result.startswith('.'):
        result = '0' + result

    return sign + result

