def poohbear(code):
    memory = {}
    pointer = 0
    copied = 0

    def get_cell(pos):
        return memory.get(pos, 0)

    def set_cell(pos, value):
        memory[pos] = int(value % 256)

    commands = [c for c in code if c in '+-><cpWEPNTQULIVABYD']

    w_e_map = {}
    w_stack = []
    for i, cmd in enumerate(commands):
        if cmd == 'W':
            w_stack.append(i)
        elif cmd == 'E':
            if w_stack:
                start = w_stack.pop()
                w_e_map[start] = i
                w_e_map[i] = start

    output = []
    ip = 0

    while ip < len(commands):
        cmd = commands[ip]

        if cmd == '+':
            set_cell(pointer, get_cell(pointer) + 1)
        elif cmd == '-':
            set_cell(pointer, get_cell(pointer) - 1)
        elif cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == 'c':
            copied = get_cell(pointer)
        elif cmd == 'p':
            set_cell(pointer, copied)
        elif cmd == 'W':
            if get_cell(pointer) == 0:
                ip = w_e_map[ip] + 1
                continue
        elif cmd == 'E':
            if get_cell(pointer) != 0:
                ip = w_e_map[ip]
                continue
        elif cmd == 'P':
            output.append(chr(get_cell(pointer)))
        elif cmd == 'N':
            output.append(str(get_cell(pointer)))
        elif cmd == 'T':
            set_cell(pointer, get_cell(pointer) * 2)
        elif cmd == 'Q':
            set_cell(pointer, get_cell(pointer) ** 2)
        elif cmd == 'U':
            set_cell(pointer, int(get_cell(pointer) ** 0.5))
        elif cmd == 'L':
            set_cell(pointer, get_cell(pointer) + 2)
        elif cmd == 'I':
            set_cell(pointer, get_cell(pointer) - 2)
        elif cmd == 'V':
            set_cell(pointer, get_cell(pointer) // 2)
        elif cmd == 'A':
            set_cell(pointer, get_cell(pointer) + copied)
        elif cmd == 'B':
            set_cell(pointer, get_cell(pointer) - copied)
        elif cmd == 'Y':
            set_cell(pointer, get_cell(pointer) * copied)
        elif cmd == 'D':
            if copied != 0:
                set_cell(pointer, get_cell(pointer) // copied)

        ip += 1

    return ''.join(output)

def simplify(expression):
    if not expression:
        return "0"

    from collections import defaultdict

    # Parse the expression into terms
    terms = []
    i = 0
    n = len(expression)

    # Determine if there's an initial sign (for first term)
    current_sign = 1
    if expression[0] == '+':
        i = 1
    elif expression[0] == '-':
        current_sign = -1
        i = 1

    while i < n:
        # Each term has the structure: [sign][coefficient][variables]
        # Sign is already captured before the loop for first term
        # For subsequent terms, sign is at position i before the coefficient

        # Parse coefficient (may be absent, meaning 1)
        coeff_start = i
        has_digit = False
        while i < n and expression[i].isdigit():
            has_digit = True
            i += 1

        if has_digit:
            coeff = int(expression[coeff_start:i])
        else:
            coeff = 1

        # Parse variables (lowercase letters)
        vars_start = i
        while i < n and expression[i].isalpha():
            i += 1

        vars_str = expression[vars_start:i]

        if vars_str:  # Only non-constant terms
            sorted_vars = tuple(sorted(vars_str))
            terms.append((current_sign * coeff, sorted_vars))

        # Look for next sign (which starts the next term)
        if i < n and expression[i] in '+-':
            if expression[i] == '+':
                current_sign = 1
            else:
                current_sign = -1
            i += 1

    # Combine like terms
    combined = defaultdict(int)
    for coeff, vars_tuple in terms:
        combined[vars_tuple] += coeff

    # Filter out zero coefficients
    combined = {k: v for k, v in combined.items() if v != 0}

    if not combined:
        return "0"

    # Sort: by number of variables (ascending), then lexicographically
    sorted_terms = sorted(combined.items(), key=lambda x: (len(x[0]), x[0]))

    # Format output
    result_parts = []
    for coeff, vars_tuple in sorted_terms:
        # Determine variable string
        if not vars_tuple:
            term_str = str(coeff)
        else:
            vars_str = ''.join(vars_tuple)
            if abs(coeff) == 1:
                term_str = vars_str
            else:
                term_str = str(abs(coeff)) + vars_str

        # Determine sign to prepend
        if coeff < 0:
            sign_str = '-'
        else:
            sign_str = '+'

        result_parts.append((sign_str, term_str))

    # Build final string, omitting leading '+'
    output_parts = []
    for idx, (sign_str, term_str) in enumerate(result_parts):
        if idx == 0 and sign_str == '+':
            output_parts.append(term_str)
        else:
            output_parts.append(sign_str + term_str)

    return ''.join(output_parts)

