def parse_int(s):
    if not s:
        return 0

    # Define mappings
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14, 'fifteen': 15,
        'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19,
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    scale_words = {
        'hundred': 100,
        'thousand': 1000,
        'million': 1000000
    }

    # Split by spaces and filter out empty strings
    tokens = [token for token in s.split() if token]

    total = 0
    current = 0

    for token in tokens:
        if token == 'and':
            continue

        # Handle hyphenated numbers
        if '-' in token:
            parts = token.split('-')
            num = 0
            for part in parts:
                if part in word_to_num:
                    num += word_to_num[part]
                elif part in scale_words:
                    num *= scale_words[part]
            current += num
        elif token in word_to_num:
            current += word_to_num[token]
        elif token in scale_words:
            current *= scale_words[token]
            total += current
            current = 0

    return total + current

def sum_of_a_beach(s):
    words = ["sand", "water", "fish", "sun"]
    s_lower = s.lower()
    count = 0
    i = 0

    while i < len(s_lower):
        matched = False
        for word in words:
            if s_lower[i:i+len(word)] == word:
                count += 1
                i += len(word)
                matched = True
                break
        if not matched:
            i += 1

    return count

def count_divisors(n):
    """
    Returns the number of divisors of n (1 <= n <= 10^12).
    Uses trial division up to sqrt(n).
    """
    if n <= 0:
        return 0

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1

    return count

