                attacks.add((x, y))
                x += dx
                y += dy

        # Knight moves
        knight_moves = [(2, 1), (1, 2), (-1, 2), (-2, 1), (-2, -1), (-1, -2), (1, -2), (2, -1)]
        for dx, dy in knight_moves:
            new_pos = (amazon_pos[0] + dx, amazon_pos[1] + dy)
            if is_valid(new_pos):
                attacks.add((new_pos))

        return attacks

    def is_adjacent(pos1, pos2):
        return abs(pos1[0] - pos2[0]) <= 1 and abs(pos1[1] - pos2[1]) <= 1

    king_pos = chess_to_coords(king)
    amazon_pos = chess_to_coords(amazon)

    # Get all squares the amazon attacks
    amazon_attacks = get_amazon_attacks(amazon_pos)

    # Get all squares the white king attacks (for adjacency constraint)
    king_attacks = set(get_king_moves(king_pos))

    # Get all squares adjacent to the white king
    adjacent_squares = set()
    for dx in [-1, 0, 1]:
        for dy in [-1, 0, 1]:
            if dx == 0 and dy == 0:
                continue
            new_pos = (king_pos[0] + dx, king_pos[1] + dy)
            if is_valid(new_pos):
                adjacent_squares.add(new_pos)

    result = [0, 0, 0, 0]  # [checkmate, check, stalemate, safe]

    # Check all possible positions for the black king
    for x in range(8):
        for y in range(8):
            black_king_pos = (x, y)

            # Skip if position is occupied by white king or amazon
            if black_king_pos == king_pos or black_king_pos == amazon_pos:
                continue

            # Skip if position is adjacent to white king
            if black_king_pos in adjacent_squares:
                continue

            # Check if black king is under attack by amazon
            is_under_attack = black_king_pos in amazon_attacks

            # Get all possible moves for black king
            black_king_moves = get_king_moves(black_king_pos)
            safe_moves = []

            for move in black_king_moves:
                # Skip if move is to an occupied square
                if move == king_pos or move == amazon_pos:
                    continue
                # Skip if move is to an adjacent square of white king
                if move in adjacent_squares:
                    continue
                # Skip if move is to a square under attack
                if move in amazon_attacks:
                    continue
                safe_moves.append(move)

            # Classify position
            if is_under_attack:
                if len(safe_moves) == 0:
                    result[0] += 1  # checkmate
                else:
                    result[1] += 1  # check
            else:
                if len(safe_moves) == 0:
                    result[2] += 1  # stalemate
                else:
                    result[3] += 1  # safe

    return result

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part to given base
    if integer_part == 0:
        integer_result = '0'
    else:
        digits = []
        n = integer_part
        while n > 0:
            remainder = n % base
            # Adjust for negative remainders
            if remainder < 0:
                remainder += base
                n = (n - remainder) // base - 1
            else:
                n = (n - remainder) // base
            digits.append(remainder)

        # Convert to proper digit representation
        integer_result = ''
        for digit in reversed(digits):
            if digit < 10:
                integer_result += str(int(digit))
            else:
                integer_result += chr(ord('A') + int(digit) - 10)

    # Convert fractional part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            if digit < 10:
                fractional_result += str(digit)
            else:
                fractional_result += chr(ord('A') + digit - 10)
            fractional_part -= digit

    # Combine results
    result = integer_result + fractional_result

    # Handle negative sign
    if negative:
        result = '-' + result

    # Handle case where result is less than 1 and needs leading zero
    if result.startswith('.'):
        result = '0' + result

    return result

from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = ""
    depth = 0

    for char in paren_string:
        if char == ' ':
            continue

        if char == '(':
            current_group += char
            depth += 1
        elif char == ')':
            current_group += char
            depth -= 1

            if depth == 0:
                result.append(current_group)
                current_group = ""

    return result

import re

def simplify(expr):
    # Split the expression into monomials, keeping track of signs
    monomials_str = re.split(r'(?=[+-])', expr)
    monomials_str = [m.strip() for m in monomials_str if m.strip()]

    if not monomials_str:
        return "0"

    # Parse each monomial into coefficient and variables
    parsed = []
    for mon in monomials_str:
        # Determine sign
        if mon[0] == '-':
            sign = -1
            mon = mon[1:]
        elif mon[0] == '+':
            sign = 1
            mon = mon[1:]
        else:
            sign = 1

        # Parse coefficient (digits at the start)
        i = 0
        while i < len(mon) and mon[i].isdigit():
            i += 1

        if i > 0:
            coeff = int(mon[:i]) * sign
            variables = ''.join(sorted(mon[i:]))
        else:
            coeff = sign
            variables = ''.join(sorted(mon))

        parsed.append((coeff, variables))

    # Combine like terms (same variables)
    terms = {}
    for coeff, variables in parsed:
        key = frozenset(variables)
        terms[key] = terms.get(key, 0) + coeff

    # Filter out zero coefficients and convert to list
    result = []
    for key in terms:
        coeff = terms[key]
        if coeff != 0:
            result.append((coeff, ''.join(sorted(key))))

    if not result:
        return "0"

    # Sort: first by number of variables, then lexicographically
    result.sort(key=lambda x: (len(x[1]), x[1]))

    # Format output
    output_parts = []
    for i, (coeff, variables) in enumerate(result):
        if coeff == 1:
            part = variables
        elif coeff == -1:
            part = '-' + variables
        elif coeff > 0:
            part = str(coeff) + variables
        else:
            part = str(coeff) + variables

        # No leading + for first term
        if i == 0 and part.startswith('+'):
            part = part[1:]
        elif i > 0 and part.startswith('-'):
            pass  # Keep the minus
        elif i > 0:
            part = '+' + part

        output_parts.append(part)

    return ''.join(output_parts)

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 31536000),
        ('day', 86400),
        ('hour', 3600),
        ('minute', 60),
        ('second', 1)
    ]

    # Calculate each unit
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            plural = 's' if count > 1 else ''
            components.append(f"{count} {unit_name}{plural}")

    # Format the output string
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

def parse_int(text):
    # Mapping of number words to values
    ones = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9,
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16,
        'seventeen': 17, 'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    multipliers = {
        'hundred': 100,
        'thousand': 1000,
        'million': 1000000
    }

    # Special case for zero
    if text.lower() == 'zero':
        return 0

    # Normalize text: lowercase, replace hyphens with spaces
    text = text.lower().replace('-', ' ')
    words = text.split()

    # Remove 'and' words (they don't contribute to value)
    words = [w for w in words if w != 'and']

    total = 0
    current = 0

    for word in words:
        if word in ones:
            current += ones[word]
        elif word in tens:
            current += tens[word]
        elif word == 'hundred':
            current *= 100
        elif word == 'thousand':
            total += current * 1000
            current = 0
        elif word == 'million':
            total += current * 1000000
            current = 0

    total += current
    return total

def next_smallest(lst):
    if len(lst) < 2:
        return None

    smallest = float('inf')
    second_smallest = float('inf')

    for num in lst:
        if num < smallest:
            second_smallest = smallest
            smallest = num
        elif num < second_smallest and num != smallest:
            second_smallest = num

    return second_smallest if second_smallest != float('inf') else None

import sys

def main():
    data = sys.stdin.read()
    tokens = data.split()
    ptr = 0

    k = int(tokens[ptr])
    ptr += 1
    q = int(tokens[ptr])
    ptr += 1

    queries = []
    for i in range(q):
        queries.append(int(tokens[ptr]))
        ptr += 1

    # Precompute binomial coefficients C[n][r]
    C = [[0] * (k + 1) for _ in range(k + 1)]
    for i in range(k + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = C[i-1][j-1] + C[i-1][j]

    def probability(n):
        """Compute P(all k types collected in n days) using inclusion-exclusion"""
        result = 0.0
        for j in range(k + 1):
            if k - j == 0:
                if n == 0:
                    term = C[k][j] * 1.0
                else:
                    term = 0.0
            else:
                base = (k - j) / k
                term = C[k][j] * (base ** n)

            if j % 2 == 1:
                result -= term
            else:
                result += term

        # Clamp to [0, 1] for numerical stability
        return max(0.0, min(1.0, result))

    eps = 1e-8
    results = []

    for p in queries:
        threshold = (p - eps) / 2000.0

        # Binary search for minimum n
        # Lower bound: need at least k days to collect k different types
        # Upper bound: safe large number covering all cases
        left, right = k, 10_000_000
        answer = right

        while left <= right:
            mid = (left + right) // 2
            if probability(mid) >= threshold:
                answer = mid
                right = mid - 1
            else:
                left = mid + 1

        results.append(answer)

    for r in results:
        print(r)

if __name__ == "__main__":
    main()

def cycpattern_check(a, b):
    # Handle edge cases
    if not b:
        return True
    if not a:
        return False
    if len(b) > len(a):
        return False
    if b == a:
        return True

    # Concatenate b with itself
    # All rotations of b will be substrings of b+b
    b_double = b + b

    # Check if any substring of length len(b) in b_double exists in a
    for i in range(len(b)):
        rotation = b_double[i:i+len(b)]
        if rotation in a:
            return True

    return False

