def is_balanced(input_string, pairs):
    if not pairs:
        return True

    # Create a mapping of closing to opening characters
    # and a set of opening characters
    opening_chars = set()
    closing_to_opening = {}

    # Process pairs string to build mappings
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        opening_chars.add(opening)
        # If opening and closing are the same character
        if opening == closing:
            # It can serve as both opening and closing
            if opening not in closing_to_opening:
                closing_to_opening[opening] = opening
        else:
            closing_to_opening[closing] = opening

    # Stack to track opening characters
    stack = []

    for char in input_string:
        # If it's an opening character
        if char in opening_chars:
            # If it's also a closing character (same char for both)
            if char in closing_to_opening and closing_to_opening[char] == char:
                stack.append(char)
            else:
                # Regular opening character
                stack.append(char)
        # If it's a closing character
        elif char in closing_to_opening:
            # Check if stack is empty or if the top doesn't match
            if not stack or stack[-1] != closing_to_opening[char]:
                return False
            stack.pop()

    # If stack is empty, all brackets were matched
    return len(stack) == 0

