def proper_fractions(d):
    if d <= 1:
        return 0

    result = d

    # Remove factor 2
    if d % 2 == 0:
        result = result // 2
        while d % 2 == 0:
            d //= 2

    # Remove odd factors up to sqrt(d)
    i = 3
    while i * i <= d:
        if d % i == 0:
            result = result // i * (i - 1)
            while d % i == 0:
                d //= i
        i += 2

    # If d is a prime number greater than 2
    if d > 2:
        result = result // d * (d - 1)

    return result

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """

    def to_float(value):
        if isinstance(value, str):
            # Normalize decimal separator: replace comma with dot
            normalized = value.replace(',', '.')
            return float(normalized)
        else:
            return float(value)

    # Convert both values to float for numerical comparison
    a_val = to_float(a)
    b_val = to_float(b)

    # Compare and return the original value with the larger numerical representation
    if a_val > b_val:
        return a
    elif b_val > a_val:
        return b
    else:
        return None

def compare(selector1, selector2):
    def get_specificity(selector):
        id_count = 0
        class_count = 0
        tagname_count = 0

        # Remove spaces and split by combinators
        parts = selector.replace(' ', '').replace('>', '').replace('+', '').replace('~', '')

        # Count selectors
        i = 0
        while i < len(parts):
            if parts[i] == '#':
                id_count += 1
                # Skip to next non-id character
                i += 1
                while i < len(parts) and parts[i] not in ['.', '#', '[', ' ', '>', '+', '~']:
                    i += 1
            elif parts[i] == '.':
                class_count += 1
                # Skip to next non-class character
                i += 1
                while i < len(parts) and parts[i] not in ['.', '#', '[', ' ', '>', '+', '~']:
                    i += 1
            elif parts[i] == '[':
                # Skip attribute selectors
                i += 1
                while i < len(parts) and parts[i] != ']':
                    i += 1
                i += 1
            else:
                # This is a tag name
                tagname_count += 1
                # Skip to next non-tag character
                i += 1
                while i < len(parts) and parts[i] not in ['.', '#', '[', ' ', '>', '+', '~']:
                    i += 1

        return (id_count, class_count, tagname_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    if spec1 > spec2:
        return selector1
    else:
        return selector2

def is_balanced(s, pairs):
