import math

def sum_of_squares(n):
    # Check if n is a perfect square
    sqrt_n = int(math.sqrt(n))
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n is of the form 4^a(8b + 7)
    while n % 4 == 0:
        n //= 4
    if n % 8 == 7:
        return 4

    # Check if n can be represented as sum of two squares
    for i in range(1, int(math.sqrt(n)) + 1):
        remainder = n - i * i
        sqrt_remainder = int(math.sqrt(remainder))
        if sqrt_remainder * sqrt_remainder == remainder:
            return 2

    # If none of the above, answer is 3
    return 3

def getAllPrimeFactors(n):
    if not isinstance(n, (int, float)):
        return []
    if isinstance(n, float) and not n.is_integer():
        return []
    if n <= 0:
        return []
    if n == 1:
        return [1]

    factors = []
    n = int(n)

    while n % 2 == 0:
        factors.append(2)
        n //= 2

    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 2

    if n > 1:
        factors.append(n)

    return factors


def getUniquePrimeFactorsWithCount(n):
    if not isinstance(n, (int, float)):
        return [[], []]
    if isinstance(n, float) and not n.is_integer():
        return [[], []]
    if n <= 0:
        return [[], []]
    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)

    primes = []
    counts = []
    i = 0
    while i < len(factors):
        prime = factors[i]
        count = 1
        i += 1
        while i < len(factors) and factors[i] == prime:
            count += 1
            i += 1
        primes.append(prime)
        counts.append(count)

    return [primes, counts]


def getUniquePrimeFactorsWithProducts(n):
    if not isinstance(n, (int, float)):
