def amazonCheckmate(king, amazon):
    def pos_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def coords_to_pos(x, y):
        return chr(x + ord('a')) + str(y + 1)

    def is_valid(x, y):
        return 0 <= x < 8 and 0 <= y < 8

    def is_adjacent(x1, y1, x2, y2):
        return abs(x1 - x2) <= 1 and abs(y1 - y2) <= 1

    def get_amazon_attacks(amazon_x, amazon_y):
        attacks = set()

        # Queen moves (rook + bishop)
        # Horizontal and vertical
        for i in range(8):
            if i != amazon_x:
                attacks.add((i, amazon_y))
        for j in range(8):
            if j != amazon_y:
                attacks.add((amazon_x, j))

        # Diagonals
        for dx in [-1, 1]:
            for dy in [-1, 1]:
                x, y = amazon_x + dx, amazon_y + dy
                while is_valid(x, y):
                    attacks.add((x, y))
                    x += dx
                    y += dy

        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            x, y = amazon_x + dx, amazon_y + dy
            if is_valid(x, y):
                attacks.add((x, y))

        return attacks

    def get_king_moves(x, y):
        moves = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                new_x, new_y = x + dx, y + dy
                if is_valid(new_x, new_y):
                    moves.append((new_x, new_y))
        return moves

    king_x, king_y = pos_to_coords(king)
    amazon_x, amazon_y = pos_to_coords(amazon)

    amazon_attacks = get_amazon_attacks(amazon_x, amazon_y)

    # Get all valid black king positions (not adjacent to white king)
    valid_positions = []
    for x in range(8):
        for y in range(8):
            if not is_adjacent(x, y, king_x, king_y):
                valid_positions.append((x, y))

    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    for bx, by in valid_positions:
        # Check if black king is under attack
        is_attacked = (bx, by) in amazon_attacks

        if is_attacked:
            # Check if any of the king's moves leads to a safe square
            king_moves = get_king_moves(bx, by)
            safe_moves = 0

            for move_x, move_y in king_moves:
                # Check if the move is valid (not adjacent to white king)
                if not is_adjacent(move_x, move_y, king_x, king_y):
                    # Check if the move is not under attack
                    if (move_x, move_y) not in amazon_attacks:
                        safe_moves += 1

            if safe_moves == 0:
                checkmate += 1
            else:
                check += 1
        else:
            # King is not under attack, check if it can move
            king_moves = get_king_moves(bx, by)
            safe_moves = 0

            for move_x, move_y in king_moves:
                # Check if the move is valid (not adjacent to white king)
                if not is_adjacent(move_x, move_y, king_x, king_y):
                    # Check if the move is not under attack
                    if (move_x, move_y) not in amazon_attacks:
                        safe_moves += 1

            if safe_moves == 0:
                stalemate += 1
            else:
                safe += 1

    return [checkmate, check, stalemate, safe]

