def getAllPrimeFactors(n):
    # Input validation
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []
    if isinstance(n, float) and not n.is_integer():
        return []
    if n <= 0:
        return []

    n = int(n)

    # Special case for n=1
    if n == 1:
        return [1]

    factors = []
    divisor = 2

    # Trial division up to sqrt(n)
    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n = n // divisor
        divisor += 1

    # If n is still greater than 1, it's a prime factor
    if n > 1:
        factors.append(n)

    return factors


def getUniquePrimeFactorsWithCount(n):
    # Input validation
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return [[], []]
    if isinstance(n, float) and not n.is_integer():
        return [[], []]
    if n <= 0:
        return [[], []]

    n = int(n)

    # Special case for n=1
    if n == 1:
        return [[1], [1]]

    unique_factors = []
    counts = []
    divisor = 2

    # Trial division up to sqrt(n)
    while divisor * divisor <= n:
        count = 0
        while n % divisor == 0:
            count += 1
            n = n // divisor
        if count > 0:
            unique_factors.append(divisor)
            counts.append(count)
        divisor += 1

    # If n is still greater than 1, it's a prime factor with count 1
    if n > 1:
        unique_factors.append(n)
        counts.append(1)

    return [unique_factors, counts]


def getUniquePrimeFactorsWithProducts(n):
