def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 365 * 24 * 60 * 60),
        ('day', 24 * 60 * 60),
        ('hour', 60 * 60),
        ('minute', 60),
        ('second', 1)
    ]

    # Calculate each unit
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            if count > 1:
                components.append(f"{count} {unit_name}s")
            else:
                components.append(f"{count} {unit_name}")

    # Format the output
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

def simplify(expression):
    if not expression:
        return ""

    # Parse the expression
    terms = []
    i = 0
    while i < len(expression):
        # Determine the sign
        sign = 1
        if expression[i] == '+':
            i += 1
        elif expression[i] == '-':
            sign = -1
            i += 1

        # Extract coefficient and variable part
        coeff_str = ""
        var_part = ""

        # Parse coefficient (could be empty for 1 or -1)
        while i < len(expression) and expression[i].isdigit():
            coeff_str += expression[i]
            i += 1

        # If no coefficient found, it's 1 or -1
        if not coeff_str:
            coeff = sign * 1
        else:
            coeff = sign * int(coeff_str)

        # Parse variable part
        while i < len(expression) and expression[i].isalpha():
            var_part += expression[i]
            i += 1

        # If no variable part, it's just a constant (but problem says non-constant)
        if var_part:
            terms.append((coeff, var_part))

    # Normalize terms by sorting variables in each term
    normalized_terms = []
    for coeff, var_part in terms:
        sorted_var = ''.join(sorted(var_part))
        normalized_terms.append((coeff, sorted_var))

    # Aggregate terms with same variables
    term_dict = {}
    for coeff, var in normalized_terms:
        if var in term_dict:
            term_dict[var] += coeff
        else:
            term_dict[var] = coeff

    # Filter out zero coefficients
    filtered_terms = [(coeff, var) for var, coeff in term_dict.items() if coeff != 0]

    # Sort terms by number of variables (ascending) and then lexicographically
    filtered_terms.sort(key=lambda x: (len(x[1]), x[1]))

    # Format the result
    result = []
    for i, (coeff, var) in enumerate(filtered_terms):
        if i == 0:
            # First term, no leading +
            if coeff == 1:
                result.append(var)
            elif coeff == -1:
                result.append('-' + var)
            else:
                result.append(str(coeff) + var)
        else:
            # Subsequent terms
            if coeff == 1:
                result.append('+' + var)
            elif coeff == -1:
                result.append('-' + var)
            else:
                if coeff > 0:
                    result.append('+' + str(coeff) + var)
                else:
                    result.append(str(coeff) + var)

    return ''.join(result)

