import re

def differentiate(polynomial, x):
    # Parse the polynomial into terms
    # Handle the case where there's no + or - at the beginning
    if polynomial[0] != '-':
        polynomial = '+' + polynomial

    # Split by + and - signs (keeping the sign with each term)
    terms = re.findall(r'[+-][^+-]*', polynomial)

    # Process each term
    derivative_terms = []

    for term in terms:
        term = term.strip()
        if not term:
            continue

        # Determine the sign
        sign = 1 if term[0] == '+' else -1
        term = term[1:]  # Remove the sign

        # Handle different types of terms
        if 'x^' in term:
            # Term like 3x^2 or -5x^3
            coeff_part, exp_part = term.split('x^')
            coefficient = int(coeff_part) if coeff_part else 1
            exponent = int(exp_part)
            if coefficient == 1:
                coefficient = 1
            elif coefficient == -1:
                coefficient = -1
            else:
                coefficient = int(coeff_part)

            # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
            if exponent > 0:
                new_coeff = exponent * coefficient
                new_exp = exponent - 1
                if new_exp == 0:
                    derivative_terms.append(str(new_coeff))
                elif new_exp == 1:
                    derivative_terms.append(f"{new_coeff}x")
                else:
                    derivative_terms.append(f"{new_coeff}x^{new_exp}")

        elif 'x' in term:
            # Term like 3x or -5x
            coeff_part = term.replace('x', '')
            coefficient = int(coeff_part) if coeff_part else 1
            if coefficient == 1:
                coefficient = 1
            elif coefficient == -1:
                coefficient = -1
            else:
                coefficient = int(coeff_part)

            # Apply power rule: d/dx(ax^1) = 1*ax^0 = a
            derivative_terms.append(str(coefficient))

        else:
            # Constant term
            coefficient = int(term)
            # Derivative of constant is 0, so we don't add anything to derivative_terms

    # If no derivative terms, return 0
    if not derivative_terms:
        return 0

    # Build derivative expression string
    derivative_expr = derivative_terms[0]
    for i in range(1, len(derivative_terms)):
        if derivative_terms[i][0] == '-':
            derivative_expr += f" - {derivative_terms[i][1:]}"
        else:
            derivative_expr += f" + {derivative_terms[i]}"

    # Evaluate the derivative at x
    # Replace x with the value and evaluate
    result = 0
    for term in derivative_terms:
        if 'x' in term:
            # Extract coefficient and exponent
            if 'x^' in term:
                coeff_part, exp_part = term.split('x^')
                coefficient = int(coeff_part) if coeff_part else 1
                exponent = int(exp_part)
                result += coefficient * (x ** exponent)
            elif 'x' in term:
                coeff_part = term.replace('x', '')
                coefficient = int(coeff_part) if coeff_part else 1
                result += coefficient * x
        else:
            # Constant term
            result += int(term)

    return result

