        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14, 'fifteen': 15,
        'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19, 'twenty': 20,
        'thirty': 30, 'forty': 40, 'fifty': 50, 'sixty': 60, 'seventy': 70,
        'eighty': 80, 'ninety': 90
    }

    # Split the string into words, handling hyphens
    words = []
    for part in s.split():
        if '-' in part:
            # Split hyphenated words
            subparts = part.split('-')
            words.extend(subparts)
        else:
            words.append(part)

    # Remove 'and' words
    words = [word for word in words if word != 'and']

    if not words:
        return 0

    total = 0
    current = 0

    for word in words:
        if word in word_to_num:
            current += word_to_num[word]
        elif word == 'hundred':
            current *= 100
        elif word == 'thousand':
            total += current * 1000
            current = 0
        elif word == 'million':
            total += current * 1000000
            current = 0

    return total + current

def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def poohbear(code):
    # Preprocess to build jump map for W and E
    jump_map = {}
    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                start = stack.pop()
                jump_map[start] = i
                jump_map[i] = start

    # Initialize state
    tape = {}
    pointer = 0
    clipboard = 0
    ip = 0
    output = []

    while ip < len(code):
        char = code[ip]

        if char == '+':
            tape[pointer] = (tape.get(pointer, 0) + 1) % 256
        elif char == '-':
            tape[pointer] = (tape.get(pointer, 0) - 1) % 256
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            clipboard = tape.get(pointer, 0)
        elif char == 'p':
            tape[pointer] = clipboard
        elif char == 'W':
            if tape.get(pointer, 0) == 0:
                ip = jump_map[ip]
        elif char == 'E':
            if tape.get(pointer, 0) != 0:
                ip = jump_map[ip]
        elif char == 'P':
            output.append(chr(tape.get(pointer, 0)))
        elif char == 'N':
            output.append(str(tape.get(pointer, 0)))
        elif char == 'T':
            tape[pointer] = (tape.get(pointer, 0) * 2) % 256
        elif char == 'Q':
            tape[pointer] = (tape.get(pointer, 0) ** 2) % 256
        elif char == 'U':
            import math
            tape[pointer] = int(math.sqrt(tape.get(pointer, 0)))
        elif char == 'L':
            tape[pointer] = (tape.get(pointer, 0) + 2) % 256
        elif char == 'I':
            tape[pointer] = (tape.get(pointer, 0) - 2) % 256
        elif char == 'V':
            tape[pointer] = (tape.get(pointer, 0) // 2) % 256
        elif char == 'A':
            tape[pointer] = (tape.get(pointer, 0) + clipboard) % 256
        elif char == 'B':
            tape[pointer] = (tape.get(pointer, 0) - clipboard) % 256
        elif char == 'Y':
            tape[pointer] = (tape.get(pointer, 0) * clipboard) % 256
        elif char == 'D':
            if clipboard != 0:
                tape[pointer] = (tape.get(pointer, 0) // clipboard) % 256
            else:
                tape[pointer] = 0

        ip += 1

    return ''.join(output)

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    total_sum = 0
    total_product = 1
    for n in numbers:
        total_sum += n
        total_product *= n
    return (total_sum, total_product)

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, value) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract just the values from the sorted pairs
    return [num for _, _, num in indexed_nums]

