def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def is_valid(r, c):
        return 0 <= r < 8 and 0 <= c < 8

    def get_king_moves(r, c):
        moves = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc):
                    moves.append((nr, nc))
        return moves

    def get_amazon_attacks(r, c):
        attacks = set()

        # Queen moves (rook + bishop)
        # Horizontal and vertical
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            while is_valid(nr, nc):
                attacks.add((nr, nc))
                if (nr, nc) == (r, c):  # This shouldn't happen, but just in case
                    break
                nr += dr
                nc += dc

        # Diagonal
        for dr, dc in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
            nr, nc = r + dr, c + dc
            while is_valid(nr, nc):
                attacks.add((nr, nc))
                if (nr, nc) == (r, c):  # This shouldn't happen, but just in case
                    break
                nr += dr
                nc += dc

        # Knight moves
        knight_moves = [(2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)]
        for dr, dc in knight_moves:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                attacks.add((nr, nc))

        return attacks

    def is_adjacent(r1, c1, r2, c2):
        return abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1

    king_r, king_c = chess_to_coords(king)
    amazon_r, amazon_c = chess_to_coords(amazon)

    # Get all squares attacked by the amazon
    amazon_attacks = get_amazon_attacks(amazon_r, amazon_c)

    # Get all squares adjacent to the white king
    white_king_adjacent = set()
    for r, c in get_king_moves(king_r, king_c):
        white_king_adjacent.add((r, c))

    result = [0, 0, 0, 0]  # [checkmate, check, stalemate, safe]

    # Check all possible black king positions
    for r in range(8):
        for c in range(8):
            # Skip if square is occupied by white king or amazon
            if (r, c) == (king_r, king_c) or (r, c) == (amazon_r, amazon_c):
                continue

            # Skip if square is adjacent to white king
            if (r, c) in white_king_adjacent:
                continue

            # Check if black king is under attack by amazon
            is_under_attack = (r, c) in amazon_attacks

            # Get valid moves for black king
            black_king_moves = get_king_moves(r, c)
            valid_moves = []

            for nr, nc in black_king_moves:
                # Skip if square is occupied by white pieces or adjacent to white king
                if (nr, nc) == (king_r, king_c) or (nr, nc) == (amazon_r, amazon_c):
                    continue
                if (nr, nc) in white_king_adjacent:
                    continue
                # Skip if square is under attack by amazon
                if (nr, nc) in amazon_attacks:
                    continue
                valid_moves.append((nr, nc))

            # Classify the position
            if is_under_attack:
                if valid_moves:
                    # Check
                    result[1] += 1
                else:
                    # Checkmate
                    result[0] += 1
            else:
                if valid_moves:
                    # Safe and can move
                    result[3] += 1
                else:
                    # Stalemate
                    result[2] += 1

    return result

def solution(input_string, comment_markers):
