def even_odd_palindrome(n):
    def is_palindrome(num):
        # Convert to string and check if it reads the same forwards and backwards
        s = str(num)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

import sys
import math

def compute_probability(k, n):
    """Compute probability of collecting all k types in n days using inclusion-exclusion"""
    if n < k:
        return 0.0

    # Using inclusion-exclusion principle
    # P(all types collected) = sum_{i=0}^{k} (-1)^i * C(k,i) * ((k-i)/k)^n
    prob = 0.0
    for i in range(k + 1):
        # C(k, i) = k! / (i! * (k-i)!)
        if i == 0:
            comb = 1
        else:
            comb = math.factorial(k) // (math.factorial(i) * math.factorial(k - i))

        term = ((k - i) / k) ** n
        if i % 2 == 0:
            prob += comb * term
        else:
            prob -= comb * term

    return prob

def binary_search(k, target_prob):
    """Find minimum n such that probability >= target_prob"""
    if k == 1:
        return 1

    left, right = k, k * k  # Upper bound estimation

    # For large k, we can use a tighter upper bound
    if k > 100:
        right = int(k * (math.log(k) + 1.5) + 100)

    while left < right:
        mid = (left + right) // 2
        prob = compute_probability(k, mid)

        if prob >= target_prob:
            right = mid
        else:
            left = mid + 1

    return left

