        return attacks

    def get_king_moves(king_x, king_y):
        moves = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                new_x, new_y = king_x + dx, king_y + dy
                if is_valid(new_x, new_y):
                    moves.append((new_x, new_y))
        return moves

    def is_adjacent(king_x, king_y, black_king_x, black_king_y):
        return abs(king_x - black_king_x) <= 1 and abs(king_y - black_king_y) <= 1

    king_x, king_y = chess_to_coords(king)
    amazon_x, amazon_y = chess_to_coords(amazon)

    attacks = get_amazon_attacks(amazon_x, amazon_y)

    result = [0, 0, 0, 0]  # checkmate, check, stalemate, safe

    # Check all possible black king positions
    for x in range(8):
        for y in range(8):
            # Skip if position is adjacent to white king
            if is_adjacent(king_x, king_y, x, y):
                continue

            # Check if black king is under attack
            is_under_attack = (x, y) in attacks

            # Get possible moves for black king
            king_moves = get_king_moves(x, y)

            # Check if black king can move to any safe square
            can_move = False
            safe_moves = []
            for move_x, move_y in king_moves:
                # Move is safe if it's not adjacent to white king and not under attack
                if not is_adjacent(king_x, king_y, move_x, move_y) and (move_x, move_y) not in attacks:
                    can_move = True
                    safe_moves.append((move_x, move_y))

            if is_under_attack:
                if not can_move:
                    # Checkmate
                    result[0] += 1
                else:
                    # Check
                    result[1] += 1
            else:
                if not can_move:
                    # Stalemate
                    result[2] += 1
                else:
                    # Safe
                    result[3] += 1

    return result

def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    even_count = 0
    odd_count = 0

    for num in range(1, n + 1):
        # Check if num is a palindrome by comparing string with its reverse
        s = str(num)
        if s == s[::-1]:
            # It's a palindrome, check if even or odd
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

from functools import lru_cache

def almost_everywhere_zero(n, k):
    s = str(n)
    digits = [int(d) for d in s]
    n_len = len(digits)

    @lru_cache(maxsize=None)
    def dp(pos, count, tight, started):
        if pos == n_len:
            return 1 if (started and count == k) else 0

        limit = digits[pos] if tight else 9
        result = 0

        for d in range(limit + 1):
            new_tight = tight and (d == limit)
            new_started = started or (d > 0)
            new_count = count + (1 if d > 0 else 0)

            if new_count <= k:
                result += dp(pos + 1, new_count, new_tight, new_started)

        return result

    return dp(0, 0, True, False)

def next_smallest(lst):
