def amazon_check_mate(king, amazon):
    def pos_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def coords_to_pos(x, y):
        return chr(ord('a') + x) + str(y + 1)

    def is_valid(x, y):
        return 0 <= x < 8 and 0 <= y < 8

    def is_attacked(x, y, king_pos, amazon_pos):
        # Check if square (x,y) is attacked by amazon
        ax, ay = amazon_pos
        kx, ky = king_pos

        # Check queen moves (rook + bishop)
        if ax == x or ay == y or abs(ax - x) == abs(ay - y):
            # Check if king blocks the attack
            if (ax == x and kx == x and min(ay, y) < ky < max(ay, y)) or \
               (ay == y and ky == y and min(ax, x) < kx < max(ax, x)) or \
               (abs(ax - x) == abs(ay - y) and 
                abs(ax - kx) == abs(ay - ky) and 
                abs(ax - kx) < abs(ax - x) and 
                abs(ay - ky) < abs(ay - y)):
                return False
            return True

        # Check knight moves
        if (abs(ax - x) == 2 and abs(ay - y) == 1) or (abs(ax - x) == 1 and abs(ay - y) == 2):
            # Check if king blocks the attack
            if abs(ax - kx) <= 1 and abs(ay - ky) <= 1:
                return False
            return True

        return False

    def is_safe(x, y, king_pos, amazon_pos):
        # Check if square (x,y) is safe for black king
        # Not attacked by amazon
        if is_attacked(x, y, king_pos, amazon_pos):
            return False

        # Not adjacent to white king
        kx, ky = king_pos
        if abs(x - kx) <= 1 and abs(y - ky) <= 1:
            return False

        return True

    def get_valid_moves(x, y, king_pos, amazon_pos):
        # Get all valid moves from position (x,y) for black king
        moves = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and is_safe(nx, ny, king_pos, amazon_pos):
                    moves.append((nx, ny))
        return moves

    def get_all_positions():
        positions = []
        for x in range(8):
            for y in range(8):
                positions.append((x, y))
        return positions

    king_pos = pos_to_coords(king)
    amazon_pos = pos_to_coords(amazon)

    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    all_positions = get_all_positions()

    for x, y in all_positions:
        # Skip if position is occupied by white king or amazon
        if (x, y) == king_pos or (x, y) == amazon_pos:
            continue

        # Skip if position is adjacent to white king
        kx, ky = king_pos
        if abs(x - kx) <= 1 and abs(y - ky) <= 1:
            continue

        # Check if black king is attacked by amazon
        if is_attacked(x, y, king_pos, amazon_pos):
            # Check if black king can move to any safe square
            moves = get_valid_moves(x, y, king_pos, amazon_pos)
            if len(moves) == 0:
                # Checkmate
                checkmate += 1
            else:
                # Check
                check += 1
        else:
            # Check if black king is safe and can move
            moves = get_valid_moves(x, y, king_pos, amazon_pos)
            if len(moves) == 0:
                # Stalemate
                stalemate += 1
            else:
                # Safe square with valid moves
                safe += 1

    return [checkmate, check, stalemate, safe]

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part to the given base
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            # Handle negative remainders
            if remainder < 0:
                remainder += base
                temp = (temp - remainder) // base - 1
            else:
                temp = (temp - remainder) // base
            integer_digits.append(remainder)

    # Reverse to get correct order
    integer_digits.reverse()

    # Convert fractional part to the given base
    fractional_digits = []
    if fractional_part > 0:
        temp_fractional = fractional_part
        for _ in range(decimals):
            temp_fractional *= base
            digit = int(temp_fractional)
            fractional_digits.append(digit)
            temp_fractional -= digit

    # Format the result
    if not integer_digits:
        result = "0"
    else:
        result = ""
        for digit in integer_digits:
            if digit < 10:
                result += str(digit)
            else:
                result += chr(ord('A') + digit - 10)

    # Add fractional part if needed
    if decimals > 0:
        result += "."
        for digit in fractional_digits:
            if digit < 10:
                result += str(digit)
            else:
                result += chr(ord('A') + digit - 10)

    # Pad fractional part with zeros if needed
    if decimals > 0:
        current_decimals = len(result.split('.')[1]) if '.' in result else 0
        if current_decimals < decimals:
            result += "0" * (decimals - current_decimals)

    # Handle negative sign
    if negative:
        result = "-" + result

    return result

