def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define unit constants in seconds
    YEAR = 365 * 24 * 60 * 60  # 31536000
    DAY = 24 * 60 * 60         # 86400
    HOUR = 60 * 60             # 3600
    MINUTE = 60                # 60

    # Calculate each unit
    years = seconds // YEAR
    seconds %= YEAR

    days = seconds // DAY
    seconds %= DAY

    hours = seconds // HOUR
    seconds %= HOUR

    minutes = seconds // MINUTE
    seconds %= MINUTE

    # Build components list with proper singular/plural form
    components = []

    if years > 0:
        components.append(f"{years} year{'s' if years != 1 else ''}")

    if days > 0:
        components.append(f"{days} day{'s' if days != 1 else ''}")

    if hours > 0:
        components.append(f"{hours} hour{'s' if hours != 1 else ''}")

    if minutes > 0:
        components.append(f"{minutes} minute{'s' if minutes != 1 else ''}")

    if seconds > 0:
        components.append(f"{seconds} second{'s' if seconds != 1 else ''}")

    # Format with proper separators
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return " and ".join(components)
    else:
        return ", ".join(components[:-1]) + " and " + components[-1]

