def poohbear(code):
    # Preprocess code to build jump table for loops
    jump_table = {}
    stack = []

    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                start = stack.pop()
                jump_table[start] = i
                jump_table[i] = start

    # Initialize memory and interpreter state
    memory = {}
    pointer = 0
    copy_buffer = 0
    output = []
    ip = 0

    while ip < len(code):
        char = code[ip]

        if char == '+':
            memory[pointer] = (memory.get(pointer, 0) + 1) % 256
        elif char == '-':
            memory[pointer] = (memory.get(pointer, 0) - 1) % 256
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copy_buffer = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copy_buffer
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                ip = jump_table[ip]
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                ip = jump_table[ip]
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif char == 'T':
            memory[pointer] = (memory.get(pointer, 0) * 2) % 256
        elif char == 'Q':
            memory[pointer] = (memory.get(pointer, 0) ** 2) % 256
        elif char == 'U':
            import math
            memory[pointer] = int(math.sqrt(memory.get(pointer, 0))) % 256
        elif char == 'L':
            memory[pointer] = (memory.get(pointer, 0) + 2) % 256
        elif char == 'I':
            memory[pointer] = (memory.get(pointer, 0) - 2) % 256
        elif char == 'V':
            if copy_buffer != 0:
                memory[pointer] = (memory.get(pointer, 0) // copy_buffer) % 256
        elif char == 'A':
            memory[pointer] = (memory.get(pointer, 0) + copy_buffer) % 256
        elif char == 'B':
            memory[pointer] = (memory.get(pointer, 0) - copy_buffer) % 256
        elif char == 'Y':
            memory[pointer] = (memory.get(pointer, 0) * copy_buffer) % 256
        elif char == 'D':
            if copy_buffer != 0:
                memory[pointer] = (memory.get(pointer, 0) // copy_buffer) % 256

        ip += 1

    return ''.join(output)

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    gems = list(map(int, lines[1].split()))

    # Precompute palindromes
    is_palindrome = [[False] * n for _ in range(n)]

    # Every single gemstone is a palindrome
    for i in range(n):
        is_palindrome[i][i] = True

    # Check for palindromes of length 2
    for i in range(n - 1):
        if gems[i] == gems[i + 1]:
            is_palindrome[i][i + 1] = True

    # Check for palindromes of length 3 and more
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if gems[i] == gems[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP: dp[i][j] represents minimum seconds to destroy substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Base case: single gemstone requires 1 second
    for i in range(n):
        dp[i][i] = 1

    # Fill DP table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if is_palindrome[i][j]:
                # If the substring is already a palindrome, destroy it in 1 second
                dp[i][j] = 1
            else:
                # Try all possible splits and take minimum
                dp[i][j] = float('inf')
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

