    return arr

def poohbear(code):
    # Pre-process W-E loop pairs
    w_to_e = {}
    e_to_w = {}
    w_stack = []

    for i, char in enumerate(code):
        if char == 'W':
            w_stack.append(i)
        elif char == 'E':
            if w_stack:
                w_pos = w_stack.pop()
                w_to_e[w_pos] = i
                e_to_w[i] = w_pos

    # Initialize interpreter state
    tape = {}  # Dictionary for infinite tape, default 0
    ptr = 0  # Current pointer position
    copied = 0  # Copied value register
    output = []

    def get_cell(pos):
        return tape.get(pos, 0)

    def set_cell(pos, value):
        tape[pos] = value % 256

    def wrap(value):
        return value % 256

    # Execute
    ip = 0  # Instruction pointer

    while ip < len(code):
        cmd = code[ip]

        if cmd == 'W':
            if get_cell(ptr) == 0 and ip in w_to_e:
                ip = w_to_e[ip] + 1
                continue

        elif cmd == 'E':
            if get_cell(ptr) != 0 and ip in e_to_w:
                ip = e_to_w[ip]
                continue

        # Execute all commands (W/E when not jumping become no-ops)
        if cmd == '+':
            set_cell(ptr, get_cell(ptr) + 1)
        elif cmd == '-':
            set_cell(ptr, get_cell(ptr) - 1)
        elif cmd == '>':
            ptr += 1
        elif cmd == '<':
            ptr -= 1
        elif cmd == 'c':
            copied = get_cell(ptr)
        elif cmd == 'p':
            set_cell(ptr, copied)
        elif cmd == 'P':
            output.append(chr(get_cell(ptr)))
        elif cmd == 'N':
            output.append(str(get_cell(ptr)))
        elif cmd == 'T':
            set_cell(ptr, get_cell(ptr) * 2)
        elif cmd == 'Q':
            set_cell(ptr, get_cell(ptr) ** 2)
        elif cmd == 'U':
            set_cell(ptr, int(get_cell(ptr) ** 0.5))
        elif cmd == 'L':
            set_cell(ptr, get_cell(ptr) + 2)
        elif cmd == 'I':
            set_cell(ptr, get_cell(ptr) - 2)
        elif cmd == 'V':
            set_cell(ptr, get_cell(ptr) // 2)
        elif cmd == 'A':
            set_cell(ptr, get_cell(ptr) + copied)
        elif cmd == 'B':
            set_cell(ptr, get_cell(ptr) - copied)
        elif cmd == 'Y':
            set_cell(ptr, get_cell(ptr) * copied)
        elif cmd == 'D':
            if copied != 0:
                set_cell(ptr, get_cell(ptr) // copied)
        # W and E when not jumping are no-ops
        # All other characters are ignored

        ip += 1

    return ''.join(output)

