import re

def differentiate(polynomial, x_value):
    # Pattern to match polynomial terms
    # Matches: optional sign, optional coefficient, optional x, optional exponent
    term_pattern = r'([+-]?)(\d*)(x?)(\^?)(\d*)'

    # Find all terms in the polynomial
    terms = re.findall(term_pattern, polynomial)

    result = 0

    for match in terms:
        sign_str, coeff_str, has_x, exp_str_prefix, exp_str = match

        # Skip empty matches
        if not sign_str and not coeff_str and not has_x and not exp_str:
            continue

        # Handle sign
        sign = 1
        if sign_str == '-':
            sign = -1

        # Determine coefficient
        if coeff_str == '':
            coefficient = 1
        else:
            coefficient = int(coeff_str)
        coefficient *= sign

        # If there's no x, it's a constant term
        if not has_x:
            # Constant term, derivative is 0
            continue

        # Determine exponent
        if exp_str_prefix == '^':
            if exp_str == '':
                exponent = 1
            else:
                exponent = int(exp_str)
        else:
            # No exponent specified means exponent is 1
            exponent = 1

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        # If exponent is 0, term is constant, derivative is 0
        if exponent == 0:
            continue

        # Calculate derivative coefficient: n * a
        derivative_coeff = coefficient * exponent

        # Calculate derivative exponent: n - 1
        derivative_exp = exponent - 1

        # Evaluate at x_value
        if derivative_exp == 0:
            result += derivative_coeff
        elif derivative_exp == 1:
            result += derivative_coeff * x_value
        else:
            result += derivative_coeff * (x_value ** derivative_exp)

    return int(result)

