def poohbear(code):
    memory = {}
    pointer = 0
    copy_register = 0
    output = []

    def get_cell(pos):
        return memory.get(pos, 0)

    def set_cell(pos, val):
        memory[pos] = val % 256

    # Pre-process W and E to create jump pairs
    jump_map = {}
    stack = []
    for i, cmd in enumerate(code):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                w_index = stack.pop()
                jump_map[w_index] = i + 1  # After E
                jump_map[i] = w_index  # Back to W

    # Execute
    ip = 0
    while ip < len(code):
        cmd = code[ip]

        # Skip non-command characters
        if cmd not in '+-><cWpPEQUTLVIBAYD':
            ip += 1
            continue

        # Execute commands
        if cmd == '+':
            set_cell(pointer, get_cell(pointer) + 1)
        elif cmd == '-':
            set_cell(pointer, get_cell(pointer) - 1)
        elif cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == 'c':
            copy_register = get_cell(pointer)
        elif cmd == 'p':
            set_cell(pointer, copy_register)
        elif cmd == 'W':
            if get_cell(pointer) == 0:
                ip = jump_map.get(ip, ip + 1)
                continue
            ip += 1
            continue
        elif cmd == 'E':
            if get_cell(pointer) != 0:
                ip = jump_map.get(ip, ip)
                continue
            ip += 1
            continue
        elif cmd == 'P':
            output.append(chr(get_cell(pointer)))
        elif cmd == 'N':
            output.append(str(get_cell(pointer)))
        elif cmd == 'T':
            set_cell(pointer, get_cell(pointer) * 2)
        elif cmd == 'Q':
            set_cell(pointer, get_cell(pointer) ** 2)
        elif cmd == 'U':
            val = get_cell(pointer)
            set_cell(pointer, int(val ** 0.5))
        elif cmd == 'L':
            set_cell(pointer, get_cell(pointer) + 2)
        elif cmd == 'I':
            set_cell(pointer, get_cell(pointer) - 2)
        elif cmd == 'V':
            val = get_cell(pointer)
            set_cell(pointer, int(val / 2))
        elif cmd == 'A':
            set_cell(pointer, get_cell(pointer) + copy_register)
        elif cmd == 'B':
            set_cell(pointer, get_cell(pointer) - copy_register)
        elif cmd == 'Y':
            set_cell(pointer, get_cell(pointer) * copy_register)
        elif cmd == 'D':
            if copy_register != 0:
                set_cell(pointer, int(get_cell(pointer) / copy_register))
            else:
                set_cell(pointer, 0)

        ip += 1

    return output

