from typing import List, Tuple


def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    def flatten(lst):
        result = []
        for item in lst:
            if isinstance(item, list):
                result.extend(flatten(item))
            else:
                result.append(item)
        return result

    flattened = flatten(numbers)

    if not flattened:
        return (0, 1)

    total_sum = 0
    total_product = 1

    for num in flattened:
        total_sum += num
        total_product *= num

    return (total_sum, total_product)

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
integers that are prime numbers and less than n.
for example:
count_up_to(5) => [2,3]
count_up_to(11) => [2,3,5,7]
count_up_to(0) => []
count_up_to(20) => [2,3,5,7,11,13,17,19]
count_up_to(1) => []
count_up_to(18) => [2,3,5,7,11,13,17]
"""
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    primes = []
    for i in range(2, n):
        if is_prime(i):
            primes.append(i)

    return primes

def is_balanced(s, pairs):
    if not s:
        return True

    # Create a mapping from opening to closing characters
    opening_to_closing = {}
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        opening_to_closing[opening] = closing

    # Stack to keep track of opening characters
    stack = []

    for char in s:
        # If character is an opening character
        if char in opening_to_closing:
            stack.append(char)
        # If character is a closing character
        elif char in opening_to_closing.values():
            # If stack is empty or closing character doesn't match the most recent opening character
            if not stack or opening_to_closing[stack.pop()] != char:
                return False

    # If stack is empty, all characters were matched
    return len(stack) == 0

def histogram(test):
    if not test:
