    # Split the string into letters
    letters = test.split()

    # Count occurrences of each letter
    count_dict = {}
    for letter in letters:
        count_dict[letter] = count_dict.get(letter, 0) + 1

    # Find the maximum count
    max_count = max(count_dict.values())

    # Return all letters with maximum count
    return {letter: count for letter, count in count_dict.items() if count == max_count}

def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # For 2^n - 1 to be a Mersenne prime, n must be prime
    if not is_prime(n):
        return False

    # Calculate 2^n - 1
    mersenne_number = (1 << n) - 1

    # Check if the Mersenne number is prime
    return is_prime(mersenne_number)

def compare(selector1, selector2):
    def parse_selector(s):
        ids = 0
        classes = 0
        tags = 0

        parts = s.split()

        for part in parts:
            if part == '*':
                continue

            ids += part.count('#')
            classes += part.count('.')

            # Check if there's a tagname (alphanumeric at the start, before # or .)
            if part and part[0] not in '#.':
                tags += 1

        return (ids, classes, tags)

    spec1 = parse_selector(selector1)
    spec2 = parse_selector(selector2)

    # Compare specificity: (ids, classes, tags) in order of importance
    if spec1 > spec2:
        return selector1
    elif spec2 > spec1:
        return selector2
    else:
        # If all counts are equal, return the later appearing selector
        return selector2

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    c = list(map(int, lines[1].split()))

    # dp[i][j] represents minimum seconds to destroy substring from i to j (inclusive)
    dp = [[0] * n for _ in range(n)]

    # Fill dp table for all substring lengths from 1 to n
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if i == j:
                # Single gemstone requires 1 second
                dp[i][j] = 1
            elif i + 1 == j:
                # Two gemstones
                if c[i] == c[j]:
                    # Same colors, can remove together in 1 second
                    dp[i][j] = 1
                else:
                    # Different colors, need 2 seconds
                    dp[i][j] = 2
            else:
                # More than 2 gemstones
                # Initialize with the case where we split at every possible point
                dp[i][j] = dp[i][j-1] + 1  # Remove last one separately

                # Try all possible splits
                for k in range(i, j):
                    if c[i] == c[k]:
                        # If first and k-th gemstones have same color,
                        # we can remove substring i to k and k+1 to j together
                        dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j])

    print(dp[0][n-1])

