def poohbear(code):
    # Preprocess to build W/E jump mappings
    jump_map = {}
    stack = []

    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                start = stack.pop()
                jump_map[start] = i
                jump_map[i] = start

    # Initialize memory, pointer, and copy register
    memory = {}
    pointer = 0
    copy_register = 0
    ip = 0
    output = []

    while ip < len(code):
        char = code[ip]

        if char == '+':
            memory[pointer] = (memory.get(pointer, 0) + 1) % 256
        elif char == '-':
            memory[pointer] = (memory.get(pointer, 0) - 1) % 256
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copy_register = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copy_register
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                ip = jump_map[ip]
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                ip = jump_map[ip]
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif char == 'T':
            memory[pointer] = (memory.get(pointer, 0) * 2) % 256
        elif char == 'Q':
            memory[pointer] = (memory.get(pointer, 0) ** 2) % 256
        elif char == 'U':
            val = memory.get(pointer, 0)
            if val == 0:
                memory[pointer] = 0
            else:
                # Integer square root
                low, high = 0, val
                while low <= high:
                    mid = (low + high) // 2
                    if mid * mid == val:
                        memory[pointer] = mid
                        break
                    elif mid * mid < val:
                        memory[pointer] = mid
                        low = mid + 1
                    else:
                        high = mid - 1
        elif char == 'L':
            memory[pointer] = (memory.get(pointer, 0) + 2) % 256
        elif char == 'I':
            memory[pointer] = (memory.get(pointer, 0) - 2) % 256
        elif char == 'V':
            val = memory.get(pointer, 0)
            memory[pointer] = val // 2
        elif char == 'A':
            val = memory.get(pointer, 0)
            memory[pointer] = (val + copy_register) % 256
        elif char == 'B':
            val = memory.get(pointer, 0)
            memory[pointer] = (val - copy_register) % 256
        elif char == 'Y':
            val = memory.get(pointer, 0)
            memory[pointer] = (val * copy_register) % 256
        elif char == 'D':
            val = memory.get(pointer, 0)
            if copy_register != 0:
                memory[pointer] = val // copy_register
            else:
                memory[pointer] = 0

        ip += 1

    return ''.join(output)

def is_balanced(string, pairs):
    opening_to_closing = {}
    closing_to_opening = {}

    # Parse pairs string to build mappings
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        opening_to_closing[opening] = closing
        closing_to_opening[closing] = opening

    stack = []

    for char in string:
        # If char is a closing character that matches the top of stack, pop
        if char in closing_to_opening:
            if stack and stack[-1] == closing_to_opening[char]:
                stack.pop()
                continue

        # Otherwise, if char is an opening character, push to stack
        if char in opening_to_closing:
            stack.append(char)

    # Stack must be empty for balanced string
    return len(stack) == 0

