        # If it's a closing character
        elif char in close_to_open:
            # If stack is empty, there's no matching opening character
            if not stack:
                return False

            # Pop the last opening character
            last_open = stack.pop()

            # Check if it matches the current closing character
            if open_to_close[last_open] != char:
                return False

    # If stack is empty, all characters were properly matched
    return len(stack) == 0

def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        # Check if the number is a palindrome
        if str(i) == str(i)[::-1]:
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def exchange_sort(sequence):
    # Create target sorted sequence
    target = sorted(sequence)

    # Create a mapping from value to its target positions
    from collections import defaultdict
    target_positions = defaultdict(list)
    for i, val in enumerate(target):
        target_positions[val].append(i)

    # Create a mapping from current positions to target positions
    position_map = {}
    for i, val in enumerate(sequence):
        if target_positions[val]:
            position_map[i] = target_positions[val].pop(0)

    # Find cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i] and i in position_map:
            # Start a new cycle
            cycles += 1
            current = i
            while not visited[current]:
                visited[current] = True
                current = position_map[current]

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """

    def is_prime(num):
        # Handle edge cases
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False

        # Check odd divisors up to sqrt(num)
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    # Main logic: return x if n is prime, otherwise return y
    if is_prime(n):
        return x
    else:
        return y

