def compare(selector1, selector2):
    def calculate_specificity(selector):
        ids = 0
        classes = 0
        tags = 0

        # Split by spaces to get each part (descendant combinators)
        parts = selector.split()

        for part in parts:
            part = part.strip()
            if not part:
                continue

            # Count ID selectors (#)
            ids += part.count('#')

            # Count class selectors (.)
            classes += part.count('.')

            # Check if there's a tag name
            # A tag name is an alphanumeric identifier at the start
            # (before any # or .)
            i = 0
            if i < len(part) and part[i].isalpha():
                tags += 1

        return (ids, classes, tags)

    spec1 = calculate_specificity(selector1)
    spec2 = calculate_specificity(selector2)

    # Compare: IDs first, then classes, then tags
    if spec1[0] > spec2[0]:
        return selector1
    elif spec1[0] < spec2[0]:
        return selector2
    elif spec1[1] > spec2[1]:
        return selector1
    elif spec1[1] < spec2[1]:
        return selector2
    elif spec1[2] > spec2[2]:
        return selector1
    elif spec1[2] < spec2[2]:
        return selector2
    else:
        # All equal, the later one wins (selector2)
        return selector2

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    result = []

    if integer_part == 0:
        result = ['0']
    else:
        while integer_part > 0:
            remainder = integer_part % base
            integer_part = integer_part // base

            # Handle negative remainders
            if remainder < 0:
                remainder += base
                integer_part += 1

            # Convert remainder to digit
            if remainder >= 10:
                digit = chr(ord('A') + int(remainder) - 10)
            else:
                digit = str(int(remainder))
            result.append(digit)

    # Reverse to get correct order
    result.reverse()

    # Handle fractional part
    fractional_part = number - int(number)
    if decimals > 0:
        decimal_result = []
        for _ in range(decimals):
            fractional_part *= base
            digit_value = int(fractional_part)

            # Handle negative digits
            if digit_value < 0:
                digit_value += base
                fractional_part += base

            if digit_value >= 10:
                digit = chr(ord('A') + digit_value - 10)
            else:
                digit = str(digit_value)
            decimal_result.append(digit)
            fractional_part -= digit_value

        if decimal_result:
            result.append('.')
            result.extend(decimal_result)

    # Join the result
    final_result = ''.join(result)

    # Add negative sign if needed
    if negative and final_result != '0':
        final_result = '-' + final_result

    # Ensure leading zero for numbers < 1
    if '.' in final_result and final_result.startswith('0.'):
        pass  # Already correct
    elif '.' in final_result and not final_result.startswith('0.'):
        # Check if we need to add leading zero
        integer_part_str = final_result.split('.')[0]
        if integer_part_str == '':
            final_result = '0' + final_result

    return final_result

def compare_one(a, b):
    def to_numeric(value):
        if isinstance(value, (int, float)):
            return float(value)
        elif isinstance(value, str):
            # Replace comma with dot for decimal separator
            normalized = value.replace(',', '.')
            return float(normalized)
        else:
            raise TypeError("Unsupported type")

    def is_equal(val1, val2):
        return abs(val1 - val2) < 1e-10

    num_a = to_numeric(a)
    num_b = to_numeric(b)

    if is_equal(num_a, num_b):
        return None

    if num_a > num_b:
        return a
    else:
        return b

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    gems = list(map(int, lines[1].split()))

    # Precompute palindrome information
    is_palindrome = [[False] * n for _ in range(n)]

    # Every single gemstone is a palindrome
    for i in range(n):
        is_palindrome[i][i] = True

    # Fill the palindrome table
    for length in range(2, n + 1):  # length of substring
        for i in range(n - length + 1):
            j = i + length - 1
            if gems[i] == gems[j]:
                if length == 2:
                    is_palindrome[i][j] = True
                else:
                    is_palindrome[i][j] = is_palindrome[i + 1][j - 1]

    # DP table: dp[i][j] = minimum seconds to destroy substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Base case: single gemstones require 1 second
    for i in range(n):
        dp[i][i] = 1

    # Fill DP table for substrings of increasing length
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if is_palindrome[i][j]:
                # If the entire substring is palindrome, we can remove it in 1 second
                dp[i][j] = 1
            else:
                # Otherwise, try all possible splits and take minimum
                dp[i][j] = float('inf')
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

