def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    if n <= 2:
        return []

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    primes = []
    for i in range(2, n):
        if is_prime(i):
            primes.append(i)

    return primes

def getAllPrimeFactors(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    if not isinstance(n, int) or n <= 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)
    unique_factors = []
    counts = []

    if factors:
        current_factor = factors[0]
        count = 0

        for factor in factors:
            if factor == current_factor:
                count += 1
            else:
                unique_factors.append(current_factor)
                counts.append(count)
                current_factor = factor
                count = 1

        unique_factors.append(current_factor)
        counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    factor_count_pairs = zip(*getUniquePrimeFactorsWithCount(n))
    products = []

    for factor, count in factor_count_pairs:
        products.append(factor ** count)

    return products

