        ax, ay = amazon_pos
        kx, ky = king_pos

        # Check if square (x,y) is attacked by amazon
        # Queen moves (rook + bishop)
        if x == ax or y == ay or abs(x - ax) == abs(y - ay):
            # Check if square is blocked by king
            if (x == kx and y == ky) or (x == ax and y == ay):
                return False
            return True
        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            if x == ax + dx and y == ay + dy:
                # Check if square is blocked by king
                if (x == kx and y == ky) or (x == ax and y == ay):
                    return False
                return True
        return False

    def is_safe(x, y, king_pos, amazon_pos):
        # Check if square is safe (not attacked by amazon)
        if is_attacked(x, y, king_pos, amazon_pos):
            return False
        # Check if square is adjacent to king
        kx, ky = king_pos
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                if x == kx + dx and y == ky + dy:
                    return False
        return True

    def get_valid_moves(x, y, king_pos, amazon_pos):
        moves = []
        kx, ky = king_pos
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and not (nx == kx and ny == ky):
                    if not is_attacked(nx, ny, king_pos, amazon_pos):
                        moves.append((nx, ny))
        return moves

    king_pos = pos_to_coords(king)
    amazon_pos = pos_to_coords(amazon)

    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    for x in range(8):
        for y in range(8):
            # Skip if square is occupied by white king or amazon
            if (x, y) == king_pos or (x, y) == amazon_pos:
                continue

            # Check if square is attacked by amazon
            if is_attacked(x, y, king_pos, amazon_pos):
                # Check if king can move to any adjacent square
                moves = get_valid_moves(x, y, king_pos, amazon_pos)
                if len(moves) == 0:
                    # Stalemate - king is safe but cannot move
                    stalemate += 1
                else:
                    # Check - king is under attack but can move
                    check += 1
            else:
                # Square is safe
                # Check if king can move to any adjacent square
                moves = get_valid_moves(x, y, king_pos, amazon_pos)
                if len(moves) == 0:
                    # Stalemate - king is safe but cannot move
                    stalemate += 1
                else:
                    # Safe - king is safe and can move
                    safe += 1

    # Recheck the positions to properly categorize
    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    for x in range(8):
        for y in range(8):
            # Skip if square is occupied by white king or amazon
            if (x, y) == king_pos or (x, y) == amazon_pos:
                continue

            # Check if square is attacked by amazon
            if is_attacked(x, y, king_pos, amazon_pos):
                # King is under attack
                # Check if king can move to any adjacent square
                moves = get_valid_moves(x, y, king_pos, amazon_pos)
                if len(moves) == 0:
                    # King cannot move anywhere - checkmate
                    checkmate += 1
                else:
                    # King can move but is under attack - check
                    check += 1
            else:
                # Square is safe
                # Check if king can move to any adjacent square
                moves = get_valid_moves(x, y, king_pos, amazon_pos)
                if len(moves) == 0:
                    # King is safe but cannot move - stalemate
                    stalemate += 1
                else:
                    # King is safe and can move - safe
                    safe += 1

    return [checkmate, check, stalemate, safe]

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Split the input string by whitespace to extract letters
    letters = test.split()

    # Handle empty string or whitespace-only string
    if not letters:
        return {}

    # Count frequency of each letter
    counts = {}
    for letter in letters:
        counts[letter] = counts.get(letter, 0) + 1

    # Find the maximum frequency
    max_count = max(counts.values())

    # Filter letters that match the maximum frequency
    result = {char: count for char, count in counts.items() if count == max_count}

    return result

def string_xor(a, b):
    # Pad the shorter string with leading zeros to match lengths
    max_len = max(len(a), len(b))
    a = a.zfill(max_len)
    b = b.zfill(max_len)

    # Perform XOR operation bit by bit
    result = []
    for i in range(max_len):
        # XOR: same bits give '0', different bits give '1'
        if a[i] == b[i]:
            result.append('0')
        else:
            result.append('1')

    return ''.join(result)

def amazon_check_mate(king, amazon):
    def parse_pos(pos):
        col = ord(pos[0]) - ord('a')
        row = int(pos[1]) - 1
        return (col, row)

    w_king = parse_pos(king)
    w_amazon = parse_pos(amazon)

    # Squares attacked by amazon (queen + knight moves)
    amazon_attacks = set()
    aw, ah = w_amazon

    # Queen moves (horizontal, vertical, diagonal)
    for d_col in [-1, 0, 1]:
        for d_row in [-1, 0, 1]:
            if d_col == 0 and d_row == 0:
                continue
            col, row = aw + d_col, ah + d_row
            while 0 <= col < 8 and 0 <= row < 8:
                amazon_attacks.add((col, row))
                col += d_col
                row += d_row

    # Knight moves
    knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
                    (1, -2), (1, 2), (2, -1), (2, 1)]
    for dc, dr in knight_moves:
        col, row = aw + dc, ah + dr
        if 0 <= col < 8 and 0 <= row < 8:
            amazon_attacks.add((col, row))

    # Squares adjacent to white king (black king cannot be here)
    white_king_adj = set()
    for d_col in [-1, 0, 1]:
        for d_row in [-1, 0, 1]:
            if d_col == 0 and d_row == 0:
                continue
            col, row = w_king[0] + d_col, w_king[1] + d_row
            if 0 <= col < 8 and 0 <= row < 8:
                white_king_adj.add((col, row))

    checkmate = 0
    check = 0
    stalemate = 0
    safe_with_moves = 0

    for col in range(8):
        for row in range(8):
            if (col, row) == w_king:
                continue
            if (col, row) == w_amazon:
                continue
            if (col, row) in white_king_adj:
                continue

            is_attacked = (col, row) in amazon_attacks
            can_escape = False

            for d_col in [-1, 0, 1]:
                for d_row in [-1, 0, 1]:
                    if d_col == 0 and d_row == 0:
                        continue
                    new_col, new_row = col + d_col, row + d_row
                    if not (0 <= new_col < 8 and 0 <= new_row < 8):
                        continue
                    if (new_col, new_row) == w_king:
                        continue
                    if (new_col, new_row) == w_amazon:
                        continue
                    if (new_col, new_row) in white_king_adj:
                        continue
                    if (new_col, new_row) in amazon_attacks:
                        continue
                    can_escape = True
                    break
                if can_escape:
                    break

            if is_attacked and not can_escape:
                checkmate += 1
            elif is_attacked and can_escape:
                check += 1
            elif not is_attacked and not can_escape:
                stalemate += 1
            else:
                safe_with_moves += 1

    return [checkmate, check, stalemate, safe_with_moves]

def smallest_change(arr):
    count = 0
    n = len(arr)
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            count += 1
    return count

def poohbear(code):
    import math

    # Memory tape - dictionary with infinite memory, defaults to 0
    memory = {}
    pointer = 0
    copied = 0
    output = []

    # Filter only valid commands
    valid_commands = set('+-><cpWENPQTULIYVAD')
    code = ''.join(c for c in code if c in valid_commands)

    # Build loop matching (W <-> E pairs)
    loop_pairs = {}
    stack = []
    for i, cmd in enumerate(code):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                w_pos = stack.pop()
                loop_pairs[w_pos] = i
                loop_pairs[i] = w_pos

    # Execute the code
    ip = 0
    while ip < len(code):
        cmd = code[ip]

        if cmd == '+':
            val = memory.get(pointer, 0) + 1
            memory[pointer] = val % 256
            ip += 1

        elif cmd == '-':
            val = memory.get(pointer, 0) - 1
            memory[pointer] = val % 256
            ip += 1

        elif cmd == '>':
            pointer += 1
            ip += 1

        elif cmd == '<':
            pointer -= 1
            ip += 1

        elif cmd == 'c':
            copied = memory.get(pointer, 0)
            ip += 1

        elif cmd == 'p':
            memory[pointer] = copied % 256
            ip += 1

        elif cmd == 'W':
            val = memory.get(pointer, 0)
            if val == 0:
                ip = loop_pairs.get(ip, ip) + 1
            else:
                ip += 1

        elif cmd == 'E':
            val = memory.get(pointer, 0)
            if val != 0:
                ip = loop_pairs.get(ip, ip)
            else:
                ip += 1

        elif cmd == 'P':
            output.append(chr(memory.get(pointer, 0)))
            ip += 1

        elif cmd == 'N':
            output.append(str(memory.get(pointer, 0)))
            ip += 1

        elif cmd == 'T':
            val = memory.get(pointer, 0) * 2
            memory[pointer] = val % 256
            ip += 1

        elif cmd == 'Q':
            val = memory.get(pointer, 0) ** 2
            memory[pointer] = val % 256
            ip += 1

        elif cmd == 'U':
            val = int(math.sqrt(memory.get(pointer, 0)))
            memory[pointer] = val % 256
            ip += 1

        elif cmd == 'L':
            val = memory.get(pointer, 0) + 2
            memory[pointer] = val % 256
            ip += 1

        elif cmd == 'I':
            val = memory.get(pointer, 0) - 2
            memory[pointer] = val % 256
            ip += 1

        elif cmd == 'V':
            val = memory.get(pointer, 0) // 2
            memory[pointer] = val % 256
            ip += 1

        elif cmd == 'A':
            val = memory.get(pointer, 0) + copied
            memory[pointer] = val % 256
            ip += 1

        elif cmd == 'B':
            val = memory.get(pointer, 0) - copied
            memory[pointer] = val % 256
            ip += 1

        elif cmd == 'Y':
            val = memory.get(pointer, 0) * copied
            memory[pointer] = val % 256
            ip += 1

        elif cmd == 'D':
            if copied == 0:
                memory[pointer] = 0
            else:
                val = memory.get(pointer, 0) // copied
                memory[pointer] = val % 256
            ip += 1

    return ''.join(output)

def separate_paren_groups(s):
    s = s.replace(' ', '')
    result = []
    current_group = ""
    balance = 0

    for char in s:
        if char == '(':
            current_group += char
            balance += 1
        elif char == ')':
            current_group += char
            balance -= 1

            if balance == 0:
                result.append(current_group)
                current_group = ""

    return result

def next_smallest(lst):
    if not lst:
        return None

    # Use a set to get unique values and then sort them
    unique_values = sorted(set(lst))

    # If we have less than 2 unique values, return None
    if len(unique_values) < 2:
        return None

    # Return the second smallest unique value
    return unique_values[1]

def correct_bracketing(brackets: str):
    counter = 0
    for char in brackets:
        if char == '(':
            counter += 1
        elif char == ')':
            counter -= 1
        if counter < 0:
            return False
    return counter == 0

def cycpattern_check(a, b):
    # Handle edge cases
    if not b:
        return True
    if not a:
        return False
    if len(b) > len(a):
        return False

    # Create a string that contains all rotations of b
    # If b is a rotation of some substring of a, then b will appear in a+a
    # But we need to check all substrings of a with length len(b)
    doubled_b = b + b

    # Check each substring of a with length equal to b
    for i in range(len(a) - len(b) + 1):
        substring = a[i:i + len(b)]
        # Check if substring is a rotation of b
        # A string is a rotation of another if it appears in the concatenation of the other with itself
        if substring in doubled_b:
            return True

    return False

def parse_int(s):
    # Normalize input: lowercase, remove "and", replace hyphens with spaces
    s = s.lower()
    s = s.replace("and", "")
    s = s.replace("-", " ")

    # Split into words and filter empty strings
    words = [w for w in s.split() if w]

    if not words:
        return 0

    # Number mappings
    units = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    teens = {
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16,
        'seventeen': 17, 'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    scales = {
        'hundred': 100, 'thousand': 1000, 'million': 1000000
    }

    total = 0
    current = 0

    for word in words:
        if word in units:
            current += units[word]
        elif word in teens:
            current += teens[word]
        elif word in tens:
            current += tens[word]
        elif word in scales:
            if word == 'hundred':
                current *= scales[word]
            else:
                total += current * scales[word]
                current = 0

    total += current
    return total

def valid_mersenne(n):
    # Handle edge cases
    if n <= 1:
        return False

    # Check if n is prime (necessary condition for Mersenne prime)
    if not is_prime(n):
        return False

    # For Mersenne primes, we need to check if 2^n - 1 is prime
    # Using Lucas-Lehmer test for Mersenne numbers
    # This is the most efficient way to test Mersenne primality
    if n == 2:
        return True

    # Lucas-Lehmer test
    # For Mersenne numbers 2^p - 1 where p is prime
    m = (1 << n) - 1  # This is 2^n - 1

    # Special case for n = 2
    if n == 2:
        return True

    # Lucas-Lehmer test
    s = 4
    for i in range(n - 2):
        s = (s * s - 2) % m

    return s == 0

def is_prime(n):
    """Check if a number is prime using trial division up to sqrt(n)"""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def file_name_check(file_name):
    # Count digits
    digit_count = 0
    for char in file_name:
        if char.isdigit():
            digit_count += 1
    if digit_count > 3:
        return 'No'

    # Check for exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    # Split by dot
    parts = file_name.split('.')
    name_part = parts[0]
    extension = parts[1]

    # Check if both parts are non-empty
    if not name_part or not extension:
        return 'No'

    # Check if first character is a letter
    if not name_part[0].isalpha():
        return 'No'

    # Check if extension is valid
    valid_extensions = ['txt', 'exe', 'dll']
    if extension not in valid_extensions:
        return 'No'

    return 'Yes'

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    colors = list(map(int, lines[1].split()))

    # Precompute whether substring from i to j is palindrome
    is_palindrome = [[False] * n for _ in range(n)]

    # Every single character is a palindrome
    for i in range(n):
        is_palindrome[i][i] = True

    # Check for palindromes of length 2
    for i in range(n - 1):
        if colors[i] == colors[i + 1]:
            is_palindrome[i][i + 1] = True

    # Check for palindromes of length 3 and more
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if colors[i] == colors[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP: dp[i][j] represents minimum seconds to destroy substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Fill DP table
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if i == j:
                # Single gemstone requires 1 second
                dp[i][j] = 1
            elif i + 1 == j:
                # Two gemstones - if they are same color, one second, otherwise two seconds
                if colors[i] == colors[j]:
                    dp[i][j] = 1
                else:
                    dp[i][j] = 2
            else:
                # For longer substrings, either:
                # 1. Remove the entire substring if it's palindrome (1 second)
                # 2. Split at some point and sum up the parts
                if is_palindrome[i][j]:
                    dp[i][j] = 1
                else:
                    # Try all possible splits
                    dp[i][j] = float('inf')
                    for k in range(i, j):
                        dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

