    return False

def palindrome(num):
    if not isinstance(num, int) or num < 0:
        return "Not valid"

    str_num = str(num)
    return str_num == str_num[::-1]

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    if not lines or not lines[0].strip():
        return

    first_line = lines[0].split()
    n = int(first_line[0])
    M = int(first_line[1])

    points = []
    for i in range(1, n + 1):
        if i < len(lines):
            x, y = map(int, lines[i].split())
            points.append((x, y))

    # For each point, calculate the Manhattan distance to all other points
    # and count how many points are within distance M
    count = 0
    for i in range(n):
        for j in range(n):
            if i != j:
                distance = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
