    # Handle empty string case
    if not txt:
        return False

    # Check if last character is alphabetical
    if not txt[-1].isalpha():
        return False

    # Check if last character is part of a word
    if len(txt) == 1:
        # Single character string is a standalone word
        return True
    elif txt[-2] == ' ':
        # Space before last char means it's a standalone word
        return True
    else:
        # Last char is part of the preceding word
        return False

def parse_nested_parens(s):
    if not s:
        return []

    groups = s.split()
    result = []

    for group in groups:
        current_level = 0
        max_level = 0

        for char in group:
            if char == '(':
                current_level += 1
                max_level = max(max_level, current_level)
            elif char == ')':
                current_level -= 1

        result.append(max_level)

    return result

