            if (r, c) == white_king or (r, c) == amazon_pos:
                continue
            if is_adjacent((r, c), white_king):
                continue
            if not is_attacked_by_amazon((r, c)):
                return True
        return False

    checkmates = 0
    checks = 0
    stalemates = 0
    safe_moves = 0

    for row in range(8):
        for col in range(8):
            pos = (row, col)
            if pos == white_king or pos == amazon_pos:
                continue
            if is_adjacent(pos, white_king):
                continue

            attacked = is_attacked_by_amazon(pos)
            valid_move = has_valid_move(pos)

            if attacked and not valid_move:
                checkmates += 1
            elif attacked and valid_move:
                checks += 1
            elif not attacked and not valid_move:
                stalemates += 1
            else:
                safe_moves += 1

    return [checkmates, checks, stalemates, safe_moves]

def order_by_points(nums):
    """
