    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def poohbear(code):
    MAX_ITERATIONS = 1000000

    # Pre-process to build W-E maps
    w_to_e = {}
    e_to_w = {}
    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                w_pos = stack.pop()
                w_to_e[w_pos] = i
                e_to_w[i] = w_pos

    # Initialize state
    memory = {}
    pointer = 0
    copied_value = 0
    ip = 0
    output = []

    def wrap(val):
        return val % 256

    def floor_div(a, b):
        if b == 0:
            return 0
        return a // b

    iterations = 0
    while ip < len(code) and iterations < MAX_ITERATIONS:
        iterations += 1
        cmd = code[ip]

        if cmd == '+':
            memory[pointer] = wrap(memory.get(pointer, 0) + 1)
            ip += 1
        elif cmd == '-':
            memory[pointer] = wrap(memory.get(pointer, 0) - 1)
            ip += 1
        elif cmd == '>':
            pointer += 1
            ip += 1
        elif cmd == '<':
            pointer -= 1
            ip += 1
        elif cmd == 'c':
            copied_value = memory.get(pointer, 0)
            ip += 1
        elif cmd == 'p':
            memory[pointer] = copied_value
            ip += 1
        elif cmd == 'W':
            if ip in w_to_e:
                if memory.get(pointer, 0) == 0:
                    ip = w_to_e[ip] + 1
                else:
                    ip += 1
            else:
                ip += 1
        elif cmd == 'E':
            if ip in e_to_w:
                if memory.get(pointer, 0) != 0:
                    ip = e_to_w[ip]
                else:
                    ip += 1
            else:
                ip += 1
        elif cmd == 'P':
            output.append(chr(memory.get(pointer, 0)))
            ip += 1
        elif cmd == 'N':
            output.append(str(memory.get(pointer, 0)))
            ip += 1
        elif cmd == 'T':
            memory[pointer] = wrap(memory.get(pointer, 0) * 2)
            ip += 1
        elif cmd == 'Q':
            memory[pointer] = wrap(memory.get(pointer, 0) ** 2)
            ip += 1
        elif cmd == 'U':
            memory[pointer] = wrap(int(memory.get(pointer, 0) ** 0.5))
            ip += 1
        elif cmd == 'L':
            memory[pointer] = wrap(memory.get(pointer, 0) + 2)
            ip += 1
        elif cmd == 'I':
            memory[pointer] = wrap(memory.get(pointer, 0) - 2)
            ip += 1
        elif cmd == 'V':
            memory[pointer] = floor_div(memory.get(pointer, 0), 2)
            ip += 1
        elif cmd == 'A':
            memory[pointer] = wrap(memory.get(pointer, 0) + copied_value)
            ip += 1
        elif cmd == 'B':
            memory[pointer] = wrap(memory.get(pointer, 0) - copied_value)
            ip += 1
        elif cmd == 'Y':
            memory[pointer] = wrap(memory.get(pointer, 0) * copied_value)
            ip += 1
        elif cmd == 'D':
            memory[pointer] = floor_div(memory.get(pointer, 0), copied_value)
            ip += 1
        else:
            ip += 1

    return ''.join(output)

