    open_to_close = {}
    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        open_to_close[open_char] = close_char

    # Create a set of closing characters for quick lookup
    close_chars = set(open_to_close.values())

    # Stack to track opening characters
    stack = []

    for char in string:
        # If it's an opening character, push it onto the stack
        if char in open_to_close:
