        elif char in close_chars:
            # If stack is empty or the closing character doesn't match the most recent opening character
            if not stack or open_to_close[stack.pop()] != char:
                return False

    # All characters are balanced if the stack is empty
    return len(stack) == 0

def choose(n, k):
    # Handle edge cases
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry property: C(n, k) = C(n, n-k)
    k = min(k, n - k)

    # Iterative computation to avoid large factorials
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

def exchange_sort(sequence):
    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for val in sequence:
        count[val] += 1

    # Create target array
    target = []
    target.extend([7] * count[7])
    target.extend([8] * count[8])
    target.extend([9] * count[9])

    # Create a mapping from value to its target positions
    target_positions = {7: [], 8: [], 9: []}
    for i, val in enumerate(target):
        target_positions[val].append(i)

    # Create a mapping from each position to what value should be there
    position_to_target = {}
    for i, val in enumerate(target):
        position_to_target[i] = val

    # Create a mapping from current value to its target positions
    current_positions = {7: [], 8: [], 9: []}
    for i, val in enumerate(sequence):
        current_positions[val].append(i)

    # Create permutation array - where each element should go
    perm = [0] * len(sequence)
    for i, val in enumerate(sequence):
        # Find the first unused position for this value in target
        target_pos = target_positions[val].pop(0)
        perm[i] = target_pos

    # Find cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i]:
            # Start a new cycle
            cycle_length = 0
            current = i
            while not visited[current]:
                visited[current] = True
                current = perm[current]
                cycle_length += 1
            if cycle_length > 0:
                cycles += 1

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

def differentiate(polynomial, x):
    # Normalize the polynomial string by ensuring we can split terms correctly
    # Add explicit + before any - that is not at the start (to handle negative terms)
    poly = polynomial
    for i in range(1, len(poly)):
        if poly[i] == '-' and poly[i-1] not in '^0123456789':
            poly = poly[:i] + '+' + poly[i:]

    terms = poly.split('+')
    derivative = 0

    for term in terms:
        if not term or term == '' or term == '+':
            continue

        # Determine sign
        sign = 1
        start_idx = 0
        if term[0] == '-':
            sign = -1
            start_idx = 1
        elif term[0] == '+':
            sign = 1
            start_idx = 1

        term = term[start_idx:]

        if not term:
            continue

        # If term doesn't contain x, it's a constant - derivative is 0
        if 'x' not in term:
            continue

        # Split into coefficient part and exponent part
        if '^' in term:
            coeff_part, exp_part = term.split('^')
            exponent = int(exp_part)
        else:
            coeff_part = term
            exponent = 1

        # Extract coefficient
        if coeff_part == '' or coeff_part == 'x':
            coefficient = 1
        elif coeff_part == '-x':
            coefficient = -1
        elif 'x' in coeff_part:
            # There's a number before x
            idx = coeff_part.index('x')
            num_part = coeff_part[:idx]
            if num_part == '' or num_part == '+':
                coefficient = 1
            elif num_part == '-':
                coefficient = -1
            else:
                coefficient = int(num_part)
        else:
            coefficient = int(coeff_part)

        coefficient *= sign

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent > 0:
            derivative += exponent * coefficient * (x ** (exponent - 1))

    return derivative

