def poohbear(code):
    valid_commands = {'+', '-', '>', '<', 'c', 'p', 'W', 'E', 'P', 'N', 
                      'T', 'Q', 'U', 'L', 'I', 'V', 'A', 'B', 'Y', 'D'}
    commands = [c for c in code if c in valid_commands]

    jump_map = {}
    w_stack = []
    for i, cmd in enumerate(commands):
        if cmd == 'W':
            w_stack.append(i)
        elif cmd == 'E':
            if w_stack:
                w_idx = w_stack.pop()
                jump_map[w_idx] = i
                jump_map[i] = w_idx

    cells = {}
    pointer = 0
    copy_register = 0
    pc = 0
    output = []

    def wrap(value):
        return value % 256

    while pc < len(commands):
        cmd = commands[pc]
        current = cells.get(pointer, 0)

        if cmd == '+':
            cells[pointer] = wrap(current + 1)
            pc += 1
        elif cmd == '-':
            cells[pointer] = wrap(current - 1)
            pc += 1
        elif cmd == '>':
            pointer += 1
            pc += 1
        elif cmd == '<':
            pointer -= 1
            pc += 1
        elif cmd == 'c':
            copy_register = current
            pc += 1
        elif cmd == 'p':
            cells[pointer] = copy_register
            pc += 1
        elif cmd == 'W':
            if current == 0:
                pc = jump_map.get(pc, pc) + 1
            else:
                pc += 1
        elif cmd == 'E':
            if current != 0:
                pc = jump_map.get(pc, pc)
            else:
                pc += 1
        elif cmd == 'P':
            output.append(chr(current))
            pc += 1
        elif cmd == 'N':
            output.append(str(current))
            pc += 1
        elif cmd == 'T':
            cells[pointer] = wrap(current * 2)
            pc += 1
        elif cmd == 'Q':
            cells[pointer] = wrap(current * current)
            pc += 1
        elif cmd == 'U':
            cells[pointer] = wrap(int(current ** 0.5))
            pc += 1
        elif cmd == 'L':
            cells[pointer] = wrap(current + 2)
            pc += 1
        elif cmd == 'I':
            cells[pointer] = wrap(current - 2)
            pc += 1
        elif cmd == 'V':
            cells[pointer] = wrap(current // 2)
            pc += 1
        elif cmd == 'A':
            cells[pointer] = wrap(current + copy_register)
            pc += 1
        elif cmd == 'B':
            cells[pointer] = wrap(current - copy_register)
            pc += 1
        elif cmd == 'Y':
            cells[pointer] = wrap(current * copy_register)
            pc += 1
        elif cmd == 'D':
            if copy_register != 0:
                cells[pointer] = wrap(current // copy_register)
            else:
                cells[pointer] = 0
            pc += 1

    return ''.join(output)

