    copied_value = 0

    # Process code to find loop pairs
    loops = []
    loop_stack = []
    for i, char in enumerate(code):
        if char == 'W':
            loop_stack.append(i)
        elif char == 'E':
            start = loop_stack.pop()
            loops.append((start, i))

    # Create loop mapping
    loop_map = {}
    for start, end in loops:
        loop_map[start] = end
        loop_map[end] = start

    # Execute code
    i = 0
    output = []

    while i < len(code):
        char = code[i]

        if char == '+':
            memory[pointer] = memory.get(pointer, 0) + 1
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == '-':
            memory[pointer] = memory.get(pointer, 0) - 1
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copied_value = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copied_value
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                i = loop_map[i]
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                i = loop_map[i]
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif char == 'T':
            memory[pointer] = memory.get(pointer, 0) * 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'Q':
            memory[pointer] = memory.get(pointer, 0) ** 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'U':
            import math
            memory[pointer] = int(math.sqrt(memory.get(pointer, 0)))
        elif char == 'L':
            memory[pointer] = memory.get(pointer, 0) + 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'V':
            memory[pointer] = memory.get(pointer, 0) // 2
        elif char == 'A':
            memory[pointer] = memory.get(pointer, 0) + copied_value
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'B':
            memory[pointer] = memory.get(pointer, 0) - copied_value
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'Y':
            memory[pointer] = memory.get(pointer, 0) * copied_value
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'D':
            if copied_value != 0:
                memory[pointer] = memory.get(pointer, 0) // copied_value
            else:
                memory[pointer] = 0

        i += 1

    return ''.join(output)

def getAllPrimeFactors(n):
    # Input validation: check if n is a number
    if not isinstance(n, (int, float)):
        return []

    # Check if n is an integer (handle float that represents integer)
    if isinstance(n, float):
        if not n.is_integer():
            return []
        n = int(n)

    # Check if n is positive
    if n <= 0:
        return []

    # Edge case: n = 1
    if n == 1:
        return [1]

    factors = []
    temp = n
    d = 2

    # Trial division up to sqrt(n)
    while d * d <= temp:
        while temp % d == 0:
            factors.append(d)
            temp //= d
        d += 1

    # If temp > 1, it's a prime factor itself
    if temp > 1:
        factors.append(temp)

    return factors


def getUniquePrimeFactorsWithCount(n):
    # Input validation: check if n is a number
    if not isinstance(n, (int, float)):
        return [[], []]

    # Check if n is an integer (handle float that represents integer)
    if isinstance(n, float):
        if not n.is_integer():
            return [[], []]
        n = int(n)

    # Check if n is positive
    if n <= 0:
        return [[], []]

    # Edge case: n = 1
    if n == 1:
        return [[1], [1]]

    # Get all prime factors
    all_factors = getAllPrimeFactors(n)

    if not all_factors:
        return [[], []]

    # Count occurrences of each unique factor
    unique_factors = []
    counts = []

    current_factor = all_factors[0]
    count = 0

    for factor in all_factors:
        if factor == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factor
            count = 1

    # Don't forget the last factor
    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]


def getUniquePrimeFactorsWithProducts(n):
    # Input validation: check if n is a number
    if not isinstance(n, (int, float)):
        return []

    # Check if n is an integer (handle float that represents integer)
    if isinstance(n, float):
        if not n.is_integer():
            return []
        n = int(n)

    # Check if n is positive
    if n <= 0:
        return []

    # Edge case: n = 1
    if n == 1:
        return [1]

    # Get unique factors with counts
    result = getUniquePrimeFactorsWithCount(n)
    unique_factors = result[0]
    counts = result[1]

    if not unique_factors:
        return []

    # Calculate products: factor ^ count
    products = []
    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

