    return sum(arr) - min(arr) - max(arr)

def parse_nested_parens(s):
    if not s:
        return []

    groups = s.split()
    result = []

    for group in groups:
        current_depth = 0
        max_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

import sys
from collections import defaultdict

def parse_url(url):
    # Remove "http://"
    url = url[7:]

    # Split by first slash to get hostname and path
    if '/' in url:
        hostname, path = url.split('/', 1)
        # Normalize path: ensure it starts with / for consistency
        if not path:
            path = ""
        else:
            path = "/" + path
    else:
        hostname = url
        path = ""

    return hostname, path

def normalize_path(path):
    # Normalize path by removing trailing slashes (but keeping the leading slash)
    if path == "":
        return ""
    if path == "/":
        return "/"

    # Remove trailing slashes
    while path.endswith('/'):
        path = path[:-1]

    # Ensure it starts with slash
    if not path.startswith('/'):
        path = '/' + path

    return path

def get_path_set(hostname, urls):
    # Collect all unique paths for this hostname
    paths = set()
    for url in urls:
        if url.startswith("http://" + hostname):
            _, path = parse_url(url)
            paths.add(path)
    return paths

def hash_path_set(paths):
    # Create a hashable representation of the set of paths
    sorted_paths = sorted(paths)
    return tuple(sorted_paths)

def main():
    data = sys.stdin.read()
    lines = data.strip().split('\n')

    n = int(lines[0])
    urls = lines[1:n+1]

    # Group URLs by hostname
    hostname_to_urls = defaultdict(list)
    for url in urls:
        hostname, _ = parse_url(url)
        hostname_to_urls[hostname].append(url)

    # For each hostname, get its set of paths
    hostname_to_paths = {}
    for hostname in hostname_to_urls:
        paths = set()
        for url in hostname_to_urls[hostname]:
            _, path = parse_url(url)
            paths.add(path)
        hostname_to_paths[hostname] = paths

    # Create hash representations of path sets
    path_set_to_hostnames = defaultdict(list)
    for hostname, paths in hostname_to_paths.items():
        hash_val = hash_path_set(paths)
        path_set_to_hostnames[hash_val].append(hostname)

    # Find groups with more than one hostname
    groups = []
    for hash_val, hostnames in path_set_to_hostnames.items():
        if len(hostnames) > 1:
            groups.append(sorted(hostnames))

    # Sort groups lexicographically
    groups.sort()

    print(len(groups))
    for group in groups:
        # Reconstruct full URLs
        full_urls = []
        for hostname in group:
            # Get any URL with this hostname to reconstruct full URL
