def poohbear(code):
    # Initialize memory and pointer
    memory = {}
    pointer = 0
    copied = 0
    ip = 0
    output = []

    # Find all loop pairs
    loop_stack = []
    loop_pairs = {}
    for i, char in enumerate(code):
        if char == 'W':
            loop_stack.append(i)
        elif char == 'E':
            start = loop_stack.pop()
            loop_pairs[start] = i
            loop_pairs[i] = start

    # Execute code
    while ip < len(code):
        char = code[ip]

        if char == '+':
            memory[pointer] = memory.get(pointer, 0) + 1
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == '-':
            memory[pointer] = memory.get(pointer, 0) - 1
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copied = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copied
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                ip = loop_pairs[ip]
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                ip = loop_pairs[ip]
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif char == 'T':
            memory[pointer] = memory.get(pointer, 0) * 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'Q':
            memory[pointer] = memory.get(pointer, 0) ** 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'U':
            import math
            memory[pointer] = int(math.sqrt(memory.get(pointer, 0)))
        elif char == 'L':
            memory[pointer] = memory.get(pointer, 0) + 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'V':
            memory[pointer] = memory.get(pointer, 0) // 2
        elif char == 'A':
            memory[pointer] = memory.get(pointer, 0) + copied
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'B':
            memory[pointer] = memory.get(pointer, 0) - copied
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'Y':
            memory[pointer] = memory.get(pointer, 0) * copied
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'D':
            if copied != 0:
                memory[pointer] = memory.get(pointer, 0) // copied
            else:
                memory[pointer] = 0

        ip += 1

    return ''.join(output)

def parse_int(s):
    # Define word mappings
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14,
        'fifteen': 15, 'sixteen': 16, 'seventeen': 17, 'eighteen': 18,
        'nineteen': 19, 'twenty': 20, 'thirty': 30, 'forty': 40,
        'fifty': 50, 'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    # Split the string into words and remove 'and'
    words = s.replace(' and ', ' ').split()

    result = 0
    current = 0

    for word in words:
        if word in word_to_num:
            current += word_to_num[word]
        elif word == 'hundred':
            current *= 100
        elif word == 'thousand':
            result += current * 1000
            current = 0
        elif word == 'million':
            result += current * 1000000
            current = 0

