    n = int(lines[0])
    gems = list(map(int, lines[1].split()))

    # Precompute palindromes
    is_palindrome = [[False] * n for _ in range(n)]

    # Every single gem is a palindrome
    for i in range(n):
        is_palindrome[i][i] = True

    # Check for palindromes of length 2
    for i in range(n - 1):
        if gems[i] == gems[i + 1]:
            is_palindrome[i][i + 1] = True

    # Check for palindromes of length 3 and more
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if gems[i] == gems[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP table: dp[i][j] represents minimum seconds to eliminate gems[i:j+1]
    dp = [[0] * n for _ in range(n)]

    # Fill DP table
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if i == j:
                # Single gemstone requires 1 second
                dp[i][j] = 1
            elif is_palindrome[i][j]:
                # If the substring is palindrome, remove it in 1 second
                dp[i][j] = 1
            else:
                # Find minimum by trying all possible partitions
                dp[i][j] = float('inf')
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

