def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def is_valid(r, c):
        return 0 <= r < 8 and 0 <= c < 8

    def get_amazon_attacks(amazon_r, amazon_c):
        attacks = set()

        # Queen moves (rook + bishop)
        # Horizontal and vertical
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            r, c = amazon_r + dr, amazon_c + dc
            while is_valid(r, c):
                attacks.add((r, c))
                if (r, c) == (king_r, king_c) or (r, c) == (amazon_r, amazon_c):
                    break
                r += dr
                c += dc

        # Diagonal
        for dr, dc in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
            r, c = amazon_r + dr, amazon_c + dc
            while is_valid(r, c):
                attacks.add((r, c))
                if (r, c) == (king_r, king_c) or (r, c) == (amazon_r, amazon_c):
                    break
                r += dr
                c += dc

        # Knight moves
        knight_moves = [(2, 1), (2, -1), (-2, 1), (-2, -1), 
                       (1, 2), (1, -2), (-1, 2), (-1, -2)]
        for dr, dc in knight_moves:
            r, c = amazon_r + dr, amazon_c + dc
            if is_valid(r, c):
                attacks.add((r, c))

        return attacks

    def get_king_adjacent(r, c):
        adjacent = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc):
                    adjacent.append((nr, nc))
        return adjacent

    def is_adjacent(r1, c1, r2, c2):
        return abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1

    def is_safe(r, c):
        # Check if square is adjacent to white king
        if is_adjacent(r, c, king_r, king_c):
            return False
        # Check if square is attacked by amazon
        if (r, c) in amazon_attacks:
            return False
        return True

    king_r, king_c = chess_to_coords(king)
    amazon_r, amazon_c = chess_to_coords(amazon)

    amazon_attacks = get_amazon_attacks(amazon_r, amazon_c)

    result = [0, 0, 0, 0]  # checkmate, check, stalemate, safe

    for r in range(8):
        for c in range(8):
            # Skip if square is occupied by white pieces
            if (r, c) == (king_r, king_c) or (r, c) == (amazon_r, amazon_c):
                continue

            # Skip if square is adjacent to white king (invalid king position)
            if is_adjacent(r, c, king_r, king_c):
                continue

            # Check if current square is attacked by amazon
            is_attacked = (r, c) in amazon_attacks

            # Find all valid moves from current square
            valid_moves = 0
            for nr, nc in get_king_adjacent(r, c):
                if is_safe(nr, nc):
                    valid_moves += 1

            # Classify position
            if is_attacked:
                if valid_moves == 0:
                    result[0] += 1  # checkmate
                else:
                    result[1] += 1  # check
            else:
                if valid_moves == 0:
                    result[2] += 1  # stalemate
                else:
                    result[3] += 1  # safe

    return result

