        return None

    # Check if all characters are alphabetic
    if not word.isalpha():
        return None

    # Convert to lowercase
    word = word.lower()

    # If word starts with a vowel
    if word[0] in 'aeiou':
        return word + 'way'

    # Find the index where the first vowel occurs
    first_vowel_index = 0
    for i, char in enumerate(word):
        if char in 'aeiou':
