        else:
            coeff = int(term)
            exp = 0

        # Calculate derivative contribution
        # d/dx(coeff * x^exp) = coeff * exp * x^(exp-1)
        if exp == 0:
            continue  # Constant term, derivative is 0
        else:
            new_coeff = coeff * exp
            new_exp = exp - 1
            if new_exp == 0:
                result += new_coeff
            else:
                result += new_coeff * (x_val ** new_exp)

    return result

