    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    # Helper function to check if n is prime with O(sqrt(n)) complexity
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False

        # Check for divisors of form 6k±1 up to sqrt(n)
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6

        return True

    return x if is_prime(n) else y

def decimal_to_binary(decimal):
    if decimal == 0:
        return "db0db"

    binary_digits = []
    while decimal > 0:
        binary_digits.append(str(decimal % 2))
        decimal = decimal // 2

    # Reverse the digits to get the correct binary representation
    binary_string = ''.join(reversed(binary_digits))
    return f"db{binary_string}db"

