def check_if_last_char_is_a_letter(txt):
    if not txt:
        return False

    # Remove trailing spaces to find the actual last character
    txt = txt.rstrip()
    if not txt:
        return False

    last_char = txt[-1]

    # Check if last character is a letter
    if not last_char.isalpha():
        return False

    # If string has only one character, it's standalone
    if len(txt) == 1:
        return True

    # Check if the character before last is a space (meaning it's standalone)
    return txt[-2] == ' '

def is_balanced(s, pairs):
    # Create a mapping of opening to closing characters
    pair_map = {}
    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        pair_map[open_char] = close_char

    # Stack to keep track of opening characters
    stack = []

    for char in s:
        # If character is an opening character
        if char in pair_map:
            # Check if it's also a closing character (self-matching case)
            if char in pair_map and pair_map[char] == char:
                # For self-matching, we can either push or pop depending on context
                # But since we're looking for matching pairs, we'll treat it as opening first
                stack.append(char)
            else:
                # Regular opening character
                stack.append(char)
        # If character is a closing character
        elif char in pair_map.values():
            # Check if stack is empty or if the closing character doesn't match the last opening character
            if not stack:
                return False

            last_opening = stack.pop()

            # Check if the closing character matches the last opening character
            if pair_map.get(last_opening) != char:
                return False

    # If stack is empty, all characters were properly matched
    return len(stack) == 0

from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    if not numbers:
        return (0, 1)

    total_sum = sum(numbers)
    total_product = 1
    for num in numbers:
        total_product *= num

    return (total_sum, total_product)

