                        else:
                            break
                    else:
                        if piece == "wB" or piece == "wQ": return True
                        else:
                            break
                nr += dr
                nc += dc

        return False

    def is_in_check(board, is_white):
        king_pos = find_king_position(board, is_white)
        if not king_pos:
            return False
        return is_square_attacked(board, king_pos[0], king_pos[1], is_white)

