def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # For 2^n - 1 to be a Mersenne prime, n must be prime
    # Also, we need to check that 2^n - 1 is actually prime
    if not is_prime(n):
        return False

    # Special case: 2^1 - 1 = 1, which is not prime
    if n == 1:
        return False

    # Calculate 2^n - 1
    mersenne_number = (1 << n) - 1

    # Check if the Mersenne number is prime
    return is_prime(mersenne_number)

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        return 1

    for i in range(n // 2, 0, -1):
        if n % i == 0:
            return i

    return 1

def sum_of_a_beach(s):
    words = ["sand", "water", "fish", "sun"]
    s_lower = s.lower()
    count = 0
    i = 0

    while i < len(s_lower):
        matched = False
        for word in words:
            if s_lower.startswith(word, i):
                count += 1
                i += len(word)
                matched = True
                break
        if not matched:
            i += 1

    return count

