def poohbear(code):
    # Build jump table for W/E loops
    jump_table = {}
    stack = []

    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                w_pos = stack.pop()
                jump_table[w_pos] = i
                jump_table[i] = w_pos

    # Initialize tape (infinite in both directions using dict)
    tape = {}
    pointer = 0
    copy_value = 0
    output = []

    def get_cell(pos):
        return tape.get(pos, 0)

    def set_cell(pos, value):
        value = value % 256  # Wraps negative values correctly in Python
        if value == 0:
            if pos in tape:
                del tape[pos]
        else:
            tape[pos] = value

    ip = 0
    while ip < len(code):
        cmd = code[ip]

        if cmd == '+':
            set_cell(pointer, get_cell(pointer) + 1)
        elif cmd == '-':
            set_cell(pointer, get_cell(pointer) - 1)
        elif cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == 'c':
            copy_value = get_cell(pointer)
        elif cmd == 'p':
            set_cell(pointer, copy_value)
        elif cmd == 'W':
            if get_cell(pointer) == 0:
                ip = jump_table[ip]
        elif cmd == 'E':
            if get_cell(pointer) != 0:
                ip = jump_table[ip]
        elif cmd == 'P':
            output.append(chr(get_cell(pointer)))
        elif cmd == 'N':
            output.append(str(get_cell(pointer)))
        elif cmd == 'T':
            set_cell(pointer, get_cell(pointer) * 2)
        elif cmd == 'Q':
            set_cell(pointer, get_cell(pointer) * get_cell(pointer))
        elif cmd == 'U':
            set_cell(pointer, int(get_cell(pointer) ** 0.5))
        elif cmd == 'L':
            set_cell(pointer, get_cell(pointer) + 2)
        elif cmd == 'I':
            set_cell(pointer, get_cell(pointer) - 2)
        elif cmd == 'V':
            set_cell(pointer, get_cell(pointer) // 2)
        elif cmd == 'A':
            set_cell(pointer, get_cell(pointer) + copy_value)
        elif cmd == 'B':
            set_cell(pointer, get_cell(pointer) - copy_value)
        elif cmd == 'Y':
            set_cell(pointer, get_cell(pointer) * copy_value)
        elif cmd == 'D':
            if copy_value != 0:
                set_cell(pointer, get_cell(pointer) // copy_value)

        ip += 1

    return ''.join(output)

