def parse_int(s):
    # Handle zero case
    if s == "zero":
        return 0

    # Define word mappings
    units = {
        'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9,
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17,
        'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    # Preprocess: lowercase, remove "and", replace hyphens with spaces
    s = s.lower().replace('and', '').replace('-', ' ').strip()

    # Split into words
    words = s.split()

    total = 0
    current = 0

    for word in words:
        if word in units:
            current += units[word]
        elif word in tens:
            current += tens[word]
        elif word == 'hundred':
            current *= 100
        elif word == 'thousand':
            total += current * 1000
            current = 0
        elif word == 'million':
            total += current * 1000000
            current = 0

    # Add any remaining value
    total += current

    return total

def histogram(s):
    if not s or not s.strip():
        return {}

    letters = s.split()

    if not letters:
        return {}

    counts = {}
    for letter in letters:
        counts[letter] = counts.get(letter, 0) + 1

    max_freq = max(counts.values())

    return {letter: count for letter, count in counts.items() if count == max_freq}

