def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2
    temp = d

    while p * p <= temp:
        if temp % p == 0:
            while temp % p == 0:
                temp //= p
            result -= result // p
        p += 1

    if temp > 1:
        result -= result // temp

    return result

def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    # Handle empty strings
    if not a and not b:
        return ""
    if not a:
        return b
    if not b:
        return a

    # Check if lengths are equal
    if len(a) != len(b):
        raise ValueError("Input strings must have equal length")

    # Perform XOR operation bit by bit
    result = ""
    for i in range(len(a)):
        # XOR: same bits give 0, different bits give 1
        if a[i] == b[i]:
            result += "0"
        else:
            result += "1"

    return result

