def compare(selector1, selector2):
    def calculate_specificity(selector):
        ids = 0
        classes = 0
        tags = 0

        parts = selector.split()

        for part in parts:
            if not part or part == '*':
                continue

            ids += part.count('#')
            classes += part.count('.')

            # Find the tag name (everything before the first # or .)
            min_pos = len(part)
            if '#' in part:
                min_pos = min(min_pos, part.find('#'))
            if '.' in part:
                min_pos = min(min_pos, part.find('.'))

            tag_part = part[:min_pos]

            if tag_part and tag_part != '*':
                tags += 1

        return (ids, classes, tags)

    spec1 = calculate_specificity(selector1)
    spec2 = calculate_specificity(selector2)

    if spec1 > spec2:
        return selector1
    elif spec2 > spec1:
        return selector2
    else:
        return selector2  # Later selector wins on tie

def proper_fractions(d):
    if d == 1:
        return 0

    result = d

    # Handle factor 2
    if d % 2 == 0:
        result = result // 2
        while d % 2 == 0:
            d //= 2

    # Handle odd prime factors
    i = 3
    while i * i <= d:
        if d % i == 0:
            result = result // i * (i - 1)
            while d % i == 0:
                d //= i
        i += 2

    # If remaining d > 1, it's a prime factor
    if d > 1:
        result = result // d * (d - 1)

    return result

