def proper_fractions(d):
    # For d = 1, there are no numerators in range (0, 1), so return 0
    if d == 1:
        return 0

    result = d
    p = 2

    # Handle factor 2 separately for efficiency
    if d % p == 0:
        while d % p == 0:
            d //= p
        result -= result // p

    # Handle odd prime factors from 3 onwards
    p = 3
    while p * p <= d:
        if d % p == 0:
            while d % p == 0:
                d //= p
            result -= result // p
        p += 2

    # If d > 1, then it's a prime factor itself
    if d > 1:
        result -= result // d

    return result

