def is_balanced(string, pairs):
    if string is None or len(string) == 0:
        return True

    # Build mapping of opener to closer
    opener_to_closer = {}
    same_char_pairs = set()

    for i in range(0, len(pairs), 2):
        opener = pairs[i]
        closer = pairs[i + 1]

        if opener == closer:
            same_char_pairs.add(opener)
        else:
            opener_to_closer[opener] = closer

    # Track counters for same-character pairs
    char_counters = {char: 0 for char in same_char_pairs}

    # Track stack for different-character pairs
    stack = []

    for char in string:
        if char in opener_to_closer:
            # Different character pair
            stack.append(char)
        elif char in same_char_pairs:
            # Same character pair - toggle counter
            if char_counters[char] == 0:
                # First occurrence, increment
                char_counters[char] = 1
            else:
                # Second occurrence, decrement
                char_counters[char] = 0
        elif char in opener_to_closer.values():
            # This is a closer character
            if stack:
                # Check if it matches the last opener
                last_opener = stack.pop()
                if opener_to_closer[last_opener] != char:
                    return False
            else:
                # No opener to match this closer
                return False

    # Check if any same-character pairs are still open
    for count in char_counters.values():
        if count != 0:
            return False

    # Check if stack is empty (all openers matched)
    return len(stack) == 0

def is_balanced(s, config):
    # Build opener to closer mapping from the configuration string
    # Each pair (index i, i+1) defines an opener and its corresponding closer
    opener_to_closer = {}
    for i in range(0, len(config), 2):
        opener_to_closer[config[i]] = config[i + 1]

    # Build closer to opener mapping for quick lookup
    closer_to_opener = {}
    for opener, closer in opener_to_closer.items():
        closer_to_opener[closer] = opener

    stack = []

    for char in s:
        if char in opener_to_closer:
            # This character can be an opener
            # Check if it could also be a closer for the top of stack (identical opener/closer case)
            if stack and opener_to_closer.get(stack[-1]) == char:
                # It's a closer for the top opener - pop it
                stack.pop()
            else:
                # It's an opener - push it
                stack.append(char)
        elif char in closer_to_opener:
            # This character is only a closer (not an opener)
            if not stack or opener_to_closer.get(stack[-1]) != char:
                return False
            stack.pop()
        # Characters not in config are ignored

    # Stack must be empty for balanced string
    return len(stack) == 0

