def smallest_change(arr):
    if not arr:
        return 0

    changes = 0
    n = len(arr)

    # Compare elements from both ends moving toward the center
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1

    return changes

def correct_bracketing(brackets: str):
    counter = 0
    for bracket in brackets:
        if bracket == '(':
            counter += 1
        elif bracket == ')':
            counter -= 1
            if counter < 0:
                return False
    return counter == 0

def get_closest_vowel(word):
    if len(word) < 3:
        return ""

    vowels = "aeiouAEIOU"

    # Start from the right side, but skip the last character
    for i in range(len(word) - 2, 0, -1):
        # Check if current character is a vowel
        if word[i] in vowels:
            # Check if it's between two consonants
            if word[i-1] not in vowels and word[i+1] not in vowels:
                return word[i]

    return ""

def cycpattern_check(a, b):
    # If b is empty, it's considered a substring of any string
    if not b:
        return True
    # If b is longer than a, no rotation of b can be a substring of a
    if len(b) > len(a):
        return False
    # Check all rotations of b
    for i in range(len(b)):
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True
    return False

def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def is_valid(pos):
        return 0 <= pos[0] < 8 and 0 <= pos[1] < 8

    def is_adjacent(pos1, pos2):
        return abs(pos1[0] - pos2[0]) <= 1 and abs(pos1[1] - pos2[1]) <= 1

    def get_amazon_attacks(amazon_pos):
        attacks = set()
        # Queen moves (rook + bishop)
        # Horizontal and vertical
        for i in range(8):
            if i != amazon_pos[0]:
                attacks.add((i, amazon_pos[1]))
            if i != amazon_pos[1]:
                attacks.add((amazon_pos[0], i))

        # Diagonals
        for i in range(1, 8):
            if is_valid((amazon_pos[0] + i, amazon_pos[1] + i)):
                attacks.add((amazon_pos[0] + i, amazon_pos[1] + i))
            if is_valid((amazon_pos[0] + i, amazon_pos[1] - i)):
                attacks.add((amazon_pos[0] + i, amazon_pos[1] - i))
            if is_valid((amazon_pos[0] - i, amazon_pos[1] + i)):
                attacks.add((amazon_pos[0] - i, amazon_pos[1] + i))
            if is_valid((amazon_pos[0] - i, amazon_pos[1] - i)):
                attacks.add((amazon_pos[0] - i, amazon_pos[1] - i))

        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            new_pos = (amazon_pos[0] + dx, amazon_pos[1] + dy)
            if is_valid(new_pos):
                attacks.add(new_pos)

        return attacks

    def get_king_attacks(king_pos):
        attacks = set()
        for i in range(-1, 2):
            for j in range(-1, 2):
                if i == 0 and j == 0:
                    continue
                new_pos = (king_pos[0] + i, king_pos[1] + j)
                if is_valid(new_pos):
                    attacks.add(new_pos)
        return attacks

    king_pos = chess_to_coords(king)
    amazon_pos = chess_to_coords(amazon)

    # Get all squares attacked by the amazon
    amazon_attacks = get_amazon_attacks(amazon_pos)

    # Get all squares attacked by the white king
    king_attacks = get_king_attacks(king_pos)

    # Counters for the four situations
    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    # Check all possible black king positions
    for i in range(8):
        for j in range(8):
            black_king_pos = (i, j)

            # Skip if position is occupied by white king or amazon
            if black_king_pos == king_pos or black_king_pos == amazon_pos:
                continue

            # Skip if position is adjacent to white king
            if is_adjacent(black_king_pos, king_pos):
                continue

            # Check if black king is under attack by amazon
            is_under_attack = black_king_pos in amazon_attacks

            # Check if black king can make a valid move
            can_move = False
            for di in range(-1, 2):
                for dj in range(-1, 2):
                    if di == 0 and dj == 0:
                        continue
                    new_pos = (black_king_pos[0] + di, black_king_pos[1] + dj)

                    # Check if new position is valid
                    if not is_valid(new_pos):
                        continue

                    # Check if new position is occupied by white pieces
                    if new_pos == king_pos or new_pos == amazon_pos:
                        continue

                    # Check if new position is adjacent to white king
                    if is_adjacent(new_pos, king_pos):
                        continue

                    # Check if new position is under attack by amazon
                    if new_pos in amazon_attacks:
                        continue

                    # If we reach here, the move is valid
                    can_move = True
                    break
                if can_move:
                    break

            # Classify the position
            if is_under_attack:
                if not can_move:
                    checkmate += 1
                else:
                    check += 1
            else:
                if not can_move:
                    stalemate += 1
                else:
                    safe += 1

    return [checkmate, check, stalemate, safe]

def almost_everywhere_zero(n, k):
    s = str(n)
    length = len(s)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, count, tight, started):
        if pos == length:
            return 1 if started and count == k else 0

        limit = int(s[pos]) if tight else 9
        total = 0

        for digit in range(limit + 1):
            new_tight = tight and (digit == limit)

            if not started and digit == 0:
                # Still in leading zeros, don't count
                total += dp(pos + 1, count, new_tight, False)
            else:
                # Number has started or this is the first non-zero digit
                new_started = True
                new_count = count + (1 if digit != 0 else 0)

                if new_count <= k:
                    total += dp(pos + 1, new_count, new_tight, True)

        return total

    return dp(0, 0, True, False)

def fib4(n: int):
    if n == 0 or n == 1 or n == 3:
        return 0
    if n == 2:
        return 2

    # Initialize the first four values
    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute fib4(n) for n >= 4
    for i in range(4, n + 1):
        next_val = a + b + c + d
        # Slide the window
        a, b, c, d = b, c, d, next_val

    return d

def almost_everywhere_zero(n, k):
    n_str = str(n)
    num_digits = len(n_str)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, count, tight, started):
        # Base case: all positions processed
        if pos == num_digits:
            return 1 if count == k and started else 0

        # Determine the upper bound for the current digit
        limit = int(n_str[pos]) if tight else 9

        result = 0

        for digit in range(limit + 1):
            new_tight = tight and (digit == limit)
            new_started = started or (digit != 0)
            new_count = count + (1 if digit != 0 else 0)

            # Skip if non-zero count exceeds k
            if new_count > k:
                continue

            result += dp(pos + 1, new_count, new_tight, new_started)

        return result

    return dp(0, 0, True, False)

