def converter(number, decimals=0, base=3.141592653589793):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    result = []

    if integer_part == 0:
        result = ['0']
    else:
        while integer_part > 0:
            remainder = integer_part % int(base)
            if remainder < 10:
                result.append(str(remainder))
            else:
                result.append(chr(ord('A') + remainder - 10))
            integer_part //= int(base)

    result.reverse()
    integer_string = ''.join(result)

    # Convert fractional part
    fractional_part = number - int(number)
    fractional_string = []

    if decimals > 0:
        fractional_string.append('.')
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            if digit < 10:
                fractional_string.append(str(digit))
            else:
                fractional_string.append(chr(ord('A') + digit - 10))
            fractional_part -= digit

    # Combine results
    final_result = integer_string + ''.join(fractional_string)

    # Handle negative sign
    if negative:
        final_result = '-' + final_result

    # Handle special case where we need leading zero
    if number < 1 and decimals > 0:
        if not final_result.startswith('0.'):
            # This shouldn't happen with our logic, but just in case
            pass

    return final_result

