def strange_sort_list(nums):
    sorted_nums = sorted(nums)
    left = 0
    right = len(sorted_nums) - 1
    result = []

    while left <= right:
        if len(result) % 2 == 0:
            result.append(sorted_nums[left])
            left += 1
        else:
            result.append(sorted_nums[right])
            right -= 1

    return result

def solution(input_string, markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the earliest position of any marker
        earliest_marker_pos = len(line)
        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < earliest_marker_pos:
                earliest_marker_pos = pos

        # If we found a marker, truncate the line
        if earliest_marker_pos < len(line):
            processed_line = line[:earliest_marker_pos]
        else:
            processed_line = line

        # Strip trailing whitespace
        processed_line = processed_line.rstrip()
        result_lines.append(processed_line)

    return '\n'.join(result_lines)

def amazon_check_mate(board, white=True):
    """
    Check if the given chess board position is checkmate.

    Args:
        board: 8x8 chess board representation (list of 8 strings or list of lists)
               where each cell contains a piece or '.' for empty squares
               Piece notation: 'K'='White King', 'k'='Black King',
               'Q'='White Queen', 'q'='Black Queen',
               'R'='White Rook', 'r'='Black Rook',
               'B'='White Bishop', 'b'='Black Bishop',
               'N'='White Knight', 'n'='Black Knight',
               'P'='White Pawn', 'p'='Black Pawn',
               '.'='Empty square'
        white: Boolean indicating whose turn it is (True=White to move, False=Black to move)
               Default is True (White)

    Returns:
        bool: True if it's checkmate, False otherwise

    Checkmate conditions:
    1. The king is currently in check
    2. The king has no legal moves to escape the check
    """

    def get_piece(row, col):
        """Get piece at position, return '.' if out of bounds."""
        if 0 <= row < 8 and 0 <= col < 8:
            return board[row][col] if isinstance(board[row], str) else board[row][col]
        return '.'

    def find_king():
        """Find king position for the side whose turn it is."""
        king = 'K' if white else 'k'
        for r in range(8):
            for c in range(8):
                if get_piece(r, c) == king:
                    return r, c
        return None, None

    def is_square_attacked_by_enemy(row, col):
        """Check if a square is attacked by enemy pieces."""
        for r in range(8):
            for c in range(8):
                piece = get_piece(r, c)
                if piece == '.' or piece.isupper() == (white):
                    continue  # Skip empty or same-color pieces

                # Check attack patterns for each piece type
                if piece == 'K' or piece == 'k':  # King
                    if abs(r - row) <= 1 and abs(c - col) <= 1:
                        return True
                elif piece == 'Q' or piece == 'q':  # Queen (rook + bishop)
                    if is_attacked_by_rook(r, c, row, col) or is_attacked_by_bishop(r, c, row, col):
                        return True
                elif piece == 'R' or piece == 'r':  # Rook
                    if is_attacked_by_rook(r, c, row, col):
                        return True
                elif piece == 'B' or piece == 'b':  # Bishop
                    if is_attacked_by_bishop(r, c, row, col):
                        return True
                elif piece == 'N' or piece == 'n':  # Knight
                    if abs(r - row) == 1 and abs(c - col) == 2:
                        return True
                    if abs(r - row) == 2 and abs(c - col) == 1:
                        return True
                elif piece == 'P' or piece == 'p':  # Pawn
                    if piece == 'p' and not white:  # Black pawn attacks
                        if r == row + 1 and abs(c - col) == 1:
                            return True
                    elif piece == 'P' and white:  # White pawn attacks
                        if r == row - 1 and abs(c - col) == 1:
                            return True
        return False

    def is_attacked_by_rook(r1, c1, r2, c2):
        """Check if (r1, c1) can attack (r2, c2) like a rook."""
        if r1 != r2 and c1 != c2:
            return False
        if r1 == r2:  # Same row
            min_c, max_c = min(c1, c2), max(c1, c2)
            for c in range(min_c + 1, max_c):
                if get_piece(r1, c) != '.':
                    return False
        else:  # Same column
            min_r, max_r = min(r1, r2), max(r1, r2)
            for r in range(min_r + 1, max_r):
                if get_piece(r, c1) != '.':
                    return False
        return True

    def is_attacked_by_bishop(r1, c1, r2, c2):
        """Check if (r1, c1) can attack (r2, c2) like a bishop."""
        if abs(r1 - r2) != abs(c1 - c2):
            return False
        dr = 1 if r2 > r1 else -1
        dc = 1 if c2 > c1 else -1
        r, c = r1 + dr, c1 + dc
        while r != r2:
            if get_piece(r, c) != '.':
                return False
            r += dr
            c += dc
        return True

    def can_move_to(row, col):
        """Check if the king can safely move to (row, col)."""
        if not (0 <= row < 8 and 0 <= col < 8):
            return False
        if get_piece(row, col) == '.':
            return not is_square_attacked_by_enemy(row, col)
        piece = get_piece(row, col)
        if piece.isupper() == white:  # Own piece blocks
            return False
        return not is_square_attacked_by_enemy(row, col)

    def is_in_check():
        """Check if the king is currently in check."""
        king_r, king_c = find_king()
        if king_r is None:
            return False
        return is_square_attacked_by_enemy(king_r, king_c)

    def has_escape_moves():
        """Check if the king has any legal escape moves."""
        king_r, king_c = find_king()
        if king_r is None:
            return True  # No king means invalid position, not checkmate

        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                new_r, new_c = king_r + dr, king_c + dc
                if can_move_to(new_r, new_c):
                    return True
        return False

    # Checkmate requires: king in check AND no escape moves
    return is_in_check() and not has_escape_moves()

def exchange_sort(sequence):
    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for val in sequence:
        count[val] += 1

    # Create target sequence
    target = []
    target.extend([7] * count[7])
    target.extend([8] * count[8])
    target.extend([9] * count[9])

    # Create a mapping from value to its correct positions
    correct_positions = {7: [], 8: [], 9: []}
