    return [num for _, _, num in indexed_nums]

def solution(text, markers):
    # Split text into lines
    lines = text.split('\n')

    # Process each line
    result_lines = []
    for line in lines:
        # Find the first occurrence of any marker
        min_index = len(line)  # Start with the end of the line (no marker case)
        for marker in markers:
            index = line.find(marker)
            if index != -1 and index < min_index:
                min_index = index

        # If we found a marker, cut the line at that position
        if min_index < len(line):
            line = line[:min_index]

        # Strip trailing whitespace
        line = line.rstrip()

        result_lines.append(line)

    # Join lines back with newlines
    return '\n'.join(result_lines)

