            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)
            exponent = int(parts[1])
        elif 'x' in term:
            # Term is like "3x" or "-3x" or "x" or "-x"
            if term == 'x':
                coeff = 1
                exponent = 1
            elif term == '-x':
                coeff = -1
                exponent = 1
            else:
                # Remove the 'x' to get coefficient
                coeff_str = term[:-1]
                if coeff_str == '' or coeff_str == '+':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str)
                exponent = 1
        else:
            # This shouldn't happen, but just in case
            continue

        # Apply power rule: d/dx(cx^n) = c*n*x^(n-1)
        if exponent == 0:
            # Constant term, derivative is 0
            continue
        else:
            new_coeff = coeff * exponent
            new_exponent = exponent - 1

            # Evaluate the derivative at x
            if new_exponent == 0:
                total_derivative += new_coeff
            else:
                total_derivative += new_coeff * (x ** new_exponent)

    return total_derivative

def greatest_common_divisor(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> greatest_common_divisor(3, 5)
    1
    >>> greatest_common_divisor(25, 15)
    5
    """
    # Handle edge cases
    if a == 0:
        return abs(b)
    if b == 0:
        return abs(a)

    # Use Euclidean algorithm
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

