def is_balanced(s, pairs):
    # Create mapping from opening to closing characters
    opening_to_closing = {}
    closing_to_opening = {}

    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        opening_to_closing[opening] = closing
        closing_to_opening[closing] = opening

    stack = []

    for char in s:
        if char in opening_to_closing:
            stack.append(char)
        elif char in closing_to_opening:
            if not stack:
                return False
            top = stack[-1]
            if opening_to_closing[top] != char:
                return False
            stack.pop()

    return len(stack) == 0

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Use enumerate to keep track of original indices for stability
    indexed_nums = [(num, i) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    sorted_nums = sorted(indexed_nums, key=lambda x: (digit_sum(x[0]), x[1]))

    # Extract just the numbers from the sorted pairs
    return [num for num, _ in sorted_nums]

