def getAllPrimeFactors(n):
    # Input validation
    if not isinstance(n, int) or not isinstance(n, (int, float)):
        return []
    if n <= 0:
        return []

    # Handle edge cases
    if n == 1:
        return [1]
    if n == 2:
        return [2]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

