        else:  # val == 9
            wrong_9 += 1

    # The minimum number of swaps is the maximum of wrong_7 and wrong_9
    # because we can swap a wrong 7 with a wrong 9, and vice versa
    # but we need to be careful about the constraint that 8s must be in middle
    # So we compute: min(swaps needed) = max(wrong_7, wrong_9)

    # Actually, let's reconsider the approach:
    # We need to count mismatches properly

    # Count how many 7s are in positions where 8s or 9s should be
    # and how many 8s are in positions where 7s or 9s should be
    # and how many 9s are in positions where 7s or 8s should be

    wrong_7s = 0  # 7s in wrong positions (8s or 9s in 7s positions)
    wrong_8s = 0  # 8s in wrong positions (7s or 9s in 8s positions)
    wrong_9s = 0  # 9s in wrong positions (7s or 8s in 9s positions)

    # Check 7s positions (should be 7s)
    for i in range(count[7]):
