    return max(wrong_7s, wrong_8s, wrong_9s)

def sum_of_squares(n):
    # Check if n is a perfect square
    sqrt_n = int(n**0.5)
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n can be represented as sum of two squares
    # Using the fact that a number is sum of two squares if and only if
    # in its prime factorization, every prime of the form 4k+3 appears an even number of times
    def is_sum_of_two_squares(n):
        # Remove factors of 4
        while n % 4 == 0:
            n //= 4
        # Check if n is sum of two squares
        # This is a simplified check - for full correctness we'd need to factor n
        # But for our purposes, we'll check up to sqrt(n) for potential representations
        for i in range(1, int(n**0.5) + 1):
            if n % (i * i) == 0:
                # Check if n/i is a perfect square
                j = n // (i * i)
                if int(j**0.5)**2 == j:
                    return True
        return False

    # For small numbers, we can check directly
    if n < 10000:
        # Brute force for small n
        for a in range(1, int(n**0.5) + 1):
            for b in range(a, int((n - a*a)**0.5) + 1):
                remaining = n - a*a - b*b
                if remaining >= 0:
                    sqrt_remaining = int(remaining**0.5)
                    if sqrt_remaining * sqrt_remaining == remaining:
                        return 3
        return 4

    # Use Legendre's three-square theorem and Lagrange's four-square theorem
    # A natural number n can be represented as the sum of three squares of integers
    # if and only if n is not of the form n = 4^a(8b + 7) for integers a and b.

    # Remove all factors of 4
    while n % 4 == 0:
        n //= 4

    # If n = 8b + 7, then it requires 4 squares
    if n % 8 == 7:
        return 4

    # Check if it's a sum of two squares
    sqrt_n = int(n**0.5)
    for i in range(1, sqrt_n + 1):
        remainder = n - i*i
        if remainder == 0:
            return 2
        sqrt_remainder = int(remainder**0.5)
        if sqrt_remainder * sqrt_remainder == remainder:
            return 2

    # If not sum of two squares, it's sum of three squares
    return 3

def is_balanced(text, pairs):
    # Build mapping from closing characters to their corresponding opening characters
    closing_to_opening = {}
    opening_set = set()

    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        closing_to_opening[closing] = opening
        opening_set.add(opening)

    stack = []

    for char in text:
        if char in opening_set:
            # Opening character: push onto stack
            stack.append(char)
        elif char in closing_to_opening:
            # Closing character: must match most recent opening
            if not stack or stack[-1] != closing_to_opening[char]:
                return False
            stack.pop()
        # Ignore all other characters

    # All opening characters must have been closed
    return len(stack) == 0

