def differentiate(polynomial, x):
    # Parse the polynomial into terms
    # Handle the case where there's no + or - signs
    terms = []
    current_term = ""

    # Split by + and - signs, keeping the signs
    i = 0
    while i < len(polynomial):
        if polynomial[i] in ['+', '-'] and i > 0:
            terms.append(current_term)
            current_term = polynomial[i]
        else:
            current_term += polynomial[i]
        i += 1
    terms.append(current_term)

    # Remove empty terms
    terms = [term for term in terms if term]

    derivative_sum = 0

    for term in terms:
        # Handle the sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Parse the term
        if 'x^' in term:
            # Format: ax^n
            parts = term.split('x^')
            coeff_str = parts[0]
            if coeff_str == '':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)
            power = int(parts[1])

            # Derivative: n*ax^(n-1)
            if power > 0:
                derivative_sum += sign * power * coeff * (x ** (power - 1))

        elif 'x' in term:
            # Format: ax or -ax or ax^1
            if term == 'x':
                coeff = 1
                power = 1
            elif term == '-x':
                coeff = -1
                power = 1
            else:
                # Remove x and get coefficient
                coeff_str = term[:-1]
                if coeff_str == '':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str)
                power = 1

            # Derivative: a*x^0 = a
            derivative_sum += sign * coeff

        else:
            # Constant term
            if term:
                derivative_sum += 0  # Derivative of constant is 0

    return derivative_sum

