                if not is_adjacent(white_king_pos, pos) and not is_adjacent(amazon_pos, pos):
                    safe_positions.append(pos)
        return safe_positions

    def is_in_check(pos, threats):
        return pos in threats

    def can_escape(pos, threats, safe_positions):
        moves = get_king_moves(pos)
        for move in moves:
            if move in safe_positions and not is_in_check(move, threats):
                return True
        return False

