def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, number) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract the numbers in the new order
    return [num for _, _, num in indexed_nums]

import math
from collections import defaultdict

def poohbear(code):
    # Extract actual code from input
    if isinstance(code, list):
        code_str = code[0] if code else ""
    elif isinstance(code, str):
        code_str = code
        # Strip outer brackets if present
        code_str = code_str.strip()
        if code_str.startswith("['") and code_str.endswith("']"):
            code_str = code_str[2:-2]
        elif code_str.startswith('["') and code_str.endswith('"]'):
            code_str = code_str[2:-2]
    else:
        code_str = str(code)

    # Filter to only valid commands
    valid_commands = set('+-<>cpWEPNTQULIVABYD')
    filtered_code = ''.join(c for c in code_str if c in valid_commands)

    # Build loop matching dictionary (W -> E and E -> W)
    loop_map = {}
    stack = []

    for i, cmd in enumerate(filtered_code):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                w_index = stack.pop()
                loop_map[w_index] = i
                loop_map[i] = w_index

    # Initialize state
    cells = defaultdict(int)  # Infinite memory, default 0
    ptr = 0  # Data pointer
    copy = 0  # Copy register
    pc = 0  # Program counter
    output = []

    # Execute commands
    while pc < len(filtered_code):
        cmd = filtered_code[pc]

        if cmd == '+':
            cells[ptr] = (cells[ptr] + 1) % 256
        elif cmd == '-':
            cells[ptr] = (cells[ptr] - 1) % 256
        elif cmd == '>':
            ptr += 1
        elif cmd == '<':
            ptr -= 1
        elif cmd == 'c':
            copy = cells[ptr]
        elif cmd == 'p':
            cells[ptr] = copy
        elif cmd == 'W':
            if cells[ptr] == 0:
                pc = loop_map[pc]
                pc += 1
                continue
        elif cmd == 'E':
            if cells[ptr] != 0:
                pc = loop_map[pc]
                continue
        elif cmd == 'P':
            output.append(chr(cells[ptr]))
        elif cmd == 'N':
            output.append(str(cells[ptr]))
        elif cmd == 'T':
            cells[ptr] = (cells[ptr] * 2) % 256
        elif cmd == 'Q':
            cells[ptr] = (cells[ptr] ** 2) % 256
        elif cmd == 'U':
            cells[ptr] = int(math.sqrt(cells[ptr]))
        elif cmd == 'L':
            cells[ptr] = (cells[ptr] + 2) % 256
        elif cmd == 'I':
            cells[ptr] = (cells[ptr] - 2) % 256
        elif cmd == 'V':
            cells[ptr] = (cells[ptr] // 2) % 256
        elif cmd == 'A':
            cells[ptr] = (cells[ptr] + copy) % 256
        elif cmd == 'B':
            cells[ptr] = (cells[ptr] - copy) % 256
        elif cmd == 'Y':
            cells[ptr] = (cells[ptr] * copy) % 256
        elif cmd == 'D':
            if copy != 0:
                cells[ptr] = (cells[ptr] // copy) % 256

        pc += 1

    return ''.join(output)

def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
