        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            while is_valid(nx, ny):
                moves.append((nx, ny))
                if (nx, ny) == (x, y):  # This shouldn't happen, but just in case
                    break
                nx += dx
                ny += dy

        # Knight moves
        knight_moves = [(2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)]
        for dx, dy in knight_moves:
