    amazon_attacks = get_amazon_moves(amazon_x, amazon_y)

    # Get all positions the white king can attack
    king_attacks = get_king_moves(king_x, king_y)

    # Get all positions the white king can move to
    king_moves = get_king_moves(king_x, king_y)

    # Initialize counters
    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    # Check all possible black king positions
    for bx in range(8):
        for by in range(8):
            # Skip if this position is adjacent to white king
            if is_adjacent(bx, by, king_x, king_y):
                continue

            # Skip if this position is occupied by the amazon or white king
            if (bx, by) == (amazon_x, amazon_y) or (bx, by) == (king_x, king_y):
                continue

            # Check if black king is under attack by amazon
            is_under_attack = (bx, by) in amazon_attacks

            # Get black king's possible moves
            black_king_moves = get_king_moves(bx, by)

            # Check if black king can move to a safe square
            safe_moves = []
            for move in black_king_moves:
