                if is_adjacent(move[0], move[1], king_x, king_y):
                    continue
                # Skip if move is occupied by amazon or white king
                if move == (amazon_x, amazon_y) or move == (king_x, king_y):
                    continue
                # Skip if move is under attack by white king
                if move in king_attacks:
                    continue
                safe_moves.append(move)

            # If black king is under attack and has no safe moves, it's checkmate
            if is_under_attack and len(safe_moves) == 0:
                checkmate += 1
            # If black king is under attack but has safe moves, it's check
            elif is_under_attack and len(safe_moves) > 0:
                check += 1
            # If black king is not under attack but has no moves, it's stalemate
            elif not is_under_attack and len(safe_moves) == 0:
                stalemate += 1
            # If black king is not under attack and has moves, it's safe
            elif not is_under_attack and len(safe_moves) > 0:
                safe += 1

    return [checkmate, check, stalemate, safe]

import sys
from math import factorial, log, exp

def combination(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1
    return factorial(n) // (factorial(k) * factorial(n - k))

def calculate_probability(k, n):
    # Using inclusion-exclusion principle
    # P(all k types collected in n days) = sum_{i=0}^k (-1)^i * C(k,i) * ((k-i)/k)^n
    prob = 0.0
    for i in range(k + 1):
        sign = (-1) ** i
        comb = combination(k, i)
        prob += sign * comb * ((k - i) / k) ** n
    return prob

def find_min_days(k, p):
    # Binary search for minimum days
    left = k
    right = k * 1000000  # Upper bound estimate

    target = (p - 1e-10) / 2000.0

    while left < right:
        mid = (left + right) // 2
        prob = calculate_probability(k, mid)

        if prob >= target:
            right = mid
        else:
            left = mid + 1

    return left

