import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part to the given base
    if integer_part == 0:
        integer_result = '0'
    else:
        digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            # Handle negative remainders
            if remainder < 0:
                remainder += base
                temp = (temp - remainder) // base - 1
            else:
                temp = (temp - remainder) // base
            digits.append(remainder)

        # Convert digits to string representation
        result_digits = []
        for digit in reversed(digits):
            if digit < 10:
                result_digits.append(str(int(digit)))
            else:
                result_digits.append(chr(ord('A') + int(digit) - 10))
        integer_result = ''.join(result_digits)

    # Convert fractional part
    if decimals == 0:
        fractional_result = ''
    else:
        fractional_digits = []
        temp_fraction = fractional_part
        for _ in range(decimals):
            temp_fraction *= base
            digit = int(temp_fraction)
            fractional_digits.append(digit)
            temp_fraction -= digit
            # Handle very small fractions that might cause precision issues
            if abs(temp_fraction) < 1e-15:
                break

        # Convert fractional digits to string representation
        fractional_str = ''
        for digit in fractional_digits:
            if digit < 10:
                fractional_str += str(digit)
            else:
                fractional_str += chr(ord('A') + digit - 10)

        # Handle case where fractional part is all zeros
        if not fractional_str or all(c == '0' for c in fractional_str):
            fractional_result = ''
        else:
            fractional_result = '.' + fractional_str

    # Combine results
    result = integer_result + fractional_result

    # Handle negative numbers
    if negative:
        result = '-' + result

    # Handle case where result is less than 1 and has no decimal part
    if result.startswith('.'):
        result = '0' + result

    return result

