def longest_palindrome(s: str) -> str:
    if not s:
        return ""

    start, end = 0, 0

    def expand_around_center(left: int, right: int) -> tuple:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(s)):
        left1, right1 = expand_around_center(i, i)       # Odd length
        left2, right2 = expand_around_center(i, i + 1)   # Even length

        if right1 - left1 > end - start:
            start, end = left1, right1
        if right2 - left2 > end - start:
            start, end = left2, right2

    return s[start:end + 1]

def parse_int(text):
    """
    Convert English number words to integer.
    Supports numbers from zero to one million.
    """
    # Mapping of number words to their values
    units = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }
    teens = {
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17,
        'eighteen': 18, 'nineteen': 19
    }
    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }
    scales = {
        'hundred': 100,
        'thousand': 1000,
        'million': 1000000
    }

    # Combine all mappings
    word_to_value = {**units, **teens, **tens, **scales}

    # Handle zero case
    if text.strip().lower() == 'zero':
        return 0

    # Clean the input: remove 'and', convert to lowercase, replace hyphens with spaces
    text = text.lower().replace('and', '').replace('-', ' ')

    # Split into tokens
    tokens = text.split()

    total = 0
    current = 0

    for token in tokens:
        if token not in word_to_value:
            continue  # Skip any unexpected tokens

        value = word_to_value[token]

        if token in scales:
            if token == 'hundred':
                # Multiply current by 100
                current *= 100
            elif token == 'thousand':
                # Multiply current by 1000 and add to total, reset current
                current *= 1000
                total += current
                current = 0
            elif token == 'million':
                # Multiply current by 1000000 and add to total, reset current
                current *= 1000000
                total += current
                current = 0
        else:
            # Regular number: add to current
            current += value

    return total + current

from fractions import Fraction

def simplify(frac):
