    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute fib4 from 4 to n
    for i in range(4, n + 1):
        # fib4(i) = fib4(i-1) + fib4(i-2) + fib4(i-3) + fib4(i-4)
        next_val = a + b + c + d
        # Shift the window: a,b,c,d become fib4(i-3), fib4(i-2), fib4(i-1), fib4(i)
        a, b, c, d = b, c, d, next_val

    return d

def proper_fractions(n):
    if n == 1:
        return 0

    result = n

    # Check for factor 2
    if n % 2 == 0:
        result -= result // 2
        while n % 2 == 0:
            n //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result -= result // i
            while n % i == 0:
                n //= i
        i += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        result -= result // n

    return result

def simplify(expression):
    if not expression:
        return ""

    # Parse the expression
    terms = []
    i = 0
    while i < len(expression):
        # Determine the sign
        sign = 1
        if expression[i] == '+':
            i += 1
        elif expression[i] == '-':
            sign = -1
            i += 1

        # Extract coefficient and variable part
        coeff_str = ""
        var_part = ""

        # Parse coefficient (could be empty for 1 or -1)
        while i < len(expression) and expression[i].isdigit():
            coeff_str += expression[i]
            i += 1

        # If no coefficient found, it's 1 or -1
        if not coeff_str:
            coeff = sign * 1
        else:
            coeff = sign * int(coeff_str)

        # Parse variable part
        while i < len(expression) and expression[i].isalpha():
            var_part += expression[i]
            i += 1

        # If no variable part, it's just a constant (but problem says non-constant)
        if var_part:
            terms.append((coeff, var_part))

    # Normalize terms by sorting variables in each term
    normalized_terms = []
    for coeff, var_part in terms:
        sorted_var = ''.join(sorted(var_part))
        normalized_terms.append((coeff, sorted_var))

    # Aggregate terms with same variables
    term_dict = {}
    for coeff, var in normalized_terms:
        if var in term_dict:
            term_dict[var] += coeff
        else:
            term_dict[var] = coeff

    # Filter out zero coefficients
    filtered_terms = [(coeff, var) for var, coeff in term_dict.items() if coeff != 0]

    # Sort terms by number of variables (ascending) and then lexicographically
    filtered_terms.sort(key=lambda x: (len(x[1]), x[1]))

    # Format the result
    result = []
    for i, (coeff, var) in enumerate(filtered_terms):
        if i == 0:
            # First term, no leading +
            if coeff == 1:
                result.append(var)
            elif coeff == -1:
                result.append('-' + var)
            else:
                result.append(str(coeff) + var)
        else:
            # Subsequent terms
            if coeff == 1:
                result.append('+' + var)
            elif coeff == -1:
                result.append('-' + var)
            else:
                if coeff > 0:
                    result.append('+' + str(coeff) + var)
                else:
                    result.append(str(coeff) + var)

    return ''.join(result)

def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0

    for num in range(1, n + 1):
        num_str = str(num)
        if num_str == num_str[::-1]:
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def count_up_to(n):
    """Returns all prime numbers less than n in ascending order."""
    if n <= 2:
        return []

    # Create boolean array for Sieve of Eratosthenes
    is_prime = [True] * n
    is_prime[0] = False
    is_prime[1] = False

    # Sieve of Eratosthenes algorithm
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            # Mark all multiples of i starting from i*i as not prime
            for j in range(i * i, n, i):
                is_prime[j] = False

    # Collect all prime numbers
    return [i for i in range(2, n) if is_prime[i]]

