def getAllPrimeFactors(n):
    # Validate input
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []
    if n == 1:
        return [1]

    factors = []
    temp = n

    # Check for factor 2
    while temp % 2 == 0:
        factors.append(2)
        temp //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= temp:
        while temp % i == 0:
            factors.append(i)
            temp //= i
        i += 2

    # If temp is still greater than 1, it's a prime factor
    if temp > 1:
        factors.append(temp)

    return factors


def getUniquePrimeFactorsWithCount(n):
    # Validate input
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return [[], []]
    if not isinstance(n, int):
        return [[], []]
    if n <= 0:
        return [[], []]
    if n == 1:
        return [[1], [1]]

    factors = []
    counts = []
    temp = n

    # Check for factor 2
    count = 0
    while temp % 2 == 0:
        count += 1
        temp //= 2

    if count > 0:
        factors.append(2)
        counts.append(count)

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= temp:
        count = 0
        while temp % i == 0:
            count += 1
            temp //= i
        if count > 0:
            factors.append(i)
            counts.append(count)
        i += 2

    # If temp is still greater than 1, it's a prime factor
    if temp > 1:
        factors.append(temp)
        counts.append(1)

    return [factors, counts]


def getUniquePrimeFactorsWithProducts(n):
    # Validate input
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []
    if n == 1:
        return [1]

    primes, counts = getUniquePrimeFactorsWithCount(n)
    products = [p ** c for p, c in zip(primes, counts)]

    return products

def compare(s1, s2):
    def parse_selector(s):
        components = s.split()
        id_count = 0
        class_count = 0
        tag_count = 0

        for comp in components:
            if '#' in comp:
                parts = comp.split('#')
                tag_part = parts[0]
                id_part = parts[1]

                if tag_part:
                    if '.' in tag_part:
                        tag_classes = tag_part.split('.')
                        if tag_classes[0]:
                            tag_count += 1
                        class_count += len(tag_classes) - 1
                    else:
                        tag_count += 1

                if id_part:
                    if '.' in id_part:
                        id_classes = id_part.split('.')
                        if id_classes[0]:
                            id_count += 1
                        class_count += len(id_classes) - 1
                    else:
                        id_count += 1
            else:
                if '.' in comp:
                    parts = comp.split('.')
                    if parts[0]:
                        tag_count += 1
                    class_count += len(parts) - 1
                else:
                    tag_count += 1

        return (id_count, class_count, tag_count)

    spec1 = parse_selector(s1)
    spec2 = parse_selector(s2)

    if spec1 > spec2:
        return s1
    else:
        return s2

def count_up_to(n):
    if n <= 2:
