        open_char = pairs[i]
        close_char = pairs[i + 1]
        open_chars.add(open_char)
        close_to_open[close_char] = open_char

    stack = []

    for char in text:
        if char in open_chars:
            stack.append(char)
        elif char in close_to_open:
            if not stack or stack[-1] != close_to_open[char]:
                return False
            stack.pop()

    return len(stack) == 0

def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    def miller_rabin(n, k=5):
        if n < 2:
            return False
        if n == 2 or n == 3:
            return True
        if n % 2 == 0:
            return False

        # Write n-1 as d * 2^r
        r = 0
        d = n - 1
        while d % 2 == 0:
            d //= 2
            r += 1

        # Witness loop
        import random
        for _ in range(k):
            a = random.randrange(2, n - 1)
            x = pow(a, d, n)
            if x == 1 or x == n - 1:
                continue
            for _ in range(r - 1):
                x = pow(x, 2, n)
                if x == n - 1:
                    break
            else:
                return False
        return True

    # Handle edge cases
    if n <= 0:
        return False

    # A Mersenne number 2^n - 1 can only be prime if n is prime
    if not is_prime(n):
        return False

    # Compute Mersenne number
    mersenne = (1 << n) - 1  # This is 2^n - 1

    # For small numbers, use trial division
    if n <= 20:
        return is_prime(mersenne)
    else:
        # For large numbers, use Miller-Rabin
        return miller_rabin(mersenne)

