            while True:
                r += dr
                c += dc
                if not is_valid(r, c):
                    break
                if (r, c) == white_king:
                    break
                threats.add((r, c))

        for dr, dc in knight_moves:
            r, c = white_amazon[0] + dr, white_amazon[1] + dc
            if is_valid(r, c):
