                r, c = king_pos[0] + dr, king_pos[1] + dc
                if is_valid(r, c):
                    adjacent.add((r, c))
        return adjacent

    amazon_threats = get_amazon_threats()
    white_king_adjacent = get_king_adjacent_positions(white_king)

