                if dr == 0 and dc == 0:
                    continue
                if is_valid_escape((r + dr, c + dc)):
                    return True
        return False

    checkmate = 0
    check = 0
    stalemate = 0
    safe_with_moves = 0

    for row in range(8):
        for col in range(8):
            black_king = (row, col)

            if black_king == white_king:
