        monomial = token
        if token.startswith('-'):
            sign = -1
            monomial = token[1:]
        elif token.startswith('+'):
            sign = 1
            monomial = token[1:]

        # If the monomial is just a number (no variables), handle it
        if not re.search(r'[a-z]', monomial):
            if monomial:
                monomials.append((sign * int(monomial), '', 0))
        else:
            # Extract variables and their coefficients
            # The coefficient is 1 if not specified
            coeff_str = re.match(r'^[+-]?\d*', monomial)
            if coeff_str and coeff_str.group():
                coeff = int(coeff_str.group())
            else:
                coeff = 1

            # Remove coefficient part to get variables
            var_part = re.sub(r'^[+-]?\d*', '', monomial)
            # Sort variables to normalize order (e.g., "yx" -> "xy")
            sorted_vars = ''.join(sorted(var_part))
            monomials.append((sign * coeff, sorted_vars, len(sorted_vars)))

    # Group by variables and sum coefficients
    grouped = defaultdict(int)
    for coeff, vars_str, num_vars in monomials:
        grouped[vars_str] += coeff

    # Filter out zero coefficients
    terms = [(coeff, vars_str) for vars_str, coeff in grouped.items() if coeff != 0]

    # Sort by number of variables, then lexicographically
    terms.sort(key=lambda x: (len(x[1]), x[1]))

    # Format output
    result = []
    for i, (coeff, vars_str) in enumerate(terms):
        if coeff == 1 and vars_str:
            term = vars_str
        elif coeff == -1 and vars_str:
            term = '-' + vars_str
        else:
            term = str(coeff) + vars_str

        if i == 0:
            result.append(term)
        else:
            if term.startswith('-'):
                result.append('-' + term[1:])
            else:
                result.append('+' + term)

    # Join and handle special case of leading +
