def exchange_sort(sequence):
    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for num in sequence:
        count[num] += 1

    # Create target positions for each value
    target_positions = {}
    pos = 0
    for value in [7, 8, 9]:
        for i in range(count[value]):
            target_positions[pos + i] = value
        pos += count[value]

    # Create a mapping from current positions to target positions
    # We need to track where each element should go
    position_map = {}
    for i, num in enumerate(sequence):
        # Find the first available position for this value in target
        target_pos = -1
        for j in range(len(sequence)):
            if target_positions.get(j) == num and j not in position_map.values():
                target_pos = j
                break
        if target_pos != -1:
            position_map[i] = target_pos

    # Find cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i] and i in position_map:
            # Start a new cycle
            cycle_length = 0
            current = i
            while not visited[current]:
                visited[current] = True
                current = position_map[current]
                cycle_length += 1
            if cycle_length > 1:
                cycles += cycle_length - 1

    return cycles

