def differentiate(poly, x_val):
    # Insert spaces around + and - (except at start) to separate terms
    processed = poly
    for i in range(1, len(poly)):
        if poly[i] in '+-':
            processed = processed[:i] + ' ' + poly[i] + processed[i+1:]

    # Split into terms
    terms = processed.split()

    result = 0

    for term in terms:
        # Check if term has x
        has_x = 'x' in term

        if has_x:
            # Split at x to get coefficient and potential exponent
            x_pos = term.index('x')
            coeff_str = term[:x_pos]
            rest = term[x_pos+1:]

            # Parse coefficient
            if coeff_str == '' or coeff_str == '+':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)

            # Parse exponent
            if '^' in rest:
                exp_str = rest.split('^')[1]
                exponent = int(exp_str)
            else:
                exponent = 1
        else:
            # Constant term (exponent 0, derivative is 0)
            coeff = int(term)
            exponent = 0

        # Power rule: d/dx(coeff * x^exponent) = coeff * exponent * x^(exponent-1)
        if exponent == 0:
            continue  # derivative of constant is 0
        elif exponent == 1:
            result += coeff
        else:
            result += coeff * exponent * (x_val ** (exponent - 1))

    return result

def histogram(s):
