def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    def is_mersenne_prime(p):
        if not is_prime(p):
            return False

        # Calculate 2^p - 1
        mersenne = (1 << p) - 1

        # For small numbers, we can check directly
        if mersenne < 1000000:
            return is_prime(mersenne)

        # For larger numbers, use a more efficient primality test
        # Miller-Rabin test for larger numbers
        def miller_rabin(n, k=5):
            if n < 2:
                return False
            if n == 2 or n == 3:
                return True
            if n % 2 == 0:
                return False

            # Write n-1 as d * 2^r
            r = 0
            d = n - 1
            while d % 2 == 0:
                d //= 2
                r += 1

            # Witness loop
            import random
            for _ in range(k):
                a = random.randrange(2, n - 1)
                x = pow(a, d, n)
                if x == 1 or x == n - 1:
                    continue
                for _ in range(r - 1):
                    x = pow(x, 2, n)
                    if x == n - 1:
                        break
                else:
                    return False
            return True

        return miller_rabin(mersenne)

    return is_mersenne_prime(n)

def solution(input_string, markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the position of the first comment marker
        first_comment_pos = len(line)
        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < first_comment_pos:
                first_comment_pos = pos

        # If we found a comment marker, truncate the line
        if first_comment_pos < len(line):
            line = line[:first_comment_pos]

        # Strip trailing whitespace
        line = line.rstrip()

        result_lines.append(line)

    return '\n'.join(result_lines)

