def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Constants for time units in seconds
    # Year = 365 days, Day = 24 hours
    units = [
        (365 * 24 * 60 * 60, "year"),
        (24 * 60 * 60, "day"),
        (60 * 60, "hour"),
        (60, "minute"),
        (1, "second")
    ]

    parts = []

    for unit_seconds, unit_name in units:
        count = seconds // unit_seconds
        if count > 0:
            seconds %= unit_seconds
            suffix = "s" if count > 1 else ""
            parts.append(f"{count} {unit_name}{suffix}")

        # Optimization: if remaining seconds is 0, we can stop processing
        if seconds == 0:
            break

    if len(parts) == 1:
        return parts[0]
    elif len(parts) == 2:
        return f"{parts[0]} and {parts[1]}"
    else:
        return ", ".join(parts[:-1]) + " and " + parts[-1]

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, number) for sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract the numbers in the new order
    return [num for _, _, num in indexed_nums]

def compare(selector1, selector2):
    def get_specificity(selector):
        # Count the number of each type of selector
        id_count = selector.count('#')
        class_count = selector.count('.')
        tag_count = len([x for x in selector.split() if not x.startswith(('#', '.')) and x != '*'])

        # Handle the case where there are no tags but there are elements
        if tag_count == 0:
            # Check if it's just a tagname or a complex selector
            elements = selector.split()
            tag_count = len([x for x in elements if not x.startswith(('#', '.')) and x != '*'])

        # Special case: if selector is just "*" it has no specificity
        if selector.strip() == '*':
            return (0, 0, 0)

        # If there are no elements and no classes and no ids, it's a tagname
        if id_count == 0 and class_count == 0:
            # Count actual tag names (not classes or ids)
            tag_names = [x for x in selector.split() if not x.startswith(('#', '.')) and x != '*']
            tag_count = len(tag_names)

        return (id_count, class_count, tag_count)

    def normalize_selector(selector):
        # Remove extra spaces and normalize
        return ' '.join(selector.split())

    # Normalize selectors
    selector1 = normalize_selector(selector1)
    selector2 = normalize_selector(selector2)

    # Get specificities
    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    # Compare specificities
    if spec1 > spec2:
        return selector1
    elif spec2 > spec1:
        return selector2
    else:
        # If specificities are equal, the later one wins
        # In this problem, we're just comparing two selectors, so we return the first one
        return selector1

