                for dx in [-1, 0, 1]:
                    for dy in [-1, 0, 1]:
                        if dx == 0 and dy == 0:
                            continue
                        nx, ny = x + dx, y + dy
                        # Check if adjacent square is valid, not adjacent to white king, and not attacked
                        if (is_valid_pos(nx, ny) and 
                            not is_adjacent(nx, ny, king_x, king_y) and 
                            not can_attack(amazon_x, amazon_y, nx, ny)):
                            can_move = True
                            break
                    if can_move:
                        break

                if can_move:
                    result[3] += 1  # Safe with moves
                else:
                    result[2] += 1  # Stalemate

    return result

def pig_latin(word):
    if not word or not word.isalpha():
        return None

    word = word.lower()
    vowels = "aeiou"

    if word[0] in vowels:
        return word + "way"

    # Find the index where the first vowel occurs
    first_vowel_index = 0
    for i, char in enumerate(word):
        if char in vowels:
            first_vowel_index = i
            break
    else:
        # No vowels found
        return word + "ay"

    # Move consonants from beginning to end until first vowel
    result = word[first_vowel_index:] + word[:first_vowel_index] + "ay"
    return result

def get_closest_vowel(word):
    if len(word) < 3:
        return ""

    vowels = set('aeiouAEIOU')

    # Scan from right to left, starting from the second-to-last character
    # and ending at the second character (to ensure we have chars on both sides)
    for i in range(len(word) - 2, 0, -1):
        # Check if current character is a vowel
        if word[i] in vowels:
            # Check if both adjacent characters are consonants
            if word[i-1] not in vowels and word[i+1] not in vowels:
                return word[i]

    return ""

