from collections import Counter

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Handle empty string case
    if not test or test.strip() == '':
        return {}

    # Split the string by spaces to get individual letters
    letters = test.split()

    # Count frequency of each letter
    counts = Counter(letters)

    # Find the maximum occurrence
    max_count = max(counts.values())

    # Return all letters with the maximum count
    return {letter: count for letter, count in counts.items() if count == max_count}

def converter(number, decimals, base):
    if base < 2:
        raise ValueError("Base must be at least 2")

    # Handle special case of zero
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Separate integer and fractional parts
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_result = ''
    else:
        digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
        integer_result = ''
        while integer_part > 0:
            remainder = integer_part % base
            integer_result = digits[remainder] + integer_result
            integer_part //= base

    # Convert fractional part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            fractional_result += '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'[digit]
            fractional_part -= digit

    # Combine results
    if integer_result == '':
        result = '0' + fractional_result
    else:
        result = integer_result + fractional_result

    # Handle negative numbers
    if negative:
        result = '-' + result

    return result

import math

def converter(number, decimals=0, base=None):
    # Default base is pi
    if base is None:
        base = math.pi

    # Handle negative numbers
    if isinstance(number, (int, float)) and number < 0:
        sign = '-'
        number = abs(number)
    else:
        sign = ''

    # Handle zero case
    if number == 0:
        result = '0'
        if decimals > 0:
            result += '.' + '0' * decimals
        return sign + result

    # Helper function to get digit character
    def digit_char(d):
        d = int(d)
        if 0 <= d < 10:
            return str(d)
        else:
            return chr(ord('A') + d - 10)

    # Determine if base is a standard integer base (2-36)
    is_integer_base = isinstance(base, int) and 2 <= base <= 36

    if is_integer_base:
        # Standard integer base conversion
        result_int = []
        temp = int(number)

        if temp == 0:
            result_int = ['0']
        else:
            while temp > 0:
                remainder = temp % base
                result_int.append(digit_char(remainder))
                temp = temp // base
            result_int.reverse()

        result = ''.join(result_int)

        if decimals > 0:
            result += '.'
            fractional = number - int(number)
            for _ in range(decimals):
                fractional *= base
                digit = int(fractional)
                result += digit_char(digit)
                fractional -= digit

        return sign + result
    else:
        # Non-integer base conversion (like pi)
        max_digit = int(base)

        # Find the highest power needed for integer part
        power = 0
        while base ** (power + 1) <= number:
            power += 1

        result = []
        remainder = number

        # Integer part conversion
        for pos in range(power, -1, -1):
            place_value = base ** pos
            digit = int(remainder / place_value)
            digit = min(digit, max_digit)
            result.append(digit_char(digit))
            remainder -= digit * place_value

        # Handle case where number < 1 (no integer digits generated)
        if not result:
            result = ['0']
            remainder = number

        # Fractional part conversion
        if decimals > 0:
            result.append('.')
            for _ in range(decimals):
                remainder *= base
                digit = int(remainder)
                digit = min(digit, max_digit)
                result.append(digit_char(digit))
                remainder -= digit

        return sign + ''.join(result)

