        # Add current value to total and reset current
        if word in ['thousand', 'million']:
            total += current
            current = 0

    # Add the last current value
    total += current

    return total

def valid_mersenne(n):
    # A Mersenne number is of the form 2^p - 1 where p is a prime.
    # A Mersenne prime is a Mersenne number that is also prime.
    # This function checks if n is a Mersenne prime.

    def is_prime(k):
        if k < 2:
            return False
        if k == 2:
            return True
        if k % 2 == 0:
            return False
        i = 3
        while i * i <= k:
            if k % i == 0:
                return False
            i += 2
        return True

    # Step 1: Check if n is of the form 2^p - 1
    # So m = n + 1 must be a power of 2
    if n <= 0:
        return False

    m = n + 1
    # Check if m is a power of 2
    if (m & (m - 1)) != 0:
        return False

    # Find p such that 2^p = m
    # Since m is a power of 2, we can find p by counting trailing zeros or log2
    p = 0
    temp = m
    while temp > 1:
        p += 1
        temp >>= 1

    # Step 2: Check if p is prime
    return is_prime(p)

