def cycpattern_check(a, b):
    # Handle edge cases
    if not b:
        return True
    if len(b) > len(a):
        return False

    # Create doubled string to contain all rotations
    bb = b + b

    # Check if any substring of a with length len(b) is a rotation of b
    for i in range(len(a) - len(b) + 1):
        substring = a[i:i + len(b)]
        if substring in bb:
            return True

    return False

import math

def converter(number, decimals=0, base=math.pi):
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36")

    # Handle zero case
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    if base == math.pi:
        # Special handling for pi base
        digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % 1
            if remainder >= 0.5:
                digit = 1
            else:
                digit = 0
            digits.append(str(digit))
            temp = (temp - digit) / math.pi
        # Reverse the digits since we built them backwards
        integer_result = ''.join(reversed(digits))
    else:
        # Standard base conversion for integer bases
        digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % int(base)
            if remainder < 10:
                digits.append(str(remainder))
            else:
                digits.append(chr(ord('A') + remainder - 10))
            temp //= int(base)
        integer_result = ''.join(reversed(digits))

    # Handle fractional part
    fractional_part = number - integer_part
    if decimals == 0:
        result = integer_result
    else:
        fractional_digits = []
        temp_fraction = fractional_part
        for _ in range(decimals):
            temp_fraction *= base
            digit = int(temp_fraction)
            if digit < 10:
                fractional_digits.append(str(digit))
            else:
                fractional_digits.append(chr(ord('A') + digit - 10))
            temp_fraction -= digit
        fractional_result = ''.join(fractional_digits)
        result = integer_result + '.' + fractional_result

    # Handle negative numbers
    if negative:
        result = '-' + result

    # Handle leading zero for values < 1
    if number < 1 and not negative:
        if '.' not in result:
            result = '0.' + result
        else:
            # Check if we need to add leading zero before decimal point
            parts = result.split('.')
            if len(parts[0]) == 0:
                result = '0.' + parts[1]

    return result

def parse_int(s):
