            current = 0

    result += current
    return result

def largest_divisor(n: int) -> int:
    if n <= 1:
        return None  # or raise an exception, depending on requirements

    # Find the smallest prime factor
    smallest_factor = n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            smallest_factor = i
            break

    # If no factor found, n is prime, so largest proper divisor is 1
    if smallest_factor == n:
        return 1

    # Otherwise, largest proper divisor is n divided by smallest prime factor
    return n // smallest_factor

def smallest_change(arr):
    if len(arr) <= 1:
        return 0

    changes = 0
    left = 0
    right = len(arr) - 1

    while left < right:
        if arr[left] != arr[right]:
            changes += 1
        left += 1
        right -= 1

    return changes

def separate_paren_groups(s):
    result = []
    current_group = ""
    depth = 0

    for char in s:
        if char == ' ':
            continue

        current_group += char

        if char == '(':
            depth += 1
        elif char == ')':
            depth -= 1

        if depth == 0 and current_group:
            result.append(current_group)
            current_group = ""

    return result

