def compare(s1, s2):
    def get_specificity(selector):
        ids = 0
        classes = 0
        tags = 0

        # Split by spaces to get individual elements
        elements = selector.split()

        for element in elements:
            # Count IDs
            ids += element.count('#')

            # Count classes (including grouped classes like .a.b)
            class_count = 0
            i = 0
            while i < len(element):
                if element[i] == '.':
                    class_count += 1
                    # Skip to the next dot or end of string
                    i += 1
                    while i < len(element) and element[i] != '.':
                        i += 1
                else:
                    i += 1
            classes += class_count

            # Count tags (elements that are not IDs or classes)
            if not element.startswith('#') and not element.startswith('.'):
                tags += 1
            elif element.startswith('#') or element.startswith('.'):
                # Check if it's a tag name mixed with ID or class
                # For example: div#id.class or .class#id
                # We need to count the tag part
                tag_part = ""
                i = 0
                while i < len(element):
                    if element[i] == '#' or element[i] == '.':
                        break
                    tag_part += element[i]
                    i += 1
                if tag_part and not tag_part.isspace():
                    tags += 1
            else:
                tags += 1

        return (ids, classes, tags)

    # Special case for star selector
    if s1 == "*":
        return s2
    if s2 == "*":
        return s1

    spec1 = get_specificity(s1)
    spec2 = get_specificity(s2)

    # Compare specificity
    if spec1 > spec2:
        return s1
    elif spec2 > spec1:
        return s2
    else:
        # If specificity is equal, the second selector wins (tie-breaker)
        return s2

def getAllPrimeFactors(n):
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []
    if isinstance(n, float) and not n.is_integer():
        return []
    if n < 1:
        return []
    if n == 1:
        return [1]

    factors = []
    temp = int(n)
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            factors.append(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)
    return factors


def getUniquePrimeFactorsWithCount(n):
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return [[], []]
    if isinstance(n, float) and not n.is_integer():
        return [[], []]
    if n < 1:
        return [[], []]
    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)
    if not factors:
        return [[], []]

    unique_factors = []
    counts = []
    current = factors[0]
    count = 0

    for factor in factors:
        if factor == current:
            count += 1
        else:
            unique_factors.append(current)
            counts.append(count)
            current = factor
            count = 1

    unique_factors.append(current)
    counts.append(count)

    return [unique_factors, counts]


def getUniquePrimeFactorsWithProducts(n):
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []
    if isinstance(n, float) and not n.is_integer():
        return []
    if n < 1:
        return []
    if n == 1:
        return [1]

    unique_factors, counts = getUniquePrimeFactorsWithCount(n)
    return [f ** c for f, c in zip(unique_factors, counts)]

from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    """
    if not numbers:
        return (0, 1)

    total_sum = sum(numbers)
    total_product = 1
    for num in numbers:
        total_product *= num

    return (total_sum, total_product)

def amazon_check_mate(king, amazon):
    # Convert chess notation to coordinates (0-7 for both dimensions)
    def parse_position(pos):
        file = ord(pos[0]) - ord('a')  # a=0, b=1, ..., h=7
        rank = int(pos[1]) - 1  # 1=0, 2=1, ..., 8=7
        return (file, rank)

    # Get all squares attacked by the amazon
    def amazon_attacks(file, rank):
        attacks = set()

        # Queen-like moves
        # Horizontal
        for f in range(8):
            if f != file:
                attacks.add((f, rank))

        # Vertical
        for r in range(8):
            if r != rank:
                attacks.add((file, r))

        # Diagonal (top-right, top-left, bottom-right, bottom-left)
        for direction in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
            df, dr = direction
            f, r = file + df, rank + dr
            while 0 <= f < 8 and 0 <= r < 8:
                attacks.add((f, r))
                f += df
                r += dr

        # Knight-like moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), 
                       (1, -2), (1, 2), (2, -1), (2, 1)]
        for df, dr in knight_moves:
            f = file + df
            r = rank + dr
            if 0 <= f < 8 and 0 <= r < 8:
                attacks.add((f, r))

        return attacks

    # Get all squares adjacent to a position (king's movement range)
    def adjacent_squares(file, rank):
        adjacent = set()
        for df in [-1, 0, 1]:
            for dr in [-1, 0, 1]:
                if df == 0 and dr == 0:
                    continue
                f = file + df
                r = rank + dr
                if 0 <= f < 8 and 0 <= r < 8:
                    adjacent.add((f, r))
        return adjacent

    # Get all king's possible moves from a position
    def king_moves(file, rank):
        moves = set()
        for df in [-1, 0, 1]:
            for dr in [-1, 0, 1]:
                if df == 0 and dr == 0:
                    continue
                f = file + df
                r = rank + dr
                if 0 <= f < 8 and 0 <= r < 8:
                    moves.add((f, r))
        return moves

    white_king_pos = parse_position(king)
    amazon_pos = parse_position(amazon)

    amazon_attacks_set = amazon_attacks(amazon_pos[0], amazon_pos[1])
    white_king_adjacent = adjacent_squares(white_king_pos[0], white_king_pos[1])

    checkmate = 0
    check = 0
    stalemate = 0
    safe_with_moves = 0

    # Iterate through all possible black king positions
    for file in range(8):
        for rank in range(8):
            black_pos = (file, rank)

            # Black king cannot be adjacent to white king
            if black_pos in white_king_adjacent:
                continue

            # Black king cannot occupy the same square as amazon (amazon is a piece)
            if black_pos == amazon_pos:
                continue

            # Black king cannot occupy the same square as white king
            if black_pos == white_king_pos:
                continue

            under_attack = black_pos in amazon_attacks_set

            # Get all valid moves for black king from this position
            possible_moves = king_moves(file, rank)
            valid_moves = []

            for move in possible_moves:
                # Move cannot be adjacent to white king
                if move in white_king_adjacent:
                    continue
                # Move cannot be on amazon's square
                if move == amazon_pos:
                    continue
                # Move cannot be on white king's square
                if move == white_king_pos:
                    continue
                # Move cannot be under amazon attack
                if move in amazon_attacks_set:
                    continue
                valid_moves.append(move)

            if under_attack:
                # Black king is in check
                if len(valid_moves) == 0:
                    checkmate += 1
                else:
                    check += 1
            else:
                # Black king is not in check
                if len(valid_moves) == 0:
                    stalemate += 1
                else:
                    safe_with_moves += 1

    return [checkmate, check, stalemate, safe_with_moves]

import re

def simplify(expression):
    """
    Simplifies a multilinear polynomial expression by combining like terms,
    normalizing variable order, and formatting the output correctly.

    Args:
        expression: A string representing a multilinear polynomial (e.g., "3x-yx+2xy-x")

    Returns:
        A simplified string representation of the polynomial
    """
    if not expression:
        return ""

    # Step 1: Parse the expression into terms using regex
    terms = re.findall(r'[+-]?[\d]*[a-z]+', expression)

    # Step 2: Dictionary to store coefficients for each normalized variable combination
    coeffs = {}

    for term in terms:
        # Extract sign
        if term and term[0] in ['+', '-']:
            sign_part = term[0]
            rest = term[1:]
        else:
            sign_part = '+'
            rest = term

        # Extract coefficient and variables
        # Pattern: optional digits followed by one or more lowercase letters
        match = re.match(r'^(\d*)([a-z]+)$', rest)
        if match:
            coef_str, variables = match.groups()
            # Implicit coefficient of 1 if no digits are present
            coef = int(coef_str) if coef_str else 1

            # Apply sign
            if sign_part == '-':
                coef = -coef

            # Normalize variables (sort alphabetically)
            variables = ''.join(sorted(variables))

            # Aggregate coefficients for like terms
            coeffs[variables] = coeffs.get(variables, 0) + coef

    # Step 3: Filter out terms with zero coefficient
    coeffs = {k: v for k, v in coeffs.items() if v != 0}

    # Step 4: Sort by degree (number of variables), then lexicographically
    sorted_terms = sorted(coeffs.items(), key=lambda x: (len(x[0]), x[0]))

    # Step 5: Format output string
    result_parts = []
    for i, (variables, coef) in enumerate(sorted_terms):
        # Handle first term separately (no leading '+' for positive)
        if i == 0:
            if coef == 1:
                result_parts.append(variables)
            elif coef == -1:
                result_parts.append('-' + variables)
            else:
                result_parts.append(str(coef) + variables)
        else:
            # Subsequent terms include sign
            if coef == 1:
                result_parts.append('+' + variables)
            elif coef == -1:
                result_parts.append('-' + variables)
            elif coef > 0:
                result_parts.append('+' + str(coef) + variables)
            else:
                result_parts.append(str(coef) + variables)

    return ''.join(result_parts)

def is_balanced(s, pairs):
    # Build mapping of opening characters to their closing counterparts
    open_to_close = {}
    close_chars = set()

    # Parse pairs string: even indices are open, odd indices are close
    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        open_to_close[open_char] = close_char
        close_chars.add(close_char)

    # Stack to track opening characters
    stack = []

    # Process each character in the input string
    for char in s:
        if char in open_to_close:
            # It's an opening character, push to stack
            stack.append(char)
        elif char in close_chars:
            # It's a closing character, must match the most recent opening
            if not stack:
                return False  # Nothing to close
            last_open = stack.pop()
            if open_to_close[last_open] != char:
                return False  # Mismatched pair

    # All opening characters must be closed
    return len(stack) == 0

def decode_shift(s: str):
