def sum_of_squares(n):
    # Step 1: Check if n is a perfect square
    import math
    sqrt_n = math.isqrt(n)
    if sqrt_n * sqrt_n == n:
        return 1

    # Step 2: Check if n can be written as sum of two perfect squares
    for i in range(1, sqrt_n + 1):
        remainder = n - i * i
        sqrt_remainder = math.isqrt(remainder)
        if sqrt_remainder * sqrt_remainder == remainder:
            return 2

    # Step 3: Check if n is of the form 4^k*(8m+7) (Legendre's three-square theorem)
    temp = n
    while temp % 4 == 0:
        temp //= 4
    if temp % 8 == 7:
        return 4

    # Step 4: Otherwise, answer is 3
    return 3

def sum_of_squares(n):
    # Helper function to check if a number is a perfect square
    def is_perfect_square(x):
        root = int(x**0.5)
        return root * root == x

    # Case 1: Check if n itself is a perfect square
    if is_perfect_square(n):
        return 1

    # Case 2: Check if n can be written as sum of 2 perfect squares
    for i in range(1, int(n**0.5) + 1):
        j = n - i * i
        if j < i * i:  # Avoid duplicate checks (symmetry optimization)
            break
        if is_perfect_square(j):
            return 2

    # Case 3 & 4: Apply Legendre's three-square theorem
    # A number can be written as sum of 3 squares iff it's NOT of form 4^a(8b + 7)
    temp = n
    while temp % 4 == 0:
        temp //= 4

    if temp % 8 == 7:
        return 4

    return 3

