            if char.isupper():
                # For uppercase letters
                shifted = chr((ord(char) - ord('A') + 4) % 26 + ord('A'))
            else:
                # For lowercase letters
                shifted = chr((ord(char) - ord('a') + 4) % 26 + ord('a'))
            result += shifted
        else:
            # Non-alphabetic characters remain unchanged
            result += char
    return result

def compare(selector1, selector2):
    def parse_selector(s):
        ids = 0
        classes = 0
        tags = 0

        parts = s.split()

        for part in parts:
            if part == '*':
                continue

            ids += part.count('#')
            classes += part.count('.')

            # Check if there's a tagname (alphanumeric at the start, before # or .)
            if part and part[0] not in '#.':
                tags += 1

        return (ids, classes, tags)

    spec1 = parse_selector(selector1)
    spec2 = parse_selector(selector2)

    # Compare specificity: (ids, classes, tags) in order of importance
    if spec1 > spec2:
        return selector1
    elif spec2 > spec1:
        return selector2
    else:
        # If all counts are equal, return the later appearing selector
        return selector2

def valid_mersenne(n):
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False

        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6

        return True

    if n <= 0:
        return False

    if n == 1:
        return False

    if not is_prime(n):
        return False

    m = 2**n - 1
    s = 4
    for _ in range(n - 2):
        s = (s * s - 2) % m

    return s == 0

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units (value in seconds, singular name, plural name)
    units = [
        (31536000, "year", "years"),   # 365 days
        (86400, "day", "days"),         # 24 hours
        (3600, "hour", "hours"),        # 60 minutes
        (60, "minute", "minutes"),      # 60 seconds
        (1, "second", "seconds")        # 1 second
    ]

    parts = []
    remaining = seconds

    for value, singular, plural in units:
        count = remaining // value
        remaining = remaining % value
        if count > 0:
            unit_name = plural if count > 1 else singular
            parts.append(f"{count} {unit_name}")

    if len(parts) == 1:
        return parts[0]
    elif len(parts) == 2:
        return parts[0] + " and " + parts[1]
    else:
        return ", ".join(parts[:-1]) + " and " + parts[-1]

def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0

    # Iterate through the range 1 to n inclusive
    for i in range(1, n + 1):
        # Check if the number is a palindrome by comparing string with its reverse
        s = str(i)
        if s == s[::-1]:
            # Classify as even or odd
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    # Return the counts as a tuple
    return (even_count, odd_count)

