    return changes

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle sign
    sign = ''
    if number < 0:
        sign = '-'
        number = -number

    # Convert integer part
    integer_part = int(number)
    digits = []

    # Special case for base 2
    if base == 2:
        temp = integer_part
        while temp > 0:
            digits.append(str(temp % 2))
            temp //= 2
        digits.reverse()
        integer_result = ''.join(digits) if digits else '0'
    else:
        # General case for any base
        temp = integer_part
        while temp > 0:
            remainder = temp % int(base)
            digits.append(str(remainder))
            temp = temp // int(base)
        digits.reverse()
        integer_result = ''.join(digits) if digits else '0'

    # Convert fractional part
    fractional_part = number - integer_part
    fractional_digits = []

    if decimals > 0:
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            fractional_digits.append(str(digit))
            fractional_part -= digit

    # Build result
    if decimals == 0:
        result = integer_result
    else:
        fractional_str = ''.join(fractional_digits)
        # Handle the case where we have trailing zeros
        if fractional_str.rstrip('0'):
            result = integer_result + '.' + fractional_str.rstrip('0')
        else:
            result = integer_result + '.' + fractional_str

    # Handle leading zero for numbers less than 1
    if number < 1 and decimals > 0:
        if not result.startswith('0.'):
            result = '0' + result

    return sign + result

def correct_polish_letters(st):
    diacritics = {
        'ą': 'a', 'ć': 'c', 'ę': 'e', 'ł': 'l',
        'ń': 'n', 'ó': 'o', 'ś': 's', 'ź': 'z', 'ż': 'z'
    }

    result = []
    for char in st:
        if char in diacritics:
            result.append(diacritics[char])
        else:
            result.append(char)

    return ''.join(result)

def exchange_sort(sequence):
    # Count occurrences of each element
    count = {7: 0, 8: 0, 9: 0}
    for num in sequence:
        count[num] += 1

    # Create target sorted sequence
    target = []
    target.extend([7] * count[7])
    target.extend([8] * count[8])
    target.extend([9] * count[9])

    # Find positions where elements are misplaced
    misplaced = []
    for i in range(len(sequence)):
        if sequence[i] != target[i]:
            misplaced.append((i, sequence[i], target[i]))

    # If no misplaced elements, return 0
    if not misplaced:
        return 0

    # Create a mapping from current positions to target positions
    # and find cycles
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i] and sequence[i] != target[i]:
            # Start a new cycle
            cycles += 1
            current = i
            while not visited[current]:
                visited[current] = True
                # Find where the element at current position should go
                for j in range(len(sequence)):
                    if sequence[current] == target[j]:
                        current = j
                        break

    # Minimum swaps = n - cycles
    return len(sequence) - cycles

def count_divisors(n):
    if n <= 0:
        return 0

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

