import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    if integer_part == 0:
        integer_result = ''
    else:
        digits = []
        temp = integer_part
        while temp > 0:
            digits.append(temp % int(base))
            temp //= int(base)
        integer_result = ''.join(convert_digit(d) for d in reversed(digits))

    # Convert fractional part
    fractional_part = number - integer_part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            fractional_result += convert_digit(digit)
            fractional_part -= digit

    # Combine results
    result = integer_result + fractional_result

    # Handle negative sign
    if negative:
        result = '-' + result

    # Handle case where integer part is empty (e.g., 0.5)
    if result.startswith('.'):
        result = '0' + result

    return result

def convert_digit(digit):
    if digit < 10:
        return str(digit)
    else:
        return chr(ord('A') + digit - 10)

