def order_by_points(nums):
    """
    Sorts a list of numbers by the sum of their digits in ascending order.
    If two numbers have the same digit sum, they are sorted by their actual value.

    Args:
        nums: List of integers

    Returns:
        List of integers sorted by digit sum, then by value
    """
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    return sorted(nums, key=lambda x: (digit_sum(x), x))

def median(numbers):
    if not numbers:
        raise ValueError("Cannot compute median of an empty list")

    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)
    mid = n // 2

    if n % 2 == 1:
        return float(sorted_numbers[mid])
    else:
        return (sorted_numbers[mid - 1] + sorted_numbers[mid]) / 2.0

