            # If we have more closing brackets than opening brackets at any point,
            # the string is invalid
            if balance < 0:
                return False

    # All brackets are matched if balance is exactly 0
    return balance == 0

def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def coords_to_chess(row, col):
        return chr(ord('a') + row) + str(col + 1)

    def is_valid(row, col):
        return 0 <= row < 8 and 0 <= col < 8

    king_pos = chess_to_coords(king)
    amazon_pos = chess_to_coords(amazon)

    # Knight moves (8 possible L-shapes)
    knight_moves = [
        (-2, -1), (-2, 1), (-1, -2), (-1, 2),
        (1, -2), (1, 2), (2, -1), (2, 1)
    ]

    # Rook-like moves (horizontal and vertical)
    rook_moves = [
        (-1, 0), (1, 0), (0, -1), (0, 1)
    ]

    # Bishop-like moves (diagonal)
    bishop_moves = [
        (-1, -1), (-1, 1), (1, -1), (1, 1)
    ]

    # All possible moves for amazon (queen + knight)
    amazon_moves = rook_moves + bishop_moves + knight_moves

    # Get all squares attacked by amazon
    attacked_squares = set()

    # Add knight moves
    for dr, dc in knight_moves:
        new_row, new_col = amazon_pos[0] + dr, amazon_pos[1] + dc
        if is_valid(new_row, new_col):
            attacked_squares.add((new_row, new_col))

    # Add rook and bishop moves (queen-like)
    for dr, dc in rook_moves + bishop_moves:
        new_row, new_col = amazon_pos[0] + dr, amazon_pos[1] + dc
        # Move in direction until board edge or blocked by white king
        while is_valid(new_row, new_col):
            # Check if white king blocks the attack
            if (new_row, new_col) == king_pos:
                break
            attacked_squares.add((new_row, new_col))
            new_row += dr
            new_col += dc

    # Get all squares adjacent to white king (white king protection)
    king_adjacent = set()
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            new_row, new_col = king_pos[0] + dr, king_pos[1] + dc
            if is_valid(new_row, new_col):
                king_adjacent.add((new_row, new_col))

    # Get all squares that are safe (not attacked by amazon and not adjacent to white king)
    safe_squares = set()
    for row in range(8):
        for col in range(8):
            if (row, col) not in attacked_squares and (row, col) not in king_adjacent:
                safe_squares.add((row, col))

    # Count results
    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    # Check each square for black king position
    for row in range(8):
        for col in range(8):
            # Skip if square is occupied by white king or amazon
            if (row, col) == king_pos or (row, col) == amazon_pos:
                continue

            # Skip if square is adjacent to white king
            is_adjacent_to_king = False
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    new_row, new_col = king_pos[0] + dr, king_pos[1] + dc
                    if is_valid(new_row, new_col) and (new_row, new_col) == (row, col):
                        is_adjacent_to_king = True
                        break
                if is_adjacent_to_king:
                    break
            if is_adjacent_to_king:
                continue

            # Check if black king is under attack
            is_under_attack = (row, col) in attacked_squares

            # Check if black king can move to any safe square
            can_move = False
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    new_row, new_col = row + dr, col + dc
                    if is_valid(new_row, new_col):
                        # Check if new square is safe (not attacked by amazon and not adjacent to white king)
                        if (new_row, new_col) not in attacked_squares and (new_row, new_col) not in king_adjacent:
                            can_move = True
                            break
                if can_move:
                    break

            if is_under_attack:
                if can_move:
                    check += 1
                else:
                    checkmate += 1
            else:
                if can_move:
                    safe += 1
                else:
                    stalemate += 1

    return [checkmate, check, stalemate, safe]

def compare(selector1, selector2):
