            classes += comp.count('.')
            without_symbols = comp.replace('#', '').replace('.', '')
            if without_symbols and without_symbols != '*':
                tags += 1
        return (ids, classes, tags)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    if spec1 > spec2:
