def getAllPrimeFactors(n):
    # Input validation: must be a number
    if not isinstance(n, (int, float, bool)):
        return []

    # Boolean is a subclass of int in Python, exclude it
    if isinstance(n, bool):
        return []

    # Check if it's a float and not an integer
    if isinstance(n, float):
        if not n.is_integer():
            return []
        n = int(n)

    # Check for negative numbers
    if n < 0:
        return []

    # Handle edge cases
    if n == 0:
        return []

    if n == 1:
        return [1]

    # Prime factorization algorithm
    factors = []
    temp = n
    d = 2

    # Trial division up to sqrt(temp)
    while d * d <= temp:
        while temp % d == 0:
            factors.append(d)
            temp = temp // d
        d += 1

    # If remaining temp is a prime > 1
    if temp > 1:
        factors.append(temp)

    return factors

