def simplify(expression):
    if not expression:
        return ""

    terms = []
    i = 0
    n = len(expression)

    while i < n:
        # Determine sign
        sign = 1
        if expression[i] == '+':
            sign = 1
            i += 1
        elif expression[i] == '-':
            sign = -1
            i += 1

        # Parse coefficient
        coeff_start = i
        while i < n and expression[i].isdigit():
            i += 1

        if i == coeff_start:
            coeff = 1
        else:
            coeff = int(expression[coeff_start:i])

        coeff *= sign

        # Parse variables
        vars_start = i
        while i < n and expression[i].isalpha():
            i += 1

        vars_str = expression[vars_start:i]
        vars_sorted = ''.join(sorted(vars_str))

        terms.append((coeff, vars_sorted))

    # Combine like terms
    combined = {}

    for coeff, vars_str in terms:
        if vars_str not in combined:
            combined[vars_str] = 0
        combined[vars_str] += coeff

    # Filter out zero coefficients
    non_zero_terms = [(coeff, vars) for vars, coeff in combined.items() if coeff != 0]

    # Sort by number of variables, then lexicographically
    non_zero_terms.sort(key=lambda x: (len(x[1]), x[1]))

    # Format output
    result = []
    for coeff, vars in non_zero_terms:
        if coeff > 0:
            if result:
                result.append('+')
            if abs(coeff) != 1:
                result.append(str(coeff))
            result.append(vars)
        else:  # coeff < 0
            if result:
                result.append('+')
            if abs(coeff) != 1:
                result.append(str(-coeff))
            result.append(vars)

    return ''.join(result) if result else ""

