import math

def converter(number, decimals=0, base=math.pi):
    if base < 2:
        raise ValueError("Base must be greater than or equal to 2")

    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    is_negative = number < 0
    number = abs(number)

    # Separate integer and fractional parts
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_result = ''
    else:
        digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            # Handle floating point precision issues
            if remainder >= base:
                remainder = base - 1e-10
            digits.append(remainder)
            temp = int((temp - remainder) / base)

        # Convert digits to proper representation
        integer_result = ''
        for digit in reversed(digits):
            if digit < 10:
                integer_result += str(int(digit))
            else:
                integer_result += chr(ord('A') + int(digit) - 10)

    # Convert fractional part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            if digit < 10:
                fractional_result += str(digit)
            else:
                fractional_result += chr(ord('A') + digit - 10)
            fractional_part -= digit

    # Combine results
    if integer_result == '':
        result = '0' + fractional_result
    else:
        result = integer_result + fractional_result

    # Handle negative sign
    if is_negative:
        result = '-' + result

    return result

from typing import List, Tuple, Union

def sum_product(numbers: List[Union[int, List[int]]]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    # Flatten the input list
    def flatten(lst):
        result = []
        for item in lst:
            if isinstance(item, list):
                result.extend(flatten(item))
            else:
                result.append(item)
        return result

    # Flatten the input
    flattened = flatten(numbers)

    # Handle empty list case
    if not flattened:
        return (0, 1)

    # Calculate sum and product
    total_sum = sum(flattened)

    product = 1
    for num in flattened:
        product *= num

    return (total_sum, product)

def is_balanced(content, bracket_pairs):
    # Create a mapping of opening to closing brackets and vice versa
    bracket_map = {}
    for i in range(0, len(bracket_pairs), 2):
        open_bracket = bracket_pairs[i]
        close_bracket = bracket_pairs[i + 1]
        bracket_map[open_bracket] = close_bracket
        # If opening and closing are the same character, it's a dual-role bracket
        if open_bracket == close_bracket:
            if open_bracket in bracket_map:
                # Already exists, which is fine for dual roles
                pass
            else:
                bracket_map[open_bracket] = close_bracket
        else:
            # For different brackets, we need to track both directions
            if close_bracket not in bracket_map:
                bracket_map[close_bracket] = None  # Mark as closing

    # Stack to keep track of opening brackets
    stack = []

    for char in content:
        # If it's an opening bracket
        if char in bracket_map and (bracket_map[char] is not None or char in bracket_map):
            # Check if it's a dual-role bracket (same char for open and close)
            if char in bracket_map and bracket_map[char] == char:
                stack.append(char)
            elif char in bracket_map and bracket_map[char] is not None:
                # Regular opening bracket
                stack.append(char)
        # If it's a closing bracket
        elif char in bracket_map and bracket_map[char] is None:
            # This is a closing bracket that's also an opening bracket (dual role)
            if not stack or stack[-1] != char:
                return False
            stack.pop()
        elif char in bracket_map:
            # Regular closing bracket
            if not stack or bracket_map[stack[-1]] != char:
                return False
            stack.pop()

    # If stack is empty, all brackets were matched
    return len(stack) == 0

def poohbear(code):
    # Initialize memory and pointers
    memory = {}
    pointer = 0
    copied_value = 0
    code_ptr = 0
    loop_stack = []
    output = []

    # Parse code to find loop pairs
    loop_pairs = {}
    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                start = stack.pop()
                loop_pairs[start] = i
                loop_pairs[i] = start

    # Execute code
    while code_ptr < len(code):
        char = code[code_ptr]

        if char == '+':
            memory[pointer] = memory.get(pointer, 0) + 1
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == '-':
            memory[pointer] = memory.get(pointer, 0) - 1
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copied_value = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copied_value
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                if code_ptr in loop_pairs:
                    code_ptr = loop_pairs[code_ptr]
            else:
                loop_stack.append(code_ptr)
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                if loop_stack:
                    code_ptr = loop_stack[-1] - 1
            else:
                if code_ptr in loop_pairs:
                    loop_stack.pop()
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif char == 'T':
            memory[pointer] = memory.get(pointer, 0) * 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'Q':
            memory[pointer] = memory.get(pointer, 0) ** 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'U':
            import math
            memory[pointer] = int(math.sqrt(memory.get(pointer, 0)))
        elif char == 'L':
            memory[pointer] = memory.get(pointer, 0) + 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'V':
            memory[pointer] = memory.get(pointer, 0) // 2
        elif char == 'A':
            memory[pointer] = memory.get(pointer, 0) + copied_value
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'B':
            memory[pointer] = memory.get(pointer, 0) - copied_value
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'Y':
            memory[pointer] = memory.get(pointer, 0) * copied_value
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'D':
            if copied_value != 0:
                memory[pointer] = memory.get(pointer, 0) // copied_value
            else:
                memory[pointer] = 0

        code_ptr += 1

    return ''.join(output)

def compare(selector1, selector2):
    def get_specificity(selector):
        id_count = 0
        class_count = 0
        tag_count = 0

        # Split by whitespace to get individual tokens
        tokens = selector.split()

        for token in tokens:
            # Count IDs
            id_count += token.count('#')

            # Count classes (handle multiple classes in one token like ".a.b")
            class_count += token.count('.')

            # Count tags (elements that are not IDs or classes)
            if not token.startswith('#') and not token.startswith('.'):
                tag_count += 1
            else:
                # If token starts with # or ., we need to count the actual tag part
                # Find where the tag part starts (after # or .)
                if '#' in token:
                    # Extract tag part before first #
                    tag_part = token.split('#')[0]
                    if tag_part and tag_part.isalnum():
                        tag_count += 1
                elif '.' in token:
                    # Extract tag part before first .
                    tag_part = token.split('.')[0]
                    if tag_part and tag_part.isalnum():
                        tag_count += 1
                else:
                    # This shouldn't happen for valid CSS, but just in case
                    if token.isalnum():
                        tag_count += 1

        # Handle the case where we have tokens like "div#id.class" - we want to count the tag "div"
        # We need to reprocess tokens to properly count tags
        tag_count = 0
        for token in tokens:
            # Remove all # and . from the token to get the tag
            clean_token = ''.join(c for c in token if c not in '#.')
            # If there's something left and it's alphanumeric, it's a tag
            if clean_token and clean_token.isalnum():
                tag_count += 1

        return (id_count, class_count, tag_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    # Compare specificity
    if spec1 > spec2:
        return selector1
    else:
        return selector2

def histogram(s):
    # Split the input string into a list of tokens based on whitespace
    tokens = s.split()

    # If the list is empty (e.g., empty string or only whitespace), return empty dict
    if not tokens:
        return {}

    # Count the frequency of each letter
    counts = {}
    for letter in tokens:
        if letter in counts:
            counts[letter] += 1
        else:
            counts[letter] = 1

    # Find the maximum frequency
    max_freq = max(counts.values())

    # Create a dictionary with only the letters that have the maximum frequency
    result = {letter: count for letter, count in counts.items() if count == max_freq}

