def is_balanced(s, pairs):
    if not pairs:
        return True

    open_chars = set()
    close_chars = set()
    close_to_open = {}

    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        open_chars.add(open_char)
        close_chars.add(close_char)
        close_to_open[close_char] = open_char

    stack = []

    for char in s:
        if char in close_to_open:
            required_open = close_to_open[char]
            if char in open_chars:
                if stack and stack[-1] == required_open:
                    stack.pop()
                else:
                    stack.append(char)
            else:
                if not stack or stack[-1] != required_open:
                    return False
                stack.pop()
        elif char in open_chars:
            stack.append(char)

    return len(stack) == 0

def fib4(n: int):
    if n < 0:
        return 0

    # Base cases
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize the first four values
    prev4, prev3, prev2, prev1 = 0, 0, 2, 0

    # Iteratively compute fib4(n)
    for i in range(4, n + 1):
        current = prev1 + prev2 + prev3 + prev4
        # Shift the window
        prev4, prev3, prev2, prev1 = prev3, prev2, prev1, current

    return prev1

def largest_divisor(n: int) -> int:
    if n <= 1:
        return 1

    largest = 1

    # Check divisors up to sqrt(n)
    i = 2
    while i * i <= n:
        if n % i == 0:
            # i is a divisor
            largest = max(largest, i)
            # n/i is also a divisor (if it's different from i)
            if n // i != i:
                largest = max(largest, n // i)
        i += 1

    return largest

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    # Split the string and count occurrences
    letters = test.split()
    if not letters:
        return {}

    # Count each letter
    count_dict = {}
    for letter in letters:
        count_dict[letter] = count_dict.get(letter, 0) + 1

    # Find the maximum count
    max_count = max(count_dict.values())

    # Return dictionary with only the letters that have the maximum count
    return {letter: count for letter, count in count_dict.items() if count == max_count}

def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    # For 2^n - 1 to be prime, n must be prime (but not all prime n give prime 2^n - 1)
    if not is_prime(n):
        return False

    # Special case: 2^1 - 1 = 1, which is not prime
    if n == 1:
        return False

    # Calculate 2^n - 1 and check if it's prime
    mersenne_number = (1 << n) - 1  # This is 2^n - 1

    return is_prime(mersenne_number)

