    # 3-digit palindromes (101, 111, 121, ..., 999)
    if n >= 100:
        for i in range(1, 10):  # first digit 1-9
            for j in range(0, 10):  # middle digit 0-9
                palindrome = i * 100 + j * 10 + i
                if palindrome <= n:
                    if palindrome % 2 == 0:
                        even_count += 1
                    else:
                        odd_count += 1

    # 4-digit palindromes (1001, 1111, 1221, ..., 9999)
    # But since n <= 1000, no 4-digit palindromes are possible

    return (even_count, odd_count)

def fib4(n):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize the first four values
    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute fib4(n)
    for i in range(4, n + 1):
        next_val = a + b + c + d
        # Slide the window
        a, b, c, d = b, c, d, next_val

    return d

