def differentiate(polynomial, x):
    # Split the polynomial into terms
    # Handle the case where the first term might not start with a +
    terms = []
    current_term = ""

    for i, char in enumerate(polynomial):
        if char in ['+', '-'] and i > 0:
            terms.append(current_term)
            current_term = char
        else:
            current_term += char

    terms.append(current_term)

    # Process each term
    result = 0

    for term in terms:
        term = term.strip()
        if not term:
            continue

        # Handle the coefficient and exponent
        if 'x^' in term:
            # Term is like "3x^2" or "-3x^2"
            parts = term.split('x^')
            coeff_str = parts[0]
            exp = int(parts[1])

            # Handle coefficient
            if coeff_str == '+' or coeff_str == '':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)

        elif 'x' in term:
            # Term is like "3x" or "-3x" or "x" or "-x"
            if term == 'x':
                coeff = 1
                exp = 1
            elif term == '-x':
                coeff = -1
                exp = 1
            else:
                # Remove the 'x' to get coefficient
                coeff_str = term[:-1]
                if coeff_str == '+' or coeff_str == '':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str)
                exp = 1

        else:
            # Constant term
            coeff = int(term)
            exp = 0

        # Apply power rule: ax^n -> a*n*x^(n-1)
        if exp == 0:
            # Derivative of constant is 0
            derivative = 0
        else:
            derivative = coeff * exp * (x ** (exp - 1))

        result += derivative

    return result

