def is_balanced(s, pairs):
    # Create a mapping from opening to closing characters
    pair_map = {}
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        pair_map[opening] = closing

    # Stack to keep track of opening characters
    stack = []

    for char in s:
        # If character is an opening character
        if char in pair_map:
            stack.append(char)
        # If character is a closing character
        elif char in pair_map.values():
            # If stack is empty, we have a closing character without opening
            if not stack:
                return False

            # Pop the last opening character
            last_opening = stack.pop()

            # Check if the closing character matches the last opening character
            if pair_map[last_opening] != char:
                return False

    # String is balanced if stack is empty
    return len(stack) == 0

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    if n <= 1:
        return y
    if n == 2:
        return x
    if n % 2 == 0:
        return y

    limit = int(n**0.5) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return y

    return x

