def is_balanced(s, pairs):
    if not s:
        return True

    # Build mapping from opening to closing characters
    # Track identical pairs (where opening == closing character)
    opening_to_closing = {}
    closing_chars = set()
    identical_pairs = set()

    for i in range(0, len(pairs), 2):
        if i + 1 >= len(pairs):
            continue  # Skip incomplete pair
        open_char = pairs[i]
        close_char = pairs[i + 1]
        opening_to_closing[open_char] = close_char
        closing_chars.add(close_char)
        if open_char == close_char:
            identical_pairs.add(open_char)

    stack = []

    for char in s:
        if char in identical_pairs:
            # For identical pairs: if char is on stack top, it's a closer; otherwise it's an opener
            if stack and stack[-1] == char:
                stack.pop()
            else:
                stack.append(char)
        elif char in opening_to_closing:
            # Opening character
            stack.append(char)
        elif char in closing_chars:
            # Closing character - must match the most recent opening
            if not stack:
                return False
            if opening_to_closing[stack[-1]] == char:
                stack.pop()
            else:
                return False
        # Other characters are ignored

    return len(stack) == 0

def almost_everywhere_zero(n, k):
    s = str(n)
    length = len(s)

    memo = {}

    def dp(pos, count, tight, leading_zeros):
        if pos == length:
            # Valid only if we have exactly k non-zero digits
            # and we're not still in leading zeros state (which would mean number 0)
            return 1 if count == k and not leading_zeros else 0

        state = (pos, count, tight, leading_zeros)
        if state in memo:
            return memo[state]

        result = 0
        limit = int(s[pos]) if tight else 9

        for digit in range(limit + 1):
            new_tight = tight and (digit == limit)

            if leading_zeros and digit == 0:
                # Still placing leading zeros, don't count this digit
                new_leading_zeros = True
                new_count = count
            else:
                # Either transitioning out of leading zeros or placing actual digit
                new_leading_zeros = False
                new_count = count + (1 if digit != 0 else 0)

            # Prune if we already exceeded k non-zero digits
            if new_count <= k:
                result += dp(pos + 1, new_count, new_tight, new_leading_zeros)

        memo[state] = result
        return result

    return dp(0, 0, True, True)

def encrypt(s):
    result = []
    for char in s:
        if 'a' <= char <= 'z':
            # Lowercase letters: shift by 4 with wrap-around
            shifted = chr(ord('a') + (ord(char) - ord('a') + 4) % 26)
            result.append(shifted)
        elif 'A' <= char <= 'Z':
            # Uppercase letters: shift by 4 with wrap-around
            shifted = chr(ord('A') + (ord(char) - ord('A') + 4) % 26)
            result.append(shifted)
        else:
            # Non-alphabetic characters remain unchanged
            result.append(char)
    return ''.join(result)

