def getAllPrimeFactors(n):
    def validate(n):
        if not isinstance(n, (int, float)) or isinstance(n, bool):
            return False
        if not float(n).is_integer():
            return False
        n = int(n)
        if n < 1:
            return False
        return True

    if not validate(n):
        return []

    if n == 1:
        return [1]

    factors = []
    num = n
    d = 2
    while d * d <= num:
        while num % d == 0:
            factors.append(d)
            num //= d
        d += 1
    if num > 1:
        factors.append(num)
    return factors


def getUniquePrimeFactorsWithCount(n):
    def validate(n):
        if not isinstance(n, (int, float)) or isinstance(n, bool):
            return False
        if not float(n).is_integer():
            return False
        n = int(n)
        if n < 1:
            return False
        return True

    if not validate(n):
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)
    primes = []
    counts = []

    if not factors:
        return [[], []]

    current_prime = factors[0]
    count = 0

    for f in factors:
        if f == current_prime:
            count += 1
        else:
            primes.append(current_prime)
            counts.append(count)
            current_prime = f
            count = 1

    primes.append(current_prime)
    counts.append(count)

    return [primes, counts]


def getUniquePrimeFactorsWithProducts(n):
    def validate(n):
        if not isinstance(n, (int, float)) or isinstance(n, bool):
            return False
        if not float(n).is_integer():
            return False
        n = int(n)
        if n < 1:
            return False
        return True

    if not validate(n):
        return []

    if n == 1:
        return [1]

    primes_and_counts = getUniquePrimeFactorsWithCount(n)
    primes = primes_and_counts[0]
    counts = primes_and_counts[1]

    products = [p ** c for p, c in zip(primes, counts)]
    return products

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    if integer_part == 0:
        integer_result = ''
    else:
        digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
        integer_result = ''
        while integer_part > 0:
            remainder = integer_part % base
            if remainder >= base:
                remainder = int(remainder)
            integer_result = digits[int(remainder)] + integer_result
            integer_part = int(integer_part / base)

    # Convert fractional part
    fractional_part = number - int(number)
    fractional_result = ''

    if decimals > 0:
        fractional_result = '.'
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
            fractional_result += digits[digit]
            fractional_part -= digit

    # Combine results
    if integer_result == '':
        result = '0' + fractional_result
    else:
        result = integer_result + fractional_result

    # Handle negative sign
    if negative:
        result = '-' + result

    return result

