def encrypt(s):
    result = ""
    for char in s:
        if char.isalpha():
            if char.islower():
                # For lowercase letters, shift by 4 positions with wraparound
                shifted = (ord(char) - ord('a') + 4) % 26
                result += chr(shifted + ord('a'))
            else:
                # For uppercase letters, shift by 4 positions with wraparound
                shifted = (ord(char) - ord('A') + 4) % 26
                result += chr(shifted + ord('A'))
        else:
            # Non-alphabetic characters remain unchanged
            result += char
    return result

