            copy = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copy
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                code_pointer = loop_map[code_pointer]
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                code_pointer = loop_map[code_pointer]
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
