            memory[pointer] = memory[pointer] % 256
        elif char == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            memory[pointer] = memory[pointer] % 256
        elif char == 'V':
            memory[pointer] = memory.get(pointer, 0) // 2
            memory[pointer] = memory[pointer] % 256
        elif char == 'A':
            memory[pointer] = memory.get(pointer, 0) + copy
            memory[pointer] = memory[pointer] % 256
        elif char == 'B':
            memory[pointer] = memory.get(pointer, 0) - copy
            memory[pointer] = memory[pointer] % 256
        elif char == 'Y':
