def is_balanced(s, pairs):
    # Create a mapping of opening to closing characters
    pair_map = {}
    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        pair_map[open_char] = close_char

    # Stack to keep track of opening characters
    stack = []

    for char in s:
        # If character is an opening character
        if char in pair_map:
            # Check if it's also a closing character (self-matching case)
            if char in pair_map and pair_map[char] == char:
                # For self-matching, we can either push or pop depending on context
                # But since we're looking for matching pairs, we'll treat it as opening first
                stack.append(char)
            else:
                # Regular opening character
                stack.append(char)
        # If character is a closing character
        elif char in pair_map.values():
            # Check if stack is empty or if the closing character doesn't match the last opening character
            if not stack:
                return False

            last_opening = stack.pop()

            # Check if the closing character matches the last opening character
            if pair_map.get(last_opening) != char:
                return False

    # If stack is empty, all characters were properly matched
    return len(stack) == 0

def exchange_sort(sequence):
    if len(sequence) <= 1:
        return 0

    # Create target sorted sequence
    target = []
    count = [0, 0, 0]  # count[0] for 7s, count[1] for 8s, count[2] for 9s

    for num in sequence:
        if num == 7:
            count[0] += 1
        elif num == 8:
            count[1] += 1
        else:  # num == 9
            count[2] += 1

    # Build target sequence
    target = [7] * count[0] + [8] * count[1] + [9] * count[2]

    # Create position mapping for target
    pos_map = {}
    for i, num in enumerate(target):
        if num not in pos_map:
            pos_map[num] = []
        pos_map[num].append(i)

    # Create permutation array - where each element should go
    perm = [0] * len(sequence)
    for i, num in enumerate(sequence):
        # Get the next available position for this number in target
        pos = pos_map[num].pop(0)
        perm[i] = pos

    # Count cycles in permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i]:
            # Start a new cycle
            cycles += 1
            current = i

            while not visited[current]:
                visited[current] = True
                current = perm[current]

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

