def amazon_check_mate(board, current_turn):
    """
    Determine if the current position is checkmate.

    Args:
        board: 8x8 2D list representing the chess board
        current_turn: 'white' or 'black' - whose turn it is

    Returns:
        bool: True if checkmate, False otherwise
    """

    def find_king(board, player):
        """Find the king's position for the given player."""
        king_char = 'K' if player == 'white' else 'k'
        for row in range(8):
            for col in range(8):
                if board[row][col] == king_char:
                    return (row, col)
        return None

    def get_attacker_colors(board, player):
        """Return the color of opponent pieces."""
        if player == 'white':
            return ['p', 'n', 'b', 'r', 'q', 'k']
        return ['P', 'N', 'B', 'R', 'Q', 'K']

    def is_square_attacked(board, square, player):
        """Check if a square is attacked by opponent."""
        if square is None:
            return False
        row, col = square
        opponent_colors = get_attacker_colors(board, player)

        for piece in opponent_colors:
            for r in range(8):
                for c in range(8):
                    if board[r][c] == piece:
                        if is_attacking(board, (r, c), square, piece, player):
                            return True
        return False

    def is_attacking(board, piece_pos, target, piece, player):
        """Check if a piece attacks a target square."""
        pr, pc = piece_pos
        tr, tc = target
        dr = tr - pr
        dc = tc - pc

        # Pawn attacks
        if piece in ['p', 'P']:
            direction = -1 if piece == 'p' else 1
            return dr == direction and abs(dc) == 1

        # King attacks
        if piece in ['k', 'K']:
            return abs(dr) <= 1 and abs(dc) <= 1

        # Knight attacks
        if piece in ['n', 'N']:
            return (abs(dr) == 2 and abs(dc) == 1) or (abs(dr) == 1 and abs(dc) == 2)

        # Bishop attacks
        if piece in ['b', 'B']:
            if abs(dr) != abs(dc) or dr == 0 or dc == 0:
                return False
            return is_path_clear(board, piece_pos, target)

        # Rook attacks
        if piece in ['r', 'R']:
            if dr != 0 and dc != 0:
                return False
            return is_path_clear(board, piece_pos, target)

        # Queen attacks
        if piece in ['q', 'Q']:
            if (dr == 0 or dc == 0 or abs(dr) == abs(dc)):
                return is_path_clear(board, piece_pos, target)
            return False

        return False

    def is_path_clear(board, start, end):
        """Check if path between two squares is clear."""
        sr, sc = start
        er, ec = end
        dr = 0 if er == sr else (1 if er > sr else -1)
        dc = 0 if ec == sc else (1 if ec > sc else -1)

        r, c = sr + dr, sc + dc
        while (r, c) != (er, ec):
            if board[r][c] != '.':
                return False
            r += dr
            c += dc
        return True

    def simulate_move(board, piece, target, captured):
        """Simulate a move on a copy of the board."""
        new_board = [row[:] for row in board]
        new_board[target[0]][target[1]] = piece
        new_board[0][1] = captured
        return new_board

    def get_possible_moves(board, player):
        """Get all possible moves for the player."""
        moves = []
        king_char = 'K' if player == 'white' else 'k'
        pieces = ['P', 'N', 'B', 'R', 'Q', 'K'] if player == 'white' else ['p', 'n', 'b', 'r', 'q', 'k']

        for row in range(8):
            for col in range(8):
                if board[row][col] in pieces:
                    piece = board[row][col]
                    moves.append(((row, col), piece))

        return moves

    def has_legal_move(board, player):
        """Check if player has any legal move."""
        king_pos = find_king(board, player)
        possible_moves = get_possible_moves(board, player)

        for move in possible_moves:
            piece_pos, piece = move
            if piece_pos == king_pos:
                continue

            # Simulate move
            new_board = simulate_move(board, piece, (0, 1), board[0][1])

            # Check if move results in own king being in check
            if not is_square_attacked(new_board, find_king(new_board, player), player):
                return True

        return False

    # Check if current player's king is in check
    if not is_square_attacked(board, find_king(board, current_turn), current_turn):
        return False

    # Check if current player has any legal moves
    return not has_legal_move(board, current_turn)

