import math

def converter(n, decimals=0, base=math.pi):
    if n == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Handle sign
    negative = n < 0
    n = abs(n)

    # Convert integer part
    integer_part = int(n)
    result = []

    if integer_part > 0:
        while integer_part > 0:
            digit = integer_part % int(base)
            result.append(str(digit))
            integer_part //= int(base)
        result.reverse()
    else:
        result = ['0']

    # Handle fractional part
    fractional_part = n - int(n)
    if decimals > 0 and fractional_part > 0:
        result.append('.')
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            result.append(str(digit))
            fractional_part -= digit
    elif decimals > 0:
        result.append('.')
        for _ in range(decimals):
            result.append('0')

    # Join result
    final_result = ''.join(result)

    # Handle negative sign
    if negative:
        final_result = '-' + final_result

    # Special case for values < 1 that should start with 0.
    if final_result.startswith('.'):
        final_result = '0' + final_result

    return final_result

def converter(number, decimals, base):
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36")

    if decimals < 0:
        raise ValueError("Decimals must be non-negative")

    if number == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Handle negative numbers
    is_negative = number < 0
    number = abs(number)

    # Separate integer and fractional parts
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_result = ""
    else:
        digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        integer_result = ""
        while integer_part > 0:
            remainder = integer_part % base
            integer_result = digits[remainder] + integer_result
            integer_part //= base

    # Convert fractional part
    fractional_result = ""
    if decimals > 0:
        fractional_result = "."
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
            fractional_result += digits[digit]
            fractional_part -= digit

    # Combine results
    if integer_result == "":
        result = "0" + fractional_result
    else:
        result = integer_result + fractional_result

    # Handle negative sign
    if is_negative:
        result = "-" + result

    return result

