    for char in identifier[1:]:
        if not (char.isalnum() or char == '_' or char == '$'):
            return False

    return True

def amazon_check_mate(king, amazon):
    # Convert chess notation to 0-indexed coordinates
    def to_coords(pos):
        file = ord(pos[0]) - ord('a')  # 0-7 for a-h
        rank = int(pos[1]) - 1          # 0-7 for 1-8
        return (rank, file)  # (row, col) where row 0 = rank 1

    king_pos = to_coords(king)
    amazon_pos = to_coords(amazon)

    # Compute all squares attacked by the amazon
    def get_amazon_attacks(pos):
        r, c = pos
        attacks = set()

        # Queen moves: entire row, column, and diagonals
        for i in range(8):
            attacks.add((r, i))
            attacks.add((i, c))

        for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
            for step in range(1, 8):
                nr, nc = r + dr * step, c + dc * step
                if 0 <= nr < 8 and 0 <= nc < 8:
                    attacks.add((nr, nc))
                else:
                    break

        # Knight moves: 8 possible L-shaped jumps
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
                       (1, -2), (1, 2), (2, -1), (2, 1)]
        for dr, dc in knight_moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 8 and 0 <= nc < 8:
                attacks.add((nr, nc))

        # Remove the amazon's own square
        attacks.discard((r, c))

        return attacks

    attacked_squares = get_amazon_attacks(amazon_pos)

    # Check if a square is adjacent to the white king (invalid for black king)
    def is_adjacent_to_white_king(pos):
        kr, kc = king_pos
        pr, pc = pos
        return abs(pr - kr) <= 1 and abs(pc - kc) <= 1

    # Check if black king has valid moves from position
    def has_valid_moves(pos):
        r, c = pos
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < 8 and 0 <= nc < 8:
                    # Valid move: not attacked, not on white king, not adjacent to white king
                    if (nr, nc) != king_pos and \
                       (nr, nc) not in attacked_squares and \
                       not is_adjacent_to_white_king((nr, nc)):
                        return True
        return False

    checkmate, check, stalemate, safe = 0, 0, 0, 0

    # Iterate through all possible black king positions
    for r in range(8):
        for c in range(8):
            pos = (r, c)

            # Skip invalid positions (on or adjacent to white king)
            if pos == king_pos or is_adjacent_to_white_king(pos):
                continue

            under_attack = pos in attacked_squares
            valid_moves = has_valid_moves(pos)

            if under_attack:
                if not valid_moves:
                    checkmate += 1
                else:
                    check += 1
            else:
                if not valid_moves:
                    stalemate += 1
                else:
                    safe += 1

    return [checkmate, check, stalemate, safe]

def solution(input_string, comment_markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the earliest comment marker position
        min_pos = len(line)
        for marker in comment_markers:
            pos = line.find(marker)
            if pos != -1 and pos < min_pos:
                min_pos = pos

        # If we found a comment marker, truncate the line
        if min_pos < len(line):
            line = line[:min_pos]

        # Strip trailing whitespace
        line = line.rstrip()
        result_lines.append(line)

    return '\n'.join(result_lines)

def fib4(n):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize the first four values
    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute fib4(n)
    for i in range(4, n + 1):
        next_val = a + b + c + d
        a, b, c, d = b, c, d, next_val

    return d

