def is_valid(s):
    # Check if string is empty
    if not s:
        return False

    # Define alpha characters (a-z, A-Z)
    def is_alpha(c):
        return 'a' <= c <= 'z' or 'A' <= c <= 'Z'

    # Define digit characters (0-9)
    def is_digit(c):
        return '0' <= c <= '9'

    # Define valid identifier characters
    def is_valid_char(c):
        return is_alpha(c) or is_digit(c) or c == '_' or c == '$'

    # First character must be alpha, underscore, or dollar sign (not digit)
    first_char = s[0]
    if not (is_alpha(first_char) or first_char == '_' or first_char == '$'):
        return False

    # Rest of the characters can be alpha, digit, underscore, or dollar sign
    for i in range(1, len(s)):
        if not is_valid_char(s[i]):
            return False

    return True

def median(l: list):
    """Return median of elements in the list l."""
    sorted_l = sorted(l)
    n = len(sorted_l)

    if n == 0:
        raise ValueError("Cannot compute median of empty list")

    mid = n // 2

    if n % 2 == 1:
        return sorted_l[mid]
    else:
        return (sorted_l[mid - 1] + sorted_l[mid]) / 2

def sum_of_squares(n):
    # Step 1: Check if n is a perfect square (answer = 1)
    root = int(n**0.5)
    if root * root == n:
        return 1

    # Step 2: Check if n can be written as sum of two squares (answer = 2)
    for i in range(1, root + 1):
        remainder = n - i * i
        r = int(remainder**0.5)
        if r * r == remainder:
            return 2

    # Step 3: Check Legendre's three-square theorem condition
    # A number needs 4 squares iff it's of form 4^a(8b + 7)
    temp = n
    while temp % 4 == 0:
        temp //= 4

    if temp % 8 == 7:
        return 4

    # Otherwise, by Lagrange's four-square theorem, answer is 3
    return 3

import math

def converter(number, decimals=0, base=math.pi):
    if base == int(base):
        base = int(base)
        return _convert_integer_base(number, decimals, base)
    else:
        return _convert_non_integer_base(number, decimals, base)

def _convert_integer_base(number, decimals, base):
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    sign = '-' if number < 0 else ''
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    if integer_part == 0:
        integer_result = '0'
    else:
        integer_result = ''
        while integer_part > 0:
            integer_result = digits[integer_part % base] + integer_result
            integer_part //= base

    # Convert fractional part
    fractional_part = number - int(number)
    if decimals == 0:
        fractional_result = ''
    else:
        fractional_result = '.'
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            fractional_result += digits[digit]
            fractional_part -= digit

    result = integer_result + fractional_result

    # Handle case where result is less than 1
    if result.startswith('.'):
        result = '0' + result

    return sign + result

def _convert_non_integer_base(number, decimals, base):
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    sign = '-' if number < 0 else ''
    number = abs(number)

    # Handle integer part using greedy algorithm
    if number == 0:
        integer_result = '0'
    else:
        # Find the highest power
        if number >= 1:
            power = int(math.log(number) / math.log(base))
        else:
            power = 0

        integer_result = ''
        remaining = number

        # Process from highest power down to 0
        for p in range(power, -1, -1):
            power_value = base ** p
            if power_value <= remaining:
                digit = int(remaining / power_value)
                integer_result += digits[digit]
                remaining -= digit * power_value
            else:
                integer_result += '0'

        # Handle case where we might have leading zeros
        integer_result = integer_result.lstrip('0') or '0'

    # Handle fractional part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        remaining = number - int(number)
        for _ in range(decimals):
            remaining *= base
            digit = int(remaining)
            fractional_result += digits[digit]
            remaining -= digit

    result = integer_result + fractional_result

    # Handle case where result is less than 1
    if result.startswith('.'):
        result = '0' + result

    return sign + result

def even_odd_palindrome(n):
    def is_palindrome(num):
        s = str(num)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    colors = list(map(int, lines[1].split()))

    # Precompute palindromes
    is_palindrome = [[False] * n for _ in range(n)]

    # Every single character is a palindrome
    for i in range(n):
        is_palindrome[i][i] = True

    # Check for palindromes of length 2
    for i in range(n - 1):
        if colors[i] == colors[i + 1]:
            is_palindrome[i][i + 1] = True

    # Check for palindromes of length 3 and more
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if colors[i] == colors[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP table: dp[i][j] represents minimum seconds to eliminate substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Fill DP table
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if i == j:
                # Single element is palindrome, takes 1 second
                dp[i][j] = 1
            elif is_palindrome[i][j]:
                # If the substring is palindrome, takes 1 second
                dp[i][j] = 1
            else:
                # Need to split into two parts
                dp[i][j] = length  # Worst case: remove each element separately
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

