def almost_everywhere_zero(n, k):
    s = str(n)
    length = len(s)

    # Memoization table
    memo = {}

    def dp(pos, count, tight, started):
        # Base case: we've processed all digits
        if pos == length:
            return 1 if count == k else 0

        # Check memo
        if (pos, count, tight, started) in memo:
            return memo[(pos, count, tight, started)]

        # Determine the upper limit for current digit
        limit = int(s[pos]) if tight else 9
        result = 0

        # Try placing each possible digit at current position
        for digit in range(0, limit + 1):
            # If we're placing a non-zero digit
            if digit > 0:
                # Only increment count if we've started placing digits
                if started:
                    new_count = count + 1
                else:
                    new_count = 1
                new_started = True
            else:
                # If we're placing 0
                if started:
                    new_count = count
                else:
                    new_count = count  # Still 0, we haven't started
                new_started = started

            # If we've exceeded k non-zero digits, no point continuing
            if new_count > k:
                continue

            # Recurse to next position
            result += dp(pos + 1, new_count, tight and (digit == limit), new_started)

        memo[(pos, count, tight, started)] = result
        return result

    # Start the DP
    return dp(0, 0, True, False)

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    if n <= 2:
        return []

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    primes = []
    for i in range(2, n):
        if is_prime(i):
            primes.append(i)

    return primes

def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2

    while p * p <= d:
        if d % p == 0:
            while d % p == 0:
                d //= p
            result -= result // p
        p += 1

    if d > 1:
        result -= result // d

    return result

def simplify(expression):
    from collections import defaultdict

    # Dictionary to store monomials: normalized_var_string -> coefficient
    monomials = defaultdict(int)

    # Parse the expression
    i = 0
    n = len(expression)

    # Handle the first sign (if present)
    if expression[0] == '-':
        sign = -1
        i = 1
    elif expression[0] == '+':
        sign = 1
        i = 1
    else:
        sign = 1

    # Parse first term
    coeff_str = ""
    while i < n and expression[i].isdigit():
        coeff_str += expression[i]
        i += 1

    if coeff_str == "":
        coeff = sign
    else:
        coeff = sign * int(coeff_str)

    vars_str = ""
    while i < n and expression[i].isalpha():
        vars_str += expression[i]
        i += 1

    if vars_str:
        vars_str = ''.join(sorted(vars_str))
        monomials[vars_str] += coeff

    # Parse remaining terms
    while i < n:
        if expression[i] == '+':
            sign = 1
            i += 1
        elif expression[i] == '-':
            sign = -1
            i += 1
        else:
            break

        coeff_str = ""
        while i < n and expression[i].isdigit():
            coeff_str += expression[i]
            i += 1

        if coeff_str == "":
            coeff = sign
        else:
            coeff = sign * int(coeff_str)

        vars_str = ""
        while i < n and expression[i].isalpha():
            vars_str += expression[i]
            i += 1

        if vars_str:
            vars_str = ''.join(sorted(vars_str))
            monomials[vars_str] += coeff

    # Remove zero coefficient terms
    monomials = {k: v for k, v in monomials.items() if v != 0}

    if not monomials:
        return ""

    # Sort by degree (number of variables), then lexicographically
    sorted_items = sorted(monomials.items(), key=lambda x: (len(x[0]), x[0]))

    # Build result string
    result = []
    for idx, (vars_str, coeff) in enumerate(sorted_items):
        if idx == 0:
            if coeff == 1:
                term = vars_str
            elif coeff == -1:
                term = "-" + vars_str
            else:
                term = f"{coeff}{vars_str}"
            result.append(term)
        else:
            if coeff == 1:
                result.append("+" + vars_str)
            elif coeff == -1:
                result.append("-" + vars_str)
            elif coeff > 0:
                result.append("+" + f"{coeff}{vars_str}")
            else:
                result.append(f"{coeff}{vars_str}")

    return "".join(result)

