        return sum(int(digit) for digit in str(abs(n)))

    # Create list of (digit_sum, original_value, original_index) tuples
    indexed_nums = [(digit_sum(num), num, i) for i, num in enumerate(nums)]

    # Sort by digit sum, then by original value, then by original index
    indexed_nums.sort(key=lambda x: (x[0], x[1], x[2]))

    # Extract the sorted numbers
    return [num for digit_sum_val, num, index in indexed_nums]

def parse_nested_parens(s):
    if not s:
        return []

    groups = s.split()
    result = []

    for group in groups:
        current_depth = 0
        max_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

