import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part to given base
    if integer_part == 0:
        integer_result = '0'
    else:
        digits = []
        n = integer_part
        while n > 0:
            remainder = n % base
            # Handle negative remainders
            if remainder < 0:
                remainder += base
                n -= base
            digits.append(remainder)
            n = (n - remainder) // base

        # Convert remainders to digits
        integer_result = ''
        for i in range(len(digits) - 1, -1, -1):
            digit_value = int(digits[i])
            if digit_value < 10:
                integer_result += str(digit_value)
            else:
                integer_result += chr(ord('A') + digit_value - 10)

    # Convert fractional part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            if digit < 10:
                fractional_result += str(digit)
            else:
                fractional_result += chr(ord('A') + digit - 10)
            fractional_part -= digit

    # Combine results
    result = integer_result + fractional_result

    # Handle negative sign
    if negative:
        result = '-' + result

    # Ensure leading zero for fractional numbers less than 1
    if result.startswith('.'):
        result = '0' + result

    return result

def simplify(expression):
    if not expression:
        return ""

    # Parse terms
    terms = []
    i = 0
    while i < len(expression):
        # Skip spaces
        if expression[i] == ' ':
            i += 1
            continue

        # Determine sign
        sign = 1
        if expression[i] == '+':
            i += 1
        elif expression[i] == '-':
            sign = -1
            i += 1

        # Parse coefficient
        coeff = 0
        while i < len(expression) and expression[i].isdigit():
            coeff = coeff * 10 + int(expression[i])
            i += 1

        # If no digits were found, coefficient is 1 or -1
        if coeff == 0:
            coeff = 1

        # Apply sign to coefficient
        coeff *= sign

        # Parse variables
        variables = []
        while i < len(expression) and expression[i].islower():
            variables.append(expression[i])
            i += 1

        # Sort variables to normalize
        variables.sort()
        var_str = ''.join(variables)

        # Add to terms
        if var_str:  # Only add if there are variables
            terms.append((coeff, var_str))
        else:  # Handle constant terms (no variables)
            terms.append((coeff, ""))

    # Combine like terms
    monomial_dict = {}
    for coeff, var_str in terms:
        if var_str in monomial_dict:
            monomial_dict[var_str] += coeff
        else:
            monomial_dict[var_str] = coeff

    # Remove terms with zero coefficient
    monomial_dict = {var_str: coeff for var_str, coeff in monomial_dict.items() if coeff != 0}

    # Sort terms
    sorted_terms = sorted(monomial_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Format result
    result = []
    for i, (var_str, coeff) in enumerate(sorted_terms):
        if coeff == 1 and var_str:  # Coefficient is 1 and there are variables
            term = var_str
        elif coeff == -1 and var_str:  # Coefficient is -1 and there are variables
            term = '-' + var_str
        else:  # Other coefficients
            term = str(coeff) + var_str if var_str else str(coeff)

        if i == 0:
            result.append(term)
        else:
            if term.startswith('-'):
                result.append('-' + term[1:])
            else:
                result.append('+' + term)

    # Handle empty result
    if not result:
        return ""

    # Join the terms
    final_result = result[0]
    for term in result[1:]:
        if term.startswith('-'):
            final_result += term
        else:
            final_result += '+' + term

    return final_result

def is_balanced(text, pairs):
    # Create mapping from opening to closing characters
    open_to_close = {}
    close_to_open = {}

    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        open_to_close[open_char] = close_char
        close_to_open[close_char] = open_char

    # Stack to track opening characters
    stack = []

    for char in text:
        if char in open_to_close:
            # It's an opening character
            stack.append(char)
        elif char in close_to_open:
            # It's a closing character
            if not stack:
                return False
            last_open = stack.pop()
            if close_to_open[char] != last_open:
                return False
        # Ignore any other characters

    # Stack should be empty for balanced string
    return len(stack) == 0

