def encrypt(s):
    result = ""
    for char in s:
        if char.isalpha():
            # Determine if uppercase or lowercase
            if char.isupper():
                # For uppercase letters (A-Z)
                shifted = (ord(char) - ord('A') + 4) % 26
                result += chr(shifted + ord('A'))
            else:
                # For lowercase letters (a-z)
                shifted = (ord(char) - ord('a') + 4) % 26
                result += chr(shifted + ord('a'))
        else:
            # Non-alphabetic characters remain unchanged
            result += char
    return result

def choose(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry property to minimize computation
    k = min(k, n - k)

    # Calculate using iterative approach to avoid large factorials
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

def converter(number, decimals=0, base=3.141592653589793):
