def exchange_sort(sequence):
    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for num in sequence:
        count[num] += 1

    # Create target sorted sequence
    target = []
    target.extend([7] * count[7])
    target.extend([8] * count[8])
    target.extend([9] * count[9])

    # Create mapping from value to its correct positions
    correct_positions = {7: [], 8: [], 9: []}
    for i, val in enumerate(target):
        correct_positions[val].append(i)

    # Create a mapping from current positions to target positions
    pos_map = {}
    for i, val in enumerate(sequence):
        if correct_positions[val]:
            pos_map[i] = correct_positions[val].pop(0)

    # Find cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i] and i in pos_map:
            # Start a new cycle
            cycle_length = 0
            current = i

            while not visited[current]:
                visited[current] = True
                if current in pos_map:
                    current = pos_map[current]
                else:
                    break
                cycle_length += 1

            if cycle_length > 0:
                cycles += 1

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

