def parse_int(s):
    ones = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9,
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17,
        'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    multipliers = {
        'hundred': 100, 'thousand': 1000, 'million': 1000000
    }

    # Replace hyphens with spaces and convert to lowercase
    s = s.replace('-', ' ').lower()
    words = s.split()

    total = 0
    current = 0

    for word in words:
        if word == 'and':
            continue

        if word in ones:
            current += ones[word]
        elif word in tens:
            current += tens[word]
        elif word in multipliers:
            if word == 'hundred':
                current *= 100
            else:
                current *= multipliers[word]
                total += current
                current = 0

    total += current
    return total

def choose(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1

    # Use the smaller of k and n-k to minimize calculations
    k = min(k, n - k)

    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

def x_or_y(n, x, y):
