    if not s or not pairs:
        return True

    # Parse pairs into openers and closers
    openers = pairs[::2]
    closers = pairs[1::2]

    # Create mapping for distinct pairs
    pair_map = {}
    # Set for characters that are both openers and closers
    self_balancing = set()

    for i, (opener, closer) in enumerate(zip(openers, closers)):
        if opener == closer:
            self_balancing.add(opener)
        else:
            pair_map[opener] = closer

    # Initialize tracking structures
    stack = []
    counters = {char: 0 for char in self_balancing}

    for char in s:
        if char in pair_map:
            # Distinct pair: opener
            if char in pair_map:
                stack.append(char)
        elif char in self_balancing:
            # Self-balancing pair
            counters[char] += 1
        elif char in closers:
            # Closing character
            if char in pair_map.values():
                # It's a closer from distinct pair
                if not stack:
                    return False
                opener = stack.pop()
                if pair_map[opener] != char:
                    return False
            elif char in self_balancing:
                # It's a closer from self-balancing pair
                counters[char] -= 1
                if counters[char] < 0:
                    return False

    # Check if all counters are zero for self-balancing pairs
    for count in counters.values():
        if count != 0:
            return False

    # Check if stack is empty for distinct pairs
    return len(stack) == 0

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False

        # Check odd divisors up to sqrt(num)
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    if is_prime(n):
        return x
    else:
        return y

def largest_divisor(n: int) -> int:
    if n == 1:
        return 0

    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i

    return 1

def amazon_check_mate(board):
    """
    Determines if the black king is in checkmate on an 8x8 chess board.

    Args:
        board (list of list of str): 8x8 list representing the chess board.
            Pieces are represented by uppercase letters for white and 
            lowercase for black:
            R/r (Rook), N/n (Knight), B/b (Bishop), Q/q (Queen), K/k (King), P/p (Pawn).
