        # but for capture, it's an enemy.
        is_white = piece.isupper()
        if is_white and my_color == 'white':
            return True
        if not is_white and my_color == 'black':
            return True
        return False

    def is_enemy(b, r, c, my_color):
        if not is_valid(r, c):
            return False
        piece = b[r][c]
        if piece == '.':
            return False
        is_white = piece.isupper()
        if my_color == 'white' and not is_white:
            return True
        if my_color == 'black' and is_white:
            return True
        return False

    def get_attacked_squares(b, color):
