                        if is_valid(attack_r, c-1) and is_enemy(b, attack_r, c-1, 'white'):
                            attacked.add((attack_r, c-1))
                        if is_valid(attack_r, c+1) and is_enemy(b, attack_r, c+1, 'white'):
                            attacked.add((attack_r, c+1))
                    else: # black
