                    return False # Valid move found
                else:
                    # Occupied by black piece, invalid
                    continue
            else:
                # Empty square
                # Simulate move
                temp_board = [row[:] for row in board]
                temp_board[nr][nc] = 'k'
                temp_board[kr][kc] = '.'
                if not is_safe_for_black_king(nr, nc, temp_board):
                    continue
                return False # Valid move found

    # 2. Check capturing the attacker
    # Find the piece giving check.
    # If multiple pieces are checking (double check), only king move can help.
    # But we already checked king moves. So if double check, we just need to ensure no capture/block works (which is impossible for block in double check anyway).
    # However, we must verify if capturing the attacker is valid.

    # Let's find all white pieces that attack the black king.
    attackers = []
    for r in range(8):
