                continue
            # Check if this piece attacks the king
            # We can reuse logic but simpler: simulate moving this piece to see if it hits king? No.
            # Better: check if the king is in the attack set of this specific piece.
            # Re-implementing attack logic for single piece is messy.
            # Alternative: iterate all white pieces, simulate their capture by black.
            pass

    # Instead of finding attackers explicitly, iterate all black pieces and see if they can capture a white piece that is attacking the king.
    # Wait, capturing any white piece that is attacking the king removes the check.
    # Also blocking works.

    # Let's iterate all black pieces and generate their potential moves.
    # If any move results in the king not being in check, return False.

    black_pieces = []
    for r in range(8):
        for c in range(8):
            if board[r][c].islower() and board[r][c] != 'k': # Exclude king, handled separately
                black_pieces.append((r, c, board[r][c]))

    for pr, pc, piece in black_pieces:
        p_type = piece
        moves = []

        if p_type == 'p':
            # Pawn capture moves
            # Direction for black: down (+1)
            # Capture diagonals
            for dc in [-1, 1]:
                nr, nc = pr + 1, pc + dc
                if is_valid(nr, nc):
                    if is_enemy(board, nr, nc, 'black'): # Capturing white piece
                        moves.append((nr, nc))

        elif p_type == 'n':
            moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]

        elif p_type in ['r', 'b', 'q']:
            directions = []
            if p_type in ['r', 'q']:
                directions += [(0, 1), (0, -1), (1, 0), (-1, 0)]
            if p_type in ['b', 'q']:
                directions += [(1, 1), (1, -1), (-1, 1), (-1, -1)]

            for dr, dc in directions:
                nr, nc = pr + dr, pc + dc
                while is_valid(nr, nc):
                    moves.append((nr, nc)) # We will handle blocking/capture logic in simulation
                    if board[nr][nc] != '.':
                        break
                    nr += dr
                    nc += dc

        elif p_type == 'k':
            # Already handled king moves above. Skip.
            continue

        if not moves:
            continue

        # Now check each move
        for mr, mc in moves:
            # Simulate move
            temp_board = [row[:] for row in board]
            temp_board[mr][mc] = p_type # Move piece to square
            temp_board[pr][pc] = '.' # Remove from original

            # If the move was a capture, the piece at (mr, mc) is removed (replaced by our piece)
            # If the move was a move to empty, it's fine.

            # Check if king is safe
            if not is_safe_for_black_king(kr, kc, temp_board):
