def cycpattern_check(a, b):
    if not b:
        return True

    if len(b) > len(a):
        return False

    # Create a string that contains all rotations of b
    # by concatenating b with itself
    double_b = b + b

    # Check if a is a substring of double_b
    # and if b is a substring of a
    return b in a or any(double_b[i:i+len(b)] in a for i in range(len(b)))

