    def is_alpha(c):
        return 'a' <= c <= 'z' or 'A' <= c <= 'Z'

    # Define digit characters (0-9)
    def is_digit(c):
        return '0' <= c <= '9'

    # Define valid identifier characters
    def is_valid_char(c):
        return is_alpha(c) or is_digit(c) or c == '_' or c == '$'

    # First character must be alpha, underscore, or dollar sign (not digit)
    first_char = s[0]
    if not (is_alpha(first_char) or first_char == '_' or first_char == '$'):
