    return max(l)

def almost_everywhere_zero(n, k):
    s = str(n)
    length = len(s)

    # Memoization cache
    memo = {}

    def dp(pos, non_zero_count, is_limit, is_started):
        # Base case: if we've processed all digits
        if pos == length:
            return 1 if non_zero_count == k else 0

        # Check if we've computed this state before
        if (pos, non_zero_count, is_limit, is_started) in memo:
            return memo[(pos, non_zero_count, is_limit, is_started)]

        # Determine the upper limit for current digit
        limit = int(s[pos]) if is_limit else 9
        result = 0

        # Try all possible digits for current position
        for digit in range(0, limit + 1):
            # If we're placing a zero
            if digit == 0:
                # If we haven't started placing non-zero digits yet, we can still place zeros
                # But we don't increment non_zero_count
                new_non_zero_count = non_zero_count
                new_is_started = is_started
                # If we haven't started yet and we're placing 0, we remain in "not started" state
                # If we have started, we can continue placing zeros
                if not is_started:
                    result += dp(pos + 1, new_non_zero_count, is_limit and (digit == limit), False)
                else:
                    result += dp(pos + 1, new_non_zero_count, is_limit and (digit == limit), True)
            else:
                # We're placing a non-zero digit
                new_non_zero_count = non_zero_count + 1
                new_is_started = True
                result += dp(pos + 1, new_non_zero_count, is_limit and (digit == limit), True)

        memo[(pos, non_zero_count, is_limit, is_started)] = result
        return result

    # We need to subtract the count of numbers with less than k non-zero digits
    # But actually, let's reconsider - we want exactly k non-zero digits
    # So we just compute dp(0, 0, True, False) where we start with no digits placed

    # Actually, let's restructure to be clearer:
    # We want numbers from 1 to n with exactly k non-zero digits
    # We can compute this as: (count of numbers <= n with exactly k non-zero digits) - (count of numbers <= 0 with exactly k non-zero digits)
    # But since we're counting from 1, we just compute the first part

    # Let's define a cleaner DP function
    def count_with_k_nonzero(limit_str, k):
        memo = {}

        def dp(pos, non_zero_count, is_limit, is_started):
            if pos == len(limit_str):
                return 1 if non_zero_count == k else 0

            if (pos, non_zero_count, is_limit, is_started) in memo:
                return memo[(pos, non_zero_count, is_limit, is_started)]

            limit = int(limit_str[pos]) if is_limit else 9
            result = 0

            for digit in range(0, limit + 1):
                if digit == 0:
                    # If we haven't started placing digits yet, we can place 0
                    # But if we have started, we can continue placing 0
                    if not is_started:
                        result += dp(pos + 1, non_zero_count, is_limit and (digit == limit), False)
                    else:
                        result += dp(pos + 1, non_zero_count, is_limit and (digit == limit), True)
                else:
                    # Placing a non-zero digit
                    result += dp(pos + 1, non_zero_count + 1, is_limit and (digit == limit), True)

            memo[(pos, non_zero_count, is_limit, is_started)] = result
            return result

        return dp(0, 0, True, False)

    return count_with_k_nonzero(s, k)

