    # Handle fractional part
    fractional_part = number - int(number)
    if decimals > 0 and fractional_part != 0:
        result.append('.')
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            if digit < 10:
                result.append(str(digit))
            else:
                result.append(chr(ord('A') + digit - 10))
            fractional_part -= digit
    elif decimals == 0 and fractional_part != 0:
        # If we have a fractional part but no decimals requested,
        # we still need to check if there's a fractional part to represent
        # But since we're not adding decimals, we don't add anything
        pass

    # Join result
    final_result = ''.join(result)

    # Add negative sign if needed
    if is_negative:
        final_result = '-' + final_result

    # Handle case where absolute value < 1
    if number < 1 and '.' in final_result:
        # Check if we need to add leading zero
        parts = final_result.split('.')
        if len(parts) > 1 and parts[0] == '0':
            # Already has leading zero
            pass
        elif len(parts) > 1 and parts[0] == '-0':
            # Already has leading zero for negative
            pass
        elif len(parts) > 1 and parts[0] == '':
            # This case shouldn't happen but just in case
            pass
        else:
            # Check if we need to add leading zero
            if not is_negative and parts[0] == '0':
                pass  # Already has leading zero
            elif is_negative and parts[0] == '-0':
                pass  # Already has leading zero
            elif not is_negative and parts[0] != '0':
                # Need to add leading zero for numbers less than 1
                pass  # Actually, we should not be adding leading zeros for numbers less than 1
                # Let's recheck the logic
                pass

    # Special case for numbers less than 1
    if number < 1 and '.' in final_result:
        # Check if we have a leading zero already
        if final_result.startswith('0.'):
            pass  # Already correct
        elif final_result.startswith('-0.'):
            pass  # Already correct
        elif final_result.startswith('.'):
            # Need to add leading zero
            if is_negative:
                final_result = '-0' + final_result[1:]
            else:
                final_result = '0' + final_result

    return final_result

def proper_fractions(d):
    if d == 1:
        return 0

    result = d

    # Check for factor 2
    if d % 2 == 0:
        result -= result // 2
        while d % 2 == 0:
            d //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= d:
        if d % i == 0:
            result -= result // i
            while d % i == 0:
                d //= i
        i += 2

    # If d is still greater than 1, then it's a prime factor
    if d > 1:
        result -= result // d

    return result

