            # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
            if exp == 0:
                continue  # Derivative of constant is 0
            else:
                new_coeff = coeff * exp
                new_exp = exp - 1
                if new_exp == 0:
                    derivative_terms.append(str(new_coeff))
                elif new_exp == 1:
                    derivative_terms.append(f"{new_coeff}x")
                else:
                    derivative_terms.append(f"{new_coeff}x^{new_exp}")

        elif 'x' in term:
            # Format: coefficient*x or x
            if term == 'x':
                coeff = 1 * sign
                exp = 1
            else:
                coeff_str = term.split('x')[0]
                if coeff_str == '+':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str) * sign
                exp = 1

            # Apply power rule
            if exp == 0:
                continue  # Derivative of constant is 0
            else:
                new_coeff = coeff * exp
                new_exp = exp - 1
                if new_exp == 0:
                    derivative_terms.append(str(new_coeff))
                elif new_exp == 1:
                    derivative_terms.append(f"{new_coeff}x")
                else:
                    derivative_terms.append(f"{new_coeff}x^{new_exp}")

        else:
            # Format: constant
            if term:
                coeff = int(term) * sign
                # Derivative of constant is 0, so we skip this term
                continue

    # Handle the case where all terms were constants
    if not derivative_terms:
        return 0

    # Build derivative expression string
    derivative_expr = derivative_terms[0]
    for i in range(1, len(derivative_terms)):
        if derivative_terms[i].startswith('-'):
            derivative_expr += f" - {derivative_terms[i][1:]}"
        else:
            derivative_expr += f" + {derivative_terms[i]}"

    # Evaluate the derivative at x
    # Replace x with the value and evaluate
    result = 0
    for term in derivative_terms:
        if 'x' in term:
            if term == 'x':
                result += x
            elif term == '-x':
                result -= x
            else:
                # Extract coefficient and power
                if term.startswith('-'):
                    coeff_str = term[1:].split('x')[0]
                    coeff = -int(coeff_str)
