def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    if n <= 1:
        return y
    if n == 2:
        return x
    if n % 2 == 0:
        return y

    i = 3
    while i * i <= n:
        if n % i == 0:
            return y
        i += 2

    return x

import sys
from math import comb

def solve():
    data = sys.stdin.read()
    lines = data.splitlines()

    k, q = map(int, lines[0].split())

    def probability_all_collected(n, k):
        # Using inclusion-exclusion principle
        # P(all k types collected in n days) = sum_{i=0}^{k} (-1)^i * C(k,i) * ((k-i)/k)^n
        if k == 0:
            return 1.0 if n >= 0 else 0.0
        if n < 0:
            return 0.0
        if n == 0:
            return 0.0 if k > 0 else 1.0

        prob = 0.0
        for i in range(k + 1):
            sign = (-1) ** i
            comb_k_i = comb(k, i)
            prob += sign * comb_k_i * ((k - i) / k) ** n

        return prob

    def find_min_days(k, target_prob):
        # Binary search for minimum n
        left, right = 1, k * 10000  # Upper bound estimation

        while left < right:
            mid = (left + right) // 2
            prob = probability_all_collected(mid, k)

            if prob >= target_prob:
                right = mid
            else:
                left = mid + 1

        return left

    results = []
    for i in range(1, q + 1):
        p = int(lines[i])
        # Calculate the required probability threshold
        threshold = (p - 1e-10) / 2000.0  # ε = 1e-10 is less than 1e-7

        if k == 1:
            # If there's only one type of orb, we need just 1 day
            results.append(1)
        else:
            min_days = find_min_days(k, threshold)
            results.append(min_days)

    for result in results:
        print(result)

