        (-1, -1), (-1, 1), (1, -1), (1, 1)   # diagonals
    ]

    # Add queen moves
    for dr, dc in directions:
        r, c = amazon_pos[0], amazon_pos[1]
        while True:
            r += dr
            c += dc
            if r < 0 or r >= 8 or c < 0 or c >= 8:
                break
            attacked[r][c] = True

    # Knight-like attacks
    knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), 
                    (1, -2), (1, 2), (2, -1), (2, 1)]
    for dr, dc in knight_moves:
        r, c = amazon_pos[0] + dr, amazon_pos[1] + dc
        if 0 <= r < 8 and 0 <= c < 8:
            attacked[r][c] = True

