def is_balanced(s, pairs):
    opening = set()
    closing = set()
    close_to_open = {}

    # Parse the pairs string to build character mappings
    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        opening.add(open_char)
        closing.add(close_char)
        close_to_open[close_char] = open_char

    stack = []

    for char in s:
        if char in opening:
            stack.append(char)
        elif char in closing:
            if not stack:
                return False
            if close_to_open[char] != stack.pop():
                return False

    return len(stack) == 0

def get_closest_vowel(word):
    if len(word) < 3:
        return ""

    vowels = set('aeiouAEIOU')

    # Iterate from right to left, starting from second-to-last character
    # and ending at index 1 (since we need at least one character before and after)
    for i in range(len(word) - 2, 0, -1):
        # Check if current character is a vowel
        if word[i] in vowels:
            # Check if both neighbors are consonants
            if word[i-1] not in vowels and word[i+1] not in vowels:
                return word[i]

    return ""

def solution(input, markers):
    lines = input.split('\n')
    result_lines = []

    for line in lines:
        # Find the first occurrence of any marker
        first_marker_pos = len(line)  # Initialize to end of line
        marker_found = False

        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < first_marker_pos:
                first_marker_pos = pos
                marker_found = True

        # If we found a marker, truncate the line at that position
        if marker_found:
            processed_line = line[:first_marker_pos]
        else:
            processed_line = line

        # Strip trailing whitespace
        processed_line = processed_line.rstrip()
        result_lines.append(processed_line)

    return '\n'.join(result_lines)

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    if not nums:
        return []

    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)

def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into terms
    terms = []
    # Split by + and - signs, keeping the signs
    tokens = re.findall(r'[+-]?[^+-]+', expression)

    for token in tokens:
        if not token:
            continue
        # Determine the sign
        if token.startswith('-'):
            sign = -1
            term = token[1:]
        elif token.startswith('+'):
            sign = 1
            term = token[1:]
        else:
            sign = 1
            term = token

        # Extract coefficient and variables
        # Find the coefficient (all leading digits)
        coeff_match = re.match(r'^(\d+)', term)
        if coeff_match:
            coeff = int(coeff_match.group(1))
            var_part = term[coeff_match.end():]
        else:
            coeff = 1
            var_part = term

        # Apply sign to coefficient
        coeff *= sign

        # Sort variables alphabetically to canonicalize
        variables = sorted(list(var_part))
        canonical_var = ''.join(variables)

        terms.append((coeff, canonical_var))

    # Aggregate like terms
    aggregated = defaultdict(int)
    for coeff, var in terms:
        aggregated[var] += coeff

    # Remove zero coefficients
    aggregated = {var: coeff for var, coeff in aggregated.items() if coeff != 0}

    # Sort terms
    sorted_terms = sorted(aggregated.items(), key=lambda x: (len(x[0]), x[0]))

    # Format output
    result = []
    first = True
    for var, coeff in sorted_terms:
        if coeff == 1 and not first:
            term = var
        elif coeff == -1 and not first:
            term = '-' + var
        elif coeff == 1 and first:
            term = var
        elif coeff == -1 and first:
            term = '-' + var
        else:
            term = str(coeff) + var

        if first:
            result.append(term)
            first = False
        else:
            if term.startswith('-'):
                result.append('-' + term[1:])
            else:
                result.append('+' + term)

    return ''.join(result)

def sum_of_a_beach(string):
    if not string:
        return 0

    count = 0
    text = string.lower()

    # Search for each word separately
    words = ["sand", "water", "fish", "sun"]

    for word in words:
        start = 0
        while True:
            pos = text.find(word, start)
            if pos == -1:
                break
            count += 1
            start = pos + 1  # Move by 1 to avoid overlapping

    return count

