def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) <= 1:
        return True

    is_increasing = None

    for i in range(len(l) - 1):
        if l[i] < l[i + 1]:
            if is_increasing is False:
                return False
            is_increasing = True
        elif l[i] > l[i + 1]:
            if is_increasing is True:
                return False
            is_increasing = False
        # If l[i] == l[i + 1], we don't change is_increasing

    return True

def choose(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1

    # Use the smaller of k and n-k to minimize computation
    k = min(k, n - k)

    # Calculate C(n,k) = n! / (k! * (n-k)!)
    # Using the iterative approach to avoid large factorials
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

def smallest_change(arr):
    if not arr:
        return 0

    changes = 0
    n = len(arr)

    # Compare elements from both ends moving toward the center
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1

    return changes

