        class_count = 0
        element_count = 0

        # Split by spaces to handle compound selectors
        parts = selector.split()

        for part in parts:
            # Count ID selectors (#id)
            if part.startswith('#'):
                id_count += 1
            # Count class selectors (.class)
            elif part.startswith('.'):
                class_count += 1
            # Count element selectors (tag names)
            else:
