                # Remove any # or . from the part to count elements
                clean_part = ''.join(c for c in part if c not in '#.')
                if clean_part:  # Only count if there's actually an element
                    element_count += 1

        return (id_count, class_count, element_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    # Compare specificity tuples
    if spec1 > spec2:
        return selector1
    else:
        return selector2

