def amazon_check_mate(king, amazon):
    def parse_pos(pos):
        col = ord(pos[0]) - ord('a')
        row = int(pos[1]) - 1
        return (col, row)

    w_king = parse_pos(king)
    w_amazon = parse_pos(amazon)

    # Squares attacked by amazon (queen + knight moves)
    amazon_attacks = set()
    aw, ah = w_amazon

    # Queen moves (horizontal, vertical, diagonal)
    for d_col in [-1, 0, 1]:
        for d_row in [-1, 0, 1]:
            if d_col == 0 and d_row == 0:
                continue
            col, row = aw + d_col, ah + d_row
            while 0 <= col < 8 and 0 <= row < 8:
                amazon_attacks.add((col, row))
                col += d_col
                row += d_row

    # Knight moves
    knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
                    (1, -2), (1, 2), (2, -1), (2, 1)]
    for dc, dr in knight_moves:
        col, row = aw + dc, ah + dr
        if 0 <= col < 8 and 0 <= row < 8:
            amazon_attacks.add((col, row))

    # Squares adjacent to white king (black king cannot be here)
    white_king_adj = set()
    for d_col in [-1, 0, 1]:
        for d_row in [-1, 0, 1]:
            if d_col == 0 and d_row == 0:
                continue
            col, row = w_king[0] + d_col, w_king[1] + d_row
            if 0 <= col < 8 and 0 <= row < 8:
                white_king_adj.add((col, row))

    checkmate = 0
    check = 0
    stalemate = 0
    safe_with_moves = 0

    for col in range(8):
        for row in range(8):
            if (col, row) == w_king:
                continue
            if (col, row) == w_amazon:
                continue
            if (col, row) in white_king_adj:
                continue

            is_attacked = (col, row) in amazon_attacks
            can_escape = False

            for d_col in [-1, 0, 1]:
                for d_row in [-1, 0, 1]:
                    if d_col == 0 and d_row == 0:
                        continue
                    new_col, new_row = col + d_col, row + d_row
                    if not (0 <= new_col < 8 and 0 <= new_row < 8):
                        continue
                    if (new_col, new_row) == w_king:
                        continue
                    if (new_col, new_row) == w_amazon:
                        continue
                    if (new_col, new_row) in white_king_adj:
                        continue
                    if (new_col, new_row) in amazon_attacks:
                        continue
                    can_escape = True
                    break
                if can_escape:
                    break

            if is_attacked and not can_escape:
                checkmate += 1
            elif is_attacked and can_escape:
                check += 1
            elif not is_attacked and not can_escape:
                stalemate += 1
            else:
                safe_with_moves += 1

    return [checkmate, check, stalemate, safe_with_moves]

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    if is_prime(n):
        return x
    else:
        return y

