def is_balanced(text, pairs):
    close_to_open = {}
    opening_chars = set()

    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        close_to_open[close_char] = open_char
        opening_chars.add(open_char)

    stack = []

    for char in text:
        if char not in opening_chars and char not in close_to_open:
            continue

        if char in close_to_open:
            if stack and stack[-1] == close_to_open[char]:
                stack.pop()
                continue

        if char in opening_chars:
            stack.append(char)

    return len(stack) == 0

def is_balanced(text, pairs):
    # Build mapping from closing characters to their corresponding opening characters
    closing_to_opening = {}
    opening_set = set()

    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        closing_to_opening[closing] = opening
        opening_set.add(opening)

    stack = []

    for char in text:
        if char in opening_set:
            # Opening character: push onto stack
            stack.append(char)
        elif char in closing_to_opening:
            # Closing character: must match most recent opening
            if not stack or stack[-1] != closing_to_opening[char]:
                return False
            stack.pop()
        # Ignore all other characters

    # All opening characters must have been closed
    return len(stack) == 0

