            return True
        # Knight moves
        if (abs(amazon_x - x) == 2 and abs(amazon_y - y) == 1) or \
           (abs(amazon_x - x) == 1 and abs(amazon_y - y) == 2):
            return True
        return False

    def get_king_moves(x, y):
        moves = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny):
                    moves.append((nx, ny))
        return moves

