            # Skip if position is invalid or adjacent to white king
            if not is_valid(x, y) or is_adjacent((x, y), (king_x, king_y)):
                continue

            # Skip if position is attacked by amazon
            if (x, y) in attacked:
                # Check if black king can escape
                can_escape = False
                for dx in [-1, 0, 1]:
                    for dy in [-1, 0, 1]:
                        if dx == 0 and dy == 0:
