                        nx, ny = x + dx, y + dy
                        if is_valid(nx, ny) and not is_adjacent((nx, ny), (king_x, king_y)):
                            if (nx, ny) not in attacked:
                                can_escape = True
                                break
                    if can_escape:
                        break

                if can_escape:
                    # It's a check
                    result[1] += 1
                else:
                    # It's a checkmate
                    result[0] += 1
            else:
                # Check if black king can move
                can_move = False
                for dx in [-1, 0, 1]:
                    for dy in [-1, 0, 1]:
                        if dx == 0 and dy == 0:
