def converter(data, input_type, output_type):
    """
    Convert data from one type to another

    Args:
        data: The input data to convert
        input_type: Type of input data ('int', 'float', 'str', 'list', 'dict')
        output_type: Type to convert to ('int', 'float', 'str', 'list', 'dict')

    Returns:
        Converted data in the specified output type
    """
    try:
        if input_type == output_type:
            return data

        if input_type == 'int' and output_type == 'str':
            return str(data)
        elif input_type == 'int' and output_type == 'float':
            return float(data)
        elif input_type == 'float' and output_type == 'int':
            return int(data)
        elif input_type == 'float' and output_type == 'str':
            return str(data)
