def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into monomials
    monomials = []
    # Split by + and - signs, keeping the signs
    tokens = re.findall(r'[+-]?[^+-]+', expression)

    for token in tokens:
        if not token:
            continue
        # Determine the sign
        sign = 1
        if token.startswith('-'):
            sign = -1
            token = token[1:]
        elif token.startswith('+'):
            token = token[1:]

        # Extract coefficient and monomial part
        if token[0].isdigit():
            coeff_str = ''
            i = 0
            while i < len(token) and token[i].isdigit():
                coeff_str += token[i]
                i += 1
            coefficient = int(coeff_str) * sign
            monomial = token[i:]
        else:
            coefficient = sign
            monomial = token

        # Sort the variables in the monomial
        sorted_monomial = ''.join(sorted(monomial))
        monomials.append((coefficient, sorted_monomial))

    # Group by monomial terms and sum coefficients
    term_dict = defaultdict(int)
    for coeff, mono in monomials:
        term_dict[mono] += coeff

    # Remove terms with zero coefficient
    term_dict = {mono: coeff for mono, coeff in term_dict.items() if coeff != 0}

    # Sort terms by number of variables, then lexicographically
    sorted_terms = sorted(term_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Format the result
    result_parts = []
    for i, (mono, coeff) in enumerate(sorted_terms):
        if coeff == 1 and i > 0:
            # Don't show coefficient 1 for positive terms (except first)
            result_parts.append('+' + mono if i > 0 else mono)
        elif coeff == -1 and i > 0:
            # Show -1 as just -
            result_parts.append('-' + mono)
        elif coeff > 0 and i > 0:
            result_parts.append('+' + str(coeff) + mono)
        elif coeff < 0:
            result_parts.append('-' + str(-coeff) + mono)
        else:
            result_parts.append(str(coeff) + mono)

    # Special case for first term - don't show leading +
    if result_parts and result_parts[0].startswith('+'):
        result_parts[0] = result_parts[0][1:]

    return ''.join(result_parts)

def reverse_delete(s, c=None):
    # Handle the case where input comes as a list
    if isinstance(s, list) and c is None:
        s, c = s[0], s[1]

    # Remove all characters from s that appear in c
    result = ''.join(char for char in s if char not in c)

    # Check if the result is a palindrome
    is_palindrome = result == result[::-1]

    return (result, is_palindrome)

