from collections import defaultdict

def parse_url(url):
    # Remove "http://" prefix
    if url.startswith("http://"):
        url = url[7:]

    # Split by first slash to get hostname and path
    if '/' in url:
        hostname, path = url.split('/', 1)
        # Add slash to path to distinguish between path and path/
        if not path.endswith('/'):
            path = path + '/'
    else:
        hostname = url
        path = '/'

    return hostname, path

def normalize_path(path):
    # Normalize path to handle cases like "test/" vs "test"
    if path == '/':
        return ''
    if path.endswith('/'):
        return path[:-1]
    return path

def get_path_set(paths):
    # Convert list of paths to a set for comparison
    return frozenset(paths)

def main():
    data = sys.stdin.read()
    lines = data.strip().split('\n')

    n = int(lines[0])

    # Dictionary to store hostname -> set of paths
    hostname_paths = defaultdict(set)

    # Parse all URLs and collect paths for each hostname
    for i in range(1, n + 1):
        url = lines[i]
        hostname, path = parse_url(url)
        hostname_paths[hostname].add(path)

    # Group hostnames by their path sets
    path_set_to_hostnames = defaultdict(list)

    for hostname, paths in hostname_paths.items():
        # Convert to sorted tuple for consistent hashing
        path_set = get_path_set(paths)
        path_set_to_hostnames[path_set].append(hostname)

    # Find clusters with more than one hostname
    clusters = []
    for path_set, hostnames in path_set_to_hostnames.items():
        if len(hostnames) > 1:
            clusters.append(sorted(hostnames))

    # Output results
    print(len(clusters))
    for cluster in clusters:
        # Reconstruct full URLs
        full_urls = [f"http://{hostname}" for hostname in cluster]
        print(" ".join(full_urls))

if __name__ == "__main__":
    main()

