def simplify(expr):
    from collections import defaultdict

    if not expr:
        return ""

    # Step 1: Parse the expression into individual monomials
    monomials = []
    i = 0
    while i < len(expr):
        sign = ''
        if expr[i] in '+-':
            sign = expr[i]
            i += 1

        j = i
        while j < len(expr) and expr[j] not in '+-':
            j += 1

        if j > i:
            monomial = sign + expr[i:j]
            monomials.append(monomial)
            i = j
        else:
            i += 1

    # Step 2 & 3: Normalize and aggregate coefficients by sorted variable string
    coeffs = defaultdict(int)

    for monomial in monomials:
        if monomial.startswith('-'):
            coeff = -1
            rest = monomial[1:]
        elif monomial.startswith('+'):
            coeff = 1
            rest = monomial[1:]
        else:
            coeff = 1
            rest = monomial

        # Extract numeric coefficient if present
        if rest and rest[0].isdigit():
            k = 0
            while k < len(rest) and rest[k].isdigit():
                k += 1
            coeff_str = rest[:k]
            rest = rest[k:]
            coeff = int(coeff_str)

        # Sort variables alphabetically for normalization
        variables = ''.join(sorted(rest))
        coeffs[variables] += coeff

    # Step 4: Filter out zero coefficients
    terms = [(variables, coeff) for variables, coeff in coeffs.items() if coeff != 0]

    # Step 5: Sort by number of variables, then lexicographically
    terms.sort(key=lambda x: (len(x[0]), x[0]))

    # Step 6: Format the output string
    result = []
    for variables, coeff in terms:
        if coeff == 1 and variables:
            term = variables
        elif coeff == -1 and variables:
            term = '-' + variables
        else:
            term = str(coeff) + variables

        if not result:
            result.append(term)
        else:
            if term.startswith('-'):
                result.append(term)
            else:
                result.append('+' + term)

    return ''.join(result)

