def solution(text, markers):
    lines = text.split('\n')
    result_lines = []

    for line in lines:
        # Find the first occurrence of any marker
        first_marker_pos = len(line)

        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < first_marker_pos:
                first_marker_pos = pos

        # If a marker was found, slice the line up to that position
        if first_marker_pos < len(line):
