def differentiate(polynomial, x):
    # Remove all spaces
    polynomial = polynomial.replace(" ", "")

    # Split by + and - operators, keeping the operators
    terms = []
    current_term = ""

    for i, char in enumerate(polynomial):
        if char in ['+', '-'] and i > 0:
            terms.append(current_term)
            current_term = char
        else:
            current_term += char

    terms.append(current_term)

    # Process each term
    derivative_terms = []

    for term in terms:
        if not term:
            continue

        # Handle the case where term starts with a minus sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        else:
            sign = 1

        # Parse the term
        if 'x^' in term:
            # Term is like "3x^2" or "-3x^2"
            parts = term.split('x^')
            coeff_str = parts[0]
            if coeff_str == '' or coeff_str == '+':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)
            coeff *= sign
            exponent = int(parts[1])

            # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
            if exponent > 0:
                new_coeff = coeff * exponent
                new_exponent = exponent - 1
                if new_exponent == 0:
                    derivative_terms.append(str(new_coeff))
                elif new_exponent == 1:
                    derivative_terms.append(f"{new_coeff}x")
                else:
                    derivative_terms.append(f"{new_coeff}x^{new_exponent}")

        elif 'x' in term:
            # Term is like "3x" or "-3x"
            coeff_str = term.replace('x', '')
            if coeff_str == '' or coeff_str == '+':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)
            coeff *= sign

            # Apply power rule: d/dx(ax^1) = 1*ax^0 = a
            derivative_terms.append(str(coeff))

        else:
            # Term is a constant
            # Derivative of a constant is 0
            continue

    # If no terms, derivative is 0
    if not derivative_terms:
        return 0

    # Create the derivative polynomial string
    derivative_poly = derivative_terms[0]
    for i in range(1, len(derivative_terms)):
        if derivative_terms[i].startswith('-'):
            derivative_poly += f" - {derivative_terms[i][1:]}"
        else:
            derivative_poly += f" + {derivative_terms[i]}"

    # Evaluate the derivative at x
    # Replace x with the value and evaluate
    result = 0
    for term in derivative_terms:
        if 'x' in term:
            if term == 'x':
                result += x
            elif term == '-x':
                result -= x
            else:
                # Extract coefficient and exponent
                if term.startswith('-'):
                    coeff_str = term[1:]
                    if 'x^' in coeff_str:
                        coeff_str = coeff_str.split('x^')[0]
                        coeff = int(coeff_str) * -1
                    else:
                        coeff = int(coeff_str[:-1]) * -1
                else:
                    if 'x^' in term:
                        coeff_str = term.split('x^')[0]
                        coeff = int(coeff_str)
                    else:
                        coeff = int(term[:-1])

                # Calculate coeff * x^exponent
                if 'x^' in term:
                    exponent = int(term.split('x^')[1])
                    result += coeff * (x ** exponent)
                else:
                    result += coeff * x
        else:
            # Constant term
            result += int(term)

    return result

def histogram(test):
    if not test:
        return {}

    # Split the string into individual characters
    letters = test.split()

    # Count frequency of each letter
    freq_count = {}
    for letter in letters:
        freq_count[letter] = freq_count.get(letter, 0) + 1

    # Find the maximum frequency
    max_freq = max(freq_count.values())

    # Filter to only include letters with maximum frequency
    result = {letter: count for letter, count in freq_count.items() if count == max_freq}

    return result

