def next_bigger(n):
    digits = [int(d) for d in str(n)]

    # Step 2: Find rightmost digit smaller than next digit
    i = None
    for idx in range(len(digits) - 2, -1, -1):
        if digits[idx] < digits[idx + 1]:
            i = idx
            break

    # Step 3: If no such position exists, return -1
    if i is None:
        return -1

    # Step 4: Find smallest digit on the right > digits[i]
    j = None
    for idx in range(len(digits) - 1, i, -1):
        if digits[idx] > digits[i]:
            j = idx
            break

    # Step 5: Swap digits at i and j
    digits[i], digits[j] = digits[j], digits[i]

    # Step 6: Reverse digits after position i
    digits[i + 1:] = reversed(digits[i + 1:])

    # Step 7: Convert back to integer
    return int(''.join(str(d) for d in digits))

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)

def is_balanced(s, pairs):
    # Build opening set and closing map
    openers = set()
    closers = {}

    for i in range(0, len(pairs), 2):
        opener = pairs[i]
        closer = pairs[i + 1]
        openers.add(opener)
        closers[closer] = opener

    stack = []

    for char in s:
        if char in closers:
            # Character is in closing map (potential closer)
            if char in openers:
                # Character is both opener and closer (identical pair like "'" or "-")
                if stack and stack[-1] == char:
                    # Stack not empty and top matches - treat as closer
                    stack.pop()
                else:
                    # Stack empty or top doesn't match - treat as opener
                    stack.append(char)
            else:
                # Character is only a closer (distinct from opener)
                if not stack or stack[-1] != closers[char]:
                    return False
                stack.pop()
        elif char in openers:
            # Character is only an opener (not in closing map)
            stack.append(char)
        # Ignore characters not in pairs

    return len(stack) == 0

def getAllPrimeFactors(n):
    # Input validation
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Special cases
    if n == 1:
        return [1]
    if n == 2:
        return [2]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Input validation
    if not isinstance(n, int):
        return [[], []]
    if n <= 0:
        return [[], []]

    # Special cases
    if n == 1:
        return [[1], [1]]
    if n == 2:
        return [[2], [1]]

    factors = getAllPrimeFactors(n)

    if not factors:
        return [[], []]

    unique_factors = []
    counts = []

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Input validation
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Special cases
    if n == 1:
        return [1]
    if n == 2:
        return [2]

    factor_count_pairs = getUniquePrimeFactorsWithCount(n)
    unique_factors = factor_count_pairs[0]
    counts = factor_count_pairs[1]

    products = []

    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

