    # Process each term
    term_dict = defaultdict(int)

    for term in terms:
        # Determine the sign
        sign = 1
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            term = term[1:]

        # Extract coefficient and variables
        # Look for the first letter that is a variable
        coeff_str = ""
        var_part = ""
        i = 0

        # Check if the term is just a variable or a number
        if term and term[0].isalpha():
            # No explicit coefficient, so coefficient is 1 or -1
            coeff = sign
            var_part = term
        else:
            # Extract coefficient first
            while i < len(term) and (term[i].isdigit() or term[i] == '-'):
                coeff_str += term[i]
                i += 1

            if not coeff_str:
                coeff = sign
            else:
                coeff = sign * int(coeff_str)

            # Remaining part is variables
            var_part = term[i:]

            # If coefficient is 0, skip this term
            if coeff == 0:
                continue

        # Normalize the variable part
        if var_part:
            sorted_vars = ''.join(sorted(var_part))
            term_dict[sorted_vars] += coeff
        else:
            # Handle constant terms (should not occur in multilinear non-constant)
            pass

    # Build the result
    result_terms = []

    # Sort by number of variables, then lexicographically
    sorted_items = sorted(term_dict.items(), key=lambda x: (len(x[0]), x[0]))

    for var_str, coeff in sorted_items:
        if coeff == 0:
            continue

        if coeff == 1:
            if not result_terms:
                result_terms.append(var_str)
            else:
                result_terms.append("+" + var_str)
        elif coeff == -1:
            result_terms.append("-" + var_str)
        else:
            if not result_terms:
                result_terms.append(str(coeff) + var_str)
            else:
                if coeff > 0:
                    result_terms.append("+" + str(coeff) + var_str)
                else:
                    result_terms.append(str(coeff) + var_str)

    if not result_terms:
        return ""

    return "".join(result_terms)

def encrypt(s):
    result = []
    for char in s:
        if char.islower():
            # Shift lowercase letters by 4 positions with wrapping
            shifted = chr((ord(char) - ord('a') + 4) % 26 + ord('a'))
            result.append(shifted)
        else:
            # Keep other characters unchanged
            result.append(char)
    return ''.join(result)

def poohbear(code):
    # Filter out non-command characters
    valid_commands = "+-><cWEPNTQU LIVABYD"
    cmd_chars = [char for char in code if char in valid_commands]

    # Pre-process W-E loops
    w_to_e = {}  # maps W index in cmd_chars to matching E index
    e_to_w = {}  # maps E index in cmd_chars to matching W index
    stack = []

    for i, cmd in enumerate(cmd_chars):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                w_idx = stack.pop()
                w_to_e[w_idx] = i
                e_to_w[i] = w_idx

    # Initialize memory and pointer
    memory = {}  # Dictionary for infinite cells, default value 0
    pointer = 0
    copied = 0  # "copied" value from c command
    output = []

    # Execute commands
    cmd_idx = 0

    while cmd_idx < len(cmd_chars):
        cmd = cmd_chars[cmd_idx]
        cell = memory.get(pointer, 0)

        if cmd == '+':
            memory[pointer] = (cell + 1) % 256
        elif cmd == '-':
            memory[pointer] = (cell - 1) % 256
        elif cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == 'c':
            copied = cell
        elif cmd == 'p':
            memory[pointer] = copied
        elif cmd == 'W':
            if cell == 0:
                cmd_idx = w_to_e[cmd_idx] + 1
            else:
                cmd_idx += 1
        elif cmd == 'E':
            if cell != 0:
                cmd_idx = e_to_w[cmd_idx]
            else:
                cmd_idx += 1
        elif cmd == 'P':
            output.append(chr(cell))
        elif cmd == 'N':
            output.append(str(cell))
        elif cmd == 'T':
            memory[pointer] = (cell * 2) % 256
        elif cmd == 'Q':
            memory[pointer] = (cell * cell) % 256
        elif cmd == 'U':
            memory[pointer] = int(cell ** 0.5) % 256
        elif cmd == 'L':
            memory[pointer] = (cell + 2) % 256
        elif cmd == 'I':
            memory[pointer] = (cell - 2) % 256
        elif cmd == 'V':
            memory[pointer] = (cell // 2) % 256
        elif cmd == 'A':
            memory[pointer] = (cell + copied) % 256
        elif cmd == 'B':
            memory[pointer] = (cell - copied) % 256
        elif cmd == 'Y':
            memory[pointer] = (cell * copied) % 256
        elif cmd == 'D':
            if copied != 0:
                memory[pointer] = (cell // copied) % 256

        cmd_idx += 1

    return ''.join(output)

def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def automorphic(n: int) -> bool:
    n_str = str(n)
    n_sq = n * n
    n_sq_str = str(n_sq)
    return n_sq_str.endswith(n_str)

def separate_paren_groups(s):
    result = []
    current_group = []
    counter = 0

    for char in s:
        if char == ' ':
            continue

        current_group.append(char)

        if char == '(':
            counter += 1
        elif char == ')':
            counter -= 1

        if counter == 0:
            result.append(''.join(current_group))
            current_group = []

    return result

