def poohbear(code):
    cells = {}  # Infinite cells in both directions
    ptr = 0  # Cell pointer
    copied = 0  # Copied value for c/p commands
    output = []  # Collect output

    def get_cell(pos):
        return cells.get(pos, 0)

    def set_cell(pos, value):
        # Wrap value to 0-255 range
        cells[pos] = value % 256

    # Filter only valid commands
    instructions = [c for c in code if c in '+-><cpWEPNTQULIVABYD']

    # Build W-E loop matching pairs
    w_to_e = {}
    e_to_w = {}
    stack = []

    for i, cmd in enumerate(instructions):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                w_idx = stack.pop()
                w_to_e[w_idx] = i
                e_to_w[i] = w_idx

    # Execute
    pc = 0
    while pc < len(instructions):
        cmd = instructions[pc]

        if cmd == '+':
            set_cell(ptr, get_cell(ptr) + 1)
        elif cmd == '-':
            set_cell(ptr, get_cell(ptr) - 1)
        elif cmd == '>':
            ptr += 1
        elif cmd == '<':
            ptr -= 1
        elif cmd == 'c':
            copied = get_cell(ptr)
        elif cmd == 'p':
            set_cell(ptr, copied)
        elif cmd == 'W':
            if get_cell(ptr) == 0:
                pc = w_to_e.get(pc, pc + 1)
            else:
                pc += 1
        elif cmd == 'E':
            if get_cell(ptr) != 0:
                pc = e_to_w.get(pc, pc + 1)
            else:
                pc += 1
        elif cmd == 'P':
            val = get_cell(ptr)
            output.append(chr(val))
        elif cmd == 'N':
            val = get_cell(ptr)
            output.append(str(val))
        elif cmd == 'T':
            set_cell(ptr, get_cell(ptr) * 2)
        elif cmd == 'Q':
            set_cell(ptr, get_cell(ptr) ** 2)
        elif cmd == 'U':
            val = get_cell(ptr)
            set_cell(ptr, int(val ** 0.5))
        elif cmd == 'L':
            set_cell(ptr, get_cell(ptr) + 2)
        elif cmd == 'I':
            set_cell(ptr, get_cell(ptr) - 2)
        elif cmd == 'V':
            val = get_cell(ptr)
            set_cell(ptr, int(val / 2))
        elif cmd == 'A':
            set_cell(ptr, get_cell(ptr) + copied)
        elif cmd == 'B':
            set_cell(ptr, get_cell(ptr) - copied)
        elif cmd == 'Y':
            set_cell(ptr, get_cell(ptr) * copied)
        elif cmd == 'D':
            val = get_cell(ptr)
            if copied != 0:
                set_cell(ptr, int(val / copied))
            # If copied is 0, cell stays unchanged
        else:
            # Unknown command, skip
            pass

        pc += 1

    return ''.join(output)

