def is_balanced(s, pairs):
    opening = set()
    closing = set()
    close_to_open = {}

    # Parse the pairs string to build character mappings
    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        opening.add(open_char)
        closing.add(close_char)
        close_to_open[close_char] = open_char

    stack = []

    for char in s:
        if char in opening:
            stack.append(char)
        elif char in closing:
            if not stack:
                return False
            if close_to_open[char] != stack.pop():
                return False

    return len(stack) == 0

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    gems = list(map(int, lines[1].split()))

    # Precompute palindromes
    is_palindrome = [[False] * n for _ in range(n)]

    # Every single gem is a palindrome
    for i in range(n):
        is_palindrome[i][i] = True

    # Check for palindromes of length 2
    for i in range(n - 1):
        if gems[i] == gems[i + 1]:
            is_palindrome[i][i + 1] = True

    # Check for palindromes of length 3 and more
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if gems[i] == gems[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP table: dp[i][j] represents minimum moves to eliminate substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Base case: single gem requires 1 move
    for i in range(n):
        dp[i][i] = 1

    # Fill DP table for substrings of increasing length
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if is_palindrome[i][j]:
                # If the substring is already a palindrome, remove it in one move
                dp[i][j] = 1
            else:
                # Find the minimum moves by trying all possible splits
                dp[i][j] = length  # Worst case: remove each gem individually
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

