from typing import List, Optional


def longest(strings: List[str]) -> Optional[str]:
    if not strings:
        return None

    max_string = strings[0]

    for s in strings[1:]:
        if len(s) > len(max_string):
            max_string = s

    return max_string

def choose(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry property: C(n, k) = C(n, n-k)
    k = min(k, n - k)

    # Compute using multiplicative formula with integer arithmetic
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

def encrypt(s):
    result = ""
    for char in s:
        if char.isalpha():
            if char.islower():
                # For lowercase letters, shift by 4 positions with wrapping
                shifted = (ord(char) - ord('a') + 4) % 26
                result += chr(shifted + ord('a'))
            else:
                # For uppercase letters, shift by 4 positions with wrapping
                shifted = (ord(char) - ord('A') + 4) % 26
                result += chr(shifted + ord('A'))
        else:
            # Non-alphabetic characters remain unchanged
            result += char
    return result

