def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create list of tuples: (digit_sum, sign_priority, original_index, value)
    # sign_priority: 0 for negative, 1 for non-negative
    indexed_nums = [(digit_sum(num), 0 if num < 0 else 1, i, num) for i, num in enumerate(nums)]

    # Sort by digit_sum, then by sign_priority (negative before positive), then by original index
    indexed_nums.sort(key=lambda x: (x[0], x[1], x[2]))

    # Extract the original values in the new order
    return [num for _, _, _, num in indexed_nums]

import math

def converter(number, decimals=0, base=math.pi):
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36")

    if decimals < 0:
        raise ValueError("Decimals must be non-negative")

    # Handle sign
    is_negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_digits = ['0']
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % int(base)
            integer_digits.append(remainder)
            temp = temp // int(base)
        integer_digits.reverse()

    # Convert fractional part
    fractional_digits = []
    if decimals > 0:
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            fractional_digits.append(digit)
            fractional_part -= digit

    # Convert digits to characters
    def digit_to_char(digit):
        if digit < 10:
            return str(digit)
        else:
            return chr(ord('A') + digit - 10)

    # Build integer part string
    integer_str = ''.join(digit_to_char(d) for d in integer_digits)

    # Build fractional part string
    if decimals > 0:
        fractional_str = ''.join(digit_to_char(d) for d in fractional_digits)
        result = integer_str + '.' + fractional_str
    else:
        result = integer_str

    # Add sign if needed
    if is_negative and result != '0':
        result = '-' + result

    # Handle special case where result is just "0" but we need to show decimal places
    if result == '0' and decimals > 0:
        result = '0.' + '0' * decimals

    # Special handling for numbers less than 1
    if result.startswith('.'):
        result = '0' + result

    return result

def next_smallest(lst):
    if not lst:
        return None

    smallest = float('inf')
    second_smallest = float('inf')

    for num in lst:
        if num < smallest:
            second_smallest = smallest
            smallest = num
        elif num < second_smallest and num != smallest:
            second_smallest = num

    return second_smallest if second_smallest != float('inf') else None

