def amazon_check_mate(white_pieces, black_pieces):
    # Input validation
    if not isinstance(white_pieces, list) or not isinstance(black_pieces, list):
        raise ValueError("Both inputs must be lists")

    if len(white_pieces) == 0 or len(black_pieces) == 0:
        raise ValueError("Both white_pieces and black_pieces must be non-empty lists")

    # Validate position format and convert to coordinates
    def validate_position(pos):
        if not isinstance(pos, str):
            raise ValueError(f"Invalid position type: {type(pos)}")
        if len(pos) != 2:
            raise ValueError(f"Invalid position format: {pos}")
        file_char = pos[0].lower()
        rank_char = pos[1]
        if not ('a' <= file_char <= 'h'):
            raise ValueError(f"Invalid file: {file_char}")
        if not ('1' <= rank_char <= '8'):
            raise ValueError(f"Invalid rank: {rank_char}")
        return (ord(file_char) - ord('a'), int(rank_char) - 1)

    # Validate all positions and check for duplicates within each color
    def validate_pieces(pieces):
        positions = []
        for pos in pieces:
            coords = validate_position(pos)
            if coords in positions:
                raise ValueError(f"Duplicate position: {pos}")
            positions.append(coords)
        return positions

    white_positions = validate_pieces(white_pieces)
    black_positions = validate_pieces(black_pieces)

    # Check for overlapping positions between white and black
    for wp in white_positions:
        if wp in black_positions:
            raise ValueError("Overlapping positions between white and black pieces")

    # Find white king position (first position in white_pieces represents the king)
    white_king_pos = white_positions[0]

    def is_king_attacked(king_pos, attacker_positions):
        """Check if the king position is under attack by any piece in attacker_positions"""
        kx, ky = king_pos

        for pos in attacker_positions:
            px, py = pos
            dx = abs(kx - px)
            dy = abs(ky - py)

            # King attacks adjacent squares (1 square in any direction)
            if dx <= 1 and dy <= 1 and not (dx == 0 and dy == 0):
                return True

            # Queen-like attacks (horizontal, vertical, diagonal - any distance)
            if dx == 0 or dy == 0 or dx == dy:
                return True

        return False

    def is_in_check(king_pos, black_positions):
        """Check if the king is currently in check"""
        return is_king_attacked(king_pos, black_positions)

    def get_king_moves(king_pos):
        """Get all possible moves for the king (1 square in any direction)"""
        kx, ky = king_pos
        moves = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                new_x, new_y = kx + dx, ky + dy
                # Check if move is within board boundaries
                if 0 <= new_x < 8 and 0 <= new_y < 8:
                    # Check if target square is not occupied by white piece
                    if (new_x, new_y) not in white_positions:
                        moves.append((new_x, new_y))
        return moves

    def is_checkmate():
        """Determine if the position is checkmate for the white king"""
        # First check if king is in check
        if not is_in_check(white_king_pos, black_positions):
            return False

        # Check all possible king moves
        king_moves = get_king_moves(white_king_pos)

        # Check if any move escapes check
        for move in king_moves:
            if not is_in_check(move, black_positions):
                return False

        return True

    return is_checkmate()

def poohbear(code):
    import math

    memory = {}
    cell_ptr = 0
    copy_register = 0
    output = []

    def get_cell():
        return memory.get(cell_ptr, 0)

    def set_cell(value):
        memory[cell_ptr] = ((value % 256) + 256) % 256

    # Preprocess W/E pairs for loops
    w_to_e = {}
    e_to_w = {}
    stack = []

    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                w_pos = stack.pop()
                w_to_e[w_pos] = i
                e_to_w[i] = w_pos

    pc = 0
    while pc < len(code):
        cmd = code[pc]

        if cmd not in '+-><cpWEPNTQUILYDAB':
            pc += 1
            continue

        current = get_cell()

        if cmd == '+':
            set_cell(current + 1)
        elif cmd == '-':
            set_cell(current - 1)
        elif cmd == '>':
            cell_ptr += 1
        elif cmd == '<':
            cell_ptr -= 1
        elif cmd == 'c':
            copy_register = current
        elif cmd == 'p':
            set_cell(copy_register)
        elif cmd == 'W':
            if current == 0:
                pc = w_to_e[pc] + 1
                continue
            pc += 1
        elif cmd == 'E':
            if current != 0:
                pc = e_to_w[pc]
                continue
            pc += 1
        elif cmd == 'P':
            output.append(chr(current))
        elif cmd == 'N':
            output.append(str(current))
        elif cmd == 'T':
            set_cell(current * 2)
        elif cmd == 'Q':
            set_cell(current * current)
        elif cmd == 'U':
            set_cell(int(math.floor(current ** 0.5)))
        elif cmd == 'L':
            set_cell(current + 2)
        elif cmd == 'I':
            set_cell(current - 2)
        elif cmd == 'V':
            set_cell(current // 2)
        elif cmd == 'A':
            set_cell(current + copy_register)
        elif cmd == 'B':
            set_cell(current - copy_register)
        elif cmd == 'Y':
            set_cell(current * copy_register)
        elif cmd == 'D':
            if copy_register != 0:
                set_cell(current // copy_register)

        pc += 1

    return ''.join(output)

def encrypt(s):
    result = ""
    for char in s:
        if char.isalpha():
            # Determine if uppercase or lowercase
            if char.isupper():
                # For uppercase letters
                shifted = chr((ord(char) - ord('A') + 4) % 26 + ord('A'))
            else:
                # For lowercase letters
                shifted = chr((ord(char) - ord('a') + 4) % 26 + ord('a'))
            result += shifted
        else:
            # Non-alphabetic characters remain unchanged
            result += char
    return result

def cycpattern_check(string1: str, string2: str) -> bool:
    if len(string2) > len(string1):
        return False

    # Check all rotations of string1
    for i in range(len(string1)):
        # Create a rotation by slicing
        rotated = string1[i:] + string1[:i]
        if string2 in rotated:
            return True

    return False

