def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into monomials
    # Find all terms (including signs)
    terms = re.findall(r'[+-]?[^+-]+', expression)

    # Dictionary to store monomials and their coefficients
    monomial_dict = defaultdict(int)

    for term in terms:
        # Separate the coefficient from the variables
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Find coefficient
        coeff_str = ''
        i = 0
        while i < len(term) and term[i].isdigit():
            coeff_str += term[i]
            i += 1

        if coeff_str:
            coeff = int(coeff_str) * sign
        else:
            coeff = sign

        # Remaining part is the variables
        variables = term[i:]

        # Sort variables to normalize monomial representation
        sorted_variables = ''.join(sorted(variables))

        # Add to dictionary
        monomial_dict[sorted_variables] += coeff

    # Remove zero coefficients
    monomial_dict = {k: v for k, v in monomial_dict.items() if v != 0}

    # Sort monomials by number of variables, then lexicographically
    monomials = sorted(monomial_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Build result string
    result = []
    first = True

    for monomial, coeff in monomials:
        if coeff == 1 and not first:
            result.append('+' + monomial)
        elif coeff == -1 and not first:
            result.append('-' + monomial)
        elif coeff > 0 and not first:
            result.append('+' + str(coeff) + monomial)
        elif coeff < 0 and not first:
            result.append('-' + str(-coeff) + monomial)
        elif coeff > 0 and first:
            result.append(str(coeff) + monomial)
        elif coeff < 0 and first:
            result.append('-' + str(-coeff) + monomial)
        else:  # coeff == 0 (should not happen after filtering)
            pass

        first = False

    # Handle case where result is empty
    if not result:
        return "0"

    # Join and return
    return ''.join(result)

