def is_valid(s):
    # Rule: Each identifier must have at least one character
    if not s:
        return False

    # Helper function to check if a character is a valid first character
    # (alpha, underscore, or dollar sign)
    def is_valid_first_char(c):
        return c.isalpha() or c == '_' or c == '$'

    # Helper function to check if a character is a valid identifier character
    # (alpha, digit, underscore, or dollar sign)
    def is_valid_char(c):
        return c.isalpha() or c.isdigit() or c == '_' or c == '$'

    # Check first character (must be alpha, underscore, or dollar sign, not digit)
    if not is_valid_first_char(s[0]):
        return False

    # Check remaining characters (can be alpha, digit, underscore, or dollar sign)
    for c in s[1:]:
        if not is_valid_char(c):
            return False

    return True

def count_divisors(n):
    if n <= 0:
        return 0

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

def almost_everywhere_zero(n, k):
    n_str = str(n)
    length = len(n_str)

    memo = {}

    def dp(pos, count, tight, started):
        state = (pos, count, tight, started)
        if state in memo:
            return memo[state]

        if pos == length:
            return 1 if count == k and started else 0

        limit = int(n_str[pos]) if tight else 9
        result = 0

        for digit in range(0, limit + 1):
            new_tight = tight and (digit == limit)
            new_started = started or (digit > 0)

            if digit > 0:
                new_count = count + 1
            else:
                new_count = count

            if new_count <= k:
                result += dp(pos + 1, new_count, new_tight, new_started)

        memo[state] = result
        return result

    return dp(0, 0, True, False)

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False

        # Check odd divisors up to sqrt(num)
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    if is_prime(n):
        return x
    else:
        return y

def amazon_check_mate(king, amazon):
    def to_coords(pos):
        return (int(pos[1]) - 1, ord(pos[0]) - ord('a'))

    wking = to_coords(king)
    wamazon = to_coords(amazon)

    def is_adjacent(p1, p2):
        return abs(p1[0] - p2[0]) <= 1 and abs(p1[1] - p2[1]) <= 1 and p1 != p2

    def amazon_attacks(pos):
        # Queen-like attack (requires clear path)
        if pos[0] == wamazon[0] or pos[1] == wamazon[1] or abs(pos[0] - wamazon[0]) == abs(pos[1] - wamazon[1]):
            # Check if white king blocks the path
            if is_adjacent(pos, wking) or pos == wking:
                return False
            # Check if white king is on the attack line between amazon and pos
            dr = 0 if pos[0] == wamazon[0] else (1 if pos[0] > wamazon[0] else -1)
            dc = 0 if pos[1] == wamazon[1] else (1 if pos[1] > wamazon[1] else -1)
            r, c = wamazon[0] + dr, wamazon[1] + dc
            while (r, c) != pos:
                if (r, c) == wking:
                    return False
                r += dr
                c += dc
            return True
        # Knight-like attack
        dr, dc = abs(pos[0] - wamazon[0]), abs(pos[1] - wamazon[1])
        return (dr == 1 and dc == 2) or (dr == 2 and dc == 1)

    def is_safe(pos):
        return not is_adjacent(pos, wking) and pos != wking and pos != wamazon and not amazon_attacks(pos)

    result = [0, 0, 0, 0]  # checkmate, check, stalemate, safe

    for row in range(8):
        for col in range(8):
            pos = (row, col)
            # Skip invalid black king positions
            if pos == wking or pos == wamazon or is_adjacent(pos, wking):
                continue

            # Check if under attack
            under_attack = amazon_attacks(pos)

            # Check for valid moves
            has_valid_move = False
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    new_pos = (row + dr, col + dc)
                    if 0 <= new_pos[0] < 8 and 0 <= new_pos[1] < 8:
                        if is_safe(new_pos):
                            has_valid_move = True
                            break
                if has_valid_move:
                    break

            # Classify the position
            if under_attack:
                if has_valid_move:
                    result[1] += 1  # check
                else:
                    result[0] += 1  # checkmate
            else:
                if has_valid_move:
                    result[3] += 1  # safe with valid moves
                else:
                    result[2] += 1  # stalemate

    return result

