def parse_int(s):
    if not s or s == "zero":
        return 0

    units = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9,
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17,
        'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    scales = {
        'hundred': 100,
        'thousand': 1000
    }

    # Pre-process: remove 'and' and replace hyphens with spaces
    s = s.replace('-', ' ').replace(' and', '').replace('and ', '').replace(' and ', ' ')
    tokens = s.lower().split()

    total = 0
    current = 0

    for token in tokens:
        if token in units or token in tens:
            current += units.get(token, tens.get(token, 0))
        elif token in scales:
            if token == 'hundred':
                current *= 100
            elif token == 'thousand':
                current *= 1000
                total += current
                current = 0

    total += current
    return total

def order_by_points(nums):
    """
    Create a function that organizes the provided list of integers
    in ascending order based on their digit sum values.
    Note: when multiple elements share the same digit sum,
    arrange them according to their original list positions.

    Example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    if not nums:
        return []

    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return [num for idx, num in sorted(enumerate(nums), 
                                       key=lambda pair: (digit_sum(pair[1]), pair[0]))]

def differentiate(poly: str, x: int) -> int:
    # Replace '-' with '+-' to handle negative terms when splitting
    poly = poly.replace('-', '+-')
    terms = poly.split('+')

    result = 0

    for term in terms:
        # Skip empty terms
        if not term:
            continue

        # Check if term contains 'x'
        if 'x' not in term:
            # Constant term, derivative is 0
            continue

        # Find position of 'x'
        x_pos = term.index('x')
        coef_str = term[:x_pos]
        exp_str = term[x_pos + 1:]

        # Parse coefficient
        if coef_str == '' or coef_str == '+':
            coef = 1
        elif coef_str == '-':
            coef = -1
        else:
            coef = int(coef_str)

        # Parse exponent
        if exp_str == '':
            exp = 1
        elif exp_str.startswith('^'):
            exp = int(exp_str[1:])
        else:
            exp = 1

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exp == 0:
            # Constant term, derivative is 0
            continue
        else:
            # Apply power rule
            result += coef * exp * (x ** (exp - 1))

    return result

