def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds (from largest to smallest)
    units = [
        (31536000, "year", "years"),
        (86400, "day", "days"),
        (3600, "hour", "hours"),
        (60, "minute", "minutes"),
        (1, "second", "seconds")
    ]

    components = []

    for unit_seconds, singular, plural in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds %= unit_seconds
            if count == 1:
                components.append(f"{count} {singular}")
            else:
                components.append(f"{count} {plural}")

    # Format the output with proper separators
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + " and " + components[-1]

from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []

    for group in groups:
        max_depth = 0
        current_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

def largest_divisor(n):
    if n <= 0:
        raise ValueError("n must be a positive integer")
    if n == 1:
        return 1

    # Find smallest divisor greater than 1
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i

    return n  # n is prime, so no proper divisors, return 1 or n

