def cycpattern_check(a, b):
    # Check if b is longer than a
    if len(b) > len(a):
        return False

    # If b is empty, it should be considered as a substring
    if len(b) == 0:
        return True

    # Create doubled string to contain all rotations
    doubled_b = b + b

    # Check if any rotation of b exists in a
    for i in range(len(b)):
        rotation = doubled_b[i:i+len(b)]
        if rotation in a:
            return True

    return False

def amazon_check_mate(board, color):
    """
    Check if the given board position is a checkmate for the specified color.

    Args:
        board: 8x8 list of lists representing chess board (None or piece objects)
        color: 'white' or 'black' indicating which player to check

    Returns:
        bool: True if checkmate, False otherwise
    """
    def get_king_position(board, color):
        for r in range(8):
            for c in range(8):
                piece = board[r][c]
                if piece and piece.get('color') == color and piece.get('type') == 'king':
                    return (r, c)
        return None

    def is_square_attacked(board, r, c, by_color):
        # Check all possible attacking moves on square (r, c) by opponent
        for row in range(8):
            for col in range(8):
                piece = board[row][col]
                if piece and piece.get('color') == by_color:
                    if piece_in_check_attack(piece, board, (row, col), (r, c)):
                        return True
        return False

    def piece_in_check_attack(piece, board, from_pos, to_pos):
        dr = to_pos[0] - from_pos[0]
        dc = to_pos[1] - from_pos[1]
        piece_type = piece.get('type')

        if piece_type == 'pawn':
            direction = -1 if piece.get('color') == 'white' else 1
            return abs(dc) == 1 and dr == direction

        if piece_type == 'knight':
            return (abs(dr) == 2 and abs(dc) == 1) or (abs(dr) == 1 and abs(dc) == 2)

        if piece_type == 'bishop':
            if abs(dr) != abs(dc):
                return False
            return is_path_clear(board, from_pos, to_pos)

        if piece_type == 'rook':
            if dr != 0 and dc != 0:
                return False
            return is_path_clear(board, from_pos, to_pos)

        if piece_type == 'queen':
            if abs(dr) == abs(dc) or dr == 0 or dc == 0:
                return is_path_clear(board, from_pos, to_pos)
            return False

        if piece_type == 'king':
            return abs(dr) <= 1 and abs(dc) <= 1

        return False

    def is_path_clear(board, from_pos, to_pos):
        r1, c1 = from_pos
        r2, c2 = to_pos
        dr = 0 if r1 == r2 else (1 if r2 > r1 else -1)
        dc = 0 if c1 == c2 else (1 if c2 > c1 else -1)
        r, c = r1 + dr, c1 + dc
        while (r, c) != (r2, c2):
            if board[r][c] is not None:
                return False
            r += dr
            c += dc
        return True

    def generate_moves(board, color):
        moves = []
        for r in range(8):
            for c in range(8):
                piece = board[r][c]
                if piece and piece.get('color') == color:
                    piece_moves = get_piece_moves(piece, board, r, c, color)
                    moves.extend(piece_moves)
        return moves

    def get_piece_moves(piece, board, r, c, color):
        moves = []
        piece_type = piece.get('type')

        if piece_type == 'pawn':
            direction = -1 if color == 'white' else 1
            # Forward move
            nr = r + direction
            if 0 <= nr < 8 and board[nr][c] is None:
                moves.append((r, c, nr, c))
                # Double move from starting position
                start_row = 6 if color == 'white' else 1
                if r == start_row:
                    nr2 = r + 2 * direction
                    if board[nr2][c] is None:
                        moves.append((r, c, nr2, c))
            # Captures
            for dc in [-1, 1]:
                nc = c + dc
                if 0 <= nc < 8 and 0 <= nr < 8:
                    target = board[nr][nc]
                    if target and target.get('color') != color:
                        moves.append((r, c, nr, nc))

        elif piece_type == 'knight':
            for dr, dc in [(-2,-1),(-2,1),(-1,-2),(-1,2),(1,-2),(1,2),(2,-1),(2,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 8 and 0 <= nc < 8:
                    target = board[nr][nc]
                    if target is None or target.get('color') != color:
                        moves.append((r, c, nr, nc))

        elif piece_type == 'king':
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 8 and 0 <= nc < 8:
                        target = board[nr][nc]
                        if target is None or target.get('color') != color:
                            moves.append((r, c, nr, nc))

        elif piece_type in ['rook', 'bishop', 'queen']:
            directions = []
            if piece_type in ['rook', 'queen']:
                directions += [(-1,0),(1,0),(0,-1),(0,1)]
            if piece_type in ['bishop', 'queen']:
                directions += [(-1,-1),(-1,1),(1,-1),(1,1)]

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                while 0 <= nr < 8 and 0 <= nc < 8:
                    target = board[nr][nc]
                    if target is None:
                        moves.append((r, c, nr, nc))
                    elif target.get('color') != color:
                        moves.append((r, c, nr, nc))
                        break
                    else:
                        break
                    nr += dr
                    nc += dc

        return moves

    # Check if it's checkmate
    opponent = 'black' if color == 'white' else 'white'

    # 1. Find king position
    king_pos = get_king_position(board, color)
    if king_pos is None:
        return False

    # 2. Check if king is under attack (in check)
    if not is_square_attacked(board, king_pos[0], king_pos[1], opponent):
        return False

    # 3. Check if any legal move exists
    all_moves = generate_moves(board, color)
    for move in all_moves:
        r1, c1, r2, c2 = move
        # Create copy of board
        new_board = [row[:] for row in board]
        piece = new_board[r1][c1]
        new_board[r2][c2] = piece
        new_board[r1][c1] = None

        # Check if king would still be in check after this move
        new_king_pos = get_king_position(new_board, color)
        if not is_square_attacked(new_board, new_king_pos[0], new_king_pos[1], opponent):
            return False

    # No legal moves exist while in check = checkmate
    return True

from typing import List

def intersperse(numbers: List[int], delimeter: int) -> List[int]:
    if len(numbers) <= 1:
        return numbers

    result = []
    for i, num in enumerate(numbers):
        result.append(num)
        if i < len(numbers) - 1:
            result.append(delimeter)

    return result

def candies(arr):
    if len(arr) <= 1:
        return -1

    max_candies = max(arr)
    total_candies = 0

    for candy in arr:
        total_candies += max_candies - candy

    return total_candies

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds (from largest to smallest)
    units = [
        (31536000, "year", "years"),
        (86400, "day", "days"),
        (3600, "hour", "hours"),
        (60, "minute", "minutes"),
        (1, "second", "seconds")
    ]

    components = []

    for unit_seconds, singular, plural in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds %= unit_seconds
            if count == 1:
                components.append(f"{count} {singular}")
            else:
                components.append(f"{count} {plural}")

    # Format the output with proper separators
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + " and " + components[-1]

def largest_divisor(n: int) -> int:
    if n <= 1:
        return None

    if n == 2:
        return 1

    # Find the smallest prime factor
    smallest_factor = n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            smallest_factor = i
            break

    # If no factor found, n is prime, so largest divisor is 1
    if smallest_factor == n:
        return 1

    # Otherwise, largest divisor is n divided by smallest prime factor
    return n // smallest_factor

def choose(n, k):
    # Handle edge cases
    if k > n or n < 0 or k < 0:
        return 0

    # Use the more efficient iterative approach
    # to avoid computing large factorials directly
    if k > n - k:
        k = n - k  # Take advantage of symmetry

    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

