        i = 0
        current_term = ""
        while i < len(poly_str):
            if poly_str[i] in ['+', '-'] and i > 0:
                if current_term:
                    terms.append(current_term)
                terms.append(poly_str[i])
                current_term = ""
            else:
                current_term += poly_str[i]
            i += 1
        if current_term:
            terms.append(current_term)
        return terms

    # Get all terms
    terms = get_terms(polynomial)

    # Process terms
    coeffs = []
    powers = []

    i = 0
    while i < len(terms):
        term = terms[i]
        if term == '+' or term == '-':
            i += 1
            continue

        # Determine sign
        sign = 1
        if i > 0 and terms[i-1] == '-':
            sign = -1

        # Parse the term
        if 'x^' in term:
            # ax^n format
            coeff_part, power_part = term.split('x^')
            if coeff_part == '' or coeff_part == '+':
                coeff = 1
            elif coeff_part == '-':
                coeff = -1
            else:
                coeff = int(coeff_part)
            coeff *= sign
            power = int(power_part)
        elif 'x' in term:
            # ax or x format
            if term == 'x':
                coeff = 1
                power = 1
            elif term == '-x':
                coeff = -1
                power = 1
            else:
                coeff_part = term.replace('x', '')
                if coeff_part == '' or coeff_part == '+':
                    coeff = 1
                elif coeff_part == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_part)
                power = 1
            coeff *= sign
        else:
            # Constant term
            coeff = int(term)
            power = 0

        coeffs.append(coeff)
        powers.append(power)
        i += 1

    # Differentiate each term
    derivative_coeffs = []
    derivative_powers = []

    for coeff, power in zip(coeffs, powers):
        if power == 0:
            # Derivative of constant is 0
            continue
        else:
            new_coeff = power * coeff
            new_power = power - 1
            derivative_coeffs.append(new_coeff)
            derivative_powers.append(new_power)

    # Evaluate at x
    result = 0
    for coeff, power in zip(derivative_coeffs, derivative_powers):
        result += coeff * (x ** power)

    return result

