    # For even numbers, the largest divisor smaller than n is n // 2
    if n % 2 == 0:
        return n // 2

    # For odd numbers, check odd divisors from 3 up to sqrt(n)
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
