def choose(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry: C(n, k) == C(n, n - k)
    k = min(k, n - k)

    result = 1
    for i in range(k):
        # Multiply by (n - i) then divide by (i + 1)
        # Using integer division ensures we stay in integer arithmetic
        result = result * (n - i) // (i + 1)

    return result

