    return 1

import math

def is_perfect_square(n):
    if n < 0:
        return False
    root = int(math.sqrt(n))
    return root * root == n

def sum_of_squares(n):
    # Check if n is a perfect square
    if is_perfect_square(n):
        return 1

    # Check if n is a sum of two squares
    sqrt_n = int(math.sqrt(n))
    for i in range(1, sqrt_n + 1):
        remainder = n - i * i
        if is_perfect_square(remainder):
            return 2

    # Check Legendre's three-square theorem
    # Remove all factors of 4
    while n % 4 == 0:
        n //= 4

    # If n ≡ 7 (mod 8), then it requires 4 squares
    if n % 8 == 7:
        return 4

    # Otherwise, it can be represented as sum of 3 squares
    return 3

