def amazon_check_mate(king, amazon):
    # Parse chess notation to (row, col)
    def parse_pos(pos):
        col = ord(pos[0]) - ord('a')
        row = int(pos[1]) - 1
        return (row, col)

    # White pieces positions
    wk = parse_pos(king)
    wz = parse_pos(amazon)

    # Generate all squares threatened by amazon (queen + knight moves)
    def get_amazon_threats(pos):
        threats = set()
        r, c = pos

        # Queen moves (horizontal, vertical, diagonal)
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r, c
                while True:
                    nr += dr
                    nc += dc
                    if 0 <= nr < 8 and 0 <= nc < 8:
                        threats.add((nr, nc))
                    else:
                        break

        # Knight moves (L-shaped)
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
                       (1, -2), (1, 2), (2, -1), (2, 1)]
        for dr, dc in knight_moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 8 and 0 <= nc < 8:
                threats.add((nr, nc))

        return threats

    amazon_threats = get_amazon_threats(wz)

    # Check if a square is adjacent to white king (kings cannot be adjacent)
    def is_adjacent_to_wk(pos):
        r, c = pos
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if (nr, nc) == wk:
                    return True
        return False

    # Check if black king at pos has at least one legal move to a safe square
    def has_legal_move(pos):
        r, c = pos
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < 8 and 0 <= nc < 8:
                    target = (nr, nc)
                    # Cannot move to occupied squares
                    if target == wk or target == wz:
                        continue
                    # Cannot move adjacent to white king
                    if is_adjacent_to_wk(target):
                        continue
                    # Cannot move to amazon-threatened squares
                    if target in amazon_threats:
                        continue
                    # This is a valid legal move
                    return True
        return False

    # Count scenarios for each possible black king position
    checkmate = 0
    check = 0
    stalemate = 0
    normal = 0

    for r in range(8):
        for c in range(8):
            pos = (r, c)

            # Skip squares occupied by white pieces
            if pos == wk or pos == wz:
                continue

            # Skip squares adjacent to white king
            if is_adjacent_to_wk(pos):
                continue

            # Determine if under attack by amazon
            under_attack = pos in amazon_threats

            # Determine if black king has at least one legal move
            can_move = has_legal_move(pos)

            if under_attack and not can_move:
                checkmate += 1
            elif under_attack and can_move:
                check += 1
            elif not under_attack and not can_move:
                stalemate += 1
            else:
                normal += 1

    return [checkmate, check, stalemate, normal]

