                id_count += 1
            # Count class selectors (.class)
            elif part.startswith('.'):
                class_count += 1
            # Count tag name selectors (tag)
            else:
                tagname_count += 1

        return (id_count, class_count, tagname_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    if spec1 > spec2:
        return selector1
    else:
        return selector2

import math

def converter(number, base, decimals=0):
    """
    Converts a base 10 number to a given base.

    Args:
        number (int|float|str): The number to convert
        base (int|float|str): The base to convert to (must be >= 2)
        decimals (int): Number of decimal places in the result

    Returns:
        str: String representation of the converted number
    """
    # Parse inputs
    try:
        num = float(number)
        base_val = float(base)
    except (ValueError, TypeError):
        raise ValueError("Invalid number or base")

    if base_val < 2:
        raise ValueError("Base must be >= 2")

    # Handle sign
    sign = ''
    if num < 0:
        sign = '-'
        num = abs(num)

    # Handle zero
    if num == 0:
        if decimals > 0:
            return '0.' + '0' * decimals
        return '0'

    # Separate integer and fractional parts
    integer_part = int(num)
    fractional_part = num - integer_part

    # Convert integer part
    int_str = _integer_to_base(integer_part, base_val)

    # Convert fractional part if needed
    frac_str = ''
    if decimals > 0:
        frac_str = _fractional_to_base(fractional_part, base_val, decimals)

    # Assemble result
    if decimals > 0:
        return sign + int_str + '.' + frac_str
    else:
        return sign + int_str


def _integer_to_base(n, base):
    """Convert integer part to given base."""
    if n == 0:
        return '0'

    digits = []
    while n > 0:
        # Use integer division for standard base conversion
        n, remainder = divmod(n, int(base))
        digits.append(_digit_to_char(remainder))

    return ''.join(reversed(digits))


def _fractional_to_base(frac, base, count):
    """Convert fractional part to given base."""
    digits = []
    for _ in range(count):
        frac *= base
        digit = int(frac)
        frac -= digit
        digits.append(_digit_to_char(digit))

    return ''.join(digits)


def _digit_to_char(d):
    """Convert digit value to character."""
    if 0 <= d < 10:
        return str(d)
    elif 10 <= d < 36:
        return chr(ord('A') + d - 10)
    else:
        return '?'  # For digits beyond base 36

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Handle empty string case
    if not test:
        return {}

    # Split the string into individual letters
    letters = test.split()

    # Count occurrences of each letter
    letter_counts = {}
    for letter in letters:
