def differentiate(polynomial, x):
    # Split the polynomial into terms
    # Handle the case where the polynomial starts with a negative term
    if polynomial[0] == '-':
        terms = ['-']
        polynomial = polynomial[1:]
    else:
        terms = []

    # Split by '+' and handle '-' as a separator
    current_term = ""
    for i, char in enumerate(polynomial):
        if char == '+' or char == '-':
            if current_term:
                terms.append(current_term)
            if char == '-':
                current_term = '-'
            else:
                current_term = ''
        else:
            current_term += char
    if current_term:
        terms.append(current_term)

    # Process each term
    derivative_sum = 0

    for term in terms:
        if term == '':
            continue

        # Handle the sign
        if term[0] == '-':
            sign = -1
            term = term[1:]
        else:
            sign = 1

        # Parse the term
        if 'x^' in term:
            # Format: ax^n
            coeff_part, exp_part = term.split('x^')
            coefficient = int(coeff_part) if coeff_part else 1
            exponent = int(exp_part)
        elif 'x' in term:
            # Format: ax or a (where a is the coefficient)
            if term == 'x':
                coefficient = 1
                exponent = 1
            else:
                coeff_part = term[:-1]  # Remove 'x'
                coefficient = int(coeff_part) if coeff_part != '-' else -1
                exponent = 1
        else:
            # Format: constant
            coefficient = int(term)
            exponent = 0

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent == 0:
            # Derivative of a constant is 0
            derivative = 0
        else:
            derivative = coefficient * exponent * (x ** (exponent - 1))

        derivative_sum += sign * derivative

    return derivative_sum

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    result = []

    if integer_part == 0:
        result = ['0']
    else:
        while integer_part > 0:
            remainder = integer_part % int(base)
            result.append(get_digit(remainder))
            integer_part //= int(base)
        result.reverse()

    # Handle fractional part
    fractional_part = number - int(number)
    if decimals > 0:
        result.append('.')
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            result.append(get_digit(digit))
            fractional_part -= digit

    # Join the result
    final_result = ''.join(result)

    # Add negative sign if needed
    if negative:
        final_result = '-' + final_result

    return final_result

def get_digit(value):
    if value < 10:
        return str(value)
    else:
        return chr(ord('A') + value - 10)

def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def coords_to_chess(x, y):
        return chr(ord('a') + x) + str(y + 1)

    def is_valid(x, y):
        return 0 <= x < 8 and 0 <= y < 8

    def is_adjacent(x1, y1, x2, y2):
        return abs(x1 - x2) <= 1 and abs(y1 - y2) <= 1

    def amazon_attacks(x, y, amazon_x, amazon_y):
        # Check if amazon attacks position (x, y)
        # Queen moves (rook + bishop)
        if amazon_x == x or amazon_y == y or abs(amazon_x - x) == abs(amazon_y - y):
            # Check if there's a piece blocking the path
            if amazon_x == x:
                # Vertical attack
                step_y = 1 if y > amazon_y else -1
                for i in range(1, abs(y - amazon_y)):
                    if is_valid(amazon_x, amazon_y + i * step_y):
                        # Check if any piece is blocking
                        pass
            elif amazon_y == y:
                # Horizontal attack
                step_x = 1 if x > amazon_x else -1
                for i in range(1, abs(x - amazon_x)):
                    if is_valid(amazon_x + i * step_x, amazon_y):
                        # Check if any piece is blocking
                        pass
            else:
                # Diagonal attack
                step_x = 1 if x > amazon_x else -1
                step_y = 1 if y > amazon_y else -1
                for i in range(1, abs(x - amazon_x)):
                    if is_valid(amazon_x + i * step_x, amazon_y + i * step_y):
                        # Check if any piece is blocking
                        pass
            return True

        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            if x == amazon_x + dx and y == amazon_y + dy:
                return True
        return False

    def get_king_moves(x, y):
        moves = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny):
                    moves.append((nx, ny))
        return moves

    def get_all_positions():
        positions = []
        for x in range(8):
            for y in range(8):
                positions.append((x, y))
        return positions

    king_x, king_y = chess_to_coords(king)
    amazon_x, amazon_y = chess_to_coords(amazon)

    # Precompute all positions that amazon attacks
    attacks = set()
    for x in range(8):
        for y in range(8):
            if amazon_attacks(x, y, amazon_x, amazon_y):
                attacks.add((x, y))

    # Get all valid positions for black king
    all_positions = get_all_positions()

    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    for x, y in all_positions:
        # Skip if king is adjacent to white king
        if is_adjacent(x, y, king_x, king_y):
            continue

        # Skip if position is attacked by amazon
        if (x, y) in attacks:
            # Check if king can escape
            king_moves = get_king_moves(x, y)
            can_escape = False
            for nx, ny in king_moves:
                # Check if escape square is valid (not adjacent to white king, not attacked)
                if not is_adjacent(nx, ny, king_x, king_y) and (nx, ny) not in attacks:
                    can_escape = True
                    break

            if can_escape:
                check += 1
            else:
                checkmate += 1
        else:
            # King is safe
            king_moves = get_king_moves(x, y)
            can_move = False
            for nx, ny in king_moves:
                # Check if move is valid (not adjacent to white king, not attacked)
                if not is_adjacent(nx, ny, king_x, king_y) and (nx, ny) not in attacks:
                    can_move = True
                    break

            if can_move:
                safe += 1
            else:
                stalemate += 1

    return [checkmate, check, stalemate, safe]

def vowels_count(s):
    if not s:
        return 0

    vowels = set('aeiou')
    count = 0

    # Check each character in the string
    for i, char in enumerate(s.lower()):
        # If character is a regular vowel
        if char in vowels:
            count += 1
        # If character is 'y' and it's at the end of the string
        elif char == 'y' and i == len(s) - 1:
