    return count

def parse_int(s):
    if not s:
        return 0

    # Define mappings
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14,
        'fifteen': 15, 'sixteen': 16, 'seventeen': 17, 'eighteen': 18,
        'nineteen': 19, 'twenty': 20, 'thirty': 30, 'forty': 40,
        'fifty': 50, 'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    scale_words = {
        'hundred': 100,
        'thousand': 1000,
        'million': 1000000
    }

    # Split the string into words, handling hyphens
    words = s.replace('-', ' ').split()

    # Remove 'and' words
    words = [word for word in words if word != 'and']

    # Process words
    total = 0
    current = 0

    for word in words:
        if word in word_to_num:
            current += word_to_num[word]
        elif word in scale_words:
            if word == 'hundred':
                current *= scale_words[word]
            else:
                total += current * scale_words[word]
                current = 0

    total += current
    return total

def exchange_sort(sequence):
    if len(sequence) <= 1:
        return 0

    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for val in sequence:
        count[val] += 1

    # Create target sorted sequence
    target = []
    target.extend([7] * count[7])
    target.extend([8] * count[8])
    target.extend([9] * count[9])

    # Create a mapping from value to its target positions
    # We'll track where each element should go
    pos_map = {}
    for i, val in enumerate(sequence):
        if val not in pos_map:
            pos_map[val] = []
        pos_map[val].append(i)

    # Create a visited array to track which positions we've processed
    visited = [False] * len(sequence)
    cycles = 0

    # Find cycles in the permutation
    for i in range(len(sequence)):
        if visited[i] or sequence[i] == target[i]:
            continue

        # Start a new cycle
        cycle_length = 0
        current = i

        while not visited[current]:
            visited[current] = True
            # Find where the current element should go
            target_val = sequence[current]
            # Find the next position where this value appears in the target
            next_pos = -1
            for j in range(len(target)):
                if target[j] == target_val and not visited[j]:
                    next_pos = j
                    break
            if next_pos == -1:
                # If we can't find an unvisited position, look for any position
                for j in range(len(target)):
                    if target[j] == target_val:
                        next_pos = j
                        break

            current = next_pos
            cycle_length += 1

        if cycle_length > 0:
            cycles += 1

    # Actually, let's use a cleaner approach
    # Create a mapping from current positions to target positions
    # and count cycles properly

    # Create a mapping of what each position should contain
    pos_to_val = {}
    for i, val in enumerate(sequence):
        pos_to_val[i] = val

    # Create target positions mapping
    target_positions = {}
    pos = 0
    for val in [7, 8, 9]:
        for i in range(count[val]):
            target_positions[pos] = val
            pos += 1

    # Create a mapping from current value to where it should be
    # and track positions
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if visited[i]:
            continue

        if sequence[i] == target[i]:
            continue

        # Start a cycle
        cycle_length = 0
        current = i

        while not visited[current]:
            visited[current] = True
            # Find where this element should go
            target_val = sequence[current]
            # Find first position where this value should be in target
            target_pos = -1
            for j in range(len(target)):
                if target[j] == target_val and not visited[j]:
                    target_pos = j
                    break

            if target_pos == -1:
                # If no unvisited position, find any
                for j in range(len(target)):
                    if target[j] == target_val:
                        target_pos = j
                        break

            current = target_pos
            cycle_length += 1

        if cycle_length > 1:
            cycles += 1

    # Simpler approach: just count the number of swaps needed
    # Create target array
    target = []
    target.extend([7] * count[7])
    target.extend([8] * count[8])
    target.extend([9] * count[9])

    # Create mapping of current to target positions
    visited = [False] * len(sequence)
    swaps = 0

    for i in range(len(sequence)):
        if visited[i]:
            continue

        if sequence[i] == target[i]:
            continue

        # Find the cycle
        cycle_length = 0
        current = i

        while not visited[current]:
            visited[current] = True
            # Find where sequence[current] should be in the target
            val = sequence[current]
            # Find the first position in target where val should be
            target_pos = -1
            for j in range(len(target)):
                if target[j] == val and not visited[j]:
                    target_pos = j
                    break

            if target_pos == -1:
                # Find any position where val should be
                for j in range(len(target)):
                    if target[j] == val:
                        target_pos = j
                        break

            current = target_pos
            cycle_length += 1

        # For a cycle of length n, we need (n-1) swaps
        if cycle_length > 1:
            swaps += cycle_length - 1

    return swaps

def getAllPrimeFactors(n):
    # Error handling
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Special cases
    if n == 1:
        return [1]
    if n == 2:
        return [2]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Error handling
    if not isinstance(n, int):
        return [[], []]
    if n <= 0:
        return [[], []]

    # Special cases
    if n == 1:
        return [[1], [1]]
    if n == 2:
        return [[2], [1]]

    factors = getAllPrimeFactors(n)

    if not factors:
        return [[], []]

    unique_factors = []
    counts = []

    current_factor = factors[0]
    count = 0

    for factor in factors:
        if factor == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factor
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Error handling
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Special cases
    if n == 1:
        return [1]
    if n == 2:
        return [2]

    factor_count_pairs = getUniquePrimeFactorsWithCount(n)
    unique_factors = factor_count_pairs[0]
    counts = factor_count_pairs[1]

    products = []

    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    i = 2

    while i * i <= d:
        if d % i == 0:
            result -= result // i
            while d % i == 0:
                d //= i
        i += 1

    if d > 1:
        result -= result // d

    return result

def check_if_last_char_is_a_letter(txt):
    # Handle empty string
    if not txt:
        return False

    # Check if the last character is an alphabetical letter
    if not txt[-1].isalpha():
        return False

    # If the string has only one character and it's a letter, it's standalone
    if len(txt) == 1:
        return True

    # Check if the character before the last one is a space
