def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Constants for time units in seconds
    # Year = 365 days, Day = 24 hours
    units = [
        (365 * 24 * 60 * 60, "year"),
        (24 * 60 * 60, "day"),
        (60 * 60, "hour"),
        (60, "minute"),
        (1, "second")
    ]

    parts = []

    for unit_seconds, unit_name in units:
        count = seconds // unit_seconds
        if count > 0:
            seconds %= unit_seconds
            suffix = "s" if count > 1 else ""
            parts.append(f"{count} {unit_name}{suffix}")

        # Optimization: if remaining seconds is 0, we can stop processing
        if seconds == 0:
            break

    if len(parts) == 1:
        return parts[0]
    elif len(parts) == 2:
        return f"{parts[0]} and {parts[1]}"
    else:
        return ", ".join(parts[:-1]) + " and " + parts[-1]

def fib4(n):
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Initialize the base cases for iteration
    a, b, c, d = 0, 0, 2, 0  # fib4(0), fib4(1), fib4(2), fib4(3)

    for i in range(4, n + 1):
        # Calculate fib4(i) as the sum of the previous 4 values
        next_val = a + b + c + d

        # Shift values forward: discard oldest, add new value
        a, b, c, d = b, c, d, next_val

    return d

