def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    # Split by spaces to get individual characters
    letters = test.split()

    if not letters:
        return {}

    # Count frequency of each letter
    freq = {}
    for letter in letters:
        freq[letter] = freq.get(letter, 0) + 1

    # Find maximum frequency
    max_count = max(freq.values())

    # Filter letters with maximum frequency
    result = {letter: count for letter, count in freq.items() if count == max_count}

    return result

def compare(selector1, selector2):
    def get_specificity(selector):
        id_count = 0
        class_count = 0
        tagname_count = 0

        # Split by spaces to handle compound selectors
        parts = selector.split()

        for part in parts:
            # Count ID selectors (#id)
            if part.startswith('#'):
                id_count += 1
            # Count class selectors (.class)
            elif part.startswith('.'):
                class_count += 1
            # Count tag name selectors (tag)
            else:
                tagname_count += 1

        return (id_count, class_count, tagname_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    if spec1 > spec2:
        return selector1
    else:
        return selector2

