    return result

def sum_of_squares(n):
    # Step 1: Check if n is a perfect square
    root = int(n**0.5)
    if root * root == n:
        return 1

    # Step 2: Check if n is sum of two perfect squares
    for i in range(1, root + 1):
        remainder = n - i * i
        root2 = int(remainder**0.5)
        if root2 * root2 == remainder:
            return 2

    # Step 3: Apply Legendre's three-square theorem
    # A number n can be expressed as sum of 3 squares iff n is not of form 4^a(8b + 7)
    temp = n
    while temp % 4 == 0:
        temp //= 4

    if temp % 8 == 7:
        return 4

    # Step 4: By Lagrange's four-square theorem and elimination, must be 3
    return 3

