def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2

    # Check for factor 2
    if d % p == 0:
        while d % p == 0:
            d //= p
        result -= result // p

    # Check for odd factors from 3 onwards
    p = 3
    while p * p <= d:
        if d % p == 0:
            while d % p == 0:
                d //= p
            result -= result // p
        p += 2

    # If d is a prime number greater than 2
    if d > 1:
        result -= result // d

    return result

def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    # Handle empty strings
    if not a and not b:
        return ""
    if not a:
        return b
    if not b:
        return a

    # Check if lengths are equal
    if len(a) != len(b):
        raise ValueError("Input strings must have equal length")

    # Perform XOR operation bit by bit
    result = ""
    for i in range(len(a)):
        # XOR: same bits give 0, different bits give 1
        if a[i] == b[i]:
            result += "0"
        else:
            result += "1"

    return result

