def is_balanced(s, pairs):
    # Create mapping from opening to closing characters
    pair_map = {}
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        pair_map[opening] = closing

    # Stack to track opening characters
    stack = []

    # Process each character in the string
    for char in s:
        # If it's an opening character, push to stack
        if char in pair_map:
            stack.append(char)
        # If it's a closing character
        elif char in pair_map.values():
            # If stack is empty or doesn't match, it's unbalanced
            if not stack or pair_map[stack.pop()] != char:
                return False

    # String is balanced if stack is empty
    return len(stack) == 0

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part to given base
    if integer_part == 0:
        integer_result = '0'
    else:
        digits = []
        n = integer_part
        while n > 0:
            remainder = n % base
            # Adjust for negative remainders
            if remainder < 0:
                remainder += base
                n = (n - remainder) // base - 1
            else:
                n = (n - remainder) // base
            digits.append(remainder)

        # Convert to proper digit representation
        integer_result = ''
        for digit in reversed(digits):
            if digit < 10:
                integer_result += str(int(digit))
            else:
                integer_result += chr(ord('A') + int(digit) - 10)

    # Convert fractional part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            if digit < 10:
                fractional_result += str(digit)
            else:
                fractional_result += chr(ord('A') + digit - 10)
            fractional_part -= digit

    # Combine results
    result = integer_result + fractional_result

    # Handle negative sign
    if negative:
        result = '-' + result

    # Handle case where result is less than 1 and needs leading zero
    if result.startswith('.'):
        result = '0' + result

    return result

