def main():
    data = sys.stdin.read()
    tokens = data.split()
    ptr = 0

    k = int(tokens[ptr])
    ptr += 1
    q = int(tokens[ptr])
    ptr += 1

    queries = []
    for i in range(q):
        queries.append(int(tokens[ptr]))
        ptr += 1

    # Precompute binomial coefficients C[n][r]
    C = [[0] * (k + 1) for _ in range(k + 1)]
    for i in range(k + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = C[i-1][j-1] + C[i-1][j]

    def probability(n):
        """Compute P(all k types collected in n days) using inclusion-exclusion"""
        result = 0.0
        for j in range(k + 1):
            if k - j == 0:
                if n == 0:
                    term = C[k][j] * 1.0
                else:
                    term = 0.0
            else:
                base = (k - j) / k
                term = C[k][j] * (base ** n)

            if j % 2 == 1:
                result -= term
            else:
                result += term

        # Clamp to [0, 1] for numerical stability
        return max(0.0, min(1.0, result))

    eps = 1e-8
    results = []

    for p in queries:
        threshold = (p - eps) / 2000.0

        # Binary search for minimum n
        # Lower bound: need at least k days to collect k different types
        # Upper bound: safe large number covering all cases
        left, right = k, 10_000_000
        answer = right

        while left <= right:
            mid = (left + right) // 2
            if probability(mid) >= threshold:
                answer = mid
                right = mid - 1
            else:
                left = mid + 1

        results.append(answer)

    for r in results:
        print(r)

