def largest_divisor(n: int) -> int:
    if n <= 1:
        return None

    # Find the smallest prime factor
    smallest_factor = n

    # Check for factor 2
    if n % 2 == 0:
        smallest_factor = 2
    else:
        # Check odd factors from 3 onwards
        i = 3
        while i * i <= n:
            if n % i == 0:
                smallest_factor = i
                break
            i += 2

    # If no factor found, n is prime, so largest proper divisor is 1
    if smallest_factor == n:
        return 1

    return n // smallest_factor

def proper_fractions(n):
    if n == 1:
        return 0

    result = n

    # Check for factor 2
    if n % 2 == 0:
        result //= 2
        while n % 2 == 0:
            n //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result = result - result // i
            while n % i == 0:
                n //= i
        i += 2

    # If n is a prime factor greater than 2
    if n > 1:
        result = result - result // n

    return result

