        cut_index = len(line)

        # Find the first occurrence of any marker in the current line
        for marker in markers:
            index = line.find(marker)
            if index != -1:
                # We want the earliest marker occurrence to strip everything following it
                if index < cut_index:
                    cut_index = index

        # Truncate the line at the marker position and strip trailing whitespace
        cleaned_line = line[:cut_index].rstrip()
        result_lines.append(cleaned_line)

    # Join the processed lines back together
    return '\n'.join(result_lines)

from typing import List, Tuple


def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    if not numbers:
        return (0, 1)

    total_sum = sum(numbers)

    product = 1
    for num in numbers:
        product *= num

    return (total_sum, product)

def compare(selector1, selector2):
    def get_specificity(selector):
        # Count ID selectors (#)
        id_count = selector.count('#')

        # Count class selectors (.)
        class_count = selector.count('.')

        # Count tag name selectors (elements without # or .)
        # We need to be careful about elements that are part of compound selectors
        # Split by spaces and then by # and . to count elements properly
        elements = []
        parts = selector.split()
        for part in parts:
            # Remove any # or . from the part to count pure elements
            clean_part = ''.join(c for c in part if c not in '#.')
            if clean_part and clean_part != '*':
                elements.append(clean_part)

        # Count tag names (elements that are not # or .)
        tag_count = 0
        for part in selector.split():
            # Count pure tag names (no # or .)
            if part and part != '*' and not part.startswith('#') and not part.startswith('.'):
                tag_count += 1
            else:
                # If it's a compound like div#id or div.class, count the tag
                if '#' in part or '.' in part:
                    # Split by # and . to find the tag name
                    clean_part = part
                    if '#' in part:
                        clean_part = part.split('#')[0]
                    if '.' in clean_part:
                        clean_part = clean_part.split('.')[0]
                    if clean_part and clean_part != '*':
                        tag_count += 1
                elif part != '*':
                    tag_count += 1

        # More precise counting of tag names
        tag_count = 0
        for part in selector.split():
            if part == '*':
                continue
            # Check if part is a tag name (not an ID or class)
            if part.startswith('#') or part.startswith('.'):
                # If it's a compound selector like div#id or div.class
                if '#' in part:
                    tag_part = part.split('#')[0]
                elif '.' in part:
                    tag_part = part.split('.')[0]
                else:
                    tag_part = ''
                if tag_part and tag_part != '*':
                    tag_count += 1
            else:
                tag_count += 1

        # Simpler and more accurate approach
        # Count ID selectors
        id_count = selector.count('#')

        # Count class selectors
        class_count = selector.count('.')

        # Count tag selectors (elements without # or .)
        tag_count = 0
        # Split by spaces to get individual parts
        parts = selector.split()
        for part in parts:
            # If part contains # or ., we need to extract the tag
            if '#' in part or '.' in part:
                # Split by # first, then by . to get the tag part
                tag_part = part
                if '#' in tag_part:
                    tag_part = tag_part.split('#')[0]
                if '.' in tag_part:
                    tag_part = tag_part.split('.')[0]
                if tag_part and tag_part != '*':
                    tag_count += 1
            elif part != '*':
                tag_count += 1

        return (id_count, class_count, tag_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    if spec1 > spec2:
        return selector1
    else:
        return selector2

import sys
from collections import defaultdict

def parse_url(url):
    # Remove "http://"
    url = url[7:]

    # Split by first slash to get hostname and path
    if '/' in url:
        hostname, path = url.split('/', 1)
        # If path is empty after splitting, it means the URL was like http://host/
        # We need to distinguish this from http://host
        if not path:
            return hostname, set([''])
        else:
            # Split path into components and create a set
            path_components = path.split('/')
            return hostname, set(path_components)
    else:
        # No path, just hostname
        return url, set()

def main():
    data = sys.stdin.read()
    lines = data.strip().split('\n')

    n = int(lines[0])
    queries = lines[1:n+1]

    # Dictionary to store hostname -> set of paths
    hostname_to_paths = defaultdict(set)

    # Process each query
    for query in queries:
        hostname, path_set = parse_url(query)
        hostname_to_paths[hostname].update(path_set)

    # Group hostnames by their path sets
    signature_to_hostnames = defaultdict(list)

    for hostname, path_set in hostname_to_paths.items():
        # Convert set to tuple so it can be used as a dictionary key
        signature = tuple(sorted(path_set))
        signature_to_hostnames[signature].append(hostname)

    # Filter groups with more than one hostname
    result_groups = []
    for group in signature_to_hostnames.values():
        if len(group) > 1:
            result_groups.append(sorted(group))

    # Sort groups lexicographically
    result_groups.sort()

    # Output
    print(len(result_groups))
    for group in result_groups:
        print(' '.join(group))

if __name__ == "__main__":
    main()

def file_name_check(file_name):
    # Check if there is exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    # Split the file name into prefix and suffix
    prefix, suffix = file_name.split('.')

    # Check if prefix is not empty
    if not prefix:
        return 'No'

    # Check if prefix starts with a letter
    if not prefix[0].isalpha():
        return 'No'

    # Check if suffix is one of the allowed extensions
    if suffix not in ['txt', 'exe', 'dll']:
        return 'No'

    # Count digits in the entire file name
    digit_count = sum(1 for char in file_name if char.isdigit())
    if digit_count > 3:
        return 'No'

    return 'Yes'

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, value) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract just the values from the sorted pairs
    return [num for _, _, num in indexed_nums]

def differentiate(polynomial, x_value):
    def parse_term(term):
        """Parse a term to extract coefficient and exponent."""
        if 'x' not in term:
            # Constant term
            try:
                return int(term), 0
            except ValueError:
                return 0, 0

        # Split around 'x'
        x_pos = term.find('x')
        coeff_str = term[:x_pos]
        exp_str = term[x_pos + 1:]

        # Parse coefficient
        if coeff_str == '' or coeff_str == '+':
            coefficient = 1
        elif coeff_str == '-':
            coefficient = -1
        else:
            try:
                coefficient = int(coeff_str)
            except ValueError:
                coefficient = 0

        # Parse exponent
        if exp_str == '':
            exponent = 1
        elif exp_str.startswith('^'):
            exponent = int(exp_str[1:])
        else:
            exponent = 1

        return coefficient, exponent

    # Split polynomial into terms
    # We need to split by + or - but keep the sign with each term
    import re

    # Use regex to find all terms including their signs
    terms = re.findall(r'[+-]?[^+-]+', polynomial)

    # Remove empty strings if any
    terms = [t for t in terms if t.strip()]

    # Calculate derivative value
    derivative_value = 0

    for term in terms:
        coefficient, exponent = parse_term(term)

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent == 0:
            # Derivative of constant is 0
            continue
        else:
            new_coefficient = exponent * coefficient
            new_exponent = exponent - 1

            if new_exponent == 0:
                derivative_value += new_coefficient
            else:
                derivative_value += new_coefficient * (x_value ** new_exponent)

    return derivative_value

def sum_of_squares(n):
    # Check if n is a perfect square (1 square needed)
    root = int(n ** 0.5)
    if root * root == n:
        return 1

    # Check if n is sum of 2 squares
    for i in range(1, root + 1):
        i_sq = i * i
        if i_sq >= n:
            break
        remainder = n - i_sq
        j = int(remainder ** 0.5)
        if j * j == remainder:
            return 2

    # Check Legendre's three-square theorem
    # n cannot be represented as sum of 3 squares if n = 4^a(8b + 7)
    temp = n
    while temp % 4 == 0:
        temp //= 4
    if temp % 8 == 7:
        return 4

    return 3

def next_smallest(lst):
    if len(lst) < 2:
        return None

    smallest = float('inf')
    second_smallest = float('inf')

    for num in lst:
        if num < smallest:
            second_smallest = smallest
            smallest = num
        elif num < second_smallest and num != smallest:
            second_smallest = num

    return second_smallest if second_smallest != float('inf') else None

