def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """

    def normalize(value):
        """Convert a value to float for comparison"""
        if isinstance(value, (int, float)):
            return float(value)
        elif isinstance(value, str):
            # Handle comma as decimal separator
            normalized_str = value.replace(',', '.')
            return float(normalized_str)
        else:
            raise TypeError("Unsupported type for comparison")

    # Normalize both values for comparison
    normalized_a = normalize(a)
    normalized_b = normalize(b)

    # Compare normalized values
    if normalized_a > normalized_b:
        return a
    elif normalized_b > normalized_a:
        return b
    else:
        return None

def solution(input_str, markers):
    lines = input_str.split('\n')
    result_lines = []

    for line in lines:
        # Find the position of the first occurrence of any marker
        first_marker_pos = len(line)  # Initialize to end of line
        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < first_marker_pos:
                first_marker_pos = pos

        # If a marker was found, truncate the line at that position
        if first_marker_pos < len(line):
            processed_line = line[:first_marker_pos]
        else:
            processed_line = line

        # Strip trailing whitespace
        processed_line = processed_line.rstrip()
        result_lines.append(processed_line)

    return '\n'.join(result_lines)

def proper_fractions(n):
    if n == 1:
        return 0

    result = n
    p = 2

    # Check for factor 2
    if n % p == 0:
        while n % p == 0:
            n //= p
        result -= result // p

    # Check for odd prime factors from 3 to sqrt(n)
    p = 3
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 2

    # If n > 1, the remaining n is a prime factor
    if n > 1:
        result -= result // n

    return result

def getAllPrimeFactors(n):
    # Error handling
    if not isinstance(n, (int, float)):
        return []
    if isinstance(n, float) and not n.is_integer():
        return []
    if n < 0 or n == 0:
        return []

    n = int(n)

    if n == 1:
        return [1]

    factors = []
    temp = n

    # Divide by 2 first
    d = 2
    while temp % d == 0:
        factors.append(d)
        temp //= d

    # Check odd divisors
    d = 3
    while d * d <= temp:
        while temp % d == 0:
            factors.append(d)
            temp //= d
        d += 2

    # If temp > 1, it's a prime factor
    if temp > 1:
        factors.append(temp)

    return factors


