    if n == 1:
        return [1]
    if n == 2:
        return [2]

    primes = []
    counts = []
    divisor = 2

    while divisor * divisor <= n:
        if n % divisor == 0:
            primes.append(divisor)
            count = 0
            while n % divisor == 0:
                n //= divisor
                count += 1
            counts.append(count)
        divisor += 1

    if n > 1:
        primes.append(n)
        counts.append(1)

    products = []
    for i in range(len(primes)):
        products.append(primes[i] ** counts[i])

    return products

