def get_closest_vowel(word):
    if len(word) < 3:
        return ""

    vowels = set('aeiouAEIOU')

    # Iterate from right to left, excluding the last character
    for i in range(len(word) - 2, 0, -1):
        # Check if current character is a vowel
        if word[i] in vowels:
            # Check if left neighbor is a consonant
            if word[i-1] not in vowels:
                # Check if right neighbor is a consonant
                if word[i+1] not in vowels:
                    return word[i]

    return ""

def count_up_to(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    primes = []
    for num in range(2, n):
        if is_prime(num):
            primes.append(num)

    return primes

def is_valid(identifier):
