    first_char = identifier[0]
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Check if all remaining characters are valid
    for char in identifier[1:]:
        if not (char.isalnum() or char == '_' or char == '$'):
