def string_xor(s: str, t: str) -> str:
    """
    Returns the bitwise XOR of two binary strings of equal length.

    Args:
        s (str): First binary string.
        t (str): Second binary string.

    Returns:
        str: Binary string resulting from XOR operation.
    """
    if len(s) != len(t):
        raise ValueError("Input strings must be of equal length.")

    result = []
    for char_s, char_t in zip(s, t):
        if char_s == char_t:
            result.append('0')
        else:
            result.append('1')

    return ''.join(result)

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def to_float(val):
        if isinstance(val, (int, float)):
            return float(val)
        elif isinstance(val, str):
            # Replace comma with dot for decimal separator
            val = val.replace(',', '.')
            return float(val)
        else:
            raise ValueError("Unsupported type")

    a_float = to_float(a)
    b_float = to_float(b)

    if a_float > b_float:
        return a
    elif b_float > a_float:
        return b
    else:
        return None

def amazon_check_mate(board, color):
    """
    Check if the given board position is a checkmate for the specified color.

    Args:
        board: 8x8 list of lists representing chess board (None or piece objects)
        color: 'white' or 'black' indicating which player to check

    Returns:
        bool: True if checkmate, False otherwise
    """
    def get_king_position(board, color):
        for r in range(8):
            for c in range(8):
                piece = board[r][c]
                if piece and piece.get('color') == color and piece.get('type') == 'king':
                    return (r, c)
        return None

    def is_square_attacked(board, r, c, by_color):
        # Check all possible attacking moves on square (r, c) by opponent
        for row in range(8):
            for col in range(8):
                piece = board[row][col]
                if piece and piece.get('color') == by_color:
                    if piece_in_check_attack(piece, board, (row, col), (r, c)):
                        return True
        return False

    def piece_in_check_attack(piece, board, from_pos, to_pos):
        dr = to_pos[0] - from_pos[0]
        dc = to_pos[1] - from_pos[1]
        piece_type = piece.get('type')

        if piece_type == 'pawn':
            direction = -1 if piece.get('color') == 'white' else 1
            return abs(dc) == 1 and dr == direction

        if piece_type == 'knight':
            return (abs(dr) == 2 and abs(dc) == 1) or (abs(dr) == 1 and abs(dc) == 2)

        if piece_type == 'bishop':
            if abs(dr) != abs(dc):
                return False
            return is_path_clear(board, from_pos, to_pos)

        if piece_type == 'rook':
            if dr != 0 and dc != 0:
                return False
            return is_path_clear(board, from_pos, to_pos)

        if piece_type == 'queen':
            if abs(dr) == abs(dc) or dr == 0 or dc == 0:
                return is_path_clear(board, from_pos, to_pos)
            return False

        if piece_type == 'king':
            return abs(dr) <= 1 and abs(dc) <= 1

        return False

    def is_path_clear(board, from_pos, to_pos):
        r1, c1 = from_pos
        r2, c2 = to_pos
        dr = 0 if r1 == r2 else (1 if r2 > r1 else -1)
        dc = 0 if c1 == c2 else (1 if c2 > c1 else -1)
        r, c = r1 + dr, c1 + dc
        while (r, c) != (r2, c2):
            if board[r][c] is not None:
                return False
            r += dr
            c += dc
        return True

    def generate_moves(board, color):
        moves = []
        for r in range(8):
            for c in range(8):
                piece = board[r][c]
                if piece and piece.get('color') == color:
                    piece_moves = get_piece_moves(piece, board, r, c, color)
                    moves.extend(piece_moves)
        return moves

    def get_piece_moves(piece, board, r, c, color):
        moves = []
        piece_type = piece.get('type')

        if piece_type == 'pawn':
            direction = -1 if color == 'white' else 1
            # Forward move
            nr = r + direction
            if 0 <= nr < 8 and board[nr][c] is None:
                moves.append((r, c, nr, c))
                # Double move from starting position
                start_row = 6 if color == 'white' else 1
                if r == start_row:
                    nr2 = r + 2 * direction
                    if board[nr2][c] is None:
                        moves.append((r, c, nr2, c))
            # Captures
            for dc in [-1, 1]:
                nc = c + dc
                if 0 <= nc < 8 and 0 <= nr < 8:
                    target = board[nr][nc]
                    if target and target.get('color') != color:
                        moves.append((r, c, nr, nc))

        elif piece_type == 'knight':
            for dr, dc in [(-2,-1),(-2,1),(-1,-2),(-1,2),(1,-2),(1,2),(2,-1),(2,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 8 and 0 <= nc < 8:
                    target = board[nr][nc]
                    if target is None or target.get('color') != color:
                        moves.append((r, c, nr, nc))

        elif piece_type == 'king':
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 8 and 0 <= nc < 8:
                        target = board[nr][nc]
                        if target is None or target.get('color') != color:
                            moves.append((r, c, nr, nc))

        elif piece_type in ['rook', 'bishop', 'queen']:
            directions = []
            if piece_type in ['rook', 'queen']:
                directions += [(-1,0),(1,0),(0,-1),(0,1)]
            if piece_type in ['bishop', 'queen']:
                directions += [(-1,-1),(-1,1),(1,-1),(1,1)]

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                while 0 <= nr < 8 and 0 <= nc < 8:
                    target = board[nr][nc]
                    if target is None:
                        moves.append((r, c, nr, nc))
                    elif target.get('color') != color:
                        moves.append((r, c, nr, nc))
                        break
                    else:
                        break
                    nr += dr
                    nc += dc

        return moves

    # Check if it's checkmate
    opponent = 'black' if color == 'white' else 'white'

    # 1. Find king position
    king_pos = get_king_position(board, color)
    if king_pos is None:
        return False

    # 2. Check if king is under attack (in check)
    if not is_square_attacked(board, king_pos[0], king_pos[1], opponent):
        return False

    # 3. Check if any legal move exists
    all_moves = generate_moves(board, color)
    for move in all_moves:
        r1, c1, r2, c2 = move
        # Create copy of board
        new_board = [row[:] for row in board]
        piece = new_board[r1][c1]
        new_board[r2][c2] = piece
        new_board[r1][c1] = None

        # Check if king would still be in check after this move
        new_king_pos = get_king_position(new_board, color)
        if not is_square_attacked(new_board, new_king_pos[0], new_king_pos[1], opponent):
            return False

    # No legal moves exist while in check = checkmate
    return True

def exchange_sort(sequence):
    if len(sequence) <= 1:
        return 0

    # Create target sorted sequence
    target = sorted(sequence)

    # Create a mapping from value to its target positions
    value_positions = {7: [], 8: [], 9: []}
    for i, val in enumerate(target):
        value_positions[val].append(i)

    # Create a permutation array where perm[i] = j means
    # element at position i should be at position j in the sorted array
    perm = [0] * len(sequence)
    pos_index = {7: 0, 8: 0, 9: 0}

    for i, val in enumerate(sequence):
        target_pos = value_positions[val][pos_index[val]]
        perm[i] = target_pos
        pos_index[val] += 1

    # Find number of cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i]:
            # Start a new cycle
            cycles += 1
            current = i
            while not visited[current]:
                visited[current] = True
                current = perm[current]

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

def choose(n, k):
    # Handle edge cases
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry optimization: C(n, k) = C(n, n-k)
    k = min(k, n - k)

    # Compute iteratively to avoid large intermediate factorials
    result = 1
    for i in range(1, k + 1):
        result = result * (n - i + 1) // i

    return result

