def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """

    def is_prime(num):
        """Helper function to check if a number is prime"""
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        # Check odd divisors up to sqrt(num)
        for i in range(3, int(num ** 0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    return x if is_prime(n) else y

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Use enumerate to keep track of original indices for stability
    indexed_nums = list(enumerate(nums))

    # Sort by digit sum first, then by original index for stability
    sorted_nums = sorted(indexed_nums, key=lambda x: (digit_sum(x[1]), x[0]))

    # Extract just the numbers from the sorted result
    return [num for index, num in sorted_nums]

def count_divisors(n):
    sqrt_n = int(n ** 0.5)
    total = 0
    for i in range(1, sqrt_n + 1):
        total += n // i
    return 2 * total - sqrt_n * sqrt_n

