def exchange_sort(sequence):
    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for val in sequence:
        count[val] += 1

    # Create target sorted sequence
    target = []
    target.extend([7] * count[7])
    target.extend([8] * count[8])
    target.extend([9] * count[9])

    # Create a mapping from value to its target positions
    target_positions = {7: [], 8: [], 9: []}
    for i, val in enumerate(target):
        target_positions[val].append(i)

    # Create a mapping from current positions to target positions
    current_positions = {7: [], 8: [], 9: []}
    for i, val in enumerate(sequence):
        current_positions[val].append(i)

    # Find mismatches
    mismatches = []
    for i, val in enumerate(sequence):
        if val != target[i]:
            mismatches.append((i, val))

    # Count cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i] and sequence[i] != target[i]:
            # Start a new cycle
            cycles += 1
            current = i
            while not visited[current]:
                visited[current] = True
                # Find where current element should go
                target_val = sequence[current]
                # Find the first position in target_positions[target_val] that's not visited
                target_pos = target_positions[target_val].pop(0)
                current = target_pos

    # The minimum number of swaps is (n - cycles)
    return len(sequence) - cycles

def pig_latin(word):
    if not word or not word.isalpha():
        return None

    word = word.lower()
    vowels = set('aeiou')

    if word[0] in vowels:
        return word + "way"

    first_vowel_idx = None
    for i, c in enumerate(word):
        if c in vowels:
            first_vowel_idx = i
            break

    if first_vowel_idx is None:
        return word + "ay"

    return word[first_vowel_idx:] + word[:first_vowel_idx] + "ay"

def getAllPrimeFactors(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    if not isinstance(n, int) or n <= 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)
    unique_factors = []
    counts = []

    if factors:
        current_factor = factors[0]
        count = 1

        for i in range(1, len(factors)):
            if factors[i] == current_factor:
                count += 1
            else:
                unique_factors.append(current_factor)
                counts.append(count)
                current_factor = factors[i]
                count = 1

        unique_factors.append(current_factor)
        counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    factor_counts = getUniquePrimeFactorsWithCount(n)
    unique_factors = factor_counts[0]
    counts = factor_counts[1]

    products = []
    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

def poohbear(code):
    # Initialize memory and pointer
    memory = {}
    pointer = 0
    copied = 0
    pc = 0
    output = []

    # Find all loop pairs
    loop_stack = []
    loop_pairs = {}

    for i, char in enumerate(code):
        if char == 'W':
            loop_stack.append(i)
        elif char == 'E':
            if loop_stack:
                start = loop_stack.pop()
                loop_pairs[start] = i
                loop_pairs[i] = start

    # Execute code
    while pc < len(code):
        char = code[pc]

        if char == '+':
            memory[pointer] = memory.get(pointer, 0) + 1
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == '-':
            memory[pointer] = memory.get(pointer, 0) - 1
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copied = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copied
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                pc = loop_pairs[pc]
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                pc = loop_pairs[pc]
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif char == 'T':
            memory[pointer] = memory.get(pointer, 0) * 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'Q':
            memory[pointer] = memory.get(pointer, 0) ** 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'U':
            import math
            memory[pointer] = int(math.sqrt(memory.get(pointer, 0)))
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'L':
            memory[pointer] = memory.get(pointer, 0) + 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'V':
            memory[pointer] = memory.get(pointer, 0) // 2
        elif char == 'A':
            memory[pointer] = memory.get(pointer, 0) + copied
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'B':
            memory[pointer] = memory.get(pointer, 0) - copied
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'Y':
            memory[pointer] = memory.get(pointer, 0) * copied
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'D':
            if copied != 0:
                memory[pointer] = memory.get(pointer, 0) // copied
            else:
                memory[pointer] = 0

        pc += 1

    return ''.join(output)

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    gems = list(map(int, lines[1].split()))

    # Precompute palindromes
    is_palindrome = [[False] * n for _ in range(n)]

    # Every single gem is a palindrome
    for i in range(n):
        is_palindrome[i][i] = True

    # Check for palindromes of length 2
    for i in range(n - 1):
        if gems[i] == gems[i + 1]:
            is_palindrome[i][i + 1] = True

    # Check for palindromes of length 3 and more
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if gems[i] == gems[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP approach
    # dp[i][j] represents minimum time to remove gems from i to j
    dp = [[0] * n for _ in range(n)]

    # Base case: single gem requires 1 second
    for i in range(n):
        dp[i][i] = 1

    # Fill DP table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if is_palindrome[i][j]:
                # If the substring is palindrome, we can remove it in 1 second
                dp[i][j] = 1
            else:
                # Otherwise, split and find minimum
                dp[i][j] = length  # Worst case: remove each one by one
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

