    return hashlib.md5(text.encode('utf-8')).hexdigest()

def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            if char.islower():
                shifted = chr((ord(char) - ord('a') + 4) % 26 + ord('a'))
                result.append(shifted)
            else:
                shifted = chr((ord(char) - ord('A') + 4) % 26 + ord('A'))
                result.append(shifted)
        else:
            result.append(char)
    return ''.join(result)

