def getAllPrimeFactors(n):
    # Input validation
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Special case for 1
    if n == 1:
        return [1]

    factors = []
    # Handle factor 2
    while n % 2 == 0:
        factors.append(2)
        n = n // 2

    # Handle odd factors
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n = n // i
        i += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Input validation
    if not isinstance(n, int):
        return [[], []]
    if n <= 0:
        return [[], []]

    # Special case for 1
    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)

    if not factors:
        return [[], []]

    unique_factors = []
    counts = []

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    # Add the last group
    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Input validation
    if not isinstance(n, int):
        return []
    if n <= 0:
        return []

    # Special case for 1
    if n == 1:
        return [1]

    unique_factors_counts = getUniquePrimeFactorsWithCount(n)
    unique_factors = unique_factors_counts[0]
    counts = unique_factors_counts[1]

    if not unique_factors:
        return []

    products = []
    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

def poohbear(code):
    # Pre-process code to find loop matches
    loops = []
    loop_stack = []
    loop_matches = {}

    for i, char in enumerate(code):
        if char == 'W':
            loop_stack.append(i)
        elif char == 'E':
            if loop_stack:
                start = loop_stack.pop()
                loop_matches[start] = i
                loop_matches[i] = start

    # Initialize tape and state
    tape = {}
    pointer = 0
    copied = 0
    ip = 0
    output = []

    # Process commands
    while ip < len(code):
        char = code[ip]

        if char == '+':
            tape[pointer] = (tape.get(pointer, 0) + 1) % 256
        elif char == '-':
            tape[pointer] = (tape.get(pointer, 0) - 1) % 256
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copied = tape.get(pointer, 0)
        elif char == 'p':
            tape[pointer] = copied
        elif char == 'W':
            if tape.get(pointer, 0) == 0:
                ip = loop_matches[ip]
        elif char == 'E':
            if tape.get(pointer, 0) != 0:
                ip = loop_matches[ip]
        elif char == 'P':
            output.append(chr(tape.get(pointer, 0)))
        elif char == 'N':
            output.append(str(tape.get(pointer, 0)))
        elif char == 'T':
            tape[pointer] = (tape.get(pointer, 0) * 2) % 256
        elif char == 'Q':
            tape[pointer] = (tape.get(pointer, 0) ** 2) % 256
        elif char == 'U':
            import math
            tape[pointer] = int(math.sqrt(tape.get(pointer, 0))) % 256
        elif char == 'L':
            tape[pointer] = (tape.get(pointer, 0) + 2) % 256
        elif char == 'I':
            tape[pointer] = (tape.get(pointer, 0) - 2) % 256
        elif char == 'V':
            if copied != 0:
                tape[pointer] = (tape.get(pointer, 0) // copied) % 256
            else:
                tape[pointer] = 0
        elif char == 'A':
            tape[pointer] = (tape.get(pointer, 0) + copied) % 256
        elif char == 'B':
            tape[pointer] = (tape.get(pointer, 0) - copied) % 256
        elif char == 'Y':
            tape[pointer] = (tape.get(pointer, 0) * copied) % 256
        elif char == 'D':
            if copied != 0:
                tape[pointer] = (tape.get(pointer, 0) // copied) % 256
            else:
                tape[pointer] = 0

        ip += 1

    return ''.join(output)

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    if not lines or not lines[0].strip():
        return

    first_line = lines[0].split()
    n = int(first_line[0])
    M = int(first_line[1])

    points = []
    for i in range(1, n + 1):
        if i < len(lines):
            x, y = map(int, lines[i].split())
            points.append((x, y))

    # For each point, calculate the Manhattan distance to all other points
    # and count how many points are within distance M
    count = 0
    for i in range(n):
        for j in range(n):
            if i != j:
                distance = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
                if distance <= M:
                    count += 1

    print(count)

if __name__ == "__main__":
    main()

def choose(n, k):
    # Handle edge cases
    if k < 0 or k > n:
        return 0

    # Use symmetry property: C(n, k) = C(n, n-k)
    if k > n - k:
        k = n - k

    # Handle trivial cases
    if k == 0:
        return 1

    # Compute using iterative multiplicative formula
    # C(n, k) = n * (n-1) * ... * (n-k+1) / (k * (k-1) * ... * 1)
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

def exchange_sort(sequence):
    n = len(sequence)
    if n <= 1:
        return 0

    # Count occurrences of each value
    count_7 = sequence.count(7)
    count_8 = sequence.count(8)
    count_9 = sequence.count(9)

    # Determine zone boundaries for sorted sequence
    zone7_end = count_7
    zone8_end = count_7 + count_8

    # Count misplaced elements in each zone
    c7_8 = c7_9 = c8_7 = c8_9 = c9_7 = c9_8 = 0

    for i in range(n):
        if i < zone7_end:
            if sequence[i] == 8:
                c7_8 += 1
            elif sequence[i] == 9:
                c7_9 += 1
        elif i < zone8_end:
            if sequence[i] == 7:
                c8_7 += 1
            elif sequence[i] == 9:
                c8_9 += 1
        else:
            if sequence[i] == 7:
                c9_7 += 1
            elif sequence[i] == 8:
                c9_8 += 1

    # Calculate direct swaps (each fixes 2 elements)
    swap_7_8 = min(c7_8, c8_7)
    swap_7_9 = min(c7_9, c9_7)
    swap_8_9 = min(c8_9, c9_8)

    # Remaining elements form 3-cycles (each cycle needs 2 swaps)
    remaining_cycles = c7_8 - swap_7_8

    # Total swaps = direct swaps + 2 * remaining 3-cycles
    return swap_7_8 + swap_7_9 + swap_8_9 + remaining_cycles * 2

