        return None
    return hashlib.md5(text.encode('utf-8')).hexdigest()

def compare_one(a, b):
    def parse_value(v):
        """Convert value to float for comparison, handling string decimal separators"""
        if isinstance(v, str):
            # Replace comma with dot for decimal separator
            return float(v.replace(',', '.'))
        else:
            return float(v)

    # Parse both values to float for comparison
    num_a = parse_value(a)
    num_b = parse_value(b)

