def parse_int(s):
    # Define word mappings
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14, 'fifteen': 15,
        'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19,
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    # Split the string into words and remove 'and' words
    words = s.replace(' and ', ' ').split()

    result = 0
    current = 0

    for word in words:
        if word in word_to_num:
            current += word_to_num[word]
        elif word == 'hundred':
            current *= 100
        elif word == 'thousand':
            result += current * 1000
            current = 0
        elif word == 'million':
            result += current * 1000000
            current = 0

    return result + current

def getAllPrimeFactors(n):
    # Error checking
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []
    if isinstance(n, float) and not n.is_integer():
        return []
    n = int(n)
    if n < 0:
        return []

    # Edge case n=0
    if n == 0:
        return []

    # Edge case n=1
    if n == 1:
        return [1]

    # Prime factorization
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Error checking
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return [[], []]
    if isinstance(n, float) and not n.is_integer():
        return [[], []]
    n = int(n)
    if n < 0:
        return [[], []]

    # Edge case n=0
    if n == 0:
        return [[], []]

    # Edge case n=1
    if n == 1:
        return [[1], [1]]

    # Get all prime factors
    factors = getAllPrimeFactors(n)

    if not factors:
        return [[], []]

    # Count occurrences
    unique_primes = []
    counts = []
    i = 0
    while i < len(factors):
        prime = factors[i]
        count = 0
        while i < len(factors) and factors[i] == prime:
            count += 1
            i += 1
        unique_primes.append(prime)
        counts.append(count)

    return [unique_primes, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Error checking
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []
    if isinstance(n, float) and not n.is_integer():
        return []
    n = int(n)
    if n < 0:
        return []

    # Edge case n=0
    if n == 0:
        return []

    # Edge case n=1
    if n == 1:
        return [1]

    # Get unique prime factors with counts
    result = getUniquePrimeFactorsWithCount(n)
    unique_primes = result[0]
    counts = result[1]

    # Calculate products
    products = []
    for prime, count in zip(unique_primes, counts):
        products.append(prime ** count)

    return products

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 365 * 24 * 60 * 60),
        ('day', 24 * 60 * 60),
        ('hour', 60 * 60),
        ('minute', 60),
        ('second', 1)
    ]

    # Calculate components
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            if count > 1:
                components.append(f"{count} {unit_name}s")
            else:
                components.append(f"{count} {unit_name}")

    # Format the result
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

