                                is_king_attacked = True
                                break

                        # Check if new position is not attacked by amazon
                        is_amazon_attacked = (nr, nc) in amazon_attacks

                        if not is_king_attacked and not is_amazon_attacked:
                            can_escape = True
                            break
                if can_escape:
                    break

            if can_escape:
                check += 1
            else:
                checkmate += 1
        else:
            # Black king is not under attack, check if it can move
            can_move = False
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
