def compare(selector1, selector2):
    def calculate_specificity(selector):
        id_count = 0
        class_count = 0
        tagname_count = 0

        # Split selector by whitespace into parts
        parts = selector.split()

        for part in parts:
            if not part or part == '*':
                continue

            # Count ID selectors (#)
            id_parts = part.split('#')
            id_count += len(id_parts) - 1

            # Count class selectors (.)
            class_parts = part.split('.')
            class_count += len(class_parts) - 1

            # Determine tagname (text before first # or .)
            tagname_part = part
            if '#' in tagname_part:
                tagname_part = tagname_part.split('#')[0]
            if '.' in tagname_part:
                tagname_part = tagname_part.split('.')[0]

            if tagname_part and tagname_part != '*' and tagname_part not in ['#', '.']:
                # Check if it's a valid tagname (alphanumeric)
                tagname_count += 1

        return (id_count, class_count, tagname_count)

    spec1 = calculate_specificity(selector1)
    spec2 = calculate_specificity(selector2)

    # Compare specificities
    if spec1 > spec2:
        return selector1
    elif spec2 > spec1:
        return selector2
    else:
        # Equal specificity - return the later appearing one (selector2)
        return selector2

def histogram(test):
    if not test.strip():
        return {}

    letters = test.split()
    count = {}
    for letter in letters:
        count[letter] = count.get(letter, 0) + 1

    max_count = max(count.values())
    return {letter: cnt for letter, cnt in count.items() if cnt == max_count}

def fib4(n):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize the first four values
    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute fib4(n)
    for i in range(4, n + 1):
        next_val = a + b + c + d
        # Slide the window
        a, b, c, d = b, c, d, next_val

    return d

def is_valid(s):
    if not s:
