    # Check the first character
    first_char = s[0]
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Check the rest of the characters
    for char in s[1:]:
        if not (char.isalpha() or char.isdigit() or char == '_' or char == '$'):
            return False

    return True

