def sum_of_squares(n):
    def is_perfect_square(x):
        if x < 0:
            return False
        sqrt_x = int(x ** 0.5)
        return sqrt_x * sqrt_x == x

    # Step 1: Check if n is a perfect square (answer = 1)
    if is_perfect_square(n):
        return 1

    # Step 2: Check if n can be written as sum of 2 squares (answer = 2)
    for i in range(1, int(n ** 0.5) + 1):
        if is_perfect_square(n - i * i):
            return 2

    # Step 3: Apply Legendre's Three-Square Theorem
    # n can be written as sum of 3 squares iff n is NOT of form 4^a(8b + 7)
    temp = n
    while temp % 4 == 0:
        temp //= 4
    if temp % 8 == 7:
        return 4
    else:
        return 3

