def pig_latin(word):
    if not word or not word.isalpha():
        return None

    word = word.lower()
    vowels = "aeiou"

    if word[0] in vowels:
        return word + "way"

    # Find the index where the first vowel occurs
    first_vowel_index = 0
    for i, char in enumerate(word):
        if char in vowels:
            first_vowel_index = i
            break
    else:
        # No vowels found, return original + "ay"
        return word + "ay"

    # Move consonants before first vowel to the end
    consonant_cluster = word[:first_vowel_index]
    rest_of_word = word[first_vowel_index:]

    return rest_of_word + consonant_cluster + "ay"

