def choose(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry property: C(n, k) = C(n, n-k)
    k = min(k, n - k)

    # Compute using multiplicative formula with integer arithmetic
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define units in seconds
    years = seconds // 31536000
    seconds %= 31536000

    days = seconds // 86400
    seconds %= 86400

    hours = seconds // 3600
    seconds %= 3600

    minutes = seconds // 60
    seconds %= 60

    # Build components
    components = []

    if years > 0:
        components.append(f"{years} year{'s' if years > 1 else ''}")

    if days > 0:
        components.append(f"{days} day{'s' if days > 1 else ''}")

    if hours > 0:
