def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into terms
    # Find all terms (including the leading one if it's not preceded by + or -)
    terms = re.findall(r'[+-]?[^+-]+', expression)

    # Dictionary to store monomials and their coefficients
    monomial_dict = defaultdict(int)

    for term in terms:
        # Handle the sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Extract coefficient and monomial part
        coeff_str = ''
        i = 0
        while i < len(term) and term[i].isdigit():
            coeff_str += term[i]
            i += 1

        if coeff_str == '':
            coeff = sign * 1
        else:
            coeff = sign * int(coeff_str)

        monomial = term[i:]  # The remaining part is the monomial

        # Sort variables in monomial for consistent representation
        sorted_monomial = ''.join(sorted(monomial))

        # Add to dictionary
        monomial_dict[sorted_monomial] += coeff

    # Remove zero coefficients
    monomial_dict = {m: c for m, c in monomial_dict.items() if c != 0}

    # Sort monomials by number of variables, then lexicographically
    sorted_monomials = sorted(monomial_dict.keys(), key=lambda x: (len(x), x))

    # Build result string
    result_parts = []

    for monomial in sorted_monomials:
        coeff = monomial_dict[monomial]
        if coeff == 1 and monomial != '':
            coeff_str = ''
        elif coeff == -1 and monomial != '':
            coeff_str = '-'
        else:
            coeff_str = str(coeff)

        if monomial == '':
            # Constant term
            result_parts.append(coeff_str)
        else:
            result_parts.append(coeff_str + monomial)

    # Join parts with proper signs
    if not result_parts:
        return "0"

    result = result_parts[0]
    for part in result_parts[1:]:
        if part.startswith('-'):
            result += ' - ' + part[1:]
        else:
            result += ' + ' + part

    # Remove leading + if present
    if result.startswith('+ '):
        result = result[2:]

    return result

def proper_fractions(n):
    if n == 1:
        return 0

    result = n

    # Check for factor 2
    if n % 2 == 0:
        result -= result // 2
        while n % 2 == 0:
            n //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result -= result // i
            while n % i == 0:
                n //= i
        i += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        result -= result // n

    return result

