        dy = p[1] - start[1]
        if dx == 0 and dy == 0:
            return (0, 0)
        return (dx, dy)

    points.sort(key=lambda p: (math.atan2(p[1] - start[1], p[0] - start[0]), 
                              distance(start, p)))

    # Graham scan
    hull = [start]
    for point in points[1:]:
        while len(hull) > 1 and cross_product(hull[-2], hull[-1], point) <= 0:
