    return arr

def largest_divisor(n: int) -> int:
    if n <= 1:
        return None

    # Find the smallest prime factor
    smallest_factor = n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            smallest_factor = i
            break

    # If no factor found, n is prime, so largest proper divisor is 1
    if smallest_factor == n:
        return 1

    # Return n divided by its smallest prime factor
    return n // smallest_factor

def differentiate(polynomial, x):
    # Parse the polynomial into terms
    # Handle the case where there's no plus/minus in the beginning
    if polynomial[0] != '-':
        polynomial = '+' + polynomial

    # Split by + and - signs (keeping the sign with the term)
    terms = []
    current_term = ""
    i = 0
    while i < len(polynomial):
        if polynomial[i] in ['+', '-'] and i > 0:
            if current_term:
                terms.append(current_term)
            current_term = polynomial[i]
        else:
            current_term += polynomial[i]
        i += 1
    if current_term:
        terms.append(current_term)

    # Process each term
    derivative_terms = []
    for term in terms:
        if term == '+':
            continue
        elif term == '-':
            continue

        # Remove the leading + or - for processing
        sign = 1 if term[0] == '+' else -1
        term = term[1:] if term[0] in ['+', '-'] else term

        # Handle different term formats
        if 'x^' in term:
            # Format: ax^n
            parts = term.split('x^')
            coeff_str = parts[0]
            if coeff_str == '':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)
            coeff *= sign
            exponent = int(parts[1])

            # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
            if exponent > 0:
                new_coeff = coeff * exponent
                new_exponent = exponent - 1
                if new_exponent == 0:
                    derivative_terms.append(str(new_coeff))
                elif new_exponent == 1:
                    derivative_terms.append(f"{new_coeff}x")
                else:
                    derivative_terms.append(f"{new_coeff}x^{new_exponent}")

        elif 'x' in term:
            # Format: ax or -ax
            if term == 'x':
                coeff = 1
            elif term == '-x':
                coeff = -1
            else:
                coeff_str = term[:-1]
                if coeff_str == '+':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str)
            coeff *= sign

            # Apply power rule: d/dx(ax) = a
            derivative_terms.append(str(coeff))

        else:
            # Format: constant
            coeff = int(term) * sign
            # Derivative of constant is 0, so we don't add anything to derivative_terms

    # Evaluate the derivative at x
    result = 0
    for term in derivative_terms:
        if 'x' in term:
            # Extract coefficient and exponent
            if 'x^' in term:
                parts = term.split('x^')
                coeff = int(parts[0])
                exponent = int(parts[1])
                result += coeff * (x ** exponent)
            else:
                # x term
                coeff_str = term[:-1]
                if coeff_str == '':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str)
                result += coeff * x
        else:
            # Constant term
            result += int(term)

    return result

