import re
from collections import defaultdict

def simplify(expression):
    if not expression or not expression.strip():
        return ""

    expression = expression.strip()

    # Split into monomials while preserving signs
    # Each monomial starts with + or -, or is the first term
    parts = re.findall(r'([+-]?[^+-]+)', expression)
    parts = [p for p in parts if p]

    # Parse each part and combine like terms
    coeffs = defaultdict(int)

    for part in parts:
        if not part:
            continue

        # Extract sign, coefficient, and variables
        i = 0

        # Get sign
        sign = 1
        if i < len(part) and part[i] in '+-':
            if part[i] == '-':
                sign = -1
            i += 1

        # Get coefficient (digits)
        num_end = i
        while num_end < len(part) and part[num_end].isdigit():
            num_end += 1

        if num_end > i:
            coefficient = int(part[i:num_end])
        else:
            coefficient = 1

        coefficient *= sign

        # Get variables
        var_end = num_end
        while var_end < len(part) and part[var_end].islower():
            var_end += 1

        var_str = part[num_end:var_end]

        # Sort variables for canonical form
        sorted_vars = ''.join(sorted(var_str))

        # Add to dictionary (combine like terms)
        if sorted_vars:  # Skip if no variables (constant)
            coeffs[sorted_vars] += coefficient

    # Filter out zero coefficients
    terms = [(vars_str, coef) for vars_str, coef in coeffs.items() if coef != 0]

    # Sort by number of variables, then lexicographically
    terms.sort(key=lambda t: (len(t[0]), t[0]))

    # Build result
    result = []
    for vars_str, coef in terms:
        if not vars_str:  # Skip constant terms
            continue

        if coef == 1:
            if result:
                result.append('+' + vars_str)
            else:
                result.append(vars_str)
        elif coef == -1:
            result.append('-' + vars_str)
        else:
            if result and coef > 0:
                result.append('+' + str(coef) + vars_str)
            else:
                result.append(str(coef) + vars_str)

    return ''.join(result)

def getAllPrimeFactors(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    if not isinstance(n, int) or n <= 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)
    unique_factors = []
    counts = []

    if factors:
        current_factor = factors[0]
        count = 0

        for factor in factors:
            if factor == current_factor:
                count += 1
            else:
                unique_factors.append(current_factor)
                counts.append(count)
                current_factor = factor
                count = 1

        unique_factors.append(current_factor)
        counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    factor_count_pairs = zip(*getUniquePrimeFactorsWithCount(n))
    products = []

    for factor, count in factor_count_pairs:
        products.append(factor ** count)

    return products

def almost_everywhere_zero(n, k):
    # Convert n to string for digit manipulation
    s = str(n)
    length = len(s)

    # Memoization dictionary
    memo = {}

    def dp(pos, count, tight, started):
        # pos: current position in the digit string
        # count: number of non-zero digits used so far
        # tight: whether we're still bounded by the original number
        # started: whether we've placed a non-zero digit yet

        # Base case: if we've processed all digits
        if pos == length:
            return 1 if count == k else 0

        # Check memoization
        if (pos, count, tight, started) in memo:
            return memo[(pos, count, tight, started)]

        # Determine the upper limit for current digit
        limit = int(s[pos]) if tight else 9
        result = 0

        # Try placing each possible digit at current position
        for digit in range(0, limit + 1):
            # If we place a non-zero digit
            if digit > 0:
                # Only increment count if we haven't started yet or we're continuing
                if not started:
                    # First non-zero digit
                    result += dp(pos + 1, count + 1, tight and (digit == limit), True)
                else:
                    # Continuing with non-zero digits
                    result += dp(pos + 1, count + 1, tight and (digit == limit), True)
            else:
                # If we place zero
                if not started:
                    # We can still place zeros without starting the number
                    result += dp(pos + 1, count, tight and (digit == limit), False)
                else:
                    # We're already started, so we can place zeros
                    result += dp(pos + 1, count, tight and (digit == limit), True)

        memo[(pos, count, tight, started)] = result
        return result

    # Start the DP
    return dp(0, 0, True, False)

def encrypt(s):
    result = ""
    for char in s:
        if 'a' <= char <= 'z':
            # Shift by 4 positions with wrapping
            shifted = (ord(char) - ord('a') + 4) % 26
            result += chr(shifted + ord('a'))
        else:
            # Non-lowercase letters remain unchanged
            result += char
    return result

