def choose(n, k):
    # Handle edge cases
    if k > n or n < 0 or k < 0:
        return 0

    # Use the more efficient iterative approach
    # to avoid computing large factorials directly
    if k > n - k:
        k = n - k  # Take advantage of symmetry

    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

