def choose(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1

    # Use the smaller of k and n-k to minimize calculations
    k = min(k, n - k)

    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

def converter(number, decimals=0, base=3.141592653589793):
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36")
    if decimals < 0:
        raise ValueError("Decimals must be non-negative")

    # Handle zero case
    if number == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Handle negative numbers
    is_negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    digits = []

    if integer_part == 0:
        digits = ['0']
    else:
        temp = integer_part
        while temp > 0:
            digits.append(temp % int(base))
            temp //= int(base)
        digits.reverse()

    # Convert fractional part
    fractional_part = number - integer_part
    fractional_digits = []

    if decimals > 0 and fractional_part > 0:
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            # Handle floating point precision issues
            if digit >= int(base):
                digit = int(base) - 1
            fractional_digits.append(digit)
            fractional_part -= digit

    # Convert digits to characters
    char_map = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

    integer_string = ''.join(char_map[d] for d in digits)

    if decimals == 0:
        result = integer_string
    else:
        fractional_string = ''.join(char_map[d] for d in fractional_digits)
        result = integer_string + '.' + fractional_string

    # Handle case where result is less than 1
    if number < 1 and not result.startswith('0.'):
        result = '0.' + result

    if is_negative:
        result = '-' + result

    return result

