def differentiate(polynomial, point):
    # Handle leading minus sign for proper splitting
    if polynomial.startswith('-'):
        poly = '+' + polynomial
    else:
        poly = polynomial

    # Split by + to get individual terms
    terms = poly.split('+')

    result = 0

    for term in terms:
        if not term:
            continue

        # Parse coefficient and exponent
        if '^' in term:
            # Term has exponent like ax^n or x^n
            parts = term.split('^')
            coeff_part = parts[0]
            exponent = int(parts[1])

            # Parse coefficient
            if coeff_part == 'x':
                coefficient = 1
            elif coeff_part == '-x':
                coefficient = -1
            else:
                coefficient = int(coeff_part)
        else:
            # No exponent operator
            if 'x' in term:
                # Linear term like ax, x, or -x
                if term == 'x':
                    coefficient = 1
                    exponent = 1
                elif term == '-x':
                    coefficient = -1
                    exponent = 1
                else:
                    # Parse coefficient before x
                    coefficient = int(term.replace('x', ''))
                    exponent = 1
            else:
                # Constant term
                coefficient = int(term)
                exponent = 0

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent == 0:
            # Constant term derivative is 0
            continue
        else:
            # Calculate derivative coefficient and new exponent
            deriv_coeff = coefficient * exponent
            deriv_exponent = exponent - 1

            # Evaluate at given point
            if deriv_exponent == 0:
                result += deriv_coeff
            else:
                result += deriv_coeff * (point ** deriv_exponent)

    return result

