def differentiate(polynomial, x):
    # Parse the polynomial into terms
    terms = []
    current_term = ""
    i = 0

    # Handle the first term specially if it starts with -
    if polynomial[0] == '-':
        current_term = "-"
        i = 1
    else:
        current_term = ""
        i = 0

    # Split by + and - signs, but keep the signs
    while i < len(polynomial):
        if polynomial[i] in ['+', '-']:
            if current_term:
                terms.append(current_term)
            current_term = polynomial[i]
        else:
            current_term += polynomial[i]
        i += 1

    if current_term:
        terms.append(current_term)

    # Process each term
    derivative_terms = []

    for term in terms:
        # Skip empty terms
        if not term or term == '+' or term == '-':
            continue

        # Determine sign
        sign = 1
        term_content = term
        if term.startswith('-'):
            sign = -1
            term_content = term[1:]
        elif term.startswith('+'):
            term_content = term[1:]

        # Handle constant term (no x)
        if 'x' not in term_content:
            # This is a constant term, derivative is 0
            continue

        # Extract coefficient and exponent
        if 'x^' in term_content:
            # Format: ax^n
            parts = term_content.split('x^')
            coeff_str = parts[0]
            if coeff_str == '':
                coeff = sign * 1
            elif coeff_str == '-':
                coeff = sign * -1
            else:
                coeff = sign * int(coeff_str)
            exp = int(parts[1])
        elif 'x' in term_content:
            # Format: ax or ax^1
            if term_content == 'x':
                coeff = sign * 1
                exp = 1
            elif term_content == '-x':
                coeff = sign * -1
                exp = 1
            else:
                coeff_str = term_content.replace('x', '')
                if coeff_str == '':
                    coeff = sign * 1
                elif coeff_str == '-':
                    coeff = sign * -1
                else:
                    coeff = sign * int(coeff_str)
                exp = 1
        else:
            # This shouldn't happen if we handle correctly above
            continue

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exp > 0:
            new_coeff = exp * coeff
            new_exp = exp - 1
            derivative_terms.append((new_coeff, new_exp))

    # Evaluate the derivative at x
    result = 0
    for coeff, exp in derivative_terms:
        if exp == 0:
            result += coeff
        else:
            result += coeff * (x ** exp)

    return result

import hashlib

def string_to_md5(text):
    if not text:
        return None

    # Convert string to bytes using UTF-8 encoding
    text_bytes = text.encode('utf-8')

    # Create MD5 hash
    md5_hash = hashlib.md5(text_bytes)

    # Return hexadecimal representation
    return md5_hash.hexdigest()

from typing import List, Tuple


def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    def flatten(lst):
        result = []
        for item in lst:
            if isinstance(item, list):
                result.extend(flatten(item))
            else:
                result.append(item)
        return result

    flattened = flatten(numbers)

    if not flattened:
        return (0, 1)

    total_sum = 0
    total_product = 1

    for num in flattened:
        total_sum += num
        total_product *= num

    return (total_sum, total_product)

def candies(ratings):
    if not ratings:
        return 0

    n = len(ratings)
    candy_dist = [1] * n

    # Left to right pass
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            candy_dist[i] = candy_dist[i - 1] + 1

    # Right to left pass
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            candy_dist[i] = max(candy_dist[i], candy_dist[i + 1] + 1)

    return sum(candy_dist)

