def amazon_check_mate(king, amazon):
    # Parse positions: convert chess notation to (x, y) coordinates
    def parse_position(pos):
        x = ord(pos[0]) - ord('a')  # a=0, b=1, ..., h=7
        y = int(pos[1]) - 1         # 1=0, 2=1, ..., 8=7
        return (x, y)

    kx, ky = parse_position(king)   # White king position
    ax, ay = parse_position(amazon) # Amazon position

    # Calculate all squares attacked by amazon (queen moves + knight moves)
    amazon_attacks = set()

    # Queen-like moves (horizontal, vertical, diagonal)
    # Horizontal
    for x in range(8):
        if x != ax:
            amazon_attacks.add((x, ay))
    # Vertical
    for y in range(8):
        if y != ay:
            amazon_attacks.add((ax, y))
    # Diagonal (top-right, top-left, bottom-right, bottom-left)
    # Top-right
    dx, dy = 1, 1
    while ax + dx < 8 and ay + dy < 8:
        amazon_attacks.add((ax + dx, ay + dy))
        dx += 1
        dy += 1
    # Top-left
    dx, dy = 1, -1
    while ax + dx < 8 and ay + dy >= 0:
        amazon_attacks.add((ax + dx, ay + dy))
        dx += 1
        dy -= 1
    # Bottom-right
    dx, dy = -1, 1
    while ax + dx >= 0 and ay + dy < 8:
        amazon_attacks.add((ax + dx, ay + dy))
        dx -= 1
        dy += 1
    # Bottom-left
    dx, dy = -1, -1
    while ax + dx >= 0 and ay + dy >= 0:
        amazon_attacks.add((ax + dx, ay + dy))
        dx -= 1
        dy -= 1

    # Knight moves (8 possible L-shaped moves)
    knight_moves = [(2, 1), (2, -1), (-2, 1), (-2, -1), 
                    (1, 2), (1, -2), (-1, 2), (-1, -2)]
    for dx, dy in knight_moves:
        nx, ny = ax + dx, ay + dy
        if 0 <= nx < 8 and 0 <= ny < 8:
            amazon_attacks.add((nx, ny))

    # Check if a black king position is valid
    def is_valid_position(bk_x, bk_y):
        # Black king cannot be on white pieces
        if (bk_x, bk_y) == (kx, ky) or (bk_x, bk_y) == (ax, ay):
            return False
        # Black king cannot be adjacent to white king (8-directional)
        if abs(bk_x - kx) <= 1 and abs(bk_y - ky) <= 1:
            return False
        return True

    # Check if black king can reach any safe square from position
    def has_valid_escape(bk_x, bk_y):
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                new_x, new_y = bk_x + dx, bk_y + dy
                # Check if this new position is valid and safe from amazon
                if is_valid_position(new_x, new_y) and (new_x, new_y) not in amazon_attacks:
                    return True
        return False

    # Count for each category
    checkmate = 0
    check = 0
    stalemate = 0
    safe_with_moves = 0

    # Check all 64 squares for black king position
    for bx in range(8):
        for by in range(8):
            # Position must be valid for black king
            if not is_valid_position(bx, by):
                continue

            is_under_attack = (bx, by) in amazon_attacks

            if is_under_attack:
                # Black king is under attack
                if has_valid_escape(bx, by):
                    check += 1  # Can reach a safe square
                else:
                    checkmate += 1  # Cannot make a valid move to safety
            else:
                # Black king is on a safe square
                if has_valid_escape(bx, by):
                    safe_with_moves += 1  # Can make a valid move
                else:
                    stalemate += 1  # Cannot make a valid move

    return [checkmate, check, stalemate, safe_with_moves]

