def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into terms
    terms = []
    # Split by + and - signs, keeping the signs
    tokens = re.findall(r'[+-]?[^+-]+', expression)

    for token in tokens:
        if not token:
            continue
        # Determine the sign
        if token.startswith('-'):
            sign = -1
            term = token[1:]
        elif token.startswith('+'):
            sign = 1
            term = token[1:]
        else:
            sign = 1
            term = token

        # Extract coefficient and variables
        # Find the coefficient (all leading digits)
        coeff_match = re.match(r'^(\d+)', term)
        if coeff_match:
            coeff = int(coeff_match.group(1))
            var_part = term[coeff_match.end():]
        else:
            coeff = 1
            var_part = term

        # Apply sign to coefficient
        coeff *= sign

        # Sort variables alphabetically to canonicalize
        variables = sorted(list(var_part))
        canonical_var = ''.join(variables)

        terms.append((coeff, canonical_var))

    # Aggregate like terms
    aggregated = defaultdict(int)
    for coeff, var in terms:
        aggregated[var] += coeff

    # Remove zero coefficients
    aggregated = {var: coeff for var, coeff in aggregated.items() if coeff != 0}

    # Sort terms
    sorted_terms = sorted(aggregated.items(), key=lambda x: (len(x[0]), x[0]))

    # Format output
    result = []
    first = True
    for var, coeff in sorted_terms:
        if coeff == 1 and not first:
            term = var
        elif coeff == -1 and not first:
            term = '-' + var
        elif coeff == 1 and first:
            term = var
        elif coeff == -1 and first:
            term = '-' + var
        else:
            term = str(coeff) + var

        if first:
            result.append(term)
            first = False
        else:
            if term.startswith('-'):
                result.append('-' + term[1:])
            else:
                result.append('+' + term)

    return ''.join(result)

def valid_mersenne(n):
    if n < 2:
        return False

    # Calculate 2^n - 1
    mersenne_number = (2 ** n) - 1

    # Check if the number is prime
    if mersenne_number < 2:
        return False

    # Efficient prime checking
    if mersenne_number == 2:
        return True

    if mersenne_number % 2 == 0:
        return False

    # Check odd divisors up to sqrt(mersenne_number)
    i = 3
    while i * i <= mersenne_number:
        if mersenne_number % i == 0:
            return False
        i += 2

    return True

from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    current_group = ""
    depth = 0

    for char in paren_string:
        if char == ' ':
            continue

        if char == '(':
            if depth == 0:
                current_group = ""
            current_group += char
            depth += 1
        elif char == ')':
            current_group += char
            depth -= 1
            if depth == 0:
                groups.append(current_group)

    return groups

