            # Get all possible moves for black king
            king_moves = get_king_moves(x, y)

            # Check if any move is safe
            safe_moves = []
            for move_x, move_y in king_moves:
                # Check if move is not adjacent to white king
                if not is_adjacent(move_x, move_y, king_x, king_y):
                    safe_moves.append((move_x, move_y))

            # If no safe moves, king is either checkmate or stalemate
            if not safe_moves:
                if is_under_attack:
                    # Checkmate
                    result[0] += 1
                else:
                    # Stalemate
                    result[2] += 1
            else:
                # King can move
                if is_under_attack:
                    # Check
                    result[1] += 1
                else:
                    # Safe
                    result[3] += 1

    return result

def getAllPrimeFactors(n):
    # Input validation
    if not isinstance(n, int) or n <= 0:
        return []

    # Edge cases
    if n == 1:
        return [1]
    if n == 2:
        return [2]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Input validation
    if not isinstance(n, int) or n <= 0:
        return [[], []]

    # Edge cases
    if n == 1:
        return [[1], [1]]
    if n == 2:
        return [[2], [1]]

    factors = getAllPrimeFactors(n)

    if not factors:
        return [[], []]

    unique_factors = []
    counts = []

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Input validation
    if not isinstance(n, int) or n <= 0:
        return []

    # Edge cases
    if n == 1:
        return [1]
    if n == 2:
        return [2]

    factor_counts = getUniquePrimeFactorsWithCount(n)
    unique_factors = factor_counts[0]
    counts = factor_counts[1]

    products = []

    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

def exchange_sort(sequence):
    if len(sequence) <= 1:
        return 0

    # Create target sorted sequence
    target = []
    count = [0, 0, 0]  # count[0] for 7s, count[1] for 8s, count[2] for 9s

    for num in sequence:
        if num == 7:
            count[0] += 1
        elif num == 8:
            count[1] += 1
        else:  # num == 9
            count[2] += 1

    # Build target sequence
    target = [7] * count[0] + [8] * count[1] + [9] * count[2]

    # Create position mapping for target
    pos_map = {}
    for i, num in enumerate(target):
        if num not in pos_map:
            pos_map[num] = []
        pos_map[num].append(i)

    # Create permutation array - where each element should go
    perm = [0] * len(sequence)
    for i, num in enumerate(sequence):
        # Get the next available position for this number in target
        pos = pos_map[num].pop(0)
        perm[i] = pos

    # Count cycles in permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i]:
            # Start a new cycle
            cycles += 1
            current = i

            while not visited[current]:
                visited[current] = True
                current = perm[current]

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, number) for sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract the numbers in the new order
    return [num for _, _, num in indexed_nums]

def sum_of_a_beach(text):
    if not text:
        return 0

    text_lower = text.lower()
    words = ["sand", "water", "fish", "sun"]
    count = 0
    i = 0

    while i < len(text_lower):
        for word in words:
            if text_lower.startswith(word, i):
                count += 1
                i += len(word)
                break
        else:
            i += 1

    return count

def encrypt(s):
    result = []
    for char in s:
        if 'a' <= char <= 'z':
            # Lowercase letters: shift by 4 with wrap-around
            shifted = chr(ord('a') + (ord(char) - ord('a') + 4) % 26)
            result.append(shifted)
        elif 'A' <= char <= 'Z':
            # Uppercase letters: shift by 4 with wrap-around
            shifted = chr(ord('A') + (ord(char) - ord('A') + 4) % 26)
            result.append(shifted)
        else:
            # Non-alphabetic characters remain unchanged
            result.append(char)
    return ''.join(result)

def automorphic(n):
