    square_str = str(square)

    # Check if the square ends with the same digits as the number
    if square_str.endswith(n_str):
        return "Automorphic"
    else:
        return "Not!!"

def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def is_on_board(row, col):
        return 0 <= row < 8 and 0 <= col < 8

    def is_adjacent(row1, col1, row2, col2):
        return abs(row1 - row2) <= 1 and abs(col1 - col2) <= 1

    def is_attacked_by_amazon(row, col, amazon_row, amazon_col):
        # Check queen-like moves (orthogonal and diagonal)
        # Horizontal and vertical
        if row == amazon_row:
            # Check if col is between amazon_col and col
            if col > amazon_col:
                for c in range(amazon_col + 1, col):
                    if is_on_board(row, c):
                        return False
            else:
                for c in range(col + 1, amazon_col):
                    if is_on_board(row, c):
                        return False
            return True
        elif col == amazon_col:
            # Check if row is between amazon_row and row
            if row > amazon_row:
                for r in range(amazon_row + 1, row):
                    if is_on_board(r, col):
                        return False
            else:
                for r in range(row + 1, amazon_row):
                    if is_on_board(r, col):
                        return False
            return True
        elif abs(row - amazon_row) == abs(col - amazon_col):
            # Diagonal move
            row_dir = 1 if row > amazon_row else -1
            col_dir = 1 if col > amazon_col else -1
            r, c = amazon_row + row_dir, amazon_col + col_dir
            while r != row and c != col:
                if is_on_board(r, c):
                    return False
                r += row_dir
                c += col_dir
            return True

        # Check knight-like moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dr, dc in knight_moves:
            if row == amazon_row + dr and col == amazon_col + dc:
                return True

        return False

    # Convert input to coordinates
    king_row, king_col = chess_to_coords(king)
    amazon_row, amazon_col = chess_to_coords(amazon)

    # Initialize counters
    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    # Iterate through all squares on the board
    for r in range(8):
        for c in range(8):
            # Skip if square is occupied by white king or amazon
            if (r == king_row and c == king_col) or (r == amazon_row and c == amazon_col):
                continue

            # Skip if square is adjacent to white king
            if is_adjacent(r, c, king_row, king_col):
                continue

            # Check if square is attacked by amazon
            attacked = is_attacked_by_amazon(r, c, amazon_row, amazon_col)

            # Count valid escape moves
            valid_moves = 0
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc

                    # Check if new position is on board
                    if not is_on_board(nr, nc):
                        continue

                    # Check if new position is occupied by white king or amazon
                    if (nr == king_row and nc == king_col) or (nr == amazon_row and nc == amazon_col):
                        continue

                    # Check if new position is adjacent to white king
                    if is_adjacent(nr, nc, king_row, king_col):
                        continue

                    # Check if new position is attacked by amazon
                    if is_attacked_by_amazon(nr, nc, amazon_row, amazon_col):
                        continue

                    valid_moves += 1

            # Classify position
            if attacked:
                if valid_moves == 0:
                    checkmate += 1
                else:
                    check += 1
            else:
                if valid_moves == 0:
                    stalemate += 1
                else:
                    safe += 1

    return [checkmate, check, stalemate, safe]

def compare(selector1, selector2):
    def get_specificity(selector):
        # Count the number of each type of selector
        id_count = selector.count('#')
        class_count = selector.count('.')
        tag_count = len(selector.split()) - id_count - class_count

        # Handle special case where selector contains only '*' (no specificity)
        if selector.strip() == '*':
            return (0, 0, 0)

        # Handle cases where selectors contain combined selectors like div#id or div.class
        # We need to count actual tag names, not just parts of combined selectors
        # Split by spaces and count non-id, non-class selectors (i.e., actual tag names)
        parts = selector.split()
        actual_tag_count = 0
        for part in parts:
            # If it's not an ID or class selector, it's a tag name
            if not part.startswith('#') and not part.startswith('.'):
                actual_tag_count += 1
            else:
                # If it's a combined selector like div#id or div.class, we still count the tag
                if '#' in part or '.' in part:
                    # Extract tag name before # or .
                    tag_part = part.split('#')[0].split('.')[0]
                    if tag_part and tag_part != '*':
                        actual_tag_count += 1

        # Special handling for combined selectors
        # Count actual tag names properly
        actual_tag_count = 0
        for part in selector.split():
            if part == '*':
                continue
            if part.startswith('#'):
                # This is an ID selector
                continue
            elif part.startswith('.'):
                # This is a class selector
                continue
            else:
                # This is a tag name
                actual_tag_count += 1

        # Count actual tag names correctly
        tag_count = 0
        parts = selector.split()
        for part in parts:
            if part != '*' and not part.startswith('#') and not part.startswith('.'):
                tag_count += 1
            elif part.startswith('#') or part.startswith('.'):
                # Check if it's a combined selector like div#id or div.class
                if '#' in part or '.' in part:
                    # Extract tag name part
                    tag_part = part.split('#')[0].split('.')[0]
                    if tag_part and tag_part != '*':
                        tag_count += 1

        # More robust tag counting
        tag_count = 0
        for part in selector.split():
            if part != '*':
                # If it's a tag name (not starting with # or .)
                if not part.startswith('#') and not part.startswith('.'):
                    tag_count += 1
                # If it's a combined selector like div#id or div.class
                elif '#' in part or '.' in part:
                    # Count the tag part
                    tag_part = part.split('#')[0].split('.')[0]
                    if tag_part and tag_part != '*':
                        tag_count += 1

        # Actually, let's do a cleaner approach:
        # Split by spaces, then for each part, determine its type
        id_count = 0
        class_count = 0
        tag_count = 0

        parts = selector.split()
        for part in parts:
            if part == '*':
                continue
            elif part.startswith('#'):
                id_count += 1
            elif part.startswith('.'):
                class_count += 1
            else:
                # This is a tag name
                tag_count += 1

        return (id_count, class_count, tag_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    if spec1 > spec2:
        return selector1
    else:
        return selector2

def pig_latin(word):
    if not word.isalpha():
        return None

    word = word.lower()
    vowels = 'aeiou'

    first_vowel_idx = -1
    for i, char in enumerate(word):
        if char in vowels:
            first_vowel_idx = i
            break

    if first_vowel_idx == 0:
        return word + "way"
    elif first_vowel_idx != -1:
        return word[first_vowel_idx:] + word[:first_vowel_idx] + "ay"
    else:
        return word + "ay"

