    # Generate all cyclic rotations of string1
    for i in range(len(string1)):
        rotated = string1[i:] + string1[:i]
        if string2 in rotated:
            return True

    return False

def fib4(n: int):
    # Base cases for n = 0, 1, 2, 3
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Initialize the last 4 values: fib4(0), fib4(1), fib4(2), fib4(3)
    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute from 4 to n
    for i in range(4, n + 1):
        next_val = a + b + c + d
        # Shift the window forward
        a, b, c, d = b, c, d, next_val

    return d

def median(l: list):
    if not l:
        return None

    sorted_list = sorted(l)
    n = len(sorted_list)

    if n % 2 == 1:
        # Odd length: return the middle element
        return sorted_list[n // 2]
    else:
        # Even length: return the average of the two middle elements
        mid1 = sorted_list[n // 2 - 1]
        mid2 = sorted_list[n // 2]
        return (mid1 + mid2) / 2.0

def is_balanced(string, pairs):
    # Create a mapping of opening to closing characters
    opening_to_closing = {}
    closing_to_opening = {}

    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        opening_to_closing[opening] = closing
        closing_to_opening[closing] = opening

    stack = []

    for char in string:
        # If it's an opening character, push it onto the stack
        if char in opening_to_closing:
            stack.append(char)
        # If it's a closing character
        elif char in closing_to_opening:
            # If stack is empty or the top doesn't match, it's unbalanced
            if not stack or stack[-1] != closing_to_opening[char]:
                return False
            # Pop the matching opening character
            stack.pop()

    # If stack is empty, all characters were balanced
    return len(stack) == 0

