    a, b, c, d = 0, 0, 2, 0

    for i in range(4, n + 1):
        next_val = a + b + c + d
        a, b, c, d = b, c, d, next_val

    return d

def is_balanced(s, pairs):
    # Step 1: Parse the pairs string into mappings
    opener_to_closer = {}
    closer_to_opener = {}

    for i in range(0, len(pairs), 2):
        opener = pairs[i]
        closer = pairs[i + 1]
        opener_to_closer[opener] = closer
        closer_to_opener[closer] = opener

    # Step 2: Process the input string
    stack = []
    relevant_chars = set(opener_to_closer.keys()) | set(closer_to_opener.keys())

    for char in s:
        # Skip characters not in our pair set
        if char not in relevant_chars:
            continue

        # If it's an opener, push to stack
        if char in opener_to_closer:
            stack.append(char)
        # If it's a closer
        else:
            # Check if stack is empty (unmatched closer)
            if not stack:
                return False

            # Pop from stack and verify it matches the expected opener
            last_opener = stack.pop()
            expected_opener = closer_to_opener[char]

            if last_opener != expected_opener:
                return False

    # Step 3: Final validation - stack must be empty
    return len(stack) == 0

def reverse_delete(s, c):
