    def get_amazon_attacks(amz_r, amz_c):
        attacked = set()

        # Queen moves (horizontal, vertical, diagonal)
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                r, c = amz_r, amz_c
                while True:
