def differentiate(poly, x_point):
    # Remove spaces
    poly = poly.replace(" ", "")

    if not poly:
        return 0

    # Split into terms based on + or - operators
    terms = []
    i = 0
    while i < len(poly):
        j = i + 1
        while j < len(poly) and poly[j] not in ['+', '-']:
            j += 1
        term = poly[i:j]
        terms.append(term)
        i = j

    total = 0

    for term in terms:
        if not term:
            continue

        # Parse coefficient and exponent from term
        if 'x' not in term:
            # Constant term (exponent = 0)
            coefficient = int(term)
            exponent = 0
        elif '^' in term:
            # Term with explicit exponent
            parts = term.split('^')
            x_part = parts[0]
            exponent = int(parts[1])

            if x_part == '' or x_part == '+':
                coefficient = 1
            elif x_part == '-':
                coefficient = -1
            else:
                coefficient = int(x_part)
        else:
            # Term with x but no explicit exponent (exponent = 1)
            exponent = 1
            if term == 'x' or term == '+x':
                coefficient = 1
            elif term == '-x':
                coefficient = -1
            else:
                # Find where x is located and extract coefficient
                x_index = term.find('x')
                coeff_part = term[:x_index]

                if coeff_part == '' or coeff_part == '+':
                    coefficient = 1
                elif coeff_part == '-':
                    coefficient = -1
                else:
                    coefficient = int(coeff_part)

        # Apply power rule: d/dx(coefficient * x^exponent)
        if exponent == 0:
            derivative_value = 0
        elif exponent == 1:
            derivative_value = coefficient
        else:
            derivative_value = coefficient * exponent * (x_point ** (exponent - 1))

        total += derivative_value

    return total

def compare(selector1, selector2):
    def get_specificity(selector):
        # Count ID, class, and tag selectors
        id_count = 0
        class_count = 0
        tag_count = 0

        # Split by spaces to get individual parts
        parts = selector.split()

        for part in parts:
            # Count ID selectors (#id)
            if part.startswith('#'):
                id_count += 1
            # Count class selectors (.class)
            elif part.startswith('.'):
                # Count each class in compound selectors like .foo.bar
                class_count += part.count('.')
            # Count tag selectors (tagname)
            else:
                # Handle compound selectors like div.foo.bar
                if '.' in part:
                    # Split by '.' to count tag and classes
                    tag_and_classes = part.split('.')
                    tag_count += 1  # At least one tag
                    class_count += len(tag_and_classes) - 1  # Add classes
                else:
                    tag_count += 1

        return (id_count, class_count, tag_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    # Compare specificity
    if spec1 > spec2:
        return selector1
    elif spec2 > spec1:
        return selector2
    else:
        # If specificity is equal, return the later one
        # In this context, we'll assume selector2 is later
        return selector2

