import re

def simplify(expression):
    # Extract all terms using regex
    # Pattern: optional sign, optional number, one or more lowercase letters
    terms = re.findall(r'[+-]?\d*[a-z]+', expression)

    if not terms:
        return "0"

    # Dictionary to store monomials: key = sorted variable string, value = coefficient
    monomials = {}

    for term in terms:
        # Find where variables start (after coefficient)
        var_start = 0
        for i, c in enumerate(term):
            if c.isalpha():
                var_start = i
                break

        # Extract coefficient
        coef_str = term[:var_start]
        if not coef_str or coef_str == '+':
            coef = 1
        elif coef_str == '-':
            coef = -1
        else:
            coef = int(coef_str)

        # Extract and sort variables
        variables = sorted(term[var_start:])
        var_key = ''.join(variables)

        # Combine like terms
        if var_key in monomials:
            monomials[var_key] += coef
        else:
            monomials[var_key] = coef

    # Remove zero coefficient monomials
    monomials = {k: v for k, v in monomials.items() if v != 0}

    if not monomials:
        return "0"

    # Sort monomials: first by number of variables, then lexicographically
    sorted_monomials = sorted(monomials.items(), key=lambda x: (len(x[0]), x[0]))

    # Format output
    result = []
    for i, (variables, coef) in enumerate(sorted_monomials):
        if i == 0:
            # First term
            if coef == 1 and variables:
                result.append(variables)
            elif coef == -1 and variables:
                result.append('-' + variables)
            elif coef == 1 and not variables:
                result.append('1')
            elif coef == -1 and not variables:
                result.append('-1')
            elif coef != 0:
                if coef > 0:
                    result.append(f'{coef}{variables}')
                else:
                    result.append(f'{coef}{variables}')
        else:
            # Subsequent terms
            if coef == 1 and variables:
                result.append('+' + variables)
            elif coef == -1 and variables:
                result.append('-' + variables)
            elif coef == 1 and not variables:
                result.append('+1')
            elif coef == -1 and not variables:
                result.append('-1')
            elif coef > 0:
                result.append(f'+{coef}{variables}')
            else:
                result.append(f'{coef}{variables}')

    return ''.join(result)

def getAllPrimeFactors(n):
    # Check if n is a number type (exclude bool)
    if isinstance(n, bool) or not isinstance(n, (int, float)):
        return []

    # Convert float to int if it's a whole number, otherwise reject
    if isinstance(n, float):
        if n != int(n):
            return []
        n = int(n)

    # Check if n is positive
    if n <= 0:
        return []

    # Handle n=1 as special case
    if n == 1:
        return [1]

    factors = []

    # Trial division starting from 2
    factor = 2
    while factor * factor <= n:
        while n % factor == 0:
            factors.append(factor)
            n //= factor
        factor += 1

    # If n > 1 after all divisions, it's a prime factor
    if n > 1:
        factors.append(n)

    return factors

