import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Handle negative numbers
    is_negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            # Round the remainder to nearest integer to handle floating point errors
            remainder = round(remainder)
            if remainder >= base:
                remainder = base - 1
            elif remainder < 0:
                remainder = 0
            integer_digits.append(remainder)
            temp = (temp - remainder) / base
            # Round the quotient to handle floating point errors
            temp = round(temp)

    integer_digits.reverse()

    # Handle the case where integer part is 0
    if not integer_digits:
        integer_result = "0"
    else:
        integer_result = ""
        for digit in integer_digits:
            if digit < 10:
                integer_result += str(digit)
            else:
                integer_result += chr(ord('A') + digit - 10)

    # Convert fractional part
    fractional_digits = []
    if decimals > 0:
        temp_fractional = fractional_part
        tolerance = 1e-15

        for _ in range(decimals):
            if temp_fractional < tolerance:
                fractional_digits.append(0)
                continue

            product = temp_fractional * base
            digit = int(product)
            # Round the digit to handle floating point errors
            digit = round(digit)
            if digit >= base:
                digit = base - 1
            elif digit < 0:
                digit = 0
            fractional_digits.append(digit)
            temp_fractional = product - digit

    # Build result
    result = integer_result
    if decimals > 0 and fractional_digits:
        result += "."
        for digit in fractional_digits:
            if digit < 10:
                result += str(digit)
            else:
                result += chr(ord('A') + digit - 10)

    # Handle negative sign
    if is_negative:
        result = "-" + result

    # Special case for numbers less than 1
    if number < 1 and decimals == 0:
        # If we have a fractional part but no decimals requested, 
        # we should return "0" for the integer part
        if result.startswith("0") and "." in result:
            result = result[1:]  # Remove leading zero

    return result

