    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    if base == math.pi:
        # Special handling for pi base
        digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % 1
            if remainder >= 0.5:
                digit = 1
            else:
                digit = 0
            digits.append(str(digit))
            temp = (temp - digit) / math.pi
        # Reverse the digits since we built them backwards
        integer_result = ''.join(reversed(digits))
    else:
        # Standard base conversion for integer bases
        digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % int(base)
            if remainder < 10:
                digits.append(str(remainder))
            else:
                digits.append(chr(ord('A') + remainder - 10))
            temp //= int(base)
        integer_result = ''.join(reversed(digits))

    # Handle fractional part
    fractional_part = number - integer_part
    if decimals == 0:
        result = integer_result
    else:
        fractional_digits = []
        temp_fraction = fractional_part
        for _ in range(decimals):
            temp_fraction *= base
            digit = int(temp_fraction)
            if digit < 10:
                fractional_digits.append(str(digit))
            else:
                fractional_digits.append(chr(ord('A') + digit - 10))
            temp_fraction -= digit
        fractional_result = ''.join(fractional_digits)
        result = integer_result + '.' + fractional_result

    # Handle negative numbers
    if negative:
        result = '-' + result

    # Handle leading zero for values < 1
    if number < 1 and not negative:
        if '.' not in result:
            result = '0.' + result
        else:
            # Check if we need to add leading zero before decimal point
            parts = result.split('.')
            if len(parts[0]) == 0:
                result = '0.' + parts[1]

    return result

def getAllPrimeFactors(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    if not isinstance(n, int) or n <= 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)
    unique_factors = []
    counts = []

    if not factors:
        return [[], []]

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    factor_counts = getUniquePrimeFactorsWithCount(n)
    unique_factors = factor_counts[0]
    counts = factor_counts[1]

    products = []
    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

