def check_if_last_char_is_a_letter(txt):
    # Check if string is empty
    if not txt:
        return False

    # Find the last non-space character
    last_char = None
    for i in range(len(txt) - 1, -1, -1):
        if txt[i] != ' ':
            last_char = txt[i]
            break

    # If no non-space character found (shouldn't happen with our loop)
    if last_char is None:
        return False

    # Check if the last non-space character is alphabetical
    if not last_char.isalpha():
        return False

    # Find the position of this last character
    last_char_pos = -1
    for i in range(len(txt) - 1, -1, -1):
        if txt[i] == last_char:
            last_char_pos = i
            break

    # If this is the only character in the string, it's standalone
    if len(txt) == 1:
        return True

    # If the last character is at the beginning of the string, it's standalone
    if last_char_pos == 0:
        return True

    # Check if the character before it is a space (meaning it's standalone)
    return txt[last_char_pos - 1] == ' '

def fib4(n):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize the first four values
    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute fib4(n)
    for i in range(4, n + 1):
        next_val = a + b + c + d
        # Slide the window
        a, b, c, d = b, c, d, next_val

    return d

