    mersenne = (1 << n) - 1  # This is 2^n - 1

    # For large numbers, we use a more efficient primality test
    # Simple trial division for smaller numbers
    if mersenne < 1000000:
        # For numbers up to about 1 million, simple trial division is fine
        if mersenne < 2:
            return False
        if mersenne == 2:
            return True
        if mersenne % 2 == 0:
            return False
        for i in range(3, int(mersenne**0.5) + 1, 2):
            if mersenne % i == 0:
                return False
        return True

    # For larger numbers, we use a more sophisticated approach
    # But given the constraint (n up to 2000), 2^n - 1 can be very large
    # Let's use a known list of Mersenne primes for efficiency
    # Mersenne primes are 2^p - 1 where p is prime and 2^p - 1 is prime
    # Known Mersenne primes for small exponents
    known_mersenne_primes = {
