    s = s.replace(' ', '')

    result = []
    stack = []
    start = 0

    for i, char in enumerate(s):
        if char == '(':
            stack.append(char)
        elif char == ')':
            stack.pop()

        # When stack is empty, we've found a complete group
        if not stack:
