        # Check if position is under attack by amazon
        if pos in amazon_moves:
            return False
        return True

    def can_escape(pos, white_king, amazon_moves):
        king_moves = get_king_moves(pos)
        for move in king_moves:
            if is_safe(move, white_king, amazon_moves):
                return True
        return False

    # Convert input to coordinates
    white_king_pos = chess_to_coords(king)
    amazon_pos = chess_to_coords(amazon)

    # Get all squares amazon can attack
    amazon_moves = get_amazon_moves(amazon_pos)

    # Initialize counters
    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    # Check all possible positions for black king
    for i in range(8):
