def getAllPrimeFactors(n):
    if not isinstance(n, (int, float)):
        return []
    if isinstance(n, float) and not n.is_integer():
        return []
    if n <= 0:
        return []
    if n == 1:
        return [1]

    factors = []
    n = int(n)

    while n % 2 == 0:
        factors.append(2)
        n //= 2

    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 2

    if n > 1:
        factors.append(n)

    return factors


