def sum_of_squares(n):
    # Step 1: Check if n is a perfect square (answer = 1)
    root = int(n**0.5)
    if root * root == n:
        return 1

    # Step 2: Check if n can be written as sum of two squares (answer = 2)
    for i in range(1, root + 1):
        remainder = n - i * i
        r = int(remainder**0.5)
        if r * r == remainder:
            return 2

    # Step 3: Check Legendre's three-square theorem condition
    # A number needs 4 squares iff it's of form 4^a(8b + 7)
    temp = n
    while temp % 4 == 0:
        temp //= 4

    if temp % 8 == 7:
        return 4

    # Otherwise, by Lagrange's four-square theorem, answer is 3
    return 3

def differentiate(polynomial, x):
    # Parse the polynomial into terms
    # Handle the case where there's no + or - in the string
    if polynomial[0] != '-':
        polynomial = '+' + polynomial

    # Split by + and - signs
    terms = []
    current_term = ""

    for i, char in enumerate(polynomial):
        if char in ['+', '-'] and i > 0:
            terms.append(current_term)
            current_term = char
        else:
            current_term += char

    terms.append(current_term)

    # Process each term
    derivative_terms = []

    for term in terms:
        if not term:
            continue

        # Remove leading + or -
        if term[0] in ['+', '-']:
            sign = -1 if term[0] == '-' else 1
            term = term[1:]
        else:
            sign = 1

        # Handle the case of just 'x' or 'x^1'
        if term == 'x':
            derivative_terms.append('1')
        elif term == 'x^1':
            derivative_terms.append('1')
        elif term.startswith('x^'):
            # Extract exponent
            exp = int(term[2:])
            if exp == 1:
                derivative_terms.append('1')
            else:
                derivative_terms.append(f'{exp}x^{exp-1}')
        elif term == 'x^0':
            derivative_terms.append('0')
        elif 'x^' in term:
