def getAllPrimeFactors(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    if not isinstance(n, int) or n <= 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)
    unique_factors = []
    counts = []

    if not factors:
        return [[], []]

    current_factor = factors[0]
    count = 0

    for factor in factors:
        if factor == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factor
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    unique_factors, counts = getUniquePrimeFactorsWithCount(n)
    products = []

    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    # For 2^n - 1 to be a Mersenne prime, n must be prime
    if not is_prime(n):
        return False

    # Calculate 2^n - 1
    mersenne = (1 << n) - 1

    # Check if the Mersenne number is prime
    return is_prime(mersenne)

