def valid_mersenne(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    # Check if n is prime using trial division
    is_n_prime = True
    i = 3
    while i * i <= n:
        if n % i == 0:
            is_n_prime = False
            break
        i += 2

    if not is_n_prime:
        return False

    # Lucas-Lehmer test for Mersenne numbers
    mp = (1 << n) - 1
    s = 4
    for _ in range(n - 1):
        s = (s * s - 2) % mp

    return s == 0

