    terms = re.findall(r'[+-][^\+\-]+', poly_str)

    if not terms:
        return 0

    result = 0

    for term in terms:
        sign = 1 if term[0] == '+' else -1
        term_body = term[1:]

        if not term_body:
            continue

        # Parse coefficient and exponent
        if 'x' not in term_body:
            # Constant term
            coeff = int(term_body)
            exponent = 0
        else:
            # Split by x (at most 1 split to handle edge cases)
            parts = term_body.split('x', 1)

            # Parse coefficient
            coeff_part = parts[0]
            if coeff_part == '' or coeff_part == '+':
                coeff = 1
            elif coeff_part == '-':
                coeff = -1
            else:
                coeff = int(coeff_part)

            # Parse exponent
            exponent_part = parts[1] if len(parts) > 1 else ''
            if not exponent_part:
                exponent = 1
            elif exponent_part.startswith('^'):
                exponent = int(exponent_part[1:])
            else:
                exponent = 1

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent == 0:
            derivative_value = 0
        elif exponent == 1:
            derivative_value = coeff * sign
