    lines = text.split('\n')
    result_lines = []

    for line in lines:
        # Find the first occurrence of any comment marker
        min_pos = len(line)  # Default to end of line (no truncation)

        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < min_pos:
