            for c in range(min_c + 1, max_c):
                if (ar, c) == white_king:
                    blocked = True
                    break
            if not blocked:
                return True

        # Queen moves: same column
        if col == ac:
            min_r = min(row, ar)
            max_r = max(row, ar)
            blocked = False
            for r in range(min_r + 1, max_r):
                if (r, ac) == white_king:
                    blocked = True
                    break
            if not blocked:
                return True

        # Queen moves: diagonal
        if abs(row - ar) == abs(col - ac):
            dr = 1 if row > ar else -1
            dc = 1 if col > ac else -1
            r, c = ar + dr, ac + dc
            blocked = False
            while (r, c) != (row, col):
                if (r, c) == white_king:
                    blocked = True
                    break
                r += dr
                c += dc
            if not blocked:
                return True

        # Knight moves
        knight_moves = [
            (-2, -1), (-2, 1), (-1, -2), (-1, 2),
            (1, -2), (1, 2), (2, -1), (2, 1)
        ]
        for dr, dc in knight_moves:
            nr, nc = ar + dr, ac + dc
            if (nr, nc) == (row, col):
                return True

        return False

    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    for row in range(8):
        for col in range(8):
            if (row, col) == white_king or (row, col) == white_amazon:
                continue
            if is_adjacent((row, col), white_king):
                continue

            attacked = is_attacked(row, col)
            escape_count = 0

            for adj_r, adj_c in get_adjacent_squares(row, col):
                if (adj_r, adj_c) == white_king or (adj_r, adj_c) == white_amazon:
                    continue
                if is_adjacent((adj_r, adj_c), white_king):
                    continue
                if not is_attacked(adj_r, adj_c):
                    escape_count += 1

            if attacked:
                if escape_count == 0:
                    checkmate += 1
                else:
                    check += 1
            else:
                if escape_count == 0:
                    stalemate += 1
                else:
                    safe += 1

    return [checkmate, check, stalemate, safe]

def poohbear(code):
    # Initialize memory and pointer
    memory = {}
    pointer = 0
    copied = 0
    ip = 0
    output = []

    # Find all loop pairs
    loop_stack = []
    loop_pairs = {}
    for i, char in enumerate(code):
        if char == 'W':
            loop_stack.append(i)
        elif char == 'E':
            start = loop_stack.pop()
            loop_pairs[start] = i
            loop_pairs[i] = start

    # Execute code
    while ip < len(code):
        char = code[ip]

        if char == '+':
            memory[pointer] = memory.get(pointer, 0) + 1
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == '-':
            memory[pointer] = memory.get(pointer, 0) - 1
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copied = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copied
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                ip = loop_pairs[ip]
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                ip = loop_pairs[ip]
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif char == 'T':
            memory[pointer] = memory.get(pointer, 0) * 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'Q':
            memory[pointer] = memory.get(pointer, 0) ** 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'U':
            import math
            memory[pointer] = int(math.sqrt(memory.get(pointer, 0)))
        elif char == 'L':
            memory[pointer] = memory.get(pointer, 0) + 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'V':
            memory[pointer] = memory.get(pointer, 0) // 2
        elif char == 'A':
            memory[pointer] = memory.get(pointer, 0) + copied
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'B':
            memory[pointer] = memory.get(pointer, 0) - copied
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'Y':
            memory[pointer] = memory.get(pointer, 0) * copied
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'D':
            if copied != 0:
                memory[pointer] = memory.get(pointer, 0) // copied
            else:
                memory[pointer] = 0

        ip += 1

    return ''.join(output)

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 365 * 24 * 60 * 60),
        ('day', 24 * 60 * 60),
        ('hour', 60 * 60),
        ('minute', 60),
        ('second', 1)
    ]

    # Calculate each unit
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            if count > 1:
                components.append(f"{count} {unit_name}s")
            else:
                components.append(f"{count} {unit_name}")

    # Format the output
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

def parse_int(s):
    s = s.lower()
    s = s.replace('-', ' ')
    words = [w for w in s.split() if w and w != 'and']

    ones = {"zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, 
            "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9}
    teens = {"ten": 10, "eleven": 11, "twelve": 12, "thirteen": 13, "fourteen": 14,
             "fifteen": 15, "sixteen": 16, "seventeen": 17, "eighteen": 18, "nineteen": 19}
    tens = {"twenty": 20, "thirty": 30, "forty": 40, "fifty": 50, 
            "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90}

    num_map = {**ones, **teens, **tens}

    total = 0
    current = 0

    for word in words:
        if word in num_map:
            current += num_map[word]
        elif word == "hundred":
            current *= 100
        elif word == "thousand":
            total += current * 1000
            current = 0
        elif word == "million":
            total += current * 1000000
            current = 0

    total += current
    return total

