import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    result = []

    if integer_part == 0:
        result = ['0']
    else:
        while integer_part > 0:
            quotient = int(integer_part / base)
            remainder = integer_part - (quotient * base)

            # Ensure remainder is positive
            if remainder < 0:
                remainder += base
                quotient -= 1

            # Convert remainder to digit
            if remainder >= 10:
                digit = chr(ord('A') + int(remainder) - 10)
            else:
                digit = str(int(remainder))

            result.append(digit)
            integer_part = quotient

        result.reverse()

    # Handle fractional part
    fractional_part = number - int(number)
    if decimals > 0 and fractional_part > 0:
        result.append('.')
        for _ in range(decimals):
            fractional_part *= base
            digit_value = int(fractional_part)

            if digit_value >= 10:
                digit = chr(ord('A') + digit_value - 10)
            else:
                digit = str(digit_value)

            result.append(digit)
            fractional_part -= digit_value
    elif decimals > 0:
        result.append('.')
        result.extend(['0'] * decimals)

    # Join the result
    final_result = ''.join(result)

    # Add negative sign if needed
    if negative:
        final_result = '-' + final_result

    # Handle case where result is less than 1 and needs leading zero
    if final_result.startswith('.'):
        final_result = '0' + final_result

    return final_result

def is_balanced(string_to_validate, pairs_string):
    # Handle empty inputs
    if not string_to_validate:
        return True

    # Build the mapping from closing to opening characters
    # Based on examples: even indices (0, 2, 4...) are opening, odd indices (1, 3, 5...) are closing
    closing_to_opening = {}
    opening_chars = set()

    for i in range(0, len(pairs_string), 2):
        if i + 1 < len(pairs_string):
            opening_char = pairs_string[i]
            closing_char = pairs_string[i + 1]
            opening_chars.add(opening_char)
            closing_to_opening[closing_char] = opening_char

    # Use a stack to track opening characters
    stack = []

    for char in string_to_validate:
        if char in opening_chars:
            # It's an opening character, push to stack
            stack.append(char)
        elif char in closing_to_opening:
            # It's a closing character, check if it matches the most recent opening
            if not stack:
                return False
            if stack[-1] != closing_to_opening[char]:
                return False
            stack.pop()
        # Characters not in pairs_string are ignored

    # Check if all opening characters have been closed
    return len(stack) == 0

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, value) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract just the values from the sorted pairs
    return [num for _, _, num in indexed_nums]

