def differentiate(polynomial, point):
    # Parse the polynomial into terms
    # Handle the case where there's no + or - in the string
    if '+' in polynomial:
        terms = polynomial.split('+')
    else:
        terms = [polynomial]

    # Split terms by - (but keep the minus sign with negative terms)
    expanded_terms = []
    for term in terms:
        if '-' in term and term != '-':
            # Split by - but keep the minus sign
            parts = term.split('-')
            expanded_terms.append(parts[0])
            for part in parts[1:]:
                expanded_terms.append('-' + part)
        else:
            expanded_terms.append(term)

    # Remove empty strings
    expanded_terms = [term for term in expanded_terms if term]

    # Parse each term
    parsed_terms = []
    for term in expanded_terms:
        # Handle negative terms
        is_negative = False
        if term.startswith('-'):
            is_negative = True
            term = term[1:]

        # Parse coefficient and exponent
        if 'x^' in term:
            # Format: ax^n
            parts = term.split('x^')
            coeff_str = parts[0]
            if coeff_str == '':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)
            if is_negative:
                coeff = -coeff
            exponent = int(parts[1])
            parsed_terms.append((coeff, exponent))
        elif 'x' in term:
            # Format: ax or ax^1
            if term == 'x':
                coeff = 1
                exponent = 1
            elif term == '-x':
                coeff = -1
                exponent = 1
            else:
                coeff_str = term.replace('x', '')
                if coeff_str == '':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str)
                exponent = 1
            if is_negative:
                coeff = -coeff
            parsed_terms.append((coeff, exponent))
        else:
            # Format: constant term
            coeff = int(term)
            exponent = 0
            parsed_terms.append((coeff, exponent))

    # Differentiate each term
    derivative_terms = []
    for coeff, exponent in parsed_terms:
        if exponent == 0:
            # Derivative of constant is 0
            derivative_terms.append((0, 0))
        else:
            # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
            new_coeff = coeff * exponent
            new_exponent = exponent - 1
            derivative_terms.append((new_coeff, new_exponent))

    # Evaluate the derivative at the given point
    result = 0
    for coeff, exponent in derivative_terms:
        if exponent == 0:
            result += coeff
        else:
            result += coeff * (point ** exponent)

    return result

def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into terms
    # Split by + and - signs, keeping the signs
    terms = re.findall(r'[+-]?[^+-]+', expression)

    # Dictionary to store monomial -> coefficient mapping
    monomial_coeffs = defaultdict(int)

    for term in terms:
        # Handle the sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Parse the coefficient and monomial
        if 'x' in term:
            # Find coefficient (everything before the first 'x')
            coeff_str = ''
            i = 0
            while i < len(term) and term[i] != 'x':
                coeff_str += term[i]
                i += 1

            if coeff_str == '' or coeff_str == '+':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)

            # Get the remaining part (the monomial without coefficient)
            monomial_part = term[i:]
        else:
            # No 'x' means it's a constant or just a variable
            if term == '':
                coeff = 0
            else:
                coeff = int(term) if term.lstrip('+-').isdigit() else 1
            monomial_part = ''

        # Apply sign to coefficient
        coeff *= sign

        # Normalize monomial (sort variables)
        if monomial_part:
            sorted_vars = ''.join(sorted(monomial_part))
        else:
            sorted_vars = ''

        # Add to dictionary
        monomial_coeffs[sorted_vars] += coeff

    # Remove zero coefficients
    monomial_coeffs = {m: c for m, c in monomial_coeffs.items() if c != 0}

    # Sort monomials by number of variables, then lexicographically
    sorted_monomials = sorted(monomial_coeffs.items(), 
                              key=lambda x: (len(x[0]), x[0]))

    # Format output
    result = []
    for i, (monomial, coeff) in enumerate(sorted_monomials):
        if coeff == 1 and monomial != '':
            term = monomial
        elif coeff == -1 and monomial != '':
            term = '-' + monomial
        else:
            term = str(coeff) + monomial

        # Add sign
        if i == 0:
            result.append(term)
        else:
            if term.startswith('-'):
                result.append('-' + term[1:])
            else:
                result.append('+' + term)

    # Join and remove leading +
    output = ''.join(result)
    if output.startswith('+'):
        output = output[1:]

    return output

def is_valid(identifier):
    # Check if the string is empty
    if not identifier:
        return False

    # Check if the first character is valid (letter, underscore, or dollar sign)
    first_char = identifier[0]
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Check if all remaining characters are valid (letters, digits, underscores, or dollar signs)
    for char in identifier[1:]:
        if not (char.isalnum() or char == '_' or char == '$'):
            return False

    # If all checks pass, the identifier is valid
    return True

