def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)

def differentiate(polynomial, x):
    import re

    def parse_term(term):
        """Parse a term to extract coefficient and exponent"""
        if 'x' not in term:
            # Constant term (exponent 0)
            return int(term), 0

        if '^' in term:
            # Has explicit exponent
            coeff_part, exp_part = term.split('^')
            exp = int(exp_part)
            # Determine coefficient
            if coeff_part == '' or coeff_part == '+':
                coeff = 1
            elif coeff_part == '-':
                coeff = -1
            else:
                coeff = int(coeff_part)
        else:
            # No exponent means exponent is 1
            exp = 1
            # Determine coefficient
            if term == 'x' or term == '+x':
                coeff = 1
            elif term == '-x':
                coeff = -1
            else:
                # Remove 'x' and parse coefficient
                coeff = int(term[:-1])

        return coeff, exp

    # Find all terms using regex
    # Pattern matches: optional sign, optional digits, x, optional exponent
    terms = re.findall(r'[+-]?\d*x(?:\^\d+)?|[+-]?\d+', polynomial)

    result = 0

    for term in terms:
        coeff, exp = parse_term(term)
        # Apply power rule: d/dx(ax^n) = n*a*x^(n-1)
        if exp > 0:
            result += exp * coeff * (x ** (exp - 1))
        # If exp == 0 (constant term), derivative is 0

    return result

