def converter(number, from_base, to_base):
    # Convert from the original base to decimal
    decimal_value = 0
    for digit in number:
        if digit.isdigit():
            digit_value = int(digit)
        else:
            digit_value = ord(digit.upper()) - ord('A') + 10

        if digit_value >= from_base:
            raise ValueError("Invalid digit for the given base")

        decimal_value = decimal_value * from_base + digit_value

    # Convert from decimal to the target base
    if decimal_value == 0:
        return "0"

    result = ""
    while decimal_value > 0:
        remainder = decimal_value % to_base
        if remainder < 10:
            result = str(remainder) + result
        else:
            result = chr(ord('A') + remainder - 10) + result
        decimal_value //= to_base

    return result

def count_divisors(n):
    if n == 1:
        return 1

    k = int(n**0.5)
    total = 0

    for i in range(1, k + 1):
        total += n // i

    return 2 * total - k * k

def sum_of_a_beach(s):
