def proper_fractions(d):
    """
    Counts the number of proper fractions with denominator d.
    This is equivalent to computing Euler's totient function φ(d).
    """
    if d == 1:
        return 0

    result = d
    n = d

    # Check for factor 2
    if n % 2 == 0:
        result = result // 2 * 1  # result = result * (1 - 1/2)
        while n % 2 == 0:
            n //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result = result // i * (i - 1)  # result = result * (1 - 1/i)
            while n % i == 0:
                n //= i
        i += 2

    # If n > 1, then it's a prime factor
    if n > 1:
        result = result // n * (n - 1)

    return result

def count_divisors(n):
    if n == 0:
        return 0

    sqrt_n = int(n ** 0.5)

    # Calculate sum of floor(n/i) for i from 1 to sqrt_n
    total = 0
    for i in range(1, sqrt_n + 1):
        total += n // i

    # Apply the formula: 2 * sum - sqrt_n^2
    return 2 * total - sqrt_n * sqrt_n

def amazonCheckmate(king, amazon):
    def pos_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def coords_to_pos(x, y):
        return chr(x + ord('a')) + str(y + 1)

    def is_valid(x, y):
        return 0 <= x < 8 and 0 <= y < 8

    def is_adjacent(x1, y1, x2, y2):
        return abs(x1 - x2) <= 1 and abs(y1 - y2) <= 1

    def get_amazon_threats(amazon_x, amazon_y):
        threats = set()

        # Queen moves (rook + bishop)
        # Horizontal and vertical
        for i in range(8):
            if i != amazon_x:
                threats.add((i, amazon_y))
        for j in range(8):
            if j != amazon_y:
                threats.add((amazon_x, j))

        # Diagonal moves
        for i in range(1, 8):
            if is_valid(amazon_x + i, amazon_y + i):
                threats.add((amazon_x + i, amazon_y + i))
            if is_valid(amazon_x - i, amazon_y + i):
                threats.add((amazon_x - i, amazon_y + i))
            if is_valid(amazon_x + i, amazon_y - i):
                threats.add((amazon_x + i, amazon_y - i))
            if is_valid(amazon_x - i, amazon_y - i):
                threats.add((amazon_x - i, amazon_y - i))

        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            new_x, new_y = amazon_x + dx, amazon_y + dy
            if is_valid(new_x, new_y):
                threats.add((new_x, new_y))

        return threats

    def get_king_moves(x, y):
        moves = []
        for i in range(-1, 2):
            for j in range(-1, 2):
                if i == 0 and j == 0:
                    continue
                new_x, new_y = x + i, y + j
                if is_valid(new_x, new_y):
                    moves.append((new_x, new_y))
        return moves

    king_x, king_y = pos_to_coords(king)
    amazon_x, amazon_y = pos_to_coords(amazon)

    amazon_threats = get_amazon_threats(amazon_x, amazon_y)

    # Find all valid black king positions (not adjacent to white king)
    valid_positions = []
    for x in range(8):
        for y in range(8):
            if not is_adjacent(king_x, king_y, x, y):
                valid_positions.append((x, y))

    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    for bx, by in valid_positions:
        # Check if black king is under threat
        is_threatened = (bx, by) in amazon_threats

        if is_threatened:
            # Check if it's checkmate
            king_moves = get_king_moves(bx, by)
            safe_moves = 0

            for move_x, move_y in king_moves:
                # Check if the move is valid (not adjacent to white king)
                if not is_adjacent(king_x, king_y, move_x, move_y):
                    # Check if the new position is threatened by amazon
                    if (move_x, move_y) not in amazon_threats:
                        safe_moves += 1

            if safe_moves == 0:
                checkmate += 1
            else:
                check += 1
        else:
            # King is safe
            king_moves = get_king_moves(bx, by)
            safe_moves = 0

            for move_x, move_y in king_moves:
                # Check if the move is valid (not adjacent to white king)
                if not is_adjacent(king_x, king_y, move_x, move_y):
                    # Check if the new position is threatened by amazon
                    if (move_x, move_y) not in amazon_threats:
                        safe_moves += 1

            if safe_moves == 0:
                stalemate += 1
            else:
                safe += 1

    return [checkmate, check, stalemate, safe]

