import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle sign
    is_negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Build integer part
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            integer_digits.append(temp % int(base))
            temp //= int(base)
        integer_digits.reverse()

    # Convert fractional part
    fractional_digits = []
    if decimals > 0:
        temp_fraction = fractional_part
        for _ in range(decimals):
            temp_fraction *= base
            digit = int(temp_fraction)
            fractional_digits.append(digit)
            temp_fraction -= digit

    # Build result string
    digit_map = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    integer_str = ''.join(digit_map[d] for d in integer_digits) if integer_digits else '0'

    if not fractional_digits:
        result = integer_str
    else:
        fractional_str = ''.join(digit_map[d] for d in fractional_digits)
        result = integer_str + '.' + fractional_str

    # Handle negative sign
    if is_negative:
        result = '-' + result

    # Handle case where integer part is 0 but number is not 0 (i.e., result < 1)
    if not is_negative and integer_part == 0 and number < 1:
        if decimals == 0:
            result = '0' + result[1:]  # Replace leading 0 with 0
        else:
            # Ensure we have a leading 0 before decimal point
            if not result.startswith('0'):
                result = '0' + result

    return result

def smallest_change(arr):
