def string_xor(a: str, b: str) -> str:
    result = []
    for i in range(len(a)):
        if a[i] != b[i]:
            result.append('1')
        else:
            result.append('0')
    return ''.join(result)

def valid_mersenne(n):
    """Check if 2^n - 1 is a Mersenne prime"""
    # Handle edge cases
    if n < 2:
        return False

    # Necessary condition: n must be prime
    # For small n (up to 2000), trial division is efficient
    if n == 2:
        return True  # M_2 = 3 is prime
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False

    # Compute M_n = 2^n - 1
    m = (1 << n) - 1

    # Lucas-Lehmer test for Mersenne primes (works for n >= 3)
    s = 4
    for _ in range(n - 2):
        s = (s * s - 2) % m

    return s == 0

def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        # Check if i is a palindrome
        if str(i) == str(i)[::-1]:
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def converter(number, decimals=0, base=3.141592653589793):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Split into integer and fractional parts
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_result = ''
    else:
        digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        integer_result = ''
        while integer_part > 0:
            remainder = integer_part % base
            # Handle floating point precision issues
            if remainder >= base:
                remainder = base - 1e-10
            elif remainder < 0:
                remainder = 0
            integer_result = digits[int(round(remainder))] + integer_result
            integer_part = int((integer_part - remainder) / base)

    # Convert fractional part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            # Handle floating point precision issues
            if digit >= base:
                digit = int(base - 1e-10)
            elif digit < 0:
                digit = 0
            fractional_result += str(digit)
            fractional_part -= digit

    # Combine results
    result = integer_result + fractional_result

    # Handle negative sign
    if negative:
        result = '-' + result

    # Ensure leading zero for numbers less than 1
    if result.startswith('.'):
        result = '0' + result

    return result

from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    # Validate that input is a list
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list")

    # Validate that all elements are integers (but not booleans)
    for num in numbers:
        if isinstance(num, bool) or not isinstance(num, int):
            raise TypeError("All elements must be integers")

    # Handle empty list
    if len(numbers) == 0:
        return (0, 1)

    # Calculate sum and product
    total_sum = 0
    total_product = 1

    for num in numbers:
        total_sum += num
        total_product *= num

    return (total_sum, total_product)

