def compare(selector1, selector2):
    def get_specificity(selector):
        # Count the number of each type of selector
        id_count = selector.count('#')
        class_count = selector.count('.')
        tag_count = len([part for part in selector.split() if part and not part.startswith(('#', '.')) and part != '*'])

        # Handle the case where there are no tag names but there are other selectors
        # This is a bit tricky - we need to count actual tag names
        if tag_count == 0 and not selector.startswith(('#', '.')) and '*' not in selector:
            # If selector is just a tag name
            tag_count = 1
        elif tag_count == 0:
            # If selector has no tag names but has other selectors, we still count it
            # but we need to be more careful about this
            parts = selector.split()
            tag_count = sum(1 for part in parts if part and not part.startswith(('#', '.')) and part != '*')

        # Special case for "*" selector
        if selector.strip() == '*':
            return (0, 0, 0)

        # Count tag names properly
        tag_names = []
        for part in selector.split():
            if part and not part.startswith(('#', '.')) and part != '*':
                tag_names.append(part)

        tag_count = len(tag_names)

        # If no tag names and no other selectors, it's just a tag
        if tag_count == 0 and id_count == 0 and class_count == 0:
            if selector.strip() == '*':
                return (0, 0, 0)
            elif selector.strip():
                tag_count = 1

        # If it's just a tag name (no # or .)
        if id_count == 0 and class_count == 0 and '*' not in selector and not any(part.startswith(('#', '.')) for part in selector.split()):
            if selector.strip() != '*':
                tag_count = 1
        elif id_count == 0 and class_count == 0 and '*' in selector:
            tag_count = 0
        elif id_count == 0 and class_count == 0:
            tag_count = 1

        # Handle the case where we have a complex selector
        # Let's recompute properly
        tag_count = 0
        class_count = 0
        id_count = 0

        # Split by spaces to get individual parts
        parts = selector.split()
        for part in parts:
            if part == '*':
                continue
            elif part.startswith('#'):
                id_count += 1
            elif part.startswith('.'):
                class_count += 1
            else:
                # It's a tag name
                tag_count += 1

        return (id_count, class_count, tag_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    if spec1 > spec2:
        return selector1
    else:
        return selector2

def histogram(s):
    if not s:
        return {}

    # Split the string and count frequencies
    letters = s.split()
    freq = {}
    for letter in letters:
        freq[letter] = freq.get(letter, 0) + 1

    # Find the maximum frequency
    max_freq = max(freq.values())

    # Return all letters with maximum frequency
    return {letter: count for letter, count in freq.items() if count == max_freq}

def amazon_check_mate(king, amazon):
    def to_coord(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def is_adjacent(p1, p2):
        dx = abs(p1[0] - p2[0])
        dy = abs(p1[1] - p2[1])
        return dx <= 1 and dy <= 1 and (dx != 0 or dy != 0)

    def amazon_attacks(sq, am_pos):
        ax, ay = am_pos
        bx, by = sq
        dx = bx - ax
        dy = by - ay
        if dx == 0 and dy == 0:
            return False
        if (abs(dx), abs(dy)) in [(1, 2), (2, 1)]:
            return True
        if dx == 0 or dy == 0 or abs(dx) == abs(dy):
            return True
        return False

    wk_pos = to_coord(king)
    am_pos = to_coord(amazon)

    checkmates = 0
    checks = 0
    stalemates = 0
    normals = 0

    for i in range(8):
        for j in range(8):
            pos = (i, j)
            if pos == wk_pos or pos == am_pos:
                continue
            if is_adjacent(pos, wk_pos):
                continue

            under_attack = amazon_attacks(pos, am_pos)

            valid_moves = 0
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    if di == 0 and dj == 0:
                        continue
                    new_pos = (i + di, j + dj)
                    if 0 <= new_pos[0] < 8 and 0 <= new_pos[1] < 8:
                        if new_pos == wk_pos or new_pos == am_pos:
                            continue
                        if is_adjacent(new_pos, wk_pos):
                            continue
                        if amazon_attacks(new_pos, am_pos):
                            continue
                        valid_moves += 1

            if under_attack:
                if valid_moves == 0:
                    checkmates += 1
                else:
                    checks += 1
            else:
                if valid_moves == 0:
                    stalemates += 1
                else:
                    normals += 1

    return [checkmates, checks, stalemates, normals]

def poohbear(code):
    # Initialize memory and pointers
    memory = {}
    pointer = 0
    copied_value = 0
    code_ptr = 0
    loop_stack = []
    output = []

    # Parse code to find loop pairs
    loop_pairs = {}
    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                start = stack.pop()
                loop_pairs[start] = i
                loop_pairs[i] = start

    # Execute code
    while code_ptr < len(code):
        char = code[code_ptr]

        if char == '+':
            memory[pointer] = memory.get(pointer, 0) + 1
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == '-':
            memory[pointer] = memory.get(pointer, 0) - 1
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copied_value = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copied_value
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                if code_ptr in loop_pairs:
                    code_ptr = loop_pairs[code_ptr]
            else:
                loop_stack.append(code_ptr)
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                if loop_stack:
                    code_ptr = loop_stack[-1] - 1
            else:
                if code_ptr in loop_pairs:
                    loop_stack.pop()
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif char == 'T':
            memory[pointer] = memory.get(pointer, 0) * 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'Q':
            memory[pointer] = memory.get(pointer, 0) ** 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'U':
            import math
            memory[pointer] = int(math.sqrt(memory.get(pointer, 0)))
        elif char == 'L':
            memory[pointer] = memory.get(pointer, 0) + 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'V':
            memory[pointer] = memory.get(pointer, 0) // 2
        elif char == 'A':
            memory[pointer] = memory.get(pointer, 0) + copied_value
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'B':
            memory[pointer] = memory.get(pointer, 0) - copied_value
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'Y':
            memory[pointer] = memory.get(pointer, 0) * copied_value
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'D':
            if copied_value != 0:
                memory[pointer] = memory.get(pointer, 0) // copied_value
            else:
                memory[pointer] = 0

        code_ptr += 1

    return ''.join(output)

def fib4(n: int):
    # Handle negative input
    if n < 0:
        return 0

    # Base cases
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # For n >= 4, use iteration
    # Initialize the last 4 values: fib4(0), fib4(1), fib4(2), fib4(3)
    a, b, c, d = 0, 0, 2, 0

    for i in range(4, n + 1):
        # Calculate fib4(i) = fib4(i-1) + fib4(i-2) + fib4(i-3) + fib4(i-4)
        new_val = a + b + c + d
        # Shift values for next iteration
        a, b, c, d = b, c, d, new_val

    return d

def is_valid(s):
    # Check if the string is empty
    if len(s) == 0:
        return False

    # Check if the first character is valid (alpha, underscore, or dollar sign)
    first_char = s[0]
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Check if all remaining characters are valid (alpha, digit, underscore, or dollar sign)
    for char in s[1:]:
        if not (char.isalnum() or char == '_' or char == '$'):
            return False

    return True

def max_element(l: list):
