import math

def converter(number, decimals=0, base=math.pi):
    if base == int(base):
        base = int(base)
        return _convert_integer_base(number, decimals, base)
    else:
        return _convert_non_integer_base(number, decimals, base)

def _convert_integer_base(number, decimals, base):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    is_negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    digits = []
    while integer_part > 0:
        remainder = integer_part % base
        digits.append(_get_digit_char(remainder))
        integer_part //= base
    integer_str = ''.join(reversed(digits))

    # Convert fractional part
    fractional_part = number - int(number)
    fractional_str = ""
    if decimals > 0:
        fractional_str = "."
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            fractional_str += _get_digit_char(digit)
            fractional_part -= digit

    result = integer_str + fractional_str

    if is_negative:
        result = '-' + result

    return result

def _convert_non_integer_base(number, decimals, base):
    if number == 0:
        return '0.' + '0' * decimals if decimals > 0 else '0'

    is_negative = number < 0
    number = abs(number)

    # Handle integer part with greedy algorithm
    integer_part = int(number)
    digits = []

    if integer_part > 0:
        # Find highest power
        if base >= 1:
            power = int(math.log(integer_part) / math.log(base))
        else:
            power = 0

        remaining = integer_part
        while power >= 0:
            if base ** power <= remaining:
                digit = int(remaining / (base ** power))
                if digit >= base:
                    digit = int(base - 1)
                digits.append(_get_digit_char(digit))
                remaining -= digit * (base ** power)
            else:
                digits.append(_get_digit_char(0))
            power -= 1
    else:
        digits.append(_get_digit_char(0))

    integer_str = ''.join(digits)

    # Handle fractional part
    fractional_part = number - int(number)
    fractional_str = ""
    if decimals > 0:
        fractional_str = "."
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            if digit >= base:
                digit = int(base - 1)
            fractional_str += _get_digit_char(digit)
            fractional_part -= digit

    result = integer_str + fractional_str

    if is_negative:
        result = '-' + result

    return result

def _get_digit_char(digit):
    if digit < 10:
        return str(digit)
    else:
        return chr(ord('A') + digit - 10)

def is_balanced(s, pairs):
    # Build mapping from closing to opening characters and set of opening characters
    closing_to_opening = {}
    opening_chars = set()
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        closing_to_opening[closing] = opening
        opening_chars.add(opening)

    stack = []

    for char in s:
        if char in closing_to_opening:
            # Check if this should be treated as closing (matches top of stack)
            if stack and stack[-1] == closing_to_opening[char]:
                stack.pop()
            elif char in opening_chars:
                # Character can be both opening and closing (like ' in '')
                stack.append(char)
            else:
                # Unbalanced - closing without matching opening
                return False
        elif char in opening_chars:
            stack.append(char)
        # Ignore other characters

    return len(stack) == 0

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, number) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract just the numbers from the sorted pairs
    return [num for _, _, num in indexed_nums]

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    colors = list(map(int, lines[1].split()))

    # Precompute palindrome status for all substrings
    is_palindrome = [[False] * n for _ in range(n)]

    # Process substrings in order of increasing length
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if i == j:
                # Single character is always palindrome
                is_palindrome[i][j] = True
            elif i + 1 == j:
                # Two characters are palindrome if they are equal
                is_palindrome[i][j] = (colors[i] == colors[j])
            else:
                # Longer substrings are palindrome if first and last characters match
                # and the inner substring is also palindrome
                is_palindrome[i][j] = (colors[i] == colors[j] and is_palindrome[i + 1][j - 1])

    # DP table: dp[i][j] = minimum seconds to eliminate substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Fill DP table for all substrings
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if is_palindrome[i][j]:
                # If the substring is palindrome, we can remove it in one second
                dp[i][j] = 1
            else:
                # Otherwise, try all possible splits and take minimum
                dp[i][j] = float('inf')
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

