import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part to the given base
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            # Handle negative remainders
            if remainder < 0:
                remainder += base
                temp = (temp - remainder) // base - 1
            else:
                temp = (temp - remainder) // base
            integer_digits.append(remainder)

    # Reverse to get correct order
    integer_digits.reverse()

    # Convert fractional part to the given base
    fractional_digits = []
    if fractional_part > 0:
        temp_fractional = fractional_part
        for _ in range(decimals):
            temp_fractional *= base
            digit = int(temp_fractional)
            fractional_digits.append(digit)
            temp_fractional -= digit

    # Format the result
    if not integer_digits:
        result = "0"
    else:
        result = ""
        for digit in integer_digits:
            if digit < 10:
                result += str(digit)
            else:
                result += chr(ord('A') + digit - 10)

    # Add fractional part if needed
    if decimals > 0:
        result += "."
        for digit in fractional_digits:
            if digit < 10:
                result += str(digit)
            else:
                result += chr(ord('A') + digit - 10)

    # Pad fractional part with zeros if needed
    if decimals > 0:
        current_decimals = len(result.split('.')[1]) if '.' in result else 0
        if current_decimals < decimals:
            result += "0" * (decimals - current_decimals)

    # Handle negative sign
    if negative:
        result = "-" + result

    return result

def largest_divisor(n):
    if n <= 0:
        raise ValueError("n must be a positive integer")
    if n == 1:
        return 1

    # Find smallest divisor greater than 1
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i

    return n  # n is prime, so no proper divisors, return 1 or n

def pig_latin(word):
