    else:
        # No vowels found, return original word plus "ay"
        return word + 'ay'

    # Move consonants from the beginning to the end until the first vowel
    return word[vowel_index:] + word[:vowel_index] + 'ay'

def parse_nested_parens(paren_string):
    if not paren_string:
        return []

    structures = paren_string.split()
    result = []

    for structure in structures:
        max_depth = 0
        current_depth = 0

        for char in structure:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

def count_up_to(n):
    """Returns all prime numbers less than n in ascending order."""
    if n <= 2:
        return []

    # Create boolean array for Sieve of Eratosthenes
    is_prime = [True] * n
    is_prime[0] = False
    is_prime[1] = False

    # Sieve of Eratosthenes algorithm
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            # Mark all multiples of i starting from i*i as not prime
            for j in range(i * i, n, i):
                is_prime[j] = False

    # Collect all prime numbers
    return [i for i in range(2, n) if is_prime[i]]

def parse_int(s):
    units = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    teens = {
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16,
        'seventeen': 17, 'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    s = s.lower().strip()
    s = s.replace('-', ' ')
    s = s.replace(' and ', ' ')

    words = s.split()

    total = 0
    current = 0

    for word in words:
        if word == 'hundred':
            current *= 100
        elif word in units:
            current += units[word]
        elif word in teens:
            current += teens[word]
        elif word in tens:
            current += tens[word]
        elif word == 'thousand':
            total += current * 1000
            current = 0
        elif word == 'million':
            total += current * 1000000
            current = 0

    total += current

    return total

def count_divisors(n):
    s = int(n ** 0.5)
    result = 0
    for i in range(1, s + 1):
        result += n // i
    return 2 * result - s * s

