def amazon_check_mate(king: str, amazon: str) -> list:
    def parse_pos(pos):
        file_idx = ord(pos[0]) - ord('a')
        rank_idx = int(pos[1]) - 1
        return (file_idx, rank_idx)

    k_file, k_rank = parse_pos(king)
    a_file, a_rank = parse_pos(amazon)

    def in_board(f, r):
        return 0 <= f < 8 and 0 <= r < 8

    def is_adjacent_to_king(f, r):
        return abs(f - k_file) <= 1 and abs(r - k_rank) <= 1

    def amazon_attacks(f, r, f2, r2):
        return (f == f2) or (r == r2) or (abs(f - f2) == abs(r - r2))

    checkmate_positions = []

    for f in range(8):
        for r in range(8):
            if f == k_file and r == k_rank:
                continue
            if not in_board(f, r):
                continue

            king_kills_amazon = amazon_attacks(k_file, k_rank, f, r)
            king_moved_to_empty = True

            for df in [-1, 0, 1]:
                for dr in [-1, 0, 1]:
                    if df == 0 and dr == 0:
                        continue
                    kf, kr = k_file + df, k_rank + dr
                    if not in_board(kf, kr):
                        continue
                    if kf == f and kr == r:
                        king_moved_to_empty = False
                        break
                    if amazon_attacks(f, r, kf, kr):
                        king_moved_to_empty = False
                        break
                if not king_moved_to_empty:
                    break

            if not king_moved_to_empty:
                continue

            if not king_kills_amazon:
                continue

            checkmate_positions.append((f, r))

    def categorize(f, r):
        diff_f = abs(f - k_file)
        diff_r = abs(r - k_rank)

        if f == k_file:
            return 0
        elif r == k_rank:
            return 1
        elif diff_f == diff_r:
            if (f == k_file - 1 and r == k_rank - 1) or \
               (f == k_file - 1 and r == k_rank + 1) or \
               (f == k_file + 1 and r == k_rank - 1) or \
               (f == k_file + 1 and r == k_rank + 1):
                return 2
            else:
                return 3
        return -1

    counts = [0, 0, 0, 0]
    for pos in checkmate_positions:
        cat = categorize(pos[0], pos[1])
        if cat != -1:
            counts[cat] += 1

    return counts

