            result += symbols[i]

    return result.lower()

import math

def poohbear(code):
    # Initialize memory and pointers
    memory = {}
    pointer = 0
    copy_value = 0
    code_pointer = 0
    loop_stack = []
    output = []

    # Parse loops first to build loop mapping
    loop_map = {}
    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                start = stack.pop()
                loop_map[start] = i
                loop_map[i] = start

    # Execute code
    while code_pointer < len(code):
        char = code[code_pointer]

        if char == '+':
            memory[pointer] = memory.get(pointer, 0) + 1
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == '-':
            memory[pointer] = memory.get(pointer, 0) - 1
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copy_value = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copy_value
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                code_pointer = loop_map[code_pointer]
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                code_pointer = loop_map[code_pointer]
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif char == 'T':
            memory[pointer] = memory.get(pointer, 0) * 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'Q':
            memory[pointer] = memory.get(pointer, 0) ** 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'U':
            memory[pointer] = int(math.sqrt(memory.get(pointer, 0)))
        elif char == 'L':
            memory[pointer] = memory.get(pointer, 0) + 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            if memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'V':
            memory[pointer] = memory.get(pointer, 0) // 2
        elif char == 'A':
            memory[pointer] = memory.get(pointer, 0) + copy_value
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'B':
            memory[pointer] = memory.get(pointer, 0) - copy_value
            if memory[pointer] > 255:
                memory[pointer] = 0
            elif memory[pointer] < 0:
                memory[pointer] = 255
        elif char == 'Y':
            memory[pointer] = memory.get(pointer, 0) * copy_value
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'D':
            if copy_value != 0:
                memory[pointer] = memory.get(pointer, 0) // copy_value
            else:
                memory[pointer] = 0
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                code_pointer = loop_map[code_pointer]
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                code_pointer = loop_map[code_pointer]

        code_pointer += 1

    return ''.join(output)

def almost_everywhere_zero(n, k):
    n_str = str(n)
    length = len(n_str)

    memo = {}

    def dp(pos, cnt, tight, leading_zero):
        state = (pos, cnt, tight, leading_zero)
        if state in memo:
            return memo[state]

        if pos == length:
            return 1 if cnt == k and not leading_zero else 0

        limit = int(n_str[pos]) if tight else 9
        result = 0

        for digit in range(0, limit + 1):
            new_tight = tight and (digit == limit)
            new_leading_zero = leading_zero and (digit == 0)
            new_cnt = cnt + (1 if digit != 0 else 0)

            if new_cnt <= k:
                result += dp(pos + 1, new_cnt, new_tight, new_leading_zero)

        memo[state] = result
        return result

    return dp(0, 0, True, True)

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Handle empty string case
    if not test:
        return {}

    # Split the string into individual letters
    letters = test.split()

    # Count occurrences of each letter
    letter_counts = {}
    for letter in letters:
        letter_counts[letter] = letter_counts.get(letter, 0) + 1

    # Find the maximum count
    max_count = max(letter_counts.values())

    # Create result dictionary with all letters that have the maximum count
    result = {letter: count for letter, count in letter_counts.items() if count == max_count}

    return result

def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into monomials
    # Find all terms (including signs)
    terms = re.findall(r'[+-]?\w+', expression)

    # Dictionary to store monomials and their coefficients
    monomial_dict = defaultdict(int)

    for term in terms:
        # Separate the sign from the rest
        if term[0] == '-':
            sign = -1
            rest = term[1:]
        elif term[0] == '+':
            sign = 1
            rest = term[1:]
        else:
            sign = 1
            rest = term

        # If the term is just a sign, it's invalid in our context
        if not rest:
            continue

        # Count the variables in the monomial
        variables = sorted(list(rest))
        monomial_key = ''.join(variables)

        # Determine coefficient
        if rest == '1' or rest == '':
            coefficient = sign
        else:
            # Extract coefficient (if there's a number)
            coeff_str = ''
            i = 0
            while i < len(rest) and rest[i].isdigit():
                coeff_str += rest[i]
                i += 1

            if coeff_str:
                coefficient = sign * int(coeff_str)
            else:
                coefficient = sign

        # Add to dictionary
        monomial_dict[monomial_key] += coefficient

    # Filter out zero coefficients
    monomial_dict = {k: v for k, v in monomial_dict.items() if v != 0}

    # Sort monomials by number of variables, then lexicographically
    sorted_monomials = sorted(monomial_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Build result string
    result = []
    first = True

    for monomial, coeff in sorted_monomials:
        if coeff == 0:
            continue

        # Handle the coefficient
        if coeff == 1 and not first:
            term = monomial
        elif coeff == -1 and not first:
            term = '-' + monomial
        elif coeff == 1 and first:
            term = monomial
        elif coeff == -1 and first:
            term = '-' + monomial
        else:
            term = str(coeff) + monomial

        # Add to result
        if first:
            result.append(term)
            first = False
        else:
            if coeff > 0:
                result.append('+' + term)
            else:
                result.append('-' + term[1:])  # Remove the - sign we already added

    # Handle the case where all coefficients are zero
    if not result:
        return "0"

    return ''.join(result)

def cycpattern_check(a, b):
    # If b is empty, empty string is considered a substring of any string
    if not b:
        return True

    # If a is empty but b is not, b cannot be in a
    if not a:
        return False

    # If b is longer than a, no rotation of b can be in a
    if len(b) > len(a):
        return False

    # Generate all rotations of b and check if any exists in a
    n = len(b)
    for i in range(n):
        # Create rotation by taking suffix from i to end + prefix from 0 to i
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True

    return False

def sum_array(arr):
