def amazon_check_mate(king, amazon):
    # Convert chess notation to 0-indexed coordinates
    def to_coords(pos):
        file = ord(pos[0]) - ord('a')  # 0-7 for a-h
        rank = int(pos[1]) - 1          # 0-7 for 1-8
        return (rank, file)  # (row, col) where row 0 = rank 1

    king_pos = to_coords(king)
    amazon_pos = to_coords(amazon)

    # Compute all squares attacked by the amazon
    def get_amazon_attacks(pos):
        r, c = pos
        attacks = set()

        # Queen moves: entire row, column, and diagonals
        for i in range(8):
            attacks.add((r, i))
            attacks.add((i, c))

        for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
            for step in range(1, 8):
                nr, nc = r + dr * step, c + dc * step
                if 0 <= nr < 8 and 0 <= nc < 8:
                    attacks.add((nr, nc))
                else:
                    break

        # Knight moves: 8 possible L-shaped jumps
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
                       (1, -2), (1, 2), (2, -1), (2, 1)]
        for dr, dc in knight_moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 8 and 0 <= nc < 8:
                attacks.add((nr, nc))

        # Remove the amazon's own square
        attacks.discard((r, c))

        return attacks

    attacked_squares = get_amazon_attacks(amazon_pos)

    # Check if a square is adjacent to the white king (invalid for black king)
    def is_adjacent_to_white_king(pos):
        kr, kc = king_pos
        pr, pc = pos
        return abs(pr - kr) <= 1 and abs(pc - kc) <= 1

    # Check if black king has valid moves from position
    def has_valid_moves(pos):
        r, c = pos
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < 8 and 0 <= nc < 8:
                    # Valid move: not attacked, not on white king, not adjacent to white king
                    if (nr, nc) != king_pos and \
                       (nr, nc) not in attacked_squares and \
                       not is_adjacent_to_white_king((nr, nc)):
                        return True
        return False

    checkmate, check, stalemate, safe = 0, 0, 0, 0

    # Iterate through all possible black king positions
    for r in range(8):
        for c in range(8):
            pos = (r, c)

            # Skip invalid positions (on or adjacent to white king)
            if pos == king_pos or is_adjacent_to_white_king(pos):
                continue

            under_attack = pos in attacked_squares
            valid_moves = has_valid_moves(pos)

            if under_attack:
                if not valid_moves:
                    checkmate += 1
                else:
                    check += 1
            else:
                if not valid_moves:
                    stalemate += 1
                else:
                    safe += 1

    return [checkmate, check, stalemate, safe]

def exchange_sort(sequence):
    if len(sequence) <= 1:
        return 0

    # Create target sorted sequence
    target = []
    count = [0, 0, 0]  # count[0] for 7, count[1] for 8, count[2] for 9

    # Count occurrences
    for num in sequence:
        if num == 7:
            count[0] += 1
        elif num == 8:
            count[1] += 1
        else:  # num == 9
            count[2] += 1

    # Build target sequence
    target = [7] * count[0] + [8] * count[1] + [9] * count[2]

    # Create position mapping for target
    pos_map = {}
    for i, num in enumerate(target):
        if num not in pos_map:
            pos_map[num] = []
        pos_map[num].append(i)

    # Create a mapping from each element to its target position
    element_to_target = {}
    for i, num in enumerate(target):
        if not pos_map[num]:  # This shouldn't happen if we have correct counts
            continue
        target_pos = pos_map[num].pop(0)
        element_to_target[i] = target_pos

    # Count cycles using visited array
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if visited[i]:
            continue

        if i not in element_to_target:
            continue

        # Start a new cycle
        current = i
        cycle_length = 0

        while not visited[current]:
            visited[current] = True
            # Move to where current element should go
            if current in element_to_target:
                current = element_to_target[current]
            else:
                break
            cycle_length += 1

        if cycle_length > 0:
            cycles += 1

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

from typing import List


def intersperse(numbers: List[int], delimeter: int) -> List[int]:
    if not numbers:
        return []

    result = [numbers[0]]
    for num in numbers[1:]:
        result.append(delimeter)
        result.append(num)

