    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        # Check if i is a palindrome without string conversion
        original = i
        reversed_num = 0
        temp = i
        while temp > 0:
            reversed_num = reversed_num * 10 + temp % 10
            temp //= 10

        if original == reversed_num:
            # Categorize as even or odd
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def simplify(expr):
    if not expr:
        return ""

    # Parse terms
    terms = []
    i = 0
    n = len(expr)

    while i < n:
        # Determine sign
        sign = 1
        if expr[i] == '+':
            i += 1
        elif expr[i] == '-':
            sign = -1
            i += 1

        # Extract coefficient (optional)
        coef_str = ''
        while i < n and expr[i].isdigit():
            coef_str += expr[i]
            i += 1

        coef = int(coef_str) if coef_str else 1
        coef *= sign

        # Collect variables
        vars_str = ''
        while i < n and expr[i].isalpha():
            vars_str += expr[i]
            i += 1

        if vars_str:  # Only non-constant terms
            # Sort variables alphabetically for canonical form
            sorted_vars = ''.join(sorted(vars_str))
            terms.append((coef, sorted_vars))

    # Combine like terms
    from collections import defaultdict
    monomials = defaultdict(int)
    for coef, vars_key in terms:
        monomials[vars_key] += coef

    # Remove zero coefficients
    monomials = {k: v for k, v in monomials.items() if v != 0}

    # Sort by number of variables, then lexicographically
    sorted_terms = sorted(monomials.items(), key=lambda x: (len(x[0]), x[0]))

    # Format output
    result = []
    for vars_key, coef in sorted_terms:
        if coef == 1:
            term = vars_key
        elif coef == -1:
            term = '-' + vars_key
        else:
            term = str(coef) + vars_key

        if not result:
            result.append(term)
        elif term.startswith('-'):
            result.append(term)
        else:
            result.append('+' + term)

    return ''.join(result)

def order_by_points(nums):
    def digit_sum(n):
        # Calculate sum of digits, ignoring the sign
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, value) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract the sorted values
    return [num for _, _, num in indexed_nums]

def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) <= 1:
        return True

    is_increasing = None

    for i in range(1, len(l)):
        if l[i] > l[i-1]:
            if is_increasing is False:
                return False
            is_increasing = True
        elif l[i] < l[i-1]:
            if is_increasing is True:
                return False
            is_increasing = False
        # If l[i] == l[i-1], we continue without changing the trend

    return True

