from collections import defaultdict

def parse_url(url):
    # Remove http:// prefix
    url = url[7:]

    # Split hostname and path
    if '/' in url:
        hostname, path = url.split('/', 1)
        # Normalize path - remove trailing slashes but keep the slash if it's just "/"
        if path == '':
            path = '/'
        elif path.endswith('/'):
            path = path.rstrip('/')
    else:
        hostname = url
        path = '/'

    return hostname, path

def normalize_path(path):
    # Handle the path normalization
    if path == '/':
        return '/'

    # Split by slashes and filter out empty strings and '.'
    components = [comp for comp in path.split('/') if comp and comp != '.']

    # Handle '..' components (simple approach - remove last component if possible)
    stack = []
    for comp in components:
        if comp == '..':
            if stack:
                stack.pop()
        else:
            stack.append(comp)

    # Reconstruct path
    if not stack:
        return '/'

    return '/' + '/'.join(stack)

def get_paths_for_hostname(hostname, queries):
    paths = set()
    for query in queries:
        if query.startswith(f"http://{hostname}"):
            # Extract path part
            path = query[len(f"http://{hostname}"):]
            if not path:
                path = '/'
            else:
                # Normalize the path
                path = normalize_path(path)
            paths.add(path)
    return paths

def get_hash_for_paths(paths):
    # Create a canonical representation of the path set
    sorted_paths = sorted(list(paths))
    # Create a string representation and hash it
    path_string = '|'.join(sorted_paths)
    return hash(path_string)

