def solution(input_string, comment_markers):
    if not input_string:
        return ""

    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the earliest comment marker position
        earliest_marker_pos = len(line)
        for marker in comment_markers:
            pos = line.find(marker)
            if pos != -1 and pos < earliest_marker_pos:
                earliest_marker_pos = pos

        # Truncate the line at the earliest marker position
        if earliest_marker_pos < len(line):
            processed_line = line[:earliest_marker_pos]
        else:
            processed_line = line

        # Strip trailing whitespace
        processed_line = processed_line.rstrip()
        result_lines.append(processed_line)

    return '\n'.join(result_lines)

