def valid_mersenne(n):
    """
    Check if 2^n - 1 is a Mersenne prime.
    """
    # n must be at least 2
    if n < 2:
        return False

    # n must be prime for 2^n - 1 to be prime (necessary condition)
    if not is_prime(n):
        return False

    # Special case for n = 2
    if n == 2:
        return True

    # Use Lucas-Lehmer test for Mersenne primes
    return lucas_lehmer(n)


def is_prime(num):
    """
    Check if a number is prime using trial division.
    """
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False

    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True


def lucas_lehmer(n):
    """
    Lucas-Lehmer test for Mersenne primes.

    For M_p = 2^p - 1 where p is prime, M_p is prime if and only if
    S_{p-2} ≡ 0 (mod M_p), where S_0 = 4 and S_{i+1} = S_i^2 - 2 (mod M_p).
    """
    m = pow(2, n) - 1

    # Lucas-Lehmer sequence
    s = 4

    # Perform n-2 iterations
    for _ in range(n - 2):
        s = (s * s - 2) % m

    return s == 0

