def choose(n, k):
    # Handle edge cases
    if k < 0 or k > n:
        return 0

    # Use symmetry property: C(n, k) = C(n, n-k)
    if k > n - k:
        k = n - k

    # Handle trivial cases
    if k == 0:
        return 1

    # Compute using iterative multiplicative formula
    # C(n, k) = n * (n-1) * ... * (n-k+1) / (k * (k-1) * ... * 1)
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

