def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """

    def to_numeric(value):
        """Convert any input to a float for comparison."""
        if isinstance(value, (int, float)):
            return float(value)
        elif isinstance(value, str):
            # Replace comma with period for consistent decimal handling
            normalized = value.replace(',', '.')
            return float(normalized)
        else:
            raise TypeError(f"Unsupported type: {type(value)}")

    # Convert both to numeric for comparison
    num_a = to_numeric(a)
    num_b = to_numeric(b)

    # Compare and return original value based on comparison
    if num_a > num_b:
        return a
    elif num_b > num_a:
        return b
    else:
        return None

def candies(arr):
    if len(arr) < 2:
        return -1

    max_candies = max(arr)
    total_given = 0

    for candy_count in arr:
