    return total_given

import sys

def prob_all_collected(k, n):
    # Using inclusion-exclusion principle
    # P(all k types collected in n days) = sum_{j=0}^{k} (-1)^j * C(k,j) * ((k-j)/k)^n
    prob = 0
    for j in range(k + 1):
        # Calculate C(k,j) = k! / (j! * (k-j)!)
        if j == 0:
            coeff = 1
        else:
            coeff = 1
            for i in range(j):
                coeff = coeff * (k - i) // (i + 1)

        term = ((k - j) / k) ** n
        if j % 2 == 0:
            prob += coeff * term
        else:
            prob -= coeff * term
    return prob

def solve(k, target_prob):
    # Binary search for minimum n
    left, right = 1, k * k * 10  # Reasonable upper bound

    while left < right:
        mid = (left + right) // 2
        prob = prob_all_collected(k, mid)
        if prob >= target_prob:
            right = mid
        else:
            left = mid + 1

    return left

