            while is_valid(nr, nc):
                if (nr, nc) == (r, c):
                    return True
                nr += dr
                nc += dc
        for dr, dc in knight_moves:
            nr, nc = ar + dr, ac + dc
            if is_valid(nr, nc) and (nr, nc) == (r, c):
                return True
        return False

    def is_adjacent_to_white_king(r, c, kr, kc):
        for dr, dc in king_moves:
            if (r + dr, c + dc) == (kr, kc):
                return True
        return False

    kr, kc = parse_square(king)
    ar, ac = parse_square(amazon)

    checkmate = 0
    check = 0
    stalemate = 0
    safe_moves = 0

    for r in range(8):
        for c in range(8):
            if (r, c) == (kr, kc) or (r, c) == (ar, ac):
                continue
            if is_adjacent_to_white_king(r, c, kr, kc):
                continue

            under_attack = is_attacked_by_amazon(r, c, ar, ac)
            safe_escape_moves = 0

            for dr, dc in king_moves:
                nr, nc = r + dr, c + dc
                if not is_valid(nr, nc):
                    continue
                if (nr, nc) == (kr, kc) or (nr, nc) == (ar, ac):
                    continue
                if is_adjacent_to_white_king(nr, nc, kr, kc):
                    continue
                if is_attacked_by_amazon(nr, nc, ar, ac):
                    continue
                safe_escape_moves += 1

            if under_attack:
                if safe_escape_moves == 0:
                    checkmate += 1
                else:
                    check += 1
            else:
                if safe_escape_moves == 0:
                    stalemate += 1
                else:
                    safe_moves += 1

    return [checkmate, check, stalemate, safe_moves]

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    gems = list(map(int, lines[1].split()))

    # dp[i][j] represents minimum operations to remove substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Fill the DP table
    # Length of substring
    for length in range(1, n + 1):
        # Starting index
        for i in range(n - length + 1):
            j = i + length - 1

            if i == j:
                # Single element needs 1 operation
                dp[i][j] = 1
            elif i + 1 == j:
                # Two elements
                if gems[i] == gems[j]:
                    dp[i][j] = 1  # Can remove as one palindrome
                else:
                    dp[i][j] = 2  # Need two operations
            else:
                # More than 2 elements
                if gems[i] == gems[j]:
                    # If first and last are same, we can remove them together
                    # and solve for the middle
                    dp[i][j] = dp[i + 1][j - 1]
                else:
                    # Otherwise, we must split
                    dp[i][j] = float('inf')
                    # Try all possible splits
                    for k in range(i, j):
                        dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

if __name__ == "__main__":
    main()

