def solution(input_string, markers):
    lines = input_string.split('\n')
    result = []

    for line in lines:
        # Find the position of the first marker
        marker_positions = []
        for marker in markers:
            pos = line.find(marker)
            if pos != -1:
                marker_positions.append(pos)

        # If we found any markers, truncate the line at the first one
        if marker_positions:
            first_marker_pos = min(marker_positions)
            cleaned_line = line[:first_marker_pos]
        else:
            cleaned_line = line

        # Strip trailing whitespace
        cleaned_line = cleaned_line.rstrip()
        result.append(cleaned_line)

    return '\n'.join(result)

def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # A Mersenne prime is of the form 2^n - 1 where both n and 2^n - 1 are prime
    if not is_prime(n):
        return False

    mersenne_number = (2 ** n) - 1
    return is_prime(mersenne_number)

