def is_balanced(input_string, pairs):
    if not pairs:
        return True

    # Create a mapping of opening to closing characters and vice versa
    pair_map = {}
    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        pair_map[open_char] = close_char
        # If opening and closing are the same, it's both
        if open_char == close_char:
            pair_map[open_char] = close_char

    # Stack to keep track of opening characters
    stack = []

    for char in input_string:
        # If it's an opening character
        if char in pair_map and (pair_map[char] != char or char not in stack):
            stack.append(char)
        # If it's a closing character
        elif char in pair_map.values():
            # Check if stack is empty or if the closing character doesn't match the last opening character
            if not stack or pair_map.get(stack[-1]) != char:
                return False
            stack.pop()

    # If stack is empty, all brackets were closed
    return len(stack) == 0

def decimal_to_binary(n: int) -> str:
    if n == 0:
        return "0"

    if n < 0:
        return "-" + decimal_to_binary(-n)

    binary = []
    while n > 0:
        binary.append(str(n % 2))
        n = n // 2

    return "".join(reversed(binary))

def sum_product(numbers):
    if not numbers:
        return 0, 1

    total_sum = sum(numbers)
    product = 1
    for num in numbers:
        product *= num

    return total_sum, product

def order_by_points(nums):
    """
    Given a list of integers, order them based on the sum of their digits.
    If two numbers have the same sum of digits, maintain their original relative order.
    Negative numbers have the same point value as their positive counterparts.
    If the list is empty, return an empty list.
    """
    def digit_sum(n):
        """Calculate the sum of digits in an integer, ignoring the sign."""
        return sum(int(digit) for digit in str(abs(n)))

    # Use sorted with key parameter to sort by digit sum
    # The stable sort will maintain original order for equal digit sums
    return sorted(nums, key=digit_sum)

