def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def coords_to_chess(row, col):
        return chr(ord('a') + row) + str(col + 1)

    def is_valid(row, col):
        return 0 <= row < 8 and 0 <= col < 8

    def get_king_moves(row, col):
        moves = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                new_row, new_col = row + dr, col + dc
                if is_valid(new_row, new_col):
                    moves.append((new_row, new_col))
        return moves

    def is_adjacent(king_row, king_col, other_row, other_col):
        return abs(king_row - other_row) <= 1 and abs(king_col - other_col) <= 1

    def is_attacked_by_amazon(amazon_row, amazon_col, king_row, king_col, target_row, target_col):
        # Check if target square is attacked by amazon
        # Amazon can move like queen or knight

        # Knight moves (8 possible)
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dr, dc in knight_moves:
            if target_row == amazon_row + dr and target_col == amazon_col + dc:
                return True

        # Queen moves (horizontal, vertical, diagonal)
        # Check if target is in same row, column or diagonal as amazon
        if (amazon_row == target_row or 
            amazon_col == target_col or 
            abs(amazon_row - target_row) == abs(amazon_col - target_col)):

            # Check if king blocks the line
            # If king is on the line between amazon and target, it blocks the attack
            if (amazon_row == target_row == king_row and 
                (king_col - amazon_col) * (king_col - target_col) <= 0):
                return False
            if (amazon_col == target_col == king_col and 
                (king_row - amazon_row) * (king_row - target_row) <= 0):
                return False
            if (abs(amazon_row - target_row) == abs(amazon_col - target_col) and 
                abs(amazon_row - king_row) == abs(amazon_col - king_col) and
                (king_row - amazon_row) * (king_row - target_row) <= 0 and
                (king_col - amazon_col) * (king_col - target_col) <= 0):
                return False

            # Check if target is in same row
            if amazon_row == target_row:
                if king_row == target_row:
                    # King is on same row
                    if (king_col - amazon_col) * (king_col - target_col) <= 0:
                        return False
                return True

            # Check if target is in same column
            if amazon_col == target_col:
                if king_col == target_col:
                    # King is on same column
                    if (king_row - amazon_row) * (king_row - target_row) <= 0:
                        return False
                return True

            # Check if target is in same diagonal
            if abs(amazon_row - target_row) == abs(amazon_col - target_col):
                # Check if king is blocking
                if (abs(amazon_row - king_row) == abs(amazon_col - king_col) and
                    (king_row - amazon_row) * (king_row - target_row) <= 0 and
                    (king_col - amazon_col) * (king_col - target_col) <= 0):
                    return False
                return True

        return False

    king_row, king_col = chess_to_coords(king)
    amazon_row, amazon_col = chess_to_coords(amazon)

    # Initialize counts
    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    # Iterate through all possible black king positions
    for row in range(8):
        for col in range(8):
            # Skip if square is occupied by white king or amazon
            if (row == king_row and col == king_col) or (row == amazon_row and col == amazon_col):
                continue

            # Skip if square is adjacent to white king
            if is_adjacent(king_row, king_col, row, col):
                continue

            # Check if black king is under attack by amazon
            attacked = is_attacked_by_amazon(amazon_row, amazon_col, king_row, king_col, row, col)

            # Check if black king can escape
            can_escape = False
            king_moves = get_king_moves(row, col)
            for move_row, move_col in king_moves:
                # Skip if move is to occupied square or adjacent to white king
                if (move_row == king_row and move_col == king_col) or (move_row == amazon_row and move_col == amazon_col):
                    continue
                if is_adjacent(king_row, king_col, move_row, move_col):
                    continue

                # Check if move square is under attack
                if not is_attacked_by_amazon(amazon_row, amazon_col, king_row, king_col, move_row, move_col):
                    can_escape = True
                    break

            # Categorize position
            if attacked and not can_escape:
                checkmate += 1
            elif attacked and can_escape:
                check += 1
            elif not attacked and not can_escape:
                stalemate += 1
            elif not attacked and can_escape:
                safe += 1

    return [checkmate, check, stalemate, safe]

