def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
integers that are prime numbers and less than n.
for example:
count_up_to(5) => [2,3]
count_up_to(11) => [2,3,5,7]
count_up_to(0) => []
count_up_to(20) => [2,3,5,7,11,13,17,19]
count_up_to(1) => []
count_up_to(18) => [2,3,5,7,11,13,17]
"""
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    result = []
    for i in range(2, n):
        if is_prime(i):
            result.append(i)

    return result

from functools import lru_cache

def almost_everywhere_zero(n, k):
    s = str(n)
    n_digits = len(s)

    @lru_cache(None)
    def dp(pos, cnt, tight, started):
        if pos == n_digits:
            return 1 if cnt == k and started else 0

        limit = int(s[pos]) if tight else 9
        total = 0

        for d in range(0, limit + 1):
            new_tight = tight and (d == limit)
            new_started = started or (d > 0)

            if d == 0:
                # Zero digit doesn't increase non-zero count
                new_cnt = cnt
            else:
                # Non-zero digit increases the count
                new_cnt = cnt + 1

            if new_cnt <= k:
                total += dp(pos + 1, new_cnt, new_tight, new_started)

        return total

    return dp(0, 0, True, False)

import math

def converter(number, decimals=0, base=math.pi):
    EPSILON = 1e-12
    SYMBOLS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle sign
    sign = ''
    if number < 0:
        sign = '-'
        number = -number

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Handle integer part
    if integer_part == 0:
        integer_result = ''
    else:
        integer_result = ''
        temp = integer_part
        power = 0

        # Find the highest power
        while base ** (power + 1) <= temp:
            power += 1

        # Convert to base
        while temp > EPSILON:
            if power < 0:
                break
            digit_value = int(temp // (base ** power))
            if digit_value >= base:
                digit_value = int(base - 1)
            if digit_value < 0:
                digit_value = 0
            integer_result += SYMBOLS[digit_value]
            temp -= digit_value * (base ** power)
            power -= 1

    # Handle fractional part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        remainder = fractional_part

        # Calculate required digits
        for i in range(decimals + 1):  # One extra for rounding
            product = remainder * base
            digit = int(round(product))  # Round to nearest integer
            if digit >= base:
                digit = int(base - 1)
            if digit < 0:
                digit = 0
            fractional_result += SYMBOLS[digit]
            remainder = product - digit

            # If we've calculated all required digits, check for rounding
            if i == decimals - 1:
                # Check if the extra digit is >= 5
                if remainder * base >= 0.5:
                    # Need to round up the last digit
                    # This is a simplified approach - in practice, we'd need to handle carry propagation
                    pass

        # Remove the extra digit we calculated for rounding
        fractional_result = fractional_result[:-1]

        # Handle rounding properly
        if decimals > 0:
            # Recalculate with proper rounding
            fractional_result = ''
            remainder = fractional_part
            for i in range(decimals):
                product = remainder * base
                digit = int(round(product))
                if digit >= base:
                    digit = int(base - 1)
                if digit < 0:
                    digit = 0
                fractional_result += SYMBOLS[digit]
                remainder = product - digit

            # Handle final rounding
            if decimals > 0:
                product = remainder * base
                extra_digit = int(round(product))
                if extra_digit >= base:
                    extra_digit = int(base - 1)
                if extra_digit >= 5:
                    # Propagate carry
                    fractional_result = list(fractional_result)
                    for j in range(len(fractional_result) - 1, -1, -1):
                        if fractional_result[j] != '0':
                            digit_val = SYMBOLS.index(fractional_result[j])
                            fractional_result[j] = SYMBOLS[(digit_val + 1) % len(SYMBOLS)]
                            if digit_val + 1 < len(SYMBOLS):
                                break
                            else:
                                fractional_result[j] = '0'
                                if j == 0:
                                    # Need to add carry to integer part
                                    integer_result = integer_result[:-1] + SYMBOLS[SYMBOLS.index(integer_result[-1]) + 1] if integer_result else '1'
                                    break
                        else:
                            fractional_result[j] = '0'
                            if j == 0:
                                integer_result = integer_result[:-1] + SYMBOLS[SYMBOLS.index(integer_result[-1]) + 1] if integer_result else '1'
                    fractional_result = ''.join(fractional_result)

    # Combine results
    if fractional_result == '.':
        fractional_result = ''
    elif fractional_result == '.0' and decimals == 0:
        fractional_result = ''

    result = sign + integer_result + fractional_result

    # Handle special case where we have a leading zero in fractional part
    if result.startswith('.'):
        result = '0' + result

    # Remove trailing zeros in fractional part
    if '.' in result:
        result = result.rstrip('0').rstrip('.')

    return result

import re

def differentiate(poly_string, x_value):
    # Normalize consecutive signs
    poly_string = poly_string.replace('+-', '-').replace('--', '+')

    # Split by + and - but keep signs with terms
    terms = re.split(r'(?=[+-])', poly_string)
    terms = [t for t in terms if t]  # Remove empty strings

    total = 0

    for term in terms:
        # Parse coefficient and exponent
        if 'x' in term:
            # Find position of x
            x_pos = term.index('x')
            coeff_part = term[:x_pos]
            exp_part = term[x_pos+1:]

            # Parse exponent
            if '^' in exp_part:
                exp = int(exp_part.split('^')[1])
            else:
                exp = 1

            # Parse coefficient
            if coeff_part == '' or coeff_part == '+':
                coeff = 1
            elif coeff_part == '-':
                coeff = -1
            else:
                coeff = int(coeff_part)
        else:
            # Constant term - derivative is 0
            continue

        # Apply power rule: derivative of cx^n is cnx^(n-1)
        if exp == 0:
            term_result = 0
        elif exp == 1:
            term_result = coeff
        else:
            term_result = coeff * exp * (x_value ** (exp - 1))

        total += term_result

    return total

def parse_int(s):
    if not s:
