def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds (from largest to smallest)
    units = [
        (365 * 24 * 60 * 60, "year"),    # 31,536,000
        (24 * 60 * 60, "day"),           # 86,400
        (60 * 60, "hour"),               # 3,600
        (60, "minute"),                  # 60
        (1, "second")                    # 1
    ]

    parts = []

    for divisor, name in units:
        count = seconds // divisor
        if count > 0:
            # Handle pluralization
            if count == 1:
                parts.append(f"{count} {name}")
            else:
                parts.append(f"{count} {name}s")
            seconds -= count * divisor

    # Join parts with proper formatting
    if len(parts) == 1:
        return parts[0]
    elif len(parts) == 2:
        return f"{parts[0]} and {parts[1]}"
    else:
        return ", ".join(parts[:-1]) + " and " + parts[-1]

