from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    # Validate that input is a list
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list")

    # Validate that all elements are integers (but not booleans)
    for num in numbers:
        if isinstance(num, bool) or not isinstance(num, int):
            raise TypeError("All elements must be integers")

    # Handle empty list
    if len(numbers) == 0:
        return (0, 1)

    # Calculate sum and product
    total_sum = 0
    total_product = 1

    for num in numbers:
        total_sum += num
        total_product *= num

    return (total_sum, total_product)

def is_balanced(s, pairs):
    # Create mapping from opening to closing characters
    pair_map = {}
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        pair_map[opening] = closing

    # Stack to track opening characters
    stack = []

    # Process each character in the string
    for char in s:
        # If it's an opening character, push to stack
        if char in pair_map:
            stack.append(char)
        # If it's a closing character
        elif char in pair_map.values():
            # If stack is empty or doesn't match, it's unbalanced
            if not stack or pair_map[stack.pop()] != char:
                return False

    # String is balanced if stack is empty
    return len(stack) == 0

def check_if_last_char_is_a_letter(txt):
