def amazon_check_mate(king, amazon):
    def parse_pos(pos):
        file = ord(pos[0]) - ord('a')  # 'a' -> 0, 'h' -> 7
        rank = int(pos[1]) - 1  # '1' -> 0, '8' -> 7
        return (file, rank)

    def is_valid_sq(f, r):
        return 0 <= f < 8 and 0 <= r < 8

    def is_adjacent(f1, r1, f2, r2):
        return abs(f1 - f2) <= 1 and abs(r1 - r2) <= 1

    def is_amazon_attack(am_f, am_r, target_f, target_r):
        # Knight moves (8 possible)
        knight_moves = [(2,1), (2,-1), (-2,1), (-2,-1), (1,2), (1,-2), (-1,2), (-1,-2)]
        for df, dr in knight_moves:
            if am_f + df == target_f and am_r + dr == target_r:
                return True

        # Queen moves (rook + bishop)
        # Same row (rook-like)
        if am_r == target_r and am_f != target_f:
            return True
        # Same column (rook-like)
        if am_f == target_f and am_r != target_r:
            return True
        # Diagonal (bishop-like)
        if abs(am_f - target_f) == abs(am_r - target_r) and am_f != target_f:
            return True

        return False

    def can_reach_safe_square(black_f, black_r, white_k_f, white_k_r, am_f, am_r):
        # Check all 8 possible king moves
        for df in [-1, 0, 1]:
            for dr in [-1, 0, 1]:
                if df == 0 and dr == 0:
                    continue
                nf, nr = black_f + df, black_r + dr
                if not is_valid_sq(nf, nr):
                    continue
                # Cannot be adjacent to white king
                if is_adjacent(nf, nr, white_k_f, white_k_r):
                    continue
                # Cannot be under amazon attack
                if is_amazon_attack(am_f, am_r, nf, nr):
                    continue
                return True
        return False

    white_k_f, white_k_r = parse_pos(king)
    am_f, am_r = parse_pos(amazon)

    # [checkmate, check, stalemate, safe]
    results = [0, 0, 0, 0]

    for bf in range(8):
        for br in range(8):
            # Black king cannot be on white king's square
            if bf == white_k_f and br == white_k_r:
                continue
            # Black king cannot be adjacent to white king
            if is_adjacent(bf, br, white_k_f, white_k_r):
                continue

            in_check = is_amazon_attack(am_f, am_r, bf, br)
            can_escape = can_reach_safe_square(bf, br, white_k_f, white_k_r, am_f, am_r)

            if in_check:
                if can_escape:
                    results[1] += 1  # check
                else:
                    results[0] += 1  # checkmate
            else:
                if can_escape:
                    results[3] += 1  # safe
                else:
                    results[2] += 1  # stalemate

    return results

def exchange_sort(sequence):
    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for val in sequence:
        count[val] += 1

    # Create target sequence
    target = []
    target.extend([7] * count[7])
    target.extend([8] * count[8])
    target.extend([9] * count[9])

    # Create a mapping from value to its correct positions
    correct_positions = {7: [], 8: [], 9: []}
    for i, val in enumerate(target):
        correct_positions[val].append(i)

    # Create a mapping from index to correct value
    index_to_correct = {}
    for i, val in enumerate(target):
        index_to_correct[i] = val

    # Track which positions are correctly placed
    correct = [False] * len(sequence)

    # Mark correctly placed elements
    for i in range(len(sequence)):
        if sequence[i] == target[i]:
            correct[i] = True

    # Count cycles
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i] and not correct[i]:
            # Start a new cycle
            cycle_length = 0
            current = i
            while not visited[current]:
                visited[current] = True
                cycle_length += 1
                # Find where current element should go
                correct_val = target[current]
                # Find the index of correct_val that is not yet visited
                next_pos = -1
                for pos in correct_positions[correct_val]:
                    if not visited[pos]:
                        next_pos = pos
                        break
                if next_pos == -1:
                    # Find any unvisited position with correct value
                    for pos in correct_positions[correct_val]:
                        if not visited[pos]:
                            next_pos = pos
                            break
                current = next_pos
            if cycle_length > 0:
                cycles += 1

    # The minimum number of swaps is total elements - cycles
    return len(sequence) - cycles

def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    p = 2

    while p * p <= d:
        if d % p == 0:
            while d % p == 0:
                d //= p
            result = result // p * (p - 1)
        p += 1

    if d > 1:
        result = result // d * (d - 1)

    return result

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=lambda x: (digit_sum(x), x))

