def getAllPrimeFactors(n):
    # Validate input
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []
    if isinstance(n, float) and not n.is_integer():
        return []
    if n <= 0:
        return []

    # Edge case for n=1
    if n == 1:
        return [1]

    # Prime factorization
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)

    return factors


def getUniquePrimeFactorsWithCount(n):
    # Validate input
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return [[], []]
    if isinstance(n, float) and not n.is_integer():
        return [[], []]
    if n <= 0:
        return [[], []]

    # Edge case for n=1
    if n == 1:
        return [[1], [1]]

    # Prime factorization with counting
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1

    # Return sorted unique factors and their counts
    unique_factors = sorted(factors.keys())
    counts = [factors[f] for f in unique_factors]

    return [unique_factors, counts]


def getUniquePrimeFactorsWithProducts(n):
    # Validate input
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []
    if isinstance(n, float) and not n.is_integer():
        return []
    if n <= 0:
        return []

    # Edge case for n=1
    if n == 1:
        return [1]

    # Prime factorization with counting
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1

    # Calculate products (prime^count for each unique prime)
    products = [f ** count for f, count in sorted(factors.items())]

    return products

import math

def sum_of_squares(n):
    # Check if n is a perfect square
    sqrt_n = int(math.sqrt(n))
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n can be represented as sum of two squares
    for i in range(1, int(math.sqrt(n)) + 1):
        remainder = n - i * i
        sqrt_remainder = int(math.sqrt(remainder))
        if sqrt_remainder * sqrt_remainder == remainder:
            return 2

    # Check Legendre's three-square theorem
    # n = 4^a * (8b + 7) for some integers a, b >= 0
    while n % 4 == 0:
        n //= 4

    if n % 8 == 7:
        return 4

    # If none of the above, return 3
    return 3

def median(l: list):
    """Return median of elements in the list l.
    >>> median([3, 1, 2, 4, 5])
    3
    >>> median([-10, 4, 6, 1000, 10, 20])
    15.0
    """
    if not l:
        return 0

    sorted_list = sorted(l)
    n = len(sorted_list)

    if n % 2 == 1:
        # Odd length: return the middle element
        return float(sorted_list[n // 2])
    else:
        # Even length: return the average of the two middle elements
        mid1 = sorted_list[n // 2 - 1]
        mid2 = sorted_list[n // 2]
        return float((mid1 + mid2) / 2)

def simplify(expression):
    if not expression:
        return ""

    # Parse the expression into terms
    terms = []
    i = 0
    while i < len(expression):
        # Handle sign
        if expression[i] == '+':
            sign = 1
            i += 1
        elif expression[i] == '-':
            sign = -1
            i += 1
        else:
            sign = 1

        # Parse coefficient
        coeff = 0
        start = i
        while i < len(expression) and expression[i].isdigit():
            coeff = coeff * 10 + int(expression[i])
            i += 1

        if start == i:  # No digits found, coefficient is 1 or -1
            coeff = 1
        else:
            coeff = coeff * sign

        # Parse variables
        variables = []
        while i < len(expression) and expression[i].islower():
            variables.append(expression[i])
            i += 1

        # Normalize variables (sort them)
        normalized_vars = ''.join(sorted(variables))

        # Add to terms
        if variables:  # Only add if there are variables
            terms.append((coeff, normalized_vars))
        else:  # Handle constant terms (no variables)
            terms.append((coeff, ""))

    # Accumulate coefficients by normalized variable string
    coeff_dict = {}
    for coeff, var_str in terms:
        if var_str in coeff_dict:
            coeff_dict[var_str] += coeff
        else:
            coeff_dict[var_str] = coeff

    # Filter out zero coefficients and create list of (coeff, var_str) pairs
    result_terms = [(coeff, var_str) for var_str, coeff in coeff_dict.items() if coeff != 0]

    # Sort by number of variables (ascending), then lexicographically
    result_terms.sort(key=lambda x: (len(x[1]), x[1]))

    # Format output
    result = []
    for i, (coeff, var_str) in enumerate(result_terms):
        if coeff == 1 and var_str != "":
            term = var_str
        elif coeff == -1 and var_str != "":
            term = "-" + var_str
        else:
            term = str(coeff) + var_str

        if i == 0 and coeff > 0:
            result.append(term)
        else:
            if coeff > 0:
                result.append("+" + term)
            else:
                result.append("-" + term)

    # Special case for empty result
    if not result:
        return ""

    # Join and fix the first term if it starts with a +
    output = "".join(result)
    if output.startswith("+"):
        output = output[1:]

    return output

def getAllPrimeFactors(n):
    # Error handling
    if not isinstance(n, int) or not isinstance(n, (int, float)) or n <= 0:
        return []

    if n == 1:
        return [1]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Error handling
    if not isinstance(n, int) or not isinstance(n, (int, float)) or n <= 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)
    unique_factors = []
    counts = []

    if not factors:
        return [[], []]

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Error handling
    if not isinstance(n, int) or not isinstance(n, (int, float)) or n <= 0:
        return []

    if n == 1:
        return [1]

    unique_factors, counts = getUniquePrimeFactorsWithCount(n)
    products = []

    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """
    def to_number(val):
        if isinstance(val, (int, float)):
            return float(val)
        elif isinstance(val, str):
            # Replace comma with dot for decimal separator, then convert to float
            return float(val.replace(',', '.').strip())
        else:
            raise TypeError(f"Unsupported type: {type(val)}")

    num_a = to_number(a)
    num_b = to_number(b)

    if num_a > num_b:
        return a
    elif num_b > num_a:
        return b
    else:
        return None

