def largest_divisor(n: int) -> int:
    if n <= 1:
        return 1

    max_divisor = 1

    # Iterate up to sqrt(n)
    i = 1
    while i * i <= n:
        if n % i == 0:
            # i is a divisor
            if i < n:
                max_divisor = max(max_divisor, i)

            # n//i is also a divisor
            complement = n // i
            if complement < n:
                max_divisor = max(max_divisor, complement)
        i += 1

    return max_divisor

def exchange_sort(sequence):
    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for val in sequence:
        count[val] += 1

    # Create target positions for each value
    # 7s go first, then 8s, then 9s
    target_positions = []
    for val in [7, 8, 9]:
        target_positions.extend([val] * count[val])

    # Create mapping from current positions to target positions
    # This tells us where each element should go
    pos_map = {}
    for i, val in enumerate(sequence):
        if val not in pos_map:
            pos_map[val] = []
        pos_map[val].append(i)

    # Create a mapping from current index to target index
    current_to_target = {}
    target_idx = 0
    for val in [7, 8, 9]:
        for _ in range(count[val]):
            current_to_target[target_idx] = target_idx
            target_idx += 1

    # Create mapping from current positions to target positions
    # We need to track where each element should go
    element_positions = []
    for i, val in enumerate(sequence):
        element_positions.append((val, i))

    # Create target positions for each element
    target_positions = []
    pos_7 = 0
    pos_8 = count[7]
    pos_9 = count[7] + count[8]

    # Build target index mapping
    target_idx_map = {}
    for i, val in enumerate(sequence):
        if val == 7:
            target_idx_map[i] = pos_7
            pos_7 += 1
        elif val == 8:
            target_idx_map[i] = pos_8
            pos_8 += 1
        else:  # val == 9
            target_idx_map[i] = pos_9
            pos_9 += 1

    # Find cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i]:
            # Start a new cycle
            cycle_length = 0
            current = i

            while not visited[current]:
                visited[current] = True
                current = target_idx_map[current]
                cycle_length += 1

            # A cycle of length k requires k-1 swaps
            if cycle_length > 1:
                cycles += 1

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle sign
    sign = ''
    if number < 0:
        sign = '-'
        number = -number

    # Convert integer part
    integer_part = int(number)
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        power = 0
        # Find the highest power needed
        while base ** (power + 1) <= temp:
            power += 1
        # Extract digits from highest power down
        while power >= 0:
            if base ** power <= temp:
                digit = int(temp // (base ** power))
                integer_digits.append(digit)
                temp -= digit * (base ** power)
            else:
                integer_digits.append(0)
            power -= 1

    # Convert fractional part
    fractional_part = number - integer_part
    fractional_digits = []

    if fractional_part > 0 and decimals > 0:
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            fractional_digits.append(digit)
            fractional_part -= digit

    # Convert digits to characters
    digits_map = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

    # Build integer part string
    if integer_digits:
        integer_str = ''.join(digits_map[d] for d in integer_digits)
    else:
        integer_str = '0'

    # Build fractional part string
    if fractional_digits:
        fractional_str = ''.join(digits_map[d] for d in fractional_digits)
        result = integer_str + '.' + fractional_str
    else:
        result = integer_str

    return sign + result

