def getAllPrimeFactors(n):
    # Error handling
    if not isinstance(n, (int, float)):
        return []
    if isinstance(n, float) and not n.is_integer():
        return []
    if n < 0 or n == 0:
        return []

    n = int(n)

    if n == 1:
        return [1]

    factors = []
    temp = n

    # Divide by 2 first
    d = 2
    while temp % d == 0:
        factors.append(d)
        temp //= d

    # Check odd divisors
    d = 3
    while d * d <= temp:
        while temp % d == 0:
            factors.append(d)
            temp //= d
        d += 2

    # If temp > 1, it's a prime factor
    if temp > 1:
        factors.append(temp)

    return factors


def getUniquePrimeFactorsWithCount(n):
    # Error handling
    if not isinstance(n, (int, float)):
        return [[], []]
    if isinstance(n, float) and not n.is_integer():
        return [[], []]
    if n < 0 or n == 0:
        return [[], []]

    n = int(n)

    if n == 1:
        return [[1], [1]]

    all_factors = getAllPrimeFactors(n)

    if not all_factors:
        return [[], []]

    unique_primes = []
    counts = []

    i = 0
    while i < len(all_factors):
        prime = all_factors[i]
        count = 0
        while i < len(all_factors) and all_factors[i] == prime:
            count += 1
            i += 1
        unique_primes.append(prime)
        counts.append(count)

    return [unique_primes, counts]


def getUniquePrimeFactorsWithProducts(n):
    # Error handling
    if not isinstance(n, (int, float)):
        return []
    if isinstance(n, float) and not n.is_integer():
        return []
    if n < 0 or n == 0:
        return []

    n = int(n)

    if n == 1:
        return [1]

    result = getUniquePrimeFactorsWithCount(n)
    unique_primes = result[0]
    counts = result[1]

    products = [p ** c for p, c in zip(unique_primes, counts)]
    return products

import math

def sum_of_squares(n):
    # Check if n is a perfect square
    sqrt_n = int(math.sqrt(n))
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n can be represented as sum of two squares
    for i in range(1, int(math.sqrt(n)) + 1):
        remainder = n - i * i
        sqrt_remainder = int(math.sqrt(remainder))
        if sqrt_remainder * sqrt_remainder == remainder:
            return 2

    # Check if n can be represented as sum of three squares
    # Using Legendre's three-square theorem: n = 4^a * (8b + 7) cannot be represented as sum of three squares
    while n % 4 == 0:
        n //= 4

    if n % 8 == 7:
        return 4

    # If none of the above, it can be represented as sum of three squares
    return 3

