def valid_mersenne(n):
    if n <= 1:
        return False

    # Check if n is a Mersenne number (form 2^k - 1)
    # A number n is a Mersenne number if n + 1 is a power of 2
    n_plus_1 = n + 1

    # Check if n_plus_1 is a power of 2
    if n_plus_1 & (n_plus_1 - 1) != 0:
        return False

    # Now check if n is prime
    # Since n = 2^k - 1, for n to be a Mersenne prime, k must be prime
    # But we'll check primality of n directly

    # Special case for small n
    if n < 2:
        return False
    if n == 2:
        return False  # 2 is not a Mersenne number (2 = 2^1 - 0, not 2^k - 1)
    if n % 2 == 0:
        return False

    # Check for primality
    import math
    sqrt_n = int(math.sqrt(n)) + 1
    for i in range(3, sqrt_n, 2):
        if n % i == 0:
            return False

    return True

