def count_up_to(n):
    if n <= 2:
        return []

    # Use Sieve of Eratosthenes to find all primes less than n
    sieve = [True] * n
    sieve[0] = sieve[1] = False

    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n, i):
                sieve[j] = False

    # Collect primes
    primes = []
    for i in range(2, n):
        if sieve[i]:
            primes.append(i)

    return primes

