def solution(text, comment_markers):
    if not text:
        return ""

    lines = text.split('\n')
    result_lines = []

    for line in lines:
        # Initialize min_index to the end of the line (no comment found)
        min_index = len(line)

        # Find the first occurrence of any comment marker
        for marker in comment_markers:
            index = line.find(marker)
            if index != -1 and index < min_index:
                min_index = index

        # Extract the line up to (but not including) the first comment marker
        processed_line = line[:min_index]

        # Strip trailing whitespace
        processed_line = processed_line.rstrip()

        result_lines.append(processed_line)

    return '\n'.join(result_lines)

def correct_bracketing(brackets: str):
    balance = 0
    for char in brackets:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
            if balance < 0:
