def amazonCheckmate(king, amazon):
    def pos_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def coords_to_pos(x, y):
        return chr(x + ord('a')) + str(y + 1)

    def is_valid(x, y):
        return 0 <= x < 8 and 0 <= y < 8

    def get_amazon_attacks(amazon_x, amazon_y):
        attacks = set()

        # Queen moves (rook + bishop)
        # Horizontal and vertical
        for i in range(8):
            if i != amazon_x:
                attacks.add((i, amazon_y))
        for j in range(8):
            if j != amazon_y:
                attacks.add((amazon_x, j))

        # Diagonals
        for dx in [-1, 1]:
            for dy in [-1, 1]:
                x, y = amazon_x + dx, amazon_y + dy
                while is_valid(x, y):
                    attacks.add((x, y))
                    x += dx
                    y += dy

        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), 
                       (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            x, y = amazon_x + dx, amazon_y + dy
            if is_valid(x, y):
                attacks.add((x, y))

        return attacks

    def get_king_safe_moves(king_x, king_y):
        moves = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                x, y = king_x + dx, king_y + dy
                if is_valid(x, y):
                    moves.append((x, y))
        return moves

    def is_adjacent(king_x, king_y, target_x, target_y):
        return abs(king_x - target_x) <= 1 and abs(king_y - target_y) <= 1

    def is_safe(king_x, king_y, target_x, target_y):
        # Check if target position is adjacent to white king
        if is_adjacent(king_x, king_y, target_x, target_y):
            return False
        return True

    # Convert input positions to coordinates
    king_x, king_y = pos_to_coords(king)
    amazon_x, amazon_y = pos_to_coords(amazon)

    # Get all squares amazon attacks
    amazon_attacks = get_amazon_attacks(amazon_x, amazon_y)

    # Get all possible black king positions
    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    # Iterate through all possible black king positions
    for x in range(8):
        for y in range(8):
            # Skip if position is adjacent to white king
            if is_adjacent(king_x, king_y, x, y):
                continue

            # Check if black king is under attack
            is_under_attack = (x, y) in amazon_attacks

            if is_under_attack:
                # Check if it's checkmate (under attack and no safe moves)
                safe_moves = get_king_safe_moves(x, y)
                can_escape = False
                for move_x, move_y in safe_moves:
                    # Check if move is safe (not adjacent to white king and not under attack)
                    if is_safe(king_x, king_y, move_x, move_y) and (move_x, move_y) not in amazon_attacks:
                        can_escape = True
                        break

                if can_escape:
                    check += 1
                else:
                    checkmate += 1
            else:
                # King is safe, check if it can move
                safe_moves = get_king_safe_moves(x, y)
                can_move = False
                for move_x, move_y in safe_moves:
                    if is_safe(king_x, king_y, move_x, move_y) and (move_x, move_y) not in amazon_attacks:
                        can_move = True
                        break

                if can_move:
                    safe += 1
                else:
                    stalemate += 1

    return [checkmate, check, stalemate, safe]

