def differentiate(polynomial, x):
    # Parse the polynomial into terms
    # Replace 'x' with 'x^1' for easier parsing
    polynomial = polynomial.replace('x', 'x^1')
    # Replace 'x^' with 'x^1' when there's no explicit power
    polynomial = polynomial.replace('x^', 'x^1')

    # Split by + and - signs
    terms = []
    current_term = ""
    for i, char in enumerate(polynomial):
        if char in ['+', '-'] and i > 0:
            terms.append(current_term)
            current_term = char
        else:
            current_term += char
    terms.append(current_term)

    # Remove empty terms
    terms = [term for term in terms if term.strip()]

    # Process each term
    derivative = 0
    for term in terms:
        # Handle the sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Parse coefficient and exponent
        if 'x^' in term:
            parts = term.split('x^')
            if parts[0] == '':
                coeff = 1
            elif parts[0] == '-':
                coeff = -1
            else:
                coeff = int(parts[0])
            exp = int(parts[1])
        elif 'x' in term:
            coeff = int(term.replace('x', '')) if term.replace('x', '') not in ['', '-'] else (1 if term.replace('x', '') != '-' else -1)
            exp = 1
        else:
            coeff = int(term)
            exp = 0

        # Apply derivative rule: d/dx(ax^n) = n*ax^(n-1)
        if exp > 0:
            new_coeff = coeff * exp
            new_exp = exp - 1
            if new_exp == 0:
                derivative += sign * new_coeff
            else:
                derivative += sign * new_coeff * (x ** new_exp)
        else:
            # Constant term derivative is 0
            pass

    return int(derivative)

def simplify(expression):
    # Parse the expression into monomials
    monomials = []
    i = 0
    n = len(expression)

    # Handle the first term separately (may not have leading sign)
    while i < n and expression[i] not in '+-':
        i += 1
    if i > 0:
        monomials.append(expression[:i])

    # Handle remaining terms (each starts with + or -)
    while i < n:
        start = i
        i += 1  # skip the sign
        while i < n and expression[i] not in '+-':
            i += 1
        monomials.append(expression[start:i])

    # Dictionary to store combined terms: key = sorted variables, value = coefficient
    terms = {}

    for mono in monomials:
        # Determine sign and extract parts
        sign = 1
        start_idx = 0
        if mono[0] == '-':
            sign = -1
            start_idx = 1
        elif mono[0] == '+':
            start_idx = 1

        mono_content = mono[start_idx:]

        # Extract coefficient
        coef_str = ""
        j = 0
        while j < len(mono_content) and mono_content[j].isdigit():
            coef_str += mono_content[j]
            j += 1

        if coef_str:
            coef = int(coef_str) * sign
        else:
            coef = sign

        # Extract variables
        variables = mono_content[j:]
        sorted_vars = ''.join(sorted(variables))

        # Combine coefficients for same variable combinations
        if sorted_vars not in terms:
            terms[sorted_vars] = 0
        terms[sorted_vars] += coef

    # Remove terms with zero coefficient
    terms = {k: v for k, v in terms.items() if v != 0}

    # Sort terms: by variable count (ascending), then lexicographically
    sorted_terms = sorted(terms.items(), key=lambda x: (len(x[0]), x[0]))

    # Build result string
    result_parts = []
    for i, (variables, coef) in enumerate(sorted_terms):
        if coef == 1:
            term_str = variables if variables else "1"
        elif coef == -1:
            term_str = "-" + variables if variables else "-1"
        elif coef > 0:
            term_str = str(coef) + variables if variables else str(coef)
        else:  # coef < 0
            term_str = str(coef) + variables if variables else str(coef)

        if i == 0 and coef > 0:
            # Remove leading + for first positive term
            if term_str.startswith('+'):
                term_str = term_str[1:]

        result_parts.append(term_str)

    return ''.join(result_parts)

def differentiate(polynomial, x):
    # Normalize the polynomial string by ensuring we can split terms correctly
    # Add explicit + before any - that is not at the start (to handle negative terms)
    poly = polynomial
    for i in range(1, len(poly)):
        if poly[i] == '-' and poly[i-1] not in '^0123456789':
            poly = poly[:i] + '+' + poly[i:]

    terms = poly.split('+')
    derivative = 0

    for term in terms:
        if not term or term == '' or term == '+':
            continue

        # Determine sign
        sign = 1
        start_idx = 0
        if term[0] == '-':
            sign = -1
            start_idx = 1
        elif term[0] == '+':
            sign = 1
            start_idx = 1

        term = term[start_idx:]

        if not term:
            continue

        # If term doesn't contain x, it's a constant - derivative is 0
        if 'x' not in term:
            continue

        # Split into coefficient part and exponent part
        if '^' in term:
            coeff_part, exp_part = term.split('^')
            exponent = int(exp_part)
        else:
            coeff_part = term
            exponent = 1

        # Extract coefficient
        if coeff_part == '' or coeff_part == 'x':
            coefficient = 1
        elif coeff_part == '-x':
            coefficient = -1
        elif 'x' in coeff_part:
            # There's a number before x
            idx = coeff_part.index('x')
            num_part = coeff_part[:idx]
            if num_part == '' or num_part == '+':
                coefficient = 1
            elif num_part == '-':
                coefficient = -1
            else:
                coefficient = int(num_part)
        else:
            coefficient = int(coeff_part)

        coefficient *= sign

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent > 0:
            derivative += exponent * coefficient * (x ** (exponent - 1))

    return derivative

def amazon_check_mate(king, amazon):
    # Convert chess notation to coordinates (0-7, 0-7)
    def parse_pos(pos):
        col = ord(pos[0]) - ord('a')
        row = int(pos[1]) - 1
        return (col, row)

    # Check if a position is on the board
    def is_valid(col, row):
        return 0 <= col < 8 and 0 <= row < 8

    # Get all squares attacked by amazon (ignoring blocking)
    def get_amazon_attacks(amazon_col, amazon_row):
        attacks = set()

        # Queen-like moves (horizontal, vertical, diagonal)
        for dc in [-1, 0, 1]:
            for dr in [-1, 0, 1]:
                if dc == 0 and dr == 0:
                    continue
                c, r = amazon_col, amazon_row
                while True:
                    c += dc
                    r += dr
                    if not is_valid(c, r):
                        break
                    attacks.add((c, r))

        # Knight-like moves (L-shaped)
        knight_moves = [
            (2, 1), (2, -1), (-2, 1), (-2, -1),
            (1, 2), (1, -2), (-1, 2), (-1, -2)
        ]
        for dc, dr in knight_moves:
            c = amazon_col + dc
            r = amazon_row + dr
            if is_valid(c, r):
                attacks.add((c, r))

        return attacks

    # Get all squares adjacent to a position (including diagonals)
    def get_adjacent(col, row):
        adjacent = set()
        for dc in [-1, 0, 1]:
            for dr in [-1, 0, 1]:
                if dc == 0 and dr == 0:
                    continue
                c = col + dc
                r = row + dr
                if is_valid(c, r):
                    adjacent.add((c, r))
        return adjacent

    # Check if square is attacked by amazon (considering white king blocks)
    def is_attacked(black_col, black_row):
        # Amazon attacks
        attacked = False

        # Check queen-like attacks (with blocking by white king)
        for dc in [-1, 0, 1]:
            for dr in [-1, 0, 1]:
                if dc == 0 and dr == 0:
                    continue
                c, r = amazon_col, amazon_row
                while True:
                    c += dc
                    r += dr
                    if not is_valid(c, r):
                        break
                    if (c, r) == (black_col, black_row):
                        attacked = True
                        break
                    if (c, r) == (king_col, king_row):
                        break  # White king blocks

        # Check knight attacks (not blocked)
        if not attacked:
            knight_moves = [
                (2, 1), (2, -1), (-2, 1), (-2, -1),
                (1, 2), (1, -2), (-1, 2), (-1, -2)
            ]
            for dc, dr in knight_moves:
                c = amazon_col + dc
                r = amazon_row + dr
                if (c, r) == (black_col, black_row):
                    attacked = True
                    break

        return attacked

    # Parse positions
    king_col, king_row = parse_pos(king)
    amazon_col, amazon_row = parse_pos(amazon)

    # Get squares adjacent to white king (black king cannot be here)
    king_adjacent = get_adjacent(king_col, king_row)

    # Results for each scenario
    checkmate_count = 0
    check_count = 0
    stalemate_count = 0
    safe_count = 0

    # Check all possible black king positions
    for col in range(8):
        for row in range(8):
            # Black king cannot be on white king or amazon square
            if (col, row) == (king_col, king_row):
                continue
            if (col, row) == (amazon_col, amazon_row):
                continue

            # Black king cannot be adjacent to white king
            if (col, row) in king_adjacent:
                continue

            # Check if black king is under amazon's attack
            in_check = is_attacked(col, row)

            # Find all valid moves for black king
            valid_moves = 0
            for dc in [-1, 0, 1]:
                for dr in [-1, 0, 1]:
                    if dc == 0 and dr == 0:
                        continue
                    new_col = col + dc
                    new_row = row + dr
                    if not is_valid(new_col, new_row):
                        continue
                    # Cannot move to white king or amazon
                    if (new_col, new_row) == (king_col, king_row):
                        continue
                    if (new_col, new_row) == (amazon_col, amazon_row):
                        continue
                    # Cannot move adjacent to white king
                    if (new_col, new_row) in king_adjacent:
                        continue
                    # Cannot move to amazon's attacked square
                    if is_attacked(new_col, new_row):
                        continue
                    valid_moves += 1

            # Classify the position
            if in_check:
                if valid_moves == 0:
                    checkmate_count += 1
                else:
                    check_count += 1
            else:
                if valid_moves == 0:
                    stalemate_count += 1
                else:
                    safe_count += 1

    return [checkmate_count, check_count, stalemate_count, safe_count]

def exchange_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                arr[i], arr[j] = arr[j], arr[i]
    return arr

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)

def almost_everywhere_zero(n, k):
    s = str(n)
    length = len(s)

    memo = {}

    def dp(pos, count, tight, started):
        if count > k:
            return 0

        if pos == length:
            return 1 if started and count == k else 0

        state = (pos, count, tight, started)
        if state in memo:
            return memo[state]

        result = 0
        limit = int(s[pos]) if tight else 9

        for digit in range(0, limit + 1):
            new_tight = tight and (digit == limit)
            new_started = started or (digit != 0)
            new_count = count + (1 if digit != 0 else 0)

            if new_count <= k:
                result += dp(pos + 1, new_count, new_tight, new_started)

        memo[state] = result
        return result

    return dp(0, 0, True, False)

def even_odd_palindrome(k):
    def is_palindrome(n):
        s = str(n)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for num in range(1, k + 1):
        if is_palindrome(num):
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return even_count, odd_count

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    gems = list(map(int, lines[1].split()))

    # Precompute palindromes
    is_palindrome = [[False] * n for _ in range(n)]

    # Every single gem is a palindrome
    for i in range(n):
        is_palindrome[i][i] = True

    # Check for palindromes of length 2
    for i in range(n - 1):
        if gems[i] == gems[i + 1]:
            is_palindrome[i][i + 1] = True

    # Check for palindromes of length 3 and more
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if gems[i] == gems[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP approach
    # dp[i][j] represents minimum time to remove gems from i to j
    dp = [[0] * n for _ in range(n)]

    # Base case: single gem requires 1 second
    for i in range(n):
        dp[i][i] = 1

    # Fill DP table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if is_palindrome[i][j]:
                # If the substring is palindrome, we can remove it in 1 second
                dp[i][j] = 1
            else:
                # Otherwise, split and find minimum
                dp[i][j] = length  # Worst case: remove each one by one
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

