def largest_divisor(n: int) -> int:
    if n <= 1:
        return 1

    # Find the smallest prime factor
    smallest_factor = n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            smallest_factor = i
            break

    # If no factor found, n is prime, so largest divisor smaller than n is 1
    if smallest_factor == n:
        return 1

    # Otherwise, largest divisor smaller than n is n/smallest_factor
    return n // smallest_factor

