def simplify(expr):
    if not expr:
        return ""

    # Preprocess: ensure each term starts with + or -
    if expr[0] != '-':
        expr = '+' + expr

    # Step 1: Split into terms
    terms = []
    i = 0
    while i < len(expr):
        if expr[i] in '+-':
            j = i + 1
            while j < len(expr) and expr[j] not in '+-':
                j += 1
            terms.append(expr[i:j])
            i = j
        else:
            i += 1

    # Step 2: Parse each term into (coefficient, sorted_variables)
    def parse_term(term):
        # term starts with + or -
        sign = 1
        idx = 1

        # Check if there's a digit (explicit coefficient)
        if idx < len(term) and term[idx].isdigit():
            num_end = idx
            while num_end < len(term) and term[num_end].isdigit():
                num_end += 1
            coeff = int(term[idx:num_end])
            if term[0] == '-':
                coeff = -coeff
            var_str = term[num_end:]
        else:
            # Implicit coefficient of 1
            coeff = 1 if term[0] == '+' else -1
            var_str = term[idx:]

        # Normalize variables by sorting alphabetically
        var_sorted = ''.join(sorted(var_str))
        return coeff, var_sorted

    # Step 3: Aggregate terms by variable string
    from collections import defaultdict
    aggregated = defaultdict(int)

    for term in terms:
        coeff, var_str = parse_term(term)
        aggregated[var_str] += coeff

    # Step 4: Remove zero coefficients
    filtered = {k: v for k, v in aggregated.items() if v != 0}

    if not filtered:
        return "0"

    # Step 5: Sort by number of variables ascending, then lexicographically
    sorted_vars = sorted(filtered.keys(), key=lambda v: (len(v), v))

    # Step 6: Format the output
    result_parts = []
    for i, var_str in enumerate(sorted_vars):
        coeff = filtered[var_str]

        # Format coefficient part
        if coeff == 1:
            coeff_str = ''
        elif coeff == -1:
            coeff_str = '-'
        else:
            coeff_str = str(coeff)

        # Build the term
        term_str = coeff_str + var_str

        # Handle first term specially (no leading +)
        if i == 0:
            result_parts.append(term_str)
        else:
            # Remove leading + for non-first terms
            if term_str.startswith('+'):
                term_str = term_str[1:]
            result_parts.append(term_str)

    return ''.join(result_parts)

