def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """

    # Helper function to extract integers from potentially nested/irregular input
    def extract_integers(items):
        integers = []
        if isinstance(items, list):
            for item in items:
                if isinstance(item, int) and not isinstance(item, bool):
                    integers.append(item)
                elif isinstance(item, list):
                    integers.extend(extract_integers(item))
                # Skip None and other non-integer values
        return integers

    # Handle None or non-list input
    if numbers is None or not isinstance(numbers, list):
        return (0, 1)

    # Extract all integers from the input
    valid_integers = extract_integers(numbers)

    # Calculate sum and product
    total_sum = sum(valid_integers) if valid_integers else 0
    total_product = 1
    for num in valid_integers:
        total_product *= num

    return (total_sum, total_product)

