def proper_fractions(d):
    if d == 1:
        return 0

    result = d

    # Handle factor 2
    if d % 2 == 0:
        result = result // 2
        while d % 2 == 0:
            d //= 2

    # Handle odd prime factors
    i = 3
    while i * i <= d:
        if d % i == 0:
            result = result // i * (i - 1)
            while d % i == 0:
                d //= i
        i += 2

    # If remaining d > 1, it's a prime factor
    if d > 1:
        result = result // d * (d - 1)

    return result

