def parse_int(s):
    if not s:
        return 0

    # Define mappings for number words
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14, 'fifteen': 15,
        'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19, 'twenty': 20,
        'thirty': 30, 'forty': 40, 'fifty': 50, 'sixty': 60, 'seventy': 70,
        'eighty': 80, 'ninety': 90
    }

    # Split the string by spaces and hyphens
    parts = []
    for part in s.split():
        parts.extend(part.split('-'))

    # Remove empty parts
    parts = [part for part in parts if part]

    # Handle special case for "and"
    cleaned_parts = []
    for i, part in enumerate(parts):
        if part == 'and':
            # Skip 'and' if it's at the beginning or end, or if it's between two numbers
            if i > 0 and i < len(parts) - 1:
                # Check if both neighbors are numbers
                if parts[i-1] in word_to_num and parts[i+1] in word_to_num:
                    continue  # Skip the 'and'
        cleaned_parts.append(part)

    parts = cleaned_parts

    result = 0
    current = 0

    for part in parts:
        if part in word_to_num:
            current += word_to_num[part]
        elif part == 'hundred':
            current *= 100
        elif part == 'thousand':
            result += current * 1000
            current = 0
        elif part == 'million':
            result += current * 1000000
            current = 0

    result += current
    return result

def proper_fractions(d):
    if d == 1:
        return 0

    result = d

    # Check for factor 2
    if d % 2 == 0:
        result -= result // 2
        while d % 2 == 0:
            d //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= d:
        if d % i == 0:
            result -= result // i
            while d % i == 0:
                d //= i
        i += 2

    # If d is still greater than 1, then it's a prime factor
    if d > 1:
        result -= result // d

    return result

def is_valid(identifier):
    # Check if identifier is empty
    if not identifier:
        return False

    # Check first character - must be alpha, underscore, or dollar sign
    first_char = identifier[0]
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Check remaining characters - can be alpha, digit, underscore, or dollar sign
    for char in identifier[1:]:
        if not (char.isalnum() or char == '_' or char == '$'):
            return False

    return True

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    return sorted(nums, key=digit_sum)

def amazon_check_mate(king, amazon):
    def chess_to_coords(pos):
        return (ord(pos[0]) - ord('a'), int(pos[1]) - 1)

    def is_valid(r, c):
        return 0 <= r < 8 and 0 <= c < 8

    def is_adjacent(r1, c1, r2, c2):
        return abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1

    def is_attacked(r, c, king_r, king_c, amazon_r, amazon_c):
        # Check if amazon can attack position (r, c) using queen moves
        # Queen moves: horizontal, vertical, diagonal
        if (r == amazon_r or c == amazon_c or 
            abs(r - amazon_r) == abs(c - amazon_c)):
            # Check if the path is blocked by king
            if (r == amazon_r and c == amazon_c) or \
               (r == king_r and c == king_c):
                return False
            # Check if path is blocked by king or amazon
            if r == amazon_r:
                # Horizontal attack
                min_c, max_c = min(c, amazon_c), max(c, amazon_c)
                if (king_r == r and min_c < king_c < max_c):
                    return False
            elif c == amazon_c:
                # Vertical attack
                min_r, max_r = min(r, amazon_r), max(r, amazon_r)
                if (king_c == c and min_r < king_r < max_r):
                    return False
            elif abs(r - amazon_r) == abs(c - amazon_c):
                # Diagonal attack
                dr = 1 if r > amazon_r else -1
                dc = 1 if c > amazon_c else -1
                r_temp, c_temp = amazon_r + dr, amazon_c + dc
                while (r_temp != r and c_temp != c):
                    if r_temp == king_r and c_temp == king_c:
                        return False
                    r_temp += dr
                    c_temp += dc
            return True

        # Check if amazon can attack position (r, c) using knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), 
                       (1, -2), (1, 2), (2, -1), (2, 1)]
        for dr, dc in knight_moves:
            if r == amazon_r + dr and c == amazon_c + dc:
                return True
        return False

    king_r, king_c = chess_to_coords(king)
    amazon_r, amazon_c = chess_to_coords(amazon)

    # Precompute all squares adjacent to the white king
    adjacent_squares = set()
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = king_r + dr, king_c + dc
            if is_valid(nr, nc):
                adjacent_squares.add((nr, nc))

    checkmate = 0
    check = 0
    stalemate = 0
    safe = 0

    # Check all possible black king positions
    for r in range(8):
        for c in range(8):
            # Skip if position is occupied by white king or amazon
            if (r == king_r and c == king_c) or (r == amazon_r and c == amazon_c):
                continue

            # Skip if position is adjacent to white king
            if (r, c) in adjacent_squares:
                continue

            # Check if black king position is under attack
            attacked = is_attacked(r, c, king_r, king_c, amazon_r, amazon_c)

            # Count valid escape squares
            escape_count = 0
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    # Check if escape square is valid
                    if (is_valid(nr, nc) and 
                        not (nr == king_r and nc == king_c) and
                        (nr, nc) not in adjacent_squares and
                        not is_attacked(nr, nc, king_r, king_c, amazon_r, amazon_c)):
                        escape_count += 1

            if attacked:
                if escape_count == 0:
                    checkmate += 1
                else:
                    check += 1
            else:
                if escape_count == 0:
                    stalemate += 1
                else:
                    safe += 1

    return [checkmate, check, stalemate, safe]

def valid_mersenne(n):
    def is_prime(x):
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
