def parse_int(text):
    # Mappings for basic numbers and scales
    ones = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9,
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17,
        'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    # Normalize the input: lowercase, remove 'and', replace hyphens with spaces
    text = text.lower()
    text = text.replace(' and ', ' ')
    text = text.replace('-', ' ')

    tokens = text.split()

    result = 0
    current = 0

    for token in tokens:
        if not token:
            continue

        if token in ones:
            current += ones[token]
        elif token in tens:
            current += tens[token]
        elif token == 'hundred':
            current *= 100
        elif token == 'thousand':
            result += current * 1000
            current = 0
        elif token == 'million':
            result += current * 1000000
            current = 0

    return result + current

def pig_latin(word):
    if not word:
        return None

    if not word.isalpha():
        return None

    word = word.lower()

    vowels = "aeiou"

    if word[0] in vowels:
        return word + "way"

    # Find the index where the first vowel occurs
    first_vowel_index = 0
    for i, char in enumerate(word):
        if char in vowels:
            first_vowel_index = i
            break
    else:
        # No vowels found
        return word + "ay"

    # Move consonants before the first vowel to the end
    result = word[first_vowel_index:] + word[:first_vowel_index] + "ay"

    return result

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Handle edge case: empty string or string with only spaces
    if not test.strip():
        return {}

    # Split the string by spaces to get individual characters
    characters = test.split()

    # Count occurrences of each character
    counts = {}
    for char in characters:
        counts[char] = counts.get(char, 0) + 1

    # Find the maximum frequency
    max_count = max(counts.values())

    # Filter to include only characters with the maximum frequency
    result = {char: count for char, count in counts.items() if count == max_count}

    return result

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 365 * 24 * 60 * 60),
        ('day', 24 * 60 * 60),
        ('hour', 60 * 60),
        ('minute', 60),
        ('second', 1)
    ]

    components = []

    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            if count > 1:
                components.append(f"{count} {unit_name}s")
            else:
                components.append(f"{count} {unit_name}")

    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

