def solution(input_string, comment_markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the earliest comment marker position
        min_pos = len(line)
        for marker in comment_markers:
            pos = line.find(marker)
            if pos != -1 and pos < min_pos:
                min_pos = pos

        # If we found a comment marker, truncate the line
        if min_pos < len(line):
            line = line[:min_pos]

        # Strip trailing whitespace
        line = line.rstrip()
        result_lines.append(line)

    return '\n'.join(result_lines)

def sum_of_squares(n):
    # Check if n is a perfect square (answer = 1)
    sqrt_n = int(n**0.5)
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n is sum of two squares (answer = 2)
    # Try all squares s where s < n, check if n - s is also a perfect square
    for i in range(1, sqrt_n + 1):
        j = n - i*i
        if j <= 0:
            break
        sqrt_j = int(j**0.5)
        if sqrt_j * sqrt_j == j:
            return 2

    # Check Legendre's three-square theorem condition
    # If n = 4^k * (8m + 7) for integers k, m >= 0, then answer = 4, else answer = 3
    temp = n
    while temp % 4 == 0:
        temp //= 4

    if temp % 8 == 7:
        return 4

    return 3

def proper_fractions(n):
    if n == 1:
        return 0

    result = n

    # Check for factor 2
    if n % 2 == 0:
        result -= result // 2
        while n % 2 == 0:
            n //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result -= result // i
            while n % i == 0:
                n //= i
        i += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        result -= result // n

    return result

