    else:
        return "Not!!"

def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        # Check if palindrome
        str_i = str(i)
        if str_i == str_i[::-1]:
            # Check if even or odd
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def amazon_check_mate(king, amazon):
    # Convert chess notation to coordinates (a=0, ..., h=7 for columns; 1=0, ..., 8=7 for rows)
    def parse_pos(pos):
        col = ord(pos[0]) - ord('a')
        row = int(pos[1]) - 1
        return (row, col)

    # Check if position is on board
    def is_valid_pos(pos):
        return 0 <= pos[0] <= 7 and 0 <= pos[1] <= 7

    # Get all positions attacked by Amazon from a given position
    def get_amazon_attacks(pos):
        attacks = set()
        row, col = pos

        # Queen-like moves (horizontal and vertical)
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            for i in range(1, 8):
                nr, nc = row + dr * i, col + dc * i
                if is_valid_pos((nr, nc)):
                    attacks.add((nr, nc))

        # Queen-like moves (diagonal)
        for dr, dc in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
            for i in range(1, 8):
                nr, nc = row + dr * i, col + dc * i
                if is_valid_pos((nr, nc)):
                    attacks.add((nr, nc))

        # Knight-like moves
        knight_moves = [
            (-2, -1), (-2, 1), (-1, -2), (-1, 2),
            (1, -2), (1, 2), (2, -1), (2, 1)
        ]
        for dr, dc in knight_moves:
            nr, nc = row + dr, col + dc
            if is_valid_pos((nr, nc)):
                attacks.add((nr, nc))

        return attacks

    # Check if two positions are adjacent (including diagonally), but not the same square
    def is_adjacent(pos1, pos2):
        if pos1 == pos2:
            return False
        return abs(pos1[0] - pos2[0]) <= 1 and abs(pos1[1] - pos2[1]) <= 1

    # Get all possible king moves from a position
    def get_king_moves(pos):
        moves = []
        row, col = pos
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = row + dr, col + dc
                if is_valid_pos((nr, nc)):
                    moves.append((nr, nc))
        return moves

    # Parse input positions
    white_king_pos = parse_pos(king)
    white_amazon_pos = parse_pos(amazon)

    # Get all squares attacked by Amazon
    amazon_attacks = get_amazon_attacks(white_amazon_pos)

    # Counters for each category
    checkmate = 0
    check = 0
    stalemate = 0
    safe_with_moves = 0

    # Check all possible black king positions
    for row in range(8):
        for col in range(8):
            black_king_pos = (row, col)

            # Skip if occupied by white pieces
            if black_king_pos == white_king_pos or black_king_pos == white_amazon_pos:
                continue

            # Skip if adjacent to white king (kings cannot be adjacent)
            if is_adjacent(black_king_pos, white_king_pos):
                continue

            # Check if black king is under Amazon attack
            under_attack = black_king_pos in amazon_attacks

            # Check if black king has valid escape moves
            escape_moves = []
            for move in get_king_moves(black_king_pos):
                # Move must be on board (already guaranteed by get_king_moves)
                # Move cannot be occupied by white pieces
                if move == white_king_pos or move == white_amazon_pos:
                    continue
                # Move cannot be adjacent to white king
                if is_adjacent(move, white_king_pos):
                    continue
                # Move cannot be under Amazon attack
                if move in amazon_attacks:
                    continue
                escape_moves.append(move)

            # Categorize based on attack status and escape moves
            if under_attack:
                if len(escape_moves) == 0:
                    checkmate += 1
                else:
                    check += 1
            else:
                if len(escape_moves) == 0:
                    stalemate += 1
                else:
                    safe_with_moves += 1

    return [checkmate, check, stalemate, safe_with_moves]

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def to_float(x):
        if isinstance(x, (int, float)):
            return float(x)
        elif isinstance(x, str):
            # Replace comma with period for decimal separator
            normalized_str = x.replace(',', '.')
            return float(normalized_str)
        else:
            raise TypeError("Unsupported type")

    # Convert both inputs to float for comparison
    a_float = to_float(a)
    b_float = to_float(b)

    # Compare the float values
    if a_float > b_float:
        return a
    elif b_float > a_float:
        return b
    else:
        return None

def smallest_change(arr):
    n = len(arr)
    changes = 0
    # Compare elements from both ends moving inward
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1
    return changes

def encrypt(s):
    result = ""
    for char in s:
        if char.isalpha():
            if char.islower():
                # For lowercase letters, shift by 4 positions with wraparound
                shifted = (ord(char) - ord('a') + 4) % 26
                result += chr(shifted + ord('a'))
            else:
                # For uppercase letters, shift by 4 positions with wraparound
                shifted = (ord(char) - ord('A') + 4) % 26
                result += chr(shifted + ord('A'))
        else:
            # Non-alphabetic characters remain unchanged
            result += char
    return result

def poohbear(code):
    # Initialize memory as a dictionary for infinite tape
    memory = {}
    pointer = 0
    copied_value = 0
    output = []

    # Preprocess to find matching W and E pairs
    loop_stack = []
    loop_pairs = {}

    for i, char in enumerate(code):
        if char == 'W':
            loop_stack.append(i)
        elif char == 'E':
            if loop_stack:
                start = loop_stack.pop()
                loop_pairs[start] = i
                loop_pairs[i] = start

    # Execute code
    i = 0
    while i < len(code):
        char = code[i]

        # Skip non-command characters
        if char not in "+-><cWEPNTQLIVABYD":
            i += 1
            continue

        if char == '+':
            memory[pointer] = memory.get(pointer, 0) + 1
            memory[pointer] %= 256
        elif char == '-':
            memory[pointer] = memory.get(pointer, 0) - 1
            memory[pointer] %= 256
        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copied_value = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copied_value
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                # Jump to matching E
                i = loop_pairs[i]
            # If not zero, continue normally
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                # Jump to matching W
                i = loop_pairs[i]
            # If zero, continue normally
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif char == 'T':
            memory[pointer] = memory.get(pointer, 0) * 2
            memory[pointer] %= 256
        elif char == 'Q':
            memory[pointer] = memory.get(pointer, 0) ** 2
            memory[pointer] %= 256
        elif char == 'U':
            import math
            memory[pointer] = int(math.sqrt(memory.get(pointer, 0)))
        elif char == 'L':
            memory[pointer] = memory.get(pointer, 0) + 2
            memory[pointer] %= 256
        elif char == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            memory[pointer] %= 256
        elif char == 'V':
            if memory.get(pointer, 0) != 0:
                memory[pointer] = memory.get(pointer, 0) // 2
        elif char == 'A':
            memory[pointer] = memory.get(pointer, 0) + copied_value
            memory[pointer] %= 256
        elif char == 'B':
            memory[pointer] = memory.get(pointer, 0) - copied_value
            memory[pointer] %= 256
        elif char == 'Y':
            memory[pointer] = memory.get(pointer, 0) * copied_value
            memory[pointer] %= 256
        elif char == 'D':
            if copied_value != 0:
                memory[pointer] = memory.get(pointer, 0) // copied_value

        i += 1

    return ''.join(output)

