            # Skip amazon position
            if (row, col) == (am_row, am_col):
                continue

            # Skip if adjacent to white king (invalid position)
            if is_adjacent(row, col, wk_row, wk_col):
                continue

            # Check if under attack by amazon
            under_attack = (row, col) in amazon_attacks

            # Count safe moves from this position
            safe_moves = 0

