def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define conversion factors
    YEAR = 365 * 24 * 60 * 60  # 31536000
    DAY = 24 * 60 * 60         # 86400
    HOUR = 60 * 60             # 3600
    MINUTE = 60

    # Calculate each unit
    years = seconds // YEAR
    seconds = seconds % YEAR

    days = seconds // DAY
    seconds = seconds % DAY

    hours = seconds // HOUR
    seconds = seconds % HOUR

    minutes = seconds // MINUTE
    seconds = seconds % MINUTE

    # Build components list
    components = []

    if years > 0:
        components.append(f"{years} year{'s' if years > 1 else ''}")
    if days > 0:
        components.append(f"{days} day{'s' if days > 1 else ''}")
    if hours > 0:
        components.append(f"{hours} hour{'s' if hours > 1 else ''}")
    if minutes > 0:
        components.append(f"{minutes} minute{'s' if minutes > 1 else ''}")
    if seconds > 0:
        components.append(f"{seconds} second{'s' if seconds > 1 else ''}")

    # Join components with proper formatting
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return " and ".join(components)
    else:
        return ", ".join(components[:-1]) + " and " + components[-1]

def getAllPrimeFactors(n):
    # Error handling - check if n is a number (int or float, but not bool)
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []

    # Check if n is actually an integer (not a float like 2.0)
    if isinstance(n, float):
        return []

    if n < 0:
        return []

    # Edge case n=0
    if n == 0:
        return []

    # Edge case n=1
    if n == 1:
        return [1]

    factors = []
    # Check for 2
    while n % 2 == 0:
        factors.append(2)
        n //= 2

    # Check odd numbers from 3
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 2

    # If n > 2, then n is prime
    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    # Error handling
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return [[], []]

    if isinstance(n, float):
        return [[], []]

    if n < 0:
        return [[], []]

    if n == 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)

    # Count occurrences
    primes = []
    counts = []
    if factors:
        current_prime = factors[0]
        count = 1
        for i in range(1, len(factors)):
            if factors[i] == current_prime:
                count += 1
            else:
                primes.append(current_prime)
                counts.append(count)
                current_prime = factors[i]
                count = 1
        primes.append(current_prime)
        counts.append(count)

    return [primes, counts]

def getUniquePrimeFactorsWithProducts(n):
    # Error handling
    if not isinstance(n, (int, float)) or isinstance(n, bool):
        return []

    if isinstance(n, float):
        return []

    if n < 0:
        return []

    if n == 0:
        return []

    if n == 1:
        return [1]

    primes, counts = getUniquePrimeFactorsWithCount(n)

    # Calculate prime^count for each
    products = []
    for p, c in zip(primes, counts):
        products.append(p ** c)

    return products

def count_divisors(n):
    """
    Count the number of positive divisors of a positive integer n.

    Args:
        n (int): A positive integer.

    Returns:
        int: The number of positive divisors of n.
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1

    return count

def even_odd_palindrome(n):
    def is_palindrome(num):
        s = str(num)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def converter(number, decimals=0, base=3.141592653589793):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part to given base
    if integer_part == 0:
        integer_digits = ['0']
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % int(base)
            integer_digits.append(get_digit(remainder))
            temp = temp // int(base)
        integer_digits.reverse()

    # Convert fractional part to given base
    fractional_digits = []
    if decimals > 0:
        temp_fractional = fractional_part
        for _ in range(decimals):
            temp_fractional *= base
            digit = int(temp_fractional)
            fractional_digits.append(get_digit(digit))
            temp_fractional -= digit

    # Combine results
    result = ''.join(integer_digits)
    if decimals > 0:
        result += '.' + ''.join(fractional_digits)

    # Add negative sign if needed
    if negative:
        result = '-' + result

    return result

def get_digit(value):
    if value < 10:
        return str(value)
    else:
        return chr(ord('A') + value - 10)

def almost_everywhere_zero(n, k):
    # Convert n to string for easier digit manipulation
    s = str(n)
    length = len(s)

    # Memoization for DP
    memo = {}

    def dp(pos, tight, started, non_zero_count):
        # Base case: if we've processed all digits
        if pos == length:
            return 1 if non_zero_count == k else 0

        # Check memoization
        if (pos, tight, started, non_zero_count) in memo:
            return memo[(pos, tight, started, non_zero_count)]

        # Determine the upper limit for current digit
        limit = int(s[pos]) if tight else 9
        result = 0

        # Try placing each possible digit at current position
        for digit in range(0, limit + 1):
            # If we haven't started placing non-zero digits yet
            if not started:
                if digit == 0:
                    # Continue with leading zeros
                    result += dp(pos + 1, tight and (digit == limit), False, 0)
                else:
                    # Start placing non-zero digits
                    result += dp(pos + 1, tight and (digit == limit), True, 1)
            else:
                # We've started placing digits
                if digit == 0:
                    # Place zero
                    result += dp(pos + 1, tight and (digit == limit), True, non_zero_count)
                else:
                    # Place non-zero digit
                    result += dp(pos + 1, tight and (digit == limit), True, non_zero_count + 1)

        memo[(pos, tight, started, non_zero_count)] = result
        return result

    # Handle special case where k is 0 - this would mean all digits are zero, which is only possible for 0
    if k == 0:
        return 1 if n == 0 else 0

    # Start DP from position 0
    return dp(0, True, False, 0)

def is_balanced(s, pairs):
    if not s:
        return True

    # Create mapping of opening to closing characters
    opening_to_closing = {}
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        opening_to_closing[opening] = closing

    # Stack to keep track of expected closing characters
    stack = []

    for char in s:
        # If character is an opening character
        if char in opening_to_closing:
            # Push the corresponding closing character onto the stack
            stack.append(opening_to_closing[char])
        # If character is a closing character
        elif char in opening_to_closing.values():
            # If stack is empty or the top doesn't match, it's unbalanced
            if not stack or stack.pop() != char:
                return False

    # If stack is empty, all characters were properly matched
    return len(stack) == 0

