            # Convert to 0-25 range, shift by 4, wrap around, convert back
            shifted = (ord(char) - ord('a') + 4) % 26 + ord('a')
            result.append(chr(shifted))
        elif char.isupper():
            # Convert to 0-25 range, shift by 4, wrap around, convert back
            shifted = (ord(char) - ord('A') + 4) % 26 + ord('A')
            result.append(chr(shifted))
