def converter(number, decimals=0, base=3.141592653589793):
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Separate integer and fractional parts
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_result = '0'
    else:
        digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            # Handle case where remainder is not an integer
            if remainder >= base:
                remainder = remainder - base
            digits.append(remainder)
            temp = (temp - remainder) // base
        # Convert to proper base representation
        integer_result = ''
        for digit in reversed(digits):
            if digit < 10:
                integer_result += str(int(digit))
            else:
                integer_result += chr(ord('A') + int(digit) - 10)

    # Convert fractional part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            if digit < 10:
                fractional_result += str(digit)
            else:
                fractional_result += chr(ord('A') + digit - 10)
            fractional_part -= digit

    # Combine results
    result = integer_result + fractional_result

    # Handle negative sign
    if negative:
        result = '-' + result

    # Special case for numbers with absolute value < 1
    if integer_part == 0 and fractional_result != '':
        # Ensure we have exactly one leading zero before decimal point
        if not result.startswith('0.'):
            result = '0' + result

    return result

