def exchange_sort(sequence):
    if len(sequence) <= 1:
        return 0

    # Create target sorted sequence
    target = []
    count = [0, 0, 0]  # count[0] for 7, count[1] for 8, count[2] for 9

    # Count occurrences
    for num in sequence:
        if num == 7:
            count[0] += 1
        elif num == 8:
            count[1] += 1
        else:  # num == 9
            count[2] += 1

    # Build target sequence
    target = [7] * count[0] + [8] * count[1] + [9] * count[2]

    # Create position mapping for target
    pos_map = {}
    for i, num in enumerate(target):
        if num not in pos_map:
            pos_map[num] = []
        pos_map[num].append(i)

    # Create a mapping from each element to its target position
    element_to_target = {}
    for i, num in enumerate(target):
        if not pos_map[num]:  # This shouldn't happen if we have correct counts
            continue
        target_pos = pos_map[num].pop(0)
        element_to_target[i] = target_pos

    # Count cycles using visited array
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if visited[i]:
            continue

        if i not in element_to_target:
            continue

        # Start a new cycle
        current = i
        cycle_length = 0

        while not visited[current]:
            visited[current] = True
            # Move to where current element should go
            if current in element_to_target:
                current = element_to_target[current]
            else:
                break
            cycle_length += 1

        if cycle_length > 0:
            cycles += 1

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

