    # Check first character - must be alpha, underscore, or dollar sign
    first_char = s[0]
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Check remaining characters - must be alpha, digit, underscore, or dollar sign
    for char in s[1:]:
        if not (char.isalnum() or char == '_' or char == '$'):
            return False

    return True

import math

def count_divisors(n: int) -> int:
    if n <= 0:
        raise ValueError("Input must be a positive integer.")

    count = 0
    sqrt_n = int(math.isqrt(n))

    for i in range(1, sqrt_n + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2

    return count

def proper_fractions(d):
    if d == 1:
        return 0

    result = d

    # Check for factor 2
    if d % 2 == 0:
        result -= result // 2
        while d % 2 == 0:
            d //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= d:
        if d % i == 0:
            result -= result // i
            while d % i == 0:
                d //= i
        i += 2

    # If d is still greater than 1, then it's a prime factor
    if d > 1:
        result -= result // d

    return result

