def poohbear(code):
    # Initialize memory and pointer
    memory = {}
    pointer = 0
    copied = 0
    pc = 0
    output = []

    # Find all loop pairs
    loop_stack = []
    loop_pairs = {}

    for i, char in enumerate(code):
        if char == 'W':
            loop_stack.append(i)
        elif char == 'E':
            if loop_stack:
                start = loop_stack.pop()
                loop_pairs[start] = i
                loop_pairs[i] = start

    # Execute code
    while pc < len(code):
        char = code[pc]

        if char == '+':
