        elif char == '>':
            pointer += 1
        elif char == '<':
            pointer -= 1
        elif char == 'c':
            copied = memory.get(pointer, 0)
        elif char == 'p':
            memory[pointer] = copied
        elif char == 'W':
            if memory.get(pointer, 0) == 0:
                pc = loop_pairs[pc]
        elif char == 'E':
            if memory.get(pointer, 0) != 0:
                pc = loop_pairs[pc]
        elif char == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif char == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif char == 'T':
            memory[pointer] = memory.get(pointer, 0) * 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'Q':
            memory[pointer] = memory.get(pointer, 0) ** 2
            if memory[pointer] > 255:
                memory[pointer] = 0
        elif char == 'U':
            import math
            memory[pointer] = int(math.sqrt(memory.get(pointer, 0)))
            if memory[pointer] > 255:
