    # Generate all rotations of b and check if any is a substring of a
    # A rotation of b can be obtained by taking b[i:] + b[:i] for i in range(len(b))
    for i in range(len(b)):
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True

    return False

def solution(input_string, markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the position of the first comment marker
        first_marker_pos = len(line)  # Default to end of line

        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < first_marker_pos:
                first_marker_pos = pos

        # If we found a marker, truncate the line at that position
        if first_marker_pos < len(line):
            processed_line = line[:first_marker_pos]
        else:
            processed_line = line

        # Strip trailing whitespace
        processed_line = processed_line.rstrip()
        result_lines.append(processed_line)

    return '\n'.join(result_lines)

