def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, value) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract the sorted values
    return [num for _, _, num in indexed_nums]

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 365 * 24 * 60 * 60),
        ('day', 24 * 60 * 60),
        ('hour', 60 * 60),
        ('minute', 60),
        ('second', 1)
    ]

    # Calculate each unit
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            plural = 's' if count > 1 else ''
            components.append(f"{count} {unit_name}{plural}")

    # Format the result
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

def smallest_change(arr):
    if len(arr) <= 1:
        return 0

    changes = 0
    n = len(arr)

    # Compare elements from both ends moving towards the center
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1

    return changes

import math

def converter(number, decimals=0, base=math.pi):
    if number == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Handle sign
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part to given base
    if integer_part == 0:
        integer_result = "0"
    else:
        digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        result = []
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            result.append(digits[int(remainder)])
            temp = (temp - remainder) // base
        integer_result = "".join(reversed(result))

    # Convert fractional part to given base
    if decimals == 0:
        fractional_result = ""
    else:
        digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        result = []
        temp = fractional_part
        for _ in range(decimals):
            temp *= base
            digit = int(temp)
            result.append(digits[digit])
            temp -= digit
        fractional_result = "".join(result)

    # Combine results
    if decimals == 0:
        result = integer_result
    else:
        if integer_result == "0":
            result = "0." + fractional_result
        else:
            result = integer_result + "." + fractional_result

    # Add negative sign if needed
    if negative:
        result = "-" + result

    return result

