def compare(selector1, selector2):
    def calculate_specificity(selector):
        # Count id, class, and tagname selectors
        id_count = 0
        class_count = 0
        tagname_count = 0

        # Remove spaces and split by combinators
        parts = selector.replace('>', ' ').replace('+', ' ').replace('~', ' ').split()

        for part in parts:
            # Remove any pseudo-selectors
            if ':' in part:
                part = part.split(':')[0]

            # Skip universal selector
            if part == '*':
                continue

            # Check for id selector
            if part.startswith('#'):
                id_count += 1
            # Check for class selector
            elif part.startswith('.'):
                class_count += 1
            # Everything else is a tagname
            else:
                tagname_count += 1

        return (id_count, class_count, tagname_count)

    spec1 = calculate_specificity(selector1)
    spec2 = calculate_specificity(selector2)

    # Compare specificity
    if spec1 > spec2:
        return selector1
    else:
        return selector2

