import re

def differentiate(polynomial, x):
    # Remove spaces
    polynomial = polynomial.replace(" ", "")

    # Split by + and - signs, keeping the signs
    terms = re.split(r'(?=[+-])', polynomial)
    # Remove empty strings
    terms = [term for term in terms if term]

    derivative_terms = []

    for term in terms:
        # Handle the sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Parse the term
        if 'x^' in term:
            # Format: coefficient*x^exponent
            coeff_part, exp_part = term.split('x^')
            if coeff_part == '':
                coefficient = 1
            else:
                coefficient = int(coeff_part)
            exponent = int(exp_part)
        elif 'x' in term:
            # Format: coefficient*x or x
            if term == 'x':
                coefficient = 1
                exponent = 1
            else:
                coeff_part = term[:-1]  # Remove 'x'
                if coeff_part == '-':
                    coefficient = -1
                else:
                    coefficient = int(coeff_part)
                exponent = 1
        else:
            # Constant term
            coefficient = int(term)
            exponent = 0

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent == 0:
            # Derivative of a constant is 0
            continue
        else:
            new_coefficient = coefficient * exponent
            new_exponent = exponent - 1

            # Build the derivative term
            if new_exponent == 0:
                derivative_terms.append(str(new_coefficient))
            elif new_exponent == 1:
                if new_coefficient == 1:
                    derivative_terms.append('x')
                elif new_coefficient == -1:
                    derivative_terms.append('-x')
                else:
                    derivative_terms.append(f"{new_coefficient}x")
            else:
                if new_coefficient == 1:
                    derivative_terms.append(f"x^{new_exponent}")
                elif new_coefficient == -1:
                    derivative_terms.append(f"-x^{new_exponent}")
                else:
                    derivative_terms.append(f"{new_coefficient}x^{new_exponent}")

    # If no derivative terms, the result is 0
    if not derivative_terms:
        return 0

    # Reconstruct the derivative polynomial
    derivative_poly = derivative_terms[0]
    for i in range(1, len(derivative_terms)):
        if derivative_terms[i].startswith('-'):
            derivative_poly += f" - {derivative_terms[i][1:]}"
        else:
            derivative_poly += f" + {derivative_terms[i]}"

    # Evaluate the derivative at x
    # Replace x with the value and evaluate
    result = 0
    for term in derivative_terms:
        if 'x' in term:
            if term == 'x':
                result += x
            elif term == '-x':
                result -= x
            else:
                coeff_part = term.split('x')[0]
                if coeff_part == '':
                    coeff = 1
                elif coeff_part == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_part)
                exp = term.split('x^')[1] if 'x^' in term else 1
                if exp == 1:
                    result += coeff * x
                else:
                    result += coeff * (x ** int(exp))
        else:
            result += int(term)

    return result

def pig_latin(word):
    if not word or not word.isalpha():
        return None

    word = word.lower()
    vowels = "aeiou"

    if word[0] in vowels:
        return word + "way"

    # Find the index where the first vowel occurs
    first_vowel_index = 0
    for i, char in enumerate(word):
        if char in vowels:
            first_vowel_index = i
            break
    else:
        # No vowels found
        return word + "ay"

    # Move consonants from the beginning to the end until the first vowel
    result = word[first_vowel_index:] + word[:first_vowel_index] + "ay"
    return result

