def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    n = d

    # Check for factor of 2 separately for efficiency
    if n % 2 == 0:
        while n % 2 == 0:
            n //= 2
        result -= result // 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            while n % i == 0:
                n //= i
            result -= result // i
        i += 2

    # If remaining n is a prime greater than 2
    if n > 1:
        result -= result // n

    return result

def is_balanced(s, pairs):
    # Handle empty input - an empty string is balanced
    if not s:
        return True

    # Build mappings from opening to closing and closing to opening characters
    opening_to_closing = {}
    closing_to_opening = {}

    # Parse pairs string: even positions are opening, odd positions are closing
    for i in range(0, len(pairs), 2):
        if i + 1 < len(pairs):
            opening_to_closing[pairs[i]] = pairs[i + 1]
            closing_to_opening[pairs[i + 1]] = pairs[i]

    # Stack to track opening characters
    stack = []

    # Iterate through each character in the string
    for char in s:
        if char in opening_to_closing:
            # It's an opening character, push to stack
            stack.append(char)
        elif char in closing_to_opening:
            # It's a closing character
            if not stack:
                return False  # No matching opening character

            # Check if this closing character matches the most recent opening
            expected_closing = opening_to_closing[stack[-1]]
            if expected_closing != char:
                return False  # Mismatch

            stack.pop()
        # Ignore any other characters that are not part of the pairs

    # Stack should be empty if all opening characters are properly closed
    return len(stack) == 0

