def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    def lucas_lehmer_test(p):
        if p == 2:
            return True
        s = 4
        m = (1 << p) - 1  # This is 2^p - 1
        for _ in range(p - 2):
            s = (s * s - 2) % m
        return s == 0

    # Check if n is prime
    if not is_prime(n):
        return False

    # If n is prime, check if 2^n - 1 is prime using Lucas-Lehmer test
    return lucas_lehmer_test(n)

def exchange_sort(sequence):
    # Create target sorted sequence
    target = sorted(sequence)

    # Create a mapping from value to its target positions
    from collections import defaultdict
    target_positions = defaultdict(list)
    for i, val in enumerate(target):
        target_positions[val].append(i)

    # Create a mapping from current positions to target positions
    current_to_target = {}
    for i, val in enumerate(sequence):
        if target_positions[val]:
            current_to_target[i] = target_positions[val].pop(0)

    # Find cycles in the permutation
    visited = [False] * len(sequence)
    cycles = 0

    for i in range(len(sequence)):
        if not visited[i] and i in current_to_target:
            # Start a new cycle
            cycle_length = 0
            current = i

            while not visited[current]:
                visited[current] = True
                if current in current_to_target:
                    current = current_to_target[current]
                else:
                    break
                cycle_length += 1

            if cycle_length > 0:
                cycles += 1

    # Minimum swaps = total elements - number of cycles
    return len(sequence) - cycles

