def differentiate(polynomial, x):
    # Parse the polynomial into terms
    # Handle the case where there's no plus/minus in the beginning
    if polynomial[0] != '-':
        polynomial = '+' + polynomial

    # Split by + and - signs (keeping the sign with the term)
    terms = []
    current_term = ""
    i = 0
    while i < len(polynomial):
        if polynomial[i] in ['+', '-'] and i > 0:
            if current_term:
                terms.append(current_term)
            current_term = polynomial[i]
        else:
            current_term += polynomial[i]
        i += 1
    if current_term:
        terms.append(current_term)

    # Process each term
    derivative_terms = []
    for term in terms:
        if term == '+':
            continue
        elif term == '-':
            continue

        # Remove the leading + or - for processing
        sign = 1 if term[0] == '+' else -1
        term = term[1:] if term[0] in ['+', '-'] else term

        # Handle different term formats
        if 'x^' in term:
            # Format: ax^n
            parts = term.split('x^')
            coeff_str = parts[0]
            if coeff_str == '':
                coeff = 1
            elif coeff_str == '-':
                coeff = -1
            else:
                coeff = int(coeff_str)
            coeff *= sign
            exponent = int(parts[1])

            # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
            if exponent > 0:
                new_coeff = coeff * exponent
                new_exponent = exponent - 1
                if new_exponent == 0:
                    derivative_terms.append(str(new_coeff))
                elif new_exponent == 1:
                    derivative_terms.append(f"{new_coeff}x")
                else:
                    derivative_terms.append(f"{new_coeff}x^{new_exponent}")

        elif 'x' in term:
            # Format: ax or -ax
            if term == 'x':
                coeff = 1
            elif term == '-x':
                coeff = -1
            else:
                coeff_str = term[:-1]
                if coeff_str == '+':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str)
            coeff *= sign

            # Apply power rule: d/dx(ax) = a
            derivative_terms.append(str(coeff))

        else:
            # Format: constant
            coeff = int(term) * sign
            # Derivative of constant is 0, so we don't add anything to derivative_terms

    # Evaluate the derivative at x
    result = 0
    for term in derivative_terms:
        if 'x' in term:
            # Extract coefficient and exponent
            if 'x^' in term:
                parts = term.split('x^')
                coeff = int(parts[0])
                exponent = int(parts[1])
                result += coeff * (x ** exponent)
            else:
                # x term
                coeff_str = term[:-1]
                if coeff_str == '':
                    coeff = 1
                elif coeff_str == '-':
                    coeff = -1
                else:
                    coeff = int(coeff_str)
                result += coeff * x
        else:
            # Constant term
            result += int(term)

    return result

def amazon_check_mate(king, amazon):
    # Convert chess notation to 0-indexed coordinates (row, col)
    # Files a-h map to columns 0-7, ranks 1-8 map to rows 7-0 (a1 is (7, 0), h8 is (0, 7))
    def parse_position(pos):
        col = ord(pos[0]) - ord('a')  # 0-7
        row = 8 - int(pos[1])  # 7-0
        return (row, col)

    w_king = parse_position(king)
    w_amazon = parse_position(amazon)

    # Helper function to check if a position is valid for Black King
    def is_valid_black_king(br, bc):
        # Can't be on the same square as white pieces
        if (br, bc) == w_king or (br, bc) == w_amazon:
            return False
        # Can't be adjacent to white king (including diagonally)
        if max(abs(br - w_king[0]), abs(bc - w_king[1])) <= 1:
            return False
        return True

    # Helper function to check if Amazon attacks a square
    def is_attacked_by_amazon(br, bc):
        # Knight-like moves
        knight_moves = [(2, 1), (2, -1), (-2, 1), (-2, -1), 
                       (1, 2), (1, -2), (-1, 2), (-1, -2)]
        for dr, dc in knight_moves:
            nr, nc = w_amazon[0] + dr, w_amazon[1] + dc
            if 0 <= nr < 8 and 0 <= nc < 8 and (nr, nc) == (br, bc):
                return True

        # Queen-like moves (with blocking by White King)
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0),  # horizontal and vertical
                      (1, 1), (1, -1), (-1, 1), (-1, -1)]  # diagonal
        for dr, dc in directions:
            for step in range(1, 8):
                nr, nc = w_amazon[0] + dr * step, w_amazon[1] + dc * step
                if not (0 <= nr < 8 and 0 <= nc < 8):
                    break
                if (nr, nc) == (br, bc):
                    return True
                if (nr, nc) == w_king:
                    break  # White King blocks the line of attack

        return False

    # Helper function to check if Black King has valid moves from current position
    def has_valid_moves(br, bc):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = br + dr, bc + dc
                if 0 <= nr < 8 and 0 <= nc < 8:
                    if is_valid_black_king(nr, nc) and not is_attacked_by_amazon(nr, nc):
                        return True
        return False

    # Count positions for each classification
    checkmates = 0
    checks = 0
    stalemates = 0
    safe = 0

    for row in range(8):
        for col in range(8):
            if not is_valid_black_king(row, col):
                continue

            attacked = is_attacked_by_amazon(row, col)
            has_moves = has_valid_moves(row, col)

            if attacked and not has_moves:
                checkmates += 1
            elif attacked and has_moves:
                checks += 1
            elif not attacked and not has_moves:
                stalemates += 1
            else:  # not attacked and has moves
                safe += 1

    return [checkmates, checks, stalemates, safe]

from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    if not numbers:
        return (0, 1)

    total_sum = sum(numbers)

    product = 1
    for num in numbers:
        product *= num

    return (total_sum, product)

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
integers that are prime numbers and less than n.
for example:
count_up_to(5) => [2,3]
count_up_to(11) => [2,3,5,7]
count_up_to(0) => []
count_up_to(20) => [2,3,5,7,11,13,17,19]
count_up_to(1) => []
count_up_to(18) => [2,3,5,7,11,13,17]
"""
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    result = []
    for i in range(2, n):
        if is_prime(i):
            result.append(i)

    return result

def palindrome(num):
    # Check if input is valid
    if not isinstance(num, int) or num < 0:
        return "Not valid"

    # Single digit numbers are palindromes
    if num < 10:
        return True

    # Convert to string and check if it reads the same forwards and backwards
    str_num = str(num)
    return str_num == str_num[::-1]

def check_if_last_char_is_a_letter(txt):
    # Check if string is empty
    if not txt:
        return False

    # Check if last character is alphabetical
    if not txt[-1].isalpha():
        return False

    # Check if it's isolated (preceded by space or is the only character)
    if len(txt) == 1:
        return True

    # If there's a character before the last, it must be a space
    return txt[-2] == ' '

def next_smallest(lst):
    if not lst:
        return None

    # Remove duplicates and sort
    unique_sorted = sorted(set(lst))

    # Check if we have at least 2 distinct elements
    if len(unique_sorted) < 2:
        return None

    # Return the second smallest element
    return unique_sorted[1]

def count_up_to(n):
    if n <= 2:
        return []

    # Use Sieve of Eratosthenes to find all primes less than n
    sieve = [True] * n
    sieve[0] = sieve[1] = False

    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n, i):
                sieve[j] = False

    # Collect primes
    primes = []
    for i in range(2, n):
        if sieve[i]:
            primes.append(i)

    return primes

