def candies(n, a):
    if n == 0:
        return 0

    candies_distribution = [1] * n
    total_candies = 0

    # Left to right pass
    for i in range(1, n):
        if a[i] > a[i - 1]:
            candies_distribution[i] = candies_distribution[i - 1] + 1

    # Right to left pass
    for i in range(n - 2, -1, -1):
        if a[i] > a[i + 1]:
            candies_distribution[i] = max(candies_distribution[i], candies_distribution[i + 1] + 1)

    total_candies = sum(candies_distribution)
    return total_candies

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)

