import math

def converter(number, decimals=0, base=math.pi):
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36")

    if decimals < 0:
        raise ValueError("Decimals must be non-negative")

    # Handle special case of base π
    if base == math.pi:
        base = math.pi

    # Handle zero case
    if number == 0:
        if decimals == 0:
            return "0"
        else:
            return "0." + "0" * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Convert integer part
    integer_part = int(number)
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            remainder = temp % base
            integer_digits.append(remainder)
            temp = temp // base
        integer_digits.reverse()

    # Convert fractional part
    fractional_part = number - integer_part
    fractional_digits = []

    if fractional_part > 0 and decimals > 0:
        temp = fractional_part
        for _ in range(decimals):
            temp = temp * base
            digit = int(temp)
            fractional_digits.append(digit)
            temp = temp - digit

    # Convert digits to characters
    digits_chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

    # Build integer part string
    if integer_digits:
        integer_str = ''.join(digits_chars[d] for d in integer_digits)
    else:
        integer_str = '0'

    # Build fractional part string
    if fractional_digits:
        fractional_str = ''.join(digits_chars[d] for d in fractional_digits)
        result = integer_str + '.' + fractional_str
    else:
        result = integer_str

    # Handle negative sign
    if negative:
        result = '-' + result

    # Handle leading zero for numbers with absolute value < 1
    if number < 1 and not negative:
        if '.' not in result:
            result = '0.' + result
        else:
            # Find where decimal point is and insert leading zero if needed
            parts = result.split('.')
            if parts[0] == '0':
                pass  # Already has leading zero
            else:
                result = '0.' + parts[0] + '.' + parts[1] if len(parts) > 1 else '0.' + parts[0]

    # Special case for numbers less than 1 but not negative
    if number < 1 and not negative:
        if '.' not in result:
            result = '0.' + result
        else:
            # Ensure only one leading zero
            if result.startswith('0.'):
                pass
            else:
                result = '0.' + result

    # Fix the case where we have a leading zero that shouldn't be there
    if number < 1 and not negative and '.' in result:
        # Make sure we have exactly one leading zero
        parts = result.split('.')
        if len(parts) > 1 and parts[0] == '0':
            pass  # Already correct
        else:
            result = '0.' + result

    # Clean up the case where we have an extra zero
    if number < 1 and not negative:
        if result == '0.0':
            pass
        elif result.startswith('0.'):
            pass
        else:
            result = '0.' + result

    # More careful handling
    if number < 1 and not negative:
        if '.' not in result:
            result = '0.' + result
        else:
            # If the integer part is 0, we already have the correct format
            if result.startswith('0.'):
                pass
            else:
                # We need to make sure we have leading zero
                parts = result.split('.')
                if len(parts) == 1:
                    result = '0.' + result
                elif parts[0] != '0':
                    result = '0.' + result

    # Simplified approach
    if number < 1 and not negative:
        if '.' in result:
            parts = result.split('.')
            if parts[0] != '0':
                result = '0.' + result
        else:
            result = '0.' + result

    # Handle the case where we have an integer part that's 0
    if result == '0.0':
        result = '0'

    return result

def proper_fractions(d):
    if d == 1:
        return 0

    result = d

    # Check for factor 2
    if d % 2 == 0:
        result -= result // 2
        while d % 2 == 0:
            d //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= d:
        if d % i == 0:
            result -= result // i
            while d % i == 0:
                d //= i
        i += 2

    # If d is still greater than 1, then it's a prime factor
    if d > 1:
        result -= result // d

    return result

def valid_mersenne(n):
    # Edge cases
    if n <= 1:
        return False

    # Check if n is prime (necessary condition for Mersenne prime)
    if n == 2:
        return True  # M_2 = 3 is prime

    if n % 2 == 0:
        return False

    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2

    # n is prime, now check if 2^n - 1 is prime using Lucas-Lehmer test
    m = 2 ** n - 1

    s = 4
    for _ in range(n - 2):
        s = (s * s - 2) % m

    return s == 0

