import sys
from collections import defaultdict

def parse_url(url):
    # Remove "http://"
    url = url[7:]

    # Split by first slash to get hostname and path
    if '/' in url:
        hostname, path = url.split('/', 1)
        # Ensure path starts with /
        if not path.startswith('/'):
            path = '/' + path
    else:
        hostname = url
        path = ''

    return hostname, path

def normalize_path(path):
    # Normalize path to handle consecutive slashes and ensure proper format
    if path == '':
        return ''

    # Split by '/' and filter empty strings
    parts = [p for p in path.split('/') if p]

    # Reconstruct path
    if not parts:
        return '/'

    # If original path started with /, the result should start with /
    # If original path ended with /, the result should end with /
    starts_with_slash = path.startswith('/')
    ends_with_slash = path.endswith('/')

    if starts_with_slash:
        if ends_with_slash:
            return '/' + '/'.join(parts) + '/'
        else:
            return '/' + '/'.join(parts)
    else:
        if ends_with_slash:
            return '/'.join(parts) + '/'
        else:
            return '/'.join(parts)

def get_path_set(paths):
    # Convert list of paths to a set of normalized paths
    normalized_paths = set()
    for path in paths:
        normalized_paths.add(normalize_path(path))
    return normalized_paths

def hash_path_set(path_set):
    # Create a hashable representation of the set
    # Sort the paths to ensure consistent hashing
    sorted_paths = sorted(path_set)
    return tuple(sorted_paths)

