    data = sys.stdin.read()
    lines = data.strip().split('\n')

    n = int(lines[0])
    urls = lines[1:n+1]

    # Group URLs by hostname
    hostname_to_paths = defaultdict(list)

    for url in urls:
        hostname, path = parse_url(url)
        hostname_to_paths[hostname].append(path)

    # Create hash representations for each hostname
    hostname_to_hash = {}
    hash_to_hostnames = defaultdict(list)

    for hostname, paths in hostname_to_paths.items():
        path_set = get_path_set(paths)
        path_hash = hash_path_set(path_set)
        hostname_to_hash[hostname] = path_hash
        hash_to_hostnames[path_hash].append(hostname)

    # Find groups with more than one hostname
    groups = []
    for hash_val, hostnames in hash_to_hostnames.items():
        if len(hostnames) > 1:
            groups.append(sorted(hostnames))

    # Output results
    print(len(groups))
    for group in groups:
        # Format output with full URLs
        formatted_group = [f"http://{hostname}" for hostname in group]
        print(' '.join(formatted_group))

