def simplify(expression):
    if not expression:
        return ""

    # Split into terms, keeping signs
    terms = []
    i = 0
    while i < len(expression):
        # Start of a term
        start = i
        # Find end of term (next + or - that's not at start)
        j = i + 1
        while j < len(expression) and expression[j] not in '+-':
            j += 1
        terms.append(expression[i:j])
        i = j

    # Parse each term into (coefficient, sorted_variables)
    def parse_term(term):
        if not term:
            return 0, []

        # Handle sign and coefficient
        sign = 1
        coef_start = 0
        if term[0] == '+':
            coef_start = 1
        elif term[0] == '-':
            sign = -1
            coef_start = 1

        # Find where coefficient ends (first letter)
        coef_end = coef_start
        while coef_end < len(term) and term[coef_end].isdigit():
            coef_end += 1

        # Parse coefficient
        if coef_end == coef_start:
            coefficient = 1 * sign
        else:
            coefficient = int(term[coef_start:coef_end]) * sign

        # Extract variables
        variables = term[coef_end:]
        return coefficient, sorted(list(variables))

    # Combine like terms using a dictionary
    combined = {}
    for term in terms:
        coef, vars = parse_term(term)
        key = ''.join(vars)
        if key:
            combined[key] = combined.get(key, 0) + coef

    # Filter out zero coefficients
    result_list = []
    for key, coef in combined.items():
        if coef != 0:
            result_list.append((coef, key, len(key)))

    # Sort by number of variables, then lexicographically
    result_list.sort(key=lambda x: (x[2], x[1]))

    # Build output string
    output_parts = []
    for coef, vars, _ in result_list:
        if coef == 1:
            part = ''.join(vars)
        elif coef == -1:
            part = '-' + ''.join(vars)
        elif coef > 0:
            part = str(coef) + ''.join(vars)
        else:  # coef < 0
            part = str(coef) + ''.join(vars)
        output_parts.append(part)

    if not output_parts:
        return ""

    # Join parts, but handle signs properly
    result = output_parts[0]
    for part in output_parts[1:]:
        if part.startswith('-'):
            result += part
        else:
            result += '+' + part

    return result

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
integers that are prime numbers and less than n.
for example:
count_up_to(5) => [2,3]
count_up_to(11) => [2,3,5,7]
count_up_to(0) => []
count_up_to(20) => [2,3,5,7,11,13,17,19]
count_up_to(1) => []
count_up_to(18) => [2,3,5,7,11,13,17]
"""
    if n <= 2:
        return []

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    primes = []
    for i in range(2, n):
        if is_prime(i):
            primes.append(i)

    return primes

def parse_int(s):
    if not s:
        return 0

    # Define word mappings
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14, 'fifteen': 15,
        'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19, 'twenty': 20,
        'thirty': 30, 'forty': 40, 'fifty': 50, 'sixty': 60, 'seventy': 70,
        'eighty': 80, 'ninety': 90
    }

    # Split the string into words and remove 'and'
    words = s.replace('-', ' ').split()
    words = [word for word in words if word != 'and']

    if not words:
        return 0

    # Handle special case of just "zero"
    if len(words) == 1 and words[0] == 'zero':
        return 0

    # Process the words
    result = 0
    current = 0

    for word in words:
        if word in word_to_num:
            current += word_to_num[word]
        elif word == 'hundred':
            current *= 100
        elif word == 'thousand':
            result += current * 1000
            current = 0
        elif word == 'million':
            result += current * 1000000
            current = 0

    result += current
    return result

