        else:
            exp = 1

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exp > 0:
            new_coeff = coeff * exp
            new_exp = exp - 1
            result += new_coeff * (x ** new_exp)

    return result

