def cycpattern_check(a, b):
    # Handle edge cases
    if not b:
        return True
    if not a:
        return False

    # If length of b is greater than a, b or its rotations cannot be substring of a
    if len(b) > len(a):
        return False

    # Create doubled string of b
    # All rotations of b will be substrings of b+b
    doubled_b = b + b

    # Check if any rotation of b (which are substrings of doubled_b) 
    # is present in a
    for i in range(len(b)):
        rotation = doubled_b[i:i+len(b)]
        if rotation in a:
            return True

    return False

