def is_balanced(string, pairs):
    # Create a mapping of opening to closing characters
    opening_to_closing = {}
    for i in range(0, len(pairs), 2):
        opening = pairs[i]
        closing = pairs[i + 1]
        opening_to_closing[opening] = closing

    # Stack to keep track of opening characters
    stack = []

    for char in string:
        # If character is an opening character
        if char in opening_to_closing:
            stack.append(char)
        # If character is a closing character
        elif char in opening_to_closing.values():
            # If stack is empty or closing character doesn't match the most recent opening character
            if not stack or opening_to_closing[stack.pop()] != char:
                return False

    # String is balanced if stack is empty
    return len(stack) == 0

def almost_everywhere_zero(n, k):
    s = str(n)
    m = len(s)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, count, tight):
        if pos == m:
            return 1 if count == k else 0

        limit = int(s[pos]) if tight else 9
        total = 0

        for digit in range(limit + 1):
            new_tight = tight and (digit == limit)
            new_count = count + (1 if digit > 0 else 0)

            if new_count <= k:
                total += dp(pos + 1, new_count, new_tight)

        return total

    result = dp(0, 0, True)
    # Subtract 1 if k == 0 because 0 is counted but we need numbers from 1 to n
    if k == 0:
        result -= 1
    return result

