    def is_adjacent(pos1, pos2):
        return (0 <= abs(pos1[0] - pos2[0]) <= 1 and 
                0 <= abs(pos1[1] - pos2[1]) <= 1 and
                pos1 != pos2)

    def get_amazon_attacks(af, ar):
        attacks = set()

        # Queen moves - horizontal
        for f in range(8):
            if f != af:
                attacks.add((f, ar))

        # Queen moves - vertical
        for r in range(8):
            if r != ar:
                attacks.add((af, r))

        # Queen moves - diagonals
        directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        for df, dr in directions:
            for d in range(1, 8):
                nf, nr = af + df * d, ar + dr * d
                if 0 <= nf < 8 and 0 <= nr < 8:
                    attacks.add((nf, nr))

        # Knight moves
        knight_offsets = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
                         (1, -2), (1, 2), (2, -1), (2, 1)]
        for df, dr in knight_offsets:
            nf, nr = af + df, ar + dr
            if 0 <= nf < 8 and 0 <= nr < 8:
                attacks.add((nf, nr))

        return attacks

    def is_valid_bk_pos(bf, br, wkf, wkr, af, ar):
        if (bf, br) == (wkf, wkr):
            return False
        if (bf, br) == (af, ar):
            return False
        if is_adjacent((bf, br), (wkf, wkr)):
            return False
        return True

