                continue

            is_attacked = (bf, br) in amazon_attacks

            safe_moves = []
            for df in range(-1, 2):
                for dr in range(-1, 2):
                    if df == 0 and dr == 0:
                        continue
                    nf, nr = bf + df, br + dr
                    if 0 <= nf < 8 and 0 <= nr < 8:
                        if (nf, nr) not in [(wkf, wkr), (af, ar)]:
                            if not is_adjacent((nf, nr), (wkf, wkr)):
                                if (nf, nr) not in amazon_attacks:
