    def is_adjacent(x1, y1, x2, y2):
        return abs(x1 - x2) <= 1 and abs(y1 - y2) <= 1

    def get_amazon_attacks(x, y):
        attacks = set()

        # Queen moves (rook + bishop)
        # Horizontal and vertical
        for i in range(8):
            if i != x:
                attacks.add((i, y))
        for j in range(8):
            if j != y:
                attacks.add((x, j))

        # Diagonal moves
        for dx in [-1, 1]:
            for dy in [-1, 1]:
                nx, ny = x + dx, y + dy
                while is_valid(nx, ny):
                    attacks.add((nx, ny))
                    nx += dx
                    ny += dy

        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), 
                       (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                attacks.add((nx, ny))

        return attacks

    def get_king_moves(x, y):
        moves = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny):
                    moves.append((nx, ny))
        return moves

