                valid_positions.append((x, y))

    checkmate_count = 0
    check_count = 0
    stalemate_count = 0
    safe_count = 0

    for bx, by in valid_positions:
        # Check if black king is under attack
        is_under_attack = (bx, by) in amazon_attacks

        if is_under_attack:
            # Check if king can escape to a safe square
            can_escape = False
            king_moves = get_king_moves(bx, by)
            for nx, ny in king_moves:
                # Check if the new position is:
                # 1. Not adjacent to white king
                # 2. Not under attack by amazon
                if not is_adjacent(nx, ny, king_x, king_y) and (nx, ny) not in amazon_attacks:
                    can_escape = True
                    break

            if can_escape:
                check_count += 1
            else:
