                if not is_adjacent(nx, ny, king_x, king_y) and (nx, ny) not in amazon_attacks:
                    can_move = True
                    break

            if can_move:
                safe_count += 1
            else:
                stalemate_count += 1

    return [checkmate_count, check_count, stalemate_count, safe_count]

def compare(selector1, selector2):
    def parse_selector(sel):
        ids = 0
        classes = 0
        tags = 0

        parts = sel.split()

        for part in parts:
            if part == '*':
                continue

            # Parse each part to count ids, classes, and tags
            i = 0
            tag_found = False

            while i < len(part):
                if part[i] == '#':
                    ids += 1
                    i += 1
                    # Skip id name characters
                    while i < len(part) and (part[i].isalnum() or part[i] in '-_'):
                        i += 1
                elif part[i] == '.':
                    classes += 1
                    i += 1
                    # Skip class name characters
                    while i < len(part) and (part[i].isalnum() or part[i] in '-_'):
                        i += 1
                else:
                    # Start of tagname
                    tag_found = True
                    i += 1
                    # Skip tagname characters
                    while i < len(part) and (part[i].isalnum() or part[i] in '-_'):
                        i += 1

            if tag_found:
                tags += 1

        return (ids, classes, tags)

    specificity1 = parse_selector(selector1)
    specificity2 = parse_selector(selector2)

    # Compare in order: ids, classes, tags
    if specificity1[0] > specificity2[0]:
        return selector1
    elif specificity1[0] < specificity2[0]:
        return selector2

    if specificity1[1] > specificity2[1]:
        return selector1
    elif specificity1[1] < specificity2[1]:
        return selector2

    if specificity1[2] > specificity2[2]:
        return selector1
    elif specificity1[2] < specificity2[2]:
        return selector2

    # If all equal, the later one wins
    return selector2

