def differentiate(poly: str, x: int) -> int:
    # Replace '-' with '+-' to handle negative terms when splitting
    poly = poly.replace('-', '+-')
    terms = poly.split('+')

    result = 0

    for term in terms:
        # Skip empty terms
        if not term:
            continue

        # Check if term contains 'x'
        if 'x' not in term:
            # Constant term, derivative is 0
            continue

        # Find position of 'x'
        x_pos = term.index('x')
        coef_str = term[:x_pos]
        exp_str = term[x_pos + 1:]

        # Parse coefficient
        if coef_str == '' or coef_str == '+':
            coef = 1
        elif coef_str == '-':
            coef = -1
        else:
            coef = int(coef_str)

        # Parse exponent
        if exp_str == '':
            exp = 1
        elif exp_str.startswith('^'):
            exp = int(exp_str[1:])
        else:
            exp = 1

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exp == 0:
            # Constant term, derivative is 0
            continue
        else:
            # Apply power rule
            result += coef * exp * (x ** (exp - 1))

    return result

def proper_fractions(d):
    if d == 1:
        return 0

    result = d
    n = d

    # Handle factor of 2
    if n % 2 == 0:
        result = result - result // 2
        while n % 2 == 0:
            n //= 2

    # Handle odd factors
    i = 3
    while i * i <= n:
        if n % i == 0:
            result = result - result // i
            while n % i == 0:
                n //= i
        i += 2

    # If n > 1, it's a remaining prime factor
    if n > 1:
        result = result - result // n

    return result

def compare(selector1, selector2):
    def parse_selector(sel):
        ids = 0
        classes = 0
        tags = 0

        parts = sel.split()

        for part in parts:
            if part == '*':
                continue

            # Parse each part to count ids, classes, and tags
            i = 0
            tag_found = False

            while i < len(part):
                if part[i] == '#':
                    ids += 1
                    i += 1
                    # Skip id name characters
                    while i < len(part) and (part[i].isalnum() or part[i] in '-_'):
                        i += 1
                elif part[i] == '.':
                    classes += 1
                    i += 1
                    # Skip class name characters
                    while i < len(part) and (part[i].isalnum() or part[i] in '-_'):
                        i += 1
                else:
                    # Start of tagname
                    tag_found = True
                    i += 1
                    # Skip tagname characters
                    while i < len(part) and (part[i].isalnum() or part[i] in '-_'):
                        i += 1

            if tag_found:
                tags += 1

        return (ids, classes, tags)

    specificity1 = parse_selector(selector1)
    specificity2 = parse_selector(selector2)

    # Compare in order: ids, classes, tags
    if specificity1[0] > specificity2[0]:
        return selector1
    elif specificity1[0] < specificity2[0]:
        return selector2

    if specificity1[1] > specificity2[1]:
        return selector1
    elif specificity1[1] < specificity2[1]:
        return selector2

    if specificity1[2] > specificity2[2]:
        return selector1
    elif specificity1[2] < specificity2[2]:
        return selector2

    # If all equal, the later one wins
    return selector2

