from collections import defaultdict, deque

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])

    edges = []
    for i in range(1, n):
        a, b, c = map(int, lines[i].split())
        edges.append((a, b, c))

    x = []
    for i in range(n, 2*n-1):
        x.append(int(lines[i]))

    # Binary search on the answer
    def can_achieve_threshold(w):
        # Build components using edges with weight < w
        parent = list(range(n + 1))
        rank = [0] * (n + 1)

        def find(u):
            if parent[u] != u:
                parent[u] = find(parent[u])
            return parent[u]

        def union(u, v):
            pu, pv = find(u), find(v)
            if pu != pv:
                if rank[pu] < rank[pv]:
                    pu, pv = pv, pu
                parent[pv] = pu
                if rank[pu] == rank[pv]:
                    rank[pu] += 1

        # Build DSU with edges having weight < w
        for a, b, c in edges:
            if c < w:
                union(a, b)

        # Group nodes by their root
        components = defaultdict(list)
        for i in range(1, n + 1):
            root = find(i)
            components[root].append(i)

        # Check Hall's condition
        total_capacity = sum(x)
        for root, nodes in components.items():
            capacity_in_component = sum(x[node-1] for node in nodes)
            size = len(nodes)
            if total_capacity - capacity_in_component < size:
                return False

        return True

    # Binary search on weight values
    left, right = 0, 10001
    result = 0

    while left < right:
        mid = (left + right) // 2
        if can_achieve_threshold(mid):
            result = mid
            left = mid + 1
        else:
            right = mid

    print(result)

