def solution(text, markers):
    lines = text.split('\n')
    result = []

    for line in lines:
        # Find the earliest position of any marker in the line
        min_pos = len(line)  # Start with the end of the line as default

        for marker in markers:
            pos = line.find(marker)
            if pos != -1 and pos < min_pos:
                min_pos = pos

        # If a marker was found, truncate the line at that position
        if min_pos < len(line):
            line = line[:min_pos]

        # Strip trailing whitespace
        line = line.rstrip()

        result.append(line)

    return '\n'.join(result)

