import sys
from math import inf

def solve():
    data = sys.stdin.read()
    lines = data.splitlines()

    line1 = lines[0].split()
    n, l, r, Ql, Qr = map(int, line1)

    weights = list(map(int, lines[1].split()))

    # dp[i][j][last] = minimum energy to take i items from left and j items from right
    # last: 0 = left, 1 = right, -1 = none
    dp = [[[-1 for _ in range(2)] for _ in range(n + 1)] for _ in range(n + 1)]

    # Base case: no items taken yet
    dp[0][0][-1] = 0

    for i in range(n + 1):
        for j in range(n + 1):
            if i + j > n:
                continue
            if dp[i][j][0] != -1:
                # Take from left
                if i < n:
                    new_energy = dp[i][j][0] + weights[i] * l
                    if i > 0 and i + j > 0:  # Not the first move, check if previous was left
                        new_energy += Ql
                    if dp[i + 1][j][0] == -1 or dp[i + 1][j][0] > new_energy:
                        dp[i + 1][j][0] = new_energy
            if dp[i][j][1] != -1:
                # Take from right
                if j < n:
                    new_energy = dp[i][j][1] + weights[n - 1 - j] * r
                    if i + j > 0 and i + j > 0:  # Not the first move, check if previous was right
                        new_energy += Qr
                    if dp[i][j + 1][1] == -1 or dp[i][j + 1][1] > new_energy:
                        dp[i][j + 1][1] = new_energy
            if dp[i][j][-1] != -1:
                # Take from left or right for first move
                if i < n:
                    new_energy = dp[i][j][-1] + weights[i] * l
                    if dp[i + 1][j][0] == -1 or dp[i + 1][j][0] > new_energy:
                        dp[i + 1][j][0] = new_energy
                if j < n:
                    new_energy = dp[i][j][-1] + weights[n - 1 - j] * r
                    if dp[i][j + 1][1] == -1 or dp[i][j + 1][1] > new_energy:
                        dp[i][j + 1][1] = new_energy

    # Find minimum among all valid states
    result = inf
    for i in range(n + 1):
        for j in range(n + 1):
            if i + j == n:
                if dp[i][j][0] != -1 and dp[i][j][0] < result:
                    result = dp[i][j][0]
                if dp[i][j][1] != -1 and dp[i][j][1] < result:
                    result = dp[i][j][1]

    print(result)

