def order_by_points(nums):
    """
    Sorts the given list of integers in ascending order according to the sum of their digits.
    If there are several items with similar sum of their digits, order them based on their 
    index in original list (stable sort).

    Args:
        nums: List of integers to be sorted

    Returns:
        List of integers sorted by digit sum (stable sort)
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)

def proper_fractions(d):
    if d == 1:
        return 0

    result = d

    # Check for factor 2
    if d % 2 == 0:
        result -= result // 2
        while d % 2 == 0:
            d //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= d:
        if d % i == 0:
            result -= result // i
            while d % i == 0:
                d //= i
        i += 2

    # If d is still greater than 1, then it's a prime factor
    if d > 1:
        result -= result // d

    return result

