def cycpattern_check(a, b):
    # Handle edge cases
    if not b:
        return True
    if not a:
        return False
    if len(b) > len(a):
        return False

    # Create a string that contains all rotations of b
    # If b is a rotation of some substring of a, then b will appear in a+a
    # But we need to check all substrings of a with length len(b)
    doubled_b = b + b

    # Check each substring of a with length equal to b
    for i in range(len(a) - len(b) + 1):
        substring = a[i:i + len(b)]
        # Check if substring is a rotation of b
        # A string is a rotation of another if it appears in the concatenation of the other with itself
        if substring in doubled_b:
            return True

    return False

def poohbear(code):
    # Filter out non-command characters
    commands = [c for c in code if c in "+-><cWEPNTQULIABDY"]

    if not commands:
        return ""

    # Match W and E pairs using a stack
    w_stack = []
    w_to_e = {}
    e_to_w = {}

    for i, cmd in enumerate(commands):
        if cmd == 'W':
            w_stack.append(i)
        elif cmd == 'E':
            if w_stack:
                w_pos = w_stack.pop()
                w_to_e[w_pos] = i
                e_to_w[i] = w_pos

    # Initialize memory (dictionary for infinite cells in both directions)
    memory = {}
    pointer = 0
    copied_value = 0

    # Collect output
    output = []

    # Execute commands
    ip = 0  # instruction pointer

    while ip < len(commands):
        cmd = commands[ip]

        if cmd == '+':
            memory[pointer] = (memory.get(pointer, 0) + 1) % 256
            ip += 1
        elif cmd == '-':
            memory[pointer] = (memory.get(pointer, 0) - 1) % 256
            ip += 1
        elif cmd == '>':
            pointer += 1
            ip += 1
        elif cmd == '<':
            pointer -= 1
            ip += 1
        elif cmd == 'c':
            copied_value = memory.get(pointer, 0)
            ip += 1
        elif cmd == 'p':
            memory[pointer] = copied_value % 256
            ip += 1
        elif cmd == 'W':
            if memory.get(pointer, 0) == 0:
                ip = w_to_e.get(ip, ip) + 1
            else:
                ip += 1
        elif cmd == 'E':
            if memory.get(pointer, 0) != 0:
                ip = e_to_w.get(ip, ip)
            else:
                ip += 1
        elif cmd == 'P':
            output.append(chr(memory.get(pointer, 0)))
            ip += 1
        elif cmd == 'N':
            output.append(str(memory.get(pointer, 0)))
            ip += 1
        elif cmd == 'T':
            val = memory.get(pointer, 0)
            memory[pointer] = (val * 2) % 256
            ip += 1
        elif cmd == 'Q':
            val = memory.get(pointer, 0)
            memory[pointer] = (val * val) % 256
            ip += 1
        elif cmd == 'U':
            val = memory.get(pointer, 0)
            memory[pointer] = int(val ** 0.5) % 256
            ip += 1
        elif cmd == 'L':
            memory[pointer] = (memory.get(pointer, 0) + 2) % 256
            ip += 1
        elif cmd == 'I':
            memory[pointer] = (memory.get(pointer, 0) - 2) % 256
            ip += 1
        elif cmd == 'V':
            val = memory.get(pointer, 0)
            memory[pointer] = int(val / 2) % 256
            ip += 1
        elif cmd == 'A':
            val = memory.get(pointer, 0)
            memory[pointer] = (val + copied_value) % 256
            ip += 1
        elif cmd == 'B':
            val = memory.get(pointer, 0)
            memory[pointer] = (val - copied_value) % 256
            ip += 1
        elif cmd == 'Y':
            val = memory.get(pointer, 0)
            memory[pointer] = (val * copied_value) % 256
            ip += 1
        elif cmd == 'D':
            val = memory.get(pointer, 0)
            if copied_value != 0:
                memory[pointer] = int(val / copied_value) % 256
            else:
                memory[pointer] = 0
            ip += 1
        else:
            ip += 1

    return ''.join(output)

