def compare(selector1, selector2):
    def get_specificity(selector):
        id_count = 0
        class_count = 0
        element_count = 0

        # Split by spaces to handle compound selectors
        parts = selector.split()

        for part in parts:
            # Count ID selectors (#id)
            if part.startswith('#'):
                id_count += 1
            # Count class selectors (.class)
            elif part.startswith('.'):
                class_count += 1
            # Count element selectors (tag names)
            else:
                # Handle cases like div#id.class or div.class#id
                # Remove any # or . from the part to count elements
                clean_part = ''.join(c for c in part if c not in '#.')
                if clean_part:  # Only count if there's actually an element
                    element_count += 1

        return (id_count, class_count, element_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    # Compare specificity tuples
    if spec1 > spec2:
        return selector1
    else:
        return selector2

