def sum_of_squares(n):
    # Check if n is a perfect square (answer = 1)
    root = int(n ** 0.5)
    if root * root == n:
        return 1

    # Remove all factors of 4
    m = n
    while m % 4 == 0:
        m //= 4

    # Check if n is of the form 4^a(8b+7) (answer = 4)
    if m % 8 == 7:
        return 4

    # Check if n can be written as sum of 2 squares (answer = 2)
    for i in range(1, root + 1):
        j_sq = n - i * i
        j = int(j_sq ** 0.5)
        if j * j == j_sq:
            return 2

    # Otherwise answer = 3
    return 3

