def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, number) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    sorted_nums = sorted(indexed_nums, key=lambda x: (x[0], x[1]))

    # Extract just the numbers from the sorted result
    return [num for _, _, num in sorted_nums]

def get_closest_vowel(word):
    vowels = set('aeiouAEIOU')

    # Need at least 3 characters to have a vowel between two consonants
    if len(word) < 3:
        return ""

    # Iterate from right to left, checking positions from len-2 down to 1
    # (positions 0 and len-1 are boundaries where vowels don't count)
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            # Check if both adjacent characters are consonants
            left_is_consonant = word[i-1] not in vowels
            right_is_consonant = word[i+1] not in vowels

            if left_is_consonant and right_is_consonant:
                return word[i]

    return ""

def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    # For 2^n - 1 to be prime, n must be prime (but not all prime n give prime 2^n - 1)
    if not is_prime(n):
        return False

    # Special case: 2^1 - 1 = 1, which is not prime
    if n == 1:
        return False

    # Calculate 2^n - 1 and check if it's prime
    mersenne_number = (1 << n) - 1  # This is 2^n - 1

    return is_prime(mersenne_number)

def get_closest_vowel(word):
