    # Scan from right to left, starting from second-to-last character down to second character
    # This excludes first and last positions (index 0 and len-1)
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            # Check if both neighbors are consonants (not vowels)
            if word[i-1] not in vowels and word[i+1] not in vowels:
                return word[i]

    return ""

