def differentiate(polynomial, x):
    # Parse the polynomial into terms
    # Handle the case where the polynomial starts with a negative sign
    if polynomial[0] == '-':
        terms = ['-']
        polynomial = polynomial[1:]
    else:
        terms = []

    # Split by + and - signs
    current_term = ""
    for i, char in enumerate(polynomial):
        if char in ['+', '-'] and i > 0:
            terms.append(current_term)
            current_term = char
        else:
            current_term += char
    terms.append(current_term)

    # Process each term
    derivative_terms = []

    for term in terms:
        if not term:
            continue

        # Handle the case where term starts with a minus sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        else:
            sign = 1

        # Extract coefficient and exponent
        if 'x' in term:
            if '^' in term:
                # Format: ax^n
                parts = term.split('x^')
                if parts[0] == '':
                    coeff = sign * 1
                else:
                    coeff = sign * int(parts[0])
                exp = int(parts[1])
            else:
                # Format: ax or x
                if term == 'x':
                    coeff = sign * 1
                else:
                    coeff = sign * int(term[:-1])
                exp = 1
        else:
            # Constant term
            coeff = sign * int(term)
            exp = 0

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exp == 0:
            # Derivative of constant is 0
            continue
        else:
            new_coeff = coeff * exp
            new_exp = exp - 1
            derivative_terms.append((new_coeff, new_exp))

    # Evaluate the derivative at x
    result = 0
    for coeff, exp in derivative_terms:
        if exp == 0:
            result += coeff
        else:
            result += coeff * (x ** exp)

    return result

def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 365 * 24 * 60 * 60),
        ('day', 24 * 60 * 60),
        ('hour', 60 * 60),
        ('minute', 60),
        ('second', 1)
    ]

    # Calculate each unit
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            if count > 1:
                components.append(f"{count} {unit_name}s")
            else:
                components.append(f"{count} {unit_name}")

    # Format the result
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

