def largest_divisor(n: int) -> int:
    if n <= 1:
        return 1

    # Find the smallest divisor greater than 1
    for d in range(2, int(n**0.5) + 1):
        if n % d == 0:
            return n // d

    # If no divisor found, n is prime, so return 1
    return 1

def encrypt(s):
    result = ""
    for char in s:
        if char.isalpha():
            if char.islower():
                # For lowercase letters, shift by 4 positions with wraparound
                shifted = (ord(char) - ord('a') + 4) % 26
                result += chr(shifted + ord('a'))
            else:
                # For uppercase letters, shift by 4 positions with wraparound
                shifted = (ord(char) - ord('A') + 4) % 26
                result += chr(shifted + ord('A'))
        else:
            # Non-alphabetic characters remain unchanged
            result += char
    return result

