    parts = [part for part in parts if part]

    # Handle special case for "and"
    cleaned_parts = []
    for i, part in enumerate(parts):
        if part == 'and':
            # Skip 'and' if it's at the beginning or end, or if it's between two numbers
            if i > 0 and i < len(parts) - 1:
                # Check if both neighbors are numbers
                if parts[i-1] in word_to_num and parts[i+1] in word_to_num:
                    continue  # Skip the 'and'
        cleaned_parts.append(part)

    parts = cleaned_parts

    result = 0
