    for part in parts:
        if part in word_to_num:
            current += word_to_num[part]
        elif part == 'hundred':
            current *= 100
        elif part == 'thousand':
            result += current * 1000
            current = 0
        elif part == 'million':
            result += current * 1000000
            current = 0

