import math

def poohbear(code):
    # Filter out non-command characters
    commands = [c for c in code if c in "+-<>cpWEPNTQLIVABYD"]

    # Build W-E pair mappings
    we_pairs = {}
    stack = []
    for i, cmd in enumerate(commands):
        if cmd == 'W':
            stack.append(i)
        elif cmd == 'E':
            if stack:
                start = stack.pop()
                we_pairs[start] = i
                we_pairs[i] = start

    # Initialize interpreter state
    memory = {}
    pointer = 0
    copied = 0
    ip = 0
    output = []

    while ip < len(commands):
        cmd = commands[ip]

        if cmd == '+':
            memory[pointer] = memory.get(pointer, 0) + 1
            memory[pointer] = ((memory[pointer] % 256) + 256) % 256
        elif cmd == '-':
            memory[pointer] = memory.get(pointer, 0) - 1
            memory[pointer] = ((memory[pointer] % 256) + 256) % 256
        elif cmd == '>':
            pointer += 1
        elif cmd == '<':
            pointer -= 1
        elif cmd == 'c':
            copied = memory.get(pointer, 0)
        elif cmd == 'p':
            memory[pointer] = copied
        elif cmd == 'W':
            if memory.get(pointer, 0) == 0:
                ip = we_pairs[ip]
        elif cmd == 'E':
            if memory.get(pointer, 0) != 0:
                ip = we_pairs[ip]
        elif cmd == 'P':
            output.append(chr(memory.get(pointer, 0)))
        elif cmd == 'N':
            output.append(str(memory.get(pointer, 0)))
        elif cmd == 'T':
            memory[pointer] = memory.get(pointer, 0) * 2
            memory[pointer] = ((memory[pointer] % 256) + 256) % 256
        elif cmd == 'Q':
            memory[pointer] = memory.get(pointer, 0) ** 2
            memory[pointer] = ((memory[pointer] % 256) + 256) % 256
        elif cmd == 'U':
            val = memory.get(pointer, 0)
            if val == 0:
                memory[pointer] = 0
            else:
                memory[pointer] = int(math.sqrt(val))
        elif cmd == 'L':
            memory[pointer] = memory.get(pointer, 0) + 2
            memory[pointer] = ((memory[pointer] % 256) + 256) % 256
        elif cmd == 'I':
            memory[pointer] = memory.get(pointer, 0) - 2
            memory[pointer] = ((memory[pointer] % 256) + 256) % 256
        elif cmd == 'V':
            val = memory.get(pointer, 0)
            if copied == 0:
                memory[pointer] = 0
            else:
                memory[pointer] = val // copied
                memory[pointer] = ((memory[pointer] % 256) + 256) % 256
        elif cmd == 'A':
            memory[pointer] = memory.get(pointer, 0) + copied
            memory[pointer] = ((memory[pointer] % 256) + 256) % 256
        elif cmd == 'B':
            memory[pointer] = memory.get(pointer, 0) - copied
            memory[pointer] = ((memory[pointer] % 256) + 256) % 256
        elif cmd == 'Y':
            memory[pointer] = memory.get(pointer, 0) * copied
            memory[pointer] = ((memory[pointer] % 256) + 256) % 256
        elif cmd == 'D':
            val = memory.get(pointer, 0)
            if copied == 0:
                memory[pointer] = 0
            else:
                memory[pointer] = val // copied
                memory[pointer] = ((memory[pointer] % 256) + 256) % 256

        ip += 1

    return ''.join(output)

def count_divisors(n):
