def is_balanced(string, pairs):
    # Create mappings from pairs string
    closer_to_opener = {}
    openers = set()
    closers = set()
    ambiguous = set()  # Characters that are both opener and closer

    # Parse pairs string - each even index is opener, odd index is closer
    for i in range(0, len(pairs), 2):
        opener = pairs[i]
        closer = pairs[i + 1]
        closer_to_opener[closer] = opener
        openers.add(opener)
        closers.add(closer)

        # Track if a character is both opener and closer
        if opener == closer:
            ambiguous.add(opener)

    # Stack to track open sections
    stack = []

    for char in string:
        if char in openers:
            # If it's ambiguous (same as closer), check stack context
            if char in ambiguous:
                # If stack is empty or top is different, it's an opener
                # If stack top is same character, it's a closer
                if stack and stack[-1] == char:
                    stack.pop()  # It's a closer
                else:
                    stack.append(char)  # It's an opener
            else:
                stack.append(char)  # It's an opener
        elif char in closers:
            # It's only a closer (not an opener)
            if not stack:
                return False  # Closing without opening
            if stack[-1] != closer_to_opener[char]:
                return False  # Mismatched opener/closer
            stack.pop()
        # Ignore any other characters

    # All sections should be closed
    return len(stack) == 0

