        row = int(pos[1]) - 1
        return (row, col)

    # Check if position is on board
    def is_valid_pos(pos):
        return 0 <= pos[0] <= 7 and 0 <= pos[1] <= 7

    # Get all positions attacked by Amazon from a given position
    def get_amazon_attacks(pos):
        attacks = set()
        row, col = pos

        # Queen-like moves (horizontal and vertical)
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            for i in range(1, 8):
                nr, nc = row + dr * i, col + dc * i
                if is_valid_pos((nr, nc)):
                    attacks.add((nr, nc))

        # Queen-like moves (diagonal)
        for dr, dc in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
            for i in range(1, 8):
                nr, nc = row + dr * i, col + dc * i
                if is_valid_pos((nr, nc)):
                    attacks.add((nr, nc))

        # Knight-like moves
        knight_moves = [
            (-2, -1), (-2, 1), (-1, -2), (-1, 2),
            (1, -2), (1, 2), (2, -1), (2, 1)
        ]
        for dr, dc in knight_moves:
            nr, nc = row + dr, col + dc
            if is_valid_pos((nr, nc)):
                attacks.add((nr, nc))

        return attacks

    # Check if two positions are adjacent (including diagonally), but not the same square
    def is_adjacent(pos1, pos2):
        if pos1 == pos2:
            return False
        return abs(pos1[0] - pos2[0]) <= 1 and abs(pos1[1] - pos2[1]) <= 1

    # Get all possible king moves from a position
    def get_king_moves(pos):
        moves = []
        row, col = pos
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = row + dr, col + dc
                if is_valid_pos((nr, nc)):
                    moves.append((nr, nc))
        return moves

    # Parse input positions
    white_king_pos = parse_pos(king)
    white_amazon_pos = parse_pos(amazon)

    # Get all squares attacked by Amazon
    amazon_attacks = get_amazon_attacks(white_amazon_pos)

    # Counters for each category
    checkmate = 0
    check = 0
    stalemate = 0
    safe_with_moves = 0

    # Check all possible black king positions
    for row in range(8):
        for col in range(8):
            black_king_pos = (row, col)

            # Skip if occupied by white pieces
            if black_king_pos == white_king_pos or black_king_pos == white_amazon_pos:
                continue

            # Skip if adjacent to white king (kings cannot be adjacent)
            if is_adjacent(black_king_pos, white_king_pos):
                continue

            # Check if black king is under Amazon attack
            under_attack = black_king_pos in amazon_attacks

            # Check if black king has valid escape moves
            escape_moves = []
            for move in get_king_moves(black_king_pos):
                # Move must be on board (already guaranteed by get_king_moves)
                # Move cannot be occupied by white pieces
                if move == white_king_pos or move == white_amazon_pos:
                    continue
                # Move cannot be adjacent to white king
                if is_adjacent(move, white_king_pos):
                    continue
                # Move cannot be under Amazon attack
                if move in amazon_attacks:
                    continue
                escape_moves.append(move)

            # Categorize based on attack status and escape moves
            if under_attack:
                if len(escape_moves) == 0:
                    checkmate += 1
                else:
                    check += 1
            else:
                if len(escape_moves) == 0:
                    stalemate += 1
                else:
                    safe_with_moves += 1

    return [checkmate, check, stalemate, safe_with_moves]

