import sys
from math import factorial

def comb(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1
    return factorial(n) // (factorial(k) * factorial(n - k))

def probability_all_collected(n, k):
    if n < k:
        return 0.0
    if k == 0:
        return 1.0

    # Using inclusion-exclusion principle
    # P(all k types in n days) = sum_{j=0}^{k} (-1)^j * C(k,j) * ((k-j)/k)^n
    prob = 0.0
    for j in range(k + 1):
        sign = (-1) ** j
        coeff = comb(k, j)
        term = ((k - j) / k) ** n
        prob += sign * coeff * term

    return prob

def solve(k, target_prob):
    # Binary search for minimum n
    left, right = 1, k * 10000  # Upper bound estimation

    while left < right:
        mid = (left + right) // 2
        prob = probability_all_collected(mid, k)

        if prob >= target_prob:
            right = mid
        else:
            left = mid + 1

    return left

