import random

def valid_mersenne(n):
    if n <= 1:
        return False

    # n must be prime for 2^n - 1 to be a Mersenne prime
    if not is_prime(n):
        return False

    # Compute 2^n - 1
    m = pow(2, n) - 1

    # Check if m is prime
    return is_prime(m)

def is_prime(num):
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False

    # For smaller numbers, trial division is efficient
    if num < 1000000:
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    # For larger numbers, use Miller-Rabin
    return miller_rabin(num)

def miller_rabin(n, k=10):
    """Miller-Rabin primality test for large numbers"""
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    # Write n-1 as 2^r * d where d is odd
    r = 0
    d = n - 1
    while d % 2 == 0:
        r += 1
        d //= 2

    # Test with k random witnesses
    for _ in range(k):
        a = random.randrange(2, n - 1)
        x = pow(a, d, n)

        if x == 1 or x == n - 1:
            continue

        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False

    return True

