        # Split by spaces and count element selectors
        parts = selector.split()
        for part in parts:
            # Count elements (not including pseudo-elements or pseudo-classes)
            if '#' not in part and '.' not in part and part != '*':
                element_count += 1

        # Special case: if there are no selectors, it's a universal selector
        if id_count == 0 and class_count == 0 and element_count == 0:
            element_count = 1

        return (id_count, class_count, element_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    # Compare specificity tuples
    if spec1 > spec2:
        return selector1
    else:
        return selector2

def proper_fractions(d):
    if d == 1:
        return 0

    result = d

    # Check for factor 2
    if d % 2 == 0:
        result -= result // 2
        while d % 2 == 0:
            d //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= d:
        if d % i == 0:
            result -= result // i
            while d % i == 0:
                d //= i
        i += 2

    # If d is still greater than 1, then it's a prime factor
    if d > 1:
        result -= result // d

    return result

def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into terms
    # Find all terms (including signs)
    terms = re.findall(r'[+-]?[^+-]+', expression)

    # Dictionary to store monomial -> coefficient
    monomial_coeffs = defaultdict(int)

    for term in terms:
        # Separate sign from the rest
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Handle coefficient
        coeff_str = ''
        i = 0
        while i < len(term) and term[i].isdigit():
            coeff_str += term[i]
            i += 1

        if coeff_str:
            coeff = int(coeff_str) * sign
        else:
            coeff = sign

        # Extract variables (everything after the coefficient)
        variables = term[i:]

        # Sort variables to normalize the monomial
        sorted_vars = ''.join(sorted(variables))

        # Add to our dictionary
        monomial_coeffs[sorted_vars] += coeff

    # Remove zero coefficients
    monomial_coeffs = {m: c for m, c in monomial_coeffs.items() if c != 0}

    if not monomial_coeffs:
        return "0"

    # Sort monomials by degree and then lexicographically
    def sort_key(monomial):
        return (len(monomial), monomial)

    sorted_monomials = sorted(monomial_coeffs.keys(), key=sort_key)

    # Build result string
    result_parts = []

    for i, monomial in enumerate(sorted_monomials):
        coeff = monomial_coeffs[monomial]

        # Handle the coefficient
        if coeff == 1 and i > 0:
            coeff_str = ""
        elif coeff == -1 and i > 0:
            coeff_str = "-"
        else:
            coeff_str = str(coeff)

        # Handle first term (no leading +)
        if i == 0:
            if coeff == 1 and monomial:
                result_parts.append(monomial)
            elif coeff == -1 and monomial:
                result_parts.append("-" + monomial)
            else:
                result_parts.append(coeff_str + monomial if monomial else coeff_str)
        else:
            if coeff == 1:
                result_parts.append("+" + monomial)
            elif coeff == -1:
                result_parts.append("-" + monomial)
            else:
                if coeff > 0:
                    result_parts.append("+" + coeff_str + monomial)
                else:
                    result_parts.append(coeff_str + monomial)

    return "".join(result_parts)

def histogram(s):
    # Split the string by spaces to get individual letters
    letters = s.split()

    # If no letters (empty string or only spaces)
    if not letters:
        return {}

    # Count frequency of each letter
    frequency = {}
    for letter in letters:
        frequency[letter] = frequency.get(letter, 0) + 1

    # Find the maximum frequency
    max_freq = max(frequency.values())

    # Return all letters with maximum frequency
    return {letter: count for letter, count in frequency.items() if count == max_freq}

