import re

def simplify(expression):
    """
    Simplifies a multilinear polynomial expression by combining like terms,
    normalizing variable order, and formatting the output correctly.

    Args:
        expression: A string representing a multilinear polynomial (e.g., "3x-yx+2xy-x")

    Returns:
        A simplified string representation of the polynomial
    """
    if not expression:
        return ""

    # Step 1: Parse the expression into terms using regex
    terms = re.findall(r'[+-]?[\d]*[a-z]+', expression)

    # Step 2: Dictionary to store coefficients for each normalized variable combination
    coeffs = {}

    for term in terms:
        # Extract sign
        if term and term[0] in ['+', '-']:
            sign_part = term[0]
            rest = term[1:]
        else:
            sign_part = '+'
            rest = term

        # Extract coefficient and variables
        # Pattern: optional digits followed by one or more lowercase letters
        match = re.match(r'^(\d*)([a-z]+)$', rest)
        if match:
            coef_str, variables = match.groups()
            # Implicit coefficient of 1 if no digits are present
            coef = int(coef_str) if coef_str else 1

            # Apply sign
            if sign_part == '-':
                coef = -coef

            # Normalize variables (sort alphabetically)
            variables = ''.join(sorted(variables))

            # Aggregate coefficients for like terms
            coeffs[variables] = coeffs.get(variables, 0) + coef

    # Step 3: Filter out terms with zero coefficient
    coeffs = {k: v for k, v in coeffs.items() if v != 0}

    # Step 4: Sort by degree (number of variables), then lexicographically
    sorted_terms = sorted(coeffs.items(), key=lambda x: (len(x[0]), x[0]))

    # Step 5: Format output string
    result_parts = []
    for i, (variables, coef) in enumerate(sorted_terms):
        # Handle first term separately (no leading '+' for positive)
        if i == 0:
            if coef == 1:
                result_parts.append(variables)
            elif coef == -1:
                result_parts.append('-' + variables)
            else:
                result_parts.append(str(coef) + variables)
        else:
            # Subsequent terms include sign
            if coef == 1:
                result_parts.append('+' + variables)
            elif coef == -1:
                result_parts.append('-' + variables)
            elif coef > 0:
                result_parts.append('+' + str(coef) + variables)
            else:
                result_parts.append(str(coef) + variables)

    return ''.join(result_parts)

def parse_int(s: str) -> int:
    # Handle empty string edge case
    if not s or not s.strip():
        return 0

    # Create mappings for number words
    units = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9,
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17,
        'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    scales = {
        'hundred': 100, 'thousand': 1000, 'million': 1000000
    }

    # Tokenize: split on spaces and hyphens, convert to lowercase
    import re
    tokens = re.split(r'[\s-]+', s.strip().lower())
    tokens = [t for t in tokens if t]  # Remove empty strings

    result = 0
    current = 0

    for token in tokens:
        if token == 'and':
            # Ignore 'and' as it's grammatical only
            continue

        if token in units:
            # Basic number word (zero through nineteen)
            if token == 'zero' and current == 0 and result == 0:
                # Special case for "zero" at the start
                result = 0
                current = 0
            else:
                current += units[token]

        elif token in tens:
            # Tens word (twenty through ninety)
            current += tens[token]

        elif token in scales:
            # Scale multiplier
            scale = scales[token]

            if token == 'hundred':
                # Hundred multiplies the current accumulated value
                current *= scale
            else:
                # Thousand or million: add current chunk to result, reset current
                current *= scale
                result += current
                current = 0

    # Add any remaining value to result
    result += current

    return result

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, value) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract just the values from the sorted pairs
    return [num for _, _, num in indexed_nums]

def palindrome(num):
    # Check if input is a boolean (bool is a subclass of int in Python)
    if isinstance(num, bool):
        return "Not valid"

    # Check if input is not an integer
    if not isinstance(num, int):
        return "Not valid"

    # Check if input is negative
    if num < 0:
        return "Not valid"

    # Convert to string and check if it reads the same forward and backward
    num_str = str(num)
    return num_str == num_str[::-1]

