def getAllPrimeFactors(n):
    factors = []
    if n <= 1:
        return factors

    # Handle factor 2
    while n % 2 == 0:
        factors.append(2)
        n //= 2

    # Check odd numbers from 3 up to sqrt(n)
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        factors.append(n)

    return factors

import re

def differentiate(poly, x):
    poly = poly.strip()
    if not poly:
        return 0

    total = 0
    i = 0
    n = len(poly)

    while i < n:
        # Skip whitespace
        while i < n and poly[i].isspace():
            i += 1
        if i >= n:
            break

        # Parse term sign
        sign = 1
        if i < n and poly[i] == '-':
            sign = -1
            i += 1
        elif i < n and poly[i] == '+':
            i += 1

        # Skip whitespace
        while i < n and poly[i].isspace():
            i += 1
        if i >= n:
            break

        # Parse coefficient
        term_start = i
        while i < n and poly[i].isdigit():
            i += 1

        coeff_str = poly[term_start:i]
        coeff = int(coeff_str) if coeff_str else 1

        # Check for 'x'
        if i < n and poly[i] == 'x':
            i += 1

            # Check for exponent
            if i < n and poly[i] == '^':
                i += 1
                exp_start = i
                while i < n and poly[i].isdigit():
                    i += 1
                exp_str = poly[exp_start:i]
                exponent = int(exp_str) if exp_str else 1
            else:
                exponent = 1

            final_coeff = sign * coeff

            # Differentiate: d/dx(ax^n) = n*a*x^(n-1)
            if exponent > 0:
                deriv_coeff = final_coeff * exponent
                deriv_exponent = exponent - 1
                if deriv_exponent == 0:
                    total += deriv_coeff
                elif deriv_exponent > 0:
                    total += deriv_coeff * (x ** deriv_exponent)
        else:
            # Constant term, derivative is 0
            pass

        # Skip whitespace
        while i < n and poly[i].isspace():
            i += 1

    return total

def choose(n, k):
    # Handle edge cases
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    # Use symmetry property: C(n, k) = C(n, n-k)
    k = min(k, n - k)

    # Iterative computation to avoid large factorials
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)

    return result

