def parse_nested_parens(s):
    if not s:
        return []

    groups = s.split()
    result = []

    for group in groups:
        current_depth = 0
        max_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

def is_valid(s):
    if not s:
        return False

    # Check the first character
    first_char = s[0]
    # First character must be alpha, underscore, or dollar sign.
    # It cannot be a digit.
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Check the rest of the characters
    for char in s[1:]:
        # Rest can be alpha, digit, underscore, or dollar sign
        if not (char.isalnum() or char == '_' or char == '$'):
            return False

    return True

def string_xor(a, b):
    # Handle empty strings
    if not a or not b:
        return ''

    # Ensure both strings have the same length by padding with leading zeros
    max_len = max(len(a), len(b))
    a = a.zfill(max_len)
    b = b.zfill(max_len)

    # Perform XOR operation
    result = []
    for i in range(max_len):
        if a[i] == b[i]:
            result.append('0')
        else:
            result.append('1')

    return ''.join(result)

def smallest_change(arr):
    if len(arr) <= 1:
        return 0

    changes = 0
    n = len(arr)

    # Compare elements from both ends moving towards the center
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1

    return changes

