                    adjacent.append((new_row, new_col))
        return adjacent

    # Parse input
    amazon_coord = chess_to_coord(amazon_pos)
    white_king_coord = chess_to_coord(white_king_pos)

    # Get amazon attack set
    amazon_attacks = get_amazon_attacks(amazon_coord)

    # Get adjacent squares to white king
    white_king_adjacent = set(get_king_adjacent(white_king_coord))

    # Initialize result counts
    counts = [0, 0, 0, 0]

    # Check all possible black king positions
    for row in range(8):
        for col in range(8):
            # Skip if position is occupied by white king or amazon
            if (row, col) == white_king_coord or (row, col) == amazon_coord:
                continue

            # Skip if position is adjacent to white king
            if (row, col) in white_king_adjacent:
                continue

            # Check if black king is attacked by amazon
            is_attacked = (row, col) in amazon_attacks

            # Check if black king has valid move
            has_valid_move = False
            black_king_coord = (row, col)
            king_adjacent = get_king_adjacent(black_king_coord)

            for adj_row, adj_col in king_adjacent:
                # Check if adjacent square is valid
                if (adj_row, adj_col) == white_king_coord or (adj_row, adj_col) == amazon_coord:
                    continue
                if (adj_row, adj_col) in white_king_adjacent:
                    continue
                if (adj_row, adj_col) in amazon_attacks:
                    continue

                # If we reach here, the move is valid
                has_valid_move = True
                break

            # Classify state
            if is_attacked:
                if has_valid_move:
                    counts[1] += 1  # Check
                else:
                    counts[0] += 1  # Checkmate
            else:
                if has_valid_move:
                    counts[3] += 1  # Safe
                else:
                    counts[2] += 1  # Stalemate

    return counts

def next_smallest(lst):
    """
    You are given a list of integers.
    Write a function next_smallest() that returns the 2nd smallest element of the list.
    Return None if there is no such element.
    """
    if not lst:
        return None

    first = None
    second = None

    for num in lst:
        if first is None:
            first = num
        elif num < first:
            second = first
            first = num
        elif num > first and (second is None or num < second):
            second = num

    return second

