def valid_mersenne(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # A Mersenne prime is of the form 2^n - 1 where both n and 2^n - 1 are prime
    if not is_prime(n):
