def palindrome(num):
    if not isinstance(num, int) or isinstance(num, bool) or num < 0:
        return "Not valid"

    original = num
    reversed_num = 0

    while num > 0:
        reversed_num = reversed_num * 10 + num % 10
        num //= 10

    return original == reversed_num

def amazon_check_mate(amazon_row, amazon_col, white_king_row, white_king_col):
    """
    Analyze chess position with amazon and white king to count black king positions
    that result in checkmate, stalemate, check, or safe conditions.

    Args:
        amazon_row: Amazon piece row (1-8)
        amazon_col: Amazon piece column (1-8)
        white_king_row: White king row (1-8)
        white_king_col: White king column (1-8)

    Returns:
        dict with counts for 'checkmate', 'stalemate', 'check', 'safe'
    """
    # Convert to 0-indexed
    ar, ac = amazon_row - 1, amazon_col - 1
    wk_r, wk_c = white_king_row - 1, white_king_col - 1

    ROWS, COLS = 8, 8

    def get_amazon_attacks(row, col):
        """Get all squares attacked by amazon (queen + knight moves)"""
        attacks = set()

        # Queen-like moves (horizontal, vertical, diagonal)
        # Horizontal
        for c in range(COLS):
            if c != col:
                attacks.add((row, c))
        # Vertical
        for r in range(ROWS):
            if r != row:
                attacks.add((r, col))
        # Diagonal
        diagonals = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        for dr, dc in diagonals:
            r, c = row + dr, col + dc
            while 0 <= r < ROWS and 0 <= c < COLS:
                attacks.add((r, c))
                r += dr
                c += dc

        # Knight moves (8 L-shaped moves)
        knight_moves = [(2, 1), (2, -1), (-2, 1), (-2, -1),
                        (1, 2), (1, -2), (-1, 2), (-1, -2)]
        for dr, dc in knight_moves:
            r, c = row + dr, col + dc
            if 0 <= r < ROWS and 0 <= c < COLS:
                attacks.add((r, c))

        return attacks

    def get_king_adjacent(row, col):
        """Get all 8 squares adjacent to a position (king's movement)"""
        adjacent = set()
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                r, c = row + dr, col + dc
                if 0 <= r < ROWS and 0 <= c < COLS:
                    adjacent.add((r, c))
        return adjacent

    amazon_attacks = get_amazon_attacks(ar, ac)
    white_king_zone = get_king_adjacent(wk_r, wk_c)

    checkmate = 0
    stalemate = 0
    check = 0
    safe = 0

    for r in range(ROWS):
        for c in range(COLS):
            # Skip white king position
            if (r, c) == (wk_r, wk_c):
                continue

            # Skip squares adjacent to white king (kings cannot be adjacent)
            if (r, c) in white_king_zone:
                continue

            # Determine if black king is in check
            in_check = (r, c) in amazon_attacks

            # Find valid escape squares for black king
            valid_escapes = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    er, ec = r + dr, c + dc
                    if 0 <= er < ROWS and 0 <= ec < COLS:
                        if (er, ec) not in white_king_zone:
                            if (er, ec) not in amazon_attacks:
                                valid_escapes.append((er, ec))

            has_escape = len(valid_escapes) > 0

            # Classify the position
            if in_check:
                if has_escape:
                    check += 1
                else:
                    checkmate += 1
            else:
                if has_escape:
                    safe += 1
                else:
                    stalemate += 1

    return {
        'checkmate': checkmate,
        'stalemate': stalemate,
        'check': check,
        'safe': safe
    }

def get_closest_vowel(word):
    if len(word) < 3:
