def simplify(expression: str) -> str:
    import re

    if not expression:
        return ""

    # Add + at start if needed for uniform parsing
    if expression[0] != '-':
        expression = '+' + expression

    # Find all terms with their signs, coefficients, and variables
    pattern = r'([+-])(\d*)([a-z]+)'
    matches = re.findall(pattern, expression)

    # Combine like terms
    terms = {}

    for sign, coeff_str, vars_str in matches:
        coeff = int(coeff_str) if coeff_str else 1
        if sign == '-':
            coeff = -coeff
        # Sort variables to normalize (xy == yx)
        sorted_vars = ''.join(sorted(vars_str))

        if sorted_vars not in terms:
            terms[sorted_vars] = 0
        terms[sorted_vars] += coeff

    # Filter out zero coefficients
    nonzero_terms = [(vars, coeff) for vars, coeff in terms.items() if coeff != 0]

    # Sort by number of variables (ascending), then lexicographically
    nonzero_terms.sort(key=lambda x: (len(x[0]), x[0]))

    # Format the output
    result_parts = []
    for vars, coeff in nonzero_terms:
        if not result_parts:
            # First term: no leading +
            if coeff == 1:
                result_parts.append(vars)
            elif coeff == -1:
                result_parts.append('-' + vars)
            else:
                result_parts.append(str(coeff) + vars)
        else:
            # Subsequent terms: include sign explicitly
            if coeff == 1:
                result_parts.append('+' + vars)
            elif coeff == -1:
                result_parts.append('-' + vars)
            else:
                result_parts.append(str(coeff) + vars)

    return ''.join(result_parts)

