def fib4(n):
    # Base cases
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Initialize the last 4 values: fib4(0), fib4(1), fib4(2), fib4(3)
    f0, f1, f2, f3 = 0, 0, 2, 0

    # Iteratively compute fib4(n) using the recurrence relation
    for _ in range(4, n + 1):
        fn = f0 + f1 + f2 + f3
        # Shift values: drop the oldest, add the newest
        f0, f1, f2, f3 = f1, f2, f3, fn

    return f3

def encrypt(s):
    result = []
    for char in s:
        if 'a' <= char <= 'z':
            # Calculate position in alphabet (0-25)
            pos = ord(char) - ord('a')
            # Shift by 4 positions with wrapping
            new_pos = (pos + 4) % 26
            # Convert back to character
            new_char = chr(new_pos + ord('a'))
            result.append(new_char)
        else:
            # Keep non-lowercase characters unchanged
            result.append(char)
    return ''.join(result)

def parse_int(s: str) -> int:
    units = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    teens = {
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17,
        'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    scales = {
        'hundred': 100,
        'thousand': 1000,
        'million': 1000000
    }

    # Split by whitespace, then by hyphens for compound numbers
    words = []
    for word in s.split():
        words.extend(word.split('-'))

    current_total = 0
    final_total = 0

    for word in words:
        word = word.lower()

        # Skip "and"
        if word == 'and':
            continue

        # Check for scale words
        if word in scales:
            if scales[word] == 100:  # hundred
                current_total *= 100
            else:  # thousand or million
                current_total *= scales[word]
                final_total += current_total
                current_total = 0
        elif word in units:
            current_total += units[word]
        elif word in teens:
            current_total += teens[word]
        elif word in tens:
            current_total += tens[word]

    final_total += current_total

    return final_total

def parse_int(s):
    # Handle zero case
    if s == "zero":
        return 0

    # Define word mappings
    units = {
        'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9,
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17,
        'eighteen': 18, 'nineteen': 19
    }

    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }

    # Preprocess: lowercase, remove "and", replace hyphens with spaces
    s = s.lower().replace('and', '').replace('-', ' ').strip()

    # Split into words
    words = s.split()

    total = 0
    current = 0

    for word in words:
        if word in units:
            current += units[word]
        elif word in tens:
            current += tens[word]
        elif word == 'hundred':
            current *= 100
        elif word == 'thousand':
            total += current * 1000
            current = 0
        elif word == 'million':
            total += current * 1000000
            current = 0

    # Add any remaining value
    total += current

    return total

def cycpattern_check(a, b):
    # If b is longer than a, no rotation of b can be a substring of a
    if len(b) > len(a):
        return False

    # Generate all rotations of b and check if any is a substring of a
    # A rotation of b can be obtained by taking b[i:] + b[:i] for i in range(len(b))
    for i in range(len(b)):
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True

    return False

