def compare(selector1, selector2):
    def parse_selector(selector):
        parts = selector.split()
        id_count = 0
        class_count = 0
        tag_count = 0

        for part in parts:
            if not part:
                continue

            # Count IDs (#)
            id_count += part.count('#')

            # Count classes (.)
            class_count += part.count('.')

            # Check if it's a tag (contains alphanumeric character)
            # Universal selector * has no specificity
            if any(c.isalnum() for c in part):
                tag_count += 1

        return (id_count, class_count, tag_count)

    spec1 = parse_selector(selector1)
    spec2 = parse_selector(selector2)

    # Compare lexicographically: (id_count, class_count, tag_count)
    if spec1 > spec2:
        return selector1
    else:
        return selector2

