def is_valid(s):
    # Check if string is empty (must have at least one character)
    if len(s) == 0:
        return False

    # First character must be alpha, underscore, or dollar sign
    first_char = s[0]
    if not (first_char.isalpha() or first_char == '_' or first_char == '$'):
        return False

    # Remaining characters can be alpha, digit, underscore, or dollar sign
    for char in s[1:]:
        if not (char.isalpha() or char.isdigit() or char == '_' or char == '$'):
            return False

    return True

def solution(input_string, markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the earliest comment marker
        earliest_marker_index = len(line)
        for marker in markers:
            marker_index = line.find(marker)
            if marker_index != -1 and marker_index < earliest_marker_index:
                earliest_marker_index = marker_index

        # Truncate the line at the earliest marker
        truncated_line = line[:earliest_marker_index]

        # Strip trailing whitespace
        truncated_line = truncated_line.rstrip()

        result_lines.append(truncated_line)

    return '\n'.join(result_lines)

