                attacks.add((i, amazon_y))
        for j in range(8):
            if j != amazon_y:
                attacks.add((amazon_x, j))

        # Diagonals
        for dx in [-1, 1]:
            for dy in [-1, 1]:
                x, y = amazon_x + dx, amazon_y + dy
                while is_valid(x, y):
                    attacks.add((x, y))
                    x += dx
                    y += dy

        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            x, y = amazon_x + dx, amazon_y + dy
            if is_valid(x, y):
                attacks.add((x, y))

        return attacks

