def parse_nested_parens(s):
    groups = s.split()
    result = []

    for group in groups:
        current_depth = 0
        max_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

def exchange_sort(sequence):
    # Count occurrences of each value
    count = {7: 0, 8: 0, 9: 0}
    for val in sequence:
        count[val] += 1

    # Create target sorted sequence
    target = []
    target.extend([7] * count[7])
    target.extend([8] * count[8])
    target.extend([9] * count[9])

    # Create a mapping from value to its target positions
    target_positions = {7: [], 8: [], 9: []}
    for i, val in enumerate(target):
        target_positions[val].append(i)

    # Create a mapping from current positions to values
    current_positions = {}
    for i, val in enumerate(sequence):
        if val not in current_positions:
            current_positions[val] = []
        current_positions[val].append(i)

    # Create a permutation array showing where each element should go
    perm = [-1] * len(sequence)
    for val in [7, 8, 9]:
        target_idx = 0
        for current_idx in current_positions.get(val, []):
            perm[current_idx] = target_positions[val][target_idx]
            target_idx += 1

    # Count cycles in the permutation
    visited = [False] * len(sequence)
    swaps = 0

    for i in range(len(sequence)):
        if visited[i] or perm[i] == i:
            continue

        # Find cycle length
        cycle_length = 0
        current = i
        while not visited[current]:
            visited[current] = True
            current = perm[current]
            cycle_length += 1

        # For a cycle of length k, we need (k-1) swaps
        if cycle_length > 0:
            swaps += cycle_length - 1

    return swaps

