def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, value) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for stability
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract just the values from the sorted pairs
    return [num for _, _, num in indexed_nums]

def string_to_md5(text):
    import hashlib
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()

def cycpattern_check(a, b):
    if not b:
        return True
    if not a:
        return False

    # Generate all rotations of b and check if any is a substring of a
    for i in range(len(b)):
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True
    return False

def fib4(n):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize the first four values
    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute fib4(n)
    for i in range(4, n + 1):
        next_val = a + b + c + d
        a, b, c, d = b, c, d, next_val

    return d

