    n_str = str(n)
    square_str = str(square)

    # Check if the square ends with the same digits as the number
    if square_str.endswith(n_str):
        return "Automorphic"
    else:
        return "Not!!"

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    gems = list(map(int, lines[1].split()))

    # dp[i][j] represents minimum operations to remove substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Fill the DP table
    # Length of substring
    for length in range(1, n + 1):
        # Starting index
        for i in range(n - length + 1):
            j = i + length - 1

            if i == j:
                # Single element needs 1 operation
                dp[i][j] = 1
            elif i + 1 == j:
                # Two elements
                if gems[i] == gems[j]:
                    dp[i][j] = 1  # Can remove as one palindrome
                else:
                    dp[i][j] = 2  # Need two operations
            else:
                # More than 2 elements
                if gems[i] == gems[j]:
                    # If first and last are same, we can remove them together
                    # and solve for the middle
                    dp[i][j] = dp[i + 1][j - 1]
                else:
                    # Otherwise, we must split
                    dp[i][j] = float('inf')
                    # Try all possible splits
                    for k in range(i, j):
                        dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

