def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.
    """
    def digit_sum(n):
        # Calculate sum of digits using absolute value (magnitude)
        return sum(int(digit) for digit in str(abs(n)))

    # Python's sorted() is stable, so equal keys preserve original order
    return sorted(nums, key=digit_sum)

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """

    def to_numeric(val):
        """Convert input to float for comparison"""
        if isinstance(val, (int, float)):
            return float(val)
        elif isinstance(val, str):
            # Replace comma with dot for decimal separator
            return float(val.replace(',', '.'))
        return None

    num_a = to_numeric(a)
    num_b = to_numeric(b)

    if num_a > num_b:
        return a
    elif num_b > num_a:
        return b
    else:
        return None

def getAllPrimeFactors(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    if not isinstance(n, int) or n <= 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)
    unique_factors = []
    counts = []

    if not factors:
        return [[], []]

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    unique_factors, counts = getUniquePrimeFactorsWithCount(n)
    products = []

    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

