def compare(selector1, selector2):
    def get_specificity(selector):
        # Count ID selectors (#)
        id_count = selector.count('#')

        # Count class selectors (.)
        class_count = selector.count('.')

        # Count tag name selectors (elements that are not # or .)
        # We need to split by spaces and remove # and . selectors
        elements = selector.split()
        tag_count = 0
        for element in elements:
            # Remove any # or . from the element
            clean_element = element.replace('#', '').replace('.', '')
            if clean_element and clean_element != '*':
                tag_count += 1

        # Handle the case where there are no elements but there are # or . selectors
        if tag_count == 0:
            # Check if the selector is just # or . selectors
            if selector.strip() == '*':
                tag_count = 0
            elif selector.strip().startswith('#') or selector.strip().startswith('.'):
                # If it's only # or . selectors, we still count as 0 tags
                pass

        return (id_count, class_count, tag_count)

    # Special handling for "*" selector
    if selector1 == "*":
        return selector2
    if selector2 == "*":
        return selector1

    # Get specificities
    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    # Compare specificities
    if spec1 > spec2:
        return selector1
    elif spec2 > spec1:
        return selector2
    else:
        # If specificities are equal, return the second one (later in input)
        return selector2

import re
from collections import defaultdict

def simplify(expression):
    if not expression:
        return ""

    # Extract terms with their signs, coefficients, and variables
    terms = re.findall(r'([+-]?)(\d*)([a-z]+)', expression)

    monomials = defaultdict(int)

    for sign, coeff_str, var_part in terms:
        # Determine sign value
        if sign == '-':
            sign_val = -1
        else:
            sign_val = 1

        # Determine coefficient
        if coeff_str == '':
            coeff = 1
        else:
            coeff = int(coeff_str)

        coeff *= sign_val

        # Normalize variable order (sort alphabetically)
        var_part = ''.join(sorted(var_part))

        monomials[var_part] += coeff

    # Filter out zero coefficients
    monomials = {k: v for k, v in monomials.items() if v != 0}

    # Sort: by number of variables (ascending), then lexicographically
    sorted_vars = sorted(monomials.keys(), key=lambda x: (len(x), x))

    # Build output
    result_parts = []
    for i, var in enumerate(sorted_vars):
        coeff = monomials[var]
        if i == 0:
            # First term: no leading +
            if coeff == 1:
                result_parts.append(var)
            elif coeff == -1:
                result_parts.append('-' + var)
            elif coeff > 0:
                result_parts.append(str(coeff) + var)
            else:
                result_parts.append(str(coeff) + var)
        else:
            # Subsequent terms: + for positive coefficients
            if coeff == 1:
                result_parts.append('+' + var)
            elif coeff == -1:
                result_parts.append('-' + var)
            elif coeff > 0:
                result_parts.append('+' + str(coeff) + var)
            else:
                result_parts.append(str(coeff) + var)

    return ''.join(result_parts)

