def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    balance = 0
    current_group = ""

    for char in paren_string:
        if char == ' ':
            continue

        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1

        current_group += char

        if balance == 0 and current_group:
            result.append(current_group)
            current_group = ""

    return result

def cycpattern_check(a, b):
    if not a or not b:
        return False

    if len(b) > len(a):
        return False

    b_double = b + b
    b_len = len(b)

    for i in range(len(a) - b_len + 1):
        substring = a[i:i + b_len]
        if substring in b_double:
            return True

    return False

def converter(number, decimals=0, base=None):
    import math

    # Set default base to π if not provided
    if base is None:
        base = math.pi

    # Character set for digits
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

    # Handle sign
    negative = False
    if isinstance(number, (int, float)) and number < 0:
        negative = True
        number = abs(number)

    # Handle zero case
    if number == 0:
        if decimals > 0:
            return '-0.' + '0' * decimals if negative else '0.' + '0' * decimals
        else:
            return '-0' if negative else '0'

    # Split into integer and fractional parts
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_result = '0'
    else:
        result = []
        temp = integer_part

        # For integer base, use standard algorithm
        if base == int(base):
            while temp > 0:
                temp, remainder = divmod(temp, int(base))
                result.append(digits[remainder])
            integer_result = ''.join(reversed(result))
        else:
            # For non-integer base (like π)
            while temp > 0:
                quotient = temp / base
                remainder = temp - quotient
                result.append(digits[int(round(remainder))])
                temp = int(quotient)
            integer_result = ''.join(reversed(result))

    # Convert fractional part
    fractional_result = ''
    if decimals > 0 and fractional_part > 0:
        frac_digits = []
        temp = fractional_part
        for _ in range(decimals):
            temp = temp * base
            digit = int(temp)
            frac_digits.append(digits[digit])
            temp = temp - digit
        fractional_result = ''.join(frac_digits)

    # Ensure we have the right number of decimals
    while len(fractional_result) < decimals:
        fractional_result += '0'

    # Combine results with proper formatting
    if negative:
        if fractional_result:
            return f'-{integer_result}.{fractional_result}'
        else:
            return f'-{integer_result}'
    else:
        if fractional_result:
            return f'{integer_result}.{fractional_result}'
        else:
            return integer_result

import re

def differentiate(polynomial, x):
    # Parse the polynomial into terms
    # Split by + and - signs, but keep the signs
    terms = re.findall(r'[+-]?[^+-]+', polynomial)

    total_derivative = 0

    for term in terms:
        term = term.strip()
        if not term:
            continue

        # Handle the sign
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Parse the term
        if 'x^' in term:
            # Format: [coefficient]x^[exponent]
            parts = term.split('x^')
            if parts[0] == '':
                coefficient = sign * 1
            else:
                coefficient = sign * int(parts[0])
            exponent = int(parts[1])
        elif 'x' in term:
            # Format: [coefficient]x or x
            if term == 'x':
                coefficient = sign * 1
                exponent = 1
            else:
                # Remove 'x' from the end
                coefficient_str = term[:-1]
                if coefficient_str == '':
                    coefficient = sign * 1
                elif coefficient_str == '-':
                    coefficient = sign * -1
                else:
                    coefficient = sign * int(coefficient_str)
                exponent = 1
        else:
            # Constant term
            coefficient = sign * int(term)
            exponent = 0

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exponent == 0:
            # Derivative of constant is 0
            derivative = 0
        else:
            derivative = exponent * coefficient * (x ** (exponent - 1))

        total_derivative += derivative

    return total_derivative

def proper_fractions(n):
    if n == 1:
        return 0

    result = n

    # Check for factor 2
    if n % 2 == 0:
        result -= result // 2
        while n % 2 == 0:
            n //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result -= result // i
            while n % i == 0:
                n //= i
        i += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        result -= result // n

    return result

def differentiate(polynomial, x):
    # Parse the polynomial into terms
    terms = []
    current_term = ""
    i = 0

    # Handle the first term specially if it starts with -
    if polynomial[0] == '-':
        current_term = "-"
        i = 1
    else:
        current_term = ""
        i = 0

    # Split by + and - signs, but keep the signs
    while i < len(polynomial):
        if polynomial[i] in ['+', '-']:
            if current_term:
                terms.append(current_term)
            current_term = polynomial[i]
        else:
            current_term += polynomial[i]
        i += 1

    if current_term:
        terms.append(current_term)

    # Process each term
    derivative_terms = []

    for term in terms:
        # Skip empty terms
        if not term or term == '+' or term == '-':
            continue

        # Determine sign
        sign = 1
        term_content = term
        if term.startswith('-'):
            sign = -1
            term_content = term[1:]
        elif term.startswith('+'):
            term_content = term[1:]

        # Handle constant term (no x)
        if 'x' not in term_content:
            # This is a constant term, derivative is 0
            continue

        # Extract coefficient and exponent
        if 'x^' in term_content:
            # Format: ax^n
            parts = term_content.split('x^')
            coeff_str = parts[0]
            if coeff_str == '':
                coeff = sign * 1
            elif coeff_str == '-':
                coeff = sign * -1
            else:
                coeff = sign * int(coeff_str)
            exp = int(parts[1])
        elif 'x' in term_content:
            # Format: ax or ax^1
            if term_content == 'x':
                coeff = sign * 1
                exp = 1
            elif term_content == '-x':
                coeff = sign * -1
                exp = 1
            else:
                coeff_str = term_content.replace('x', '')
                if coeff_str == '':
                    coeff = sign * 1
                elif coeff_str == '-':
                    coeff = sign * -1
                else:
                    coeff = sign * int(coeff_str)
                exp = 1
        else:
            # This shouldn't happen if we handle correctly above
            continue

        # Apply power rule: d/dx(ax^n) = n*ax^(n-1)
        if exp > 0:
            new_coeff = exp * coeff
            new_exp = exp - 1
            derivative_terms.append((new_coeff, new_exp))

    # Evaluate the derivative at x
    result = 0
    for coeff, exp in derivative_terms:
        if exp == 0:
            result += coeff
        else:
            result += coeff * (x ** exp)

    return result

