def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    # Check for factor 2
    while n % 2 == 0:
        n = n // 2

    # Check for odd factors
    i = 3
    while i * i <= n:
        while n % i == 0:
            n = n // i
        i += 2

    # If n > 1 after all divisions, n itself is the largest prime factor
    if n > 1:
        return n

    # This case happens if n was only composed of factor 2
    return 2

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []

    for group in groups:
        max_depth = 0
        current_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

