def format_duration(seconds):
    if seconds == 0:
        return "now"

    # Define time units in seconds
    units = [
        ('year', 365 * 24 * 60 * 60),
        ('day', 24 * 60 * 60),
        ('hour', 60 * 60),
        ('minute', 60),
        ('second', 1)
    ]

    # Calculate each unit
    components = []
    for unit_name, unit_seconds in units:
        if seconds >= unit_seconds:
            count = seconds // unit_seconds
            seconds = seconds % unit_seconds
            plural = 's' if count > 1 else ''
            components.append(f"{count} {unit_name}{plural}")

    # Format the result
    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        return sum(int(d) for d in str(abs(n)))

    return sorted(nums, key=digit_sum)

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, value) and sort by digit_sum
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract just the values from the sorted pairs
    return [num for _, _, num in indexed_nums]

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        return 1

    # Find the smallest prime factor
    if n % 2 == 0:
        smallest_prime = 2
    else:
        smallest_prime = n  # Assume prime initially
        i = 3
        while i * i <= n:
            if n % i == 0:
                smallest_prime = i
                break
            i += 2

    return n // smallest_prime

