def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    gems = list(map(int, lines[1].split()))

    # Precompute palindromic substrings
    is_palindrome = [[False] * n for _ in range(n)]

    # Every single gem is a palindrome
    for i in range(n):
        is_palindrome[i][i] = True

    # Check for palindromes of length 2
    for i in range(n - 1):
        if gems[i] == gems[i + 1]:
            is_palindrome[i][i + 1] = True

    # Check for palindromes of length 3 and more
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if gems[i] == gems[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP approach: dp[i][j] represents minimum seconds to clear substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Fill DP table
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if i == j:
                # Single gemstone requires 1 second
                dp[i][j] = 1
            elif i + 1 == j:
                # Two gemstones - if same color, remove together in 1 second, else 2 seconds
                if gems[i] == gems[j]:
                    dp[i][j] = 1
                else:
                    dp[i][j] = 2
            else:
                # For longer substrings, either remove the entire substring if it's palindrome
                # or split it into two parts
                if is_palindrome[i][j]:
                    dp[i][j] = 1
                else:
                    # Try all possible splits
                    dp[i][j] = float('inf')
                    for k in range(i, j):
                        dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

