    if not isinstance(n, int) or isinstance(n, bool) or n < 0:
        return []

    if n == 0:
        return []

    if n == 1:
        return [1]

    factors = []
    i = 2
    temp = n

    while i * i <= temp:
        while temp % i == 0:
