def getAllPrimeFactors(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    factors = []
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

    if n > 1:
        factors.append(n)

    return factors

def getUniquePrimeFactorsWithCount(n):
    if not isinstance(n, int) or n <= 0:
        return [[], []]

    if n == 1:
        return [[1], [1]]

    factors = getAllPrimeFactors(n)
    unique_factors = []
    counts = []

    if not factors:
        return [[], []]

    current_factor = factors[0]
    count = 1

    for i in range(1, len(factors)):
        if factors[i] == current_factor:
            count += 1
        else:
            unique_factors.append(current_factor)
            counts.append(count)
            current_factor = factors[i]
            count = 1

    unique_factors.append(current_factor)
    counts.append(count)

    return [unique_factors, counts]

def getUniquePrimeFactorsWithProducts(n):
    if not isinstance(n, int) or n <= 0:
        return []

    if n == 1:
        return [1]

    unique_factors, counts = getUniquePrimeFactorsWithCount(n)
    products = []

    for i in range(len(unique_factors)):
        products.append(unique_factors[i] ** counts[i])

    return products

def solution(input_string, markers):
    lines = input_string.split('\n')
    result_lines = []

    for line in lines:
        # Find the first occurrence of any marker
        first_marker_index = len(line)  # Initialize to end of line

        for marker in markers:
            marker_index = line.find(marker)
            if marker_index != -1 and marker_index < first_marker_index:
                first_marker_index = marker_index

        # If no marker found, keep the whole line
        if first_marker_index == len(line):
            result_lines.append(line.rstrip())
        else:
            # Slice the line up to the first marker and strip trailing whitespace
            result_lines.append(line[:first_marker_index].rstrip())

    return '\n'.join(result_lines)

import re
from collections import defaultdict

def simplify(expression):
    # Parse the expression into terms
    # Find all terms (including those starting with -)
    terms = re.findall(r'[+-]?\w+', expression)

    # Dictionary to store monomials and their coefficients
    monomial_dict = defaultdict(int)

    for term in terms:
        # Separate coefficient from variables
        if term[0] == '+':
            coeff = 1
            vars_part = term[1:]
        elif term[0] == '-':
            if len(term) == 1:
                coeff = -1
                vars_part = ""
            else:
                coeff = -1
                vars_part = term[1:]
        else:
            coeff = 1
            vars_part = term

        # Handle case where there's no variable part (just coefficient)
        if not vars_part:
            monomial_dict[''] += coeff
        else:
            # Sort variables to normalize the monomial
            sorted_vars = ''.join(sorted(vars_part))
            monomial_dict[sorted_vars] += coeff

    # Filter out zero coefficients
    monomial_dict = {mon: coeff for mon, coeff in monomial_dict.items() if coeff != 0}

    # Sort monomials by number of variables, then lexicographically
    sorted_monomials = sorted(monomial_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Build result string
    result_parts = []
    first = True

    for monomial, coeff in sorted_monomials:
        if coeff == 0:
            continue

        # Format the term
        if monomial == '':
            # Constant term
            term_str = str(coeff)
        else:
            if coeff == 1:
                term_str = monomial
            elif coeff == -1:
                term_str = '-' + monomial
            else:
                term_str = str(coeff) + monomial

        # Handle signs
        if first:
            if coeff > 0:
                result_parts.append(term_str)
            else:
                result_parts.append(term_str)
            first = False
        else:
            if coeff > 0:
                result_parts.append('+' + term_str)
            else:
                result_parts.append('-' + term_str[1:])  # Remove the minus sign we added

    if not result_parts:
        return "0"

    return ''.join(result_parts)

def poohbear(code):
    valid_commands = {'+', '-', '>', '<', 'c', 'p', 'W', 'E', 'P', 'N', 
                      'T', 'Q', 'U', 'L', 'I', 'V', 'A', 'B', 'Y', 'D'}
    commands = [c for c in code if c in valid_commands]

    jump_map = {}
    w_stack = []
    for i, cmd in enumerate(commands):
        if cmd == 'W':
            w_stack.append(i)
        elif cmd == 'E':
            if w_stack:
                w_idx = w_stack.pop()
                jump_map[w_idx] = i
                jump_map[i] = w_idx

    cells = {}
    pointer = 0
    copy_register = 0
    pc = 0
    output = []

    def wrap(value):
        return value % 256

    while pc < len(commands):
        cmd = commands[pc]
        current = cells.get(pointer, 0)

        if cmd == '+':
            cells[pointer] = wrap(current + 1)
            pc += 1
        elif cmd == '-':
            cells[pointer] = wrap(current - 1)
            pc += 1
        elif cmd == '>':
            pointer += 1
            pc += 1
        elif cmd == '<':
            pointer -= 1
            pc += 1
        elif cmd == 'c':
            copy_register = current
            pc += 1
        elif cmd == 'p':
            cells[pointer] = copy_register
            pc += 1
        elif cmd == 'W':
            if current == 0:
                pc = jump_map.get(pc, pc) + 1
            else:
                pc += 1
        elif cmd == 'E':
            if current != 0:
                pc = jump_map.get(pc, pc)
            else:
                pc += 1
        elif cmd == 'P':
            output.append(chr(current))
            pc += 1
        elif cmd == 'N':
            output.append(str(current))
            pc += 1
        elif cmd == 'T':
            cells[pointer] = wrap(current * 2)
            pc += 1
        elif cmd == 'Q':
            cells[pointer] = wrap(current * current)
            pc += 1
        elif cmd == 'U':
            cells[pointer] = wrap(int(current ** 0.5))
            pc += 1
        elif cmd == 'L':
            cells[pointer] = wrap(current + 2)
            pc += 1
        elif cmd == 'I':
            cells[pointer] = wrap(current - 2)
            pc += 1
        elif cmd == 'V':
            cells[pointer] = wrap(current // 2)
            pc += 1
        elif cmd == 'A':
            cells[pointer] = wrap(current + copy_register)
            pc += 1
        elif cmd == 'B':
            cells[pointer] = wrap(current - copy_register)
            pc += 1
        elif cmd == 'Y':
            cells[pointer] = wrap(current * copy_register)
            pc += 1
        elif cmd == 'D':
            if copy_register != 0:
                cells[pointer] = wrap(current // copy_register)
            else:
                cells[pointer] = 0
            pc += 1

    return ''.join(output)

def valid_mersenne(n):
    # First check if n is prime
    if n < 2:
        return False

    # Check if n is prime
    if n == 2:
        is_prime_n = True
    elif n % 2 == 0:
        is_prime_n = False
    else:
        is_prime_n = True
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                is_prime_n = False
                break

    if not is_prime_n:
        return False

    # If n is prime, check if 2^n - 1 is prime
    # For small values, we can use deterministic Miller-Rabin
    # For larger values, we'll use probabilistic Miller-Rabin
    mersenne = (1 << n) - 1  # This is 2^n - 1

    # For numbers up to 2000, we can use a simple primality check
    # But since 2^n - 1 can be very large, we use Miller-Rabin
    return miller_rabin(mersenne, 5)

def miller_rabin(n, k):
    # Miller-Rabin primality test
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    # Write n-1 as d * 2^r
    r = 0
    d = n - 1
    while d % 2 == 0:
        d //= 2
        r += 1

    # Witness loop
    import random
    for _ in range(k):
        a = random.randrange(2, n - 1)
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

def candies(ratings):
    if not ratings:
        return 0

    n = len(ratings)
    candy_dist = [1] * n

    # Left to right pass
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            candy_dist[i] = candy_dist[i - 1] + 1

    # Right to left pass
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            candy_dist[i] = max(candy_dist[i], candy_dist[i + 1] + 1)

    return sum(candy_dist)

