def sum_of_a_beach(s):
    s_lower = s.lower()
    words = ["sand", "water", "fish", "sun"]
    count = 0
    i = 0

    while i < len(s_lower):
        matched = False
        for word in words:
            if s_lower.startswith(word, i):
                count += 1
                i += len(word)
                matched = True
                break
        if not matched:
            i += 1

    return count

def exchange_sort(arr):
        n = len(arr)
        for i in range(n):
            # Flag to optimize
            swapped = False
            for j in range(0, n - i - 1):
                if arr[j] > arr[j + 1]:
                    arr[j], arr[j + 1] = arr[j + 1], arr[j]
                    swapped = True
            if not swapped:
                break
        return arr

def proper_fractions(n):
    if n == 1:
        return 0

    result = n

    # Check for factor 2
    if n % 2 == 0:
        result -= result // 2
        while n % 2 == 0:
            n //= 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        if n % i == 0:
            result -= result // i
            while n % i == 0:
                n //= i
        i += 2

    # If n is a prime factor greater than 2
    if n > 2:
        result -= result // n

    return result

