def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def to_numeric(val):
        if isinstance(val, (int, float)):
            return float(val)
        elif isinstance(val, str):
            normalized = val.replace(',', '.')
            return float(normalized)
        else:
            raise ValueError(f"Unsupported type: {type(val)}")

    num_a = to_numeric(a)
    num_b = to_numeric(b)

    if num_a > num_b:
        return a
    elif num_b > num_a:
        return b
    else:
        return None

def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    result = ""
    for i in range(len(a)):
        if a[i] == b[i]:
            result += "0"
        else:
            result += "1"
    return result

def largest_divisor(n: int) -> int:
    if n == 0:
        return 0
    if n == 1 or n == -1:
        return 1

    n = abs(n)

    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i

    return 1

def compare(selector1, selector2):
    def get_specificity(selector):
        id_count = 0
        class_count = 0
        tagname_count = 0

        # Split by spaces to handle compound selectors
        parts = selector.split()

        for part in parts:
            if part.startswith('#'):
                id_count += 1
            elif part.startswith('.'):
                class_count += 1
            else:
                # It's a tagname
                tagname_count += 1

        return (id_count, class_count, tagname_count)

    spec1 = get_specificity(selector1)
    spec2 = get_specificity(selector2)

    if spec1 > spec2:
        return selector1
    else:
        return selector2

