from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []

    for group in groups:
        max_depth = 0
        current_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

def candies(arr):
    if len(arr) <= 1:
        return -1

    max_candies = max(arr)
    total_candies = 0

    for candy in arr:
        total_candies += max_candies - candy

    return total_candies

def even_odd_palindrome(n):
    def is_palindrome(num):
        s = str(num)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def below_threshold(l: list, t: int):
    for element in l:
        if element >= t:
            return False
    return True

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        return 1

    # Start from n//2 and go downwards
    for i in range(n // 2, 0, -1):
        if n % i == 0:
            return i

    # This should never be reached for n > 1
    return 1

