def is_balanced(text, pairs):
    # Create mapping from opening to closing characters
    open_to_close = {}
    close_to_open = {}

    for i in range(0, len(pairs), 2):
        open_char = pairs[i]
        close_char = pairs[i + 1]
        open_to_close[open_char] = close_char
        close_to_open[close_char] = open_char

    # Stack to track opening characters
    stack = []

    for char in text:
        if char in open_to_close:
            # It's an opening character
            stack.append(char)
        elif char in close_to_open:
            # It's a closing character
            if not stack:
                return False
            last_open = stack.pop()
            if close_to_open[char] != last_open:
                return False
        # Ignore any other characters

    # Stack should be empty for balanced string
    return len(stack) == 0

def compare(s1, s2):
    def get_specificity(selector):
        ids = 0
        classes = 0
        tags = 0

        # Split by spaces to get individual elements
        elements = selector.split()

        for element in elements:
            # Count IDs
            ids += element.count('#')

            # Count classes (including grouped classes like .a.b)
            class_count = 0
            i = 0
            while i < len(element):
                if element[i] == '.':
                    class_count += 1
                    # Skip to the next dot or end of string
                    i += 1
                    while i < len(element) and element[i] != '.':
                        i += 1
                else:
                    i += 1
            classes += class_count

            # Count tags (elements that are not IDs or classes)
            if not element.startswith('#') and not element.startswith('.'):
                tags += 1
            elif element.startswith('#') or element.startswith('.'):
                # Check if it's a tag name mixed with ID or class
                # For example: div#id.class or .class#id
                # We need to count the tag part
                tag_part = ""
                i = 0
                while i < len(element):
                    if element[i] == '#' or element[i] == '.':
                        break
                    tag_part += element[i]
                    i += 1
                if tag_part and not tag_part.isspace():
                    tags += 1
            else:
                tags += 1

        return (ids, classes, tags)

    # Special case for star selector
    if s1 == "*":
        return s2
    if s2 == "*":
        return s1

    spec1 = get_specificity(s1)
    spec2 = get_specificity(s2)

    # Compare specificity
    if spec1 > spec2:
        return s1
    elif spec2 > spec1:
        return s2
    else:
        # If specificity is equal, the second selector wins (tie-breaker)
        return s2

