def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        return 1

    # Find the smallest divisor greater than 1
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i

    # If no divisor found, n is prime, so the largest proper divisor is 1
    return 1

import sys

def main():
    data = sys.stdin.read()
    lines = data.splitlines()

    n = int(lines[0])
    gems = list(map(int, lines[1].split()))

    # dp[i][j] represents minimum seconds to destroy substring from i to j (inclusive)
    dp = [[float('inf')] * n for _ in range(n)]

    # Every single gemstone takes 1 second to remove
    for i in range(n):
        dp[i][i] = 1

    # Fill the DP table for all substring lengths from 2 to n
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            # If first and last gems have the same color, we can remove them together
            if gems[i] == gems[j]:
                if i + 1 <= j - 1:
                    # If there are gems in between, we can remove the outer gems and solve for inner part
                    dp[i][j] = min(dp[i][j], dp[i + 1][j - 1])
                else:
                    # If there are no gems in between, we just remove the pair
                    dp[i][j] = 1
            else:
                # If first and last gems have different colors, we need to split
                # Try all possible splits and take minimum
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

    print(dp[0][n - 1])

