def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        return 1

    # Start from n//2 and go downwards
    for i in range(n // 2, 0, -1):
        if n % i == 0:
            return i

    # This should never be reached for n > 1
    return 1

def greatest_common_divisor(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> greatest_common_divisor(3, 5)
    1
    >>> greatest_common_divisor(25, 15)
    5
    """
    # Handle edge cases with zero
    if a == 0:
        return abs(b)
    if b == 0:
        return abs(a)

    # Use Euclidean algorithm with absolute values
    a, b = abs(a), abs(b)

    while b:
        a, b = b, a % b

    return a

def largest_divisor(n: int) -> int:
    if n <= 1:
        return 1

    largest = 1

    # Iterate up to sqrt(n)
    i = 1
    while i * i <= n:
        if n % i == 0:
            # i is a divisor
            if i < n:
                largest = max(largest, i)

            # n/i is also a divisor
            complement = n // i
            if complement < n:
                largest = max(largest, complement)
        i += 1

    return largest

