def poohbear(code):
    memory = {}
    pointer = 0
    copy_register = 0
    program_counter = 0

    w_map = {}
    e_map = {}

    stack = []
    for i, char in enumerate(code):
        if char == 'W':
            stack.append(i)
        elif char == 'E':
            if stack:
                w_index = stack.pop()
                w_map[w_index] = i + 1
                e_map[i] = w_index

    output = []

    while program_counter < len(code):
        cmd = code[program_counter]
        jumped = False

        if cmd == 'N':
            pointer += 1
        elif cmd == 'B':
            pointer -= 1
        elif cmd == 'I':
            memory[pointer] = (memory.get(pointer, 0) + 1) % 256
        elif cmd == 'Y':
            memory[pointer] = (memory.get(pointer, 0) - 1) % 256
        elif cmd == 'W':
            if memory.get(pointer, 0) == 0:
                if program_counter in w_map:
                    program_counter = w_map[program_counter]
                    jumped = True
        elif cmd == 'E':
            if program_counter in e_map:
                program_counter = e_map[program_counter]
                jumped = True
        elif cmd == 'Q':
            output.append(chr(memory.get(pointer, 0)))
        elif cmd == 'P':
            current = memory.get(pointer, 0)
            next_cell = memory.get(pointer + 1, 0)
            memory[pointer] = (current + next_cell) % 256
        elif cmd == 'A':
            current = memory.get(pointer, 0)
            next_cell = memory.get(pointer + 1, 0)
            memory[pointer] = (current - next_cell) % 256
        elif cmd == 'T':
            copy_register = memory.get(pointer, 0)
        elif cmd == 'C':
            memory[pointer] = copy_register % 256
        elif cmd == 'M':
            current = memory.get(pointer, 0)
            memory[pointer] = (current * copy_register) % 256
        elif cmd == 'D':
            current = memory.get(pointer, 0)
            if copy_register != 0:
                memory[pointer] = int(current / copy_register) % 256
        elif cmd == 'R':
            current = memory.get(pointer, 0)
            memory[pointer] = int(current ** 0.5) % 256
        elif cmd == 'S':
            current = memory.get(pointer, 0)
            memory[pointer] = copy_register
            copy_register = current
        elif cmd == 'X':
            break
        else:
            pass

        if not jumped:
            program_counter += 1

    return ''.join(output)

def poohbear(code):
    # Pre-process W-E loop pairs
    w_to_e = {}
    e_to_w = {}
    w_stack = []

    for i, char in enumerate(code):
        if char == 'W':
            w_stack.append(i)
        elif char == 'E':
            if w_stack:
                w_pos = w_stack.pop()
                w_to_e[w_pos] = i
                e_to_w[i] = w_pos

    # Initialize interpreter state
    tape = {}  # Dictionary for infinite tape, default 0
    ptr = 0  # Current pointer position
    copied = 0  # Copied value register
    output = []

    def get_cell(pos):
        return tape.get(pos, 0)

    def set_cell(pos, value):
        tape[pos] = value % 256

    def wrap(value):
        return value % 256

    # Execute
    ip = 0  # Instruction pointer

    while ip < len(code):
        cmd = code[ip]

        if cmd == 'W':
            if get_cell(ptr) == 0 and ip in w_to_e:
                ip = w_to_e[ip] + 1
                continue

        elif cmd == 'E':
            if get_cell(ptr) != 0 and ip in e_to_w:
                ip = e_to_w[ip]
                continue

        # Execute all commands (W/E when not jumping become no-ops)
        if cmd == '+':
            set_cell(ptr, get_cell(ptr) + 1)
        elif cmd == '-':
            set_cell(ptr, get_cell(ptr) - 1)
        elif cmd == '>':
            ptr += 1
        elif cmd == '<':
            ptr -= 1
        elif cmd == 'c':
            copied = get_cell(ptr)
        elif cmd == 'p':
            set_cell(ptr, copied)
        elif cmd == 'P':
            output.append(chr(get_cell(ptr)))
        elif cmd == 'N':
            output.append(str(get_cell(ptr)))
        elif cmd == 'T':
            set_cell(ptr, get_cell(ptr) * 2)
        elif cmd == 'Q':
            set_cell(ptr, get_cell(ptr) ** 2)
        elif cmd == 'U':
            set_cell(ptr, int(get_cell(ptr) ** 0.5))
        elif cmd == 'L':
            set_cell(ptr, get_cell(ptr) + 2)
        elif cmd == 'I':
            set_cell(ptr, get_cell(ptr) - 2)
        elif cmd == 'V':
            set_cell(ptr, get_cell(ptr) // 2)
        elif cmd == 'A':
            set_cell(ptr, get_cell(ptr) + copied)
        elif cmd == 'B':
            set_cell(ptr, get_cell(ptr) - copied)
        elif cmd == 'Y':
            set_cell(ptr, get_cell(ptr) * copied)
        elif cmd == 'D':
            if copied != 0:
                set_cell(ptr, get_cell(ptr) // copied)
        # W and E when not jumping are no-ops
        # All other characters are ignored

        ip += 1

    return ''.join(output)

def amazon_check_mate(king, amazon):
    def pos_to_coords(pos):
