def count_up_to(n):
    if n <= 2:
        return []

    # Use Sieve of Eratosthenes for efficient prime finding
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n, i):
                is_prime[j] = False

    # Collect all prime numbers less than n
    primes = []
    for i in range(2, n):
        if is_prime[i]:
            primes.append(i)

    return primes

def fib4(n):
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Initialize the base cases for fib4(0), fib4(1), fib4(2), fib4(3)
    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute fib4 from 4 to n
    for i in range(4, n + 1):
        # fib4(i) = fib4(i-1) + fib4(i-2) + fib4(i-3) + fib4(i-4)
        next_val = a + b + c + d
        # Shift the window: a,b,c,d become fib4(i-3), fib4(i-2), fib4(i-1), fib4(i)
        a, b, c, d = b, c, d, next_val

    return d

