    return [num for _, _, num in indexed_nums]

def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into monomials
    monomials = []
    # Split by + and - signs, keeping the signs
    tokens = re.findall(r'[+-]?[^+-]+', expression)

    for token in tokens:
        if not token:
            continue
        # Determine the sign
        sign = 1
        monomial = token
        if token.startswith('-'):
            sign = -1
            monomial = token[1:]
        elif token.startswith('+'):
            sign = 1
            monomial = token[1:]

        # If the monomial is just a number (no variables), handle it
        if not re.search(r'[a-z]', monomial):
            if monomial:
                monomials.append((sign * int(monomial), '', 0))
        else:
            # Extract variables and their coefficients
            # The coefficient is 1 if not specified
            coeff_str = re.match(r'^[+-]?\d*', monomial)
            if coeff_str and coeff_str.group():
                coeff = int(coeff_str.group())
            else:
                coeff = 1

            # Remove coefficient part to get variables
            var_part = re.sub(r'^[+-]?\d*', '', monomial)
            # Sort variables to normalize order (e.g., "yx" -> "xy")
            sorted_vars = ''.join(sorted(var_part))
            monomials.append((sign * coeff, sorted_vars, len(sorted_vars)))

    # Group by variables and sum coefficients
    grouped = defaultdict(int)
    for coeff, vars_str, num_vars in monomials:
        grouped[vars_str] += coeff

    # Filter out zero coefficients
    terms = [(coeff, vars_str) for vars_str, coeff in grouped.items() if coeff != 0]

    # Sort by number of variables, then lexicographically
    terms.sort(key=lambda x: (len(x[1]), x[1]))

    # Format output
    result = []
    for i, (coeff, vars_str) in enumerate(terms):
        if coeff == 1 and vars_str:
            term = vars_str
        elif coeff == -1 and vars_str:
            term = '-' + vars_str
        else:
            term = str(coeff) + vars_str

        if i == 0:
            result.append(term)
        else:
            if term.startswith('-'):
                result.append('-' + term[1:])
            else:
                result.append('+' + term)

    # Join and handle special case of leading +
    output = ''.join(result)
    if output.startswith('+'):
        output = output[1:]

    return output

import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])

    if n == 1:
        print(0)
        return

    edges = []
    max_weight = 0

    # Parse edges
    for i in range(n - 1):
        u = int(data[1 + 3 * i])
        v = int(data[2 + 3 * i])
        w = int(data[3 + 3 * i])
        edges.append((u, v, w))
        max_weight = max(max_weight, w)

    # DSU class for union-find
    class DSU:
        def __init__(self, n):
            self.parent = list(range(n))
            self.rank = [0] * n
            self.size = [1] * n

        def find(self, x):
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])  # Path compression
            return self.parent[x]

        def union(self, x, y):
            px, py = self.find(x), self.find(y)
            if px != py:
                # Union by rank
                if self.rank[px] < self.rank[py]:
                    px, py = py, px
                self.parent[py] = px
                self.size[px] += self.size[py]
                if self.rank[px] == self.rank[py]:
                    self.rank[px] += 1
                return True
            return False

    # Check if a minimum weight W is feasible
    def check(W):
        dsu = DSU(n + 1)  # 1-indexed

        # Add edges with weight strictly less than W
        for u, v, w in edges:
            if w < W:
                dsu.union(u, v)

        # Check if any component has more than n/2 nodes
        # We need to count component sizes for root nodes
        component_sizes = {}
        for i in range(1, n + 1):
            root = dsu.find(i)
            if root not in component_sizes:
                component_sizes[root] = 0
            component_sizes[root] += 1

        # If any component has more than n//2 nodes, it's not feasible
        for size in component_sizes.values():
            if size > n // 2:
                return False

        return True

    # Binary search on the answer
    low, high = 0, max_weight
    ans = 0

    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            low = mid + 1  # Try for a larger value
        else:
            high = mid - 1  # Try for a smaller value

    print(ans)

if __name__ == "__main__":
    main()

