import re

def differentiate(polynomial, x):
    # Parse polynomial string into terms
    # Split by + or - but preserve signs
    terms = re.findall(r'[+-]?[^+-]+', polynomial)

    result = 0

    for term in terms:
        # Extract sign, coefficient, and exponent
        match = re.match(r'^([+-]?)(\d*)(x?)(\^?(\d*))$', term.strip())
        if not match:
            continue

        sign_str, coeff_str, has_x, exp_part, exp_str = match.groups()

        # Determine sign
        sign = -1 if sign_str == '-' else 1

        # Determine coefficient
        if coeff_str == '':
            coeff = 1 if has_x else 0
        else:
            coeff = int(coeff_str)

        # Determine exponent
        if has_x:
            if exp_str == '':
                exponent = 1
            else:
                exponent = int(exp_str)
        else:
            # Constant term
            exponent = 0

        # Differentiate: d/dx(ax^n) = n*a*x^(n-1)
        if exponent == 0:
            # Constant term differentiates to 0
            diff_coeff = 0
            diff_exp = 0
        else:
            diff_coeff = coeff * exponent * sign
            diff_exp = exponent - 1

        # Evaluate the differentiated term at point x
        if diff_exp == 0:
            result += diff_coeff
        elif diff_exp > 0:
            result += diff_coeff * (x ** diff_exp)

    return result

