def converter(number, decimals, base):
    if base < 2:
        raise ValueError("Base must be at least 2")

    if decimals < 0:
        raise ValueError("Decimals must be non-negative")

    # Handle special case of zero
    if number == 0:
        if decimals == 0:
            return '0'
        else:
            return '0.' + '0' * decimals

    # Handle negative numbers
    negative = number < 0
    number = abs(number)

    # Separate integer and fractional parts
    integer_part = int(number)
    fractional_part = number - integer_part

    # Convert integer part
    if integer_part == 0:
        integer_result = ''
    else:
        digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
        integer_result = ''
        temp = integer_part
        while temp > 0:
            integer_result = digits[temp % base] + integer_result
            temp //= base

    # Convert fractional part
    fractional_result = ''
    if decimals > 0:
        fractional_result = '.'
        for _ in range(decimals):
            fractional_part *= base
            digit = int(fractional_part)
            digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
            fractional_result += digits[digit]
            fractional_part -= digit

    # Combine results
    if integer_result == '':
        result = '0' + fractional_result
    else:
        result = integer_result + fractional_result

    # Handle negative sign
    if negative:
        result = '-' + result

    return result

def fib4(n):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize the first four values
    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute fib4(n)
    for i in range(4, n + 1):
        next_val = a + b + c + d
        a, b, c, d = b, c, d, next_val

    return d

