        if x1 == x2 or y1 == y2 or abs(x1 - x2) == abs(y1 - y2):
            return True
        # Knight moves (L-shape)
        if (abs(x1 - x2) == 2 and abs(y1 - y2) == 1) or (abs(x1 - x2) == 1 and abs(y1 - y2) == 2):
            return True
        return False

    def get_attacked_squares(x, y):
        # Get all squares that amazon at (x, y) can attack
        attacked = set()
        # Queen moves
        for i in range(8):
            for j in range(8):
                if (i == x or j == y or abs(i - x) == abs(j - y)) and (i != x or j != y):
                    attacked.add((i, j))
        # Knight moves
        knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        for dx, dy in knight_moves:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                attacked.add((nx, ny))
        return attacked

    def get_safe_squares(x, y):
        # Get all squares that king at (x, y) can reach
        safe = set()
        for i in range(max(0, x-1), min(8, x+2)):
            for j in range(max(0, y-1), min(8, y+2)):
                if not (i == x and j == y):
                    safe.add((i, j))
        return safe

    king_x, king_y = pos_to_coords(king)
    amazon_x, amazon_y = pos_to_coords(amazon)

    # Get attacked squares by amazon
    attacked = get_attacked_squares(amazon_x, amazon_y)

    # Get safe squares for white king
    white_king_safe = get_safe_squares(king_x, king_y)

    # Get all possible black king positions
    result = [0, 0, 0, 0]  # [checkmate, check, stalemate, safe]

    for i in range(8):
        for j in range(8):
            # Skip if square is occupied by white king or amazon
            if (i == king_x and j == king_y) or (i == amazon_x and j == amazon_y):
                continue

            # Skip if square is adjacent to white king
            if is_adjacent(i, j, king_x, king_y):
                continue

            # Check if black king is under attack
            is_under_attack = can_attack(amazon_x, amazon_y, i, j)

            # Get safe squares for black king
            black_king_safe = get_safe_squares(i, j)

            # Check if black king can move to a safe square
            can_move = False
            for safe_x, safe_y in black_king_safe:
                # Safe square must not be occupied by white king or amazon
                if (safe_x == king_x and safe_y == king_y) or (safe_x == amazon_x and safe_y == amazon_y):
                    continue
                # Safe square must not be adjacent to white king
                if is_adjacent(safe_x, safe_y, king_x, king_y):
                    continue
                # Safe square must not be under attack by amazon
                if can_attack(amazon_x, amazon_y, safe_x, safe_y):
                    continue
                can_move = True
                break

            if is_under_attack:
                # Check if black king can escape
                can_escape = False
                for safe_x, safe_y in black_king_safe:
                    # Safe square must not be occupied by white king or amazon
                    if (safe_x == king_x and safe_y == king_y) or (safe_x == amazon_x and safe_y == amazon_y):
                        continue
                    # Safe square must not be adjacent to white king
                    if is_adjacent(safe_x, safe_y, king_x, king_y):
                        continue
                    # Safe square must not be under attack by amazon
                    if can_attack(amazon_x, amazon_y, safe_x, safe_y):
                        continue
                    can_escape = True
                    break

                if can_escape:
                    result[1] += 1  # Check
                else:
                    result[0] += 1  # Checkmate
            else:
                # Black king is safe
                if can_move:
                    result[3] += 1  # Safe with moves
                else:
                    result[2] += 1  # Stalemate

    return result

def simplify(expression):
    from collections import defaultdict

    terms_dict = defaultdict(int)

    i = 0
    n = len(expression)

    while i < n:
        # Handle sign at the start of a term
        sign = 1
        if i < n and expression[i] == '+':
            sign = 1
            i += 1
        elif i < n and expression[i] == '-':
            sign = -1
            i += 1

        # Parse coefficient
        coeff = 1
        if i < n and expression[i].isdigit():
            start = i
            while i < n and expression[i].isdigit():
                i += 1
            coeff = int(expression[start:i])

        # Parse variables
        vars_str = ''
        while i < n and expression[i].isalpha():
            vars_str += expression[i]
            i += 1

        if vars_str:  # Only process if we found variables
            vars_tuple = tuple(sorted(vars_str))
            terms_dict[vars_tuple] += sign * coeff

    # Build result - sort by number of variables, then lexicographically
    sorted_terms = sorted(terms_dict.items(), key=lambda x: (len(x[0]), x[0]))

    result_parts = []
    first = True
    for vars_tuple, coeff in sorted_terms:
        if coeff == 0:
            continue

        vars_str = ''.join(vars_tuple)

        if first:
            # First term: no leading +
            if coeff > 0:
                result_parts.append(f'{coeff if coeff != 1 else ""}{vars_str}')
            else:
                result_parts.append(f'{coeff if coeff != -1 else "-"}{vars_str}')
            first = False
        else:
            # Subsequent terms: include + sign for positive
            if coeff > 0:
                result_parts.append(f'+{coeff if coeff != 1 else ""}{vars_str}')
            else:
                result_parts.append(f'{coeff if coeff != -1 else "-"}{vars_str}')

    return ''.join(result_parts)

def count_divisors(n):
    if n == 1:
        return 1
    if n < 1:
        return 0

    count = 0
    i = 1
    while i * i < n:
        if n % i == 0:
            count += 2  # Count both i and n//i
        i += 1

    if i * i == n:
        count += 1  # Perfect square case

    return count

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None
    return hashlib.md5(text.encode('utf-8')).hexdigest()

def sum_of_squares(n):
    # Check if n is a perfect square
    sqrt_n = int(n**0.5)
    if sqrt_n * sqrt_n == n:
        return 1

    # Check if n can be expressed as sum of two squares
    for i in range(1, sqrt_n + 1):
        remainder = n - i * i
        sqrt_remainder = int(remainder**0.5)
        if sqrt_remainder * sqrt_remainder == remainder:
            return 2

    # Check if n can be expressed as sum of three squares
    # Using Legendre's three-square theorem: a number can be expressed as sum of 3 squares
    # if and only if it's not of the form 4^a(8b+7)
    while n % 4 == 0:
        n //= 4

    if n % 8 != 7:
        return 3

    # If none of the above, it requires 4 squares
    return 4

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create pairs of (digit_sum, original_index, value) for stable sorting
    indexed_nums = [(digit_sum(num), i, num) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index (stable sort)
    indexed_nums.sort(key=lambda x: (x[0], x[1]))

    # Extract just the values in the new order
    return [num for _, _, num in indexed_nums]

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """

    def parse_value(val):
        """Convert a value to float for comparison, handling comma decimal separators"""
        if isinstance(val, (int, float)):
            return float(val)
        elif isinstance(val, str):
            # Replace comma with dot for decimal separator
            normalized_str = val.replace(',', '.')
            return float(normalized_str)
        else:
            raise TypeError("Unsupported type")

    # Parse both values for comparison
    parsed_a = parse_value(a)
    parsed_b = parse_value(b)

    # Compare the parsed values
    if parsed_a > parsed_b:
        return a
    elif parsed_b > parsed_a:
        return b
    else:
        return None

def compare(selector1, selector2):
    def parse_selector(selector):
        if not selector or not selector.strip():
            return (0, 0, 0)

        # Split by whitespace to get individual tokens
        tokens = selector.split()

        id_count = 0
        class_count = 0
        element_count = 0

        for token in tokens:
            # Count IDs
            id_count += token.count('#')

            # Count classes
            class_count += token.count('.')

            # Count elements (tokens that don't start with # or .)
            if not token.startswith('#') and not token.startswith('.'):
                element_count += 1
            else:
                # For tokens that start with # or ., we still need to count
                # elements that come before the modifiers
                # e.g. "div#main" should count as 1 element, 1 id
                # e.g. "div.red" should count as 1 element, 1 class
                # We need to strip the # and . prefixes to count elements
                element_part = ""
                i = 0
                while i < len(token) and (token[i] == '#' or token[i] == '.'):
                    i += 1
                element_part = token[i:]
                if element_part and element_part.isalnum():
                    element_count += 1

        return (id_count, class_count, element_count)

    # Parse both selectors
    spec1 = parse_selector(selector1)
    spec2 = parse_selector(selector2)

    # Compare specificity
    if spec1 > spec2:
        return selector1
    else:
        return selector2

def get_closest_vowel(word):
    vowels = "aeiouAEIOU"

    if len(word) < 3:
        return ""

    # Scan from right to left, checking indices 1 to len(word)-2
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            # Check if surrounded by consonants (non-vowels)
            if word[i-1] not in vowels and word[i+1] not in vowels:
                return word[i]

    return ""

def automorphic(n):
    square = n * n
    n_str = str(n)
