    # Convert integer part to the given base
    if integer_part == 0:
        integer_digits = []
    else:
        integer_digits = []
        temp = integer_part
        while temp > 0:
            quotient = int(temp / base)
            remainder = temp - quotient * base
            # Ensure remainder is positive
            if remainder < 0:
                remainder += base
                quotient += 1
            # Convert remainder to digit
            if remainder >= 36:
                digit = chr(ord('A') + int(remainder - 10))
            else:
                digit = str(int(remainder))
            integer_digits.append(digit)
            temp = quotient
        integer_digits.reverse()

    # Handle fractional part
    fractional_digits = []
    if decimals > 0:
        temp_fraction = fractional_part
        for _ in range(decimals):
            temp_fraction *= base
            digit_value = int(temp_fraction)
            if digit_value >= 36:
                digit = chr(ord('A') + digit_value - 10)
            else:
                digit = str(digit_value)
            fractional_digits.append(digit)
            temp_fraction -= digit_value

    # Combine results
    if not integer_digits:
        result = '0'
    else:
        result = ''.join(integer_digits)

    if decimals > 0:
        result += '.' + ''.join(fractional_digits)

    if negative:
        result = '-' + result

    return result

def smallest_change(arr):
    changes = 0
    n = len(arr)
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1
    return changes

from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []

    for group in groups:
        max_depth = 0
        current_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

