            j = i + length - 1
            if gems[i] == gems[j] and is_palindrome[i + 1][j - 1]:
                is_palindrome[i][j] = True

    # DP: dp[i][j] = minimum seconds to destroy substring from i to j
    dp = [[0] * n for _ in range(n)]

    # Base case: single gemstones
    for i in range(n):
        dp[i][i] = 1

    # Fill DP table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if is_palindrome[i][j]:
                dp[i][j] = 1
            else:
                # Try all possible splits
                dp[i][j] = float('inf')
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j])

