def simplify(expression):
    import re
    from collections import defaultdict

    # Parse the expression into terms
    # Find all terms (including signs)
    terms = re.findall(r'[+-]?[^+-]+', expression)

    # Dictionary to store monomials and their coefficients
    monomial_dict = defaultdict(int)

    for term in terms:
        # Separate coefficient from variables
        if term.startswith('-'):
            sign = -1
            term = term[1:]
        elif term.startswith('+'):
            sign = 1
            term = term[1:]
        else:
            sign = 1

        # Handle the case where term is just a number (coefficient)
        if not any(c.isalpha() for c in term):
            monomial_dict[''] += sign * int(term)
            continue

        # Extract coefficient and variables
        coeff_str = ''
        var_part = ''
        i = 0
        while i < len(term) and term[i].isdigit():
            coeff_str += term[i]
            i += 1
        if i < len(term):
            var_part = term[i:]

        # If no coefficient was found, it's 1 or -1
        if not coeff_str:
            coeff = sign
        else:
            coeff = sign * int(coeff_str)

        # Sort variables in the monomial
        sorted_vars = ''.join(sorted(var_part))

        # Add to dictionary
        monomial_dict[sorted_vars] += coeff

    # Remove zero coefficients
    monomial_dict = {k: v for k, v in monomial_dict.items() if v != 0}

    # Sort terms by number of variables, then lexicographically
    sorted_terms = sorted(monomial_dict.items(), key=lambda x: (len(x[0]), x[0]))

    # Format the result
    result_parts = []
    for i, (monomial, coeff) in enumerate(sorted_terms):
        if coeff == 0:
            continue
        if monomial == '':
            # Constant term
            if i == 0 and coeff > 0:
                result_parts.append(str(coeff))
            else:
                if coeff > 0:
                    result_parts.append('+' + str(coeff))
                else:
                    result_parts.append(str(coeff))
        else:
            # Non-constant term
            if i == 0 and coeff > 0:
                # First term, positive coefficient, no leading +
                result_parts.append(monomial if coeff == 1 else str(coeff) + monomial)
            else:
                # Other terms or negative first term
                if coeff == 1:
                    result_parts.append('+' + monomial)
                elif coeff == -1:
                    result_parts.append('-' + monomial)
                else:
                    if coeff > 0:
                        result_parts.append('+' + str(coeff) + monomial)
                    else:
                        result_parts.append(str(coeff) + monomial)

    if not result_parts:
        return "0"

    return ''.join(result_parts)

def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if str(i) == str(i)[::-1]:
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def histogram(s):
    parts = s.split()
    if not parts:
        return {}

    counts = {}
    for letter in parts:
        counts[letter] = counts.get(letter, 0) + 1

    max_freq = max(counts.values())

    return {letter: count for letter, count in counts.items() if count == max_freq}

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False

        # Check odd divisors up to sqrt(num)
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True

    if is_prime(n):
        return x
    else:
        return y

import re

def differentiate(poly, x):
    if not poly:
        return 0

    # Normalize: ensure polynomial starts with + or -
    if not poly.startswith('-') and not poly.startswith('+'):
        poly = '+' + poly

    # Extract all terms with their signs
    terms = re.findall(r'([+-])([^\+\-]+)', poly)

    result = 0

    for sign, term in terms:
        # Parse coefficient and exponent from the term
        if 'x^' in term:
            # Term has explicit exponent like "3x^2" or "x^2"
            x_index = term.index('x')
            exp_index = term.index('^', x_index)
            coeff_str = term[:x_index]
            exponent = int(term[exp_index + 1:])
            if coeff_str == '':
                coeff = 1
            else:
                coeff = int(coeff_str)
        elif 'x' in term:
            # Term has x but no exponent like "3x" or "x"
            x_index = term.index('x')
            coeff_str = term[:x_index]
            exponent = 1
            if coeff_str == '':
                coeff = 1
            else:
                coeff = int(coeff_str)
        else:
            # Constant term like "5" or "12"
            coeff = int(term)
            exponent = 0

        # Apply sign
        if sign == '-':
            coeff = -coeff

        # Differentiate: d/dx (coeff * x^exponent) = coeff * exponent * x^(exponent-1)
        if exponent > 0:
            result += coeff * exponent * (x ** (exponent - 1))

    return result

def largest_divisor(n: int) -> int:
    if n <= 1:
        return 1

    max_divisor = 1

    # Iterate up to sqrt(n)
    i = 1
    while i * i <= n:
        if n % i == 0:
            # i is a divisor
            if i < n:
                max_divisor = max(max_divisor, i)

            # n//i is also a divisor
            complement = n // i
            if complement < n:
                max_divisor = max(max_divisor, complement)
        i += 1

    return max_divisor

def histogram(test):
    if not test:
        return {}

    # Split the string into individual characters
    letters = test.split()

    # Count frequency of each letter
    freq_count = {}
    for letter in letters:
        freq_count[letter] = freq_count.get(letter, 0) + 1

    # Find the maximum frequency
    max_freq = max(freq_count.values())

    # Filter to only include letters with maximum frequency
    result = {letter: count for letter, count in freq_count.items() if count == max_freq}

    return result
